# ── Loading screen ───────────────────────────────────────────────────────────
# Opens the window as early as possible (right after pygame is imported) and shows a
# progress bar while the rest of the game loads, so the player sees the game opening
# instead of an empty console. It deliberately has no text that needs translating (the
# player's language is only known once the settings are read) and no animation (the
# Reduced Motion setting is not loaded yet); it only moves forward step by step. Any
# problem here disables the screen and never stops the game from starting.
class _StartupSplash:
    SIZE = (800, 600)
    BACKGROUND = (20, 30, 60)

    def __init__(self):
        self.screen = None
        self.fraction = 0.0
        self.failed = False

    def show(self):
        try:
            pygame.display.init()
            pygame.font.init()
            self.screen = pygame.display.set_mode(self.SIZE, pygame.RESIZABLE)
            pygame.display.set_caption('Snake Game')
            self._draw()
            try:                                     # close the PyInstaller picture, if the build has one
                import pyi_splash
                pyi_splash.close()
            except Exception:
                pass
        except Exception:
            self.failed = True

    def _draw(self):
        screen = self.screen
        width, height = screen.get_size()
        screen.fill(self.BACKGROUND)
        title_font = pygame.font.Font(None, max(36, min(110, width // 8)))
        title = title_font.render('Snake Game', True, (255, 255, 255))
        title_rect = title.get_rect(center=(width // 2, int(height * 0.36)))
        pygame.draw.ellipse(screen, (50, 70, 130), title_rect.inflate(int(width * 0.12), int(height * 0.08)))
        screen.blit(title, title_rect)
        # A little snake above the bar: four body squares and a head with eyes.
        cell = max(10, min(28, width // 30))
        snake_x = width // 2 - (5 * cell) // 2
        snake_y = int(height * 0.52)
        for index in range(4):
            pygame.draw.rect(screen, (50, 205, 50), pygame.Rect(snake_x + index * cell, snake_y, cell - 2, cell - 2),
                             border_radius=cell // 4)
        head = pygame.Rect(snake_x + 4 * cell, snake_y, cell - 2, cell - 2)
        pygame.draw.rect(screen, (120, 240, 120), head, border_radius=cell // 4)
        for eye_y in (head.y + cell // 4, head.bottom - cell // 4 - 3):
            pygame.draw.rect(screen, (255, 255, 255), pygame.Rect(head.right - cell // 3, eye_y, 3, 3))
        bar = pygame.Rect(0, 0, int(width * 0.5), max(10, height // 38))
        bar.center = (width // 2, int(height * 0.66))
        radius = bar.h // 2
        pygame.draw.rect(screen, (34, 44, 74), bar, border_radius=radius)
        fill = max(0.0, min(1.0, self.fraction))
        if fill > 0.0:
            pygame.draw.rect(screen, (50, 205, 50),
                             pygame.Rect(bar.x, bar.y, max(bar.h, int(bar.w * fill)), bar.h), border_radius=radius)
        pygame.draw.rect(screen, (120, 135, 175), bar, 1, border_radius=radius)
        pygame.display.flip()

    def step(self, fraction):
        """Move the bar forward and keep the window responsive."""
        if self.failed or self.screen is None:
            return
        try:
            self.fraction = max(self.fraction, fraction)
            if pygame.display.get_surface() is not self.screen:
                self.screen = pygame.display.get_surface()      # the game has taken the window over
            pygame.event.pump()
            if pygame.event.get(pygame.QUIT):
                pygame.quit()
                sys.exit(0)
            if self.screen is not None:
                self._draw()
        except SystemExit:
            raise
        except Exception:
            self.failed = True


def _startup_splash_wanted(argv=None, environ=None):
    """The loading screen is for a normal double-click start only: not for self-tests, command-line
    options, a game imported as a module, or when SGF_NO_SPLASH is set."""
    argv = sys.argv if argv is None else argv
    environ = os.environ if environ is None else environ
    if len(argv) > 1 or environ.get('SGF_NO_SPLASH'):
        return False
    return not any(environ.get(name) for name in ('SGF_IA5_SELFTEST', 'SGF_DEV_SELFTEST', 'SGF_VERIFY_FILES'))


_STARTUP_SPLASH = None
_STARTUP_BEGAN = time.perf_counter()


def _startup_progress(fraction):
    """Advance the loading screen (does nothing when there is none)."""
    if _STARTUP_SPLASH is not None:
        _STARTUP_SPLASH.step(fraction)


if __name__ == '__main__' and _startup_splash_wanted():
    _STARTUP_SPLASH = _StartupSplash()
    _STARTUP_SPLASH.show()
    _startup_progress(0.1)

