# ── CLI / developer startup options ──────────────────────────────────
# Parsed as early as possible (before pygame.init()) so flags like
# --no-audio / --safe-mode can influence what happens next. Uses
# parse_known_args so an unrecognized argument (e.g. one a launcher adds)
# never crashes normal double-click usage.
def _parse_sgf_cli_args():
    parser = _argparse.ArgumentParser(add_help=False)
    parser.add_argument('--debug', action='store_true')
    parser.add_argument('--safe-mode', action='store_true')
    parser.add_argument('--no-mods', action='store_true')
    parser.add_argument('--no-audio', action='store_true')
    parser.add_argument('--reset-settings', action='store_true')
    parser.add_argument('--verify-files', action='store_true')
    parser.add_argument('--profile', type=str, default=None)
    parser.add_argument('--log-level', type=str, default=None)
    try:
        args, _unknown = parser.parse_known_args(sys.argv[1:])
    except Exception:
        args = parser.parse_args([])
    return args


_SGF_CLI_ARGS = _parse_sgf_cli_args()
DEBUG_MODE = bool(_SGF_CLI_ARGS.debug)
