def _apply_accessibility_palette(colors):
    palette = dict(colors)
    if globals().get('_ACCESSIBILITY_HIGH_CONTRAST', False):
        palette.update({key: value for key, value in _HIGH_CONTRAST_UI_COLORS.items()
                        if key in palette})
    return palette


