def _map_theme_colors(settings):
    theme = getattr(settings, 'map_theme', 'classic')
    if not isinstance(theme, str):
        theme = 'classic'
    return MAP_THEME_PALETTES.get(theme, MAP_THEME_PALETTES['classic'])


# Skin colours: shared by the game board and the Skins preview so they can never disagree.
_SKIN_PALETTE = {'neon': (0, 235, 190), 'camouflage': (92, 132, 62)}


def _skin_colors(skin, base_color):
    """(body, head) colours of a skin. Classic (and unknown skins) use the player's snake colour;
    the head is the brighter variant of the body."""
    body = _SKIN_PALETTE.get(skin, base_color)
    return body, tuple(min(255, c + 60) for c in body)


def _rainbow_skin_color(index, speed=1.2, now=None):
    """Colour of body segment ``index`` of the animated rainbow skin."""
    phase = (time.time() if now is None else now) * speed + index * 0.28
    return (int((math.sin(phase) + 1) * 127), int((math.sin(phase + 2.1) + 1) * 127),
            int((math.sin(phase + 4.2) + 1) * 127))


def _draw_skin_preview(surface, rect, settings, skin, now=None):
    """Miniature board (the player's map theme) with a snake wearing ``skin`` and a fruit, drawn with the
    same colours as the real game. The rainbow skin animates because the screen redraws every frame."""
    background, board, grid = _map_theme_colors(settings)
    pygame.draw.rect(surface, background, rect, border_radius=10)
    pygame.draw.rect(surface, (230, 235, 245), rect, 2, border_radius=10)
    cells = 10
    cell = max(6, min((rect.w - 24) // cells, (rect.h - 24) // cells))
    board_rect = pygame.Rect(0, 0, cell * cells, cell * cells)
    board_rect.center = rect.center
    pygame.draw.rect(surface, board, board_rect)
    for i in range(cells + 1):
        pygame.draw.line(surface, grid, (board_rect.x + i * cell, board_rect.y),
                         (board_rect.x + i * cell, board_rect.bottom))
        pygame.draw.line(surface, grid, (board_rect.x, board_rect.y + i * cell),
                         (board_rect.right, board_rect.y + i * cell))
    base = getattr(settings, 'snake_color', COLORS['snake'])
    try:
        body_color, head_color = _skin_colors(skin, base)
    except Exception:
        body_color, head_color = _skin_colors('classic', COLORS['snake'])
    path = [(7, 4), (6, 4), (5, 4), (4, 4), (3, 4), (3, 5), (3, 6), (4, 6), (5, 6)]
    for index, (cx, cy) in enumerate(path):
        seg = pygame.Rect(board_rect.x + cx * cell, board_rect.y + cy * cell, cell, cell)
        if index == 0:
            color = head_color
        elif skin == 'rainbow':
            color = _rainbow_skin_color(index, now=now)
        else:
            color = body_color
        if index == len(path) - 1:                      # the tail is a little smaller, like in the game
            margin = max(1, cell // 8)
            seg = seg.inflate(-margin * 2, -margin * 2)
        pygame.draw.rect(surface, color, seg)
        if index == 0:                                  # eyes (the snake looks right)
            eye = max(1, cell // 6)
            for ey in (seg.y + cell // 4, seg.bottom - cell // 4 - eye):
                pygame.draw.rect(surface, (255, 255, 255),
                                 pygame.Rect(seg.right - cell // 3, ey, eye + 1, eye + 1))
    fruit_rect = pygame.Rect(board_rect.x + 8 * cell, board_rect.y + 4 * cell, cell, cell)
    try:
        draw_fruit(surface, fruit_rect, 'regular')
    except Exception:
        pygame.draw.circle(surface, COLORS['red'], fruit_rect.center, max(2, cell // 2 - 1))


def _draw_map_theme_preview(surface, rect, settings):
    """Miniature board drawn with the palette of settings.map_theme: the same
    background/board/grid colours the real game uses, a short snake in the
    player's colour and one fruit. Used live by the Map Themes screen."""
    background, board, grid = _map_theme_colors(settings)
    pygame.draw.rect(surface, background, rect, border_radius=10)
    pygame.draw.rect(surface, (230, 235, 245), rect, 2, border_radius=10)
    cells = 12
    cell = max(6, min((rect.w - 24) // cells, (rect.h - 24) // cells))
    board_rect = pygame.Rect(0, 0, cell * cells, cell * cells)
    board_rect.center = rect.center
    pygame.draw.rect(surface, board, board_rect)
    for i in range(cells + 1):
        pygame.draw.line(surface, grid, (board_rect.x + i * cell, board_rect.y),
                         (board_rect.x + i * cell, board_rect.bottom))
        pygame.draw.line(surface, grid, (board_rect.x, board_rect.y + i * cell),
                         (board_rect.right, board_rect.y + i * cell))
    snake_color = getattr(settings, 'snake_color', COLORS['snake'])
    try:
        head_color = tuple(min(255, int(c) + 60) for c in snake_color)
    except Exception:
        snake_color = head_color = COLORS['snake']
    body = [(8, 6), (7, 6), (6, 6), (5, 6), (5, 7), (5, 8)]
    for index, (cx, cy) in enumerate(body):
        seg = pygame.Rect(board_rect.x + cx * cell + 1, board_rect.y + cy * cell + 1,
                          cell - 2, cell - 2)
        pygame.draw.rect(surface, head_color if index == 0 else snake_color,
                         seg, border_radius=max(2, cell // 4))
    fruit_rect = pygame.Rect(board_rect.x + 3 * cell, board_rect.y + 3 * cell, cell, cell)
    try:
        draw_fruit(surface, fruit_rect, 'regular')
    except Exception:
        pygame.draw.circle(surface, COLORS['red'], fruit_rect.center, max(2, cell // 2 - 1))


_MOBILE_HAPTIC_BACKEND = None
_MOBILE_HAPTIC_CHECKED = False


def _trigger_mobile_haptic(duration_ms=35):
    """Best-effort Pydroid/Android vibration; unsupported desktops are no-ops."""
    global _MOBILE_HAPTIC_BACKEND, _MOBILE_HAPTIC_CHECKED
    try:
        duration_ms = max(1, min(120, int(duration_ms)))
    except (TypeError, ValueError, OverflowError):
        duration_ms = 35
    if not _MOBILE_HAPTIC_CHECKED:
        _MOBILE_HAPTIC_CHECKED = True
        try:
            from jnius import autoclass
            activity = autoclass('org.kivy.android.PythonActivity').mActivity
            context = autoclass('android.content.Context')
            vibrator = activity.getSystemService(context.VIBRATOR_SERVICE)
            if vibrator is not None and vibrator.hasVibrator():
                try:
                    effect_type = autoclass('android.os.VibrationEffect')
                    build = autoclass('android.os.Build$VERSION')
                    if int(build.SDK_INT) >= 26:
                        def _vibrate(ms):
                            effect = effect_type.createOneShot(ms, effect_type.DEFAULT_AMPLITUDE)
                            vibrator.vibrate(effect)
                        _MOBILE_HAPTIC_BACKEND = _vibrate
                    else:
                        _MOBILE_HAPTIC_BACKEND = lambda ms: vibrator.vibrate(ms)
                except Exception:
                    _MOBILE_HAPTIC_BACKEND = lambda ms: vibrator.vibrate(ms)
        except Exception:
            # Pydroid's optional permissions/Pyjnius integration may be
            # absent. Gameplay must continue without haptics in that case.
            _MOBILE_HAPTIC_BACKEND = None
    if _MOBILE_HAPTIC_BACKEND is not None:
        try:
            _MOBILE_HAPTIC_BACKEND(duration_ms)
        except Exception:
            _MOBILE_HAPTIC_BACKEND = None


def _is_app_background_event(event):
    """Recognize Pygame 2 focus/background events and legacy SDL focus loss."""
    event_type = getattr(event, 'type', None)
    for name in ('WINDOWFOCUSLOST', 'WINDOWHIDDEN', 'WINDOWMINIMIZED'):
        if event_type == getattr(pygame, name, object()):
            return True
    if event_type == getattr(pygame, 'ACTIVEEVENT', object()):
        if bool(getattr(event, 'gain', 1)):
            return False
        state = getattr(event, 'state', 0)
        focus_bits = (getattr(pygame, 'APPINPUTFOCUS', 2) |
                      getattr(pygame, 'APPACTIVE', 4))
        try:
            return bool(int(state) & focus_bits)
        except (TypeError, ValueError, OverflowError):
            return False
    return False

