class SoundManager:
    """Generates and plays simple synthesized sound effects using pygame.mixer."""
    def __init__(self):
        self._sounds = {}
        self._enabled = True
        self._sfx_enabled = True
        self._bgm_sound = None
        self._bgm_channel = None
        self._bgm_channels = []
        self._bgm_sounds = {}
        self._bgm_context = 'menu'
        self._bgm_track_key = None
        self._bgm_playlist = False
        self._bgm_playing_context = None
        self._bgm_volume = 0.0
        self._music_track_cursors = {}
        self._bgm_ready = _queue_mod.Queue()
        self._bgm_building = set()
        self._bgm_build_lock = threading.Lock()
        try:
            if not pygame.mixer.get_init():
                pygame.mixer.init(frequency=22050, size=-16, channels=1, buffer=512)
            pygame.mixer.set_reserved(2)
            self._bgm_channels = [pygame.mixer.Channel(0), pygame.mixer.Channel(1)]
            self._build()
            event_bus = globals().get('EVENT_BUS')
            if event_bus is not None:
                event_bus.subscribe('THEME_CHANGED', self._on_audio_content_changed)
                event_bus.subscribe('MOD_LOADED', self._on_audio_content_changed)
                event_bus.subscribe('MOD_UNLOADED', self._on_audio_content_changed)
        except Exception:
            self._enabled = False

    @staticmethod
    def _wave(freq, dur_ms, vol=0.45, rate=22050):
        import struct
        n = int(rate * dur_ms / 1000)
        data = [int(32767 * vol * math.sin(2 * math.pi * freq * i / rate)) for i in range(n)]
        # short fade-out to remove click
        fade = min(n, int(rate * 0.02))
        for i in range(fade):
            data[n - 1 - i] = int(data[n - 1 - i] * (i / fade))
        return struct.pack('<' + 'h' * n, *data)

    def _build(self):
        specs = {
            'eat':      (880, 80,  0.40),
            'eat_gold': (1047,120, 0.50),
            'click':    (660, 50,  0.25),
            'powerup':  (528, 200, 0.45),
            'portal':   (330, 180, 0.40),
            'gameover': (220, 500, 0.50),
            'victory':  (784, 400, 0.55),
            'levelup':  (698, 250, 0.50),
            'combo':    (1175,100, 0.45),
        }
        for name, (f, d, v) in specs.items():
            try:
                self._sounds[name] = pygame.mixer.Sound(buffer=self._wave(f, d, v))
            except Exception:
                pass

    def play(self, name):
        if name in ('gameover', 'victory'):
            self.set_music_context('game_over')
        if self._enabled and self._sfx_enabled:
            try:
                s = self._sounds.get(name)
                if s:
                    s.play()
            except Exception:
                pass

    @staticmethod
    def _build_bgm_buffer(rate=22050, step_ms=220):
        """Compose an 8-bar loop with changing harmony, bass and plucked lead."""
        from array import array
        chords = ((130.81, 164.81, 196.00), (110.00, 130.81, 164.81),
                  (174.61, 220.00, 261.63), (196.00, 246.94, 293.66))
        melody = (523.25, 0, 659.25, 783.99, 659.25, 0, 587.33, 523.25,
                  440.00, 0, 523.25, 659.25, 587.33, 0, 523.25, 440.00,
                  392.00, 0, 523.25, 659.25, 783.99, 0, 659.25, 523.25,
                  493.88, 0, 587.33, 659.25, 587.33, 523.25, 493.88, 392.00,
                  523.25, 0, 659.25, 880.00, 783.99, 0, 659.25, 587.33,
                  440.00, 0, 523.25, 659.25, 698.46, 0, 659.25, 523.25,
                  392.00, 0, 523.25, 659.25, 783.99, 0, 880.00, 783.99,
                  587.33, 0, 523.25, 493.88, 523.25, 587.33, 659.25, 523.25)
        n_step = int(rate * step_ms / 1000)
        total_n = n_step * len(melody)
        # Build each required oscillator once per note-step. The older version
        # called sin() 7+ times for every audio sample, causing a visible pause
        # on first play and every context switch. Recurrence keeps audio
        # preparation bounded and avoids repeated transcendental operations.
        def tone(frequency):
            angle = 2 * math.pi * frequency / rate
            step_sin, step_cos = math.sin(angle), math.cos(angle)
            current_sin, current_cos = 0.0, 1.0
            samples = array('f')
            for _ in range(n_step):
                samples.append(current_sin)
                current_sin, current_cos = (
                    current_sin * step_cos + current_cos * step_sin,
                    current_cos * step_cos - current_sin * step_sin)
            return samples

        chord_waves = []
        bass_waves = []
        for chord in chords:
            fundamentals = [tone(f) for f in chord]
            harmonics = [tone(f * 2) for f in chord]
            chord_waves.append(array('f', (
                .035 * fundamentals[0][i] + .009 * harmonics[0][i] +
                .035 * fundamentals[1][i] + .009 * harmonics[1][i] +
                .035 * fundamentals[2][i] + .009 * harmonics[2][i]
                for i in range(n_step))))
            bass_waves.append(tone(chord[0] / 2))
        lead_waves = {}
        for frequency in {f for f in melody if f}:
            fundamental, harmonic, overtone = tone(frequency), tone(frequency * 2), tone(frequency * 3)
            lead_waves[frequency] = array('f', (
                .16 * fundamental[i] + .035 * harmonic[i] + .012 * overtone[i]
                for i in range(n_step)))
        attack = max(1, int(rate * .012))
        release = max(1, int(rate * .035))
        fade = array('f', (min(1.0, i / attack, max(0.0, (n_step-i) / release))
                           for i in range(n_step)))
        bass_decay = array('f', (max(0.0, 1.0 - (i / rate) / .19)
                                 for i in range(n_step)))
        data = array('f', [0.0]) * total_n
        for step_i, lead in enumerate(melody):
            chord_i = (step_i // 8) % len(chords)
            accompaniment = chord_waves[chord_i]
            bass = bass_waves[chord_i]
            lead_wave = lead_waves.get(lead)
            base = step_i * n_step
            for i in range(n_step):
                layer = accompaniment[i]
                if step_i % 2 == 0:
                    layer += .075 * bass[i] * bass_decay[i]
                if lead_wave is not None:
                    layer += lead_wave[i]
                data[base+i] = fade[i] * layer

        # Defensive normalize, then pack as 16-bit PCM
        peak = max(0.001, max(abs(x) for x in data))
        scale = min(1.0, 0.9 / peak)
        ints = [int(max(-32767, min(32767, x * scale * 32767))) for x in data]
        return struct.pack('<' + 'h' * total_n, *ints)

    def _ensure_bgm(self, context='menu'):
        tempos = {'menu': 242, 'tutorial': 270, 'gameplay': 190,
                  'multiplayer': 190, 'studio': 242, 'mods': 242,
                  'credits': 260, 'game_over': 300}
        key = f'builtin:{context}'
        if key not in self._bgm_sounds and self._enabled:
            with self._bgm_build_lock:
                if key not in self._bgm_building and key not in self._bgm_sounds:
                    self._bgm_building.add(key)
                    worker = threading.Thread(
                        target=self._prepare_bgm_bytes,
                        args=(key, tempos.get(context, 220)),
                        name=f'sgf-music-{context}', daemon=True)
                    worker.start()
        return self._bgm_sounds.get(key)

    def _prepare_bgm_bytes(self, key, step_ms):
        """Pure-Python buffer preparation; no Pygame calls run on the worker."""
        try:
            result = self._build_bgm_buffer(step_ms=step_ms)
        except Exception as exc:
            result = exc
        self._bgm_ready.put((key, result))

    def pump_audio(self):
        """Finish decoded music on the main thread and start the latest context."""
        updated = False
        while True:
            try:
                key, result = self._bgm_ready.get_nowait()
            except _queue_mod.Empty:
                break
            with self._bgm_build_lock:
                self._bgm_building.discard(key)
            if isinstance(result, Exception):
                sgf_log.warning('Built-in music preparation failed: %s', result)
                self._bgm_sounds[key] = None
                continue
            try:
                self._bgm_sounds[key] = pygame.mixer.Sound(buffer=result)
                updated = True
            except Exception as exc:
                sgf_log.warning('Built-in music decode failed: %s', exc)
                self._bgm_sounds[key] = None
        desired_key = f'builtin:{self._bgm_context}'
        if (updated and self._bgm_volume > 0 and self._bgm_track_key != desired_key and
                self._bgm_sounds.get(desired_key) is not None):
            self.set_music_context(self._bgm_context)
        if (self._enabled and self._bgm_volume > 0 and self._bgm_playlist and
                self._bgm_playing_context == self._bgm_context and
                self._bgm_channel is not None and not self._bgm_channel.get_busy()):
            context = self._bgm_context
            self._music_track_cursors[context] = self._music_track_cursors.get(context, 0) + 1
            self.set_music_context(context)

    def _on_audio_content_changed(self, payload):
        if self._bgm_volume > 0:
            self.set_music_context(self._bgm_context)

    def _resolve_external_bgm(self, context):
        # Theme sound manifests accept context -> asset id/descriptor/list.
        # Optional or invalid tracks fall back to the built-in soundtrack.
        try:
            spec = THEME_MANAGER.get('sounds.music', {})
            if isinstance(spec, dict) and isinstance(spec.get('tracks'), list):
                raw = []
                for track in spec['tracks']:
                    if not isinstance(track, dict):
                        continue
                    contexts = track.get('contexts', ['*'])
                    if isinstance(contexts, str):
                        contexts = [contexts]
                    if isinstance(contexts, list) and any(
                            isinstance(value, str) and value in ('*', context)
                            for value in contexts):
                        raw.append(track)
            elif isinstance(spec, dict) and 'asset' in spec:
                raw = spec
            else:
                raw = (spec if isinstance(spec, (str, list)) else
                       spec.get(context, spec.get('default', spec.get('*')))
                       if isinstance(spec, dict) else None)
            entries = raw if isinstance(raw, list) else [raw]
            candidates = []
            for entry in entries:
                descriptor = entry if isinstance(entry, dict) else {'asset': entry}
                asset_id = descriptor.get('asset')
                license_id = descriptor.get('license') or THEME_MANAGER.get('license')
                owner = ASSET_MANAGER.owner_of(asset_id) if isinstance(asset_id, str) else None
                path = ASSET_MANAGER.resolve(asset_id) if isinstance(asset_id, str) else None
                if (not isinstance(license_id, str) or not license_id.strip() or
                        not isinstance(owner, str) or not owner.startswith('theme:') or
                        not path or os.path.getsize(path) > 4 * 1024 * 1024):
                    continue
                sound = ASSET_MANAGER.get_sound(asset_id)
                gain = float(descriptor.get('volume', 1.0))
                if (sound is not None and 1.5 <= sound.get_length() <= 240 and
                        math.isfinite(gain) and 0.0 <= gain <= 1.0):
                    candidates.append((f'theme:{THEME_MANAGER.active_theme_id}:{asset_id}', sound, gain))
            if candidates:
                index = self._music_track_cursors.get(context, 0) % len(candidates)
                key, sound, gain = candidates[index]
                return key, sound, gain, len(candidates) > 1
        except Exception as exc:
            sgf_log.warning('Optional theme music was skipped: %s', exc)

        # A mod can declare {"music":{"tracks":[{"asset":..., "contexts": [...],
        # "license":..., "volume": 0..1}]}}. It must own the referenced
        # registered asset and provide its license; scripts are never run.
        manager = globals().get('MOD_MANAGER')
        if manager is not None:
            candidates = []
            for mod_id in sorted(getattr(manager, 'active', ())):
                manifest = getattr(manager, 'discovered', {}).get(mod_id)
                music = getattr(manifest, 'data', {}).get('music') if manifest else None
                tracks = music.get('tracks', []) if isinstance(music, dict) else music
                if not isinstance(tracks, list):
                    continue
                for track in tracks:
                    if not isinstance(track, dict):
                        continue
                    contexts = track.get('contexts', ['*'])
                    if isinstance(contexts, str):
                        contexts = [contexts]
                    if (not isinstance(contexts, list) or not any(
                            entry in ('*', context) for entry in contexts
                            if isinstance(entry, str))):
                        continue
                    asset_id, license_id = track.get('asset'), track.get('license')
                    if (not isinstance(asset_id, str) or not asset_id.strip() or
                            not isinstance(license_id, str) or not license_id.strip() or
                            ASSET_MANAGER.owner_of(asset_id) != f'mod:{mod_id}'):
                        continue
                    try:
                        path = ASSET_MANAGER.resolve(asset_id)
                        if not path or os.path.getsize(path) > 4 * 1024 * 1024:
                            continue
                        sound = ASSET_MANAGER.get_sound(asset_id)
                        gain = float(track.get('volume', 1.0))
                        if (sound is not None and 1.5 <= sound.get_length() <= 240 and
                                math.isfinite(gain) and 0.0 <= gain <= 1.0):
                            candidates.append((f'mod:{mod_id}:{asset_id}', sound, gain))
                    except Exception as exc:
                        sgf_log.warning('Optional mod music track was skipped: %s', exc)
            if candidates:
                index = self._music_track_cursors.get(context, 0) % len(candidates)
                key, sound, gain = candidates[index]
                return key, sound, gain, len(candidates) > 1
        return None

    def set_music_context(self, context, volume=None):
        """Switch context once with a short crossfade; safe to call repeatedly."""
        allowed = {'menu', 'gameplay', 'tutorial', 'multiplayer', 'game_over',
                   'studio', 'mods', 'credits'}
        context = str(context or 'menu').strip().lower()
        if context not in allowed:
            context = 'menu'
        if context != self._bgm_context:
            self._music_track_cursors[context] = self._music_track_cursors.get(context, -1) + 1
        self._bgm_context = context
        if volume is not None:
            self._bgm_volume = _normalize_sound_fraction(volume)
        if not self._enabled or self._bgm_volume <= 0:
            self.stop_bgm()
            return
        try:
            external = self._resolve_external_bgm(context)
            if external:
                key, sound, gain, *playlist_state = external
                playlist = bool(playlist_state[0]) if playlist_state else False
            else:
                key, sound, gain = f'builtin:{context}', self._ensure_bgm(context), 1.0
                playlist = False
            if sound is None:
                # Built-in buffers are prepared away from the UI thread. Keep
                # the previous context audible until the new one is ready.
                self._bgm_playlist = False
                self.pump_audio()
                return
            if key == self._bgm_track_key and self._bgm_channel is not None and self._bgm_channel.get_busy():
                self._bgm_channel.set_volume(self._bgm_volume * gain)
                return
            old = next((ch for ch in self._bgm_channels if ch is self._bgm_channel), None)
            new = next((ch for ch in self._bgm_channels if ch is not old), None)
            if new is None:
                return
            if old is not None:
                old.fadeout(450)
            sound.set_volume(self._bgm_volume * gain)
            new.play(sound, loops=0 if playlist else -1, fade_ms=450)
            self._bgm_channel = new
            self._bgm_sound = sound
            self._bgm_track_key = key
            self._bgm_playlist = playlist
            self._bgm_playing_context = context
        except Exception as exc:
            sgf_log.warning('Music context %s failed: %s', context, exc)

    def play_bgm(self, volume=0.5):
        """Start looping background music if it isn't already playing.
        Safe to call repeatedly — a no-op if it's already running."""
        if not self._enabled:
            return
        self.set_music_context(self._bgm_context,
                               volume=_normalize_sound_fraction(volume, 0.5))

    def stop_bgm(self):
        try:
            for channel in self._bgm_channels:
                channel.stop()
        except Exception:
            pass
        finally:
            self._bgm_channel = None
            self._bgm_track_key = None
            self._bgm_playlist = False
            self._bgm_playing_context = None
            self._bgm_volume = 0.0

    def set_bgm_volume(self, volume):
        volume = _normalize_sound_fraction(volume)
        self._bgm_volume = volume
        try:
            if self._bgm_channel:
                self._bgm_channel.set_volume(volume)
            if self._bgm_sound:
                self._bgm_sound.set_volume(volume)
        except Exception:
            pass

    def set_sfx_state(self, enabled, volume):
        self._sfx_enabled = _normalize_sound_toggle(enabled, True)
        volume = _normalize_sound_fraction(volume)
        for sound in self._sounds.values():
            try:
                sound.set_volume(volume)
            except Exception:
                pass

# Module-level sound manager (lazily initialised)
_SOUND_MGR = None


def _normalize_sound_percent(value, default=80):
    if not isinstance(value, (int, float)) or isinstance(value, bool):
        value = default
    if not isinstance(value, (int, float)) or isinstance(value, bool):
        value = 80
    if isinstance(value, float) and not math.isfinite(value):
        value = default
    if not isinstance(value, (int, float)) or isinstance(value, bool):
        value = 80
    if isinstance(value, float) and not math.isfinite(value):
        value = 80
    if value <= 0:
        return 0
    if value >= 100:
        return 100
    return int(round(value))


def _normalize_sound_toggle(value, default):
    return value if type(value) is bool else bool(default)


def _normalize_sound_fraction(value, default=0.0):
    try:
        value = float(value)
    except (TypeError, ValueError, OverflowError):
        value = float(default)
    if not math.isfinite(value):
        value = float(default)
    return max(0.0, min(1.0, value))

def sounds():
    global _SOUND_MGR
    if _SOUND_MGR is None:
        _SOUND_MGR = SoundManager()
    return _SOUND_MGR


def _pump_audio():
    manager = _SOUND_MGR
    if manager is not None:
        manager.pump_audio()


def _apply_sfx_state(settings):
    """Apply the master and effects volume to sound effects."""
    try:
        sounds().set_sfx_state(
            _normalize_sound_toggle(getattr(settings, 'sfx_enabled', True), True),
            (_normalize_sound_percent(getattr(settings, 'master_volume', 80)) *
             _normalize_sound_percent(getattr(settings, 'sfx_volume', 100), 100) /
             10000.0),
        )
    except Exception:
        pass


def _apply_bgm_state(settings):
    """Start or stop background music to match current settings. Safe to
    call anytime — on startup, or right after Settings are saved — so a
    toggle takes effect immediately without needing a restart."""
    try:
        mgr = sounds()
        if _normalize_sound_toggle(getattr(settings, 'bgm_enabled', False), False):
            volume = (_normalize_sound_percent(getattr(settings, 'master_volume', 80)) *
                      _normalize_sound_percent(getattr(settings, 'bgm_volume', 100), 100) /
                      10000.0) * 0.5
            mgr.play_bgm(volume=volume)
        else:
            mgr.stop_bgm()
    except Exception:
        pass

def draw_apple(surface, rect, color=(255, 50, 50)):
    """Draw a realistic apple texture"""
    # Draw the main apple body
    pygame.draw.circle(surface, color, rect.center, rect.width // 2 - 2)
    
    # Add some shading to create a 3D effect
    darker_color = (max(0, color[0] - 60), max(0, color[1] - 60), max(0, color[2] - 60))
    shadow_rect = pygame.Rect(rect.centerx - rect.width // 4, rect.centery, rect.width // 2, rect.height // 2)
    pygame.draw.ellipse(surface, darker_color, shadow_rect)
    
    # Add a small indentation at the top (where the stem goes)
    indent_rect = pygame.Rect(rect.centerx - 3, rect.top + 2, 6, 4)
    pygame.draw.ellipse(surface, darker_color, indent_rect)
    
    # Draw a stem
    stem_rect = pygame.Rect(rect.centerx - 2, rect.top + 1, 4, 7)
    pygame.draw.rect(surface, (101, 67, 33), stem_rect, border_radius=1)  # Brown stem
    
    # Draw a leaf
    leaf_points = [
        (rect.centerx + 2, rect.top + 6),
        (rect.centerx + 8, rect.top + 3),
        (rect.centerx + 4, rect.top)
    ]
    pygame.draw.polygon(surface, (50, 205, 50), leaf_points)  # Green leaf
    
    # Add highlight for shininess
    highlight_pos = (rect.centerx - rect.width // 6, rect.centery - rect.height // 4)
    highlight_radius = max(2, rect.width // 10)
    pygame.draw.circle(surface, (255, 255, 255, 150), highlight_pos, highlight_radius)

def draw_orange(surface, rect, color=(255, 140, 0)):
    """Draw a realistic orange texture"""
    # Draw the main orange body
    pygame.draw.circle(surface, color, rect.center, rect.width // 2 - 1)
    
    # Add texture - orange dimples
    dimple_color = (max(0, color[0] - 30), max(0, color[1] - 20), max(0, color[2] - 10))
    dimple_size = max(1, rect.width // 15)
    
    # Create a pattern of dimples all over the orange
    for angle in range(0, 360, 45):
        for radius_pct in [0.35, 0.7]:
            radius = rect.width // 2 * radius_pct
            x = rect.centerx + int(radius * math.cos(math.radians(angle)))
            y = rect.centery + int(radius * math.sin(math.radians(angle)))
            pygame.draw.circle(surface, dimple_color, (x, y), dimple_size)
    
    # Draw small stem/leaf at top
    stem_rect = pygame.Rect(rect.centerx - 2, rect.top + 2, 4, 3)
    pygame.draw.rect(surface, (101, 67, 33), stem_rect, border_radius=1)  # Brown stem
    
    # Small green leaf
    leaf_rect = pygame.Rect(rect.centerx - 3, rect.top + 1, 6, 4)
    pygame.draw.ellipse(surface, (30, 160, 30), leaf_rect)  # Green leaf
    
    # Add highlight
    highlight_pos = (rect.centerx - rect.width // 5, rect.centery - rect.height // 5)
    highlight_radius = max(1, rect.width // 12)
    pygame.draw.circle(surface, (255, 255, 255, 150), highlight_pos, highlight_radius)

def draw_banana(surface, rect, color=(255, 220, 60)):
    """Draw a banana as a curved crescent — distinct from the round fruits,
    not a circle/ellipse blob."""
    cx, cy = rect.centerx, rect.centery
    w, h = rect.width, rect.height

    # Crescent built from an outer arc and a slightly-tighter inner arc,
    # swept through ~140 degrees so it reads as a curved banana at a glance.
    outer_r = w * 0.60
    inner_r = w * 0.32
    start_angle = math.radians(205)
    end_angle = math.radians(335)
    steps = 14

    outer_pts = []
    inner_pts = []
    for i in range(steps + 1):
        t = start_angle + (end_angle - start_angle) * i / steps
        outer_pts.append((cx + outer_r * math.cos(t), cy + outer_r * math.sin(t) * 0.9 - h * 0.05))
        inner_pts.append((cx + inner_r * math.cos(t), cy + inner_r * math.sin(t) * 0.9 - h * 0.05))

    polygon = outer_pts + inner_pts[::-1]
    pygame.draw.polygon(surface, color, polygon)
    pygame.draw.polygon(surface, tuple(max(0, c - 50) for c in color), polygon, width=max(1, w // 25))

    # Ridge line along the curve for a bit of dimensionality
    mid_pts = [((o[0] + i[0]) / 2, (o[1] + i[1]) / 2) for o, i in zip(outer_pts, inner_pts)]
    if len(mid_pts) > 1:
        pygame.draw.lines(surface, tuple(min(255, c + 25) for c in color), False, mid_pts, max(1, w // 30))

    # Brown tips at both ends — the clearest "this is a banana" signal
    tip_r = max(2, int(w * 0.09))
    pygame.draw.circle(surface, (101, 67, 33), (int(outer_pts[0][0]), int(outer_pts[0][1])), tip_r)
    pygame.draw.circle(surface, (101, 67, 33), (int(outer_pts[-1][0]), int(outer_pts[-1][1])), tip_r)

def draw_strawberry(surface, rect, color=(255, 0, 50)):
    """Draw a realistic strawberry texture"""
    # Draw the main heart-shaped strawberry body
    # We'll use a combination of circles and a triangle
    
    center_x, center_y = rect.center
    radius = min(rect.width, rect.height) // 3
    
    # Draw two circles for the top of the heart
    circle1_center = (center_x - radius // 2, center_y - radius // 2)
    circle2_center = (center_x + radius // 2, center_y - radius // 2)
    
    pygame.draw.circle(surface, color, circle1_center, radius)
    pygame.draw.circle(surface, color, circle2_center, radius)
    
    # Draw a triangle for the bottom of the heart
    triangle_points = [
        (center_x - radius, center_y),
        (center_x + radius, center_y),
        (center_x, center_y + radius * 1.5)
    ]
    pygame.draw.polygon(surface, color, triangle_points)
    
    # Add seeds (small yellow dots)
    seed_color = (255, 255, 200)
    seed_size = max(1, rect.width // 20)
    
    _local_rng = random.Random(hash((rect.x, rect.y, rect.width)))
    for _ in range(12):
        angle = _local_rng.uniform(0, 2 * math.pi)
        distance = _local_rng.uniform(0.3, 0.9) * radius
        x = center_x + int(distance * math.cos(angle))
        y = center_y + int(distance * math.sin(angle))
        pygame.draw.ellipse(surface, seed_color, (x - seed_size // 2, y - seed_size // 2, seed_size, seed_size // 2))
    
    # Add green leaf crown at the top
    leaf_color = (30, 180, 30)
    
    leaf_points = [
        (center_x, center_y - radius * 1.2),  # Center point
        (center_x - radius, center_y - radius * 0.8),  # Left point
        (center_x - radius // 2, center_y - radius),  # Left inner
        (center_x, center_y - radius * 1.4),  # Top middle
        (center_x + radius // 2, center_y - radius),  # Right inner
        (center_x + radius, center_y - radius * 0.8),  # Right point
    ]
    
    pygame.draw.polygon(surface, leaf_color, leaf_points)
    
    # Add stem
    stem_rect = pygame.Rect(center_x - 2, center_y - radius * 1.3, 4, 5)
    pygame.draw.rect(surface, (101, 67, 33), stem_rect)  # Brown stem

def draw_blueberry(surface, rect, color=(0, 0, 205)):
    """Draw a realistic blueberry texture"""
    # Draw the main blueberry body
    pygame.draw.circle(surface, color, rect.center, rect.width // 2 - 1)
    
    # Add a small indentation at the bottom
    bottom_indent = pygame.Rect(
        rect.centerx - rect.width // 6,
        rect.bottom - rect.height // 6,
        rect.width // 3,
        rect.height // 6
    )
    
    darker_blue = (max(0, color[0] - 30), max(0, color[1] - 30), max(0, color[2] - 30))
    pygame.draw.ellipse(surface, darker_blue, bottom_indent)
    
    # Add a white/gray bloom effect (the dusty coating blueberries have)
    bloom_color = (200, 200, 255, 40)  # Semi-transparent light blue/white
    
    _local_rng = random.Random(hash((rect.x, rect.y, rect.width)))
    for _ in range(6):
        angle = _local_rng.uniform(0, 2 * math.pi)
        distance = _local_rng.uniform(0.3, 0.9) * (rect.width // 3)
        x = rect.centerx + int(distance * math.cos(angle))
        y = rect.centery + int(distance * math.sin(angle))
        bloom_size = max(1, rect.width // 12)
        pygame.draw.circle(surface, (200, 200, 255), (x, y), bloom_size)
    
    # Add a small crown at the top
    crown_color = (60, 40, 30)  # Dark brown/gray
    crown_rect = pygame.Rect(
        rect.centerx - rect.width // 6,
        rect.top + rect.height // 10,
        rect.width // 3,
        rect.height // 8
    )
    
    pygame.draw.ellipse(surface, crown_color, crown_rect)
    
    # Add a tiny hole in the center of the crown
    hole_size = max(1, rect.width // 15)
    pygame.draw.circle(surface, (20, 20, 40), 
                      (rect.centerx, rect.top + rect.height // 8), 
                      hole_size)

def draw_watermelon(surface, rect, color=(220, 20, 60)):
    """Draw a realistic watermelon slice texture"""
    # Draw a triangular slice shape
    slice_points = [
        (rect.centerx, rect.top + rect.height // 6),  # Top point
        (rect.left + rect.width // 6, rect.bottom - rect.height // 6),  # Bottom left
        (rect.right - rect.width // 6, rect.bottom - rect.height // 6)   # Bottom right
    ]
    
    # Draw the red flesh
    pygame.draw.polygon(surface, color, slice_points)
    
    # Draw the green rind at the bottom
    rind_points = [
        (rect.left + rect.width // 6, rect.bottom - rect.height // 6),  # Bottom left of flesh
        (rect.right - rect.width // 6, rect.bottom - rect.height // 6),  # Bottom right of flesh
        (rect.right - rect.width // 8, rect.bottom - rect.height // 12),  # Bottom right of rind
        (rect.left + rect.width // 8, rect.bottom - rect.height // 12)   # Bottom left of rind
    ]
    
    pygame.draw.polygon(surface, (30, 180, 30), rind_points)  # Green rind
    
    # Add a darker green edge/border
    dark_green = (20, 120, 20)
    pygame.draw.line(surface, dark_green, 
                    (rect.left + rect.width // 6, rect.bottom - rect.height // 6),
                    (rect.right - rect.width // 6, rect.bottom - rect.height // 6), 
                    max(1, rect.width // 30))
    
    # Add black seeds
    seed_color = (10, 10, 10)
    seed_size = max(1, rect.width // 15)
    
    # Create a pattern of seeds
    for i in range(3):
        for j in range(2):
            x = rect.centerx - rect.width // 6 + (rect.width // 3) * j
            y = rect.top + rect.height // 3 + (rect.height // 6) * i
            
            # Draw oval seeds
            seed_rect = pygame.Rect(x - seed_size // 2, y - seed_size // 4,
                                   seed_size, seed_size // 2)
            pygame.draw.ellipse(surface, seed_color, seed_rect)

def draw_golden_apple(surface, rect):
    """Draw a golden apple texture"""
    # Use the same base as apple but with golden color
    draw_apple(surface, rect, FRUIT_COLORS['golden'])
    
    # Add sparkle effect
    sparkle_size = max(2, rect.width // 12)
    sparkle_points = [
        (rect.centerx, rect.centery - sparkle_size*2),
        (rect.centerx + sparkle_size, rect.centery),
        (rect.centerx, rect.centery + sparkle_size*2),
        (rect.centerx - sparkle_size, rect.centery)
    ]
    pygame.draw.polygon(surface, (255, 255, 255), sparkle_points)
    
    # Add a second, smaller sparkle
    small_sparkle_size = sparkle_size // 2
    small_sparkle_points = [
        (rect.centerx + rect.width // 4, rect.centery - rect.height // 4 - small_sparkle_size),
        (rect.centerx + rect.width // 4 + small_sparkle_size // 2, rect.centery - rect.height // 4),
        (rect.centerx + rect.width // 4, rect.centery - rect.height // 4 + small_sparkle_size),
        (rect.centerx + rect.width // 4 - small_sparkle_size // 2, rect.centery - rect.height // 4)
    ]
    pygame.draw.polygon(surface, (255, 255, 255), small_sparkle_points)

def draw_kiwi(surface, rect, color=(126, 88, 56)):
    """Draw a realistic kiwi half texture"""
    # Draw brown exterior (skin)
    pygame.draw.circle(surface, color, rect.center, rect.width // 2 - 1)
    
    # Add texture to the brown skin
    skin_detail = (101, 67, 33)  # Darker brown for texture
    for i in range(0, 360, 20):
        angle = math.radians(i)
        start = rect.width // 2 - 4
        end = rect.width // 2 - 1
        x1 = rect.centerx + int(start * math.cos(angle))
        y1 = rect.centery + int(start * math.sin(angle))
        x2 = rect.centerx + int(end * math.cos(angle))
        y2 = rect.centery + int(end * math.sin(angle))
        pygame.draw.line(surface, skin_detail, (x1, y1), (x2, y2), 1)
    
    # Draw green flesh
    flesh_color = (173, 255, 47)  # Green flesh
    flesh_radius = int(rect.width * 0.4)
    pygame.draw.circle(surface, flesh_color, rect.center, flesh_radius)
    
    # Draw white center
    core_color = (255, 255, 255)
    core_radius = int(rect.width * 0.15)
    pygame.draw.circle(surface, core_color, rect.center, core_radius)
    
    # Add small black seeds in the green flesh
    seed_color = (0, 0, 0)
    seed_size = max(2, rect.width // 20)
    
    # Draw seeds in a fixed pattern - no randomness to prevent flickering
    seed_angles = [0, 30, 60, 90, 120, 150, 180, 210, 240, 270, 300, 330]
    seed_radiuses = [0.25, 0.32]
    
    for angle in seed_angles:
        for radius_pct in seed_radiuses:
            radius = rect.width // 2 * radius_pct
            angle_rad = math.radians(angle)
            x = rect.centerx + int(radius * math.cos(angle_rad))
            y = rect.centery + int(radius * math.sin(angle_rad))
            
            pygame.draw.ellipse(surface, seed_color, 
                               (x - seed_size // 2, y - seed_size // 4, 
                                seed_size, seed_size // 2))

def draw_cherry(surface, rect, color=(220, 20, 60)):
    """Draw realistic cherry texture"""
    # Calculate positions for two cherries
    cherry1_center = (rect.centerx - rect.width // 5, rect.centery + rect.height // 6)
    cherry2_center = (rect.centerx + rect.width // 5, rect.centery + rect.height // 6)
    
    cherry_radius = max(3, rect.width // 4)
    
    # Draw two cherry spheres
    pygame.draw.circle(surface, color, cherry1_center, cherry_radius)
    pygame.draw.circle(surface, color, cherry2_center, cherry_radius)
    
    # Add highlights
    highlight1_pos = (cherry1_center[0] - cherry_radius // 3, cherry1_center[1] - cherry_radius // 3)
    highlight2_pos = (cherry2_center[0] - cherry_radius // 3, cherry2_center[1] - cherry_radius // 3)
    
    highlight_radius = max(1, cherry_radius // 3)
    pygame.draw.circle(surface, (255, 255, 255, 150), highlight1_pos, highlight_radius)
    pygame.draw.circle(surface, (255, 255, 255, 150), highlight2_pos, highlight_radius)
    
    # Draw stems connecting to the top
    stem_color = (101, 67, 33)  # Brown
    
    # Draw curved stems
    # First stem
    start_pos1 = (cherry1_center[0], cherry1_center[1] - cherry_radius + 1)
    control_pos1 = (rect.centerx, rect.top + rect.height // 4)
    end_pos = (rect.centerx, rect.top + rect.height // 8)
    
    # Second stem
    start_pos2 = (cherry2_center[0], cherry2_center[1] - cherry_radius + 1)
    control_pos2 = (rect.centerx, rect.top + rect.height // 4)
    
    # Draw the stems as lines (a proper Bezier curve would be better but is more complex)
    pygame.draw.line(surface, stem_color, start_pos1, control_pos1, max(1, rect.width // 25))
    pygame.draw.line(surface, stem_color, control_pos1, end_pos, max(1, rect.width // 25))
    pygame.draw.line(surface, stem_color, start_pos2, control_pos2, max(1, rect.width // 25))

def draw_tracking_fruit(surface, rect):
    """Draw tracking fruit with radar effect"""
    # Base color changes over time for a rainbow effect
    pulse_speed = 0.005
    t = time.time()
    r = int(127.5 + 127.5 * math.sin(pulse_speed * t * 1000))
    g = int(127.5 + 127.5 * math.sin(pulse_speed * t * 1000 + 2 * math.pi / 3))
    b = int(127.5 + 127.5 * math.sin(pulse_speed * t * 1000 + 4 * math.pi / 3))
    
    # Draw pulsing circle
    pygame.draw.circle(surface, (r, g, b), rect.center, rect.width // 2 - 2)
    
    # Draw tracking icon (compass-like arrows)
    if rect.width > 12:
        arrow_length = (rect.width // 2 - 2) * 0.6
        arrow_width = max(1, rect.width // 10)
        
        # Draw four directional arrows (like a compass)
        for angle in [0, math.pi/2, math.pi, 3*math.pi/2]:
            end_x = rect.centerx + int(arrow_length * math.cos(angle))
            end_y = rect.centery + int(arrow_length * math.sin(angle))
            pygame.draw.line(surface, (255, 255, 255), 
                           rect.center, (end_x, end_y), arrow_width)

def draw_fruit(surface, rect, fruit_type):
    """Draw fruit with realistic texture based on type"""
    try:
        if fruit_type == 'regular':
            draw_apple(surface, rect, FRUIT_COLORS['regular'])
        elif fruit_type == 'golden':
            draw_golden_apple(surface, rect)
        elif fruit_type == 'auto_tracking':
            draw_tracking_fruit(surface, rect)
        elif fruit_type == 'orange':
            draw_orange(surface, rect, FRUIT_COLORS.get('orange', (255, 140, 0)))
        elif fruit_type in ['blue', 'navy']:
            draw_blueberry(surface, rect, FRUIT_COLORS.get(fruit_type, (30, 144, 255)))
        elif fruit_type in ['yellow', 'cream']:
            draw_banana(surface, rect, FRUIT_COLORS.get(fruit_type, (255, 255, 0)))
        elif fruit_type in ['pink', 'crimson']:
            draw_strawberry(surface, rect, FRUIT_COLORS.get(fruit_type, (255, 105, 180)))
        elif fruit_type in ['maroon', 'red']:
            draw_cherry(surface, rect, FRUIT_COLORS.get(fruit_type, (220, 20, 60)))
        elif fruit_type in ['green', 'lime']:
            draw_kiwi(surface, rect, FRUIT_COLORS.get(fruit_type, (50, 255, 50)))
        elif fruit_type in ['cyan', 'turquoise']:
            draw_watermelon(surface, rect)  # watermelon always uses its natural red/green colours
        else:
            # For other types, use the improved apple texture with the appropriate color
            color = get_fruit_color(fruit_type)
            draw_apple(surface, rect, color)
    except (KeyError, TypeError):
        # Fallback to basic apple if there's any error
        draw_apple(surface, rect, FRUIT_COLORS.get('regular', (255, 50, 50)))
    if _ACCESSIBILITY_COLOR_CUES and rect.width >= 14 and rect.height >= 14:
        cue_types = globals().get('_ACCESSIBILITY_FRUIT_CUE_TYPES', ('regular',))
        cue_type = str(fruit_type or 'regular').lower()
        cue_aliases = {'red': 'maroon'}
        cue_type = cue_aliases.get(cue_type, cue_type)
        cue_index = cue_types.index(cue_type) + 1 if cue_type in cue_types else 0
        if cue_index:
            radius = max(5, min(9, rect.width // 4))
            center = (rect.left + radius + 1, rect.top + radius + 1)
            pygame.draw.circle(surface, (0, 0, 0), center, radius)
            pygame.draw.circle(surface, (255, 255, 255), center, radius, width=1)
            # Base-36 keeps every fruit type's cue distinct while remaining
            # legible inside the small high-contrast badge.
            digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
            value = cue_index
            cue_label = ''
            while value:
                value, rem = divmod(value - 1, len(digits))
                cue_label = digits[rem] + cue_label
            cue_font = get_font('en', 'bold', max(8, radius * 2))
            cue_text = cue_font.render(cue_label, True, (255, 255, 255))
            surface.blit(cue_text, cue_text.get_rect(center=center))


# Purely-visual fruit variety for modes that don't have the full special-fruit
# effect system (VS AI, local & LAN multiplayer). No gameplay effect is
# attached to these — they only vary what's drawn on screen, fixing fruit
# always falling back to a plain apple in those modes (live and in replay).
_COSMETIC_FRUIT_TYPES = ['regular', 'golden', 'orange', 'blue', 'yellow', 'pink', 'maroon', 'green', 'cyan']
_NET_SAFE_FRUIT_TYPES = frozenset(_COSMETIC_FRUIT_TYPES + [
    'purple', 'lime', 'brown', 'teal', 'coral', 'olive', 'salmon', 'auto_tracking',
])
_ACCESSIBILITY_FRUIT_CUE_TYPES = tuple(sorted(set(FRUIT_COLORS) | _NET_SAFE_FRUIT_TYPES))

