# Register the existing built-in encyclopedia content using stable IDs. This
# keeps current gameplay/catalog data intact while making it discoverable through
# the extensible registries.
_BUILTIN_REGISTRY_BOOTSTRAP = {
    "fruits": FruitRegistry,
    "powerups": PowerupRegistry,
    "obstacles": ObstacleRegistry,
}
for _registry_key, _registry in _BUILTIN_REGISTRY_BOOTSTRAP.items():
    for _entry in ENCYCLOPEDIA_CATALOG.get(_registry_key, []):
        try:
            _registry.register(_entry, owner_id="builtin")
        except ContentValidationError:
            pass
del _registry_key, _registry, _entry, _BUILTIN_REGISTRY_BOOTSTRAP

