def _storage_label(language, key, **values):
    table = _STORAGE_V2_LABELS.get(language) or _STORAGE_V2_LABELS['en']
    text = table.get(key) or _STORAGE_V2_LABELS['en'].get(key, key)
    try:
        return text.format(**values) if values else text
    except (KeyError, IndexError, ValueError):
        return text


def _storage_group_label(language, group_key):
    for key, label_key, _categories, _color in _STORAGE_GROUPS:
        if key == group_key:
            return get_text(language, label_key) if label_key else _storage_label(language, 'cat_' + key)
    return get_text(language, 'data_cat_other')


def _storage_group_of(category):
    """Cylinder group that a Data category belongs to (None for categories without one)."""
    for key, _label_key, categories, _color in _STORAGE_GROUPS:
        if category in categories:
            return key
    return None


def _storage_dir_size(path):
    """(bytes, files) of a folder; links are neither followed nor counted."""
    size = files = 0
    for dirpath, dirnames, filenames in os.walk(path, followlinks=False):
        dirnames[:] = [d for d in dirnames if not os.path.islink(os.path.join(dirpath, d))]
        for filename in filenames:
            full = os.path.join(dirpath, filename)
            try:
                if os.path.islink(full):
                    continue
                size += os.lstat(full).st_size
                files += 1
            except OSError:
                continue
    return size, files


def storage_tree_children(path, limit=_STORAGE_TREE_LIMIT):
    """One level of a folder for the Data tree: ([{'name', 'path', 'size', 'is_dir', 'files'}],
    hidden_count), biggest first. Links are skipped. Read-only."""
    entries = []
    try:
        names = os.listdir(path)
    except OSError:
        return [], 0
    for name in names:
        full = os.path.join(path, name)
        try:
            if os.path.islink(full):
                continue
            if os.path.isdir(full):
                size, files = _storage_dir_size(full)
                entries.append({'name': name, 'path': full, 'size': size, 'is_dir': True, 'files': files})
            elif os.path.isfile(full):
                entries.append({'name': name, 'path': full, 'size': os.lstat(full).st_size,
                                'is_dir': False, 'files': 1})
        except OSError:
            continue
    entries.sort(key=lambda item: (-item['size'], item['name'].lower()))
    return entries[:limit], max(0, len(entries) - limit)


def _storage_inside_data_root(path):
    """True only for a path that really lies inside SGF Data (after resolving links)."""
    try:
        root = os.path.realpath(_user_data_manager.get_root_dir())
        target = os.path.realpath(path)
        return os.path.commonpath([root, target]) == root and target != root
    except (ValueError, OSError):
        return False


def _storage_stale_cloudflared():
    """Cloudflare files that are not the verified version in use. Nothing is offered while a
    Cloudflare relay session is running, or when the version in use cannot be verified."""
    with _ACTIVE_CLOUDFLARE_SESSIONS_LOCK:
        if _ACTIVE_CLOUDFLARE_SESSIONS:
            return []
    root = os.path.join(_user_data_manager.get_tools_dir(), 'cloudflared')
    try:
        with open(os.path.join(root, 'release.json'), 'r', encoding='utf-8') as stream:
            manifest = json.load(stream)
        version = str(manifest.get('version', ''))
        expected = str(manifest.get('sha256', ''))
        if (not re.fullmatch(r'\d{4}\.\d{1,2}\.\d{1,3}', version)
                or not re.fullmatch(r'[0-9a-f]{64}', expected)):
            return []
        current = f'cloudflared-{version}.exe'
        if not _hmac_mod.compare_digest(_cloudflared_sha256(os.path.join(root, current)), expected):
            return []
        names = os.listdir(root)
    except (OSError, ValueError, TypeError, AttributeError):
        return []
    stale = []
    for name in names:
        if name in ('release.json', current):
            continue
        if re.fullmatch(r'cloudflared-\d{4}\.\d{1,2}\.\d{1,3}\.exe', name) or name == 'cloudflared.exe':
            stale.append(os.path.join(root, name))
    return stale


def storage_cleanup_plan(now=None):
    """What "Clean up" would remove, without removing anything: a list of
    {'kind', 'paths', 'count', 'size'} for old Cloudflare versions, stale temporary files,
    backups beyond the newest _STORAGE_BACKUP_KEEP of each kind, and quarantined replays older
    than _STORAGE_QUARANTINE_DAYS. Saves, scores, settings and the current replays are never
    candidates; the backup of the installed .exe (SGF.exe.old) is kept."""
    now = time.time() if now is None else now
    claimed = set()
    plan = []

    def add(kind, paths):
        paths = [p for p in paths if p not in claimed and _storage_inside_data_root(p) and os.path.isfile(p)]
        if not paths:
            return
        size = 0
        for path in paths:
            try:
                size += os.lstat(path).st_size
            except OSError:
                pass
        claimed.update(paths)
        plan.append({'kind': kind, 'paths': paths, 'count': len(paths), 'size': size})

    add('cloudflared', _storage_stale_cloudflared())
    temporary = []
    for category in ('cache', 'tools', 'backups'):
        for dirpath, dirnames, filenames in os.walk(_user_data_manager.get_category_path(category)):
            dirnames[:] = [d for d in dirnames if not os.path.islink(os.path.join(dirpath, d))]
            for name in filenames:
                if not (name.endswith(('.tmp', '.part', '.update-tmp')) or '.part-' in name):
                    continue
                full = os.path.join(dirpath, name)
                try:
                    if not os.path.islink(full) and now - os.path.getmtime(full) >= _STORAGE_TEMP_MIN_AGE:
                        temporary.append(full)
                except OSError:
                    continue
    add('temporary', temporary)
    try:
        found = list_backups()
    except Exception:
        found = {'update': [], 'exports': [], 'data': []}
    old_backups = []
    for kind in ('update', 'exports', 'data'):
        old_backups.extend(item['path'] for item in found.get(kind, [])[_STORAGE_BACKUP_KEEP:])
    add('backups', old_backups)
    quarantine = os.path.join(_user_data_manager.get_backup_dir(), _ORPHAN_REPLAY_DIRNAME)
    old_replays = []
    try:
        for name in os.listdir(quarantine):
            full = os.path.join(quarantine, name)
            if (os.path.isfile(full) and not os.path.islink(full)
                    and now - os.path.getmtime(full) >= _STORAGE_QUARANTINE_DAYS * 86400):
                old_replays.append(full)
    except OSError:
        pass
    add('quarantine', old_replays)
    return plan


def storage_cleanup_apply(plan):
    """Delete the files of a plan from storage_cleanup_plan(). Returns (removed, freed_bytes,
    errors). Only regular files that still lie inside SGF Data are removed."""
    removed = freed = errors = 0
    for group in plan or ():
        for path in group.get('paths', ()):
            try:
                if os.path.islink(path) or not os.path.isfile(path) or not _storage_inside_data_root(path):
                    errors += 1
                    continue
                size = os.lstat(path).st_size
                os.remove(path)
                removed += 1
                freed += size
            except OSError:
                errors += 1
    _user_data_manager.refresh_stats()
    return removed, freed, errors


def _storage_cleanup_lines(language, plan):
    """Text lines for the confirmation dialog of a clean-up plan."""
    total = sum(group['size'] for group in plan)
    lines = [_storage_label(language, 'cleanup_title', size=_format_bytes(total))]
    for group in plan:
        lines.append(_storage_label(
            language, 'cleanup_' + group['kind'], count=group['count'], size=_format_bytes(group['size']),
            keep=_STORAGE_BACKUP_KEEP, days=_STORAGE_QUARANTINE_DAYS))
    lines.append(_storage_label(language, 'cleanup_note'))
    return lines


# What each expanded category of the Data page offers besides its file list (every one has at least one).
_DATA_CATEGORY_ACTIONS = {
    'saves': ('open', 'archive'), 'maps_created': ('open', 'archive'), 'maps_imported': ('open', 'archive'),
    'cache': ('open', 'clear_cache'), 'logs': ('open', 'compress', 'archive'),
    'mods_installed': ('open', 'archive'), 'themes_installed': ('open', 'archive'),
    'profiles': ('open', 'archive'), 'game_settings': ('open', 'archive'),
    'diagnostics': ('open', 'compress', 'archive'), 'crashes': ('open', 'compress', 'archive'),
    'tools': ('open', 'cleanup'), 'backups': ('open', 'backups', 'cleanup'), 'bin': ('open',),
}
_DATA_ACTION_LABEL_KEYS = {'open': 'act_open', 'archive': 'act_archive', 'compress': 'act_compress',
                           'clear_cache': 'act_clear_cache', 'cleanup': 'act_cleanup', 'backups': 'act_backups'}


# ---- Data page tools that act on single files and folders (everything the player sees can be removed from
# inside the game; the player is in control, so the only refusals are paths outside SGF Data and the files
# the running game is using right now) ----
def _data_running_program_paths():
    """Real paths of the files this process is running from (they cannot or must not be deleted now)."""
    found = set()
    for candidate in (getattr(sys, 'executable', ''), sys.argv[0] if sys.argv else '', globals().get('__file__', ''),
                      os.environ.get('SGF_LAUNCHER_PATH', '')):
        if candidate:
            try:
                found.add(os.path.realpath(candidate))
            except OSError:
                pass
    try:
        for handler in _logging_mod.getLogger().handlers + _logging_mod.getLogger('sgf').handlers:
            name = getattr(handler, 'baseFilename', None)
            if name:
                found.add(os.path.realpath(name))
    except Exception:
        pass
    return found


def _data_path_size(path):
    try:
        if os.path.islink(path) or os.path.isfile(path):
            return os.path.getsize(path) if not os.path.islink(path) else 0
        total = 0
        for dirpath, dirnames, filenames in os.walk(path, followlinks=False):
            for name in filenames:
                full = os.path.join(dirpath, name)
                if not os.path.islink(full):
                    try:
                        total += os.path.getsize(full)
                    except OSError:
                        pass
        return total
    except OSError:
        return 0


def data_path_check(path):
    """(ok, reason): may this path be removed from the Data page? reason is '' or one of
    'outside' (not inside SGF Data), 'root' (SGF Data or a category folder itself), 'missing', 'in_use'."""
    try:
        target = os.path.abspath(path)
        root = os.path.realpath(_user_data_manager.get_root_dir())
        if os.path.realpath(target) == root:
            return False, 'root'
        parent = os.path.realpath(os.path.dirname(target))
        if os.path.commonpath([root, parent]) != root:
            return False, 'outside'
        real_target = os.path.join(parent, os.path.basename(target))
        for category in _user_data_manager._CATEGORY_DIRNAMES:
            if os.path.realpath(_user_data_manager.get_category_path(category)) == real_target:
                return False, 'root'
        if not os.path.lexists(target):
            return False, 'missing'
        in_use = _data_running_program_paths()
        resolved = os.path.realpath(target)
        for used in in_use:
            if used == resolved or used.startswith(resolved + os.sep):
                return False, 'in_use'
        return True, ''
    except (OSError, ValueError):
        return False, 'outside'


def data_delete_path(path):
    """Delete one file or folder from SGF Data. Returns (ok, freed_bytes, reason). Symbolic links are removed
    as links (their target is never touched); a folder that cannot be removed completely reports 'partial'."""
    ok, reason = data_path_check(path)
    if not ok:
        return False, 0, reason
    freed = _data_path_size(path)
    try:
        with _data_save_lock:
            if os.path.islink(path) or os.path.isfile(path):
                os.remove(path)
            else:
                failures = []
                _shutil_mod.rmtree(path, onerror=lambda _func, p, _exc: failures.append(p))
                if failures or os.path.exists(path):
                    return False, max(0, freed - _data_path_size(path)), 'partial'
    except OSError as exc:
        _logging_mod.getLogger('sgf').warning('Could not delete %s: %s', path, exc)
        return False, 0, 'error'
    _user_data_manager.refresh_stats()
    return True, freed, ''


def data_archive_paths(paths, label='data'):
    """Zip COPIES of the given files/folders into SGF Data/backups/archives/. The originals are not touched, so
    this is always safe. Returns (zip_path or None, files_added, zip_bytes, reason)."""
    import zipfile
    root = os.path.realpath(_user_data_manager.get_root_dir())
    archive_dir = os.path.join(_user_data_manager.get_backup_dir(), 'archives')
    files = []
    for path in paths:
        ok, reason = data_path_check(path)
        if not ok and reason not in ('in_use', 'root'):          # reading is harmless: only outside/missing paths are skipped
            continue
        if os.path.isdir(path) and not os.path.islink(path):
            for dirpath, dirnames, filenames in os.walk(path, followlinks=False):
                dirnames[:] = [d for d in dirnames if not os.path.islink(os.path.join(dirpath, d))
                               and os.path.join(dirpath, d) != archive_dir]
                files.extend(os.path.join(dirpath, n) for n in filenames)
        elif os.path.isfile(path) and not os.path.islink(path):
            files.append(path)
    files = [f for f in dict.fromkeys(files) if not f.endswith('.lock')]
    if not files:
        return None, 0, 0, 'empty'
    safe_label = re.sub(r'[^A-Za-z0-9_-]+', '_', str(label))[:40] or 'data'
    stamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    destination = os.path.join(archive_dir, f'archive_{safe_label}_{stamp}.zip')
    temp = destination + '.tmp'
    try:
        os.makedirs(archive_dir, exist_ok=True)
        added = 0
        with zipfile.ZipFile(temp, 'w', zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
            for full in files:
                try:
                    archive.write(full, os.path.relpath(os.path.realpath(full), root))
                    added += 1
                except OSError:
                    continue                       # a file that vanished or is locked is simply left out
        with zipfile.ZipFile(temp, 'r') as archive:
            if archive.testzip() is not None:
                raise zipfile.BadZipFile('archive failed its integrity check')
        if added == 0:
            os.remove(temp)
            return None, 0, 0, 'empty'
        os.replace(temp, destination)
        _user_data_manager.refresh_stats()
        return destination, added, os.path.getsize(destination), ''
    except (OSError, zipfile.BadZipFile) as exc:
        _logging_mod.getLogger('sgf').warning('Archive failed: %s', exc)
        try:
            if os.path.exists(temp):
                os.remove(temp)
        except OSError:
            pass
        return None, 0, 0, 'error'


def data_compress_old_files(category, min_age_seconds=600):
    """Gzip the files of a category that nothing is writing any more (older than `min_age_seconds`, not the
    log in use): foo.log becomes foo.log.gz after the copy reads back correctly. Returns
    (files_compressed, bytes_saved, errors)."""
    root = _user_data_manager.get_category_path(category)
    busy = _data_running_program_paths()
    done = saved = errors = 0
    now = time.time()
    for dirpath, dirnames, filenames in os.walk(root, followlinks=False):
        dirnames[:] = [d for d in dirnames if not os.path.islink(os.path.join(dirpath, d))]
        for name in filenames:
            full = os.path.join(dirpath, name)
            if (name.endswith(('.gz', '.xz', '.zip', '.lock', '.tmp')) or os.path.islink(full)
                    or os.path.realpath(full) in busy):
                continue
            try:
                stat = os.stat(full)
                if now - stat.st_mtime < min_age_seconds or stat.st_size == 0:
                    continue
                with open(full, 'rb') as handle:
                    raw = handle.read()
                packed = gzip.compress(raw, compresslevel=9, mtime=0)
                if len(packed) >= len(raw):
                    continue
                target = full + '.gz'
                _atomic_write_bytes(target, packed)
                with gzip.open(target, 'rb') as check:
                    if check.read() != raw:
                        os.remove(target)
                        raise ValueError('compressed copy differs')
                os.remove(full)
                done += 1
                saved += len(raw) - len(packed)
            except (OSError, ValueError, EOFError):
                errors += 1
    if done:
        _user_data_manager.refresh_stats()
    return done, saved, errors


def _data_delete_confirmation(language, category_key, category_label, stats):
    """Build an informed category-delete warning using existing translations."""
    modified = format_date(stats.get('last_modified'))
    details = get_text(language, 'data_files_updated').format(
        count=stats.get('file_count', 0), date=modified)
    return {
        'kind': 'delete_category',
        'category': category_key,
        'message_lines': [
            _t_or(language, 'confirm_delete_category',
                  'Delete all {category} data? This cannot be undone.').format(
                      category=category_label),
            f"{category_label} — {_format_bytes(stats.get('size_bytes', 0))} · {details}",
        ],
    }



