import logging as _logging_mod
from logging.handlers import RotatingFileHandler as _RotatingFileHandler

_LOG_LEVELS = {
    'DEBUG': _logging_mod.DEBUG, 'INFO': _logging_mod.INFO,
    'WARNING': _logging_mod.WARNING, 'ERROR': _logging_mod.ERROR,
    'CRITICAL': _logging_mod.CRITICAL,
}
_LOG_RING_BUFFER = []
_LOG_RING_BUFFER_MAX = 200
_log_ring_lock = threading.Lock()


class _RingBufferLogHandler(_logging_mod.Handler):
    """Keeps the last N formatted log lines in memory, so a crash report can
    include recent context even without opening the log file."""
    def emit(self, record):
        try:
            msg = self.format(record)
        except Exception:
            return
        with _log_ring_lock:
            _LOG_RING_BUFFER.append(msg)
            if len(_LOG_RING_BUFFER) > _LOG_RING_BUFFER_MAX:
                del _LOG_RING_BUFFER[0:len(_LOG_RING_BUFFER) - _LOG_RING_BUFFER_MAX]


def _init_sgf_logging():
    logger = _logging_mod.getLogger('sgf')
    if logger.handlers:
        return logger

    level_name = _CLI_LOG_LEVEL if _CLI_LOG_LEVEL in _LOG_LEVELS else 'INFO'
    if SAFE_MODE:
        level_name = 'DEBUG'  # Safe Mode always enables debug logging
    logger.setLevel(_LOG_LEVELS[level_name])

    fmt = _logging_mod.Formatter(
        '%(asctime)s [%(levelname)s] %(name)s: %(message)s', datefmt='%Y-%m-%d %H:%M:%S')

    try:
        log_path = os.path.join(_user_data_manager.get_log_dir(), 'sgf.log')
        file_handler = _RotatingFileHandler(log_path, maxBytes=1_000_000, backupCount=3, encoding='utf-8')
        file_handler.setFormatter(fmt)
        logger.addHandler(file_handler)
    except Exception as e:
        print(f"Could not initialize file logging: {e}")

    ring_handler = _RingBufferLogHandler()
    ring_handler.setFormatter(fmt)
    logger.addHandler(ring_handler)

    if DEBUG_MODE or SAFE_MODE:
        console_handler = _logging_mod.StreamHandler()
        console_handler.setFormatter(fmt)
        logger.addHandler(console_handler)

    logger.propagate = False
    return logger


sgf_log = _init_sgf_logging()


##############
# CRASH REPORTING
##############

def _gather_crash_context():
    theme_manager = globals().get('THEME_MANAGER')
    theme_id = getattr(theme_manager, 'active_theme_id', 'default')
    if not isinstance(theme_id, str) or not theme_id.strip():
        theme_id = 'default'
    theme_id = theme_id[:128]

    mod_manager = globals().get('MOD_MANAGER')
    active_mods = getattr(mod_manager, 'active', ())
    try:
        active_mod_ids = sorted({
            mod_id[:128] for mod_id in active_mods
            if isinstance(mod_id, str) and mod_id.strip()
        })[:128]
    except (TypeError, RuntimeError):
        active_mod_ids = []

    context = {
        'game_version': GAME_VERSION,
        'python_version': sys.version,
        'platform': sys.platform,
        'os_details': None,
        'pygame_version': None,
        'resolution': None,
        'active_theme': theme_id,
        'active_mods': active_mod_ids,
        'safe_mode': SAFE_MODE,
    }
    try:
        import platform as _platform_mod
        context['os_details'] = _platform_mod.platform()
    except Exception:
        pass
    try:
        context['pygame_version'] = pygame.version.ver
    except Exception:
        pass
    try:
        surf = pygame.display.get_surface()
        if surf:
            context['resolution'] = list(surf.get_size())
    except Exception:
        pass
    return context


def _write_crash_report(exc_type, exc_value, exc_tb):
    """Generate a crash report on an unhandled exception. Must never itself
    raise/crash — any failure here is swallowed and, at worst, printed."""
    try:
        import traceback as _tb_mod
        ts = datetime.now().strftime('%Y%m%d_%H%M%S')
        crash_path = os.path.join(_user_data_manager.get_crash_dir(), f'crash_{ts}.json')

        report = _gather_crash_context()
        report['timestamp'] = datetime.now().isoformat()
        report['traceback'] = ''.join(_tb_mod.format_exception(exc_type, exc_value, exc_tb))
        with _log_ring_lock:
            report['recent_log_events'] = list(_LOG_RING_BUFFER[-50:])

        with open(crash_path, 'w', encoding='utf-8') as _f:
            _f.write(scrub_sensitive_text(json.dumps(report, indent=2)))
        try:
            sgf_log.critical(f"Unhandled exception; crash report written to {crash_path}")
        except Exception:
            pass
        return crash_path
    except Exception as _report_err:
        try:
            print(f"(also failed to write crash report: {_report_err})")
        except Exception:
            pass
        return None


def _install_crash_handler():
    _default_hook = sys.excepthook

    def _hook(exc_type, exc_value, exc_tb):
        if issubclass(exc_type, KeyboardInterrupt):
            _default_hook(exc_type, exc_value, exc_tb)
            return
        _write_crash_report(exc_type, exc_value, exc_tb)
        _default_hook(exc_type, exc_value, exc_tb)

    sys.excepthook = _hook


_install_crash_handler()


