def _build_diagnostic_summary():
    """Return useful version metadata without local paths or profile names."""
    summary = {
        'game_version': GAME_VERSION,
        'save_format_version': SAVE_FORMAT_VERSION,
        'replay_format_version': REPLAY_FORMAT_VERSION,
        'python_version': sys.version,
        'platform': sys.platform,
        'safe_mode': SAFE_MODE,
    }
    try:
        import platform as _platform_mod
        summary['os_details'] = _platform_mod.platform()
    except Exception:
        pass
    try:
        summary['pygame_version'] = pygame.version.ver
    except Exception:
        pass
    try:
        summary['dependency_issues'] = _collect_environment_issues()
    except Exception:
        summary['dependency_issues'] = []
    return summary


def export_diagnostics(dest_zip_path=None):
    """Bundle logs, version/dependency info, and non-sensitive config
    metadata into one zip for a bug report. Deliberately excludes high
    scores, replays, and profile content."""
    import zipfile
    if dest_zip_path is None:
        ts = datetime.now().strftime('%Y%m%d_%H%M%S')
        dest_zip_path = os.path.join(_user_data_manager.get_diagnostics_dir(), f'sgf_diagnostics_{ts}.zip')

    summary = _build_diagnostic_summary()
    lab_score = lab_last_score()
    if lab_score:
        summary['ai_lab_score'] = lab_score        # "your PC simulated X AI moves per second"

    try:
        with zipfile.ZipFile(dest_zip_path, 'w', zipfile.ZIP_DEFLATED) as zf:
            zf.writestr('summary.json', scrub_sensitive_text(json.dumps(summary, indent=2)))

            def _add_scrubbed(path, archive_name):
                with open(path, 'r', encoding='utf-8', errors='replace') as source:
                    zf.writestr(archive_name, scrub_sensitive_text(source.read()))

            for dirpath, _dirnames, filenames in os.walk(_user_data_manager.get_log_dir()):
                for fn in filenames:
                    _add_scrubbed(os.path.join(dirpath, fn), os.path.join('logs', fn))
            crash_dir = _user_data_manager.get_crash_dir()
            for fn in sorted(os.listdir(crash_dir))[-5:] if os.path.isdir(crash_dir) else []:
                _add_scrubbed(os.path.join(crash_dir, fn), os.path.join('crashes', fn))
        return dest_zip_path
    except Exception as e:
        print(f"Error exporting diagnostics: {e}")
        return None


