def export_profile(profile_name='default'):
    """Export current settings as a portable, versioned profile. Includes
    theme/mod placeholders for forward-compatibility with the extension system."""
    try:
        gd = _load_data()
        profile = {
            'profile_format_version': 1,
            'game_version': GAME_VERSION,
            'exported_at': datetime.now().isoformat(),
            'settings': gd.get('settings', {}),
            'theme': gd.get('active_theme'),
            'mods': gd.get('active_mods', []),
        }
        path = os.path.join(_user_data_manager.get_profile_dir(), f'{profile_name}.json')
        _atomic_write_json(path, profile)
        return path
    except Exception as e:
        print(f"Error exporting profile: {e}")
        return None


def import_profile(path):
    """Import a previously exported profile. Validates structure before
    applying anything; never bypasses validation."""
    try:
        with open(path, 'r') as _f:
            profile = json.load(_f)
        if not isinstance(profile, dict) or not isinstance(profile.get('settings'), dict):
            return False, "Invalid profile file"
        gd = _load_data()
        gd['settings'] = profile['settings']
        _save_data(gd)
        return True, None
    except Exception as e:
        return False, str(e)


