_DATA_FILE = _new_data_file_path()

import hashlib

# ── Seed / RNG system ─────────────────────────────────────────────────────────
# Seeds use the full printable-ASCII alphabet (94 characters, excluding space).
# That gives 94^N unique seeds for an N-character seed string, maximising the
# namespace while staying human-typeable.

_SEED_CHARS = (
    '0123456789'
    'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    'abcdefghijklmnopqrstuvwxyz'
    '!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~'
)   # 94 printable ASCII chars (0x21–0x7E, all except space)


def generate_seed(length: int = 10) -> str:
    """Return a random seed string of the given length."""
    _sys_rng = random.SystemRandom()
    return ''.join(_sys_rng.choice(_SEED_CHARS) for _ in range(length))


def seed_to_int(seed: str) -> int:
    """Convert an arbitrary seed string to a stable integer via SHA-256."""
    return int(hashlib.sha256(seed.encode('utf-8')).hexdigest(), 16)


class SeedRNG:
    """
    A seeded random-number generator isolated from the global ``random`` module.
    Every game that has a seed creates one of these and uses it for *all*
    procedural decisions (obstacle / portal / fruit / powerup placement,
    AI tie-breaking, moving-obstacle direction, etc.).
    """
    def __init__(self, seed: str):
        self.seed_str = seed
        self._rng = random.Random(seed_to_int(seed))

    # ── convenience wrappers matching the random module API ─────────────
    def random(self):               return self._rng.random()
    def choice(self, seq):          return self._rng.choice(seq)
    def choices(self, pop, weights=None, k=1):
        return self._rng.choices(pop, weights=weights, k=k)
    def randint(self, a, b):        return self._rng.randint(a, b)
    def uniform(self, a, b):        return self._rng.uniform(a, b)
    def randrange(self, *args):     return self._rng.randrange(*args)
    def sample(self, pop, k):       return self._rng.sample(pop, k)
    def shuffle(self, lst):
        self._rng.shuffle(lst); return lst


_REPLAY_FORMAT_VERSION = 2


class GameplayPerformanceStats:
    """Low-overhead rolling gameplay/render performance telemetry.

    The object deliberately exposes data instead of drawing a debug UI so the
    integration/debug AI can surface it without coupling gameplay to UI code.
    """
    def __init__(self, history_size=120):
        self.history_size = max(30, int(history_size))
        self.samples = []
        self.last = {}

    def record_frame(self, frame_ms, update_ms=0.0, render_ms=0.0,
                     ai_ms=0.0, replay_ms=0.0, object_counts=None):
        sample = {
            'frame_ms': max(0.0, float(frame_ms)),
            'update_ms': max(0.0, float(update_ms)),
            'render_ms': max(0.0, float(render_ms)),
            'ai_ms': max(0.0, float(ai_ms)),
            'replay_ms': max(0.0, float(replay_ms)),
            'objects': dict(object_counts or {}),
        }
        self.samples.append(sample)
        if len(self.samples) > self.history_size:
            del self.samples[0]
        self.last = sample

    def snapshot(self):
        if not self.samples:
            return {
                'fps': 0.0, 'frame_ms': 0.0, 'update_ms': 0.0,
                'render_ms': 0.0, 'ai_ms': 0.0, 'replay_ms': 0.0,
                'objects': {}, 'sample_count': 0,
            }
        n = len(self.samples)
        avg = lambda key: sum(item[key] for item in self.samples) / n
        frame_ms = avg('frame_ms')
        return {
            'fps': (1000.0 / frame_ms) if frame_ms > 0 else 0.0,
            'frame_ms': frame_ms,
            'update_ms': avg('update_ms'),
            'render_ms': avg('render_ms'),
            'ai_ms': avg('ai_ms'),
            'replay_ms': avg('replay_ms'),
            'objects': dict(self.last.get('objects', {})),
            'sample_count': n,
        }

    def reset(self):
        self.samples.clear()
        self.last = {}

def run_determinism_smoke_test(game_factory, input_sequence=(), label='gameplay'):
    """Run seed/progression/replay checks against a caller-supplied game factory.

    ``game_factory`` must accept a seed string and return a fresh gameplay
    instance exposing ``next_direction``, ``move_snake``, ``deterministic_state_signature``
    and ``start_replay``. This stays UI-independent and is suitable for an
    external regression test runner.
    """
    first = game_factory('AI2_DETERMINISM_A')
    second = game_factory('AI2_DETERMINISM_A')
    initial_signature = copy.deepcopy(first.deterministic_state_signature())
    assert initial_signature == second.deterministic_state_signature(), \
        f'{label}: same seed produced different initial state'

    for direction in input_sequence:
        first.next_direction = tuple(direction)
        second.next_direction = tuple(direction)
        first.move_snake()
        second.move_snake()
        assert first.deterministic_state_signature() == second.deterministic_state_signature(), \
            f'{label}: same seed/input diverged during progression'

    other = game_factory('AI2_DETERMINISM_B')
    assert first.deterministic_state_signature() != other.deterministic_state_signature(), \
        f'{label}: different seeds produced identical state'

    history = copy.deepcopy(getattr(first, 'game_history', []))
    replay = game_factory(first.seed)
    if history:
        assert replay.start_replay(history), f'{label}: replay failed to start'
        assert replay.deterministic_state_signature()['snake'] == initial_signature['snake'], \
            f'{label}: first replay snapshot differs from initial state'

    return True


def run_ai_determinism_smoke_test():
    """Pure SnakeAI determinism smoke test; raises AssertionError on drift."""
    kwargs = dict(
        snake=[(5, 5), (4, 5), (3, 5)],
        occupied={(4, 5), (3, 5)},
        fruit=(15, 15),
        board_w=20, board_h=20, portals=[],
        powerup_pos=None, wall_collision=True, opponent_snake=[]
    )
    a = SnakeAI('hard', rng=SeedRNG('AI2_AI_TEST'))
    b = SnakeAI('hard', rng=SeedRNG('AI2_AI_TEST'))
    seq_a = [a.choose_direction(**kwargs) for _ in range(32)]
    seq_b = [b.choose_direction(**kwargs) for _ in range(32)]
    assert seq_a == seq_b, 'SnakeAI RNG stream is not deterministic'
    return True


# What the last read of game_data.json found. "ok" and "missing" are normal; "invalid" means the file
# exists but is not usable JSON (a copy is kept in backups/); "unreadable" means the file exists but could
# not be read right now (locked, no permission...), so saving is blocked until a read works again.
_DATA_LOAD_STATE = {'status': 'missing', 'reason': '', 'preserved': '', 'recovery_pending': False}


def _preserve_unreadable_data_file(path, raw):
    """Keep a copy of a game_data.json we could not parse, so a later save can never destroy it.

    The copy goes to SGF Data/backups as game_data_unreadable_<time>_<hash>.json. The same bytes are
    only copied once. Returns the copy's path, or '' if it could not be written."""
    try:
        digest = _hashlib.sha256(raw).hexdigest()[:10]
        try:
            folder = _user_data_manager.get_backup_dir()
        except Exception:
            folder = os.path.join(os.path.dirname(os.path.abspath(path)) or '.', 'backups')
        os.makedirs(folder, exist_ok=True)
        for name in os.listdir(folder):
            if name.startswith('game_data_unreadable_') and name.endswith(f'_{digest}.json'):
                return os.path.join(folder, name)
        stamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        target = os.path.join(folder, f'game_data_unreadable_{stamp}_{digest}.json')
        _atomic_write_bytes(target, raw)
        return target
    except Exception as exc:
        _logging_mod.getLogger('sgf').error('Could not keep a copy of the unreadable data file: %s', exc)
        return ''


def _read_game_data_file(path):
    """Read the unified data file. Returns (data, status, reason) with status ok/missing/invalid/unreadable."""
    if not os.path.exists(path):
        return {}, 'missing', ''
    try:
        with open(path, 'rb') as handle:
            raw = handle.read()
    except OSError as exc:
        return {}, 'unreadable', f'{type(exc).__name__}: {exc}'
    try:
        data = json.loads(raw.decode('utf-8-sig'))
        if not isinstance(data, dict):
            raise ValueError('the top level is not a JSON object')
        return data, 'ok', ''
    except Exception as exc:
        if not raw.strip():
            return {}, 'missing', ''                      # an empty file holds nothing to lose
        preserved = _preserve_unreadable_data_file(path, raw)
        _DATA_LOAD_STATE['preserved'] = preserved
        _DATA_LOAD_STATE['recovery_pending'] = True      # stays set until the player has been offered a recovery
        return {}, 'invalid', f'{type(exc).__name__}: {exc}'


def game_data_saving_blocked():
    """True while game_data.json exists but could not be read, so writing now could wipe real progress."""
    return _DATA_LOAD_STATE.get('status') == 'unreadable'


def find_recoverable_game_data_backups():
    """Valid JSON backups of the game data, newest first (for offering a recovery). Never modifies anything."""
    found = []
    try:
        folder = _user_data_manager.get_backup_dir()
        for name in os.listdir(folder):
            if not name.endswith('.json') or name.startswith('game_data_unreadable_'):
                continue
            full = os.path.join(folder, name)
            try:
                with open(full, 'r', encoding='utf-8') as handle:
                    if isinstance(json.load(handle), dict):
                        found.append((os.path.getmtime(full), full))
            except Exception:
                continue
    except Exception:
        return []
    return [path for _mtime, path in sorted(found, reverse=True)]


def _load_data():
    """Load the unified game data JSON, migrating old legacy files if needed.

    A file that exists but cannot be used is never treated as a fresh install: a copy is kept
    (invalid JSON) or saving is blocked (cannot be read right now), see _DATA_LOAD_STATE."""
    data, status, reason = _read_game_data_file(_DATA_FILE)
    _DATA_LOAD_STATE['reads'] = _DATA_LOAD_STATE.get('reads', 0) + 1      # lets a caller tell whether a read just happened
    _DATA_LOAD_STATE['status'] = status
    _DATA_LOAD_STATE['reason'] = reason
    if status in ('invalid', 'unreadable'):
        _logging_mod.getLogger('sgf').error('game_data.json is %s (%s)%s', status, reason,
                                            f"; copy kept at {_DATA_LOAD_STATE['preserved']}" if status == 'invalid' else '')
    if status == 'missing' and not os.path.exists(_DATA_FILE):
        # Migrate legacy separate files on first run
        for legacy_name, key in (('snake_settings.json', 'settings'), ('snake_highscores.json', 'highscores'),
                                 ('snake_achievements.json', 'achievements')):
            if os.path.exists(legacy_name):
                try:
                    with open(legacy_name, 'r') as _f:
                        data[key] = json.load(_f)
                except Exception:
                    pass
        if os.path.exists('snake_player_name.json'):
            try:
                with open('snake_player_name.json', 'r') as _f:
                    data['player_name'] = json.load(_f).get('player_name', '')
            except Exception:
                pass
    if isinstance(data, dict) and status != 'unreadable':
        data = _run_schema_migrations(data)
        data = _migrate_embedded_content(data)
    return data

class _CrossProcessDataLock:
    """Serialises writes to game_data.json between threads AND between running copies of the game.

    A threading.Lock covers the threads of this process; an operating-system file lock on
    `game_data.json.lock` (next to the data file) covers other processes. The OS drops that lock when its
    owner exits or crashes, so a lock abandoned by a dead instance never has to be cleaned up by hand.
    If the lock file cannot be created (read-only folder) saving carries on without it, and if another
    instance holds it for longer than `timeout` seconds the write goes ahead anyway (the write itself is
    still atomic): losing a save is worse than a rare overlap. Not reentrant, like the lock it replaces."""

    def __init__(self, timeout=5.0, poll=0.02):
        self._thread_lock = threading.Lock()
        self._timeout = timeout
        self._poll = poll
        self._fd = None
        self._owner = None

    @staticmethod
    def _os_lock(fd):
        """Try to take the exclusive OS lock without waiting; raises OSError if somebody else holds it."""
        if os.name == 'nt':
            import msvcrt
            os.lseek(fd, 0, os.SEEK_SET)
            msvcrt.locking(fd, msvcrt.LK_NBLCK, 1)
        else:
            import fcntl
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)

    @staticmethod
    def _os_unlock(fd):
        if os.name == 'nt':
            import msvcrt
            os.lseek(fd, 0, os.SEEK_SET)
            msvcrt.locking(fd, msvcrt.LK_UNLCK, 1)
        else:
            import fcntl
            fcntl.flock(fd, fcntl.LOCK_UN)

    def held_by_current_thread(self):
        return self._owner == threading.get_ident()

    def acquire(self):
        self._thread_lock.acquire()
        self._owner = threading.get_ident()
        fd = None
        try:
            fd = os.open(_DATA_FILE + '.lock', os.O_RDWR | os.O_CREAT, 0o644)
        except OSError:
            self._fd = None                      # no lock file possible here: threads are still serialised
            return True
        try:
            deadline = time.monotonic() + self._timeout
            while True:
                try:
                    self._os_lock(fd)
                    self._fd = fd
                    return True
                except OSError:
                    if time.monotonic() >= deadline:
                        _logging_mod.getLogger('sgf').warning(
                            'game_data.json lock held by another instance for %.0f s; saving anyway', self._timeout)
                        os.close(fd)
                        self._fd = None
                        return True
                    time.sleep(self._poll)
        except BaseException:
            try:
                os.close(fd)
            except OSError:
                pass
            self._owner = None
            self._thread_lock.release()
            raise

    def release(self):
        fd, self._fd = self._fd, None
        self._owner = None
        try:
            if fd is not None:
                try:
                    self._os_unlock(fd)
                finally:
                    os.close(fd)
        finally:
            self._thread_lock.release()

    def locked(self):
        return self._thread_lock.locked()

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, *exc_info):
        self.release()
        return False


_data_save_lock = _CrossProcessDataLock()
_async_data_writes = set()
_async_data_writes_lock = threading.Lock()
_replay_save_jobs = {}
_replay_save_jobs_lock = threading.Lock()
_content_migration_lock = threading.Lock()


def _safe_content_id(value, fallback='item'):
    """Return a portable filename stem without allowing path traversal."""
    value = str(value or '')
    safe = ''.join(ch for ch in value if ch.isalnum() or ch in ('-', '_', '.'))
    safe = safe.strip(' .')
    return safe[:100] or fallback


def _replay_path(replay_id):
    filename = f"replay_{_safe_content_id(replay_id, 'legacy')}.json"
    return os.path.join(_user_data_manager.get_replay_dir(), filename)


def _compressed_replay_path(replay_id):
    return _replay_path(replay_id) + '.gz'


# A replay can live as plain JSON, gzip (.json.gz, written when a game ends) or xz/LZMA (.json.xz, the
# "Ultra" compression profile: about 40 % smaller than gzip at the cost of much more time).
_REPLAY_CODEC_SUFFIX = {None: '.json', 'gz': '.json.gz', 'xz': '.json.xz'}
_REPLAY_SUFFIXES_BEST_FIRST = ('.json.xz', '.json.gz', '.json')


def _xz_replay_path(replay_id):
    return _replay_path(replay_id) + '.xz'


def _replay_split_name(filename):
    """('replay id', suffix) for replay_<id>.json[.gz|.xz], or None for any other file name."""
    if not filename.startswith('replay_'):
        return None
    for suffix in _REPLAY_SUFFIXES_BEST_FIRST:
        if filename.endswith(suffix) and len(filename) > len('replay_') + len(suffix):
            return filename[len('replay_'):-len(suffix)], suffix
    return None


def _replay_base_path(path):
    """`path` without its .json/.json.gz/.json.xz ending."""
    for suffix in _REPLAY_SUFFIXES_BEST_FIRST:
        if path.endswith(suffix):
            return path[:-len(suffix)]
    return path


def _replay_codec_of_path(path):
    if path.endswith('.json.xz'):
        return 'xz'
    if path.endswith('.json.gz'):
        return 'gz'
    return None


def _replay_open_text(path):
    codec = _replay_codec_of_path(path)
    if codec == 'xz':
        return lzma.open(path, 'rt', encoding='utf-8')
    if codec == 'gz':
        return gzip.open(path, 'rt', encoding='utf-8')
    return open(path, 'r', encoding='utf-8')


def _replay_xz_dict_size(length):
    """Smallest power-of-two dictionary (64 KiB to 64 MiB) that covers the data: memory use follows the file."""
    size = 1 << 16
    while size < length and size < (1 << 26):
        size <<= 1
    return size


def _replay_compress_bytes(raw, level):
    """`level`: None = plain JSON, an int = gzip level, 'xz' = LZMA at its strongest (extreme preset)."""
    if level is None:
        return raw
    if level == 'xz':
        filters = [{'id': lzma.FILTER_LZMA2, 'preset': 9 | lzma.PRESET_EXTREME,
                    'dict_size': _replay_xz_dict_size(len(raw)), 'lc': 4, 'lp': 0, 'pb': 0}]
        return lzma.compress(raw, format=lzma.FORMAT_XZ, check=lzma.CHECK_CRC64, filters=filters)
    return gzip.compress(raw, compresslevel=level, mtime=0)


def _existing_replay_path(replay_id):
    """The replay file to read: the most compressed variant that exists, else the plain path."""
    for candidate in (_xz_replay_path(replay_id), _compressed_replay_path(replay_id)):
        if os.path.isfile(candidate):
            return candidate
    return _replay_path(replay_id)


def _map_path(map_name):
    # A digest keeps filenames short and stable for Unicode names and avoids
    # collisions between names that sanitize to the same Windows filename.
    digest = hashlib.sha256(str(map_name).encode('utf-8')).hexdigest()[:24]
    return os.path.join(_user_data_manager.get_maps_created_dir(), f'map_{digest}.json')


def _save_replay_file(replay_id, payload):
    path = _replay_path(replay_id)
    _atomic_write_json(path, payload)
    with open(path, 'r', encoding='utf-8') as replay_file:
        saved = json.load(replay_file)
    if not isinstance(saved, dict) or not isinstance(saved.get('events'), list):
        raise ValueError('Saved replay failed validation')
    return path


def _load_replay_file(replay_id):
    if not replay_id:
        return None
    path = _existing_replay_path(replay_id)
    try:
        with _replay_open_text(path) as replay_file:
            payload = json.load(replay_file)
        return payload if isinstance(payload, dict) and isinstance(payload.get('events'), list) else None
    except (OSError, EOFError, gzip.BadGzipFile, lzma.LZMAError, ValueError, TypeError):
        return None


_REPLAY_EXISTS_MEMO = {}              # replay id -> (exists, checked_at)
_REPLAY_EXISTS_NEGATIVE_SECONDS = 3.0


def replay_exists_memo_clear():
    """Forget what is known about which replay files exist (after the player deleted or moved some)."""
    _REPLAY_EXISTS_MEMO.clear()


def _score_has_replay(score):
    """Does this score still have its replay file? Asked for every score of a list on every frame, so a file found
    is remembered (it only goes away when the player deletes it, which clears the memory); a missing one is
    re-checked at most every few seconds."""
    replay_id = score.get('replay_id')
    if replay_id:
        known = _REPLAY_EXISTS_MEMO.get(replay_id)
        now = time.monotonic()
        if known is not None and (known[0] or now - known[1] < _REPLAY_EXISTS_NEGATIVE_SECONDS):
            return known[0]
        exists = (os.path.isfile(_xz_replay_path(replay_id))
                  or os.path.isfile(_compressed_replay_path(replay_id))
                  or os.path.isfile(_replay_path(replay_id)))
        if len(_REPLAY_EXISTS_MEMO) > 20000:
            _REPLAY_EXISTS_MEMO.clear()
        _REPLAY_EXISTS_MEMO[replay_id] = (exists, now)
        return exists
    return bool(score.get('game_history') or score.get('mp_history'))


def _score_replay_id(score, fallback='replay'):
    game_id = _safe_content_id(score.get('game_id'), fallback)
    stamp = score.get('timestamp') or score.get('date')
    if stamp:
        try:
            parsed = datetime.fromisoformat(str(stamp).replace('Z', '+00:00'))
            stamp = parsed.strftime('%Y-%m-%dT%H-%M-%S.%f')
        except (TypeError, ValueError):
            stamp = ''.join(ch if ch.isalnum() or ch in ('-', '_', '.') else '-' for ch in str(stamp))
            stamp = stamp.strip('-.')
    else:
        stamp = datetime.now().strftime('%Y-%m-%dT%H-%M-%S.%f')
    return _safe_content_id(f'{stamp}_{game_id}', fallback)


def _score_replay_payload(score, history):
    payload = {
        'schema_version': REPLAY_FORMAT_VERSION,
        'game_id': score.get('game_id'),
        'timestamp': score.get('timestamp') or score.get('date'),
        'game_mode': score.get('game_mode', 'multiplayer' if score.get('is_multiplayer') else 'single_player'),
        'events': history,
        'truncated': bool(score.get('replay_truncated', False)),
        # Preserve the exact board used by this match even if its source map is
        # later renamed or deleted from the map editor.
        'custom_map': score.get('custom_map'),
    }
    for field in ('daily_challenge_id', 'daily_challenge_version',
                  'daily_challenge_modifier'):
        if field in score:
            payload[field] = score[field]
    for field in ('custom_challenge_id', 'custom_challenge_version'):
        if field in score:
            payload[field] = score[field]
    return payload


def _store_score_replay(score, history):
    """Persist a match history separately and leave a small reference in its score."""
    if not isinstance(history, list) or not history:
        score['has_replay'] = False
        score.pop('custom_map', None)
        return False
    replay_id = _score_replay_id(score, 'replay-' + hashlib.sha256(
        json.dumps(score, sort_keys=True, default=str).encode('utf-8')).hexdigest()[:20])
    try:
        _save_replay_file(replay_id, _score_replay_payload(score, history))
    except Exception as exc:
        _logging_mod.getLogger('sgf').warning('Could not save replay %s: %s', replay_id, exc)
        score['has_replay'] = False
        score.pop('custom_map', None)
        return False
    score['replay_id'] = replay_id
    score['has_replay'] = True
    score.pop('game_history', None)
    score.pop('mp_history', None)
    score.pop('custom_map', None)
    return True


def _merge_completed_score_data(data, score_entry, max_records):
    """Merge one finished score into fresh data without losing concurrent saves."""
    if not isinstance(data, dict):
        data = {}
    highscores = data.get('highscores', [])
    if not isinstance(highscores, list):
        highscores = []
    game_id = score_entry.get('game_id')
    highscores = [item for item in highscores
                  if not isinstance(item, dict) or item.get('game_id') != game_id]
    highscores.append(copy.deepcopy(score_entry))

    def _score_order(item):
        try:
            value = float(item.get('score', 0)) if isinstance(item, dict) else float('-inf')
            return value if math.isfinite(value) else float('-inf')
        except (TypeError, ValueError, OverflowError):
            return float('-inf')

    highscores.sort(key=_score_order, reverse=True)
    data['highscores'] = highscores[:max_records]
    if score_entry.get('mp_source') == 'lan_host':
        board_entries = _lan_entries_for_match(score_entry)
        if board_entries:
            board_ids = {item['game_id'] for item in board_entries}
            board = data.get('lan_leaderboard', [])
            if not isinstance(board, list):
                board = []
            board = [item for item in board if _clean_lan_score_entry(item)
                     and item.get('game_id') not in board_ids]
            board.extend(board_entries)
            data['lan_leaderboard'] = sorted(
                board, key=lambda item: (item['score'], item['date']), reverse=True)[:100]
    _sync_active_profile_snapshot(data)
    return data


_REPLAY_SAVE_SLOW_THRESHOLD_MS = 500.0
_MAX_REPLAY_RETRY_HISTORIES = 2
_REPLAY_SAVE_TIMED_PHASES = frozenset((
    'staging', 'serializing', 'compressing', 'writing', 'verifying',
    'indexing',
))


def _prune_replay_retry_histories_locked():
    failed = [(key, state) for key, state in _replay_save_jobs.items()
              if state.get('phase') == 'failed' and state.get('history')]
    for _old_key, old_state in failed[:-_MAX_REPLAY_RETRY_HISTORIES]:
        # Retain recent retry snapshots only. Durable recovery journals remain
        # available on disk, so old failures do not pin whole match histories.
        old_state['history'] = ()
        old_state['entry'] = {}


def _set_replay_save_phase(game_id, phase, **details):
    now_mono = time.perf_counter()
    record = None
    total_record = None
    with _replay_save_jobs_lock:
        state = _replay_save_jobs.get(str(game_id))
        if state is None:
            return
        previous = state.get('phase')
        previous_start = state.get('phase_started_monotonic', now_mono)
        if previous != phase:
            duration_ms = max(0.0, (now_mono - previous_start) * 1000.0)
            if previous in _REPLAY_SAVE_TIMED_PHASES:
                timings = state.setdefault('phase_durations_ms', {})
                timings[previous] = timings.get(previous, 0.0) + duration_ms
                if duration_ms >= _REPLAY_SAVE_SLOW_THRESHOLD_MS:
                    slow_phases = state.setdefault('slow_phases', [])
                    if previous not in slow_phases:
                        slow_phases.append(previous)
                record = (previous, duration_ms)
            state['phase_started_monotonic'] = now_mono
        state['phase'] = phase
        state['updated_at'] = time.time()
        state.update(details)
        if phase == 'failed':
            _prune_replay_retry_histories_locked()
        if phase in ('complete', 'failed'):
            total_ms = max(0.0, (now_mono - state.get(
                'started_monotonic', now_mono)) * 1000.0)
            state['total_duration_ms'] = total_ms
            state.setdefault('phase_durations_ms', {})['total'] = total_ms
            total_record = ('total', total_ms)
            if total_ms >= _REPLAY_SAVE_SLOW_THRESHOLD_MS:
                state.setdefault('slow_phases', []).append('total')
    for timing in (record, total_record):
        if timing is None:
            continue
        telemetry = getattr(globals().get('DEV_TOOLS'), 'telemetry', None)
        recorder = getattr(telemetry, 'record_save_phase', None)
        if callable(recorder):
            recorder(timing[0], timing[1])


def _get_replay_save_status(game_id):
    if not game_id:
        return None
    with _replay_save_jobs_lock:
        state = _replay_save_jobs.get(str(game_id))
        if state is None:
            return None
        public_state = {key: value for key, value in state.items()
                        if key not in ('done', 'entry', 'history',
                                       'started_monotonic',
                                       'phase_started_monotonic')}
        public_state['done'] = state['done'].is_set()
        public_state['has_history'] = bool(state.get('history'))
        current_phase = state.get('phase')
        current_elapsed_ms = max(0.0, (
            time.perf_counter() - state.get('phase_started_monotonic', time.perf_counter())
        ) * 1000.0)
        public_state['current_phase_elapsed_ms'] = current_elapsed_ms
        public_state['slow'] = bool(state.get('slow_phases')) or (
            current_phase in _REPLAY_SAVE_TIMED_PHASES and
            current_elapsed_ms >= _REPLAY_SAVE_SLOW_THRESHOLD_MS)
        return public_state


_REPLAY_RECOVERY_SCHEMA = 1
_REPLAY_RECOVERY_MAX_BYTES = 64 * 1024 * 1024


def _replay_recovery_dir():
    return os.path.join(_user_data_manager.get_save_dir(), 'recovery')


def _replay_recovery_path(game_id):
    safe_id = _safe_content_id(game_id, 'replay-recovery')
    return os.path.join(_replay_recovery_dir(), f'replay_job_{safe_id}.json.gz')


def _json_bytes_chunked(obj, big_key, chunk=150):
    """Compact JSON for a dict whose list under `big_key` is long (a replay's frames), encoded a slice at a time.

    One json.dumps call over a whole replay keeps the interpreter busy for its entire duration (about 25 ms for
    1500 frames, 100 ms for 6000), which freezes the game when a game ends. Slices let the game's own thread run
    between them. The result is valid JSON that parses to the same object; `big_key` comes last."""
    big = obj.get(big_key)
    dumps = lambda value: json.dumps(value, ensure_ascii=False, separators=(',', ':'))
    if not isinstance(big, (list, tuple)) or len(big) <= chunk:
        return dumps(obj).encode('utf-8')
    rest = dumps({k: v for k, v in obj.items() if k != big_key})
    body = ','.join(dumps(big[i:i + chunk])[1:-1] for i in range(0, len(big), chunk))
    prefix = rest[:-1] + ',' if rest != '{}' else '{'
    return (prefix + json.dumps(big_key) + ':[' + body + ']}').encode('utf-8')


def _write_replay_recovery_journal(game_id, score_entry, history, max_records):
    """Persist a bounded, verified retry snapshot before final replay work."""
    journal = {
        'recovery_schema': _REPLAY_RECOVERY_SCHEMA,
        'game_id': str(game_id)[:96],
        'score_entry': copy.deepcopy(score_entry),
        'history': list(history) if isinstance(history, (list, tuple)) else [],
        'max_records': max(1, min(10000, int(max_records))),
        'created_at': datetime.now().isoformat(),
    }
    raw = _json_bytes_chunked(journal, 'history')
    if len(raw) > _REPLAY_RECOVERY_MAX_BYTES:
        raise ValueError('Replay recovery snapshot exceeds the size limit')
    path = _replay_recovery_path(game_id)
    _atomic_write_bytes(path, gzip.compress(raw, compresslevel=6, mtime=0))
    # Verify by reading the file back and comparing it byte for byte with what was serialised: stronger than parsing
    # it again, and it does not hold the interpreter for the time a second full parse takes.
    with gzip.open(path, 'rb') as written:
        if written.read(_REPLAY_RECOVERY_MAX_BYTES + 1) != raw:
            raise ValueError('Replay recovery snapshot failed validation')
    return path


def _load_replay_recovery_journal(path):
    """Read a recovery snapshot with compressed and expanded size limits."""
    try:
        if os.path.getsize(path) > _REPLAY_RECOVERY_MAX_BYTES:
            return None
        with gzip.open(path, 'rb') as recovery_file:
            raw = recovery_file.read(_REPLAY_RECOVERY_MAX_BYTES + 1)
        if len(raw) > _REPLAY_RECOVERY_MAX_BYTES:
            return None
        journal = json.loads(raw.decode('utf-8'))
        if (not isinstance(journal, dict)
                or journal.get('recovery_schema') != _REPLAY_RECOVERY_SCHEMA
                or not isinstance(journal.get('game_id'), str)
                or not isinstance(journal.get('score_entry'), dict)
                or not isinstance(journal.get('history'), list)
                or len(journal['history']) > _REPLAY_SHARE_MAX_FRAMES
                or not isinstance(journal.get('max_records'), int)
                or isinstance(journal.get('max_records'), bool)
                or not 1 <= journal['max_records'] <= 10000):
            return None
        if journal['score_entry'].get('game_id') != journal['game_id']:
            return None
        return journal
    except (OSError, EOFError, gzip.BadGzipFile, UnicodeError, ValueError,
            TypeError, OverflowError):
        return None


def _list_replay_recovery_jobs():
    """Return validated pending replay saves without deleting invalid files."""
    directory = _replay_recovery_dir()
    try:
        names = sorted(name for name in os.listdir(directory)
                       if name.startswith('replay_job_') and name.endswith('.json.gz'))
    except OSError:
        return []
    jobs = []
    for name in names:
        path = os.path.join(directory, name)
        journal = _load_replay_recovery_journal(path)
        jobs.append({'path': path, 'journal': journal,
                     'invalid': journal is None})
    return jobs


def _discard_replay_recovery(path):
    """Discard only the exact recovery journal the player selected."""
    expected_root = os.path.abspath(_replay_recovery_dir())
    target = os.path.abspath(path)
    if os.path.dirname(target) != expected_root or not os.path.basename(target).startswith('replay_job_'):
        return False
    try:
        os.remove(target)
        return True
    except OSError:
        return False



def _retry_completed_score(game_id):
    """Retry a failed replay job from its immutable game-over snapshot."""
    key = str(game_id or '')
    with _replay_save_jobs_lock:
        state = _replay_save_jobs.get(key)
        if (state is None or not state['done'].is_set() or state.get('phase') != 'failed'
                or not state.get('history')):
            return False
        entry = copy.deepcopy(state.get('entry', {}))
        history = state['history']
        max_records = state.get('max_records', 10)
        state['done'].clear()
        state['phase'] = 'preparing'
        state['error'] = None
        state['retry_count'] = int(state.get('retry_count', 0)) + 1
        state['retry_rect'] = None
        state['phase_durations_ms'] = {}
        state['slow_phases'] = []
        state['started_monotonic'] = time.perf_counter()
        state['phase_started_monotonic'] = state['started_monotonic']
        state['updated_at'] = time.time()
    try:
        worker = threading.Thread(
            target=_write_completed_score_worker,
            args=(key, entry, history, max_records),
            name='SGF-replay-retry', daemon=True,
        )
        worker.start()
        return True
    except Exception as exc:
        _set_replay_save_phase(key, 'failed', error=type(exc).__name__)
        with _replay_save_jobs_lock:
            state = _replay_save_jobs.get(key)
            if state is not None:
                state['done'].set()
        return False


def _handle_replay_save_retry_event(owner, event):
    if (owner is None or event.type != pygame.MOUSEBUTTONDOWN or event.button != 1
            or not getattr(owner, 'game_over', False)):
        return False
    game_id = getattr(owner, '_replay_save_game_id', None)
    status = _get_replay_save_status(game_id)
    retry_rect = status.get('retry_rect') if status else None
    if retry_rect and retry_rect.collidepoint(event.pos):
        _retry_completed_score(game_id)
        return True
    return False

def _draw_replay_save_widget(surface, language, game_id, center, top):
    """Render real replay-save state without exposing worker internals or blocking."""
    status = _get_replay_save_status(game_id)
    if status is None:
        return
    if status['phase'] == 'complete' and time.time() - status['updated_at'] > 3.0:
        return

    sw, _sh = surface.get_size()
    box_w = min(360, max(220, sw - 32))
    failed = status['phase'] == 'failed'
    box_h = 92 if failed and status.get('has_history') else 78
    rect = pygame.Rect(int(center - box_w // 2), int(top), box_w, box_h)
    complete = status['phase'] == 'complete'
    bg = (65, 30, 35) if failed else ((25, 60, 42) if complete else (24, 35, 62))
    border = (210, 90, 90) if failed else ((90, 210, 130) if complete else (90, 135, 215))
    pygame.draw.rect(surface, bg, rect, border_radius=8)
    pygame.draw.rect(surface, border, rect, width=1, border_radius=8)

    slow = bool(status.get('slow'))
    key = ('replay_save_failed' if failed else
           'replay_save_slow' if slow else
           'score_replay_saved' if complete else 'replay_saving')
    color = ((255, 180, 180) if failed else
             (255, 205, 110) if slow else
             (150, 245, 175) if complete else (220, 230, 255))
    font = get_font(language, 'regular', 16)
    text = render_fit(font, get_text(language, key), color, rect.width - 18, padding=0)
    if failed and status.get('has_history'):
        surface.blit(text, text.get_rect(center=(rect.centerx, rect.y + 15)))
        last_phase = next(reversed(status.get('phase_durations_ms', {})), None)
        if last_phase:
            phase_key = {
                'staging': 'replay_phase_preparing',
                'serializing': 'replay_phase_serializing',
                'compressing': 'replay_phase_compressing',
                'writing': 'replay_phase_writing',
                'verifying': 'replay_phase_verifying',
                'indexing': 'replay_phase_indexing',
            }.get(last_phase)
            if phase_key:
                phase_text = render_fit(get_font(language, 'regular', 12),
                                        get_text(language, phase_key),
                                        (220, 225, 240), rect.width - 18, padding=0)
                surface.blit(phase_text, phase_text.get_rect(center=(rect.centerx, rect.y + 37)))
        retry_rect = pygame.Rect(rect.centerx - 48, rect.y + 65, 96, 21)
        pygame.draw.rect(surface, (105, 48, 55), retry_rect, border_radius=5)
        pygame.draw.rect(surface, border, retry_rect, width=1, border_radius=5)
        retry_text = render_fit(get_font(language, 'bold', 13),
                                get_text(language, 'replay_save_retry'),
                                (255, 230, 230), retry_rect.width - 8, padding=0)
        surface.blit(retry_text, retry_text.get_rect(center=retry_rect.center))
        _set_replay_save_phase(game_id, 'failed', retry_rect=retry_rect)
    else:
        surface.blit(text, text.get_rect(center=(rect.centerx, rect.y + 17)))
        phase = status.get('phase')
        phase_key = {
            'preparing': 'replay_phase_preparing',
            'staging': 'replay_phase_preparing',
            'serializing': 'replay_phase_serializing',
            'compressing': 'replay_phase_compressing',
            'writing': 'replay_phase_writing',
            'verifying': 'replay_phase_verifying',
            'indexing': 'replay_phase_indexing',
            'complete': 'replay_phase_complete',
        }.get(phase)
        if phase_key:
            phase_text = render_fit(get_font(language, 'regular', 12),
                                    get_text(language, phase_key),
                                    (195, 205, 225), rect.width - 18, padding=0)
            surface.blit(phase_text, phase_text.get_rect(center=(rect.centerx, rect.y + 38)))
        original_bytes = status.get('original_bytes')
        compressed_bytes = status.get('compressed_bytes')
        if original_bytes is not None:
            def _format_replay_size(value):
                value = max(0, int(value))
                if value >= 1024 * 1024:
                    return f'{value / (1024 * 1024):.1f} MB'
                if value >= 1024:
                    return f'{value / 1024:.1f} KB'
                return f'{value} B'
            size_label = _format_replay_size(original_bytes)
            if compressed_bytes is not None:
                size_label += ' → ' + _format_replay_size(compressed_bytes)
            size_text = render_fit(get_font(language, 'regular', 11), size_label,
                                   (165, 180, 205), rect.width - 18, padding=0)
            surface.blit(size_text, size_text.get_rect(center=(rect.centerx, rect.y + 54)))

    if not failed and not complete:
        # This is deliberately indeterminate: serialization/compression do not
        # expose byte-level progress, so the animation communicates activity
        # without inventing a percentage.
        track = pygame.Rect(rect.x + 10, rect.bottom - 4, rect.width - 20, 3)
        pygame.draw.rect(surface, (55, 70, 100), track, border_radius=2)
        segment_w = max(24, track.width // 5)
        travel = max(1, track.width - segment_w)
        segment_x = track.x + int((time.monotonic() * 0.8 % 1.0) * travel)
        pygame.draw.rect(surface, (135, 175, 255),
                         pygame.Rect(segment_x, track.y, segment_w, track.height),
                         border_radius=2)


class ReplayRecoveryScreen:
    """Offer explicit recovery actions for a durable interrupted save."""
    def __init__(self, settings, screen, recovery_item):
        self.settings = settings
        self.screen = screen
        self.recovery_item = recovery_item
        self.error = None
        self.active_game_id = None

    def _draw(self):
        screen = self.screen
        sw, sh = screen.get_size()
        language = self.settings.language
        high_contrast = bool(getattr(self.settings, 'high_contrast', False))
        background = (0, 0, 0) if high_contrast else (12, 18, 31)
        panel_color = (0, 0, 0) if high_contrast else (25, 34, 52)
        accent = (255, 255, 0) if high_contrast else (112, 153, 220)
        screen.fill(background)
        panel = pygame.Rect(12, 12, max(1, sw - 24), max(1, sh - 24))
        pygame.draw.rect(screen, panel_color, panel, border_radius=12)
        pygame.draw.rect(screen, accent, panel, width=2, border_radius=12)
        title = get_font(language, 'bold', max(20, min(32, int(sh * .055))))
        title_surface = render_fit(title, get_text(language, 'recovered_session_title'),
                                   COLORS['white'], panel.w - 36, padding=0)
        screen.blit(title_surface, title_surface.get_rect(midtop=(panel.centerx, panel.y + 24)))

        journal = self.recovery_item.get('journal')
        message_key = 'recovery_interrupted' if journal else 'recovery_invalid'
        body_font = get_font(language, 'regular', max(15, min(20, int(sh * .034))))
        body_lines = _wrap_text(get_text(language, message_key), body_font, panel.w - 44)
        body_y = panel.y + 86
        for line in body_lines[:5]:
            body = body_font.render(line, True, COLORS['white'])
            screen.blit(body, body.get_rect(centerx=panel.centerx, top=body_y))
            body_y += body.get_height() + 7

        if self.active_game_id:
            status = _get_replay_save_status(self.active_game_id)
            if status and status['phase'] == 'complete':
                _discard_replay_recovery(self.recovery_item['path'])
                return 'recovered'
            if status and status['phase'] == 'failed':
                self.active_game_id = None
                self.error = get_text(language, 'replay_save_failed')

        if self.error:
            error_surface = render_fit(body_font, self.error, (255, 150, 150),
                                       panel.w - 36, padding=0)
            screen.blit(error_surface, error_surface.get_rect(center=(panel.centerx, sh - 116)))
        elif self.active_game_id:
            progress_surface = render_fit(body_font, get_text(language, 'replay_saving'),
                                          COLORS['light_blue'], panel.w - 36, padding=0)
            screen.blit(progress_surface, progress_surface.get_rect(center=(panel.centerx, sh - 116)))

        gap = 12
        button_w = max(1, min(220, (panel.w - 48 - gap) // 2))
        button_h = max(40, min(54, int(sh * .09)))
        row_y = panel.bottom - button_h * 2 - 38
        left_x = panel.centerx - button_w - gap // 2
        right_x = panel.centerx + gap // 2
        entries = [
            ('recover', get_text(language, 'recovery_recover'), bool(journal)),
            ('discard', get_text(language, 'recovery_discard'), True),
            ('open', get_text(language, 'recovery_open_data'), True),
            ('later', get_text(language, 'recovery_later'), True),
        ]
        rects = {}
        for index, (action, label, enabled) in enumerate(entries):
            col, row = index % 2, index // 2
            rect = pygame.Rect(left_x if col == 0 else right_x,
                               row_y + row * (button_h + 10), button_w, button_h)
            rects[action] = rect
            color = ((0, 0, 0) if high_contrast else
                     ((78, 86, 104) if not enabled else
                      (60, 76, 105) if action == 'recover' else (46, 58, 78)))
            edge = accent if enabled else (150, 150, 150)
            pygame.draw.rect(screen, color, rect, border_radius=7)
            pygame.draw.rect(screen, edge, rect, width=2 if high_contrast else 1,
                             border_radius=7)
            label_surface = render_fit(get_font(language, 'bold', 16), label,
                                       COLORS['white'] if enabled else COLORS['gray'],
                                       rect.w - 10, padding=0)
            screen.blit(label_surface, label_surface.get_rect(center=rect.center))
        pygame.display.flip()
        return rects

    def _recover(self):
        journal = self.recovery_item.get('journal')
        if not journal:
            return False
        self.error = None
        self.active_game_id = _queue_completed_score(
            journal['score_entry'], journal['history'], journal['max_records'])
        if self.active_game_id is None:
            self.error = get_text(self.settings.language, 'replay_save_failed')
            return False
        return True

    def run(self):
        clock = pygame.time.Clock()
        while True:
            rects = self._draw()
            if isinstance(rects, str):
                return rects
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    return 'later'
                if event.type == pygame.VIDEORESIZE:
                    self.screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)
                    continue
                action = None
                if event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_ESCAPE:
                        return 'later'
                    if self.active_game_id:
                        continue
                    action = {
                        pygame.K_r: 'recover', pygame.K_d: 'discard',
                        pygame.K_o: 'open', pygame.K_l: 'later',
                    }.get(event.key)
                elif event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
                    for candidate, rect in rects.items():
                        if rect.collidepoint(event.pos):
                            action = candidate
                            break
                if action == 'recover' and not self.active_game_id:
                    self._recover()
                elif action == 'discard' and not self.active_game_id:
                    if _discard_replay_recovery(self.recovery_item['path']):
                        return 'discarded'
                    self.error = get_text(self.settings.language, 'replay_save_failed')
                elif action == 'open':
                    _user_data_manager.open_data_folder()
                    return 'open'
                elif action == 'later':
                    return 'later'
            clock.tick(30)


def _write_completed_score_worker(game_id, score_entry, history, max_records):
    """Thread entry point. Whatever goes wrong inside, the job is logged, marked failed and finished, so a
    screen waiting on it (or the exit hook) is never left waiting for a thread that has already died."""
    try:
        _write_completed_score_worker_body(game_id, score_entry, history, max_records)
    except BaseException as exc:
        try:
            _logging_mod.getLogger('sgf').exception('Replay/score save thread failed for %s', game_id)
        except Exception:
            pass
        try:
            _set_replay_save_phase(game_id, 'failed', error=type(exc).__name__)
        except Exception:
            pass
        with _replay_save_jobs_lock:
            state = _replay_save_jobs.get(str(game_id))
            if state is not None:
                state['done'].set()
                state['updated_at'] = time.time()


def _write_completed_score_worker_body(game_id, score_entry, history, max_records):
    replay_path = None
    recovery_path = None
    replay_saved = False
    replay_error = None
    try:
        _set_replay_save_phase(game_id, 'staging')
        recovery_path = _write_replay_recovery_journal(
            game_id, score_entry, history, max_records)
        _set_replay_save_phase(game_id, 'staging', recovery_available=True)
    except Exception as exc:
        _logging_mod.getLogger('sgf').warning(
            'Could not create replay recovery snapshot %s: %s', game_id, exc)
        _set_replay_save_phase(game_id, 'staging', recovery_available=False)
    try:
        if history:
            _set_replay_save_phase(game_id, 'serializing')
            payload = _score_replay_payload(score_entry, history)
            raw = _json_bytes_chunked(payload, 'events')
            _set_replay_save_phase(game_id, 'compressing', original_bytes=len(raw))
            compressed = gzip.compress(raw, compresslevel=6, mtime=0)
            replay_path = _compressed_replay_path(score_entry['replay_id'])
            _set_replay_save_phase(game_id, 'writing', compressed_bytes=len(compressed))
            _atomic_write_bytes(replay_path, compressed)
            _set_replay_save_phase(game_id, 'verifying')
            with gzip.open(replay_path, 'rb') as replay_file:
                written = replay_file.read()
            if (written != raw or not isinstance(payload.get('events'), (list, tuple))
                    or payload.get('game_id') != score_entry.get('game_id')
                    or len(payload['events']) != len(history)):
                raise ValueError('Compressed replay failed validation')
            replay_saved = True
    except Exception as exc:
        replay_error = type(exc).__name__
        if replay_path:
            try: os.remove(replay_path)
            except OSError: pass

    persisted_entry = copy.deepcopy(score_entry)
    persisted_entry['has_replay'] = replay_saved
    if not replay_saved:
        persisted_entry.pop('replay_id', None)
    persisted_entry.pop('custom_map', None)
    try:
        _set_replay_save_phase(game_id, 'indexing')
        with _data_save_lock:
            try:
                signature = _file_signature(_DATA_FILE)
                if (signature is not None and _SCORE_DATA_CACHE['signature'] == signature
                        and _SCORE_DATA_CACHE['path'] == _DATA_FILE and _SCORE_DATA_CACHE['data'] is not None):
                    fresh_data = _SCORE_DATA_CACHE['data']      # exactly what this worker wrote last time: no need to read it again
                else:
                    reads_before = _DATA_LOAD_STATE.get('reads', 0)
                    fresh_data = _load_data()
                    if _DATA_LOAD_STATE.get('reads', 0) != reads_before and game_data_saving_blocked():
                        raise OSError('the saved data could not be read, so nothing was written over it')
                ids_before = {s.get('replay_id') for s in fresh_data.get('highscores', []) if isinstance(s, dict) and s.get('replay_id')}
                fresh_data = _merge_completed_score_data(
                    fresh_data, persisted_entry, max_records)
                _atomic_write_json(_DATA_FILE, fresh_data)
                _SCORE_DATA_CACHE.update(signature=_file_signature(_DATA_FILE), path=_DATA_FILE, data=fresh_data)
            except BaseException:
                _SCORE_DATA_CACHE.update(signature=None, path=None, data=None)
                raise
            _prune_dropped_score_replays(ids_before, fresh_data)       # only what this game pushed off the list
            if replay_saved:
                replay_list_note_new()
        if replay_error:
            _set_replay_save_phase(game_id, 'failed', error=replay_error)
        else:
            _set_replay_save_phase(game_id, 'complete')
    except Exception as exc:
        if replay_saved and replay_path:
            try: os.remove(replay_path)
            except OSError: pass
        _set_replay_save_phase(game_id, 'failed', error=type(exc).__name__)
    finally:
        with _replay_save_jobs_lock:
            state = _replay_save_jobs.get(str(game_id))
            completed_successfully = bool(state and state.get('phase') == 'complete')
        if completed_successfully and recovery_path:
            _discard_replay_recovery(recovery_path)
        with _replay_save_jobs_lock:
            state = _replay_save_jobs.get(str(game_id))
            if state is not None:
                if completed_successfully:
                    # The durable replay file is now the sole source of truth;
                    # do not keep another full in-memory copy in the status map.
                    state['history'] = ()
                    state['entry'] = {}
                state['done'].set()
                state['updated_at'] = time.time()


_HIGHSCORE_KEPT = [None]
HIGHSCORE_KEEP_OPTIONS = (10, 25, 50, 100, 250, 500, 1000)


def highscore_records_kept():
    """How many scores (and replays) are kept. The player chooses it (Data > Replays); 10 by default. Read once."""
    if _HIGHSCORE_KEPT[0] is None:
        try:
            value = int(_load_data().get('highscore_records_kept', 10))
        except Exception:
            value = 10
        _HIGHSCORE_KEPT[0] = max(10, min(1000, value))
    return _HIGHSCORE_KEPT[0]


def highscore_records_set(count):
    count = max(10, min(1000, int(count)))
    _HIGHSCORE_KEPT[0] = count

    def mutate(data):
        data['highscore_records_kept'] = count
        return data
    _save_data_async(mutate)
    return count


def _queue_completed_score(score_entry, history, max_records=10):
    """Return immediately and persist replay compression/indexing off the UI thread."""
    if not isinstance(score_entry, dict):
        return None
    max_records = max(int(max_records), highscore_records_kept())      # the player may keep more than the default
    game_id = str(score_entry.get('game_id') or _secrets_mod.token_hex(12))[:96]
    try:
        history_snapshot = tuple(history) if isinstance(history, (list, tuple)) else ()
    except Exception:
        history_snapshot = ()
    prepared = copy.deepcopy(score_entry)
    prepared['game_id'] = game_id
    prepared['has_replay'] = bool(history_snapshot)
    if history_snapshot:
        prepared['replay_id'] = _score_replay_id(prepared, 'replay-' + _secrets_mod.token_hex(10))
    else:
        prepared.pop('replay_id', None)

    started_monotonic = time.perf_counter()
    with _replay_save_jobs_lock:
        completed = [key for key, item in _replay_save_jobs.items() if item['done'].is_set()]
        for key in completed[:-64]:
            _replay_save_jobs.pop(key, None)
        pending = sum(not item['done'].is_set() for item in _replay_save_jobs.values())
        state = {
            'game_id': game_id,
            'replay_id': prepared.get('replay_id'),
            'phase': 'preparing' if history_snapshot else 'indexing',
            'error': None,
            'original_bytes': None,
            'compressed_bytes': None,
            'started_at': time.time(),
            'started_monotonic': started_monotonic,
            'phase_started_monotonic': started_monotonic,
            'phase_durations_ms': {},
            'slow_phases': [],
            'updated_at': time.time(),
            'done': threading.Event(),
            'entry': copy.deepcopy(prepared),
            'history': history_snapshot,
            'max_records': max(1, int(max_records)),
            'retry_rect': None,
            'retry_count': 0,
        }
        _replay_save_jobs[game_id] = state

    if pending >= 4:
        fallback_entry = copy.deepcopy(prepared)
        fallback_entry['has_replay'] = False
        fallback_entry.pop('replay_id', None)
        fallback_entry.pop('custom_map', None)
        _set_replay_save_phase(game_id, 'failed', error='queue_full')
        _save_data_async(lambda data: _merge_completed_score_data(data, fallback_entry, max_records))
        with _replay_save_jobs_lock:
            _replay_save_jobs[game_id]['done'].set()
        return game_id

    try:
        worker = threading.Thread(
            target=_write_completed_score_worker,
            args=(game_id, prepared, history_snapshot, max(1, int(max_records))),
            name='SGF-replay-persist', daemon=True,
        )
        worker.start()
    except Exception as exc:
        prepared['has_replay'] = False
        prepared.pop('replay_id', None)
        prepared.pop('custom_map', None)
        _set_replay_save_phase(game_id, 'failed', error=type(exc).__name__)
        _save_data_async(lambda data: _merge_completed_score_data(data, prepared, max_records))
        with _replay_save_jobs_lock:
            _replay_save_jobs[game_id]['done'].set()
    return game_id


def _history_for_score(score):
    """Load a replay from its file, while accepting legacy inline records."""
    payload = _load_replay_file(score.get('replay_id'))
    if payload is not None:
        resolved = dict(score)
        resolved['custom_map'] = payload.get('custom_map')
        for field in ('daily_challenge_id', 'daily_challenge_version',
                      'daily_challenge_modifier'):
            if field not in resolved and field in payload:
                resolved[field] = payload[field]
        for field in ('custom_challenge_id', 'custom_challenge_version'):
            if field not in resolved and field in payload:
                resolved[field] = payload[field]
        if score.get('is_multiplayer') and score.get('mp_mode'):
            resolved['mp_history'] = payload['events']
        else:
            resolved['game_history'] = payload['events']
        return resolved
    return dict(score)


_REPLAY_SHARE_PREFIX = 'SNAKE-REPLAY:v1:'
_REPLAY_SHARE_MAX_CODE_BYTES = 8 * 1024 * 1024
_REPLAY_SHARE_MAX_PAYLOAD_BYTES = 32 * 1024 * 1024
_REPLAY_SHARE_MAX_FRAMES = 2_000_000          # sanity bound for imported files; the byte limits above still apply
_REPLAY_SHARE_SCORE_FIELDS = (
    'name', 'score', 'date', 'timestamp', 'board_size', 'update_rate_ms',
    'victory', 'wall_collision', 'powerups_enabled', 'fruit_types_enabled',
    'obstacles_enabled', 'portals_enabled', 'portal_pairs', 'seed',
    'replay_format_version', 'actual_board_width', 'actual_board_height',
    'game_mode', 'ai_difficulty', 'ai_count', 'ai_configs', 'is_multiplayer',
    'mp_mode', 'mp_source', 'player_count', 'player_names', 'player_configs',
    'player_scores', 'winner', 'replay_truncated', 'daily_challenge_id',
    'daily_challenge_version', 'daily_challenge_modifier',
    'custom_challenge_id', 'custom_challenge_version',
)
_REPLAY_SHARE_SETTING_FIELDS = (
    'board_size', 'update_rate_ms', 'wall_collision', 'powerups_enabled',
    'fruit_types_enabled', 'enable_obstacles', 'enable_portals', 'portal_pairs',
    'obstacle_count', 'ghost_mode_enabled',
)


def _replay_share_digest(bundle):
    canonical = json.dumps(bundle, sort_keys=True, separators=(',', ':'),
                           ensure_ascii=False, allow_nan=False).encode('utf-8')
    return hashlib.sha256(canonical).hexdigest()


def export_replay_share_code(score_data):
    """Build a bounded, versioned clipboard code using the canonical replay."""
    if not isinstance(score_data, dict) or not _score_has_replay(score_data):
        raise ValueError('This score has no saved replay.')
    resolved = _history_for_score(score_data)
    if 'mp_history' in resolved:
        events = resolved['mp_history']
    else:
        events = resolved.get('game_history')
    if not isinstance(events, list) or not events or len(events) > _REPLAY_SHARE_MAX_FRAMES:
        raise ValueError('Replay has an unsupported frame count.')
    metadata = _copy_json_safe({k: resolved[k] for k in _REPLAY_SHARE_SCORE_FIELDS
                                if k in resolved})
    settings = resolved.get('settings')
    if isinstance(settings, dict):
        metadata['settings'] = _copy_json_safe({
            key: settings[key] for key in _REPLAY_SHARE_SETTING_FIELDS
            if key in settings and isinstance(settings[key], (bool, int))
        })
    replay = _score_replay_payload(metadata, events)
    bundle = {
        'magic': 'SNAKE-REPLAY', 'share_version': 1,
        'game_version': GAME_VERSION, 'score': metadata, 'replay': replay,
    }
    bundle['sha256'] = _replay_share_digest(bundle)
    raw = json.dumps(bundle, sort_keys=True, separators=(',', ':'),
                     ensure_ascii=False, allow_nan=False).encode('utf-8')
    if len(raw) > _REPLAY_SHARE_MAX_PAYLOAD_BYTES:
        raise ValueError('Replay is too large to share.')
    encoded = _base64_mod.urlsafe_b64encode(_zlib_mod.compress(raw, 9)).decode('ascii').rstrip('=')
    code = _REPLAY_SHARE_PREFIX + encoded
    if len(code.encode('ascii')) > _REPLAY_SHARE_MAX_CODE_BYTES:
        raise ValueError('Replay share code exceeds the size limit.')
    return code


def import_replay_share_code(code):
    """Decode and validate an untrusted share code without writing to disk."""
    if not isinstance(code, str) or len(code.encode('utf-8', 'ignore')) > _REPLAY_SHARE_MAX_CODE_BYTES:
        raise ValueError('Replay share code is invalid or too large.')
    code = code.strip()
    if not code.startswith(_REPLAY_SHARE_PREFIX):
        raise ValueError('Replay share code has an unknown format.')
    encoded = code[len(_REPLAY_SHARE_PREFIX):]
    if not encoded or any(ch.isspace() for ch in encoded):
        raise ValueError('Replay share code is incomplete.')
    try:
        encoded_bytes = encoded.encode('ascii')
        compressed = _base64_mod.b64decode(
            encoded_bytes + b'=' * (-len(encoded_bytes) % 4), altchars=b'-_', validate=True)
        decoder = _zlib_mod.decompressobj()
        raw = decoder.decompress(compressed, _REPLAY_SHARE_MAX_PAYLOAD_BYTES + 1)
        if len(raw) > _REPLAY_SHARE_MAX_PAYLOAD_BYTES or decoder.unconsumed_tail:
            raise ValueError('Replay payload exceeds the size limit.')
        raw += decoder.flush(_REPLAY_SHARE_MAX_PAYLOAD_BYTES + 1 - len(raw))
        if len(raw) > _REPLAY_SHARE_MAX_PAYLOAD_BYTES or not decoder.eof or decoder.unused_data:
            raise ValueError('Replay payload is incomplete or exceeds the size limit.')
        bundle = json.loads(raw.decode('utf-8'))
    except (UnicodeError, ValueError, TypeError, RecursionError, _zlib_mod.error) as exc:
        if isinstance(exc, ValueError) and str(exc).startswith('Replay payload'):
            raise
        raise ValueError('Replay share code could not be decoded.') from exc
    if not isinstance(bundle, dict) or bundle.get('magic') != 'SNAKE-REPLAY' or bundle.get('share_version') != 1:
        raise ValueError('Replay share version is not supported.')
    supplied_digest = bundle.pop('sha256', None)
    if not isinstance(supplied_digest, str) or not _hmac_mod.compare_digest(
            supplied_digest, _replay_share_digest(bundle)):
        raise ValueError('Replay share integrity check failed.')
    score, replay = bundle.get('score'), bundle.get('replay')
    if not isinstance(score, dict) or not isinstance(replay, dict):
        raise ValueError('Replay share data is malformed.')
    try:
        replay_version = int(replay.get('schema_version', 1))
    except (TypeError, ValueError, OverflowError):
        raise ValueError('Replay format version is invalid.')
    if replay_version < 1 or replay_version > REPLAY_FORMAT_VERSION:
        raise ValueError('Replay format version is not supported by this game.')
    events = replay.get('events')
    if not isinstance(events, list) or not events or len(events) > _REPLAY_SHARE_MAX_FRAMES:
        raise ValueError('Replay frame count is invalid.')
    def _valid_cell(cell):
        return (isinstance(cell, (list, tuple)) and len(cell) == 2 and
                all(type(v) is int and -256 <= v <= 256 for v in cell))

    mode = str(score.get('game_mode', replay.get('game_mode', 'single_player')))
    if mode == 'vs_ai':
        valid_events = all(
            isinstance(frame, dict) and
            all(key in frame for key in ('p1', 'p1s', 'p1a', 'ais', 'ass', 'aia')) and
            isinstance(frame['p1'], list) and len(frame['p1']) <= 20000 and
            all(_valid_cell(cell) for cell in frame['p1']) and
            isinstance(frame['ais'], list) and len(frame['ais']) <= 4 and
            all(isinstance(snake, list) and len(snake) <= 20000 and
                all(_valid_cell(cell) for cell in snake) for snake in frame['ais']) and
            isinstance(frame['ass'], list) and len(frame['ass']) <= 4 and
            all(type(value) is int and 0 <= value <= 10**9 for value in frame['ass'])
            for frame in events)
    elif score.get('is_multiplayer'):
        valid_events = all(
            (isinstance(frame, dict) and isinstance(frame.get('snakes'), list) and
             1 <= len(frame['snakes']) <= 4 and
             all(isinstance(snake, list) and len(snake) <= 20000 and
                 all(_valid_cell(cell) for cell in snake) for snake in frame['snakes']))
            or (isinstance(frame, dict) and all(k in frame for k in ('p1', 'p2')) and
                isinstance(frame['p1'], list) and isinstance(frame['p2'], list) and
                len(frame['p1']) <= 20000 and len(frame['p2']) <= 20000 and
                all(_valid_cell(cell) for cell in frame['p1'] + frame['p2']))
            or (isinstance(frame, list) and len(frame) >= 9)
            for frame in events)
    else:
        valid_events = all(isinstance(frame, list) and 5 <= len(frame) <= 12 and
                           isinstance(frame[0], list) and 1 <= len(frame[0]) <= 20000 and
                           all(_valid_cell(cell) for cell in frame[0]) and
                           _valid_cell(frame[4]) and
                           type(frame[3]) is int and 0 <= frame[3] <= 10**9
                           for frame in events)
    if not valid_events:
        raise ValueError('Replay snapshots are malformed for this game mode.')
    resolved = {key: score[key] for key in _REPLAY_SHARE_SCORE_FIELDS if key in score}
    name = score.get('name', 'Imported replay')
    resolved['name'] = name[:80] if isinstance(name, str) else 'Imported replay'
    score_value = score.get('score', 0)
    resolved['score'] = score_value if type(score_value) is int and 0 <= score_value <= 10**9 else 0
    for key in ('date', 'timestamp', 'seed'):
        value = score.get(key)
        if isinstance(value, str):
            resolved[key] = value[:128]
        else:
            resolved.pop(key, None)
    for key in ('board_size', 'actual_board_width', 'actual_board_height'):
        value = score.get(key)
        if type(value) is not int or not 5 <= value <= 200:
            resolved.pop(key, None)
    update_rate = score.get('update_rate_ms')
    resolved['update_rate_ms'] = update_rate if type(update_rate) is int and 20 <= update_rate <= 10000 else 200
    raw_settings = score.get('settings')
    safe_settings = {}
    if isinstance(raw_settings, dict):
        for key, value in raw_settings.items():
            if key in ('wall_collision', 'powerups_enabled', 'fruit_types_enabled',
                       'enable_obstacles', 'enable_portals') and type(value) is bool:
                safe_settings[key] = value
            elif key in ('board_size', 'update_rate_ms', 'obstacle_count', 'portal_pairs') and type(value) is int:
                lower, upper = (20, 10000) if key == 'update_rate_ms' else ((0, 20) if key in ('obstacle_count', 'portal_pairs') else (5, 200))
                if lower <= value <= upper:
                    safe_settings[key] = value
    resolved['settings'] = safe_settings
    for field in ('daily_challenge_id', 'daily_challenge_version',
                  'daily_challenge_modifier'):
        resolved.pop(field, None)
    challenge_id = score.get('daily_challenge_id')
    challenge_version = score.get('daily_challenge_version')
    challenge_modifier = score.get('daily_challenge_modifier')
    challenge_match = (re.fullmatch(
        r'daily-v(?P<version>[12])-\d{4}-\d{2}-\d{2}', challenge_id)
        if isinstance(challenge_id, str) else None)
    if (challenge_match and type(challenge_version) is int and
            challenge_version == int(challenge_match.group('version')) and
            challenge_modifier in ('classic', 'wrap_walls', 'obstacles')):
        resolved['daily_challenge_id'] = challenge_id
        resolved['daily_challenge_version'] = challenge_version
        resolved['daily_challenge_modifier'] = challenge_modifier
    custom_challenge_id = score.get('custom_challenge_id')
    custom_challenge_version = score.get('custom_challenge_version')
    custom_challenge_match = (re.fullmatch(
        r'user-v(?P<version>[12])-[0-9a-f]{24}', custom_challenge_id)
        if isinstance(custom_challenge_id, str) else None)
    if (custom_challenge_match and type(custom_challenge_version) is int and
            custom_challenge_version == int(custom_challenge_match.group('version'))):
        resolved['custom_challenge_id'] = custom_challenge_id
        resolved['custom_challenge_version'] = custom_challenge_version
    custom_map = replay.get('custom_map')
    if custom_map is not None:
        if not isinstance(custom_map, dict):
            raise ValueError('Replay map data is malformed.')
        width, height = custom_map.get('board_width'), custom_map.get('board_height')
        obstacles = custom_map.get('obstacles', [])
        portals = custom_map.get('portals', [])
        if (type(width) is not int or type(height) is not int or not 5 <= width <= 200 or
                not 5 <= height <= 200 or not isinstance(obstacles, list) or len(obstacles) > 5000 or
                not all(_valid_cell(cell) and cell[0] < width and cell[1] < height and
                        cell[0] >= 0 and cell[1] >= 0 for cell in obstacles) or
                not isinstance(portals, list) or len(portals) > 100):
            raise ValueError('Replay map data is outside supported limits.')
        resolved['custom_map'] = custom_map
    resolved['replay_format_version'] = replay_version
    if resolved.get('is_multiplayer'):
        resolved['mp_history'] = events
    else:
        resolved['game_history'] = events
    resolved['has_replay'] = True
    resolved.pop('replay_id', None)
    return resolved


def _load_custom_maps():
    maps = {}
    root = _user_data_manager.get_maps_created_dir()
    try:
        for filename in os.listdir(root):
            if not filename.lower().endswith('.json'):
                continue
            try:
                with open(os.path.join(root, filename), 'r', encoding='utf-8') as map_file:
                    payload = json.load(map_file)
                name = payload.pop('name', None) if isinstance(payload, dict) else None
                if isinstance(name, str) and name:
                    maps[name] = payload
            except (OSError, ValueError, TypeError):
                continue
    except OSError:
        pass
    return maps


def _save_custom_map_file(name, payload):
    record = dict(payload)
    record['name'] = name
    path = _map_path(name)
    _atomic_write_json(path, record)
    with open(path, 'r', encoding='utf-8') as map_file:
        check = json.load(map_file)
    if check.get('name') != name:
        raise ValueError('Saved map failed validation')
    return path


def _delete_custom_map_file(name):
    try:
        os.remove(_map_path(name))
        return True
    except FileNotFoundError:
        return False


def all_profile_replay_ids(data=None):
    """Replay ids referenced by the high scores of EVERY local profile, not just the active one.
    All profiles share one replay folder, so "is this replay used?" must look at all of them: a
    brand-new profile has no scores at all, and judging by it alone made every other profile's
    replays look abandoned. Returns None when the saved data cannot be read, so callers can refuse
    to delete anything they cannot vouch for."""
    try:
        data = _load_data() if data is None else data
    except Exception:
        return None
    if not isinstance(data, dict):
        return None
    def ids_of(scores):
        return {s.get('replay_id') for s in (scores or []) if isinstance(s, dict) and s.get('replay_id')}
    ids = ids_of(data.get('highscores'))
    store = data.get(_LOCAL_PROFILES_KEY)
    profiles = store.get('profiles') if isinstance(store, dict) else None
    if isinstance(profiles, dict):
        for profile in profiles.values():
            profile_data = profile.get('data') if isinstance(profile, dict) else None
            if isinstance(profile_data, dict):
                ids |= ids_of(profile_data.get('highscores'))
    return ids


# The list of replays (Settings > Data > Replays) is read from disk ONCE and kept in memory. Nothing that happens in
# the game, such as a game ending (even many times a minute with the autopilot), reloads or rescans it: only the
# player does, with Recalculate or by running one of the replay tools. A game that ends only bumps a counter, so
# the page can say "N newer replays, press Recalculate" without touching the disk.
_REPLAY_LIST_CACHE = {'scan': None, 'built_at': None, 'new_since': 0}
_REPLAY_LIST_LOCK = threading.Lock()


def replay_list_cached(force=False):
    """The replay list, from memory. Reads the disk only the first time or when `force` (Recalculate) is set."""
    with _REPLAY_LIST_LOCK:
        if force or _REPLAY_LIST_CACHE['scan'] is None:
            _REPLAY_LIST_CACHE['scan'] = replay_storage_scan(referenced_ids=replay_storage_referenced_ids())
            _REPLAY_LIST_CACHE['built_at'] = time.time()
            _REPLAY_LIST_CACHE['new_since'] = 0
        return _REPLAY_LIST_CACHE['scan']


def replay_list_invalidate():
    """Forget the cached list; the next read (made when the player asks for it) walks the disk again."""
    replay_exists_memo_clear()
    with _REPLAY_LIST_LOCK:
        _REPLAY_LIST_CACHE['scan'] = None
        _REPLAY_LIST_CACHE['new_since'] = 0


def replay_list_note_new():
    """A replay was saved after the list was loaded. O(1): no disk access."""
    with _REPLAY_LIST_LOCK:
        if _REPLAY_LIST_CACHE['scan'] is not None:
            _REPLAY_LIST_CACHE['new_since'] += 1


def replay_list_info():
    with _REPLAY_LIST_LOCK:
        return {'loaded': _REPLAY_LIST_CACHE['scan'] is not None, 'built_at': _REPLAY_LIST_CACHE['built_at'],
                'new_since': _REPLAY_LIST_CACHE['new_since']}


_SCORE_DATA_CACHE = {'signature': None, 'path': None, 'data': None}


def _file_signature(path):
    """(modified time in ns, size) of a file, or None: changes whenever anything rewrites the file."""
    try:
        stat = os.stat(path)
        return (stat.st_mtime_ns, stat.st_size)
    except OSError:
        return None


def _prune_dropped_score_replays(ids_before, data):
    """After a score was added: set aside the replays of the scores that fell off the list, and only those.
    The data is already in memory, so no file is read and the replay folder is not listed; if no score was dropped
    (the usual case) it does nothing at all."""
    scores = data.get('highscores') if isinstance(data, dict) else None
    now_ids = {s.get('replay_id') for s in (scores or []) if isinstance(s, dict) and s.get('replay_id')}
    dropped = {i for i in (ids_before or ()) if i} - now_ids
    if not dropped:
        return 0
    everyone = all_profile_replay_ids(data)
    if everyone is None:
        return 0
    moved = 0
    for replay_id in dropped - everyone:
        for suffix in _REPLAY_SUFFIXES_BEST_FIRST:
            path = os.path.join(_user_data_manager.get_replay_dir(), 'replay_' + replay_id + suffix)
            if os.path.isfile(path):
                quarantine_replay_file(path)
                moved += 1
    return moved


def sweep_orphan_replays_async():
    """Once per run, in the background: set aside replays no score refers to (left by a crash, say). This used to
    run after every finished game."""
    def work():
        try:
            with _data_save_lock:
                _prune_score_replays((_load_data() or {}).get('highscores', []))
        except Exception as exc:
            _logging_mod.getLogger('sgf').warning('Orphan replay sweep failed: %s', exc)
    threading.Thread(target=work, name='replay-sweep', daemon=True).start()


def _prune_score_replays(highscores, delete=False):
    """Deal with replay files that no score of any profile refers to any more. By default they are
    moved to SGF Data/backups/orphan_replays (recoverable from Backups and Restore); only when the
    player has just deleted a score (delete=True) is its replay removed for good. Either way a replay
    that any profile still uses is kept, and if the saved data cannot be read nothing is touched."""
    referenced = {
        score.get('replay_id') for score in highscores
        if isinstance(score, dict) and score.get('replay_id')
    }
    everyone = all_profile_replay_ids()
    if everyone is None:
        return
    referenced |= everyone
    try:
        for filename in os.listdir(_user_data_manager.get_replay_dir()):
            split = _replay_split_name(filename)
            if split is None:
                continue
            replay_id, suffix = split
            if replay_id not in referenced:
                orphan = os.path.join(_user_data_manager.get_replay_dir(), filename)
                if delete:
                    try:
                        os.remove(orphan)
                    except OSError as exc:
                        _logging_mod.getLogger('sgf').warning('Could not remove replay %s: %s', filename, exc)
                else:
                    quarantine_replay_file(orphan)
    except OSError:
        pass


# ---------------------------------------------------------------------------
