def _replay_tool_label(language, key, **values):
    table = _REPLAY_TOOL_LABELS.get(language) or _REPLAY_TOOL_LABELS['en']
    text = table.get(key) or _REPLAY_TOOL_LABELS['en'].get(key, key)
    try:
        return text.format(**values) if values else text
    except (KeyError, IndexError, ValueError):
        return text


def _replay_display_name(replay_id):
    """'2026-10-08T15-18-21.725715_game' -> '08/10/2026 - 15:18:21.725715'."""
    stamp = str(replay_id).split('_', 1)[0]
    try:
        day, clock = stamp.split('T', 1)
        year, month, dom = day.split('-')
        hh, mm, rest = clock.split('-', 2)
        day_text = format_date(datetime(int(year), int(month), int(dom), int(hh), int(mm)))
        return f"{day_text} - {hh}:{mm}:{rest}"
    except (ValueError, AttributeError):
        return str(replay_id)


def replay_storage_scan(directory=None, referenced_ids=None):
    """List replay files. `referenced_ids` is the set of replay ids that high
    scores still point to, or None when that is unknown (then nothing is ever
    reported as removable)."""
    directory = directory or _user_data_manager.get_replay_dir()
    entries, by_id, extras = [], {}, []
    try:
        names = sorted(os.listdir(directory))
    except OSError:
        return {'replays': [], 'temp_files': [], 'duplicates': []}
    for name in names:
        full = os.path.join(directory, name)
        if not os.path.isfile(full) or os.path.islink(full):
            continue
        if name.endswith('.tmp') or name.endswith('.part'):
            extras.append({'path': full, 'size': os.path.getsize(full)})
            continue
        if not name.startswith('replay_'):
            continue
        split = _replay_split_name(name)
        if split is None:
            continue
        replay_id, split_suffix = split
        compressed = split_suffix != '.json'
        codec_rank = {'.json': 0, '.json.gz': 1, '.json.xz': 2}[split_suffix]
        try:
            stat = os.stat(full)
        except OSError:
            continue
        entry = {'id': replay_id, 'path': full, 'size': stat.st_size,
                 'mtime': stat.st_mtime, 'compressed': compressed, 'codec': _replay_codec_of_path(full),
                 '_rank': codec_rank,
                 'name': _replay_display_name(replay_id),
                 'referenced': (None if referenced_ids is None
                                else replay_id in referenced_ids)}
        if replay_id in by_id:
            # Several variants of one replay exist (.json, .json.gz, .json.xz): keep the most
            # compressed one as the replay, the other copies are redundant.
            first = by_id[replay_id]
            keep, drop = (entry, first) if entry['_rank'] > first['_rank'] else (first, entry)
            by_id[replay_id] = keep
            extras.append({'path': drop['path'], 'size': drop['size'], 'duplicate': True})
        else:
            by_id[replay_id] = entry
    entries = sorted(by_id.values(), key=lambda e: e['name'])
    return {'replays': entries,
            'temp_files': [e for e in extras if not e.get('duplicate')],
            'duplicates': [e for e in extras if e.get('duplicate')]}


def replay_storage_referenced_ids():
    """Replay ids still referenced by the high scores of any profile, or None if unreadable."""
    return all_profile_replay_ids()


def replay_storage_clean_candidates(scan):
    """Files Clean would remove: leftovers, redundant copies, orphaned replays."""
    items = [dict(item, reason='temp') for item in scan['temp_files']]
    items += [dict(item, reason='duplicate') for item in scan['duplicates']]
    items += [dict(entry, reason='orphan') for entry in scan['replays']
              if entry['referenced'] is False]
    return items


def replay_storage_estimate_clean(scan):
    items = replay_storage_clean_candidates(scan)
    return len(items), sum(item['size'] for item in items)


def replay_storage_clean(scan):
    """Delete the clean candidates. Returns (files_removed, bytes_freed)."""
    removed = freed = 0
    for item in replay_storage_clean_candidates(scan):
        try:
            os.remove(item['path'])
            removed += 1
            freed += item['size']
        except OSError as exc:
            _logging_mod.getLogger('sgf').warning('Clean could not remove %s: %s', item['path'], exc)
    return removed, freed


def replay_storage_delete(entries):
    """Delete the chosen replays. High scores keep their entry; they simply
    no longer have a replay (`_score_has_replay` checks the file)."""
    removed = freed = 0
    for entry in entries:
        base = _replay_base_path(entry['path'])
        for path in dict.fromkeys([entry['path']] + [base + suffix for suffix in _REPLAY_SUFFIXES_BEST_FIRST]):
            try:
                size = os.path.getsize(path)
                os.remove(path)
                removed += 1
                freed += size
            except OSError:
                pass
    return removed, freed


def _replay_read_payload(entry):
    with _replay_open_text(entry['path']) as handle:
        payload = json.load(handle)
    if not isinstance(payload, dict) or not isinstance(payload.get('events'), list):
        raise ValueError('Replay failed validation')
    return payload


class ReplayJobCancelled(Exception):
    """The player pressed Cancel while a replay tool was running."""


_REPLAY_STREAM_CHUNK = 1 << 20          # 1 MiB at a time: memory use does not depend on the size of the replay
_REPLAY_NORMALISE_MAX_BYTES = 32 * 1024 * 1024


def _replay_stream_writer(out_file, level, size_hint):
    """A writer that compresses what is written to it: level None = plain, an int = gzip, 'xz' = LZMA (strongest)."""
    if level is None:
        return out_file
    if level == 'xz':
        filters = [{'id': lzma.FILTER_LZMA2, 'preset': 9 | lzma.PRESET_EXTREME,
                    'dict_size': min(32 * 1024 * 1024, _replay_xz_dict_size(size_hint)), 'lc': 4, 'lp': 0, 'pb': 0}]
        return lzma.LZMAFile(out_file, 'wb', format=lzma.FORMAT_XZ, check=lzma.CHECK_CRC64, filters=filters)
    return gzip.GzipFile(fileobj=out_file, mode='wb', compresslevel=level, mtime=0)


def _replay_stream_reader(raw_file, path, codec='auto'):
    if codec == 'auto':
        codec = _replay_codec_of_path(path)
    if codec == 'xz':
        return lzma.LZMAFile(raw_file)
    if codec == 'gz':
        return gzip.GzipFile(fileobj=raw_file)
    return raw_file


def _replay_stream_transcode(src_path, dst_path, level, size_hint, progress=None, cancel=None):
    """Copy a replay into another compression, one megabyte at a time, without ever parsing it. Returns
    (sha256 of the uncompressed bytes, number of uncompressed bytes). `progress(fraction)` and `cancel()` are
    optional; cancelling raises ReplayJobCancelled and leaves the destination for the caller to remove."""
    total = max(1, os.path.getsize(src_path))
    digest, count = hashlib.sha256(), 0
    with open(src_path, 'rb') as raw_in:
        reader = _replay_stream_reader(raw_in, src_path)
        with open(dst_path, 'wb') as raw_out:
            writer = _replay_stream_writer(raw_out, level, size_hint)
            try:
                while True:
                    chunk = reader.read(_REPLAY_STREAM_CHUNK)
                    if not chunk:
                        break
                    if cancel is not None and cancel():
                        raise ReplayJobCancelled()
                    digest.update(chunk)
                    count += len(chunk)
                    writer.write(chunk)
                    if progress is not None:
                        progress(min(1.0, raw_in.tell() / total))
            finally:
                if writer is not raw_out:
                    writer.close()
            raw_out.flush()
            os.fsync(raw_out.fileno())
    return digest.hexdigest(), count


def _replay_stream_hash(path, codec='auto'):
    digest, count = hashlib.sha256(), 0
    with open(path, 'rb') as raw_in:
        reader = _replay_stream_reader(raw_in, path, codec)
        while True:
            chunk = reader.read(_REPLAY_STREAM_CHUNK)
            if not chunk:
                break
            digest.update(chunk)
            count += len(chunk)
    return digest.hexdigest(), count


def _replay_needs_normalising(path):
    """True if the file's layout is not the compact one this game writes (older indented files)."""
    try:
        with open(path, 'rb') as raw_in:
            head = _replay_stream_reader(raw_in, path).read(2048)
        return b'\n' in head or b'": ' in head
    except (OSError, EOFError, lzma.LZMAError):
        return False


def replay_storage_rewrite(entry, level, progress=None, cancel=None):
    """Re-save one replay with another compression. level=None keeps it as plain JSON, an int is gzip at that
    level and 'xz' is LZMA (the strongest, slowest).

    The replay is streamed through the new compressor a megabyte at a time (a long replay is far too big to parse
    into Python objects: that needs many times its size in memory). The new file is verified by reading it back and
    comparing its checksum with the original's; the original is only replaced when the result is not larger.
    Files in the old indented layout that are small enough are re-serialised compactly instead. Returns bytes
    saved (>= 0); raises ReplayJobCancelled if `cancel()` turns true."""
    codec = None if level is None else ('xz' if level == 'xz' else 'gz')
    new_path = _replay_base_path(entry['path']) + _REPLAY_CODEC_SUFFIX[codec]
    if entry['size'] <= _REPLAY_NORMALISE_MAX_BYTES and _replay_needs_normalising(entry['path']):
        payload = _replay_read_payload(entry)
        raw = json.dumps(payload, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
        data = _replay_compress_bytes(raw, level)
        if len(data) >= entry['size'] and (new_path == entry['path'] or level is not None):
            return 0
        _atomic_write_bytes(new_path, data)
        check_entry = dict(entry, path=new_path, compressed=level is not None, codec=codec)
        if len(_replay_read_payload(check_entry)['events']) != len(payload['events']):
            os.remove(new_path)
            raise ValueError('replay verification failed')
        if new_path != entry['path']:
            os.remove(entry['path'])
        return max(0, entry['size'] - len(data))
    hint = entry['size'] if not entry.get('compressed') else entry['size'] * 12
    temp = f'{new_path}.tmp-{os.getpid()}-{threading.get_ident()}'
    try:
        want_hash, want_count = _replay_stream_transcode(entry['path'], temp, level, hint, progress, cancel)
        new_size = os.path.getsize(temp)
        if new_size >= entry['size'] and (new_path == entry['path'] or level is not None):
            os.remove(temp)
            return 0
        got_hash, got_count = _replay_stream_hash(temp, codec)         # the temp name has no codec suffix: say which it is
        if got_hash != want_hash or got_count != want_count:
            raise ValueError('replay verification failed')
        os.replace(temp, new_path)
    except BaseException:
        try:
            if os.path.exists(temp):
                os.remove(temp)
        except OSError:
            pass
        raise
    if new_path != entry['path'] and os.path.exists(entry['path']):
        os.remove(entry['path'])
    return max(0, entry['size'] - new_size)


def lower_current_thread_priority():
    """Make the calling thread yield to everything else on the computer (a long compression must never make the
    rest of the system feel slow). Windows: below-normal thread priority; Linux: a higher nice value for this thread."""
    try:
        if os.name == 'nt':
            import ctypes
            kernel = ctypes.windll.kernel32
            return bool(kernel.SetThreadPriority(kernel.GetCurrentThread(), -1))
        os.setpriority(os.PRIO_PROCESS, threading.get_native_id(), 10)
        return True
    except Exception:
        return False


def training_power_enter():
    """A long training must not be slowed or interrupted by the computer saving power: on Windows, ask not to throttle this
    thread and process (the 'efficiency mode' Windows applies to minimised windows) and not to let the computer sleep while it
    runs. Best effort: returns which requests were accepted (all False elsewhere). Call training_power_leave() from the same
    thread when the training ends."""
    done = {'awake': False, 'thread_full_speed': False, 'process_full_speed': False}
    if os.name != 'nt':
        return done
    try:
        import ctypes
        kernel = ctypes.windll.kernel32
        done['awake'] = bool(kernel.SetThreadExecutionState(0x80000001))      # ES_CONTINUOUS | ES_SYSTEM_REQUIRED

        class _Throttle(ctypes.Structure):
            _fields_ = [('Version', ctypes.c_ulong), ('ControlMask', ctypes.c_ulong), ('StateMask', ctypes.c_ulong)]
        state = _Throttle(1, 1, 0)                                           # take control of execution-speed throttling and turn it off
        kernel.GetCurrentThread.restype = ctypes.c_void_p
        kernel.GetCurrentProcess.restype = ctypes.c_void_p
        for name, handle, info_class in (('thread_full_speed', kernel.GetCurrentThread(), 3), ('process_full_speed', kernel.GetCurrentProcess(), 4)):
            setter = getattr(kernel, 'SetThreadInformation' if name.startswith('thread') else 'SetProcessInformation')
            setter.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p, ctypes.c_ulong]
            setter.restype = ctypes.c_int
            done[name] = bool(setter(handle, info_class, ctypes.byref(state), ctypes.sizeof(state)))
    except Exception:
        pass
    return done


def training_power_leave():
    if os.name != 'nt':
        return False
    try:
        import ctypes
        return bool(ctypes.windll.kernel32.SetThreadExecutionState(0x80000000))   # ES_CONTINUOUS alone: back to normal
    except Exception:
        return False


def _replay_read_prefix(entry, nbytes):
    """The first `nbytes` of a replay's uncompressed text, read as a stream (never the whole file)."""
    with open(entry['path'], 'rb') as raw_in:
        return _replay_stream_reader(raw_in, entry['path']).read(nbytes)


def replay_storage_estimate_compress(scan, profile='balanced', sample=2, sample_bytes=512 * 1024, budget_seconds=3.0):
    """Estimated bytes saved by Compress (a '~' value). It compresses only the first half megabyte of a couple of
    the smallest replays with the chosen profile and scales that ratio to every replay, so its cost does not depend
    on how long the replays are. Replays already in the same or a stronger format are counted as saving nothing."""
    level = REPLAY_COMPRESSION_PROFILES.get(profile, 6)
    entries = [e for e in scan['replays'] if e['size'] > 0]
    rank = {None: 0, 'gz': 1, 'xz': 2}
    target_rank = rank[None if level is None else ('xz' if level == 'xz' else 'gz')]
    candidates = [e for e in entries if rank.get(e.get('codec'), 0) < target_rank
                  or (e.get('codec') == 'gz' and level not in (None, 'xz') and level > 6)]
    if not candidates:
        return 0
    started = time.monotonic()
    ratios = []
    for entry in sorted(candidates, key=lambda e: e['size'])[:max(1, sample)]:
        if ratios and time.monotonic() - started > budget_seconds:
            break
        try:
            head = _replay_read_prefix(entry, sample_bytes)
            if not head:
                continue
            new_ratio = len(_replay_compress_bytes(head, level)) / float(len(head))
            old_ratio = 1.0 if not entry.get('compressed') else len(_replay_compress_bytes(head, 6)) / float(len(head))
            ratios.append(max(0.0, 1.0 - new_ratio / max(old_ratio, 1e-9)))
        except Exception:
            continue
    if not ratios:
        return 0
    gain = sum(ratios) / len(ratios)
    return int(sum(e['size'] for e in candidates) * gain)


def replay_storage_compress(entries, profile='balanced', progress=None, file_progress=None, cancel=None):
    """Compress/recompress replays (also normalises their layout). Returns
    {'saved': bytes, 'done': n, 'errors': n, 'cancelled': bool}. Safe to run in a worker."""
    level = REPLAY_COMPRESSION_PROFILES.get(profile, 6)
    result = {'saved': 0, 'done': 0, 'errors': 0, 'cancelled': False}
    for index, entry in enumerate(entries):
        if cancel is not None and cancel():
            result['cancelled'] = True
            break
        try:
            result['saved'] += replay_storage_rewrite(entry, level, file_progress, cancel)
            result['done'] += 1
        except ReplayJobCancelled:
            result['cancelled'] = True
            break
        except Exception as exc:
            result['errors'] += 1
            _logging_mod.getLogger('sgf').warning('Replay compress failed for %s: %s', entry['id'], exc)
        if progress:
            progress(index + 1, len(entries))
    return result


def replay_storage_organize(entries, progress=None):
    """Compact each replay's layout without changing its compression state."""
    result = {'saved': 0, 'done': 0, 'errors': 0}
    for index, entry in enumerate(entries):
        try:
            if _replay_needs_normalising(entry['path']):      # a compact file has nothing to organise: no pass over it
                result['saved'] += replay_storage_rewrite(entry, {'xz': 'xz', 'gz': 6}.get(_replay_codec_of_path(entry['path'])))
            result['done'] += 1
        except Exception as exc:
            result['errors'] += 1
            _logging_mod.getLogger('sgf').warning('Replay organise failed for %s: %s', entry['id'], exc)
        if progress:
            progress(index + 1, len(entries))
    return result


def _content_migration_journal_path():
    return os.path.join(_user_data_manager.get_config_dir(), '.content_migration_journal.json')


def _verify_extracted_content(extracted_replays, extracted_maps):
    """Check, before any original is dropped, that every file the migration wrote reads back as it should.

    `extracted_replays` maps a replay id to the number of events it must hold; `extracted_maps` is a list
    of map names. Raises ValueError naming the first problem. Nothing is deleted or changed here."""
    for replay_id, expected_events in extracted_replays.items():
        payload = _load_replay_file(replay_id)
        if payload is None:
            raise ValueError(f'Extracted replay {replay_id} cannot be read back')
        if len(payload['events']) != expected_events:
            raise ValueError(f'Extracted replay {replay_id} has {len(payload["events"])} events, expected {expected_events}')
    if extracted_maps:
        saved = _load_custom_maps()
        for name in extracted_maps:
            if name not in saved:
                raise ValueError(f'Extracted map {name!r} cannot be read back')


def _migrate_embedded_content(data):
    """Move legacy embedded replays and user maps to their own files.

    Source data is retained unless every extracted file validates, a backup is
    written, and the reduced JSON commits atomically. The migration is safe to
    retry after interruption because each destination has a stable identifier.
    """
    if not isinstance(data, dict):
        return data
    marker = os.path.join(_user_data_manager.get_config_dir(), '.content_files_migrated')
    if os.path.exists(marker):
        return _upgrade_content_schema(data)

    with _content_migration_lock:
        if os.path.exists(marker):
            return _upgrade_content_schema(data)
        updated = copy.deepcopy(data)
        changed = False
        backup_path = None
        commit_started = False
        extracted_replays = {}
        extracted_maps = []
        journal_path = _content_migration_journal_path()
        if os.path.exists(journal_path):
            _logging_mod.getLogger('sgf').warning(
                'A previous content migration did not finish; running it again (every step can be repeated safely)')
        try:
            highscores = updated.get('highscores', [])
            if isinstance(highscores, list):
                for index, score in enumerate(highscores):
                    if not isinstance(score, dict):
                        continue
                    history = score.get('game_history')
                    if not isinstance(history, list) or not history:
                        history = score.get('mp_history')
                    if isinstance(history, list) and history:
                        replay_id = _score_replay_id(score, 'legacy-' + hashlib.sha256(
                            f'{index}:{score.get("date", "")}'.encode('utf-8')).hexdigest()[:20])
                        _save_replay_file(replay_id, _score_replay_payload(score, history))
                        extracted_replays[replay_id] = len(history)
                        score['replay_id'] = replay_id
                        score['has_replay'] = True
                        changed = True
                    else:
                        if 'game_history' in score or 'mp_history' in score:
                            score['has_replay'] = False
                            changed = True
                    if 'game_history' in score or 'mp_history' in score:
                        score.pop('game_history', None)
                        score.pop('mp_history', None)
                        changed = True
                    if 'custom_map' in score:
                        # A score without a replay cannot use this snapshot;
                        # custom maps themselves are stored in maps/created.
                        score.pop('custom_map', None)
                        changed = True

            legacy_maps = updated.get('custom_maps', {})
            if isinstance(legacy_maps, dict):
                saved_maps = _load_custom_maps()
                for name, payload in legacy_maps.items():
                    if not isinstance(name, str) or not isinstance(payload, dict):
                        raise ValueError('Legacy map record is invalid')
                    if name not in saved_maps:
                        _save_custom_map_file(name, payload)
                        extracted_maps.append(name)
                updated.pop('custom_maps', None)
                if 'custom_maps' in data:
                    changed = True

            if os.path.isfile(_DATA_FILE) and updated.get(_SCHEMA_VERSION_KEY, 1) < SAVE_FORMAT_VERSION:
                updated[_SCHEMA_VERSION_KEY] = SAVE_FORMAT_VERSION
                updated['save_format_version'] = SAVE_FORMAT_VERSION
                changed = True

            if changed:
                # Every extracted file must read back correctly BEFORE the originals are dropped from the JSON.
                _verify_extracted_content(extracted_replays, extracted_maps)
                _atomic_write_json(journal_path, {
                    'state': 'committing', 'started_at': datetime.now().isoformat(timespec='seconds'),
                    'replays': sorted(extracted_replays), 'maps': list(extracted_maps)})
                source = _DATA_FILE
                if os.path.isfile(source):
                    backup_root = _user_data_manager.get_backup_dir()
                    stamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
                    backup_path = os.path.join(backup_root, f'pre_content_split_{stamp}.json')
                    import shutil as _shutil
                    _shutil.copy2(source, backup_path)
                    with open(backup_path, 'r', encoding='utf-8') as backup_file:
                        if not isinstance(json.load(backup_file), dict):
                            raise ValueError('Content migration backup failed validation')
                commit_started = True
                _atomic_write_json(_DATA_FILE, updated)
                with open(_DATA_FILE, 'r', encoding='utf-8') as verify_file:
                    verified = json.load(verify_file)
                if not isinstance(verified, dict):
                    raise ValueError('Migrated data did not validate')
                if any(isinstance(s, dict) and ('game_history' in s or 'mp_history' in s)
                       for s in verified.get('highscores', [])):
                    raise ValueError('Replay migration left inline histories behind')
                if 'custom_maps' in verified:
                    raise ValueError('Map migration left inline maps behind')
                data = verified

            os.makedirs(os.path.dirname(marker), exist_ok=True)
            with open(marker, 'w', encoding='utf-8') as marker_file:
                marker_file.write(datetime.now().isoformat())
            try:
                os.remove(journal_path)                  # finished: nothing to recover
            except OSError:
                pass
        except Exception as exc:
            if commit_started and backup_path and os.path.isfile(backup_path):
                try:
                    with open(backup_path, 'r', encoding='utf-8') as backup_file:
                        original = json.load(backup_file)
                    _atomic_write_json(_DATA_FILE, original)
                except Exception as restore_exc:
                    _logging_mod.getLogger('sgf').critical('Could not restore pre-migration JSON from backup: %s', restore_exc)
            _logging_mod.getLogger('sgf').exception('Embedded content migration deferred: %s', exc)
    return data


def _upgrade_content_schema(data):
    """Record the separated-content schema after its one-time migration."""
    if not isinstance(data, dict) or data.get(_SCHEMA_VERSION_KEY, 1) >= SAVE_FORMAT_VERSION:
        return data
    if not os.path.isfile(_DATA_FILE):
        return data
    backup_path = None
    try:
        updated = copy.deepcopy(data)
        updated[_SCHEMA_VERSION_KEY] = SAVE_FORMAT_VERSION
        updated['save_format_version'] = SAVE_FORMAT_VERSION
        backup_root = _user_data_manager.get_backup_dir()
        stamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
        backup_path = os.path.join(backup_root, f'pre_schema_upgrade_{stamp}.json')
        import shutil as _shutil
        _shutil.copy2(_DATA_FILE, backup_path)
        with open(backup_path, 'r', encoding='utf-8') as backup_file:
            if not isinstance(json.load(backup_file), dict):
                raise ValueError('Schema-upgrade backup failed validation')
        _atomic_write_json(_DATA_FILE, updated)
        with open(_DATA_FILE, 'r', encoding='utf-8') as upgraded_file:
            verified = json.load(upgraded_file)
        if verified.get(_SCHEMA_VERSION_KEY) != SAVE_FORMAT_VERSION:
            raise ValueError('Schema upgrade failed validation')
        return verified
    except Exception as exc:
        if backup_path and os.path.isfile(backup_path):
            try:
                with open(backup_path, 'r', encoding='utf-8') as backup_file:
                    original = json.load(backup_file)
                _atomic_write_json(_DATA_FILE, original)
            except Exception as restore_exc:
                _logging_mod.getLogger('sgf').critical('Could not restore schema-upgrade backup: %s', restore_exc)
        _logging_mod.getLogger('sgf').exception('Content schema upgrade deferred: %s', exc)
        return data

def _replace_with_retry(tmp_path, path, attempts=3, delay=0.05):
    """os.replace() that retries a few times when the destination is briefly held by a sync client or
    antivirus (PermissionError on Windows, e.g. OneDrive/Dropbox). Any other error, and a PermissionError
    that outlasts the attempts, goes back to the caller with the destination untouched."""
    for attempt in range(max(1, attempts)):
        try:
            os.replace(tmp_path, path)
            return
        except PermissionError:
            if attempt + 1 >= attempts:
                raise
            time.sleep(delay)


def _atomic_write_json(path, data):
    """Write JSON to `path` without ever leaving a half-written file behind.

    Writes to a temp file in the same directory first (UTF-8), flushes it to disk, re-reads it to check it
    parses back, then uses os.replace() to atomically swap it into place (retrying briefly if the
    destination is locked by a sync client). os.replace() on the same filesystem is atomic at the OS level:
    a process that crashes, loses power, or gets force-killed mid-write will find either the old complete
    file or the new complete file next time it starts, never a truncated/corrupt one. Without this, a crash
    during the plain open(...)+write could zero out or truncate snake_game_data.json, silently wiping every
    saved score, achievement, and setting at once."""
    directory = os.path.dirname(os.path.abspath(path)) or '.'
    # json.dumps without indent uses the C encoder (about twice as fast, far less time holding the interpreter);
    # small files stay indented so they remain easy for a person to read.
    raw = json.dumps(data, separators=(',', ':')).encode('utf-8')
    if len(raw) < 262144:
        raw = json.dumps(data, indent=2).encode('utf-8')
    fd, tmp_path = tempfile.mkstemp(prefix='.snake_data_', suffix='.tmp', dir=directory)
    try:
        with os.fdopen(fd, 'wb') as _f:
            _f.write(raw)
            _f.flush()
            os.fsync(_f.fileno())
        with open(tmp_path, 'rb') as _check:
            if _check.read() != raw:                # never promote a file that is not exactly what we serialised
                raise OSError('the temporary data file does not match what was written')
        _replace_with_retry(tmp_path, path)
    except Exception:
        try:
            os.remove(tmp_path)
        except OSError:
            pass
        raise


def _atomic_write_bytes(path, payload):
    """Atomically replace a binary artifact such as a compressed replay."""
    directory = os.path.dirname(os.path.abspath(path)) or '.'
    os.makedirs(directory, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(prefix='.sgf_artifact_', suffix='.tmp', dir=directory)
    try:
        with os.fdopen(fd, 'wb') as artifact_file:
            artifact_file.write(payload)
            artifact_file.flush()
            os.fsync(artifact_file.fileno())
        _replace_with_retry(tmp_path, path)
    except Exception:
        try:
            os.remove(tmp_path)
        except OSError:
            pass
        raise

def _save_data(data):
    """Write the unified game data JSON (synchronous — use this for saves
    that must complete before continuing, e.g. right before the app exits).
    Shares a lock with _save_data_async so a synchronous save can never be
    clobbered by a slower background save landing right after it."""
    if _data_save_lock.held_by_current_thread():       # a read-modify-write that already holds the lock calls this to finish
        return _save_data_unlocked(data)
    with _data_save_lock:
        return _save_data_unlocked(data)


def _save_data_unlocked(data):
    if game_data_saving_blocked():
        # The file could not be read when it was last loaded; writing now could replace real progress.
        _logging_mod.getLogger('sgf').error('Save skipped: game_data.json could not be read (%s)', _DATA_LOAD_STATE.get('reason'))
        return False
    try:
        _atomic_write_json(_DATA_FILE, data)
        return True
    except Exception as _e:
        print(f"Error saving data: {_e}")
        return False

def _save_data_async(mutate_fn):
    """Apply mutate_fn(data) -> data to the unified game data on a
    background thread.

    Use this for saves that happen mid-gameplay (like an achievement
    unlocking) where the caller can't afford to block the main loop: the
    unified file contains metadata and progression, while replay histories
    are written to their own files. The background write still keeps
    progression updates from blocking the gameplay loop.

    mutate_fn receives the *freshest* on-disk data (re-read at the moment
    the background thread actually runs, under the lock) rather than a
    snapshot captured back when the save was queued — otherwise a slow
    background write could finish after a newer synchronous write and
    silently clobber it with stale data (e.g. wiping out a high score that
    was saved a moment after an achievement unlock queued this write).
    """
    completed = threading.Event()
    with _async_data_writes_lock:
        _async_data_writes.add(completed)

    def _write():
        with _data_save_lock:
            try:
                data = _load_data()
                if game_data_saving_blocked():
                    _logging_mod.getLogger('sgf').error('Background save skipped: game_data.json could not be read')
                    return
                data = mutate_fn(data)
                _atomic_write_json(_DATA_FILE, data)
            except Exception as _e:
                print(f"Error saving data (async): {_e}")
                _logging_mod.getLogger('sgf').exception('Background data save failed')
            finally:
                completed.set()
                with _async_data_writes_lock:
                    _async_data_writes.discard(completed)
    try:
        threading.Thread(target=_write, daemon=True).start()
    except Exception:
        completed.set()
        with _async_data_writes_lock:
            _async_data_writes.discard(completed)


def _flush_async_data_writes(timeout=5.0):
    deadline = time.monotonic() + max(0.0, float(timeout))
    while True:
        with _async_data_writes_lock:
            pending = tuple(_async_data_writes)
        with _replay_save_jobs_lock:
            pending += tuple(
                job['done'] for job in _replay_save_jobs.values()
                if not job['done'].is_set())
        if not pending:
            return True
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            return False
        pending[0].wait(min(remaining, 0.1))


_EXIT_SAVE_WAIT_SECONDS = 8.0


def _flush_pending_saves_on_exit(timeout=None):
    """Give background saves (scores, replays, achievements) time to finish before the program ends.

    The writer threads are daemons, so without this a quit right after a game could end the process in the
    middle of a write. Every way out of the game (window close, sys.exit(), Quit in a menu) ends in a normal
    interpreter exit, which runs this. Returns True if nothing was left pending. If something is still
    running when the wait ends it is logged; an unfinished replay is still on disk as a recovery journal
    and is rebuilt at the next start."""
    wait = _EXIT_SAVE_WAIT_SECONDS if timeout is None else timeout
    try:
        finished = _flush_async_data_writes(timeout=wait)
        if not finished:
            with _async_data_writes_lock:
                data_writes = len(_async_data_writes)
            with _replay_save_jobs_lock:
                replay_jobs = sum(1 for job in _replay_save_jobs.values() if not job['done'].is_set())
            _logging_mod.getLogger('sgf').warning(
                'Quit with saves still running after %.0f s (%d data, %d replay)', wait, data_writes, replay_jobs)
        return finished
    except Exception as exc:                      # never let the exit hook itself raise
        try:
            _logging_mod.getLogger('sgf').error('Could not wait for pending saves: %s', exc)
        except Exception:
            pass
        return False


atexit.register(_flush_pending_saves_on_exit)


# Local profiles keep each player's settings and progress isolated while the
# existing unified JSON remains the single source of truth on disk.
_LOCAL_PROFILES_KEY = 'local_profiles'
_PROFILE_DATA_KEYS = ('settings', 'highscores', 'achievements', 'player_name', 'progression', 'encyclopedia_progress', 'lan_leaderboard')
_LOCAL_PROFILE_SCHEMA = 1


def _profile_snapshot(data):
    return {key: copy.deepcopy(data[key]) for key in _PROFILE_DATA_KEYS if key in data}


def _sync_active_profile_snapshot(data):
    if not isinstance(data, dict):
        return
    store = data.get(_LOCAL_PROFILES_KEY)
    if not isinstance(store, dict) or not isinstance(store.get('profiles'), dict):
        return
    active_id = store.get('active_id')
    profile = store['profiles'].get(active_id)
    if isinstance(profile, dict):
        profile['data'] = _profile_snapshot(data)
        profile['updated_at'] = datetime.now().isoformat(timespec='seconds')


def _clean_local_profile_name(value):
    if not isinstance(value, str):
        raise ValueError('Profile name must be text')
    name = ''.join(ch for ch in value if ch.isprintable()).strip()
    name = ' '.join(name.split())
    if not name:
        raise ValueError('Profile name cannot be empty')
    if len(name) > 24:
        raise ValueError('Profile name must be 24 characters or fewer')
    return name


def _ensure_local_profile_store(data):
    """Add a profile index around existing top-level player data once."""
    if not isinstance(data, dict):
        data = {}
    store = data.get(_LOCAL_PROFILES_KEY)
    if isinstance(store, dict) and isinstance(store.get('profiles'), dict) and store['profiles']:
        profiles = store['profiles']
        valid = {}
        for profile_id, profile in profiles.items():
            if (isinstance(profile_id, str) and profile_id and len(profile_id) <= 64
                    and isinstance(profile, dict) and isinstance(profile.get('data'), dict)):
                try:
                    profile_name = _clean_local_profile_name(profile.get('name', ''))
                except ValueError:
                    continue
                valid[profile_id] = {
                    'id': profile_id, 'name': profile_name,
                    'created_at': str(profile.get('created_at', ''))[:64],
                    'updated_at': str(profile.get('updated_at', ''))[:64],
                    'data': {k: copy.deepcopy(v) for k, v in profile['data'].items()
                             if k in _PROFILE_DATA_KEYS},
                }
        if valid:
            changed = len(valid) != len(profiles)
            store['profiles'] = valid
            active_id = store.get('active_id')
            if active_id not in valid:
                active_id = next(iter(valid))
                # The top-level payload still belongs to an invalid/deleted
                # profile. Restore the valid target snapshot before the next
                # save can associate that payload with the wrong player.
                for key in _PROFILE_DATA_KEYS:
                    data.pop(key, None)
                data.update(copy.deepcopy(valid[active_id]['data']))
                changed = True
            store.update({'schema_version': _LOCAL_PROFILE_SCHEMA, 'active_id': active_id})
            data[_LOCAL_PROFILES_KEY] = store
            return data, store, changed

    existing_name = data.get('player_name')
    try:
        default_name = _clean_local_profile_name(existing_name) if existing_name else 'Player 1'
    except ValueError:
        default_name = 'Player 1'
    now = datetime.now().isoformat(timespec='seconds')
    profile_id = 'default'
    profile_data = _profile_snapshot(data)
    profile_data['player_name'] = profile_data.get('player_name') or default_name
    store = {
        'schema_version': _LOCAL_PROFILE_SCHEMA,
        'active_id': profile_id,
        'profiles': {profile_id: {
            'id': profile_id, 'name': default_name,
            'created_at': now, 'updated_at': now, 'data': profile_data,
        }},
    }
    data[_LOCAL_PROFILES_KEY] = store
    return data, store, True


def initialize_local_profiles():
    """Migrate current single-player data into the local profile index."""
    global ACTIVE_PROFILE_NAME
    data, store, changed = _ensure_local_profile_store(_load_data())
    if SAFE_MODE:
        return list_local_profiles(data)
    requested = str(_CLI_PROFILE_REQUEST or '').strip()
    requested_id = next((pid for pid, profile in store['profiles'].items()
                         if pid == requested or profile['name'].casefold() == requested.casefold()), None) if requested else None
    if requested_id and requested_id != store['active_id']:
        _switch_profile_in_data(data, store, requested_id)
        changed = True
    ACTIVE_PROFILE_NAME = store['active_id']
    if changed:
        _save_data(data)
    return list_local_profiles(data)


def list_local_profiles(data=None):
    if data is None:
        data = _load_data()
    data, store, _changed = _ensure_local_profile_store(data)
    active_id = store['active_id']
    return [
        {'id': pid, 'name': p['name'], 'active': pid == active_id,
         'created_at': p['created_at']}
        for pid, p in store['profiles'].items()
    ]


def _switch_profile_in_data(data, store, profile_id):
    _sync_active_profile_snapshot(data)
    target = store['profiles'][profile_id]
    for key in _PROFILE_DATA_KEYS:
        data.pop(key, None)
    data.update(copy.deepcopy(target['data']))
    data[_LOCAL_PROFILES_KEY] = store
    store['active_id'] = profile_id
    return data


def switch_local_profile(profile_id):
    global ACTIVE_PROFILE_NAME
    if SAFE_MODE:
        return False, 'Profiles cannot be changed in Safe Mode'
    if not _flush_async_data_writes():
        return False, 'Profile data is still being saved; try again shortly'
    with _data_save_lock:
        data, store, changed = _ensure_local_profile_store(_load_data())
        if profile_id not in store['profiles']:
            return False, 'Profile not found'
        _switch_profile_in_data(data, store, profile_id)
        _sync_active_profile_snapshot(data)
        try:
            _atomic_write_json(_DATA_FILE, data)
            ACTIVE_PROFILE_NAME = profile_id
            return True, None
        except Exception as exc:
            return False, type(exc).__name__


def create_local_profile(name):
    global ACTIVE_PROFILE_NAME
    if SAFE_MODE:
        return None, 'Profiles cannot be created in Safe Mode'
    try:
        name = _clean_local_profile_name(name)
    except ValueError as exc:
        return None, str(exc)
    if not _flush_async_data_writes():
        return None, 'Profile data is still being saved; try again shortly'
    with _data_save_lock:
        data, store, _changed = _ensure_local_profile_store(_load_data())
        if len(store['profiles']) >= 32:
            return None, 'The maximum of 32 local profiles has been reached'
        if any(p['name'].casefold() == name.casefold() for p in store['profiles'].values()):
            return None, 'A profile with that name already exists'
        profile_id = _secrets_mod.token_hex(8)
        now = datetime.now().isoformat(timespec='seconds')
        current_settings = copy.deepcopy(data.get('settings', {}))
        profile_data = {
            'settings': current_settings if isinstance(current_settings, dict) else {},
            'highscores': [], 'achievements': {},
            'player_name': name,
            'progression': {
                'schema_version': PROGRESSION_SCHEMA_VERSION,
                'xp_total': 0, 'games_completed': 0, 'highest_score': 0,
                'total_fruits': 0, 'total_portal_uses': 0, 'wins': 0,
                'best_combo': 0, 'unlocked_skins': ['classic'],
                'selected_skin': 'classic', 'recent_award_ids': [],
            },
        }
        store['profiles'][profile_id] = {
            'id': profile_id, 'name': name, 'created_at': now,
            'updated_at': now, 'data': profile_data,
        }
        _switch_profile_in_data(data, store, profile_id)
        try:
            _atomic_write_json(_DATA_FILE, data)
            ACTIVE_PROFILE_NAME = profile_id
            return profile_id, None
        except Exception as exc:
            del store['profiles'][profile_id]
            return None, type(exc).__name__


def rename_local_profile(profile_id, name):
    if SAFE_MODE:
        return False, 'Profiles cannot be renamed in Safe Mode'
    try:
        name = _clean_local_profile_name(name)
    except ValueError as exc:
        return False, str(exc)
    if not _flush_async_data_writes():
        return False, 'Profile data is still being saved; try again shortly'
    with _data_save_lock:
        data, store, _changed = _ensure_local_profile_store(_load_data())
        profile = store['profiles'].get(profile_id)
        if profile is None:
            return False, 'Profile not found'
        if any(pid != profile_id and p['name'].casefold() == name.casefold()
               for pid, p in store['profiles'].items()):
            return False, 'A profile with that name already exists'
        profile['name'] = name
        profile_data = profile.get('data')
        if isinstance(profile_data, dict):
            profile_data['player_name'] = name
        if store['active_id'] == profile_id:
            data['player_name'] = name
        _sync_active_profile_snapshot(data)
        try:
            _atomic_write_json(_DATA_FILE, data)
            return True, None
        except Exception as exc:
            return False, type(exc).__name__


PROGRESSION_SCHEMA_VERSION = 1
_SKIN_LEVEL_UNLOCKS = {'classic': 1, 'neon': 3, 'rainbow': 5, 'camouflage': 10}


def _progression_level_for_xp(total_xp):
    """Return (level, progress within level, XP needed for next level)."""
    try:
        remaining = max(0, min(1_000_000_000, int(total_xp)))
    except (TypeError, ValueError, OverflowError):
        remaining = 0
    level = 1
    needed = 100
    while remaining >= needed:
        remaining -= needed
        level += 1
        needed = 100 + (level - 1) * 25
    return level, remaining, needed


def _normalize_recent_matches(records):
    """Keep a bounded, non-sensitive summary of completed local matches."""
    if not isinstance(records, list):
        return []
    clean = []
    seen = set()
    for record in reversed(records[-200:]):
        if not isinstance(record, dict):
            continue
        match_id = record.get('id')
        stamp = record.get('timestamp')
        outcome = record.get('outcome')
        if any(type(record.get(key)) is not int
               for key in ('score', 'snake_length', 'combo') if key in record):
            continue
        try:
            score = int(record.get('score'))
            length = int(record.get('snake_length', 0))
            combo = int(record.get('combo', 0))
        except (TypeError, ValueError, OverflowError):
            continue
        if (not isinstance(match_id, str) or not re.fullmatch(r'[0-9a-f]{32}', match_id)
                or match_id in seen or not isinstance(stamp, str)
                or len(stamp) > 40 or outcome not in ('win', 'loss', 'draw')
                or not 0 <= score <= 1_000_000
                or not 0 <= length <= 100_000 or not 0 <= combo <= 1_000_000):
            continue
        try:
            datetime.fromisoformat(stamp)
        except ValueError:
            continue
        mode = record.get('mode', 'singleplayer')
        if not isinstance(mode, str):
            mode = 'singleplayer'
        clean.append({
            'id': match_id, 'timestamp': stamp, 'score': score,
            'outcome': outcome, 'mode': mode[:32],
            'snake_length': length, 'combo': combo,
        })
        seen.add(match_id)
        if len(clean) >= 50:
            break
    return list(reversed(clean))


def _safe_stat_int(value, maximum=1_000_000_000, minimum=0):
    """A statistic as a whole number inside [minimum, maximum]; anything unusable counts as `minimum`.

    Accepts ints, finite floats and numeric strings. Rejects booleans (True is not "1 game"), None, NaN,
    infinity and text, and clamps huge values, so old or hand-edited saves can never raise or skew a ratio."""
    if isinstance(value, bool) or value is None:
        return minimum
    try:
        if isinstance(value, float) and not math.isfinite(value):
            return minimum
        number = int(value)
    except (TypeError, ValueError, OverflowError):
        return minimum
    return max(minimum, min(maximum, number))


def _win_rate_percent(wins, games):
    """Whole-number win percentage, 0 to 100. Zero games (or more wins than games) never raises or exceeds 100."""
    games = _safe_stat_int(games)
    if games <= 0:
        return 0
    wins = min(_safe_stat_int(wins), games)
    return int(round(100 * wins / games))


def _load_progression_summary():
    try:
        raw = _load_data().get('progression', {})
        raw = raw if isinstance(raw, dict) else {}
    except Exception:
        raw = {}
    xp_total = _safe_stat_int(raw.get('xp_total', 0))
    level, level_xp, next_level_xp = _progression_level_for_xp(xp_total)
    unlocked = [skin for skin, required_level in _SKIN_LEVEL_UNLOCKS.items()
                if level >= required_level]
    def _counter(key):
        return _safe_stat_int(raw.get(key, 0))
    def _duration_counter(key, limit):
        value = raw.get(key, 0)
        if type(value) is not int:
            return 0
        return max(0, min(limit, value))
    selected = raw.get('selected_skin', 'classic')
    if not isinstance(selected, str) or selected not in unlocked:
        selected = 'classic'
    games_completed = _counter('games_completed')
    wins = _counter('wins')
    return {
        'schema_version': PROGRESSION_SCHEMA_VERSION,
        'xp_total': xp_total,
        'level': level,
        'level_xp': level_xp,
        'next_level_xp': next_level_xp,
        'games_completed': games_completed,
        'win_rate_percent': _win_rate_percent(wins, games_completed),
        'highest_score': _counter('highest_score'),
        'total_score': _counter('total_score'),
        'longest_snake': min(100_000, _counter('longest_snake')),
        'total_fruits': _counter('total_fruits'),
        'total_portal_uses': _counter('total_portal_uses'),
        'total_play_time_ms': _duration_counter(
            'total_play_time_ms', 1_000_000_000_000_000),
        'longest_survival_ms': _duration_counter(
            'longest_survival_ms', 7 * 24 * 60 * 60 * 1000),
        'wins': wins,
        'losses': _counter('losses'),
        'best_combo': _counter('best_combo'),
        'recent_matches': _normalize_recent_matches(raw.get('recent_matches', [])),
        'settings_changed': sorted({
            item for item in raw.get('settings_changed', [])
            if isinstance(item, str) and item in {
                'update_rate_ms', 'board_size', 'snake_color', 'language', 'wall_collision',
                'powerups_enabled', 'enable_obstacles', 'fruit_types_enabled',
                'enable_portals', 'master_volume', 'sfx_volume', 'bgm_volume',
                'sfx_enabled', 'bgm_enabled', 'map_theme',
                'reduced_motion', 'colorblind_cues', 'high_contrast', 'ui_scale_percent',
                'control_bindings',
            }
        }) if isinstance(raw.get('settings_changed', []), list) else [],
        'unique_fruits_collected': sorted({
            item[:32] for item in raw.get('unique_fruits_collected', [])
            if isinstance(item, str) and item
        }) if isinstance(raw.get('unique_fruits_collected', []), list) else [],
        'unlocked_skins': unlocked,
        'selected_skin': selected,
    }


def _clear_game_xp_award(game):
    """Allow the same reusable game object to earn XP in its next match."""
    state = getattr(game, '__dict__', None)
    if isinstance(state, dict):
        state.pop('_sgf_xp_award_id', None)
        state.pop('_sgf_xp_award_result', None)


def _track_game_fruit(game, fruit_type):
    """Track fruit categories eaten by the human player in this match."""
    if game is None:
        return
    fruit_type = str(fruit_type or 'regular').strip().lower()[:32] or 'regular'
    try:
        game.fruits_eaten = max(0, int(getattr(game, 'fruits_eaten', 0))) + 1
    except (TypeError, ValueError, OverflowError, AttributeError):
        pass
    try:
        collected = getattr(game, 'unique_fruits_collected', None)
        if not isinstance(collected, set):
            collected = set(collected or ())
            game.unique_fruits_collected = collected
        collected.add(fruit_type)
    except (TypeError, ValueError, AttributeError):
        pass


# These are the fields actually edited by SettingsScreen. map_theme is changed
# by the separate Player Hub screen and must not be compared against a fresh
# default Settings object when the user saves unrelated options.
_SETTINGS_SCREEN_ACHIEVEMENT_FIELDS = (
    'update_rate_ms', 'board_size', 'snake_color', 'language',
    'wall_collision', 'powerups_enabled', 'enable_obstacles',
    'fruit_types_enabled', 'enable_portals', 'master_volume', 'sfx_volume', 'bgm_volume',
    'sfx_enabled', 'bgm_enabled', 'reduced_motion', 'colorblind_cues',
    'high_contrast', 'ui_scale_percent', 'control_bindings',
)


def _record_settings_achievement_progress(settings, changed_keys):
    """Persist distinct user-edited settings and unlock related achievements."""
    allowed = {
        'update_rate_ms', 'board_size', 'snake_color', 'language', 'wall_collision',
        'powerups_enabled', 'enable_obstacles', 'fruit_types_enabled',
        'enable_portals', 'master_volume', 'sfx_volume', 'bgm_volume',
        'sfx_enabled', 'bgm_enabled', 'map_theme',
        'reduced_motion', 'colorblind_cues', 'high_contrast', 'ui_scale_percent',
        'control_bindings',
    }
    changes = {key for key in changed_keys if isinstance(key, str) and key in allowed}
    if not changes:
        return []
    try:
        data = _load_data()
        progression = data.get('progression', {})
        if not isinstance(progression, dict):
            progression = {}
        previous = progression.get('settings_changed', [])
        if not isinstance(previous, list):
            previous = []
        previous = {key for key in previous if isinstance(key, str) and key in allowed}
        accumulated = sorted(previous | changes)
        progression['settings_changed'] = accumulated
        data['progression'] = progression
        if not _save_data(data):
            return []
        manager = getattr(settings, 'achievement_manager', None)
        if manager is None:
            manager = AchievementManager()
            manager.load_state()
            settings.achievement_manager = manager
        manager.check_achievement_progress({'settings_changed': accumulated})
        return accumulated
    except Exception as exc:
        sgf_log.error('Failed to record settings achievement progress: %s', type(exc).__name__)
        return []


def _profile_game_outcome(game, mode):
    """Resolve the local profile outcome without treating ties as losses."""
    override = getattr(game, '_sgf_xp_victory_override', None)
    if override is not None:
        return 'win' if bool(override) else 'loss'
    winner = getattr(game, 'winner', None)
    if winner in ('player', 'coop_win'):
        return 'win'
    if winner == 'draw':
        return 'draw'
    if winner in ('ai', 'coop_lose'):
        return 'loss'
    if type(winner) is int:
        local_player = 2 if mode == 'lan_client' else 1
        return 'win' if winner == local_player else 'loss'
    if bool(getattr(game, 'victory', False)):
        return 'win'
    if mode in ('singleplayer', 'vs_ai'):
        return 'loss'
    return 'draw'


def _profile_won_game(game, mode):
    """Compatibility helper for code that only needs a win/loss boolean."""
    return _profile_game_outcome(game, mode) == 'win'


def _profile_snake_length(game, mode):
    """Return the final snake length belonging to the local profile slot."""
    snakes = getattr(game, 'snakes', None)
    if isinstance(snakes, (list, tuple)):
        profile_index = 1 if mode == 'lan_client' else 0
        if len(snakes) > profile_index:
            return max(0, min(100_000, len(snakes[profile_index] or [])))
    if mode == 'lan_client':
        client_snake = getattr(game, 'p2_snake', None)
        if client_snake is not None:
            return max(0, min(100_000, len(client_snake or [])))
    snake = getattr(game, 'snake', None)
    if snake is None:
        snake = getattr(game, 'p1_snake', [])
    try:
        return max(0, min(100_000, len(snake or [])))
    except (TypeError, OverflowError):
        return 0


def _profile_game_duration_ms(game):
    """Read bounded active simulation time; pauses and menus are excluded."""
    value = getattr(game, '_sim_time_ms', 0.0)
    if type(value) not in (int, float):
        return 0
    duration = float(value)
    if not math.isfinite(duration) or duration <= 0:
        return 0
    return min(7 * 24 * 60 * 60 * 1000, int(duration))


def _award_game_xp(game, mode='singleplayer'):
    """Award local XP once when a real game result is saved; replays never count."""
    if game is None or getattr(game, 'replay_mode', False) or getattr(game, '_replay_mode', False):
        return None
    award_id = getattr(game, '_sgf_xp_award_id', None)
    if not isinstance(award_id, str) or len(award_id) != 32:
        award_id = _secrets_mod.token_hex(16)
        try:
            game._sgf_xp_award_id = award_id
        except Exception:
            return None

    _xp_locked = False
    try:
        score_override = getattr(game, '_sgf_xp_score_override', None)
        if score_override is not None:
            score_value = score_override
        else:
            score_value = getattr(game, 'score', getattr(game, 'p1_score', 0))
            scores = getattr(game, 'scores', None)
            if isinstance(scores, (list, tuple)) and scores:
                profile_index = 1 if mode == 'lan_client' else 0
                if len(scores) > profile_index:
                    score_value = scores[profile_index]
            elif hasattr(game, 'p1_score'):
                score_value = game.p1_score
        score = _safe_stat_int(score_value, maximum=1_000_000)
        outcome = _profile_game_outcome(game, mode)
        victory = outcome == 'win'
        xp_awarded = 25 + min(100, score // 10) + (25 if victory else 0)
        # Read, change and write the data file as ONE step under the data lock: before, another writer (the thread that
        # saves a finished game's high score) could write in between and its score would be overwritten by this
        # snapshot.
        _data_save_lock.acquire()
        _xp_locked = True
        data = _load_data()
        progress = data.get('progression', {})
        if not isinstance(progress, dict):
            progress = {}
        recent = progress.get('recent_award_ids', [])
        if not isinstance(recent, list):
            recent = []
        if award_id in recent:
            return None

        def _counter(key):
            return _safe_stat_int(progress.get(key, 0))

        total_xp = min(1_000_000_000, _counter('xp_total') + xp_awarded)
        level, level_xp, next_level_xp = _progression_level_for_xp(total_xp)
        games_completed = _counter('games_completed') + 1
        highest_score = max(_counter('highest_score'), score)
        total_score = min(1_000_000_000, _counter('total_score') + score)
        snake_length = _profile_snake_length(game, mode)
        longest_snake = min(100_000,
                            max(_counter('longest_snake'), snake_length))
        fruits_this_game = _safe_stat_int(getattr(game, 'fruits_eaten', 0), maximum=1_000_000)
        portals_this_game = _safe_stat_int(getattr(game, 'portals_used', 0), maximum=1_000_000)
        total_fruits = min(1_000_000_000, _counter('total_fruits') + fruits_this_game)
        total_portals = min(1_000_000_000, _counter('total_portal_uses') + portals_this_game)
        duration_this_game = _profile_game_duration_ms(game)
        def _duration_counter(key):
            value = progress.get(key, 0)
            if type(value) is not int:
                return 0
            return max(0, min(1_000_000_000_000_000, value))
        total_play_time_ms = min(
            1_000_000_000_000_000,
            _duration_counter('total_play_time_ms') + duration_this_game)
        longest_survival_ms = max(
            _duration_counter('longest_survival_ms'), duration_this_game)
        best_combo = max(_counter('best_combo'), _safe_stat_int(getattr(game, 'max_combo', 0), maximum=1_000_000))
        previous_unique_fruits = progress.get('unique_fruits_collected', [])
        if not isinstance(previous_unique_fruits, list):
            previous_unique_fruits = []
        this_game_unique_fruits = getattr(game, 'unique_fruits_collected', set())
        if not isinstance(this_game_unique_fruits, (list, tuple, set)):
            this_game_unique_fruits = []
        unique_fruits = sorted({str(item)[:32] for item in previous_unique_fruits + list(this_game_unique_fruits)
                                if isinstance(item, str) and item})[:64]
        wins = min(1_000_000_000, _counter('wins') + (1 if victory else 0))
        losses = min(1_000_000_000,
                     _counter('losses') + (1 if outcome == 'loss' else 0))
        unlocked_skins = [skin for skin, required_level in _SKIN_LEVEL_UNLOCKS.items()
                          if level >= required_level]
        selected_skin = progress.get('selected_skin', 'classic')
        if selected_skin not in unlocked_skins:
            selected_skin = 'classic'
        recent = (recent + [award_id])[-256:]
        recent_matches = _normalize_recent_matches(progress.get('recent_matches', []))
        recent_matches.append({
            'id': award_id,
            'timestamp': datetime.now().isoformat(timespec='seconds'),
            'score': score,
            'outcome': outcome,
            'mode': str(mode)[:32],
            'snake_length': snake_length,
            'combo': _safe_stat_int(getattr(game, 'max_combo', 0), maximum=1_000_000),
        })
        recent_matches = _normalize_recent_matches(recent_matches)
        data['progression'] = {
            'schema_version': PROGRESSION_SCHEMA_VERSION,
            'xp_total': total_xp,
            'level': level,
            'level_xp': level_xp,
            'next_level_xp': next_level_xp,
            'games_completed': games_completed,
            'highest_score': highest_score,
            'total_score': total_score,
            'longest_snake': longest_snake,
            'total_fruits': total_fruits,
            'total_portal_uses': total_portals,
            'total_play_time_ms': total_play_time_ms,
            'longest_survival_ms': longest_survival_ms,
            'wins': wins,
            'losses': losses,
            'best_combo': best_combo,
            'recent_matches': recent_matches,
            'unique_fruits_collected': unique_fruits,
            'unlocked_skins': unlocked_skins,
            'selected_skin': selected_skin,
            'recent_award_ids': recent,
            'last_award': {'id': award_id, 'xp': xp_awarded, 'mode': str(mode)[:32]},
        }
        if not _save_data(data):                       # the lock is already ours, so this does not wait on itself
            return None
        _data_save_lock.release()
        _xp_locked = False

        manager = getattr(game, 'achievement_manager', None)
        if manager is None:
            manager = AchievementManager()
            manager.load_state()
            try:
                game.achievement_manager = manager
            except Exception:
                pass
        manager.check_achievement_progress({
            'score': score,
            'highest_score': highest_score,
            'games_played': games_completed,
            'total_fruits': total_fruits,
            'level': level,
            'wins': wins,
            'best_combo': best_combo,
            'total_portal_uses': total_portals,
            'portals_used': portals_this_game,
            'portal_uses': total_portals,
            'snake_length': len(getattr(game, 'snake', getattr(game, 'p1_snake', [])) or []),
            'board_size': getattr(game, 'board_width', getattr(getattr(game, 'settings', None), 'board_size', 10)),
            'victory': victory,
            'game_over': True,
            'max_combo': best_combo,
            'fruits_eaten': fruits_this_game,
            'powerups_used': list(getattr(game, 'powerups_used', []) or []),
            'unique_fruits_collected': unique_fruits,
            'completed_with_obstacles': bool(
                getattr(getattr(game, 'settings', None), 'enable_obstacles', False)
                or getattr(game, 'obstacles', [])),
            'max_speed_game': getattr(getattr(game, 'settings', None), 'update_rate_ms', 200) <= 100,
            'update_rate_ms': getattr(getattr(game, 'settings', None), 'update_rate_ms', 200),
            'settings_changed': _load_progression_summary().get('settings_changed', []),
        })
        result = {'xp_awarded': xp_awarded, 'xp_total': total_xp, 'level': level,
                  'level_xp': level_xp, 'next_level_xp': next_level_xp,
                  'leveled_up': level > _progression_level_for_xp(_counter('xp_total'))[0]}
        game._sgf_xp_award_result = result
        return result
    except Exception as exc:
        sgf_log.error('Failed to award local game progression: %s', type(exc).__name__)
        return None
    finally:
        if _xp_locked:
            _data_save_lock.release()


_XP_AWARD_LOCK = threading.Lock()


def _award_game_xp_async(game, mode='singleplayer'):
    """_award_game_xp on a background thread. It reads and rewrites the data file and may wait for the data lock, which
    must never happen on the thread that draws the game. The id that makes an award happen only once is fixed here, and
    awards run one at a time, so calling it twice for the same game still awards once."""
    if game is None or getattr(game, 'replay_mode', False) or getattr(game, '_replay_mode', False):
        return None
    award_id = getattr(game, '_sgf_xp_award_id', None)
    if not isinstance(award_id, str) or len(award_id) != 32:
        try:
            game._sgf_xp_award_id = _secrets_mod.token_hex(16)
        except Exception:
            return None
    done = threading.Event()
    with _async_data_writes_lock:
        _async_data_writes.add(done)

    def work():
        try:
            with _XP_AWARD_LOCK:
                _award_game_xp(game, mode)
        except Exception as exc:
            _logging_mod.getLogger('sgf').warning('XP award failed: %s', exc)
        finally:
            done.set()
            with _async_data_writes_lock:
                _async_data_writes.discard(done)
    threading.Thread(target=work, name='xp-award', daemon=True).start()
    return done


# ─────────────────────────────────────────────────────────────────────────────
# Game Settings persistence / seed / multiplayer configuration
# ─────────────────────────────────────────────────────────────────────────────

_GAME_SETTINGS_KEY = 'game_settings_by_context'  # only the tiny "last played context" pointer still lives in game_data.json
_GAME_CONTEXTS = GAME_SETTINGS_CONTEXTS  # same four contexts the data layer's file-based storage defines: one source of truth
_GAME_SETTINGS_VERSION = 1

def _game_settings_context(context):
    context = str(context or '').strip().lower()
    return context if context in _GAME_CONTEXTS else 'singleplayer'


def _copy_json_safe(value):
    try:
        return json.loads(json.dumps(value, ensure_ascii=False))
    except Exception:
        return copy.deepcopy(value)


def _load_game_settings(context, defaults=None):
    """Per-context Game Settings merged over `defaults`. Thin wrapper over
    the data layer's file-based get_last_game_settings()/save_last_game_settings()
    (config/game_settings/<context>.json) so there is exactly one storage
    location instead of a second copy embedded in game_data.json."""
    context = _game_settings_context(context)
    out = _copy_json_safe(defaults or {})
    out.update(_copy_json_safe(get_last_game_settings(context, {})))
    return out


def _save_game_settings(context, settings_dict, *, mark_last_used=True):
    context = _game_settings_context(context)
    payload = _copy_json_safe(settings_dict or {})
    save_last_game_settings(context, payload)
    if mark_last_used:
        def _mutate(data):
            data['last_game_settings_context'] = context
            return data
        _save_data_async(_mutate)
    return payload


def _last_game_settings_context():
    try:
        return _game_settings_context(_load_data().get('last_game_settings_context', 'singleplayer'))
    except Exception:
        return 'singleplayer'


def _seed_from_setting(seed_mode='random', seed_value=None):
    if str(seed_mode).lower() != 'custom':
        return generate_seed()
    value = str(seed_value or '').strip()
    return value if value else generate_seed()


