def _no_maps_text(language):
    """'No maps yet. Create one first in: Studio > Map Creator' in the player's language."""
    path = f"{_t_or(language, 'studio', 'Studio')} > {get_text(language, 'map_creator')}"
    return get_text(language, 'no_saved_maps').format(path=path)

