# SETTINGS
##############

_CONTROL_DIRECTIONS = ('up', 'down', 'left', 'right')
_CONTROL_PRIMARY_DEFAULTS = {'up': 'w', 'down': 's', 'left': 'a', 'right': 'd'}
_CONTROL_ARROW_FALLBACKS = {
    pygame.K_UP: 'up', pygame.K_DOWN: 'down',
    pygame.K_LEFT: 'left', pygame.K_RIGHT: 'right',
}


def _normalize_control_bindings(raw):
    """Return one valid, unique primary key per direction; arrows stay as
    permanent fallback controls and cannot be rebound to another direction."""
    values = raw if isinstance(raw, dict) else {}
    result = {}
    used = set()
    for action in _CONTROL_DIRECTIONS:
        candidate = values.get(action, _CONTROL_PRIMARY_DEFAULTS[action])
        if not isinstance(candidate, str):
            candidate = _CONTROL_PRIMARY_DEFAULTS[action]
        candidate = candidate.strip().lower()
        if (len(candidate) != 1 or candidate not in 'abcdefghijklmnopqrstuvwxyz0123456789'
                or candidate in used):
            candidate = _CONTROL_PRIMARY_DEFAULTS[action]
        if candidate in used:
            # Malformed persisted values cannot create ambiguous movement.
            candidate = next(key for key in _CONTROL_PRIMARY_DEFAULTS.values()
                             if key not in used)
        result[action] = candidate
        used.add(candidate)
    return result


def _movement_action_for_key(settings, key):
    if key in _CONTROL_ARROW_FALLBACKS:
        return _CONTROL_ARROW_FALLBACKS[key]
    try:
        key_name = pygame.key.name(int(key)).lower()
    except (TypeError, ValueError, OverflowError):
        return None
    bindings = _normalize_control_bindings(getattr(settings, 'control_bindings', None))
    return next((action for action, name in bindings.items() if name == key_name), None)

class Settings:
    def __init__(self):
        """Initialize default settings"""
        # Basic settings
        self.update_rate_ms = 150  # Snake movement speed in milliseconds (lower is faster)
        self.board_size = 20  # Board size (width and height)
        self.min_board_size = 3  # Minimum board size (3x3)
        self.max_board_size = 100  # Maximum board size (100x100)
        self.snake_color = COLORS['snake']  # Default snake color
        self.language = 'en'  # Default language
        self.theme_id = 'default'  # Active visual theme
        self.map_theme = 'classic'
        self.enabled_mods = []  # User-selected optional mods
        self.mod_configuration = {}  # Declarative per-mod profile config
        self.first_time = True  # Flag for first-time users
        self.wall_collision = True  # Whether hitting walls causes game over
        
        # Power-up settings
        self.powerups_enabled = True  # Master toggle for all power-ups
        self.speed_boost_enabled = True  # Temporarily increases snake speed
        self.slow_motion_enabled = True  # Temporarily decreases snake speed
        self.size_reduction_enabled = True  # Temporarily reduces snake size by 1
        self.invincibility_enabled = True  # Temporarily allows passing through walls/self
        self.double_points_enabled = True  # Temporarily doubles points from fruit
        self.ghost_mode_enabled = True  # Temporarily allows passing through snake's own body
        
        # Shield powerup settings
        self.shield_enabled = True  # Provides protection against one collision
        
        # Obstacle settings
        self.enable_obstacles = False  # Master toggle for obstacles
        self.obstacle_count = 5  # Number of obstacles to place on the board
        self.static_obstacles_enabled = False  # Static obstacles on the board
        self.moving_obstacles_enabled = False  # Obstacles that move around
        
        # Portal settings
        self.enable_portals = False  # Master toggle for teleport portals
        self.portal_pairs = 1  # Number of portal pairs on the board
        self.portal_color_1 = (0, 191, 255)  # Deep Sky Blue
        self.portal_color_2 = (75, 0, 130)   # Indigo
        
        # Gameplay features
        self.fruit_types_enabled = True  # Different types of fruit with different effects
        self.combo_fruits_enabled = False  # Consecutive fruits give bonus points
        self.levels_enabled = False  # Progressively more difficult levels
        self.increasing_speed_enabled = False  # Snake speeds up as it grows
        
        # Power-up frequency (higher value = more rare, 1-10 scale)
        self.powerup_frequency = 5  # Overall powerup frequency

        # Sound settings
        self.master_volume = 80   # 0-100
        self.sfx_volume = 100
        self.bgm_volume = 100
        self.sfx_enabled   = True
        self.bgm_enabled   = False
        self.reduced_motion = False
        self.colorblind_cues = False
        self.high_contrast = False
        self.ui_scale_percent = 100
        self.control_bindings = dict(_CONTROL_PRIMARY_DEFAULTS)
        
        # Initialize achievement manager
        self.achievement_manager = AchievementManager()
        
        # Track game stats for achievements
        self.game_stats = {
            'games_played': 0,
            'highest_score': 0,
            'powerups_used': [],
            'portal_uses': 0,
            'completed_with_obstacles': False,
            'max_combo': 0,
            'unique_fruits_collected': [],
            'max_speed_game': False,
            'settings_changed': []
        }
        
    def load(self):
        """Load settings from unified data file"""
        if SAFE_MODE:
            # Safe Mode: use default settings for this session only. The
            # persisted settings/achievements/high scores on disk are left
            # completely untouched.
            try:
                sgf_log.info("Safe Mode active: using default settings for this session.")
            except Exception:
                pass
            _apply_accessibility_preferences(self)
            self.achievement_manager.load_state()
            return
        try:
            _gd = _load_data()
            if 'settings' in _gd:
                data = _gd['settings']
                if True:  # block for indentation
                    # Load basic settings from file
                    self.update_rate_ms = data.get('update_rate_ms', self.update_rate_ms)
                    self.board_size = data.get('board_size', self.board_size)
                    self.snake_color = tuple(data.get('snake_color', self.snake_color))
                    self.language = data.get('language', self.language)
                    self.theme_id = data.get('theme_id', self.theme_id)
                    requested_map_theme = data.get('map_theme', self.map_theme)
                    self.map_theme = (requested_map_theme if isinstance(requested_map_theme, str)
                                      and requested_map_theme in MAP_THEME_PALETTES else 'classic')
                    self.enabled_mods = list(data.get('enabled_mods', self.enabled_mods) or [])
                    self.mod_configuration = copy.deepcopy(data.get('mod_configuration', self.mod_configuration) or {})
                    self.first_time = data.get('first_time', self.first_time)
                    self.wall_collision = data.get('wall_collision', self.wall_collision)

                    # Load sound settings
                    self.master_volume = _normalize_sound_percent(
                        data.get('master_volume', self.master_volume), self.master_volume)
                    self.sfx_volume = _normalize_sound_percent(
                        data.get('sfx_volume', 100), 100)
                    self.bgm_volume = _normalize_sound_percent(
                        data.get('bgm_volume', 100), 100)
                    self.sfx_enabled = _normalize_sound_toggle(
                        data.get('sfx_enabled', self.sfx_enabled), self.sfx_enabled)
                    self.bgm_enabled = _normalize_sound_toggle(
                        data.get('bgm_enabled', self.bgm_enabled), self.bgm_enabled)
                    self.reduced_motion = _normalize_sound_toggle(
                        data.get('reduced_motion', self.reduced_motion), self.reduced_motion)
                    self.colorblind_cues = _normalize_sound_toggle(
                        data.get('colorblind_cues', self.colorblind_cues), self.colorblind_cues)
                    self.high_contrast = _normalize_sound_toggle(
                        data.get('high_contrast', self.high_contrast), self.high_contrast)
                    self.control_bindings = _normalize_control_bindings(
                        data.get('control_bindings', self.control_bindings))
                    try:
                        self.ui_scale_percent = max(80, min(140, int(data.get('ui_scale_percent', self.ui_scale_percent))))
                    except (TypeError, ValueError, OverflowError):
                        self.ui_scale_percent = 100
                    
                    # Load powerup settings
                    self.powerups_enabled = data.get('powerups_enabled', self.powerups_enabled)
                    self.speed_boost_enabled = data.get('speed_boost_enabled', self.speed_boost_enabled)
                    self.slow_motion_enabled = data.get('slow_motion_enabled', self.slow_motion_enabled)
                    self.size_reduction_enabled = data.get('size_reduction_enabled', self.size_reduction_enabled)
                    self.invincibility_enabled = data.get('invincibility_enabled', self.invincibility_enabled)
                    self.double_points_enabled = data.get('double_points_enabled', self.double_points_enabled)
                    self.ghost_mode_enabled = data.get('ghost_mode_enabled', self.ghost_mode_enabled)
                    self.shield_enabled = data.get('shield_enabled', self.shield_enabled)
                    
                    # Load obstacle settings
                    self.enable_obstacles = data.get('enable_obstacles', self.enable_obstacles)
                    self.obstacle_count = data.get('obstacle_count', self.obstacle_count)
                    self.static_obstacles_enabled = data.get('static_obstacles_enabled', self.static_obstacles_enabled)
                    self.moving_obstacles_enabled = data.get('moving_obstacles_enabled', self.moving_obstacles_enabled)
                    
                    # Load portal settings
                    self.enable_portals = data.get('enable_portals', self.enable_portals)
                    self.portal_pairs = data.get('portal_pairs', self.portal_pairs)
                    
                    # Convert color tuples if they exist
                    if 'portal_color_1' in data:
                        self.portal_color_1 = tuple(data.get('portal_color_1'))
                    if 'portal_color_2' in data:
                        self.portal_color_2 = tuple(data.get('portal_color_2'))
                    
                    # Load additional gameplay features
                    self.fruit_types_enabled = data.get('fruit_types_enabled', self.fruit_types_enabled)
                    self.combo_fruits_enabled = data.get('combo_fruits_enabled', self.combo_fruits_enabled)
                    self.levels_enabled = data.get('levels_enabled', self.levels_enabled)
                    self.increasing_speed_enabled = data.get('increasing_speed_enabled', self.increasing_speed_enabled)
                    
                    # Load powerup frequency
                    self.powerup_frequency = data.get('powerup_frequency', self.powerup_frequency)
        except (json.JSONDecodeError, FileNotFoundError, IOError) as e:
            print(f"Error loading settings: {e}")
            # If there's an error, use default settings
            self.reset_to_defaults()

        _apply_accessibility_preferences(self)
        # Restore unlocked achievements (stored under the same JSON file)
        self.achievement_manager.load_state()
            
