    def draw_gameplay_settings(self, screen_width, screen_height, margin_x, content_width, start_y, spacing, controls):
        """Draw the gameplay settings page"""
        # This page can show up to 2 titles + 3 checkboxes + 2 sliders at
        # once (when obstacles and portals are both enabled) — tighter,
        # content-aware gaps than the shared default, sized to what each
        # control actually draws, so nothing bleeds into the next row or
        # the fixed button row below.
        gameplay_y = int(screen_height * 0.15)
        gap_checkbox = 30       # checkbox (24px) + small buffer
        gap_before_slider = 46  # checkbox/title row + slider's own label-above text
        gap_after_slider = 46   # slider box + its min/max row below + buffer
        gap_title = 34          # section title + buffer
        
        # Levels checkbox
        levels_rect = pygame.Rect(margin_x, gameplay_y, 24, 24)
        controls['levels'] = self.create_checkbox(
            levels_rect,
            self.temp_settings.levels_enabled,
            get_text(self.settings.language, 'levels')
        )
        
        # Increasing speed checkbox
        gameplay_y += gap_checkbox
        increasing_speed_rect = pygame.Rect(margin_x, gameplay_y, 24, 24)
        controls['increasing_speed'] = self.create_checkbox(
            increasing_speed_rect,
            self.temp_settings.increasing_speed_enabled,
            get_text(self.settings.language, 'increasing_speed')
        )
        
        # Obstacles section title
        gameplay_y += gap_title
        obstacles_font = get_font(self.settings.language, 'bold', 22)
        obstacles_title = get_text(self.settings.language, 'obstacles_title')
        obstacles_title_surface = obstacles_font.render(obstacles_title, True, COLORS['white'])
        self.screen.blit(obstacles_title_surface, (margin_x, gameplay_y))
        
        # Enable obstacles checkbox
        gameplay_y += gap_title
        obstacles_rect = pygame.Rect(margin_x, gameplay_y, 24, 24)
        controls['enable_obstacles'] = self.create_checkbox(
            obstacles_rect,
            self.temp_settings.enable_obstacles,
            get_text(self.settings.language, 'static_obstacles')
        )
        
        # Obstacle count slider (only appears if obstacles are enabled)
        if self.temp_settings.enable_obstacles:
            gameplay_y += gap_before_slider
            obstacle_count_rect = pygame.Rect(margin_x, gameplay_y, content_width, 26)
            controls['obstacle_count'] = self.create_slider(
                obstacle_count_rect,
                1,  # Minimum value
                20, # Maximum value 
                self.temp_settings.obstacle_count,
                "Obstacle Count",
                COLORS.get('slider', (60, 180, 120))
            )
            gameplay_y += gap_after_slider
        else:
            gameplay_y += gap_checkbox
        
        # Portals section title
        gameplay_y += gap_title
        portals_font = get_font(self.settings.language, 'bold', 22)
        portals_title = get_text(self.settings.language, 'portals_title')
        portals_title_surface = portals_font.render(portals_title, True, COLORS['white'])
        self.screen.blit(portals_title_surface, (margin_x, gameplay_y))
        
        # Enable portals checkbox
        gameplay_y += gap_title
        portals_rect = pygame.Rect(margin_x, gameplay_y, 24, 24)
        controls['enable_portals'] = self.create_checkbox(
            portals_rect,
            self.temp_settings.enable_portals,
            get_text(self.settings.language, 'portals_enabled')
        )
        
        # Portal pairs slider (only appears if portals are enabled)
        if self.temp_settings.enable_portals:
            gameplay_y += gap_before_slider
            portal_pairs_rect = pygame.Rect(margin_x, gameplay_y, content_width, 26)
            controls['portal_pairs'] = self.create_slider(
                portal_pairs_rect,
                1,  # Minimum value
                5,  # Maximum value
                self.temp_settings.portal_pairs,
                "Portal Pairs",
                COLORS.get('slider', (60, 180, 120))
            )
            gameplay_y += gap_after_slider
        
        # Return the updated controls
        return controls
        
