# GAME
##############

def _pos_counter(iterable):
    """Build a position -> occupancy-count map from a list of board
    coordinates. A plain set would lose track of a cell that's covered by
    two overlapping snake segments at once (the game's "green apple" effect
    deliberately duplicates the tail segment onto the same cell for one
    frame) — removing one of the two would then wrongly mark the cell as
    free while the other copy is still sitting there. Using counts instead
    of a plain set makes the O(1) occupancy check correct even when a cell
    is currently covered more than once."""
    counter = {}
    for p in iterable:
        counter[p] = counter.get(p, 0) + 1
    return counter


def _counter_add(counter, pos):
    """Mark one more occupant at `pos` in a position counter."""
    counter[pos] = counter.get(pos, 0) + 1


def _counter_discard(counter, pos):
    """Remove one occupant at `pos` from a position counter, dropping the
    key entirely once the count reaches zero so `pos in counter` reports
    False as soon as the cell is genuinely free again."""
    c = counter.get(pos, 0)
    if c <= 1:
        counter.pop(pos, None)
    else:
        counter[pos] = c - 1


class SnakeGame:
    def __init__(self, settings, screen, seed=None, custom_map=None):
        self.settings = settings
        self.screen = screen
        try:
            self._active_skin = _load_progression_summary()['selected_skin']
        except Exception:
            self._active_skin = 'classic'
        # Seed / RNG system
        self.seed = seed if seed else generate_seed()
        self.rng  = SeedRNG(self.seed)
        self.cosmetic_rng = random.Random(seed_to_int(f'{self.seed}:cosmetic'))
        # Optional custom map from the Map Editor: {'board_width', 'board_height',
        # 'obstacles': [[x,y],...], 'portals': [[x1,y1,x2,y2,pal_idx],...]}
        # When set, reset_game() uses this layout verbatim instead of
        # procedurally generating obstacles/portals.
        self.custom_map = custom_map
        # Encyclopedia: accumulate encounter/use counts in memory during
        # the match, flushed to disk once at game-over.
        self._enc_updates = {}
        self.player_name = ""
        # Will be set by MainMenu after initialization
        self.achievement_manager = None
        self.game_history = []  # For replay functionality
        self._history_cells = 0
        self._history_truncated = False
        self.replay_mode = False  # Flag to indicate replay mode
        self.replay_index = 0  # Current index in replay
        self.replay_speed = 1.0  # Speed multiplier for replay
        self.on_replay_end = None  # Callback function when replay ends
        self._replay_ended = False  # True when the last replay frame is reached
        self._replay_exit_requested = False  # Set True to break out of run()
        self.performance_stats = GameplayPerformanceStats()
        self._sim_time_ms = 0.0
        self._update_accumulator_ms = 0.0
        self.reset_game()
        if 'DEV_TOOLS' in globals():
            DEV_TOOLS.register_game(self)
        
    def _enc_touch(self, entry_id, encountered=0, used=0):
        """Accumulate an encyclopedia encounter/use count for this match;
        flushed to disk at game-over via _flush_encyclopedia_updates()."""
        if not entry_id:
            return
        d = self._enc_updates.setdefault(entry_id, {'encountered': 0, 'used': 0})
        d['encountered'] += encountered
        d['used'] += used

    def reset_game(self):
        """Reset the game state"""
        _clear_game_xp_award(self)
        self._replay_save_game_id = None
        # Re-seed the RNG so restarting reproduces the *exact* same sequence
        # of fruit positions/types, obstacle/portal placement, etc. for this
        # seed — without this, "Play Again" would continue the RNG stream
        # from wherever the previous run left off instead of starting the
        # seed fresh, so the same seed wouldn't actually replay the same way.
        self.rng = SeedRNG(self.seed)
        self.cosmetic_rng = random.Random(seed_to_int(f'{self.seed}:cosmetic'))

        # Reset replay-related properties
        if not self.replay_mode:
            self.game_history = []  # Clear history for a new game
            self._history_cells = 0
            self._history_truncated = False
        
        self.replay_index = 0
        self.replay_speed = 1.0
        self.portal_used = False
        self.portal_cooldown = 0
        
        # Reset achievement tracking counters
        self.fruits_eaten = 0
        self.unique_fruits_collected = set()
        self.powerups_used = set()
        self.portals_used = 0
        self.max_combo = 0
        
        # Level progression - start with a smaller board if enabled
        if self.custom_map:
            self.board_width = self.custom_map.get('board_width', 20)
            self.board_height = self.custom_map.get('board_height', 20)
            self.current_level = 1
        elif self.settings.levels_enabled:
            self.current_level = 1
            self.starting_board_size = 3  # Start with a 3x3 grid
            self.board_width = self.starting_board_size
            self.board_height = self.starting_board_size
        else:
            # Normal mode - use settings board size
            # Convert board_size to int if it's a string (handle both options)
            if isinstance(self.settings.board_size, str):
                size_map = {"small": 10, "medium": 15, "large": 20, "extra_large": 25}
                board_size = size_map.get(self.settings.board_size, 15)  # Default to 15 if unknown
            else:
                board_size = self.settings.board_size
                
            self.board_width = board_size
            self.board_height = board_size
            
        # Calculate cell size based on board dimensions
        self.cell_size = min(self.screen.get_width(), self.screen.get_height()) // max(self.board_width, self.board_height)
        
        # Calculate board position to center it
        self.board_offset_x = (self.screen.get_width() - (self.board_width * self.cell_size)) // 2
        self.board_offset_y = (self.screen.get_height() - (self.board_height * self.cell_size)) // 2
        
        # Portal state initialization
        self.portals = []  # List of portal pairs: [(x1, y1), (x2, y2), pair_id]
        self.portal_cooldown = 0  # To prevent immediate re-teleportation
        self.portal_used = False  # Flag to track if the snake just used a portal
        
        # Power-up state initialization - initialize these before generate_fruit() is called
        self.active_powerups = []  # List of active power-ups: {type, duration, start_time}
        self.powerup_position = None  # Current power-up position on the board
        self.powerup_type = None  # Current power-up type
        self.powerup_spawn_interval = 15000  # Spawn a powerup every 15 seconds if enabled
        self.powerup_spawn_timer = -self.powerup_spawn_interval  # Preserve immediate first-tick spawn
        self.powerup_duration = 10000  # Default 10 second duration for power-ups
        
        # Power-up effect multipliers (default = 1.0 = no effect)
        self.speed_multiplier = 1.0
        self.points_multiplier = 1.0
        self.invincible = False
        self.ghost_mode = False
        self.shield_active = False
        
        # Fruit combo tracking
        self.last_fruit_type = 'regular'
        self.current_fruit_type = 'regular'
        self.current_fruit_value = 1
        self.combo_count = 0
        self.max_combo = 0
        
        # Speed increase with length
        self.length_speed_multiplier = 1.0
        
        # Moving obstacles
        self.moving_obstacles = []
        self.obstacle_move_interval = 1000  # 1 second interval for obstacle movement
        self._sim_time_ms = 0.0
        self._update_accumulator_ms = max(1.0, float(self.settings.update_rate_ms))
        self.next_obstacle_move_time = self.obstacle_move_interval
        self.performance_stats.reset()
        
        # Snake initial state - center snake in the board
        self.direction = (1, 0)  # Start moving right
        self.snake = [(self.board_width // 4, self.board_height // 2)]
        self.next_direction = self.direction
        # Companion sets for O(1) collision lookups (self.snake/self.obstacles
        # stay the source of truth and keep their list order for rendering
        # and serialization; these mirror them for fast "in" checks in the
        # per-frame hot path instead of scanning the whole list each time).
        self._snake_set = _pos_counter(self.snake)

        # Static obstacles initialization
        self.obstacles = []
        if self.custom_map:
            self.obstacles = [tuple(o) for o in self.custom_map.get('obstacles', [])]
        elif self.settings.enable_obstacles:
            self.generate_obstacles()
        self._obstacles_set = _pos_counter(self.obstacles)
            
        # Portal initialization
        self.portals = []
        if self.custom_map:
            for p in self.custom_map.get('portals', []):
                x1, y1, x2, y2, pal_idx = p
                self.portals.append(((x1, y1), (x2, y2), pal_idx))
        elif self.settings.enable_portals:
            self.generate_portals()

        # Custom maps are hand-made and might happen to place an obstacle or
        # portal right where the snake would spawn — relocate to the nearest
        # free cell rather than spawning on top of it.
        if self.custom_map:
            occupied = set(self.obstacles) | {p[0] for p in self.portals} | {p[1] for p in self.portals}
            if self.snake[0] in occupied:
                found = None
                for radius in range(1, max(self.board_width, self.board_height)):
                    for dx in range(-radius, radius + 1):
                        for dy in range(-radius, radius + 1):
                            cand = (self.snake[0][0] + dx, self.snake[0][1] + dy)
                            if (0 <= cand[0] < self.board_width and 0 <= cand[1] < self.board_height
                                    and cand not in occupied):
                                found = cand
                                break
                        if found:
                            break
                    if found:
                        break
                if found:
                    self.snake = [found]
                    self._snake_set = _pos_counter(self.snake)
                    self.next_direction = self.direction
        
        # Game state
        self.score = 0
        self.game_over = False

        # Encyclopedia: record which mechanics/objects are active this match
        if self.obstacles:
            self._enc_touch('obstacle_static', encountered=1)
        if self.portals:
            self._enc_touch('portal_pair', encountered=len(self.portals))
        self._enc_touch('mechanic_seeds', encountered=1)
        if getattr(self.settings, 'wall_collision', True):
            self._enc_touch('mechanic_wall_collision', encountered=1)
        if getattr(self.settings, 'levels_enabled', False):
            self._enc_touch('mechanic_level_progression', encountered=1)
        if getattr(self.settings, 'combo_fruits_enabled', False):
            self._enc_touch('mechanic_combo', encountered=1)
        self.victory = False
        self.paused = False
        self.last_update_time = 0.0  # Simulation-time compatibility field
        
        # Achievement tracking counters
        self.fruits_eaten = 0
        self.unique_fruits_collected = set()
        self.powerups_used = set()
        self.portals_used = 0
        
        # Generate fruit last, after all other attributes are initialized
        self.fruit_position = self.generate_fruit()
        
    def generate_obstacles(self):
        """Generate obstacles based on settings"""
        self.obstacles = []
        self._obstacles_set = {}
        
        # Only generate obstacles if they're enabled
        if not self.settings.enable_obstacles:
            return
            
        # Calculate number of obstacles
        if self.settings.obstacle_count >= (self.board_width * self.board_height - 3):
            # Limit obstacle count to a reasonable number to ensure playability
            obstacle_count = (self.board_width * self.board_height) // 4
        else:
            obstacle_count = self.settings.obstacle_count
            
        # Make sure we don't put obstacles near the snake's starting position
        # Check if snake is initialized, in case this method is called at incorrect time
        if not hasattr(self, 'snake') or len(self.snake) == 0:
            # Create a default safe zone in the center if snake is not initialized
            center_x, center_y = self.board_width // 4, self.board_height // 2
            safe_zone = [(center_x + dx, center_y + dy) 
                       for dx in range(-2, 3) for dy in range(-2, 3)]
        else:
            snake_head = self.snake[0]
            safe_zone = [(snake_head[0] + dx, snake_head[1] + dy) 
                       for dx in range(-2, 3) for dy in range(-2, 3)]
        
        # Generate obstacle positions
        for _ in range(obstacle_count):
            available_positions = []
            for x in range(self.board_width):
                for y in range(self.board_height):
                    pos = (x, y)
                    # Make sure position is not on snake, another obstacle, or in the safe zone
                    if pos not in self._snake_set and pos not in self._obstacles_set and pos not in safe_zone:
                        available_positions.append(pos)
            
            if available_positions:
                chosen = self.rng.choice(available_positions)
                self.obstacles.append(chosen)
                _counter_add(self._obstacles_set, chosen)
            else:
                # Stop if there are no more available positions
                break
    
    def generate_fruit(self):
        """Generate a new fruit position and type"""
        available_positions = []
        for x in range(self.board_width):
            for y in range(self.board_height):
                pos = (x, y)
                # Make sure position is not occupied by snake, obstacles or powerup
                if (pos not in self._snake_set and 
                    pos not in self._obstacles_set and 
                    pos != self.powerup_position):
                    available_positions.append(pos)
                    
        if available_positions:
            position = self.rng.choice(available_positions)
            
            # Only generate different fruit types if enabled in settings
            if self.settings.fruit_types_enabled:
                # List of possible fruit types
                fruit_types = [
                    'regular',    # Regular apple - 1 point
                    'golden',     # Golden apple - double points
                    'blue',       # Blueberry - speed boost
                    'green',      # Green apple - extra length
                    'orange',     # Orange - slow motion
                    'purple',     # Plum - invincibility
                    'yellow',     # Lemon - score bonus
                    'pink',       # Strawberry - shrink snake
                    'cyan',       # Blueberry - reverse controls
                    'lime',       # Lime - clear obstacles
                    'brown',      # Coconut - teleport
                    'teal',       # Avocado - phase through walls
                    'navy',       # Blackberry - night mode
                    'coral',      # Grapefruit - reduce obstacles
                    'maroon',     # Cherry - point multiplier
                    'olive',      # Olive - extra life
                    'mint',       # Mint - freeze obstacles
                    'lavender',   # Grape - snake invisibility
                    'turquoise',  # Kiwi - creates fruit trail
                    'beige',      # Pear - temporary immunity
                    'cream',      # Banana - speed burst
                    'salmon',     # Peach - board expansion
                    'indigo',     # Blackcurrant - portal creation
                    'crimson',    # Pomegranate - attract fruits
                    'gold',       # Star fruit - combo multiplier
                    'auto_tracking' # Super rare tracking fruit - helps find fruits
                ]
                
                # Weighted selection - make regular fruits more common
                weights = [0.3]  # 30% chance for regular fruit
                special_weight = 0.7 / (len(fruit_types) - 1)  # Distribute remaining 70% among special fruits
                weights.extend([special_weight] * (len(fruit_types) - 1))
                
                # Select fruit type
                self.current_fruit_type = self.rng.choices(fruit_types, weights=weights)[0]
                
                # If combo fruits enabled, increase chance of getting the same type as before
                if self.settings.combo_fruits_enabled and hasattr(self, 'last_fruit_type'):
                    # 30% chance to get the same fruit type as the last one for combos
                    if self.rng.random() < 0.3:
                        self.current_fruit_type = self.last_fruit_type
                
                # Store point value based on fruit type
                if self.current_fruit_type == 'golden':
                    self.current_fruit_value = 2
                elif self.current_fruit_type in ['yellow', 'maroon']:
                    self.current_fruit_value = 3
                elif self.current_fruit_type == 'gold':
                    # Star fruit value increases with combo
                    if hasattr(self, 'combo_count') and self.combo_count > 0:
                        self.current_fruit_value = 1 + self.combo_count
                    else:
                        self.current_fruit_value = 1
                else:
                    self.current_fruit_value = 1

                dev_forced = None
                try:
                    dev_forced = DEV_TOOLS.forced_fruit() if DEV_TOOLS.active and DEV_TOOLS.cheats.get('force_next_item') else None
                except Exception:
                    dev_forced = None
                if dev_forced in _DEV_FRUITS:
                    self.current_fruit_type = dev_forced
                    self.current_fruit_value = 2 if dev_forced == 'golden' else (3 if dev_forced in ('yellow', 'maroon') else 1)
                self._enc_touch(_FRUIT_TYPE_TO_ENC_ID.get(self.current_fruit_type), encountered=1)
            else:
                # Default to regular fruit if different types are disabled
                self.current_fruit_type = 'regular'
                self.current_fruit_value = 1
                
            return position
        else:
            # No positions available means the snake has filled the board
            self.victory = True
            sounds().play('victory')
            return None
    
    def generate_portals(self):
        """Generate portal pairs based on settings"""
        self.portals = []
        
        # Only generate portals if enabled
        if not self.settings.enable_portals or self.settings.portal_pairs <= 0:
            return
            
        # Get safe zone around snake
        if not hasattr(self, 'snake') or len(self.snake) == 0:
            # Create a default safe zone in the center
            center_x, center_y = self.board_width // 4, self.board_height // 2
            safe_zone = [(center_x + dx, center_y + dy) 
                       for dx in range(-2, 3) for dy in range(-2, 3)]
        else:
            # Safe zone around snake head
            snake_head = self.snake[0]
            safe_zone = [(snake_head[0] + dx, snake_head[1] + dy) 
                       for dx in range(-2, 3) for dy in range(-2, 3)]
        
        # Generate portal pairs
        for pair_id in range(self.settings.portal_pairs):
            # Generate first portal
            portal1 = None
            portal2 = None
            
            # Get available positions for first portal
            available_positions1 = []
            for x in range(self.board_width):
                for y in range(self.board_height):
                    pos = (x, y)
                    # Make sure position isn't on snake, obstacles, or in safe zone
                    if (pos not in self._snake_set and 
                        pos not in self._obstacles_set and 
                        pos not in safe_zone and
                        not any(pos == p[0] or pos == p[1] for p in self.portals)):
                        available_positions1.append(pos)
            
            # If we have valid positions, place first portal
            if available_positions1:
                portal1 = self.rng.choice(available_positions1)
                
                # Get available positions for second portal that are at least 3 cells away
                available_positions2 = []
                for x in range(self.board_width):
                    for y in range(self.board_height):
                        pos = (x, y)
                        # Calculate Manhattan distance between portals
                        if portal1:
                            distance = abs(pos[0] - portal1[0]) + abs(pos[1] - portal1[1])
                        else:
                            distance = 0
                            
                        # Make sure position isn't on snake, obstacles, or too close to first portal
                        if (pos not in self._snake_set and 
                            pos not in self._obstacles_set and 
                            pos != portal1 and
                            distance >= 3 and  # Minimum distance between portals
                            not any(pos == p[0] or pos == p[1] for p in self.portals)):
                            available_positions2.append(pos)
                
                # If we have valid positions for second portal, place it
                if available_positions2:
                    portal2 = self.rng.choice(available_positions2)
                    
                    # Add the portal pair to the list
                    self.portals.append((portal1, portal2, pair_id))
            
            # If we couldn't place a complete pair, stop generating more
            if not portal1 or not portal2:
                break
                
    def generate_powerup(self):
        """Generate a new power-up if conditions are met"""
        # Only generate power-ups if the master toggle is enabled
        if not self.settings.powerups_enabled:
            self.powerup_position = None
            self.powerup_type = None
            return
            
        # Get list of available power-up types based on settings
        available_powerups = []
        if self.settings.speed_boost_enabled:
            available_powerups.append('speed_boost')
        if self.settings.slow_motion_enabled:
            available_powerups.append('slow_motion')
        if self.settings.size_reduction_enabled:
            available_powerups.append('size_reduction')
        if self.settings.invincibility_enabled:
            available_powerups.append('invincibility')
        if self.settings.double_points_enabled:
            available_powerups.append('double_points')
        if hasattr(self.settings, 'ghost_mode_enabled') and self.settings.ghost_mode_enabled:
            available_powerups.append('ghost_mode')
        if hasattr(self.settings, 'shield_enabled') and self.settings.shield_enabled:
            available_powerups.append('shield')
            
        # If no power-ups are enabled, don't spawn any
        if not available_powerups:
            self.powerup_position = None
            self.powerup_type = None
            return
            
        # Select a random power-up type (or a one-shot DEV forced value).
        forced_powerup = None
        try:
            if DEV_TOOLS.active and DEV_TOOLS.forced_powerup in available_powerups:
                forced_powerup = DEV_TOOLS.forced_powerup
                DEV_TOOLS.forced_powerup = None
        except Exception:
            forced_powerup = None
        self.powerup_type = forced_powerup or self.rng.choice(available_powerups)
        self._enc_touch(_POWERUP_TYPE_TO_ENC_ID.get(self.powerup_type), encountered=1)
        
        # Generate power-up position (not on snake, obstacles, or fruit)
        available_positions = []
        for x in range(self.board_width):
            for y in range(self.board_height):
                pos = (x, y)
                if (pos not in self._snake_set and 
                    pos not in self._obstacles_set and 
                    pos != self.fruit_position):
                    available_positions.append(pos)
                    
        if available_positions:
            self.powerup_position = self.rng.choice(available_positions)
        else:
            # No available positions, don't spawn power-up
            self.powerup_position = None
            self.powerup_type = None
            
    def _shield_redirect(self, head_x, head_y):
        """Try to save the snake using its shield by redirecting it to a
        safe adjacent direction, instead of ending the game.

        Respects self.settings.wall_collision: previously this always
        wrapped the candidate position modulo the board size, so a shield
        save could teleport the snake straight through a wall even in a
        walled game (wall_collision=True) — a save that should only ever
        be possible in wrap-around mode. Now a direction that would cross
        a wall is treated as unsafe, exactly like the main movement check
        above it.

        Returns the new head position to use if a safe direction was
        found, or None if the snake is boxed in on every side (caller
        should end the game as normal).
        """
        safe_directions = []
        for test_dir in [(0, -1), (1, 0), (0, 1), (-1, 0)]:  # up, right, down, left
            raw_x, raw_y = head_x + test_dir[0], head_y + test_dir[1]
            if self.settings.wall_collision and not self.invincible and not getattr(self, '_dev_no_wall_collision', False):
                if raw_x < 0 or raw_x >= self.board_width or raw_y < 0 or raw_y >= self.board_height:
                    continue  # would cross a wall — not a safe direction here
                test_pos = (raw_x, raw_y)
            else:
                test_pos = (raw_x % self.board_width, raw_y % self.board_height)
            if test_pos not in self._snake_set and test_pos not in self._obstacles_set:
                safe_directions.append((test_dir, test_pos))

        if not safe_directions:
            return None

        test_dir, new_head = self.rng.choice(safe_directions)
        self.direction = test_dir
        self.next_direction = test_dir
        return new_head

    def _update_gameplay_timers(self):
        """Advance power-up spawn/expiry using simulation time, not render FPS."""
        current_time = self._sim_time_ms

        if (self.settings.powerups_enabled and
            self.powerup_position is None and
            current_time - self.powerup_spawn_timer >= self.powerup_spawn_interval):
            self.powerup_spawn_interval = self.rng.randint(10000, 20000)
            self.powerup_spawn_timer = current_time
            self.generate_powerup()

        expired = [p for p in self.active_powerups
                   if current_time - p['start_time'] >= p['duration']]
        for powerup in expired:
            try:
                self.active_powerups.remove(powerup)
            except ValueError:
                continue
            self.deactivate_powerup(powerup['type'])

    def deterministic_state_signature(self):
        """Return gameplay state suitable for deterministic regression tests."""
        return {
            'seed': self.seed,
            'board': (self.board_width, self.board_height),
            'snake': tuple(self.snake),
            'fruit': self.fruit_position,
            'fruit_type': self.current_fruit_type,
            'fruit_value': self.current_fruit_value,
            'obstacles': tuple(self.obstacles),
            'portals': tuple(self.portals),
            'powerup': (self.powerup_position, self.powerup_type),
            'moving_obstacles': tuple(
                (mo['position'], mo['direction'])
                for mo in getattr(self, 'moving_obstacles', [])
            ),
            'effects': (self.speed_multiplier, self.points_multiplier,
                        self.invincible, self.ghost_mode, self.shield_active,
                        self.length_speed_multiplier),
        }

    def get_performance_stats(self):
        """Return a copy of the current rolling performance telemetry."""
        return self.performance_stats.snapshot()

    def move_snake(self):
        """Move the snake according to the current direction"""
        if self.game_over or self.victory or self.paused:
            return
        
        # Record a compact state snapshot before each move (no limit on the length of the game)
        _append_solo_replay_snapshot(self)
            
        # Update the next direction based on user input
        self.direction = self.next_direction
        
        # Calculate new head position
        head_x, head_y = self.snake[0]
        dir_x, dir_y = self.direction
        
        # New head position calculation with wall collision
        if self.settings.wall_collision and not self.invincible:
            # With wall collision - no wrapping
            new_head_x = head_x + dir_x
            new_head_y = head_y + dir_y
            
            # Check for wall collision
            if new_head_x < 0 or new_head_x >= self.board_width or new_head_y < 0 or new_head_y >= self.board_height:
                self.game_over = True
                self.save_score()
                return
                
            new_head = (new_head_x, new_head_y)
        else:
            # No wall collision or invincible - wrap around board
            new_head = ((head_x + dir_x) % self.board_width, (head_y + dir_y) % self.board_height)
        
        # Check for collision with self (only if not invincible and not in ghost mode)
        if new_head in self._snake_set and not self.invincible and not self.ghost_mode:
            # If shield is active, consume the shield instead of game over
            if self.shield_active:
                self.shield_active = False
                redirected = self._shield_redirect(head_x, head_y)
                if redirected is not None:
                    new_head = redirected
                else:
                    # No safe direction available
                    self.game_over = True
                    self.save_score()
                    return
            else:
                self.game_over = True
                self.save_score()
                return

        # Check for collision with obstacles (only if not invincible)
        if new_head in self._obstacles_set and not self.invincible:
            # If shield is active, consume the shield instead of game over
            if self.shield_active:
                self.shield_active = False
                redirected = self._shield_redirect(head_x, head_y)
                if redirected is not None:
                    new_head = redirected
                else:
                    # No safe direction available
                    self.game_over = True
                    self.save_score()
                    return
            else:
                self.game_over = True
                self.save_score()
                return
            
        # Check for portal teleportation if:
        # 1. Portal cooldown is over (prevents multiple teleports in a row)
        # 2. We're not coming from a teleport (prevents loop teleports)
        # 3. Portals are enabled
        if self.settings.enable_portals and self.portal_cooldown <= 0 and not self.portal_used:
            for portal1, portal2, pair_id in self.portals:
                if new_head == portal1:
                    # Teleport from portal1 to portal2
                    new_head = portal2
                    self.portal_cooldown = 3  # Wait 3 moves before allowing another teleport
                    self.portal_used = True
                    self.portals_used += 1  # Count for achievements
                    break
                elif new_head == portal2:
                    # Teleport from portal2 to portal1
                    new_head = portal1
                    self.portal_cooldown = 3  # Wait 3 moves before allowing another teleport
                    self.portal_used = True
                    self.portals_used += 1  # Count for achievements
                    break
        else:
            # Reset portal used flag if we moved normally
            self.portal_used = False
            
        # Decrement portal cooldown if active
        if self.portal_cooldown > 0:
            self.portal_cooldown -= 1
        
        # Move the snake
        self.snake.insert(0, new_head)
        _counter_add(self._snake_set, new_head)
        
        # Check for fruit collision
        if new_head == self.fruit_position:
            # Increment fruit counter for achievements
            _track_game_fruit(self, self.current_fruit_type)
            self._enc_touch(_FRUIT_TYPE_TO_ENC_ID.get(self.current_fruit_type), used=1)
            
            # Process fruit effect based on type
            fruit_effect_applied = self.process_fruit_effect()
            
            # Update combo counter
            if self.settings.combo_fruits_enabled:
                if hasattr(self, 'last_fruit_type') and self.current_fruit_type == self.last_fruit_type:
                    self.combo_count += 1
                    # Show combo message
                    if self.combo_count > 1:
                        # Add combo bonus points
                        combo_bonus = self.combo_count * 5  # 5 points per combo level
                        self.score += combo_bonus
                else:
                    self.combo_count = 1
                
                # Track max combo for stats
                self.max_combo = max(self.max_combo, self.combo_count)
                
                # Store fruit type for combo tracking
                self.last_fruit_type = self.current_fruit_type
            
            # Calculate base points including any fruit value and special effects
            speed_factor = 1000 / self.settings.update_rate_ms
            base_points = int(10 * speed_factor * self.points_multiplier)
            
            # Multiply by fruit value
            points = base_points * self.current_fruit_value
            
            # Add to score
            self.score += points
            # Sound feedback
            _snd = 'eat_gold' if getattr(self, 'current_fruit_type', '') == 'golden' else 'eat'
            sounds().play(_snd)
            _trigger_mobile_haptic(30)
            
            # Check if level progression should occur
            if self.settings.levels_enabled:
                # Calculate board fill percentage
                board_area = self.board_width * self.board_height
                snake_size = len(self.snake)
                fill_percentage = (snake_size / max(1, board_area)) * 100
                
                # If the board is 75% full and we're not at max size, expand the board
                if fill_percentage >= 75 and self.board_width < self.settings.board_size:
                    self.level_up()
                    sounds().play('levelup')
                    
            # Generate new fruit
            self.fruit_position = self.generate_fruit()
            
            # Add length for "normal" growth (some fruits might already change length)
            if not fruit_effect_applied:
                # This is the default growth behavior when eating a fruit
                pass  # Snake already grew by inserting the head above
        else:
            # Remove tail if no fruit was eaten
            removed_tail = self.snake.pop()
            _counter_discard(self._snake_set, removed_tail)
            
        # Process speed increases if enabled
        if self.settings.increasing_speed_enabled:
            # Increase game speed based on snake length
            # The longer the snake, the faster it gets
            snake_length = len(self.snake)
            if snake_length > 5:  # Start increasing after minimal length
                # Calculate a multiplier that increases with snake length
                # This makes the game progressively faster
                self.length_speed_multiplier = max(1.0, min(2.0, 1.0 + (snake_length - 5) * 0.02))
            else:
                self.length_speed_multiplier = 1.0
        
        # Check for power-up collision
        if self.powerup_position and new_head == self.powerup_position:
            self._enc_touch(_POWERUP_TYPE_TO_ENC_ID.get(self.powerup_type), used=1)
            self.activate_powerup(self.powerup_type)
            self.powerup_position = None
            self.powerup_type = None
            
        # Spawn/expire power-ups from simulation time so render FPS cannot alter gameplay.
        self._update_gameplay_timers()
            
        # Check for victory condition
        if len(self.snake) == self.board_width * self.board_height:
            self.victory = True
            self.save_score()
            
        # Update achievement progress if achievement manager exists
        if hasattr(self, 'achievement_manager') and self.achievement_manager:
            game_data = {
                'score': self.score,
                'snake_length': len(self.snake),
                'fruits_eaten': self.fruits_eaten if hasattr(self, 'fruits_eaten') else 0,
                'portals_used': self.portals_used if hasattr(self, 'portals_used') else 0,
                'max_combo': self.max_combo if hasattr(self, 'max_combo') else 0,
                'level': self.current_level if hasattr(self, 'current_level') else 1,
                'victory': self.victory,
                'game_over': self.game_over
            }
            self.achievement_manager.check_achievement_progress(game_data)
            
    def draw_dpad(self):
        """Draw an on-screen D-pad for touch/mobile play. Returns dict of direction->Rect."""
        sw, sh = self.screen.get_width(), self.screen.get_height()
        btn = int(min(sw, sh) * 0.10)   # Button size: 10% of smaller dimension
        gap = 4
        bx  = sw - (btn * 3 + gap * 2) - 12   # Bottom-right corner
        by  = sh - (btn * 3 + gap * 2) - 12

        rects = {
            'U': pygame.Rect(bx + btn + gap, by,              btn, btn),
            'L': pygame.Rect(bx,             by + btn + gap,  btn, btn),
            'C': pygame.Rect(bx + btn + gap, by + btn + gap,  btn, btn),  # centre (pause)
            'R': pygame.Rect(bx + btn*2+gap*2, by + btn + gap, btn, btn),
            'D': pygame.Rect(bx + btn + gap, by + btn*2+gap*2, btn, btn),
        }

        # Draw buttons
        for key, rect in rects.items():
            bg  = (60, 70, 90) if key != 'C' else (80, 50, 70)
            pygame.draw.rect(self.screen, bg, rect, border_radius=6)
            pygame.draw.rect(self.screen, (120, 140, 170), rect, width=2, border_radius=6)
            # Draw directional arrow as triangle polygon
            if key in ('U', 'D', 'L', 'R'):
                cx, cy = rect.centerx, rect.centery
                s = int(btn * 0.28)
                if key == 'U':
                    pts = [(cx, cy - s), (cx - s, cy + s//2), (cx + s, cy + s//2)]
                elif key == 'D':
                    pts = [(cx, cy + s), (cx - s, cy - s//2), (cx + s, cy - s//2)]
                elif key == 'L':
                    pts = [(cx - s, cy), (cx + s//2, cy - s), (cx + s//2, cy + s)]
                else:  # R
                    pts = [(cx + s, cy), (cx - s//2, cy - s), (cx - s//2, cy + s)]
                pygame.draw.polygon(self.screen, (220, 230, 255), pts)
            else:
                # Centre = pause symbol (two bars)
                pw, ph = btn//6, btn//2
                pygame.draw.rect(self.screen, (200, 200, 220),
                    (rect.centerx - pw*2, rect.centery - ph//2, pw, ph))
                pygame.draw.rect(self.screen, (200, 200, 220),
                    (rect.centerx + pw,   rect.centery - ph//2, pw, ph))

        return rects

    def handle_input(self, event):
        """Handle player input"""
        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_F8 and DEV_TOOLS.unlocked:
                DEV_TOOLS.open_panel(self.screen, self)
                return True
            event_key = DEV_TOOLS.reverse_direction_key(event.key)
            # User-remapped primary keys share the normalized Settings
            # binding contract; the physical arrows remain permanent fallbacks.
            direction_action = _movement_action_for_key(self.settings, event_key)
            if direction_action == 'up' and self.direction != (0, 1):
                self.next_direction = (0, -1)
            elif direction_action == 'down' and self.direction != (0, -1):
                self.next_direction = (0, 1)
            elif direction_action == 'left' and self.direction != (1, 0):
                self.next_direction = (-1, 0)
            elif direction_action == 'right' and self.direction != (-1, 0):
                self.next_direction = (1, 0)
            # Pause game
            elif event.key == pygame.K_SPACE:
                self.paused = not self.paused
                if getattr(self, 'runtime', None) is not None:
                    self.runtime.set_game_paused(self.paused, {'game': 'singleplayer'})
            # Restart game with R key
            elif event.key == pygame.K_r and (self.game_over or self.victory):
                self.reset_game()
            # Return to main menu with Escape key
            elif event.key == pygame.K_ESCAPE:
                return False
        return True
                
    def activate_powerup(self, powerup_type):
        """Activate a power-up effect"""
        current_time = self._sim_time_ms
        if isinstance(getattr(self, 'powerups_used', None), set):
            self.powerups_used.add(str(powerup_type))
        elif isinstance(getattr(self, 'powerups_used', None), list):
            if powerup_type not in self.powerups_used:
                self.powerups_used.append(powerup_type)
        else:
            self.powerups_used = {str(powerup_type)}
        
        # Add to active power-ups list
        self.active_powerups.append({
            'type': powerup_type,
            'duration': self.powerup_duration,
            'start_time': current_time
        })
        
        # Apply power-up effect
        if powerup_type == 'speed_boost':
            self.speed_multiplier = 0.5  # Half the update time (twice as fast)
        elif powerup_type == 'slow_motion':
            self.speed_multiplier = 2.0  # Double the update time (half speed)
        elif powerup_type == 'size_reduction':
            # Remove one segment from the snake's tail if possible
            if len(self.snake) > 1:
                removed_tail = self.snake.pop()
                _counter_discard(self._snake_set, removed_tail)
        elif powerup_type == 'invincibility':
            self.invincible = True
        elif powerup_type == 'double_points':
            self.points_multiplier = 2.0
        elif powerup_type == 'ghost_mode':
            # Allow passing through the snake's body (but not walls or obstacles)
            self.ghost_mode = True
        elif powerup_type == 'shield':
            # Activate shield to protect against one collision
            self.shield_active = True
    
    def deactivate_powerup(self, powerup_type):
        """An entry of `powerup_type` has just expired (the caller already removed it from active_powerups).

        Power-ups stack: picking up a second Speed Boost while the first is running adds a second entry. An
        effect therefore only ends when NO entry of its kind is left; if the kind is still running its effect is
        re-applied from the entries that remain (for speed, the most recently started one wins, as before)."""
        remaining = sorted(self.active_powerups, key=lambda entry: entry['start_time'])
        kinds = {entry['type'] for entry in remaining}
        if powerup_type in ('speed_boost', 'slow_motion'):
            latest = None
            for entry in remaining:
                if entry['type'] in ('speed_boost', 'slow_motion'):
                    latest = entry['type']
            self.speed_multiplier = 0.5 if latest == 'speed_boost' else (2.0 if latest == 'slow_motion' else 1.0)
        elif powerup_type == 'invincibility':
            self.invincible = 'invincibility' in kinds or bool(getattr(self, '_dev_no_death', False))
        elif powerup_type == 'double_points':
            self.points_multiplier = 2.0 if 'double_points' in kinds else 1.0
        elif powerup_type == 'ghost_mode':
            self.ghost_mode = 'ghost_mode' in kinds
        elif powerup_type == 'shield':
            self.shield_active = bool(self.shield_active) and 'shield' in kinds   # a shield already used up stays used
            
    def level_up(self):
        """Increase board size for level progression"""
        # Save current game state
        old_snake = self.snake.copy()
        old_fruit = self.fruit_position
        old_powerup = self.powerup_position
        old_obstacles = self.obstacles.copy()
        
        # Increase level
        self.current_level += 1
        
        # Increase board size by 2 in both dimensions, up to settings.board_size
        new_width = min(self.settings.board_size, self.board_width + 2)
        new_height = min(self.settings.board_size, self.board_height + 2)
        
        # Update board dimensions
        self.board_width = new_width
        self.board_height = new_height
        
        # Recalculate cell size and board position
        self.cell_size = min(self.screen.get_width(), self.screen.get_height()) // max(self.board_width, self.board_height)
        self.board_offset_x = (self.screen.get_width() - (self.board_width * self.cell_size)) // 2
        self.board_offset_y = (self.screen.get_height() - (self.board_height * self.cell_size)) // 2
        
        # Adjust snake position to be in the center of the new board
        x_offset = (new_width - self.board_width) // 2
        y_offset = (new_height - self.board_height) // 2
        
        # Translate snake to new position
        self.snake = [(x + x_offset, y + y_offset) for x, y in old_snake]
        self._snake_set = _pos_counter(self.snake)
        
        # Translate fruit if it exists
        if old_fruit:
            self.fruit_position = (old_fruit[0] + x_offset, old_fruit[1] + y_offset)
        
        # Translate powerup if it exists
        if old_powerup:
            self.powerup_position = (old_powerup[0] + x_offset, old_powerup[1] + y_offset)
            
        # Regenerate obstacles appropriate for the new board size
        self.obstacles = []
        if self.settings.enable_obstacles:
            # Calculate a proportional increase in obstacles based on new board size
            scale_factor = (new_width * new_height) / (self.board_width * self.board_height)
            new_obstacle_count = min(
                int(len(old_obstacles) * scale_factor),
                (new_width * new_height) // 4  # Cap at 25% of the board
            )
            
            for _ in range(new_obstacle_count):
                available_positions = []
                for x in range(self.board_width):
                    for y in range(self.board_height):
                        pos = (x, y)
                        # Make sure position is not on snake, another obstacle, fruit or powerup
                        if (pos not in self._snake_set and 
                            pos not in self._obstacles_set and 
                            pos != self.fruit_position and
                            pos != self.powerup_position):
                            available_positions.append(pos)
                
                if available_positions:
                    self.obstacles.append(self.rng.choice(available_positions))
                else:
                    break
        self._obstacles_set = _pos_counter(self.obstacles)

        # Add moving obstacles
        if hasattr(self, 'moving_obstacles') and len(self.moving_obstacles) < 3:
            self.add_moving_obstacle()
            
    def add_moving_obstacle(self):
        """Add a new moving obstacle to the game"""
        # Only add moving obstacles if there's room
        if len(self.moving_obstacles) >= 5:
            return
            
        # Find a valid position not occupied by anything else
        available_positions = []
        for x in range(self.board_width):
            for y in range(self.board_height):
                pos = (x, y)
                # Make sure position is not on snake, obstacle, fruit or powerup
                if (pos not in self._snake_set and 
                    pos not in self._obstacles_set and 
                    pos not in [mo['position'] for mo in self.moving_obstacles] and
                    pos != self.fruit_position and
                    pos != self.powerup_position):
                    available_positions.append(pos)
                    
        if available_positions:
            # Choose a random position and movement direction
            position = self.rng.choice(available_positions)
            directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # Down, Right, Up, Left
            direction = self.rng.choice(directions)
            
            # Add the moving obstacle
            self.moving_obstacles.append({
                'position': position,
                'direction': direction,
                'color': self.cosmetic_rng.choice([
                    COLORS['obstacle'],
                    (100, 50, 50),  # Reddish
                    (50, 50, 100)   # Blueish
                ])
            })
            
    def update_moving_obstacles(self):
        """Update positions of moving obstacles"""
        if not hasattr(self, 'moving_obstacles'):
            self.moving_obstacles = []
            return
            
        current_time = self._sim_time_ms

        # Advance one or more simulation intervals if a rendered frame was late.
        while current_time >= self.next_obstacle_move_time:
            self.next_obstacle_move_time += self.obstacle_move_interval

            # Update each moving obstacle.
            for i, obstacle in enumerate(self.moving_obstacles):
                x, y = obstacle['position']
                dx, dy = obstacle['direction']

                # Calculate new position with wrapping.
                new_x = (x + dx) % self.board_width
                new_y = (y + dy) % self.board_height
                new_pos = (new_x, new_y)

                # If new position collides with something, change direction.
                if (new_pos in self.snake or
                    new_pos in self.obstacles or
                    new_pos == self.fruit_position or
                    new_pos == self.powerup_position or
                    new_pos in [mo['position'] for j, mo in enumerate(self.moving_obstacles) if j != i]):
                    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
                    directions.remove(obstacle['direction'])
                    obstacle['direction'] = self.rng.choice(directions)
                else:
                    obstacle['position'] = new_pos
                
    def process_fruit_effect(self):
        """Apply special effects based on fruit type"""
        # Skip if regular fruit or different fruit types disabled
        if not self.settings.fruit_types_enabled or self.current_fruit_type == 'regular':
            return False
            
        # Apply effect based on fruit type
        if self.current_fruit_type == 'golden':
            # Golden apple - double points temporarily (similar to powerup)
            self.activate_powerup('double_points')
            
        elif self.current_fruit_type == 'blue':
            # Blueberry - speed boost
            self.activate_powerup('speed_boost')
            
        elif self.current_fruit_type == 'green':
            # Green apple - extra length (add two segments)
            # Snake already grew by 1 from eating, this adds 1 more
            last_segment = self.snake[-1]
            self.snake.append(last_segment)  # Duplicate the last segment
            _counter_add(self._snake_set, last_segment)
            
        elif self.current_fruit_type == 'orange':
            # Orange - slow motion
            self.activate_powerup('slow_motion')
            
        elif self.current_fruit_type == 'purple':
            # Plum - temporary invincibility
            self.activate_powerup('invincibility')
            
        elif self.current_fruit_type == 'yellow':
            # Lemon - immediate score bonus
            self.score += 20
            
        elif self.current_fruit_type == 'pink':
            # Strawberry - shrink snake
            if len(self.snake) > 3:  # Don't shrink below minimum length
                _counter_discard(self._snake_set, self.snake.pop())  # Remove an extra segment
                _counter_discard(self._snake_set, self.snake.pop())  # Remove another segment (snake already grew by 1)
            
        elif self.current_fruit_type == 'cyan':
            # Cyan berry - reverse controls temporarily
            # This is handled in the input processing
            current_time = self._sim_time_ms
            self.active_powerups.append({
                'type': 'reverse_controls',
                'duration': 5000,  # 5 seconds
                'start_time': current_time
            })
            
        elif self.current_fruit_type == 'lime':
            # Lime - clear some obstacles
            if self.obstacles:
                # Remove up to half of the obstacles
                remove_count = min(len(self.obstacles) // 2, 5)
                for _ in range(remove_count):
                    if self.obstacles:
                        _counter_discard(self._obstacles_set, self.obstacles.pop(self.rng.randrange(len(self.obstacles))))
            
        elif self.current_fruit_type == 'brown':
            # Coconut - teleport snake to random position
            available_positions = []
            for x in range(self.board_width):
                for y in range(self.board_height):
                    pos = (x, y)
                    if (pos not in self.snake[1:] and  # Don't teleport onto snake body (head OK)
                        pos not in self._obstacles_set and
                        pos != self.powerup_position and
                        pos != self.fruit_position):
                        available_positions.append(pos)
                        
            if available_positions:
                _counter_discard(self._snake_set, self.snake[0])
                self.snake[0] = self.rng.choice(available_positions)
                _counter_add(self._snake_set, self.snake[0])
                
        elif self.current_fruit_type == 'teal':
            # Avocado - temporary wall phase
            # Similar to invincibility but only for walls
            current_time = self._sim_time_ms
            self.active_powerups.append({
                'type': 'wall_phase',
                'duration': 8000,  # 8 seconds
                'start_time': current_time
            })
            
        elif self.current_fruit_type == 'coral':
            # Coral - reduce obstacles
            if self.obstacles:
                # Remove a few obstacles
                remove_count = min(3, len(self.obstacles))
                for _ in range(remove_count):
                    if self.obstacles:
                        _counter_discard(self._obstacles_set, self.obstacles.pop(self.rng.randrange(len(self.obstacles))))
                        
        elif self.current_fruit_type == 'olive':
            # Olive - extra life (immunity to next collision)
            current_time = self._sim_time_ms
            self.active_powerups.append({
                'type': 'extra_life',
                'duration': 15000,  # 15 seconds
                'start_time': current_time
            })
            
        elif self.current_fruit_type == 'salmon':
            # Salmon - expand the board
            if self.board_width < self.settings.board_size:
                self.level_up()
                
        # Special effect was applied
        return True
    
    def draw_active_powerups(self):
        """Draw a list of active power-ups and their remaining duration"""
        if not self.active_powerups:
            return
            
        current_time = self._sim_time_ms
        font = get_font(self.settings.language, 'regular', 16)
        y_offset = 120  # Start below pause button
        
        for powerup in self.active_powerups:
            # Get power-up name and color
            if powerup['type'] == 'speed_boost':
                name = get_text(self.settings.language, 'speed_boost')
                color = COLORS['powerup_speed_boost']
            elif powerup['type'] == 'slow_motion':
                name = get_text(self.settings.language, 'slow_motion')
                color = COLORS['powerup_slow_motion']
            elif powerup['type'] == 'size_reduction':
                name = get_text(self.settings.language, 'size_reduction')
                color = COLORS['powerup_size_reduction']
            elif powerup['type'] == 'invincibility':
                name = get_text(self.settings.language, 'invincibility')
                color = COLORS['powerup_invincibility']
            elif powerup['type'] == 'double_points':
                name = get_text(self.settings.language, 'double_points')
                color = COLORS['powerup_double_points']
            elif powerup['type'] == 'ghost_mode':
                name = get_text(self.settings.language, 'ghost_mode') or "Ghost Mode"
                color = (150, 150, 255)  # Light blue color for ghost mode
            elif powerup['type'] == 'shield':
                name = get_text(self.settings.language, 'shield') or "Shield"
                color = (255, 215, 0)  # Gold color for shield
            else:
                continue
                
            # Calculate remaining time
            remaining_ms = powerup['duration'] - (current_time - powerup['start_time'])
            remaining_sec = max(0, int(remaining_ms / 1000))
            
            # Create power-up indicator
            text = f"{name}: {remaining_sec}s"
            powerup_surface = font.render(text, True, color)
            
            # Draw power-up indicator
            self.screen.blit(powerup_surface, (20, y_offset))
            y_offset += 25
    
    def draw_board(self):
        """Draw the game board: the world (optionally supersampled) and the HUD."""
        if graphics_state()['ssaa'] > 1:
            self._draw_board_world_supersampled(graphics_state()['ssaa'])
        else:
            self._draw_board_world()
        self._draw_board_hud()

    def _draw_board_world_supersampled(self, factor):
        """SSAA: draw the board, grid, snake and fruits at `factor` times the
        size and shrink with smoothscale, which smooths every edge. Only the
        world is supersampled; text and HUD stay crisp at their real size."""
        real = self.screen
        width, height = real.get_size()
        big_size = (width * factor, height * factor)
        big = getattr(self, '_ssaa_surface', None)
        if big is None or big.get_size() != big_size:
            big = pygame.Surface(big_size)
            self._ssaa_surface = big
        saved = (self.cell_size, self.board_offset_x, self.board_offset_y)
        try:
            self.screen = big
            self.cell_size = saved[0] * factor
            self.board_offset_x = saved[1] * factor
            self.board_offset_y = saved[2] * factor
            self._ssaa_factor = factor
            self._draw_board_world()
        finally:
            self._ssaa_factor = 1
            self.screen = real
            self.cell_size, self.board_offset_x, self.board_offset_y = saved
        real.blit(pygame.transform.smoothscale(big, (width, height)), (0, 0))

    def _draw_board_world(self):
        background_color, board_color, grid_color = _map_theme_colors(self.settings)
        # Hairlines keep their visual weight when drawn at a larger scale.
        self._ssaa_factor = getattr(self, '_ssaa_factor', 1)
        # Draw background
        self.screen.fill(background_color)
        
        # Draw game board
        board_rect = pygame.Rect(
            self.board_offset_x, 
            self.board_offset_y, 
            self.board_width * self.cell_size, 
            self.board_height * self.cell_size
        )
        pygame.draw.rect(self.screen, board_color, board_rect)
        
        # Draw grid lines
        for x in range(self.board_width + 1):
            pygame.draw.line(
                self.screen, 
                grid_color,
                (self.board_offset_x + x * self.cell_size, self.board_offset_y),
                (self.board_offset_x + x * self.cell_size, self.board_offset_y + self.board_height * self.cell_size),
                self._ssaa_factor
            )

        for y in range(self.board_height + 1):
            pygame.draw.line(
                self.screen, 
                grid_color,
                (self.board_offset_x, self.board_offset_y + y * self.cell_size),
                (self.board_offset_x + self.board_width * self.cell_size, self.board_offset_y + y * self.cell_size),
                self._ssaa_factor
            )
            
        # Draw obstacles if enabled
        if self.settings.enable_obstacles:
            for obstacle in self.obstacles:
                obstacle_rect = pygame.Rect(
                    self.board_offset_x + obstacle[0] * self.cell_size,
                    self.board_offset_y + obstacle[1] * self.cell_size,
                    self.cell_size,
                    self.cell_size
                )
                
                # Draw obstacle with a rock-like appearance
                pygame.draw.rect(self.screen, COLORS.get('obstacle', (100, 100, 100)), obstacle_rect)
                
                # Add some texture to make it look like a rock/wall if cell is big enough
                if self.cell_size > 10:
                    # Draw diagonal lines for texture
                    line_color = COLORS.get('obstacle_highlight', (130, 130, 130))
                    line_width = max(1, self.cell_size // 10)
                    
                    # Draw X pattern
                    pygame.draw.line(
                        self.screen,
                        line_color,
                        (obstacle_rect.left, obstacle_rect.top),
                        (obstacle_rect.right, obstacle_rect.bottom),
                        line_width
                    )
                    pygame.draw.line(
                        self.screen,
                        line_color,
                        (obstacle_rect.left, obstacle_rect.bottom),
                        (obstacle_rect.right, obstacle_rect.top),
                        line_width
                    )
            
        # Draw power-up if present
        if self.powerup_position and self.powerup_type:
            powerup_rect = pygame.Rect(
                self.board_offset_x + self.powerup_position[0] * self.cell_size,
                self.board_offset_y + self.powerup_position[1] * self.cell_size,
                self.cell_size,
                self.cell_size
            )
            
            # Get color based on power-up type
            if self.powerup_type == 'speed_boost':
                color = COLORS['powerup_speed_boost']
            elif self.powerup_type == 'slow_motion':
                color = COLORS['powerup_slow_motion']
            elif self.powerup_type == 'size_reduction':
                color = COLORS['powerup_size_reduction']
            elif self.powerup_type == 'invincibility':
                color = COLORS['powerup_invincibility']
            elif self.powerup_type == 'double_points':
                color = COLORS['powerup_double_points']
            elif self.powerup_type == 'ghost_mode':
                color = COLORS['powerup_ghost_mode']
            elif self.powerup_type == 'shield':
                color = COLORS['powerup_shield']
            else:
                color = COLORS['white']
                
            # Draw power-up as a diamond shape
            if self.cell_size > 10:  # Only draw special shape if cell size is big enough
                center_x = powerup_rect.x + powerup_rect.width // 2
                center_y = powerup_rect.y + powerup_rect.height // 2
                size = min(powerup_rect.width, powerup_rect.height) // 2 - 2
                
                # Draw diamond shape (4 points)
                points = [
                    (center_x, center_y - size),  # Top
                    (center_x + size, center_y),  # Right
                    (center_x, center_y + size),  # Bottom
                    (center_x - size, center_y)   # Left
                ]
                
                pygame.draw.polygon(self.screen, color, points)
            else:
                # Small cell size, just draw a colored square
                pygame.draw.rect(self.screen, color, powerup_rect)
            
        # Draw fruit with correct type coloring
        if self.fruit_position:
            fruit_rect = pygame.Rect(
                self.board_offset_x + self.fruit_position[0] * self.cell_size,
                self.board_offset_y + self.fruit_position[1] * self.cell_size,
                self.cell_size,
                self.cell_size
            )
            
            # Check if we have fruit types enabled
            if hasattr(self, 'current_fruit_type') and self.settings.fruit_types_enabled:
                # Use textured fruits if cells are large enough
                if self.cell_size >= 10:
                    dev_fruit_type = getattr(DEV_TOOLS, '_next_preview', None) if DEV_TOOLS.cheats.get('rainbow_items') else self.current_fruit_type
                    if DEV_TOOLS.cheats.get('everything_apple'):
                        dev_fruit_type = 'regular'
                    dev_rect = fruit_rect
                    if DEV_TOOLS.cheats.get('giant_fruits'):
                        dev_rect = fruit_rect.inflate(max(2, self.cell_size // 2), max(2, self.cell_size // 2))
                    elif DEV_TOOLS.cheats.get('tiny_fruits'):
                        dev_rect = fruit_rect.inflate(-max(2, self.cell_size // 3), -max(2, self.cell_size // 3))
                    draw_fruit(self.screen, dev_rect, dev_fruit_type)
                else:
                    # For very small cells, use simple colored circles
                    center_x = fruit_rect.centerx
                    center_y = fruit_rect.centery
                    radius = self.cell_size // 2 - 1
                    
                    # Get color based on fruit type
                    fruit_color = get_fruit_color(self.current_fruit_type)
                    pygame.draw.circle(self.screen, fruit_color, (center_x, center_y), radius)
            else:
                # Just draw a regular fruit (red square)
                pygame.draw.rect(self.screen, COLORS.get('fruit', (255, 0, 0)), fruit_rect)
                    
            # Show combo indicator if combo is active and cell is big enough
            if (hasattr(self, 'combo_count') and self.combo_count > 1 and 
                self.settings.combo_fruits_enabled and self.cell_size > 15):
                combo_font = get_font(self.settings.language, 'bold', max(10, self.cell_size // 3))
                combo_text = f"{self.combo_count}x"
                text_surface = combo_font.render(combo_text, True, (255, 255, 255))
                self.screen.blit(text_surface, (fruit_rect.right - text_surface.get_width() - 2, 
                                               fruit_rect.top + 2))
                                               
        # Draw moving obstacles
        if hasattr(self, 'moving_obstacles'):
            for mo in self.moving_obstacles:
                mo_rect = pygame.Rect(
                    self.board_offset_x + mo['position'][0] * self.cell_size,
                    self.board_offset_y + mo['position'][1] * self.cell_size,
                    self.cell_size,
                    self.cell_size
                )
                
                # Draw obstacle with its color
                pygame.draw.rect(self.screen, mo['color'], mo_rect)
                
                # Add arrow to show movement direction if cell is big enough
                if self.cell_size > 15:
                    dx, dy = mo['direction']
                    
                    # Calculate arrow points
                    center_x = mo_rect.centerx
                    center_y = mo_rect.centery
                    arrow_size = max(5, self.cell_size // 4)
                    
                    # Arrow head position
                    head_x = center_x + dx * arrow_size
                    head_y = center_y + dy * arrow_size
                    
                    # Arrow tail position (opposite direction)
                    tail_x = center_x - dx * arrow_size
                    tail_y = center_y - dy * arrow_size
                    
                    # Draw the arrow
                    pygame.draw.line(self.screen, (0, 0, 0), (tail_x, tail_y), (head_x, head_y), 2)
                    
                    # Draw arrowhead
                    if dx == 0:  # Vertical arrow
                        if dy > 0:  # Down
                            pygame.draw.line(self.screen, (0, 0, 0), (head_x, head_y), (head_x - 3, head_y - 5), 2)
                            pygame.draw.line(self.screen, (0, 0, 0), (head_x, head_y), (head_x + 3, head_y - 5), 2)
                        else:  # Up
                            pygame.draw.line(self.screen, (0, 0, 0), (head_x, head_y), (head_x - 3, head_y + 5), 2)
                            pygame.draw.line(self.screen, (0, 0, 0), (head_x, head_y), (head_x + 3, head_y + 5), 2)
                    else:  # Horizontal arrow
                        if dx > 0:  # Right
                            pygame.draw.line(self.screen, (0, 0, 0), (head_x, head_y), (head_x - 5, head_y - 3), 2)
                            pygame.draw.line(self.screen, (0, 0, 0), (head_x, head_y), (head_x - 5, head_y + 3), 2)
                        else:  # Left
                            pygame.draw.line(self.screen, (0, 0, 0), (head_x, head_y), (head_x + 5, head_y - 3), 2)
                            pygame.draw.line(self.screen, (0, 0, 0), (head_x, head_y), (head_x + 5, head_y + 3), 2)
            
        # Draw portals if enabled and exist
        if hasattr(self, 'portals') and self.portals and hasattr(self.settings, 'enable_portals') and self.settings.enable_portals:
            for portal_pair in self.portals:
                portal1, portal2, pair_id = portal_pair
                
                # Draw first portal
                portal1_rect = pygame.Rect(
                    self.board_offset_x + portal1[0] * self.cell_size,
                    self.board_offset_y + portal1[1] * self.cell_size,
                    self.cell_size,
                    self.cell_size
                )
                
                # Draw second portal
                portal2_rect = pygame.Rect(
                    self.board_offset_x + portal2[0] * self.cell_size,
                    self.board_offset_y + portal2[1] * self.cell_size,
                    self.cell_size,
                    self.cell_size
                )
                
                # Get portal colors from settings or use defaults
                portal_color_1 = getattr(self.settings, 'portal_color_1', (0, 100, 255))  # Blue default
                portal_color_2 = getattr(self.settings, 'portal_color_2', (255, 165, 0))  # Orange default
                
                # Draw circular portals with a glowing effect
                if self.cell_size > 10:
                    # Draw outer glow
                    pygame.draw.ellipse(self.screen, portal_color_1, portal1_rect.inflate(4, 4))
                    pygame.draw.ellipse(self.screen, portal_color_2, portal2_rect.inflate(4, 4))
                    
                    # Draw main portal
                    pygame.draw.ellipse(self.screen, portal_color_1, portal1_rect)
                    pygame.draw.ellipse(self.screen, portal_color_2, portal2_rect)
                    
                    # Draw inner swirl for portal1 (a small spiral)
                    center1 = portal1_rect.center
                    radius1 = self.cell_size // 4
                    pygame.draw.arc(self.screen, (255, 255, 255), 
                                   (center1[0] - radius1, center1[1] - radius1, 
                                    radius1 * 2, radius1 * 2), 
                                   0, 3.14, 2)
                                   
                    # Draw inner swirl for portal2 (a small spiral)
                    center2 = portal2_rect.center
                    radius2 = self.cell_size // 4
                    pygame.draw.arc(self.screen, (255, 255, 255), 
                                   (center2[0] - radius2, center2[1] - radius2, 
                                    radius2 * 2, radius2 * 2), 
                                   0, 3.14, 2)
                else:
                    # For smaller cells, just draw filled circles
                    pygame.draw.ellipse(self.screen, portal_color_1, portal1_rect)
                    pygame.draw.ellipse(self.screen, portal_color_2, portal2_rect)
                    
        self._draw_daily_ghost()

        # Draw snake with special effects for powerups
        # Body colour of the skin and its brighter head (shared with the Skins preview).
        snake_color, head_color = _skin_colors(self._active_skin, self.settings.snake_color)
        dev_scale = 1.45 if DEV_TOOLS.cheats.get('giant_snake') else (0.65 if DEV_TOOLS.cheats.get('tiny_snake') else 1.0)
        dev_invisible = DEV_TOOLS.cheats.get('invisible_snake')
        
        # Apply visual effects for active powerups
        # Ghost mode: Semi-transparent snake
        if self.ghost_mode:
            # Create a lighter, semi-transparent version of the snake color
            r, g, b = snake_color
            snake_color = (min(r + 50, 255), min(g + 50, 255), min(b + 50, 255))
            # For the head too
            r, g, b = head_color
            head_color = (min(r + 50, 255), min(g + 50, 255), min(b + 50, 255))
        
        # Shield: Gold outline around snake
        shield_active = self.shield_active
        
        for i, segment in enumerate(self.snake):
            snake_rect = pygame.Rect(
                self.board_offset_x + segment[0] * self.cell_size,
                self.board_offset_y + segment[1] * self.cell_size,
                self.cell_size,
                self.cell_size
            )
            if dev_scale != 1.0:
                scaled = max(2, int(self.cell_size * dev_scale))
                snake_rect = pygame.Rect(snake_rect.centerx - scaled // 2, snake_rect.centery - scaled // 2, scaled, scaled)
            
            if shield_active and not dev_invisible:
                # Draw gold shield outline
                shield_rect = snake_rect.inflate(4, 4)
                pygame.draw.rect(self.screen, COLORS['powerup_shield'], shield_rect, 2)
            
            if i == 0:  # Head - make it distinctive with eyes and a different shape
                # Draw head with slightly larger size to make it stand out
                if not dev_invisible:
                    pygame.draw.rect(self.screen, head_color, snake_rect)
                
                # Draw eyes on the head based on direction
                eye_size = max(4, self.cell_size // 5)
                eye_offset = max(3, self.cell_size // 6)
                eye_color = (255, 255, 255)  # White eyes
                pupil_color = (0, 0, 0)      # Black pupils
                
                # Left eye position based on direction
                if self.direction == (1, 0):  # Right
                    left_eye = (snake_rect.right - eye_offset*2, snake_rect.y + eye_offset)
                    right_eye = (snake_rect.right - eye_offset*2, snake_rect.bottom - eye_offset - eye_size)
                elif self.direction == (-1, 0):  # Left
                    left_eye = (snake_rect.x + eye_offset, snake_rect.y + eye_offset)
                    right_eye = (snake_rect.x + eye_offset, snake_rect.bottom - eye_offset - eye_size)
                elif self.direction == (0, -1):  # Up
                    left_eye = (snake_rect.x + eye_offset, snake_rect.y + eye_offset)
                    right_eye = (snake_rect.right - eye_offset - eye_size, snake_rect.y + eye_offset)
                else:  # Down or default
                    left_eye = (snake_rect.x + eye_offset, snake_rect.bottom - eye_offset*2)
                    right_eye = (snake_rect.right - eye_offset - eye_size, snake_rect.bottom - eye_offset*2)
                
                # Draw eyes
                
                if not dev_invisible:
                    pygame.draw.rect(self.screen, eye_color, pygame.Rect(left_eye[0], left_eye[1], eye_size, eye_size))
                    pygame.draw.rect(self.screen, eye_color, pygame.Rect(right_eye[0], right_eye[1], eye_size, eye_size))
                
                # Draw pupils (smaller rectangle inside eyes)
                pupil_size = max(2, eye_size // 2)
                pupil_offset = (eye_size - pupil_size) // 2
                if not dev_invisible:
                    pygame.draw.rect(self.screen, pupil_color,
                                    pygame.Rect(left_eye[0] + pupil_offset, left_eye[1] + pupil_offset,
                                               pupil_size, pupil_size))
                    pygame.draw.rect(self.screen, pupil_color,
                                    pygame.Rect(right_eye[0] + pupil_offset, right_eye[1] + pupil_offset,
                                               pupil_size, pupil_size))
                
            elif i == len(self.snake) - 1:  # Tail - make it slightly smaller
                # Make the tail slightly tapered
                tail_margin = max(1, self.cell_size // 8)
                tail_rect = pygame.Rect(
                    snake_rect.x + tail_margin,
                    snake_rect.y + tail_margin,
                    snake_rect.width - (tail_margin * 2),
                    snake_rect.height - (tail_margin * 2)
                )
                if not dev_invisible:
                    pygame.draw.rect(self.screen, snake_color, tail_rect)
            else:  # Body
                if not dev_invisible:
                    if self._active_skin == 'rainbow' or DEV_TOOLS.cheats.get('rainbow_snake') or DEV_TOOLS.cheats.get('disco_snake'):
                        colour = _rainbow_skin_color(i, 3.0 if DEV_TOOLS.cheats.get('disco_snake') else 1.2)
                    else:
                        colour = snake_color
                    pygame.draw.rect(self.screen, colour, snake_rect)
        
    def _draw_board_hud(self):
        """Score, challenge label, player name and the pause overlay."""
        # Draw score
        font = get_font(self.settings.language, 'bold', 24)
        score_text = get_text(self.settings.language, 'score') + f": {self.score}"
        score_surface = font.render(score_text, True, COLORS['white'])
        self.screen.blit(score_surface, (20, 20))

        if isinstance(getattr(self, '_sgf_daily_challenge', None), dict):
            challenge_label = get_text(self.settings.language, 'daily_challenge')
            if getattr(self, '_sgf_ghost_history', None):
                challenge_label += ' · ' + get_text(
                    self.settings.language, 'daily_ghost_race')
            challenge_surface = render_fit(
                get_font(self.settings.language, 'bold', 14), challenge_label,
                COLORS['gold'], max(80, self.screen.get_width() // 3))
            self.screen.blit(challenge_surface,
                challenge_surface.get_rect(center=(self.screen.get_width() // 2, 28)))
        self._draw_ghost_hud()
        
        # Draw player name
        name_surface = font.render(self.player_name, True, COLORS['white'])
        self.screen.blit(name_surface, (self.screen.get_width() - name_surface.get_width() - 20, 20))
        
        # Draw pause indicator
        if self.paused:
            pause_font = get_font(self.settings.language, 'bold', 36)
            pause_text = get_text(self.settings.language, 'paused')
            pause_surface = pause_font.render(pause_text, True, COLORS['white'])
            pause_rect = pause_surface.get_rect(center=(self.screen.get_width() // 2, self.screen.get_height() // 2))
            
            # Draw semi-transparent background
            overlay = pygame.Surface((self.screen.get_width(), self.screen.get_height()), pygame.SRCALPHA)
            overlay.fill((0, 0, 0, 128))
            self.screen.blit(overlay, (0, 0))
            
            # Draw pause text
            self.screen.blit(pause_surface, pause_rect)
            
            # Draw resume instructions
            resume_font = get_font(self.settings.language, 'regular', 24)
            resume_text = get_text(self.settings.language, 'press_space_to_resume')
            resume_surface = resume_font.render(resume_text, True, COLORS['white'])
            resume_rect = resume_surface.get_rect(center=(self.screen.get_width() // 2, self.screen.get_height() // 2 + 60))
            self.screen.blit(resume_surface, resume_rect)
            
    def _draw_ghost_hud(self):
        """Race readout: ghost score/target, score difference and pace in seconds."""
        history = getattr(self, '_sgf_ghost_history', None)
        if not history or getattr(self, 'replay_mode', False):
            return
        tick = max(0, len(self.game_history) - 1)
        ghost_score = _ghost_score_at(history, tick)
        final_score = _ghost_final_score(history)
        if ghost_score is None or final_score is None:
            return
        language = self.settings.language
        font = get_font(language, 'bold', 15)
        difference = int(self.score) - ghost_score
        ahead = difference >= 0
        colour = (120, 235, 150) if ahead else (255, 200, 110)
        text = (f"{get_text(language, 'daily_ghost_race')}: "
                f"{ghost_score}/{final_score}  ({difference:+d})")
        max_width = max(120, self.screen.get_width() // 2 - 30)
        surface = render_fit(font, text, colour, max_width, padding=0)
        self.screen.blit(surface, (20, 54))
        pace = _ghost_pace_ticks(history, int(self.score), tick)
        if pace is not None:
            seconds = pace * float(getattr(self.settings, 'update_rate_ms', 150)) / 1000.0
            pace_surface = render_fit(
                font, f"{seconds:+.1f} s", (120, 235, 150) if seconds >= 0 else (255, 200, 110),
                max_width, padding=0)
            self.screen.blit(pace_surface, (20, 54 + surface.get_height() + 2))

    def _draw_daily_ghost(self):
        history = getattr(self, '_sgf_ghost_history', None)
        if not history or getattr(self, 'replay_mode', False):
            return
        ghost = _daily_ghost_frame(
            history, max(0, len(self.game_history) - 1),
            self.board_width, self.board_height)
        if not ghost:
            return
        size = (self.board_width * self.cell_size,
                self.board_height * self.cell_size)
        surface = getattr(self, '_sgf_ghost_surface', None)
        if surface is None or surface.get_size() != size:
            surface = pygame.Surface(size, pygame.SRCALPHA)
            self._sgf_ghost_surface = surface
        frame_key = (max(0, len(self.game_history) - 1), tuple(ghost))
        if getattr(self, '_sgf_ghost_rendered_key', None) != frame_key:
            surface.fill((0, 0, 0, 0))
            inset = max(1, self.cell_size // 8)
            for index, (x, y) in enumerate(ghost):
                rect = pygame.Rect(
                    x * self.cell_size + inset, y * self.cell_size + inset,
                    max(1, self.cell_size - 2 * inset),
                    max(1, self.cell_size - 2 * inset))
                color = (185, 245, 255, 145) if index == 0 else (70, 195, 245, 82)
                pygame.draw.rect(surface, color, rect,
                                 border_radius=max(1, self.cell_size // 5))
            self._sgf_ghost_rendered_key = frame_key
        self.screen.blit(surface, (self.board_offset_x, self.board_offset_y))

    def draw_game_over(self):
        """Draw game over screen"""
        music = globals().get('_SOUND_MGR')
        if music is not None and music._bgm_volume > 0:
            music.set_music_context('game_over')
        overlay = pygame.Surface((self.screen.get_width(), self.screen.get_height()), pygame.SRCALPHA)
        overlay.fill((0, 0, 0, 192))
        self.screen.blit(overlay, (0, 0))
        
        sw, sh = self.screen.get_width(), self.screen.get_height()

        # Game over text
        game_over_font = get_font(self.settings.language, 'bold', 48)
        if self.victory:
            game_over_text = get_text(self.settings.language, 'victory')
            text_color = COLORS['victory']
        else:
            game_over_text = get_text(self.settings.language, 'game_over')
            text_color = COLORS['game_over']
            
        game_over_surface = game_over_font.render(game_over_text, True, text_color)
        game_over_rect = game_over_surface.get_rect(center=(sw // 2, sh // 2 - 90))
        self.screen.blit(game_over_surface, game_over_rect)
        
        # Score text
        score_font = get_font(self.settings.language, 'bold', 28)
        score_text = get_text(self.settings.language, 'final_score') + f": {self.score}"
        score_surface = score_font.render(score_text, True, COLORS['white'])
        score_rect = score_surface.get_rect(center=(sw // 2, sh // 2 - 40))
        self.screen.blit(score_surface, score_rect)

        # Show seed so the player can replay or share this map
        seed_font = get_font(self.settings.language, 'regular', 20)
        seed_surface = seed_font.render(f"{get_text(self.settings.language, 'seed_label')}: {self.seed}", True, (120, 150, 200))
        seed_rect = seed_surface.get_rect(center=(sw // 2, sh // 2))
        self.screen.blit(seed_surface, seed_rect)

        # --- Touch/mouse buttons — Play Again, Menu, Copy Seed, (View Replay) ---
        has_replay = bool(self.game_history)
        n_buttons = 4 if has_replay else 3
        gap = int(sw * 0.02)
        margin = int(sw * 0.04)
        available = sw - margin * 2 - gap * (n_buttons - 1)
        btn_w = max(90, min(220, available // n_buttons))
        btn_h = max(40, int(sh * 0.07))
        total_w = n_buttons * btn_w + (n_buttons - 1) * gap
        start_x = sw // 2 - total_w // 2
        by = sh // 2 + 40

        buttons = {}
        labels = [
            ('play_again', get_text(self.settings.language, 'play_again'), COLORS['green']),
            ('menu', get_text(self.settings.language, 'menu'), COLORS['button']),
            ('copy_seed', get_text(self.settings.language, 'copy_seed'), (100, 130, 200)),
        ]
        if has_replay:
            labels.append(('view_replay', get_text(self.settings.language, 'view_replay'), (170, 45, 170)))

        btn_font = get_font(self.settings.language, 'bold', max(14, int(sh * 0.025)))
        for i, (key, label, color) in enumerate(labels):
            rect = pygame.Rect(start_x + i * (btn_w + gap), by, btn_w, btn_h)
            pygame.draw.rect(self.screen, color, rect, border_radius=8)
            pygame.draw.rect(self.screen, COLORS['white'], rect, width=1, border_radius=8)
            text_surf = btn_font.render(label, True, COLORS['white'])
            max_w = rect.width - 14
            if text_surf.get_width() > max_w and text_surf.get_width() > 0:
                scale = max_w / text_surf.get_width()
                new_size = (max_w, max(1, int(text_surf.get_height() * scale)))
                text_surf = pygame.transform.smoothscale(text_surf, new_size)
            self.screen.blit(text_surf, text_surf.get_rect(center=rect.center))
            buttons[key] = rect

        self._go_buttons = buttons

        _draw_replay_save_widget(self.screen, self.settings.language,
                                    getattr(self, '_replay_save_game_id', None), sw // 2, 8)

        # Brief "Copied!" confirmation after using the Copy Seed button
        if getattr(self, '_seed_copied_until', 0) > time.time():
            note_font = get_font(self.settings.language, 'regular', 18)
            note = note_font.render(get_text(self.settings.language, 'seed_copied'), True, (140, 220, 140))
            self.screen.blit(note, note.get_rect(center=(sw // 2, by + btn_h + 26)))

        # Keyboard-shortcut hints still shown for desktop users
        instr_font = get_font(self.settings.language, 'regular', 16)
        instr_text = get_text(self.settings.language, 'press_r_to_restart')
        instr_surface = instr_font.render(instr_text, True, (160, 160, 175))
        self.screen.blit(instr_surface, instr_surface.get_rect(center=(sw // 2, by + btn_h + 50)))
        instr2_text = get_text(self.settings.language, 'press_esc_to_menu')
        instr2_surface = instr_font.render(instr2_text, True, (160, 160, 175))
        self.screen.blit(instr2_surface, instr2_surface.get_rect(center=(sw // 2, by + btn_h + 72)))
        
    def save_score(self):
        """Save the player's score to high scores if it's high enough"""
        _flush_encyclopedia_updates(getattr(self, '_enc_updates', {}))
        self._enc_updates = {}  # avoid double-flushing if save_score() is somehow called twice

        _award_game_xp_async(self, 'singleplayer')

        if self.score <= 0:
            return
            
        # Generate unique ID for this game
        game_id = f"{int(time.time())}-{self.rng.randint(1000, 9999)}"
            
        # Create a dictionary with serializable settings
        settings_dict = {}
        for key, value in vars(self.settings).items():
            # Only include serializable settings (skip complex objects, functions, etc.)
            if isinstance(value, (int, float, str, bool, list, dict)) and value is not None:
                settings_dict[key] = value
        
        # Add current score to highscores with detailed settings
        score_entry = {
            'name': self.player_name if self.player_name else get_text(self.settings.language, 'unnamed_player'),
            'score': self.score,
            'date': datetime.now().strftime('%Y-%m-%d %H:%M'),
            'timestamp': datetime.now().isoformat(),
            'board_size': self.settings.board_size,
            'update_rate_ms': self.settings.update_rate_ms,
            'victory': self.victory,
            'wall_collision': self.settings.wall_collision,
            'powerups_enabled': self.settings.powerups_enabled,
            'fruit_types_enabled': self.settings.fruit_types_enabled,
            'obstacles_enabled': self.settings.enable_obstacles,
            'portals_enabled': self.settings.enable_portals,
            'portal_pairs': self.settings.portal_pairs if self.settings.enable_portals else 0,
            'seed': self.seed,
            'replay_format_version': _REPLAY_FORMAT_VERSION,
            'game_id': game_id,
            'has_replay': False,
            'settings': settings_dict,
            'custom_map': self.custom_map,  # moved into the replay file when one exists
            'actual_board_width': self.board_width,
            'actual_board_height': self.board_height,
        }
        _daily = getattr(self, '_sgf_daily_challenge', None)
        if isinstance(_daily, dict):
            score_entry.update({
                'daily_challenge_id': _daily['challenge_id'],
                'daily_challenge_version': _daily['challenge_version'],
                'daily_challenge_modifier': _daily['modifier'],
                'game_mode': 'daily_challenge',
            })
        _custom_challenge = getattr(self, '_sgf_custom_challenge', None)
        if isinstance(_custom_challenge, dict):
            score_entry.update({
                'custom_challenge_id': _custom_challenge['challenge_id'],
                'custom_challenge_version': _custom_challenge['challenge_version'],
                'game_mode': 'custom_challenge',
            })
        self._replay_save_game_id = _queue_completed_score(
            score_entry, self.game_history, max_records=10)
            
    def draw_pause_button(self):
        """Draw the pause button"""
        if not self.game_over and not self.victory:
            button_rect = pygame.Rect(self.screen.get_width() - 60, 70, 40, 40)
            pygame.draw.rect(self.screen, COLORS['button'], button_rect, border_radius=5)
            
            # Draw pause or play icon based on game state
            if self.paused:
                # Draw play triangle
                pygame.draw.polygon(self.screen, COLORS['white'], [
                    (button_rect.x + 12, button_rect.y + 10),
                    (button_rect.x + 12, button_rect.y + 30),
                    (button_rect.x + 32, button_rect.y + 20)
                ])
            else:
                # Draw pause bars
                pygame.draw.rect(self.screen, COLORS['white'], 
                    (button_rect.x + 12, button_rect.y + 10, 6, 20))
                pygame.draw.rect(self.screen, COLORS['white'], 
                    (button_rect.x + 24, button_rect.y + 10, 6, 20))
                
            return button_rect
        return None
    
    # ------------------------------------------------------------------
    # REPLAY SYSTEM  – compact snapshot-based recording and playback
    # ------------------------------------------------------------------

    def _snap(self):
        """Create a compact, JSON-serialisable snapshot of the current game state.

        Format (12-element list – indices must stay stable):
          [snake, fruit_pos, fruit_type, score, direction,
           powerup_pos, powerup_type, active_pu_data, obstacles, portals,
           effect_state, fruit_value]

        active_pu_data: list of [type_str, remaining_ms]   (index 7)
        effect_state:   [speed_multiplier, points_multiplier,
                         invincible, ghost_mode, shield_active,
                         length_speed_multiplier]            (index 10)
        fruit_value:    int                                  (index 11)
        """
        current_time = self._sim_time_ms
        pu_data = []
        if hasattr(self, 'active_powerups'):
            for p in self.active_powerups:
                remaining = max(0.0, p['duration'] - (current_time - p['start_time']))
                pu_data.append([p['type'], remaining])
        # Cells and the obstacle list are shared between snapshots instead of copied again every move: a
        # recording keeps one list per distinct cell, so a long game costs a fraction of the memory.
        cell_cache = self.__dict__.setdefault('_snap_cell_cache', {})
        snake_cells = []
        for s in self.snake:
            key = (s[0], s[1])
            cell = cell_cache.get(key)
            if cell is None:
                cell = cell_cache[key] = [s[0], s[1]]
            snake_cells.append(cell)
        if self.obstacles:
            obstacle_key = tuple(tuple(o) for o in self.obstacles)
            if obstacle_key != self.__dict__.get('_snap_obstacle_key'):
                self._snap_obstacle_key = obstacle_key
                self._snap_obstacle_list = [list(o) for o in self.obstacles]
            obstacle_cells = self._snap_obstacle_list
        else:
            obstacle_cells = []
        return [
            snake_cells,                                                    # 0
            list(self.fruit_position) if self.fruit_position else None,    # 1
            getattr(self, 'current_fruit_type', 'regular'),               # 2
            self.score,                                                     # 3
            list(self.direction),                                          # 4
            list(self.powerup_position) if self.powerup_position else None,# 5
            getattr(self, 'powerup_type', None),                          # 6
            pu_data,                                                        # 7 [[type, remaining_ms], ...]
            obstacle_cells,                                                 # 8
            [[list(p[0]), list(p[1]), p[2]] for p in self.portals]        # 9
            if self.portals else [],
            [                                                               # 10 effect_state
                getattr(self, 'speed_multiplier',        1.0),
                getattr(self, 'points_multiplier',       1.0),
                getattr(self, 'invincible',              False),
                getattr(self, 'ghost_mode',              False),
                getattr(self, 'shield_active',           False),
                getattr(self, 'length_speed_multiplier', 1.0),
            ],
            getattr(self, 'current_fruit_value', 1),                      # 11 fruit_value
        ]

    def _load_snap(self, snap):
        """Restore game state from a compact snapshot (for replay playback).

        Supports both:
          - Old format (10 elements): index 7 is a list of type strings
          - New format (12 elements): index 7 is [[type, remaining_ms], ...],
            index 10 is effect_state, index 11 is fruit_value
        """
        self.snake            = [tuple(s) for s in snap[0]]
        self._snake_set       = _pos_counter(self.snake)
        self.fruit_position   = tuple(snap[1]) if snap[1] else None
        self.current_fruit_type  = snap[2] if len(snap) > 2 else 'regular'
        self.score            = snap[3] if len(snap) > 3 else 0
        self.direction        = tuple(snap[4]) if len(snap) > 4 else (1, 0)
        self.next_direction   = self.direction
        self.powerup_position = tuple(snap[5]) if (len(snap) > 5 and snap[5]) else None
        self.powerup_type     = snap[6] if len(snap) > 6 else None

        # Restore active powerups with correct remaining time.
        # New format: [[type_str, remaining_ms], ...]
        # Old format: [type_str, ...]  — assume full 10 s duration for display
        current_time = self._sim_time_ms
        pu_raw = snap[7] if len(snap) > 7 else []
        self.active_powerups = []
        for entry in pu_raw:
            if isinstance(entry, list):
                pu_type      = entry[0]
                remaining_ms = max(0.0, float(entry[1]))
            else:
                pu_type      = entry          # old format: bare string
                remaining_ms = 10000.0        # assume 10 s left for display
            self.active_powerups.append({
                'type':       pu_type,
                'start_time': current_time,
                'duration':   remaining_ms,
            })

        self.obstacles = [tuple(o) for o in snap[8]] \
            if len(snap) > 8 and snap[8] else []
        self._obstacles_set = _pos_counter(self.obstacles)
        self.portals   = [(tuple(p[0]), tuple(p[1]), p[2]) for p in snap[9]] \
            if len(snap) > 9 and snap[9] else []

        # ── Restore effect-state flags (index 10, new format) ──────────────
        active_types = {p['type'] for p in self.active_powerups}
        if len(snap) > 10 and snap[10]:
            fx = snap[10]
            self.speed_multiplier        = float(fx[0]) if len(fx) > 0 else 1.0
            self.points_multiplier       = float(fx[1]) if len(fx) > 1 else 1.0
            self.invincible              = bool(fx[2])   if len(fx) > 2 else False
            self.ghost_mode              = bool(fx[3])   if len(fx) > 3 else False
            self.shield_active           = bool(fx[4])   if len(fx) > 4 else False
            self.length_speed_multiplier = float(fx[5]) if len(fx) > 5 else 1.0
        else:
            # Old format — derive best-guess effect state from active types
            if 'speed_boost' in active_types:
                self.speed_multiplier = 0.5
            elif 'slow_motion' in active_types:
                self.speed_multiplier = 2.0
            else:
                self.speed_multiplier = 1.0
            self.points_multiplier       = 2.0 if 'double_points'  in active_types else 1.0
            self.invincible              = 'invincibility' in active_types
            self.ghost_mode              = 'ghost_mode'    in active_types
            self.shield_active           = 'shield'        in active_types
            self.length_speed_multiplier = 1.0

        # ── Fruit value (index 11, new format) ────────────────────────────
        self.current_fruit_value = snap[11] if len(snap) > 11 else 1

        self.game_over = False
        self.victory   = False

    def start_replay(self, game_history):
        """Enter replay mode from a saved list of compact snapshots."""
        if not game_history:
            return False
        self.replay_mode  = True
        self.game_history = game_history
        self.replay_index = 0
        self.replay_speed = 1.0
        self.paused       = False
        self._replay_ended = False
        self._replay_ctrl_rects = {}
        self._replay_seek_held = None    # 'rewind' | 'ff' | None — for hold-to-repeat seeking
        self._replay_hold_start = 0
        self._replay_last_repeat = 0
        self._load_snap(self.game_history[0])
        return True

    def _replay_seek_repeat_interval(self, held_duration):
        """Accelerating repeat interval for hold-to-seek: starts leisurely,
        speeds up the longer the button/key is held, caps out fast but not
        so fast it feels uncontrollable."""
        if held_duration < 0.5:
            return 0.30
        elif held_duration < 1.2:
            return 0.15
        elif held_duration < 2.5:
            return 0.08
        else:
            return 0.04

    def _replay_process_held_seek(self):
        """Called once per frame: if rewind/ff is being held (mouse button
        down or arrow key down), repeat the seek at an accelerating rate."""
        if not self.replay_mode or not getattr(self, '_replay_seek_held', None):
            return
        now = time.time()
        held_duration = now - self._replay_hold_start
        interval = self._replay_seek_repeat_interval(held_duration)
        if now - self._replay_last_repeat >= interval:
            self._replay_last_repeat = now
            steps = max(1, len(self.game_history) // 10)
            if self._replay_seek_held == 'ff':
                self.replay_index = min(len(self.game_history) - 1, self.replay_index + steps)
                self._load_snap(self.game_history[self.replay_index])
                self._replay_ended = (self.replay_index >= len(self.game_history) - 1)
            else:  # 'rewind'
                self._replay_step_back(steps)
                self._replay_ended = False

    def replay_next_frame(self):
        """Advance replay by one frame. Returns False when at the last frame."""
        if not self.replay_mode or self.replay_index >= len(self.game_history) - 1:
            return False
        # Remember which powerup types are active before we advance
        prev_types = {p['type'] for p in self.active_powerups}
        self.replay_index += 1
        self._load_snap(self.game_history[self.replay_index])
        # Play the powerup sound for any powerup that newly appeared this frame
        new_types = {p['type'] for p in self.active_powerups}
        if new_types - prev_types:
            sounds().play('powerup')
        return True

    def _replay_step_back(self, steps=1):
        """Step back N frames in the replay."""
        self.replay_index = max(0, self.replay_index - steps)
        self._load_snap(self.game_history[self.replay_index])

    def _replay_seek(self, fraction):
        """Jump to a position in the replay (fraction 0.0–1.0)."""
        if not self.game_history:
            return
        idx = int(fraction * (len(self.game_history) - 1))
        self.replay_index = max(0, min(len(self.game_history) - 1, idx))
        self._load_snap(self.game_history[self.replay_index])
        self._replay_ended = (self.replay_index >= len(self.game_history) - 1)

    def replay_handle_click(self, pos):
        """Handle a mouse click on the replay control panel."""
        if not self.replay_mode or not hasattr(self, '_replay_ctrl_rects'):
            return False
        rects = self._replay_ctrl_rects

        if 'scrubber_track' in rects and rects['scrubber_track'].collidepoint(pos):
            track = rects['scrubber_track']
            frac  = max(0.0, min(1.0, (pos[0] - track.x) / max(1, track.width)))
            self._replay_seek(frac)
            self._replay_ended = (self.replay_index >= len(self.game_history) - 1)
            return True

        if 'restart' in rects and rects['restart'].collidepoint(pos):
            self.replay_index  = 0
            self.paused        = False
            self._replay_ended = False
            self._load_snap(self.game_history[0])
            return True

        if 'rewind' in rects and rects['rewind'].collidepoint(pos):
            steps = max(1, len(self.game_history) // 10)
            self._replay_step_back(steps)
            self._replay_ended = False
            self._replay_seek_held = 'rewind'
            self._replay_hold_start = time.time()
            self._replay_last_repeat = time.time()
            return True

        if 'play_pause' in rects and rects['play_pause'].collidepoint(pos):
            if self._replay_ended:
                self.replay_index  = 0
                self.paused        = False
                self._replay_ended = False
                self._load_snap(self.game_history[0])
            else:
                self.paused = not self.paused
            return True

        if 'ff' in rects and rects['ff'].collidepoint(pos):
            steps = max(1, len(self.game_history) // 10)
            self.replay_index = min(len(self.game_history) - 1,
                                    self.replay_index + steps)
            self._load_snap(self.game_history[self.replay_index])
            self._replay_ended = (self.replay_index >= len(self.game_history) - 1)
            self._replay_seek_held = 'ff'
            self._replay_hold_start = time.time()
            self._replay_last_repeat = time.time()
            return True

        for spd in [0.5, 1.0, 2.0, 4.0, 8.0]:
            key = f'speed_{spd}'
            if key in rects and rects[key].collidepoint(pos):
                self.replay_speed = spd
                return True

        if 'exit' in rects and rects['exit'].collidepoint(pos):
            self._replay_exit_requested = True
            return True

        return False

    def replay_control(self, event):
        """Handle keyboard shortcuts while in replay mode."""
        if not self.replay_mode or event.type != pygame.KEYDOWN:
            return
        k = event.key
        if k == pygame.K_SPACE:
            if self._replay_ended:
                self.replay_index  = 0
                self.paused        = False
                self._replay_ended = False
                self._load_snap(self.game_history[0])
            else:
                self.paused = not self.paused
        elif k == pygame.K_RIGHT:
            steps = max(1, len(self.game_history) // 10)
            self.replay_index = min(len(self.game_history) - 1,
                                    self.replay_index + steps)
            self._load_snap(self.game_history[self.replay_index])
            self._replay_ended = (self.replay_index >= len(self.game_history) - 1)
            self._replay_seek_held = 'ff'
            self._replay_hold_start = time.time()
            self._replay_last_repeat = time.time()
        elif k == pygame.K_LEFT:
            steps = max(1, len(self.game_history) // 10)
            self._replay_step_back(steps)
            self._replay_ended = False
            self._replay_seek_held = 'rewind'
            self._replay_hold_start = time.time()
            self._replay_last_repeat = time.time()
        elif k == pygame.K_r:
            self.replay_index  = 0
            self.paused        = False
            self._replay_ended = False
            self._load_snap(self.game_history[0])
        elif k in (pygame.K_PLUS, pygame.K_EQUALS, pygame.K_KP_PLUS):
            speeds = [0.5, 1.0, 2.0, 4.0, 8.0]
            current = min(range(len(speeds)), key=lambda i: abs(speeds[i] - self.replay_speed))
            self.replay_speed = speeds[min(len(speeds) - 1, current + 1)]
        elif k in (pygame.K_MINUS, pygame.K_KP_MINUS):
            speeds = [0.5, 1.0, 2.0, 4.0, 8.0]
            current = min(range(len(speeds)), key=lambda i: abs(speeds[i] - self.replay_speed))
            self.replay_speed = speeds[max(0, current - 1)]
        elif k == pygame.K_ESCAPE:
            self._replay_exit_requested = True

    def draw_replay_controls(self):
        """Draw the full replay control panel overlaid at the bottom of the screen."""
        if not self.replay_mode:
            return

        sw, sh   = self.screen.get_width(), self.screen.get_height()
        # Scale relative to a comfortable desktop baseline, but never let
        # touch targets shrink below a usable size on narrow/phone screens.
        scale    = max(0.72, min(1.35, sw / 800.0))
        panel_h  = int(115 * scale)
        panel_y  = sh - panel_h

        # ── semi-transparent panel background ──────────────────────────────
        overlay = pygame.Surface((sw, panel_h), pygame.SRCALPHA)
        overlay.fill((8, 12, 28, 215))
        self.screen.blit(overlay, (0, panel_y))
        pygame.draw.line(self.screen, (50, 90, 155), (0, panel_y), (sw, panel_y), 2)

        # ── "REPLAY" badge top-left corner ─────────────────────────────────
        badge_font = get_font(self.settings.language, 'bold', max(11, int(13 * scale)))
        badge_surf = badge_font.render("  ● REC REPLAY  ", True, (255, 80, 80))
        badge_bg   = pygame.Rect(8, 8, badge_surf.get_width() + 6, badge_surf.get_height() + 4)
        pygame.draw.rect(self.screen, (60, 10, 10), badge_bg, border_radius=4)
        pygame.draw.rect(self.screen, (180, 40, 40), badge_bg, width=1, border_radius=4)
        self.screen.blit(badge_surf, (badge_bg.x + 3, badge_bg.y + 2))

        # ── scrubber / progress bar ─────────────────────────────────────────
        margin   = max(10, int(16 * scale))
        track_y  = panel_y + int(10 * scale)
        track_h  = max(10, int(14 * scale))
        track    = pygame.Rect(margin, track_y, sw - margin * 2, track_h)
        pygame.draw.rect(self.screen, (30, 45, 75), track, border_radius=track_h // 2)

        total    = max(1, len(self.game_history) - 1)
        filled_w = int((self.replay_index / total) * track.width)
        if filled_w > 0:
            pygame.draw.rect(self.screen, (50, 120, 210),
                             pygame.Rect(track.x, track.y, filled_w, track_h),
                             border_radius=track_h // 2)
        thumb_x = track.x + filled_w
        thumb_r = max(8, int(9 * scale))
        pygame.draw.circle(self.screen, (100, 170, 255), (thumb_x, track.centery), thumb_r)
        pygame.draw.circle(self.screen, (210, 235, 255), (thumb_x, track.centery), max(4, thumb_r - 4))

        # ── control buttons — sized for touch (min ~40px tall) as well as mouse ──
        btn_y   = panel_y + int(33 * scale)
        btn_h   = max(40, int(36 * scale))
        btn_fnt = get_font(self.settings.language, 'bold', max(13, int(14 * scale)))
        rects   = {'scrubber_track': track}

        def _btn(label, x, w, bg=(28, 55, 100), fg=(210, 230, 255)):
            r = pygame.Rect(x, btn_y, w, btn_h)
            pygame.draw.rect(self.screen, bg, r, border_radius=6)
            pygame.draw.rect(self.screen, (70, 120, 195), r, width=1, border_radius=6)
            s = render_fit(btn_fnt, label, fg, w)
            self.screen.blit(s, (r.centerx - s.get_width() // 2,
                                 r.centery - s.get_height() // 2))
            return r

        cx  = margin
        gap = max(4, int(6 * scale))
        w_narrow = max(36, int(38 * scale))
        w_pp     = max(52, int(58 * scale))
        w_speed  = max(38, int(42 * scale))
        w_exit   = max(42, int(46 * scale))

        rects['restart']    = _btn("|<",  cx, w_narrow); cx += w_narrow + gap
        rects['rewind']     = _btn("<<",  cx, w_narrow); cx += w_narrow + gap

        if self._replay_ended:
            pp_lbl, pp_bg = "Replay", (30, 80, 50)
        elif self.paused:
            pp_lbl, pp_bg = "  >  ", (90, 55, 20)
        else:
            pp_lbl, pp_bg = " || ", (25, 70, 40)
        rects['play_pause'] = _btn(pp_lbl, cx, w_pp, bg=pp_bg); cx += w_pp + gap

        rects['ff']         = _btn(">>",  cx, w_narrow); cx += w_narrow + gap + int(10 * scale)

        # Speed selector — hidden on very narrow screens where it wouldn't fit;
        # players can still change speed via the settings/keyboard.
        remaining_w = sw - margin - cx
        replay_speeds = [0.5, 1.0, 2.0, 4.0, 8.0]
        n_speeds = len(replay_speeds)
        if remaining_w >= n_speeds * (w_speed + gap) + w_exit + gap + margin:
            for spd in replay_speeds:
                active = abs(self.replay_speed - spd) < 0.01
                bg = (55, 95, 165) if active else (22, 40, 78)
                fg = (255, 255, 255) if active else (140, 175, 220)
                rects[f'speed_{spd}'] = _btn(f"{spd:g}x", cx, w_speed, bg=bg, fg=fg)
                cx += w_speed + gap
            cx += 8

        rects['exit'] = _btn("Exit", cx, w_exit, bg=(85, 25, 25), fg=(255, 200, 200))

        # ── status text row (hidden on narrow/short screens where it won't fit) ──
        info_y   = panel_y + int(78 * scale)
        if sh > 260 and sw > 420:
            info_fnt = get_font(self.settings.language, 'regular', max(10, int(12 * scale)))

            cur_score = self.game_history[self.replay_index][3] \
                if self.game_history and len(self.game_history[self.replay_index]) > 3 else 0
            status = f"  Frame {self.replay_index + 1} / {len(self.game_history)}   Score: {cur_score}"
            if self._replay_ended:
                status += "   [REPLAY ENDED]"
            elif self.paused:
                status += "   [PAUSED]"
            left_s = info_fnt.render(status, True, (150, 185, 230))
            self.screen.blit(left_s, (margin, info_y))

            # Show seed used for this replay
            seed_info = info_fnt.render(
                f"  Seed: {getattr(self, 'seed', '?')}",
                True, (90, 130, 190))
            self.screen.blit(seed_info, (margin, info_y + int(14 * scale)))

            if sw > 640:
                hint = "SPACE: pause/resume   Hold ← →: seek   +/-: speed   R: restart   ESC: exit"
                hint_s = info_fnt.render(hint, True, (80, 110, 155))
                self.screen.blit(hint_s, (sw - hint_s.get_width() - margin, info_y))

        # Store rects for click handling
        self._replay_ctrl_rects = rects
            
    def run(self):
        """Run the game loop with a render-independent fixed-step simulation."""
        running = True
        clock = pygame.time.Clock()
        replay_timer = 0.0

        while running:
            _pump_audio()
            # Tick first so the returned delta is the elapsed real time since the
            # previous loop iteration. Clamp large stalls to avoid a catch-up spiral.
            frame_dt = min(float(clock.tick(60)), 250.0)
            raw_frame_dt = frame_dt
            frame_dt = DEV_TOOLS.scale_dt(frame_dt)
            input_start = time.perf_counter()
            update_ms = 0.0
            render_ms = 0.0
            replay_ms = 0.0

            # Handle events.
            for event in pygame.event.get():
                if _legacy_nav_event(locals().get('self'), event, locals()):
                    continue
                if _is_app_background_event(event):
                    if not self.game_over and not self.victory:
                        self.paused = True
                        self._update_accumulator_ms = 0.0
                elif event.type == pygame.QUIT:
                    running = False
                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_F11:
                        self.screen = _toggle_fullscreen(self.screen)
                    elif event.key == pygame.K_F8 and DEV_TOOLS.unlocked:
                        DEV_TOOLS.open_panel(self.screen, self)
                    elif self.replay_mode:
                        self.replay_control(event)
                    else:
                        running = self.handle_input(event)
                elif event.type == pygame.KEYUP:
                    if self.replay_mode and event.key in (pygame.K_LEFT, pygame.K_RIGHT):
                        self._replay_seek_held = None
                elif event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
                    mp = event.pos
                    if self.replay_mode:
                        self.replay_handle_click(mp)
                    elif (self.game_over or self.victory) and hasattr(self, '_go_buttons'):
                        gb = self._go_buttons
                        if gb.get('play_again') and gb['play_again'].collidepoint(mp):
                            self.reset_game()
                        elif gb.get('menu') and gb['menu'].collidepoint(mp):
                            running = False
                        elif gb.get('copy_seed') and gb['copy_seed'].collidepoint(mp):
                            if _copy_to_clipboard(str(self.seed)):
                                self._seed_copied_until = time.time() + 2.0
                        elif gb.get('view_replay') and gb['view_replay'].collidepoint(mp):
                            self.start_replay(self.game_history)
                    else:
                        pause_button = self.draw_pause_button()
                        if pause_button and pause_button.collidepoint(mp):
                            self.paused = not self.paused
                        elif hasattr(self, '_dpad_rects'):
                            dr = self._dpad_rects
                            if dr['U'].collidepoint(mp) and self.direction != (0, 1):
                                self.next_direction = (0, -1)
                            elif dr['D'].collidepoint(mp) and self.direction != (0, -1):
                                self.next_direction = (0, 1)
                            elif dr['L'].collidepoint(mp) and self.direction != (1, 0):
                                self.next_direction = (-1, 0)
                            elif dr['R'].collidepoint(mp) and self.direction != (-1, 0):
                                self.next_direction = (1, 0)
                            elif dr['C'].collidepoint(mp):
                                self.paused = not self.paused
                elif event.type == pygame.MOUSEBUTTONUP and event.button == 1:
                    if self.replay_mode:
                        self._replay_seek_held = None
                elif event.type == pygame.VIDEORESIZE:
                    self.screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)
                    self.cell_size = min(self.screen.get_width(), self.screen.get_height()) // max(self.board_width, self.board_height)
                    self.board_offset_x = (self.screen.get_width() - (self.board_width * self.cell_size)) // 2
                    self.board_offset_y = (self.screen.get_height() - (self.board_height * self.cell_size)) // 2

            input_ms = (time.perf_counter() - input_start) * 1000.0
            if self._replay_exit_requested:
                running = False
                self.replay_mode = False
                self._replay_exit_requested = False
                continue

            if self.replay_mode:
                replay_start = time.perf_counter()
                self._replay_process_held_seek()
                if not self.paused and not self._replay_ended:
                    replay_timer += frame_dt * self.replay_speed
                    snap_speed = getattr(self, 'speed_multiplier', 1.0)
                    snap_lspd = getattr(self, 'length_speed_multiplier', 1.0)
                    effective_frame_ms = self.settings.update_rate_ms * snap_speed * snap_lspd
                    if replay_timer >= effective_frame_ms:
                        more_frames = self.replay_next_frame()
                        if not more_frames:
                            self._replay_ended = True
                            self.paused = True
                        replay_timer %= max(1.0, effective_frame_ms)
                replay_ms = (time.perf_counter() - replay_start) * 1000.0
            else:
                if not self.paused and not self.game_over and not self.victory:
                    self._sim_time_ms += frame_dt
                    self._update_accumulator_ms += frame_dt

                    update_start = time.perf_counter()
                    self.update_moving_obstacles()

                    # Fixed-step gameplay.  Multiple steps may run after a long
                    # render stall, preserving elapsed gameplay time across FPS.
                    steps = 0
                    while self._update_accumulator_ms > 0:
                        effective_update_rate = (
                            self.settings.update_rate_ms *
                            getattr(self, 'speed_multiplier', 1.0) *
                            getattr(self, 'length_speed_multiplier', 1.0)
                        )
                        effective_update_rate = max(1.0, effective_update_rate)
                        if self._update_accumulator_ms < effective_update_rate:
                            break
                        DEV_TOOLS.apply_frame_cheats(self)
                        self.move_snake()
                        self._update_accumulator_ms -= effective_update_rate
                        self.last_update_time = self._sim_time_ms - self._update_accumulator_ms
                        steps += 1
                        if self.game_over or self.victory:
                            self._update_accumulator_ms = 0.0
                            break
                        if steps >= 32:
                            # A hard safety ceiling for pathological settings; the
                            # accumulator retains the remainder for the next frame.
                            break
                    if not self.replay_mode and self.game_over:
                        _trigger_mobile_haptic(90)
                    update_ms = (time.perf_counter() - update_start) * 1000.0

            render_start = time.perf_counter()
            self.draw_board()

            if not self.replay_mode:
                self.draw_pause_button()
                self._dpad_rects = self.draw_dpad()
                self.draw_active_powerups()

                if hasattr(self, 'combo_count') and self.combo_count > 1 and self.settings.combo_fruits_enabled:
                    font = get_font(self.settings.language, 'bold', 24)
                    combo_surface = font.render(f"Combo: x{self.combo_count}", True, (255, 215, 0))
                    self.screen.blit(combo_surface, (20, 85))

                if hasattr(self, 'current_level') and self.settings.levels_enabled:
                    font = get_font(self.settings.language, 'regular', 18)
                    level_surface = font.render(f"Level: {self.current_level}", True, (200, 200, 200))
                    self.screen.blit(level_surface, (20, 55))

                if self.game_over or self.victory:
                    self.draw_game_over()

                if self.achievement_manager:
                    self.achievement_manager.draw_notification(
                        self.screen, self.screen.get_width(), self.screen.get_height(),
                        self.settings.language)
            else:
                self.draw_active_powerups()
                self.draw_replay_controls()

            _legacy_nav_draw(locals().get('self'))
            DEV_TOOLS.draw_game_overlay(self.screen, self)
            pygame.display.flip()
            render_ms = (time.perf_counter() - render_start) * 1000.0
            _dev_game_frame_hook(self, raw_frame_dt, update_ms=update_ms, render_ms=render_ms, input_ms=input_ms, replay_ms=replay_ms)

            object_counts = {
                'snake_segments': len(getattr(self, 'snake', [])),
                'obstacles': len(getattr(self, 'obstacles', [])),
                'moving_obstacles': len(getattr(self, 'moving_obstacles', [])),
                'active_powerups': len(getattr(self, 'active_powerups', [])),
                'replay_frames': len(getattr(self, 'game_history', [])),
            }
            self.performance_stats.record_frame(
                frame_dt,
                update_ms=update_ms, render_ms=render_ms, replay_ms=replay_ms,
                object_counts=object_counts)

        return

##############
# HIGH SCORES
##############

class HighScoresScreen:
    # Real list geometry used by draw_screen()'s row loop — kept here as the
    # single source of truth so the scrollbar's content height can never
    # drift out of sync with what's actually drawn (it previously used two
    # different, both-wrong guesses: 70px/row+100 at init, 40px/row+100 at
    # runtime — the "+100" padding in particular was disconnected from the
    # real 20px gap between the viewport top and the first row, which made
    # the scrollbar appear even when every row already fit on screen).
    LIST_TOP = 170       # y where the first row is drawn (see draw_screen)
    ROW_HEIGHT = 40       # vertical space per row (see draw_screen)
    VIEWPORT_TOP = 150    # y where the scrollable viewport starts
    LIST_BOTTOM_MARGIN = 10  # small breathing room below the last row

    def _content_height_for(self, count):
        """Exact scrollable content height for `count` rows, measured from
        the viewport top — matches draw_screen()'s real row geometry."""
        return (self.LIST_TOP - self.VIEWPORT_TOP) + count * self.ROW_HEIGHT + self.LIST_BOTTOM_MARGIN

    def __init__(self, settings, screen):
        self.settings = settings
        self.screen = screen
        
        # Initialize scroll bar for high scores list
        self.scrollbar = None
        self.detail_buttons = []  # populated each frame in draw_screen
        # Perf fix: load_highscores()/filter_highscores() used to run on
        # every single frame (disk read + json.load() + full re-filter/sort,
        # 60x/sec) — this was the actual cause of the High Scores slowdown,
        # not rendering. Both are now cached and only recomputed when the
        # underlying data or the search/filter/sort settings actually change.
        self._hs_cache = None
        self._hs_cache_dirty = True
        self._filter_cache_sig = None
        self._filter_cache_result = []
        self.init_scrollbar()
        
    def init_scrollbar(self):
        """Initialize the scroll bar for high scores"""
        scores = self.load_highscores()
        content_height = self._content_height_for(len(scores))
        screen_height = self.screen.get_height() - 200  # Account for header/footer
        
        self.scrollbar = ScrollBar(
            self.screen.get_width() - 30,  # Right side
            150,  # Below header
            20,   # Width
            screen_height,
            content_height
        )
        # Wheel scrolling works anywhere over the list, not just over the thin bar.
        self.scrollbar.wheel_rect = pygame.Rect(0, 150, self.screen.get_width(), screen_height)
        self.search_text = ""
        self.search_active = False
        self.filter_options = {
            "sort_by": "score",        # score, date, board_size, speed
            "order": "desc",           # asc, desc
            "show_victories": "all",   # all, victory_only, no_victory
            "difficulty": "all",       # all, easy (>=200ms), medium (100-199ms), hard (<100ms)
            "has_replay": "all",       # all, with_replay, no_replay
            "obstacles": "all",        # all, with_obstacles, no_obstacles
            "powerups": "all",         # all, with_powerups, no_powerups
        }
        self.filter_menu_open = False
        self.confirm_delete = None  # score_data pending delete confirmation
        
    def load_highscores(self):
        """Load high scores from the unified data file.

        Cached: this used to call `_load_data()` (a synchronous disk read +
        `json.load()` of the whole save file on every call — and
        `draw_screen()` called it on every single frame, i.e. up to ~60
        disk reads + full JSON re-parses per second while this screen was
        open. That was the actual root cause of the reported slowdown.
        Now it only re-reads when explicitly invalidated (see
        `invalidate_highscores_cache()`), which happens when a score is
        deleted and each time the screen is (re)entered via run(), so it
        always reflects on-disk reality without paying the cost every
        frame.
        """
        if self._hs_cache is None or self._hs_cache_dirty:
            try:
                _gd = _load_data()
                hs = _gd.get('highscores', [])
                self._hs_cache = hs if isinstance(hs, list) else []
            except Exception as e:
                print(f"Error loading high scores: {e}")
                self._hs_cache = []
            self._hs_cache_dirty = False
        return self._hs_cache

    def invalidate_highscores_cache(self):
        """Force the next load_highscores()/filter_highscores() call to
        re-read from disk. Call after anything that changes saved scores."""
        self._hs_cache_dirty = True

    def get_filtered_scores(self):
        """filter_highscores(), cached against (data identity, search text,
        filter/sort settings) so re-sorting/re-filtering the whole list
        doesn't happen on every frame when nothing has actually changed."""
        highscores = self.load_highscores()
        sig = (id(highscores), len(highscores), self.search_text,
               tuple(sorted(self.filter_options.items())))
        if sig != self._filter_cache_sig:
            self._filter_cache_result = self.filter_highscores(highscores)
            self._filter_cache_sig = sig
        return self._filter_cache_result

    def filter_highscores(self, highscores):
        """Filter and sort highscores based on current filter settings and search text"""
        highscores = [score for score in highscores if isinstance(score, dict)]
        def _number(score, key, default=0.0):
            value = score.get(key, default)
            if isinstance(value, bool):
                return float(default)
            try:
                value = float(value)
                return value if math.isfinite(value) else float(default)
            except (TypeError, ValueError, OverflowError):
                return float(default)

        def _board_size_number(score):
            value = score.get('actual_board_width', score.get('board_size', 0))
            if isinstance(value, str):
                return {'small': 10, 'medium': 15, 'large': 20, 'extra_large': 25}.get(
                    value.casefold(), _number({'v': value}, 'v', 0))
            try:
                return float(value) if not isinstance(value, bool) else 0.0
            except (TypeError, ValueError, OverflowError):
                return 0.0

        # Apply search filter (name, score, date, board size, game mode keywords)
        if self.search_text:
            search_lower = self.search_text.casefold()
            def _text(value):
                return str(value or '').casefold()

            def _board_label(score):
                width = score.get('actual_board_width', score.get('board_size', ''))
                height = score.get('actual_board_height', score.get('board_size', ''))
                return f'{width}x{height}'.casefold()

            def _mode_text(score):
                mode = score.get('game_mode') or score.get('mp_mode')
                if not mode:
                    mode = 'multiplayer' if score.get('is_multiplayer') else 'single_player'
                return f"{mode} {score.get('mp_source', '')}".replace('_', ' ').casefold()

            filtered_scores = [
                score for score in highscores
                if search_lower in _text(score.get('name'))
                or search_lower in _text(score.get('score', ''))
                or search_lower in _text(score.get('date'))
                or search_lower in _text(format_date_text(score.get('date')))
                or search_lower in _board_label(score)
                or search_lower in _mode_text(score)
            ]
        else:
            filtered_scores = highscores.copy()

        # Victory filter
        sv = self.filter_options.get("show_victories", "all")
        if sv == "victory_only":
            filtered_scores = [s for s in filtered_scores if s.get('victory', False)]
        elif sv == "no_victory":
            filtered_scores = [s for s in filtered_scores if not s.get('victory', False)]

        # Difficulty filter (based on update_rate_ms — lower = faster = harder)
        diff = self.filter_options.get("difficulty", "all")
        if diff == "easy":
            filtered_scores = [s for s in filtered_scores if _number(s, 'update_rate_ms', 200) >= 200]
        elif diff == "medium":
            filtered_scores = [s for s in filtered_scores if 100 <= _number(s, 'update_rate_ms', 200) < 200]
        elif diff == "hard":
            filtered_scores = [s for s in filtered_scores if _number(s, 'update_rate_ms', 200) < 100]

        # Replay filter
        rep = self.filter_options.get("has_replay", "all")
        if rep == "with_replay":
            filtered_scores = [s for s in filtered_scores if _score_has_replay(s)]
        elif rep == "no_replay":
            filtered_scores = [s for s in filtered_scores if not _score_has_replay(s)]

        # Obstacles filter
        obs = self.filter_options.get("obstacles", "all")
        if obs == "with_obstacles":
            filtered_scores = [s for s in filtered_scores if s.get('obstacles_enabled', False)]
        elif obs == "no_obstacles":
            filtered_scores = [s for s in filtered_scores if not s.get('obstacles_enabled', False)]

        # Powerups filter
        pwrups = self.filter_options.get("powerups", "all")
        if pwrups == "with_powerups":
            filtered_scores = [s for s in filtered_scores if s.get('powerups_enabled', True)]
        elif pwrups == "no_powerups":
            filtered_scores = [s for s in filtered_scores if not s.get('powerups_enabled', True)]

        # Sorting
        sort_key = self.filter_options.get("sort_by", "score")
        desc = (self.filter_options.get("order", "desc") == "desc")
        if sort_key == "score":
            filtered_scores.sort(key=lambda x: _number(x, 'score'), reverse=desc)
        elif sort_key == "date":
            filtered_scores.sort(key=lambda x: str(x.get('date') or ''), reverse=desc)
        elif sort_key == "board_size":
            filtered_scores.sort(key=_board_size_number, reverse=desc)
        elif sort_key == "speed":
            # Lower update_rate_ms = faster; sort ascending for "fastest first" when desc=True
            filtered_scores.sort(key=lambda x: _number(x, 'update_rate_ms', 200), reverse=not desc)

        return filtered_scores
    
    def _layout_header(self):
        """Back / Title / Filter / Search solved together in one UIHorizontalFlow so
        none of them can overlap: previously each had an independently hardcoded
        pixel position that took no account of the others' width."""
        sw = self.screen.get_width()
        lang = self.settings.language
        back_w = max(90, ui_text_size(lang, 'bold', 20, get_text(lang, 'back'))[0] + 40)
        filter_w = max(90, ui_text_size(lang, 'bold', 20, get_text(lang, 'filter'))[0] + 30)
        flow = UIHorizontalFlow(pygame.Rect(20, 18, max(1, sw - 40), 0), spacing=14,
                                wrap=True, drop_optional=True)
        flow.add('back', back_w, min_w=70, h=40)
        flow.add('title', 260, min_w=90, h=40, flex=1, anchor_center=True)
        flow.add('filter', filter_w, min_w=70, h=30, priority=2)
        flow.add('search', 250, min_w=140, h=30, priority=1)
        import_label = get_text(lang, 'replay_share_paste')
        flow.add('import_replay', max(120, ui_text_size(lang, 'bold', 16, import_label)[0] + 24),
                 min_w=86, h=30, priority=3)
        res = flow.solve()
        self._hs_header_mode = res.mode
        return res.rects

    def draw_search_box(self, rect):
        """Draw the search input box at the given rect (from _layout_header)."""
        font = get_font(self.settings.language, 'regular', 20)
        search_rect = rect
        color = COLORS['light_gray'] if self.search_active else COLORS['gray']
        pygame.draw.rect(self.screen, color, search_rect, border_radius=5)

        # Draw search icon
        icon_size = min(20, search_rect.height - 4)
        icon_rect = pygame.Rect(search_rect.x + 5, search_rect.y + (search_rect.height - icon_size) // 2,
                                icon_size, icon_size)
        pygame.draw.rect(self.screen, COLORS['dark_gray'], icon_rect, border_radius=10, width=2)
        pygame.draw.line(self.screen, COLORS['dark_gray'], 
                        (icon_rect.right - 3, icon_rect.bottom - 3), 
                        (icon_rect.right + 5, icon_rect.bottom + 5), 2)

        # Draw text or placeholder, shrunk to fit the (possibly compressed) box
        avail = max(10, search_rect.width - (icon_rect.right - search_rect.x) - 12)
        if not self.search_text and not self.search_active:
            text_surface = render_fit(font, get_text(self.settings.language, 'search'), COLORS['dark_gray'], avail)
        else:
            text_surface = render_fit(font, self.search_text, COLORS['black'], avail)

        text_x = icon_rect.right + 10
        text_y = search_rect.y + (search_rect.height - text_surface.get_height()) // 2
        self.screen.blit(text_surface, (text_x, text_y))

        return search_rect

    def draw_filter_button(self, rect):
        """Draw the filter button at the given rect (from _layout_header)."""
        font = get_font(self.settings.language, 'bold', 20)
        filter_rect = rect
        filter_color = COLORS['light_blue'] if self.filter_menu_open else COLORS['button']
        pygame.draw.rect(self.screen, filter_color, filter_rect, border_radius=5)

        filter_text = get_text(self.settings.language, 'filter')
        text_surface = render_fit(font, filter_text, COLORS['white'], filter_rect.width - 8)
        text_rect = text_surface.get_rect(center=filter_rect.center)
        self.screen.blit(text_surface, text_rect)

        return filter_rect
    
    def draw_filter_menu(self, filter_rect):
        """Draw expanded filter menu if open; return list of (rect, action) tuples."""
        if not self.filter_menu_open:
            return []

        menu_width = 370
        menu_height = 430
        menu_x = filter_rect.x - (menu_width - filter_rect.width) // 2
        menu_y = filter_rect.bottom + 10

        # Keep on screen
        menu_x = max(10, min(menu_x, self.screen.get_width() - menu_width - 10))
        if menu_y + menu_height > self.screen.get_height() - 10:
            menu_y = filter_rect.top - menu_height - 10

        menu_rect = pygame.Rect(menu_x, menu_y, menu_width, menu_height)
        pygame.draw.rect(self.screen, (30, 35, 55), menu_rect, border_radius=8)
        pygame.draw.rect(self.screen, COLORS['light_blue'], menu_rect, border_radius=8, width=2)

        title_font = get_font(self.settings.language, 'bold', 20)
        menu_font = get_font(self.settings.language, 'regular', 16)
        lbl_font = get_font(self.settings.language, 'bold', 15)

        title_surf = title_font.render(_t_or(self.settings.language, 'filter_sort_title', 'Filter & Sort'), True, COLORS['white'])
        self.screen.blit(title_surf, (menu_x + 10, menu_y + 8))
        pygame.draw.line(self.screen, COLORS['light_blue'],
            (menu_x + 8, menu_y + 34), (menu_x + menu_width - 8, menu_y + 34), 1)

        interactive_rects = []
        row_h = 26
        pad = 10
        col_x = menu_x + 105  # start of button columns
        btn_w = 56
        btn_gap = 4
        cur_y = menu_y + 42

        def _row_label(text, y):
            lbl = lbl_font.render(text, True, COLORS['light_gray'])
            self.screen.blit(lbl, (menu_x + pad, y + (row_h - lbl.get_height()) // 2))

        def _btn(label, x, y, action, selected):
            r = pygame.Rect(x, y, btn_w, row_h)
            c = COLORS['light_blue'] if selected else COLORS['button']
            pygame.draw.rect(self.screen, c, r, border_radius=4)
            t = render_fit(menu_font, label, COLORS['white'], btn_w)
            self.screen.blit(t, t.get_rect(center=r.center))
            interactive_rects.append((r, action))

        def _wide_btn(label, x, y, w, action, selected):
            r = pygame.Rect(x, y, w, row_h)
            c = COLORS['light_blue'] if selected else COLORS['button']
            pygame.draw.rect(self.screen, c, r, border_radius=4)
            t = render_fit(menu_font, label, COLORS['white'], w)
            self.screen.blit(t, t.get_rect(center=r.center))
            interactive_rects.append((r, action))

        # ── Sort By ──────────────────────────────────────────
        _row_label(get_text(self.settings.language, 'sort_by'), cur_y)
        sx = col_x
        for opt, lbl in [('score', get_text(self.settings.language, 'score')), ('date', get_text(self.settings.language, 'date')), ('board_size', _t_or(self.settings.language, 'size_short', 'Size')), ('speed', get_text(self.settings.language, 'speed'))]:
            _btn(lbl, sx, cur_y, f"sort_by:{opt}", self.filter_options["sort_by"] == opt)
            sx += btn_w + btn_gap
        cur_y += row_h + 6

        # ── Order ─────────────────────────────────────────────
        _row_label(get_text(self.settings.language, 'order'), cur_y)
        _btn(get_text(self.settings.language, 'desc'), col_x, cur_y, "order:desc", self.filter_options["order"] == "desc")
        _btn(get_text(self.settings.language, 'asc'),  col_x + btn_w + btn_gap, cur_y, "order:asc", self.filter_options["order"] == "asc")
        cur_y += row_h + 6

        pygame.draw.line(self.screen, (60, 65, 90),
            (menu_x + 8, cur_y), (menu_x + menu_width - 8, cur_y), 1)
        cur_y += 6

        # ── Victory ───────────────────────────────────────────
        _row_label(_t_or(self.settings.language, 'victory_label', 'Victory'), cur_y)
        _wide_btn(_t_or(self.settings.language, 'all', 'All'),      col_x,                  cur_y, 56, "show_victories:all",          self.filter_options["show_victories"] == "all")
        _wide_btn(_t_or(self.settings.language, 'won', 'Won'),      col_x + 60,             cur_y, 56, "show_victories:victory_only",  self.filter_options["show_victories"] == "victory_only")
        _wide_btn(_t_or(self.settings.language, 'lost', 'Lost'),     col_x + 120,            cur_y, 56, "show_victories:no_victory",    self.filter_options["show_victories"] == "no_victory")
        cur_y += row_h + 6

        # ── Difficulty ────────────────────────────────────────
        _row_label(_t_or(self.settings.language, 'difficulty', 'Difficulty'), cur_y)
        _wide_btn(_t_or(self.settings.language, 'all', 'All'),    col_x,       cur_y, 56, "difficulty:all",    self.filter_options["difficulty"] == "all")
        _wide_btn(_t_or(self.settings.language, 'easy', 'Easy'),   col_x + 60,  cur_y, 56, "difficulty:easy",   self.filter_options["difficulty"] == "easy")
        _wide_btn(_t_or(self.settings.language, 'medium', 'Medium'), col_x + 120, cur_y, 68, "difficulty:medium", self.filter_options["difficulty"] == "medium")
        _wide_btn(_t_or(self.settings.language, 'hard', 'Hard'),   col_x + 192, cur_y, 56, "difficulty:hard",   self.filter_options["difficulty"] == "hard")
        cur_y += row_h + 6

        # ── Replay ────────────────────────────────────────────
        _row_label(_t_or(self.settings.language, 'replay_label', 'Replay'), cur_y)
        _wide_btn(_t_or(self.settings.language, 'all', 'All'),         col_x,       cur_y, 56, "has_replay:all",         self.filter_options["has_replay"] == "all")
        _wide_btn(_t_or(self.settings.language, 'has_replay', 'Has Replay'),  col_x + 60,  cur_y, 80, "has_replay:with_replay", self.filter_options["has_replay"] == "with_replay")
        _wide_btn(_t_or(self.settings.language, 'no_replay', 'No Replay'),   col_x + 144, cur_y, 80, "has_replay:no_replay",   self.filter_options["has_replay"] == "no_replay")
        cur_y += row_h + 6

        # ── Obstacles ─────────────────────────────────────────
        _row_label(_t_or(self.settings.language, 'obstacles_label', 'Obstacles'), cur_y)
        _wide_btn(_t_or(self.settings.language, 'all', 'All'),         col_x,       cur_y, 56, "obstacles:all",            self.filter_options["obstacles"] == "all")
        _wide_btn(_t_or(self.settings.language, 'with_word', 'With'),        col_x + 60,  cur_y, 72, "obstacles:with_obstacles", self.filter_options["obstacles"] == "with_obstacles")
        _wide_btn(_t_or(self.settings.language, 'without_word', 'Without'),     col_x + 136, cur_y, 72, "obstacles:no_obstacles",   self.filter_options["obstacles"] == "no_obstacles")
        cur_y += row_h + 6

        # ── Powerups ──────────────────────────────────────────
        _row_label(_t_or(self.settings.language, 'powerups_label', 'Powerups'), cur_y)
        _wide_btn(_t_or(self.settings.language, 'all', 'All'),         col_x,       cur_y, 56, "powerups:all",            self.filter_options["powerups"] == "all")
        _wide_btn(_t_or(self.settings.language, 'with_word', 'With'),        col_x + 60,  cur_y, 72, "powerups:with_powerups",  self.filter_options["powerups"] == "with_powerups")
        _wide_btn(_t_or(self.settings.language, 'without_word', 'Without'),     col_x + 136, cur_y, 72, "powerups:no_powerups",    self.filter_options["powerups"] == "no_powerups")
        cur_y += row_h + 10

        pygame.draw.line(self.screen, (60, 65, 90),
            (menu_x + 8, cur_y), (menu_x + menu_width - 8, cur_y), 1)
        cur_y += 8

        # ── Reset + Close buttons ─────────────────────────────
        reset_rect = pygame.Rect(menu_x + pad, cur_y, 80, 26)
        pygame.draw.rect(self.screen, COLORS['dark_gray'], reset_rect, border_radius=5)
        rt = menu_font.render(_t_or(self.settings.language, 'reset', 'Reset'), True, COLORS['white'])
        self.screen.blit(rt, rt.get_rect(center=reset_rect.center))
        interactive_rects.append((reset_rect, "reset_filters"))

        close_rect = pygame.Rect(menu_x + menu_width - 70, cur_y, 60, 26)
        pygame.draw.rect(self.screen, COLORS['red'], close_rect, border_radius=5)
        ct = menu_font.render(get_text(self.settings.language, 'close'), True, COLORS['white'])
        self.screen.blit(ct, ct.get_rect(center=close_rect.center))
        interactive_rects.append((close_rect, "close_filter"))

        return interactive_rects
            
    def draw_screen(self):
        """Draw the high scores screen"""
        # Fill background
        self.screen.fill(COLORS['dark_blue'])
        self.detail_buttons = []
        
        # Title, Back, Filter and Search are solved together in one row so they
        # can never overlap, regardless of window width or translated text length.
        header = self._layout_header()
        title_font = get_font(self.settings.language, 'bold', 30)
        title_text = get_text(self.settings.language, 'high_scores')
        title_surface = render_fit(title_font, title_text, COLORS['white'], header['title'].width)
        self.screen.blit(title_surface, title_surface.get_rect(center=header['title'].center))

        # Load and filter high scores (both cached — see load_highscores()
        # and get_filtered_scores() docstrings for why this used to be slow)
        filtered_scores = self.get_filtered_scores()

        # Draw search box and filter button
        search_rect = self.draw_search_box(header['search'])
        filter_rect = self.draw_filter_button(header['filter'])
        import_rect = header.get('import_replay')
        if import_rect:
            pygame.draw.rect(self.screen, COLORS['blue'], import_rect, border_radius=5)
            import_font = get_font(self.settings.language, 'bold', 16)
            import_text = render_fit(import_font,
                get_text(self.settings.language, 'replay_share_paste'), COLORS['white'],
                import_rect.width - 8)
            self.screen.blit(import_text, import_text.get_rect(center=import_rect.center))
        
        if not filtered_scores:
            # Draw "No high scores yet" message
            no_scores_font = get_font(self.settings.language, 'regular', 24)
            no_scores_text = get_text(self.settings.language, 'no_highscores')
            no_scores_surface = no_scores_font.render(no_scores_text, True, COLORS['white'])
            self.screen.blit(no_scores_surface, (
                self.screen.get_width() // 2 - no_scores_surface.get_width() // 2, 
                self.screen.get_height() // 2 - no_scores_surface.get_height() // 2
            ))
        else:
            # Initialize detail buttons list for interaction
            # Each entry: (rect, score_data, btn_type)  where btn_type = 'view' | 'delete'
            # Draw table headers
            header_font = get_font(self.settings.language, 'bold', 22)
            headers = [
                get_text(self.settings.language, 'rank'),
                get_text(self.settings.language, 'player_name'),
                get_text(self.settings.language, 'score'),
                get_text(self.settings.language, 'date'),
                get_text(self.settings.language, 'board_size'),
                get_text(self.settings.language, 'speed'),
                "",   # view button column
                "",   # delete button column
            ]

            col_widths = [55, 160, 80, 170, 100, 80, 70, 36]
            total_width = sum(col_widths)
            start_x = (self.screen.get_width() - total_width) // 2

            x = start_x
            for i, col_header in enumerate(headers):
                if col_header:
                    hs = header_font.render(col_header, True, COLORS['white'])
                    self.screen.blit(hs, (x + col_widths[i] // 2 - hs.get_width() // 2, 120))
                x += col_widths[i]

            pygame.draw.line(self.screen, COLORS['white'],
                (start_x, 150), (start_x + total_width, 150), 2)

            score_font = get_font(self.settings.language, 'regular', 18)
            btn_font  = get_font(self.settings.language, 'bold', 14)
            MEDAL_COLORS = {0: (255, 215, 0), 1: (192, 192, 192), 2: (205, 127, 50)}

            if self.scrollbar:
                self.scrollbar.content_height = self._content_height_for(len(filtered_scores))
                self.scrollbar.max_scroll = max(0, self.scrollbar.content_height - self.scrollbar.rect.height)
                self.scrollbar.update()

            start_y = self.LIST_TOP
            scroll_offset = self.scrollbar.get_content_offset() if self.scrollbar else 0
            visible_start = max(0, scroll_offset // self.ROW_HEIGHT)
            visible_end = min(len(filtered_scores), visible_start + 15)
            y = start_y - (scroll_offset % self.ROW_HEIGHT)

            for i, score in enumerate(filtered_scores[visible_start:visible_end], visible_start):
                row_bg = MEDAL_COLORS.get(i, None)
                row_rect = pygame.Rect(start_x, y - 4, total_width, 36)
                if row_bg:
                    s = pygame.Surface((total_width, 36), pygame.SRCALPHA)
                    s.fill((*row_bg, 50))
                    self.screen.blit(s, (start_x, y - 4))
                    pygame.draw.rect(self.screen, row_bg, row_rect, width=2, border_radius=4)
                elif i % 2 == 0:
                    s2 = pygame.Surface((total_width, 36), pygame.SRCALPHA)
                    s2.fill((255, 255, 255, 15))
                    self.screen.blit(s2, (start_x, y - 4))

                medal_labels = {0: '#1', 1: '#2', 2: '#3'}
                rank_label = medal_labels.get(i, f'#{i + 1}')

                name_text = str(score.get('name', '') or '')
                if score.get('victory', False):
                    name_text += ' ' + safe_mark(self.settings.language, 'check')

                speed_display = f"{score.get('update_rate_ms', 200)}ms"
                row_data = [
                    rank_label,
                    name_text,
                    str(score.get('score', 0)),
                    format_date_text(score.get('date', '') or ''),
                    f"{score.get('board_size', '?')}x{score.get('board_size', '?')}",
                    speed_display,
                ]

                txt_color = MEDAL_COLORS.get(i, COLORS['white'])
                x = start_x
                for j, data in enumerate(row_data):
                    ds = score_font.render(data, True, txt_color)
                    if j <= 1:
                        self.screen.blit(ds, (x + 6, y + 1))
                    else:
                        self.screen.blit(ds, (x + col_widths[j] // 2 - ds.get_width() // 2, y + 1))
                    x += col_widths[j]

                # View / Replay button
                has_replay = _score_has_replay(score)
                view_key = 'highscore_replay' if has_replay else 'highscore_view'
                view_text = get_text(self.settings.language, view_key)
                view_color = COLORS['light_blue'] if has_replay else COLORS['button']
                vw = col_widths[6] - 4
                vh = 28
                vx = x + 2
                vy = y + (36 - vh) // 2 - 4
                view_rect = pygame.Rect(vx, vy, vw, vh)
                pygame.draw.rect(self.screen, view_color, view_rect, border_radius=4)
                vt = render_fit(btn_font, view_text, COLORS['white'], vw - 4, padding=2)
                self.screen.blit(vt, vt.get_rect(center=view_rect.center))
                self.detail_buttons.append((view_rect, score, 'view'))
                x += col_widths[6]

                # Delete (×) button
                dx = x + 2
                dy = y + (36 - vh) // 2 - 4
                del_rect = pygame.Rect(dx, dy, col_widths[7] - 4, vh)
                pygame.draw.rect(self.screen, (180, 50, 50), del_rect, border_radius=4)
                xt = btn_font.render('\u00d7', True, COLORS['white'])
                self.screen.blit(xt, xt.get_rect(center=del_rect.center))
                self.detail_buttons.append((del_rect, score, 'delete'))

                y += self.ROW_HEIGHT

            # Draw delete-confirmation overlay if pending
            if self.confirm_delete is not None:
                ov = pygame.Surface(self.screen.get_size(), pygame.SRCALPHA)
                ov.fill((0, 0, 0, 160))
                self.screen.blit(ov, (0, 0))
                cx, cy = self.screen.get_width() // 2, self.screen.get_height() // 2
                dlg = pygame.Rect(cx - 200, cy - 70, 400, 140)
                pygame.draw.rect(self.screen, (40, 40, 60), dlg, border_radius=10)
                pygame.draw.rect(self.screen, COLORS['red'], dlg, border_radius=10, width=2)
                cf = get_font(self.settings.language, 'bold', 20)
                msg = cf.render(_t_or(self.settings.language, 'confirm_delete_score', 'Delete this score entry?'), True, COLORS['white'])
                self.screen.blit(msg, msg.get_rect(center=(cx, cy - 30)))
                yes_r = pygame.Rect(cx - 110, cy + 10, 90, 34)
                no_r  = pygame.Rect(cx + 20,  cy + 10, 90, 34)
                pygame.draw.rect(self.screen, (180, 50, 50), yes_r, border_radius=6)
                pygame.draw.rect(self.screen, COLORS['button'], no_r, border_radius=6)
                yt = cf.render(_t_or(self.settings.language, 'delete', 'Delete'), True, COLORS['white'])
                nt = cf.render(get_text(self.settings.language, 'cancel'), True, COLORS['white'])
                self.screen.blit(yt, yt.get_rect(center=yes_r.center))
                self.screen.blit(nt, nt.get_rect(center=no_r.center))
                # Store confirm dialog rects for run() to use
                self._confirm_yes_rect = yes_r
                self._confirm_no_rect  = no_r
                
        # Draw back button (rect comes from the shared header layout)
        back_rect = header['back']
        pygame.draw.rect(self.screen, COLORS['button'], back_rect, border_radius=10)
        
        back_font = get_font(self.settings.language, 'bold', 20)
        back_text = get_text(self.settings.language, 'back')
        back_surface = back_font.render(back_text, True, COLORS['white'])
        back_rect_center = back_rect.center
        self.screen.blit(back_surface, (
            back_rect_center[0] - back_surface.get_width() // 2, 
            back_rect_center[1] - back_surface.get_height() // 2
        ))
        
        # Draw scrollbar
        if self.scrollbar:
            self.scrollbar.draw(self.screen)
        
        # Filter menu is drawn LAST so it's always the topmost layer — it
        # previously drew before the score table, which then painted over
        # it, making it illegible.
        filter_menu_rects = self.draw_filter_menu(filter_rect)

        if (getattr(self, '_replay_share_notice', None) and
                time.monotonic() < getattr(self, '_replay_share_notice_until', 0.0)):
            notice = render_fit(get_font(self.settings.language, 'regular', 16),
                self._replay_share_notice, COLORS['light_gray'], self.screen.get_width() - 40)
            self.screen.blit(notice, notice.get_rect(
                center=(self.screen.get_width() // 2, self.screen.get_height() - 42)))
        
        # Update display
        _legacy_nav_draw(locals().get('self'))
        pygame.display.flip()
        
        return back_rect, search_rect, filter_rect, filter_menu_rects, import_rect

    def _paste_replay_share_code(self):
        try:
            score = import_replay_share_code(_read_from_clipboard())
            self._replay_share_notice = None
            self.view_replay(score)
        except (ValueError, TypeError, OSError) as exc:
            _logging_mod.getLogger('sgf').warning('Replay share import rejected: %s', exc)
            self._replay_share_notice = get_text(self.settings.language, 'replay_share_failed')
            self._replay_share_notice_until = time.monotonic() + 5.0
        
    def delete_score(self, score_data):
        """Delete a score and its independent replay file when unreferenced."""
        try:
            _gd = _load_data()
            highscores = _gd.get('highscores', [])
            game_id = score_data.get('game_id')
            if game_id:
                highscores = [s for s in highscores if s.get('game_id') != game_id]
            else:
                # Fallback: match by name + score + date
                highscores = [s for s in highscores if not (
                    s.get('name') == score_data.get('name') and
                    s.get('score') == score_data.get('score') and
                    s.get('date') == score_data.get('date')
                )]
            _gd['highscores'] = highscores
            if not _save_data(_gd):
                return
            _prune_score_replays(highscores, delete=True)    # the player deleted this score on purpose
            self.invalidate_highscores_cache()
        except Exception as e:
            print(f"Error deleting score: {e}")

    def _replay_notice(self, text):
        self._replay_share_notice = text
        self._replay_share_notice_until = time.monotonic() + 5.0

    def _replay_menu_body(self, score_data):
        language = self.settings.language
        board = score_data.get('board_size', '?')
        lines = [f"{get_text(language, 'board_size')}: {board}x{board} · "
                 f"{get_text(language, 'speed')}: {score_data.get('update_rate_ms', 200)}ms"]
        if score_data.get('seed'):
            lines.append(f"Seed: {score_data['seed']}")
        notice = getattr(self, '_replay_share_notice', None)
        if notice and time.monotonic() < getattr(self, '_replay_share_notice_until', 0.0):
            lines.append(notice)
        return '\n'.join(lines)

    def _replay_action_menu(self, score_data):
        """What to do with a replay: watch, race its ghost, copy a code, save a file."""
        language = self.settings.language
        chosen = {'action': None}
        menu = None

        def pick(action):
            chosen['action'] = action
            menu._go_back()

        entries = [('replay_watch', lambda: get_text(language, 'highscore_replay'),
                    COLORS['light_blue'], lambda: pick('watch'))]
        if _ghost_history_for_score(score_data) is not None:
            entries.append(('replay_race', lambda: get_text(language, 'daily_ghost_race'),
                            COLORS['purple'], lambda: pick('race')))
        entries.append(('replay_copy', lambda: get_text(language, 'replay_share_copy'),
                        COLORS['green'], lambda: pick('copy')))
        entries.append(('replay_file', lambda: _replay_ui_text(language, 'save_file'),
                        COLORS['button'], lambda: pick('file')))
        title = f"{score_data.get('name', '')}: {score_data.get('score', 0)}"
        menu = _SimpleMenuScreen(
            self.settings, self.screen, title_fn=lambda: title, entries=entries,
            body_fn=lambda: self._replay_menu_body(score_data))
        menu.runtime = getattr(self, 'runtime', None)
        menu.run()
        return chosen['action']

    def _copy_replay_share_code(self, score_data):
        language = self.settings.language
        try:
            copied = _copy_to_clipboard(export_replay_share_code(score_data))
            self._replay_notice(get_text(language, 'replay_share_copied' if copied else 'replay_share_failed'))
        except (ValueError, TypeError, OSError) as exc:
            _logging_mod.getLogger('sgf').warning('Replay share export failed: %s', exc)
            self._replay_notice(get_text(language, 'replay_share_failed'))

    def _save_replay_file(self, score_data):
        language = self.settings.language
        try:
            path = save_replay_file(score_data)
            self._replay_notice(_replay_ui_text(language, 'file_saved', name=os.path.basename(path)))
        except (ValueError, TypeError, OSError) as exc:
            _logging_mod.getLogger('sgf').warning('Replay file export failed: %s', exc)
            self._replay_notice(_replay_ui_text(language, 'file_failed'))

    def _import_replay_file(self, path):
        """A .sgfr file dropped on the window opens like a pasted share code."""
        try:
            score = load_replay_file(path)
        except (ValueError, TypeError, OSError, UnicodeError) as exc:
            _logging_mod.getLogger('sgf').warning('Replay file import rejected: %s', exc)
            self._replay_notice(_replay_ui_text(self.settings.language, 'file_import_failed'))
            return
        self._replay_share_notice = None
        self.view_replay(score)

    def _race_replay(self, score_data):
        """Play the replay's exact seed/rules live, racing its ghost."""
        history = _ghost_history_for_score(score_data)
        if history is None:
            self._replay_notice(get_text(self.settings.language, 'replay_share_failed'))
            return
        temp_settings = copy.deepcopy(self.settings)
        for key, value in (score_data.get('settings') or {}).items():
            if hasattr(temp_settings, key):
                setattr(temp_settings, key, value)
        if 'update_rate_ms' in score_data:
            temp_settings.update_rate_ms = score_data['update_rate_ms']
        game = SnakeGame(temp_settings, self.screen, seed=score_data.get('seed'),
                         custom_map=score_data.get('custom_map'))
        game.player_name = getattr(self, 'player_name', None) or 'Player'
        game.achievement_manager = getattr(self, 'achievement_manager', None)
        game.runtime = getattr(self, 'runtime', None)
        game._sgf_ghost_history = history
        game.run()
        self.invalidate_highscores_cache()

    def view_replay(self, score_data):
        """Replay actions: watch, race the ghost, copy a share code, save a file."""
        score_data = _history_for_score(score_data)
        if int(score_data.get('replay_format_version', 1) or 1) > _REPLAY_FORMAT_VERSION:
            self.show_details(score_data)
            return
        history = score_data.get('game_history', [])
        if not history and not score_data.get('mp_history'):
            self.show_details(score_data)
            return
        while True:
            action = self._replay_action_menu(score_data)
            if action == 'watch':
                self._play_replay(score_data)
            elif action == 'race':
                self._race_replay(score_data)
            elif action == 'copy':
                self._copy_replay_share_code(score_data)
            elif action == 'file':
                self._save_replay_file(score_data)
            else:
                return

    def _play_replay(self, score_data):
        """Load and play back a saved replay (single-, multi-player, or VS-AI)."""
        score_data = _history_for_score(score_data)
        replay_version = int(score_data.get('replay_format_version', 1) or 1)
        if replay_version > _REPLAY_FORMAT_VERSION:
            # Do not attempt to interpret a newer replay with an older reader.
            # Fall back to the metadata/detail view rather than silently showing
            # an incorrect simulation.
            self.show_details(score_data)
            return
        game_history = score_data.get('game_history', [])

        # ── VS-AI replay path ────────────────────────────────────────────
        if score_data.get('game_mode') == 'vs_ai':
            if not game_history or not isinstance(game_history[0], dict):
                self.show_details(score_data)
                return
            temp_settings = copy.deepcopy(self.settings)
            if 'settings' in score_data:
                for key, value in score_data['settings'].items():
                    if hasattr(temp_settings, key):
                        setattr(temp_settings, key, value)
            if 'update_rate_ms' in score_data:
                temp_settings.update_rate_ms = score_data['update_rate_ms']
            ai_count = score_data.get('ai_count', 1)
            ai_diff  = score_data.get('ai_difficulty', 'medium')
            vs_game  = VSAIGame(temp_settings, self.screen,
                                ai_count=ai_count, ai_difficulty=ai_diff,
                                seed=score_data.get('seed'),
                                custom_map=score_data.get('custom_map'))
            vs_game.start_replay(game_history)
            vs_game.run_replay()
            return

        # ── Multiplayer replay path ───────────────────────────────────────
        if score_data.get('is_multiplayer') and score_data.get('mp_history'):
            mp_history = score_data['mp_history']
            temp_settings = copy.deepcopy(self.settings)
            for key, value in (score_data.get('settings') or {}).items():
                if hasattr(temp_settings, key):
                    setattr(temp_settings, key, value)
            if 'update_rate_ms' in score_data:
                temp_settings.update_rate_ms = score_data['update_rate_ms']
            mode = score_data.get('mp_mode', '1v1')
            if isinstance(score_data.get('player_count'), int) and score_data['player_count'] > 0:
                game = LocalMultiplayerNGame(
                    temp_settings, self.screen, mode,
                    player_count=score_data['player_count'],
                    player_configs=score_data.get('player_configs'),
                    seed=score_data.get('seed'), custom_map=score_data.get('custom_map'))
            else:
                game = MultiplayerGame(temp_settings, self.screen, mode,
                                       custom_map=score_data.get('custom_map'))
            if game.start_replay(mp_history):
                game.run_replay()
            return

        # Single-player replay (existing logic)
        game_history = score_data.get('game_history', [])

        # Fall back to score-details screen for old/missing replays
        if not game_history or not isinstance(game_history[0], list):
            self.show_details(score_data)
            return

        # Recreate the original game settings so board size, speed, etc. match
        temp_settings = copy.deepcopy(self.settings)
        if 'settings' in score_data:
            for key, value in score_data['settings'].items():
                if hasattr(temp_settings, key):
                    setattr(temp_settings, key, value)
        # Also apply top-level convenience fields
        if 'update_rate_ms' in score_data:
            temp_settings.update_rate_ms = score_data['update_rate_ms']

        game = SnakeGame(temp_settings, self.screen, seed=score_data.get('seed'), custom_map=score_data.get('custom_map'))
        game.player_name = score_data.get('name', '')
        game.start_replay(game_history)
        game.run()
        
    def show_details(self, score_data):
        """Show detailed settings for a high score"""
        # Display a window with detailed information about the high score
        running = True
        details_clock = pygame.time.Clock()
        scrollbar = None
        last_geometry = None

        while running:
            _pump_audio()
            # Fill background
            self.screen.fill(COLORS['dark_blue'])
            
            # Draw title
            font = get_font(self.settings.language, 'bold', 26)
            title_text = f"{get_text(self.settings.language, 'score_details')}: {score_data['name']}"
            title_surface = font.render(title_text, True, COLORS['white'])
            self.screen.blit(title_surface, (self.screen.get_width() // 2 - title_surface.get_width() // 2, 50))
            
            # Draw score details
            details_font = get_font(self.settings.language, 'regular', 22)
            detail_spacing = 30
            left_margin = self.screen.get_width() // 4
            
            # Basic info
            details = [
                (f"{get_text(self.settings.language, 'score')}: {score_data['score']}", COLORS['white']),
                (f"{get_text(self.settings.language, 'date')}: {format_date_text(score_data['date'])}", COLORS['white']),
                (f"{get_text(self.settings.language, 'board_size')}: {score_data['board_size']}x{score_data['board_size']}", COLORS['white']),
                (f"{get_text(self.settings.language, 'speed')}: {score_data.get('update_rate_ms', 200)}ms", COLORS['white']),
                ("", COLORS['white']),  # Spacing
            ]
            _seed_val = score_data.get('seed', '')
            if _seed_val:
                details.insert(4, (f"Seed: {_seed_val}", (120, 150, 200)))
            
            # Game settings
            if 'settings' in score_data:
                settings_data = score_data['settings']
                # Add header for settings
                details.append((f"{get_text(self.settings.language, 'settings')}:", COLORS['light_blue']))
                
                # Display the settings in a readable format
                for key, value in settings_data.items():
                    # Skip complex objects and None values
                    if isinstance(value, (int, float, str, bool)) and value is not None:
                        # Format the key for better readability
                        formatted_key = key.replace('_', ' ').title()
                        details.append((f"{formatted_key}: {value}", COLORS['white']))
            
            # The list can be long (every setting of the run), so it scrolls inside the area between the
            # title and the buttons: wheel, scroll bar, PgUp/PgDn/Home/End and the arrow keys.
            screen_width, screen_height = self.screen.get_size()
            viewport_top = 110
            bottom_reserve = 74 if _score_has_replay(score_data) else 16
            viewport_height = max(1, screen_height - viewport_top - bottom_reserve)
            content_height = len(details) * detail_spacing + 20
            geometry = (screen_width, viewport_top, viewport_height)
            if scrollbar is None:
                scrollbar = ScrollBar(0, viewport_top, screen_width, viewport_height, content_height)
                last_geometry = geometry
            elif geometry != last_geometry:         # only on a real resize (see show_achievements)
                old_offset = scrollbar.scroll_offset
                scrollbar.set_geometry(0, viewport_top, screen_width, viewport_height)
                scrollbar.scroll_offset = min(old_offset, scrollbar.max_scroll)
                scrollbar.target_scroll = scrollbar.scroll_offset
                last_geometry = geometry
            scrollbar.wheel_rect = pygame.Rect(0, viewport_top, screen_width, viewport_height)
            scrollbar.set_content_height(content_height)
            scrollbar.update(getattr(self, '_dt', None))
            previous_clip = self.screen.get_clip()
            self.screen.set_clip(pygame.Rect(0, viewport_top, screen_width, viewport_height))
            detail_y = viewport_top + 10 - scrollbar.get_content_offset()
            for detail, color in details:
                if detail and viewport_top - detail_spacing < detail_y < viewport_top + viewport_height:
                    detail_surface = details_font.render(detail, True, color)
                    self.screen.blit(detail_surface, (left_margin, detail_y))
                detail_y += detail_spacing
            self.screen.set_clip(previous_clip)
            scrollbar.draw(self.screen)
            
            # Draw back button
            back_rect = pygame.Rect(50, 50, 100, 40)
            pygame.draw.rect(self.screen, COLORS['button'], back_rect, border_radius=10)
            
            back_font = get_font(self.settings.language, 'bold', 20)
            back_text = get_text(self.settings.language, 'back')
            back_surface = back_font.render(back_text, True, COLORS['white'])
            self.screen.blit(back_surface, (back_rect.centerx - back_surface.get_width() // 2, 
                                           back_rect.centery - back_surface.get_height() // 2))

            copy_rect = None
            if _score_has_replay(score_data):
                copy_rect = pygame.Rect(max(20, (self.screen.get_width() - 280) // 2),
                                        self.screen.get_height() - 62, 280, 42)
                pygame.draw.rect(self.screen, COLORS['blue'], copy_rect, border_radius=8)
                copy_label = get_text(self.settings.language, 'replay_share_copy')
                copy_surface = render_fit(get_font(self.settings.language, 'bold', 18),
                                          copy_label, COLORS['white'], copy_rect.width - 12)
                self.screen.blit(copy_surface, copy_surface.get_rect(center=copy_rect.center))
            if (getattr(self, '_replay_share_notice', None) and
                    time.monotonic() < getattr(self, '_replay_share_notice_until', 0.0)):
                notice_surface = render_fit(get_font(self.settings.language, 'regular', 16),
                    self._replay_share_notice, COLORS['light_gray'], self.screen.get_width() - 40)
                self.screen.blit(notice_surface, notice_surface.get_rect(
                    center=(self.screen.get_width() // 2, self.screen.get_height() - 82)))
            
            # Update display
            _legacy_nav_draw(locals().get('self'))
            pygame.display.flip()
            
            # Handle events
            for event in pygame.event.get():
                if _legacy_nav_event(locals().get('self'), event, locals()):
                    continue
                if getattr(self, 'runtime', None) is not None:
                    handled, _actions = self.runtime.input.route(event)
                    if handled:
                        continue
                if event.type == pygame.QUIT:
                    running = False
                    
                elif event.type in (pygame.MOUSEMOTION, pygame.MOUSEBUTTONUP):
                    scrollbar.handle_event(event, getattr(event, 'pos', None) or pygame.mouse.get_pos())
                elif event.type == pygame.MOUSEWHEEL:
                    wheel_pos = pygame.mouse.get_pos()
                    if scrollbar.wheel_rect.collidepoint(wheel_pos):
                        scrollbar.handle_event(event, wheel_pos)
                elif event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
                    if back_rect.collidepoint(event.pos):
                        running = False
                    elif not (copy_rect and copy_rect.collidepoint(event.pos)) and scrollbar.handle_event(event, event.pos):
                        pass                                  # click on the scroll bar track or thumb
                    elif copy_rect and copy_rect.collidepoint(event.pos):
                        try:
                            code = export_replay_share_code(score_data)
                            copied = _copy_to_clipboard(code)
                            self._replay_share_notice = get_text(
                                self.settings.language, 'replay_share_copied') if copied else get_text(
                                self.settings.language, 'replay_share_failed')
                            self._replay_share_notice_until = time.monotonic() + 5.0
                        except (ValueError, TypeError, OSError) as exc:
                            _logging_mod.getLogger('sgf').warning('Replay share export failed: %s', exc)
                            self._replay_share_notice = get_text(
                                self.settings.language, 'replay_share_failed')
                            self._replay_share_notice_until = time.monotonic() + 5.0
                        
                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_F11:
                        self.screen = _toggle_fullscreen(self.screen)
                    elif event.key == pygame.K_ESCAPE:
                        running = False
                    else:
                        for key_action in UI_INPUT.actions_for(event):
                            if scrollbar.handle_key(key_action):
                                break
            
            # Cap frame rate
            details_frame_ms = details_clock.tick(60)
            DEV_TOOLS.telemetry.record_frame(details_frame_ms)
    
    def run(self):
        """Run the high scores screen with scroll support"""
        running = True
        highscores_clock = pygame.time.Clock()
        if self.scrollbar is None:
            self.init_scrollbar()
        # Always reflect on-disk reality on (re)entry — a new game may have
        # added a score since this screen object was last shown.
        self.invalidate_highscores_cache()

        while running:
            _pump_audio()
            back_rect, search_rect, filter_rect, filter_menu_rects, import_rect = self.draw_screen()

            for event in pygame.event.get():
                if _legacy_nav_event(locals().get('self'), event, locals()):
                    continue
                if event.type == pygame.QUIT:
                    running = False

                if self.scrollbar:
                    self.scrollbar.handle_event(event)

                if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
                    mouse_pos = event.pos

                    # ── Delete confirmation dialog (highest priority) ─────────
                    if self.confirm_delete is not None:
                        yes_r = getattr(self, '_confirm_yes_rect', None)
                        no_r  = getattr(self, '_confirm_no_rect',  None)
                        if yes_r and yes_r.collidepoint(mouse_pos):
                            self.delete_score(self.confirm_delete)
                            self.confirm_delete = None
                        elif no_r and no_r.collidepoint(mouse_pos):
                            self.confirm_delete = None
                        continue  # eat click while dialog is open

                    # ── Primary navigation targets ───────────────────────────
                    primary_handled = False

                    if back_rect.collidepoint(mouse_pos):
                        running = False
                        primary_handled = True
                    elif search_rect.collidepoint(mouse_pos):
                        self.search_active = True
                        self.filter_menu_open = False
                        primary_handled = True
                    elif filter_rect.collidepoint(mouse_pos):
                        self.filter_menu_open = not self.filter_menu_open
                        self.search_active = False
                        primary_handled = True
                    elif import_rect and import_rect.collidepoint(mouse_pos):
                        self.search_active = False
                        primary_handled = True
                        self._paste_replay_share_code()

                    if primary_handled:
                        continue

                    # ── Filter menu items ────────────────────────────────────
                    if self.filter_menu_open:
                        menu_clicked = False
                        for rect, action in filter_menu_rects:
                            if rect.collidepoint(mouse_pos):
                                menu_clicked = True
                                if action == "close_filter":
                                    self.filter_menu_open = False
                                elif action == "reset_filters":
                                    self.filter_options = {
                                        "sort_by": "score",
                                        "order": "desc",
                                        "show_victories": "all",
                                        "difficulty": "all",
                                        "has_replay": "all",
                                        "obstacles": "all",
                                        "powerups": "all",
                                    }
                                elif ':' in action:
                                    key, val = action.split(':', 1)
                                    self.filter_options[key] = val
                                break
                        if not menu_clicked:
                            self.filter_menu_open = False
                        continue

                    # ── Row buttons (View / Delete) ──────────────────────────
                    row_handled = False
                    for btn_rect, score_data, btn_type in self.detail_buttons:
                        if btn_rect.collidepoint(mouse_pos):
                            row_handled = True
                            if btn_type == 'delete':
                                self.confirm_delete = score_data
                            elif score_data.get('has_replay', False):
                                self.view_replay(score_data)
                            else:
                                self.show_details(score_data)
                            break

                    # ── Clicking elsewhere deactivates search ────────────────
                    if not row_handled:
                        self.search_active = False

                elif event.type == pygame.DROPFILE:
                    self._import_replay_file(event.file)
                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_F11:
                        self.screen = _toggle_fullscreen(self.screen)
                    elif event.key == pygame.K_v and event.mod & pygame.KMOD_CTRL and not self.search_active:
                        self._paste_replay_share_code()
                    elif event.key == pygame.K_ESCAPE:
                        if self.confirm_delete is not None:
                            self.confirm_delete = None
                        elif self.filter_menu_open:
                            self.filter_menu_open = False
                        elif self.search_active:
                            self.search_active = False
                        else:
                            running = False
                    elif self.search_active:
                        if event.key == pygame.K_RETURN:
                            self.search_active = False
                        elif event.key == pygame.K_BACKSPACE:
                            self.search_text = self.search_text[:-1]
                        elif event.unicode.isprintable():
                            self.search_text += event.unicode

                elif event.type == pygame.VIDEORESIZE:
                    self.screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)
                    self.init_scrollbar()

            # Update scrollbar
            if self.scrollbar:
                self.scrollbar.update()
            
            # Cap the frame rate
            highscores_frame_ms = highscores_clock.tick(60)
            DEV_TOOLS.telemetry.record_frame(highscores_frame_ms)

##############
# SCROLL BAR
##############

class ScrollBar:
    """A scrollable interface component with smooth scrolling.

    Backward compatible with the original API (rect / content_height /
    scroll_offset / target_scroll / max_scroll / handle_event / update / draw /
    get_content_offset). Extended for the UI foundation:

      * `wheel_rect`     region that captures the mouse wheel (defaults to `rect`;
                         previously the wheel only worked over the thin bar itself)
      * set_geometry() / set_content_height()   re-fit without re-creating the bar
                         (keeps the scroll position; clamps to the new max)
      * scroll_by / scroll_to / page / home / end / ensure_visible
      * handle_key(action)   semantic-action keyboard scrolling
      * handle_event(event, mouse_pos=None)   explicit position (testable, no global state)
      * track click centres the thumb on the click; drag uses event.pos; no
        divide-by-zero on very short tracks
      * update(dt=None)  optional dt makes the easing frame-rate independent
    """
    def __init__(self, x, y, width, height, content_height):
        self.rect = pygame.Rect(x, y, width, height)
        self.content_height = content_height
        self.scroll_offset = 0
        self.max_scroll = max(0, content_height - height)

        # Scrollbar appearance
        self.bar_width = 12
        self.bar_rect = pygame.Rect(x + width - self.bar_width, y, self.bar_width, height)
        self.track_color = COLORS.get('scrollbar_track', (40, 40, 50))
        self.thumb_color = COLORS.get('scrollbar_thumb', (80, 80, 100))
        self.thumb_hover_color = COLORS.get('scrollbar_thumb_hover', (100, 100, 120))

        # Scrollbar state
        self.dragging = False
        self.hover = False
        self.last_mouse_y = 0
        self._grab_dy = 0

        # Smooth scrolling
        self.target_scroll = 0
        self.scroll_speed = 0.15

        # Extensions
        self.wheel_rect = None          # None -> self.rect
        self.line_step = UI_STYLE['scroll_line']

    # ── geometry / bounds ────────────────────────────────────────────────
    def _clamp(self, v):
        return max(0, min(self.max_scroll, v))

    def set_geometry(self, x, y, width, height):
        self.rect = pygame.Rect(x, y, width, height)
        self.bar_rect = pygame.Rect(x + width - self.bar_width, y, self.bar_width, height)
        self._refresh_bounds()

    def set_content_height(self, content_height):
        self.content_height = max(0, int(content_height))
        self._refresh_bounds()

    def _refresh_bounds(self):
        self.max_scroll = max(0, self.content_height - self.rect.height)
        self.target_scroll = self._clamp(self.target_scroll)
        self.scroll_offset = self._clamp(self.scroll_offset)

    @property
    def needs_scroll(self):
        # Some legacy screens update content_height directly. Refresh here so
        # visibility/max-scroll/thumb geometry always follow the current content.
        self._refresh_bounds()
        return self.max_scroll > 0

    # ── programmatic / keyboard scrolling ────────────────────────────────
    def scroll_to(self, y, immediate=False):
        self.target_scroll = self._clamp(y)
        if immediate:
            self.scroll_offset = self.target_scroll

    def scroll_by(self, dy, immediate=False):
        self.scroll_to(self.target_scroll + dy, immediate)

    def page(self, direction, immediate=False):
        """direction: +1 = down, -1 = up. One page = viewport minus a line of context."""
        self.scroll_by(direction * max(self.line_step, self.rect.height - self.line_step), immediate)

    def home(self, immediate=False):
        self.scroll_to(0, immediate)

    def end(self, immediate=False):
        self.scroll_to(self.max_scroll, immediate)

    def ensure_visible(self, top, bottom, margin=6, immediate=False):
        """Scroll minimally so content-space span [top, bottom] is inside the viewport."""
        view_top, view_h = self.target_scroll, self.rect.height
        if bottom - top + 2 * margin >= view_h:
            self.scroll_to(top - margin, immediate)
        elif top - margin < view_top:
            self.scroll_to(top - margin, immediate)
        elif bottom + margin > view_top + view_h:
            self.scroll_to(bottom + margin - view_h, immediate)

    def handle_key(self, action):
        """Semantic-action keyboard scrolling. Returns True if it scrolled/consumed."""
        if self.max_scroll <= 0:
            return False
        if action == 'MOVE_UP':
            self.scroll_by(-self.line_step)
        elif action == 'MOVE_DOWN':
            self.scroll_by(self.line_step)
        elif action == 'PAGE_UP':
            self.page(-1)
        elif action == 'PAGE_DOWN':
            self.page(1)
        elif action == 'HOME':
            self.home()
        elif action == 'END':
            self.end()
        else:
            return False
        return True

    def can_scroll(self, direction):
        """direction -1 up / +1 down: is there content left in that direction?"""
        if direction < 0:
            return self.target_scroll > 0
        return self.target_scroll < self.max_scroll

    # ── thumb ────────────────────────────────────────────────────────────
    def get_thumb_rect(self):
        """Calculate the thumb rectangle based on current scroll position"""
        self._refresh_bounds()
        if self.max_scroll <= 0 or self.content_height <= 0:
            return pygame.Rect(0, 0, 0, 0)  # No scrolling needed

        thumb_height = max(20, int(self.rect.height * self.rect.height / self.content_height))
        thumb_height = min(thumb_height, self.rect.height)
        travel = self.rect.height - thumb_height
        thumb_y = self.bar_rect.y + (self.scroll_offset / self.max_scroll) * travel

        return pygame.Rect(self.bar_rect.x, int(thumb_y), self.bar_width, thumb_height)

    # ── mouse ────────────────────────────────────────────────────────────
    def handle_event(self, event, mouse_pos=None):
        """Handle mouse events for scrolling. `mouse_pos` overrides the global
        pygame.mouse.get_pos() (used by tests and by managers that already know it)."""
        self._refresh_bounds()
        if event.type == pygame.MOUSEBUTTONDOWN:
            if event.button == 1 and self.max_scroll > 0:  # Left click
                pos = getattr(event, 'pos', None) or mouse_pos or pygame.mouse.get_pos()
                thumb_rect = self.get_thumb_rect()

                if thumb_rect.collidepoint(pos):
                    self.dragging = True
                    self.last_mouse_y = pos[1]
                    self._grab_dy = pos[1] - thumb_rect.y
                elif self.bar_rect.collidepoint(pos):
                    # Click on track - centre the thumb on the click
                    travel = self.rect.height - thumb_rect.height
                    if travel > 0:
                        rel = pos[1] - self.bar_rect.y - thumb_rect.height / 2
                        self.target_scroll = self._clamp(rel / travel * self.max_scroll)

        elif event.type == pygame.MOUSEBUTTONUP:
            if event.button == 1:
                self.dragging = False

        elif event.type == pygame.MOUSEMOTION:
            pos = getattr(event, 'pos', None) or mouse_pos or pygame.mouse.get_pos()
            thumb_rect = self.get_thumb_rect()
            self.hover = thumb_rect.collidepoint(pos) or self.bar_rect.collidepoint(pos)

            if self.dragging:
                travel = self.rect.height - thumb_rect.height
                if travel > 0:
                    rel = pos[1] - self._grab_dy - self.bar_rect.y
                    self.target_scroll = self._clamp(rel / travel * self.max_scroll)
                    self.last_mouse_y = pos[1]

        elif event.type == pygame.MOUSEWHEEL:
            pos = mouse_pos or pygame.mouse.get_pos()
            region = self.wheel_rect
            if region is None:
                # Legacy callers historically passed only the thin scrollbar
                # rect. Make the wheel usable across the page's vertical span
                # while preserving explicit wheel_rect ownership for UIScrollView.
                surf = pygame.display.get_surface()
                if surf is not None:
                    region = pygame.Rect(0, self.rect.y, surf.get_width(), self.rect.height)
                else:
                    region = self.rect
            if region.collidepoint(pos):
                self.target_scroll = self._clamp(self.target_scroll - event.y * self.line_step)

    def update(self, dt=None):
        """Update smooth scrolling animation. Pass dt (seconds) for frame-rate
        independent easing; without it the legacy per-frame factor is used."""
        if globals().get('_ACCESSIBILITY_REDUCED_MOTION', False):
            self.scroll_offset = self.target_scroll
            return
        if abs(self.target_scroll - self.scroll_offset) > 0.5:
            if dt is None:
                k = self.scroll_speed
            else:
                k = 1.0 - (1.0 - self.scroll_speed) ** (max(0.0, dt) * 60.0)
            self.scroll_offset += (self.target_scroll - self.scroll_offset) * k
        else:
            self.scroll_offset = self.target_scroll

    def draw(self, screen):
        """Draw the scrollbar"""
        self._refresh_bounds()
        if self.max_scroll <= 0:
            return  # No scrolling needed

        # Draw track
        pygame.draw.rect(screen, self.track_color, self.bar_rect, border_radius=6)

        # Draw thumb
        thumb_rect = self.get_thumb_rect()
        thumb_color = self.thumb_hover_color if self.hover or self.dragging else self.thumb_color
        pygame.draw.rect(screen, thumb_color, thumb_rect, border_radius=6)

    def get_content_offset(self):
        """Get the current content offset for rendering"""
        return int(self.scroll_offset)

##############
# UI FOUNDATION (AI-1)
##############
# Reusable layout primitives, semantic-action adapter, focus management and
# widgets. Everything here lives inside SGF.py on purpose (single-file
# distribution). Screens build a UIManager, add widgets, and route events to
# it; they no longer position elements with one-off pixel formulas.
#
#   layout   : UIVerticalFlow / UIHorizontalFlow  (fit -> compress -> scroll/wrap/drop)
#   input    : UI_INPUT (semantic actions; pluggable backend for the Action Mapping AI)
#   focus    : UIManager + UIFocus (Tab / Shift+Tab / arrows / Enter / Space / Esc / PgUp / PgDn / Home / End)
#   widgets  : UILabel UIButton UIPanel UICheckbox UISlider UIDropdown UITextInput
#              UIScrollView UIListView UITabBar UILayer/UIDialog
#   scrolling: ScrollBar (extended, backward compatible)
#
# Style constants live in UI_STYLE so a future Theme API has a single place to override.

UI_STYLE = {
    'radius': 8,
    'focus_color': (255, 214, 64),
    'focus_outline': (10, 10, 20),
    'disabled_bg': (70, 72, 82),
    'disabled_fg': (140, 142, 150),
    'input_bg': None,            # None -> COLORS['gray'] / COLORS['light_gray'] (legacy look)
    'panel_bg': (18, 24, 45),
    'panel_border': (60, 90, 140),
    'dim_overlay': (0, 0, 0, 160),
    'popup_bg': (30, 35, 55),
    'scroll_line': 30,
}


def _t_or(language, key, default):
    """get_text() that falls back to `default` (the current literal) when a key
    has not been added to the translation tables yet. Lets a screen become
    translatable later without another code change and never emits '[Missing: ..]'."""
    en = TRANSLATIONS.get('en', {})
    if key in en:
        return get_text(language, key)
    return default


def _ui_insets(p):
    """int | (h, v) | (l, t, r, b)  ->  (l, t, r, b)"""
    if p is None:
        return (0, 0, 0, 0)
    if isinstance(p, (int, float)):
        p = int(p)
        return (p, p, p, p)
    if len(p) == 2:
        return (int(p[0]), int(p[1]), int(p[0]), int(p[1]))
    return tuple(int(v) for v in p)


def _ui_clamp(v, lo, hi):
    return lo if v < lo else hi if v > hi else v


# ── UI text cache ─────────────────────────────────────────────────────────
# Rendering text (and shrinking it with render_fit) every frame is the main
# recurring UI cost. Rendered surfaces are cached by (language, style, size,
# text, colour, max width). The cache is bounded and evicts its least-recently
# used surface when it grows too large or when the language/font set changes.
_ui_text_cache = {}
_UI_TEXT_CACHE_MAX = 900


def ui_text_clear_cache():
    _ui_text_cache.clear()


def ui_text_surface(language, style, size, text, color, max_w=None):
    """Cached text surface. If `max_w` is given the text is shrunk with the
    existing render_fit() helper (no second fitting implementation)."""
    key = (language, style, size, text, tuple(color[:3]), max_w)
    surf, cached = _lru_cache_get(_ui_text_cache, key)
    if not cached:
        font = get_font(language, style, size)
        if max_w is None:
            surf = font.render(text, True, color)
        else:
            surf = render_fit(font, text, color, max_w, padding=0)
        _lru_cache_put(_ui_text_cache, key, surf, _UI_TEXT_CACHE_MAX)
    return surf


def ui_text_size(language, style, size, text):
    return get_font(language, style, size).size(text)


def ui_wrap_text(language, style, size, text, max_w):
    """Word-wrap using the existing _wrap_text(); additionally hard-breaks any
    line that is still too wide (CJK / Thai text has no spaces to break on)."""
    font = get_font(language, style, size)
    out = []
    for para in str(text).split('\n'):
        lines = _wrap_text(para, font, max(10, max_w)) or ['']
        for line in lines:
            if font.size(line)[0] <= max_w:
                out.append(line)
                continue
            cur = ''
            for ch in line:
                if cur and font.size(cur + ch)[0] > max_w:
                    out.append(cur)
                    cur = ch
                else:
                    cur += ch
            out.append(cur)
    return out or ['']


# ── Semantic input actions ────────────────────────────────────────────────
UI_ACTION_NAMES = (
    'CONFIRM', 'BACK', 'PLAY', 'OPEN_SETTINGS', 'EXIT_GAME', 'PAUSE', 'RESTART',
    'TOGGLE_FULLSCREEN', 'MOVE_UP', 'MOVE_DOWN', 'MOVE_LEFT', 'MOVE_RIGHT',
    # UI-navigation actions (not gameplay actions, but rebindable the same way)
    'FOCUS_NEXT', 'FOCUS_PREV', 'PAGE_UP', 'PAGE_DOWN', 'HOME', 'END', 'DELETE', 'PREVIOUS',
)


class UIInputAdapter:
    """Translates raw pygame KEYDOWN events into semantic action names.

    Integration point for the Action Mapping system: call
    `UI_INPUT.bind_backend(obj)` where `obj` provides EITHER
        actions_for(event) -> iterable[str]      (preferred)
    OR  matches(action_name, event) -> bool
    When a backend is bound it is authoritative for every name in
    UI_ACTION_NAMES it knows; the built-in table is only a fallback so the UI
    keeps working stand-alone. Screens never test pygame.K_* directly.
    """
    _SHIFT, _CTRL, _ALT = pygame.KMOD_SHIFT, pygame.KMOD_CTRL, pygame.KMOD_ALT

    def __init__(self):
        self._backend = None
        self.reset_defaults()

    def reset_defaults(self):
        K = pygame
        self.bindings = {
            'CONFIRM': [(K.K_RETURN, 0), (K.K_KP_ENTER, 0), (K.K_SPACE, 0)],
            'BACK': [(K.K_ESCAPE, 0)],
            'PLAY': [],
            'OPEN_SETTINGS': [],
            'EXIT_GAME': [(K.K_q, self._CTRL)],
            'PAUSE': [(K.K_p, 0)],
            'RESTART': [(K.K_r, 0)],
            'TOGGLE_FULLSCREEN': [(K.K_F11, 0)],
            'MOVE_UP': [(K.K_UP, 0)],
            'MOVE_DOWN': [(K.K_DOWN, 0)],
            'MOVE_LEFT': [(K.K_LEFT, 0)],
            'MOVE_RIGHT': [(K.K_RIGHT, 0)],
            'FOCUS_NEXT': [(K.K_TAB, 0)],
            'FOCUS_PREV': [(K.K_TAB, self._SHIFT)],
            'PAGE_UP': [(K.K_PAGEUP, 0)],
            'PAGE_DOWN': [(K.K_PAGEDOWN, 0)],
            'HOME': [(K.K_HOME, 0)],
            'END': [(K.K_END, 0)],
            'DELETE': [(K.K_DELETE, 0)],
            # Conventional back-one-step shortcut; visible Previous buttons are
            # still preferred wherever a nested flow exposes them.
            'PREVIOUS': [(K.K_LEFT, self._ALT)],
        }

    def bind_backend(self, backend):
        self._backend = backend

    def set_binding(self, action, keys):
        """keys: iterable of (pygame key, modifier-mask)."""
        self.bindings[action] = list(keys)

    def _mods(self, event):
        m = getattr(event, 'mod', 0)
        out = 0
        if m & self._SHIFT:
            out |= self._SHIFT
        if m & self._CTRL:
            out |= self._CTRL
        if m & self._ALT:
            out |= self._ALT
        return out

    def actions_for(self, event):
        if event.type != pygame.KEYDOWN:
            return []
        be = self._backend
        if be is not None:
            try:
                if hasattr(be, 'actions_for'):
                    got = [a for a in be.actions_for(event) if a in UI_ACTION_NAMES]
                    if got:
                        return got
                elif hasattr(be, 'matches'):
                    got = [a for a in UI_ACTION_NAMES if be.matches(a, event)]
                    if got:
                        return got
            except Exception as exc:      # a broken backend must never break the UI
                print(f"UI input backend error: {exc}")
        mods = self._mods(event)
        key = event.key
        return [a for a, keys in self.bindings.items()
                if any(k == key and m == mods for k, m in keys)]

    def matches(self, action, event):
        return action in self.actions_for(event)


UI_INPUT = UIInputAdapter()


# ── Layout: vertical flow ─────────────────────────────────────────────────
class UIFlowItem:
    __slots__ = ('key', 'h', 'min_h', 'max_h', 'w', 'min_w', 'max_w', 'gap',
                 'min_gap', 'flex', 'align')

    def __init__(self, key, h=0, min_h=None, max_h=None, w=None, min_w=None,
                 max_w=None, gap=None, min_gap=None, flex=0, align=None):
        self.key, self.h = key, int(h)
        self.min_h = int(h if min_h is None else min(min_h, h))
        self.max_h = max_h
        self.w, self.min_w, self.max_w = w, min_w, max_w
        self.gap, self.min_gap = gap, min_gap
        self.flex, self.align = flex, align


class UIFlowResult:
    """Outcome of a flow solve. `rects` are in absolute coordinates for scroll
    offset 0 (a ScrollView shifts them). mode: fit | compress | scroll | overflow."""

    def __init__(self, rects, content_height, mode, t, overflow, inner):
        self.rects, self.content_height = rects, content_height
        self.mode, self.t, self.overflow, self.inner = mode, t, overflow, inner

    def __getitem__(self, key):
        return self.rects[key]

    def get(self, key, default=None):
        return self.rects.get(key, default)

    @property
    def scrollable(self):
        return self.mode == 'scroll'


def _validate_ui_layout(rects, viewport, *, focus_order=(), required_focus=(),
                        text_metrics=None, content_height=None, scrollable=False,
                        scroll_offset=0, allowed_overlaps=()):
    """Return structural UI layout issues for headless and DEV regressions.

    `rects` maps control names to viewport-relative pygame.Rect values.
    Text metrics map names to `(rendered_width, available_width)` pairs.
    Intentional overlays can be excluded with `(name_a, name_b)` pairs.
    """
    viewport = pygame.Rect(viewport)
    rects = {str(key): pygame.Rect(value) for key, value in (rects or {}).items()}
    issues = []
    for key, rect in rects.items():
        if rect.width <= 0 or rect.height <= 0:
            issues.append({'code': 'invalid_rect', 'element': key})
        if (rect.left < viewport.left or rect.top < viewport.top
                or rect.right > viewport.right or rect.bottom > viewport.bottom):
            issues.append({'code': 'off_screen', 'element': key})

    allowed = {frozenset(pair) for pair in allowed_overlaps}
    names = list(rects)
    for i, first in enumerate(names):
        for second in names[i + 1:]:
            if (frozenset((first, second)) not in allowed
                    and rects[first].colliderect(rects[second])):
                issues.append({'code': 'overlap', 'elements': (first, second)})

    focused = {str(item) for item in focus_order}
    for key in required_focus:
        key = str(key)
        if key not in rects:
            issues.append({'code': 'missing_control', 'element': key})
        elif key not in focused:
            issues.append({'code': 'missing_focus', 'element': key})

    for key, metrics in (text_metrics or {}).items():
        try:
            rendered, available = metrics
            if float(rendered) > float(available):
                issues.append({'code': 'text_clipped', 'element': str(key)})
        except (TypeError, ValueError, OverflowError):
            issues.append({'code': 'invalid_text_metrics', 'element': str(key)})

    if content_height is not None:
        try:
            content_height = float(content_height)
            scroll_offset = float(scroll_offset)
            if content_height < 0:
                issues.append({'code': 'invalid_content_height'})
            else:
                if content_height > viewport.height and not scrollable:
                    issues.append({'code': 'scroll_unavailable'})
                if not 0 <= scroll_offset <= max(0.0, content_height - viewport.height):
                    issues.append({'code': 'invalid_scroll_offset'})
        except (TypeError, ValueError, OverflowError):
            issues.append({'code': 'invalid_scroll_metrics'})
    return issues


def _ui_distribute(values, target):
    """Round a list of floats to ints whose sum is exactly `target`
    (largest-remainder), so compressed layouts have no 1 px drift."""
    base = [int(v) for v in values]
    rem = target - sum(base)
    order = sorted(range(len(values)), key=lambda i: values[i] - base[i], reverse=True)
    n = len(order)
    i = 0
    while rem > 0 and n:
        base[order[i % n]] += 1
        rem -= 1
        i += 1
    while rem < 0 and n:
        j = order[-1 - (i % n)]
        if base[j] > 0:
            base[j] -= 1
            rem += 1
        i += 1
        if i > 4 * n + 4:
            break
    return base


class UIVerticalFlow:
    """Running-cursor vertical layout with the three-stage policy

        fit      everything at its preferred size (flex items absorb extra room,
                 leftover room is placed according to `valign`)
        compress every height and gap shrinks linearly toward its minimum
        scroll   even minimum sizes do not fit -> content is laid out at minimum
                 size and `mode == 'scroll'`; the caller wraps it in a ScrollView

    Pure geometry: no drawing, no pygame surfaces, easy to unit-test.
    """

    def __init__(self, rect, padding=0, spacing=8, min_spacing=2, align='center',
                 valign='top', allow_compress=True, allow_scroll=True):
        self.rect = pygame.Rect(rect)
        self.padding = _ui_insets(padding)
        self.spacing = int(spacing)
        self.min_spacing = int(min(min_spacing, spacing))
        self.align, self.valign = align, valign
        self.allow_compress, self.allow_scroll = allow_compress, allow_scroll
        self.items = []

    def add(self, key, h=0, **kw):
        it = UIFlowItem(key, h, **kw)
        self.items.append(it)
        return it

    def spacer(self, key, min_h=0, flex=1):
        return self.add(key, h=min_h, min_h=min_h, flex=flex)

    def solve(self):
        pl, pt, pr, pb = self.padding
        r = self.rect
        inner = pygame.Rect(r.x + pl, r.y + pt, max(0, r.w - pl - pr), max(0, r.h - pt - pb))
        items = self.items
        n = len(items)
        gp = [0] * n      # preferred gap before item i
        gm = [0] * n      # minimum gap before item i
        for i, it in enumerate(items):
            if i:
                gp[i] = it.gap if it.gap is not None else self.spacing
                gm[i] = it.min_gap if it.min_gap is not None else min(self.min_spacing, gp[i])
                gm[i] = min(gm[i], gp[i])
        hp = [it.h for it in items]
        hm = [it.min_h for it in items]
        avail = inner.h
        pref_total = sum(hp) + sum(gp)
        min_total = sum(hm) + sum(gm)

        mode, t, overflow = 'fit', 0.0, 0
        if pref_total <= avail:
            heights, gaps = list(hp), list(gp)
            extra = avail - pref_total
            flex = [(i, it.flex) for i, it in enumerate(items) if it.flex > 0]
            while extra > 0 and flex:              # distribute, honouring max_h caps
                tw = sum(w for _, w in flex)
                given, capped = 0, []
                for i, w in flex:
                    share = int(extra * w / tw)
                    cap = items[i].max_h
                    if cap is not None and heights[i] + share > cap:
                        share = max(0, cap - heights[i])
                        capped.append((i, w))
                    heights[i] += share
                    given += share
                extra -= given
                flex = [f for f in flex if f not in capped]
                if given == 0:
                    if flex:                       # remainder pixels -> first flex item
                        heights[flex[0][0]] += extra
                        extra = 0
                    break
            used = sum(heights) + sum(gaps)
            free = avail - used
        elif self.allow_compress and min_total <= avail:
            mode = 'compress'
            t = (pref_total - avail) / float(pref_total - min_total) if pref_total > min_total else 1.0
            vals = [hp[i] - t * (hp[i] - hm[i]) for i in range(n)] + \
                   [gp[i] - t * (gp[i] - gm[i]) for i in range(n)]
            ints = _ui_distribute(vals, avail)
            heights, gaps = ints[:n], ints[n:]
            free = 0
        else:
            mode = 'scroll' if self.allow_scroll else 'overflow'
            t = 1.0
            heights, gaps = list(hm), list(gm)
            overflow = max(0, min_total - avail)
            free = 0

        y = inner.y
        if free > 0:
            y += free if self.valign == 'bottom' else free // 2 if self.valign == 'center' else 0
        rects = {}
        for i, it in enumerate(items):
            y += gaps[i]
            w = inner.w if it.w is None else it.w
            if it.max_w is not None:
                w = min(w, it.max_w)
            if it.min_w is not None:
                w = max(w, it.min_w)
            w = min(w, inner.w)
            al = it.align or self.align
            x = inner.x if al == 'left' else inner.right - w if al == 'right' else inner.x + (inner.w - w) // 2
            rects[it.key] = pygame.Rect(x, y, w, heights[i])
            y += heights[i]
        content_h = (y - inner.y) + pt + pb
        return UIFlowResult(rects, content_h, mode, t, overflow, inner)


# ── Layout: horizontal flow (wrap / compress / drop optional) ────────────
class UIHFlowItem:
    __slots__ = ('key', 'w', 'min_w', 'max_w', 'h', 'flex', 'priority', 'anchor_center')

    def __init__(self, key, w, min_w=None, max_w=None, h=0, flex=0, priority=0,
                 anchor_center=False):
        self.key, self.w = key, int(w)
        self.min_w = int(w if min_w is None else min(min_w, w))
        self.max_w = max_w
        self.h, self.flex, self.priority = int(h), flex, priority
        self.anchor_center = anchor_center


class UIHFlowResult:
    def __init__(self, rects, rows, height, hidden, mode):
        self.rects, self.rows, self.height = rects, rows, height
        self.hidden, self.mode = hidden, mode

    def __getitem__(self, key):
        return self.rects[key]

    def get(self, key, default=None):
        return self.rects.get(key, default)


class UIHorizontalFlow:
    """Left-to-right layout inside a fixed width. Policy per row:

        fit       preferred widths; flex items grow into free space
        compress  widths shrink linearly toward min_w
        wrap      (wrap=True)  items that cannot share a row move to the next row
        drop      (drop_optional=True) items with priority>0 are hidden, highest
                  priority number first, until the remainder fits
    """

    def __init__(self, rect, spacing=8, row_spacing=6, wrap=False, drop_optional=False,
                 align='left', valign='center'):
        self.rect = pygame.Rect(rect)
        self.spacing, self.row_spacing = int(spacing), int(row_spacing)
        self.wrap, self.drop_optional = wrap, drop_optional
        self.align, self.valign = align, valign
        self.items = []

    def add(self, key, w, **kw):
        it = UIHFlowItem(key, w, **kw)
        self.items.append(it)
        return it

    def _solve_row(self, items, width):
        """Returns list of widths (or None if min widths do not fit) and free space."""
        n = len(items)
        if n == 0:
            return [], 0
        sp = self.spacing * (n - 1)
        pref = sum(i.w for i in items) + sp
        minw = sum(i.min_w for i in items) + sp
        if pref <= width:
            widths = [i.w for i in items]
            extra = width - pref
            flex = [(k, it.flex) for k, it in enumerate(items) if it.flex > 0]
            while extra > 0 and flex:
                tw = sum(w for _, w in flex)
                given, capped = 0, []
                for k, w in flex:
                    share = int(extra * w / tw)
                    cap = items[k].max_w
                    if cap is not None and widths[k] + share > cap:
                        share = max(0, cap - widths[k])
                        capped.append((k, w))
                    widths[k] += share
                    given += share
                extra -= given
                flex = [f for f in flex if f not in capped]
                if given == 0:
                    if flex:
                        widths[flex[0][0]] += extra
                        extra = 0
                    break
            return widths, extra
        if minw <= width:
            t = (pref - width) / float(pref - minw) if pref > minw else 1.0
            vals = [i.w - t * (i.w - i.min_w) for i in items]
            return _ui_distribute(vals, width - sp), 0
        return None, 0

    def solve(self):
        r = self.rect
        items = list(self.items)
        hidden = []
        # 1) optionally drop low-priority items until one row fits
        if self.drop_optional and not self.wrap:
            while items and self._solve_row(items, r.w)[0] is None:
                cands = [(it.priority, idx) for idx, it in enumerate(items) if it.priority > 0]
                if not cands:
                    break
                _, idx = max(cands)
                hidden.append(items.pop(idx).key)
        # 2) pack rows
        rows = []
        if self.wrap:
            cur = []
            for it in items:
                trial = cur + [it]
                if cur and self._solve_row(trial, r.w)[0] is None:
                    rows.append(cur)
                    cur = [it]
                else:
                    cur = trial
            if cur:
                rows.append(cur)
        else:
            rows = [items]
        rects, keys_rows, y, mode = {}, [], r.y, 'fit'
        for ri, row in enumerate(rows):
            widths, free = self._solve_row(row, r.w)
            if widths is None:                       # cannot fit even at min: squeeze evenly
                mode = 'overflow'
                sp = self.spacing * (len(row) - 1)
                each = max(1, (r.w - sp) // max(1, len(row)))
                widths, free = [each] * len(row), 0
            elif sum(i.w for i in row) + self.spacing * (len(row) - 1) > r.w:
                mode = 'compress' if mode == 'fit' else mode
            row_h = max([it.h for it in row] + [0])
            if ri:
                y += self.row_spacing
            x = r.x
            if free > 0:
                x += free if self.align == 'right' else free // 2 if self.align == 'center' else 0
            placed = []
            for it, w in zip(row, widths):
                h = it.h or row_h
                yy = y + (row_h - h) // 2 if self.valign == 'center' else y
                rc = pygame.Rect(x, yy, w, h)
                rects[it.key] = rc
                placed.append((it, rc))
                x += w + self.spacing
            # soft-centre anchored items (e.g. a title) without touching neighbours
            for idx, (it, rc) in enumerate(placed):
                if it.anchor_center and len(rows) == 1:
                    lo = placed[idx - 1][1].right + self.spacing if idx else r.x
                    hi = placed[idx + 1][1].x - self.spacing if idx + 1 < len(placed) else r.right
                    w = min(it.w, hi - lo)
                    if w > 0:
                        nx = _ui_clamp(r.centerx - w // 2, lo, hi - w)
                        rects[it.key] = pygame.Rect(nx, rc.y, w, rc.h)
            keys_rows.append([it.key for it in row])
            y += row_h
        if len(rows) > 1 and mode != 'overflow':
            mode = 'wrap'
        return UIHFlowResult(rects, keys_rows, y - r.y, hidden, mode)

# ── Widgets ───────────────────────────────────────────────────────────────
_ui_glow_cache = {}


def ui_draw_focus_ring(surface, rect, radius=8):
    """Two-tone ring (dark outline + bright band) so focus is visible on any background."""
    pygame.draw.rect(surface, UI_STYLE['focus_outline'], rect.inflate(10, 10),
                     width=2, border_radius=radius + 4)
    pygame.draw.rect(surface, UI_STYLE['focus_color'], rect.inflate(6, 6),
                     width=2, border_radius=radius + 2)


def _ui_shade(color, delta):
    return tuple(max(0, min(255, c + delta)) for c in color[:3])


# ---- Text editing shared by every text box: key repeat, a gentle caret, the I-beam pointer ----
TEXT_REPEAT_DELAY_MS, TEXT_REPEAT_INTERVAL_MS = 400, 35       # holding a key: wait, then repeat steadily
TEXT_CARET_SOLID_MS, TEXT_CARET_PERIOD_MS = 530, 1060         # the caret stays solid after typing, then fades in and out
_UI_CURSOR = {'kind': None}


class KeyRepeater:
    """Auto-repeat for one held key, driven by a clock the caller passes in (so it is testable and never depends on a global
    setting: pygame's own set_repeat would also repeat movement keys and shortcuts during a game). The screen calls press()
    on KEYDOWN, release() on KEYUP and poll() every frame; poll() returns the KEYDOWN events to replay."""
    NO_REPEAT = frozenset({pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_ESCAPE, pygame.K_TAB})

    def __init__(self, delay=TEXT_REPEAT_DELAY_MS, interval=TEXT_REPEAT_INTERVAL_MS):
        self.delay, self.interval = delay, interval
        self.event, self.next_at = None, 0

    def press(self, event, now):
        if event.key in self.NO_REPEAT or (getattr(event, 'mod', 0) & (pygame.KMOD_CTRL | pygame.KMOD_ALT)):
            self.event = None
            return
        self.event, self.next_at = event, now + self.delay

    def release(self, key=None):
        if key is None or (self.event is not None and self.event.key == key):
            self.event = None

    def poll(self, now, limit=4):
        out = []
        while self.event is not None and now >= self.next_at and len(out) < limit:
            ev = self.event
            out.append(pygame.event.Event(pygame.KEYDOWN, key=ev.key, unicode=getattr(ev, 'unicode', ''),
                                          mod=getattr(ev, 'mod', 0), scancode=getattr(ev, 'scancode', 0)))
            self.next_at += self.interval
        if self.event is not None and now >= self.next_at:
            self.next_at = now + self.interval                    # a stalled frame never floods the field with repeats
        return out


def text_caret_alpha(now_ms, last_input_ms):
    """0 to 255: solid while the player types or moves the caret, then a smooth fade in and out (steady with reduced motion)."""
    idle = now_ms - last_input_ms
    if idle < TEXT_CARET_SOLID_MS or globals().get('_ACCESSIBILITY_REDUCED_MOTION', False):
        return 255
    phase = ((idle - TEXT_CARET_SOLID_MS) % TEXT_CARET_PERIOD_MS) / float(TEXT_CARET_PERIOD_MS)
    return int(255 * (0.5 + 0.5 * math.cos(2.0 * math.pi * phase)))


def draw_text_caret(surface, x, top, bottom, color, now_ms, last_input_ms):
    alpha = text_caret_alpha(now_ms, last_input_ms)
    if alpha <= 0 or bottom <= top:
        return
    stripe = pygame.Surface((2, int(bottom - top)), pygame.SRCALPHA)
    stripe.fill((color[0], color[1], color[2], alpha))
    surface.blit(stripe, (int(x), int(top)))


def ui_set_cursor(kind):
    """'ibeam' over something the player can type into, 'arrow' everywhere else (only touched when it changes)."""
    if _UI_CURSOR['kind'] == kind:
        return
    _UI_CURSOR['kind'] = kind
    try:
        pygame.mouse.set_cursor(pygame.SYSTEM_CURSOR_IBEAM if kind == 'ibeam' else pygame.SYSTEM_CURSOR_ARROW)
    except (pygame.error, AttributeError, TypeError):
        pass


class TextEditor:
    """One line of text being edited by a screen that draws its own boxes: caret movement (Left, Right, Home, End),
    Backspace and Delete, typing with an optional character filter and length limit, and a caret that stays solid while
    the player types. Held keys repeat through a KeyRepeater owned by the screen (which replays KEYDOWN events here)."""

    def __init__(self, text='', max_len=40, allowed=None, now=None):
        self.max_len, self.allowed = max_len, allowed
        self.text = str(text)[:max_len]
        self.caret = len(self.text)
        self.now = now or pygame.time.get_ticks
        self.last_input = self.now()
        self.scroll_x = 0

    def key(self, event):
        """Apply a KEYDOWN. Returns 'changed' (the text changed), 'moved' (consumed, the text is the same), 'enter',
        'escape', or None for a key a text box does not use."""
        key = event.key
        if key in (pygame.K_RETURN, pygame.K_KP_ENTER):
            return 'enter'
        if key == pygame.K_ESCAPE:
            return 'escape'
        self.last_input = self.now()
        if key == pygame.K_BACKSPACE:
            if self.caret <= 0:
                return 'moved'
            self.text = self.text[:self.caret - 1] + self.text[self.caret:]
            self.caret -= 1
            return 'changed'
        if key == pygame.K_DELETE:
            if self.caret >= len(self.text):
                return 'moved'
            self.text = self.text[:self.caret] + self.text[self.caret + 1:]
            return 'changed'
        if key == pygame.K_LEFT:
            self.caret = max(0, self.caret - 1)
            return 'moved'
        if key == pygame.K_RIGHT:
            self.caret = min(len(self.text), self.caret + 1)
            return 'moved'
        if key == pygame.K_HOME:
            self.caret = 0
            return 'moved'
        if key == pygame.K_END:
            self.caret = len(self.text)
            return 'moved'
        ch = getattr(event, 'unicode', '')
        if ch and ch.isprintable() and not (getattr(event, 'mod', 0) & (pygame.KMOD_CTRL | pygame.KMOD_ALT)):
            if (self.allowed is None or self.allowed(ch)) and len(self.text) + len(ch) <= self.max_len:
                self.text = self.text[:self.caret] + ch + self.text[self.caret:]
                self.caret += len(ch)
                return 'changed'
            return 'moved'
        return None

    def caret_from_x(self, x, font):
        """The caret position nearest to x pixels from the start of the text."""
        best, previous = len(self.text), 0
        for index in range(len(self.text) + 1):
            width = font.size(self.text[:index])[0]
            if width >= x:
                return index if index == 0 or (width - x) < (x - previous) else index - 1
            previous = width
        return best

    def draw(self, surface, area, font, color):
        old = surface.get_clip()
        surface.set_clip(old.clip(area))
        full, caret_x = font.size(self.text)[0], font.size(self.text[:self.caret])[0]
        if full + 3 <= area.w:
            self.scroll_x = 0
        else:
            if caret_x - self.scroll_x > area.w - 3:
                self.scroll_x = caret_x - area.w + 3
            elif caret_x - self.scroll_x < 0:
                self.scroll_x = caret_x
            self.scroll_x = max(0, min(self.scroll_x, full - area.w + 3))
        if self.text:
            surf = font.render(self.text, True, color)
            surface.blit(surf, (area.x - self.scroll_x, area.centery - surf.get_height() // 2))
        half = font.get_height() // 2
        draw_text_caret(surface, area.x - self.scroll_x + caret_x, area.centery - half, area.centery + half, color,
                        self.now(), self.last_input)
        surface.set_clip(old)


def nice_ticks(low, high, count=4):
    """(ticks, step): round numbers (1, 2, 2.5, 5 times a power of ten) that span low..high, for an axis."""
    if not (math.isfinite(low) and math.isfinite(high)):
        return [0.0, 1.0], 1.0
    if high - low < 1e-12:
        low, high = low - 0.5, high + 0.5
    rough = (high - low) / max(1, count)
    magnitude = 10 ** math.floor(math.log10(rough))
    step = magnitude * 10
    for factor in (1, 2, 2.5, 5, 10):
        if rough <= factor * magnitude + 1e-12:
            step = factor * magnitude
            break
    value, ticks = math.ceil(low / step - 1e-9) * step, []
    while value <= high + step * 1e-9 and len(ticks) < 24:
        ticks.append(round(value, 10))
        value += step
    return ticks, step


def format_tick(value, step=1.0):
    """An axis number: 1.5M, 12k, or the plain number with only the decimals the step needs."""
    magnitude = abs(value)
    if magnitude >= 1e6:
        return f'{value / 1e6:.3g}M'
    if magnitude >= 1e4:
        return f'{value / 1e3:.3g}k'
    decimals = 0
    while decimals < 4 and abs(round(step, decimals) - step) > 1e-9:
        decimals += 1
    text = f'{value:.{decimals}f}'
    return '0' if float(text) == 0 else text


class TrainingChart:
    """The training chart: axes with round-number scales, the window that is shown (zoom with the wheel, move by dragging,
    reset with a double click; it follows the newest data while it is at the right edge) and a read-out of the values under
    the pointer. The data is a list of points with 'total' (steps trained so far), 'avg_fruits' and 'avg_reward'."""
    LEFT, RIGHT_DUAL, RIGHT, BOTTOM, TOP = 38, 38, 8, 15, 6
    SERIES = (('avg_fruits', 'axis_fruits', (70, 210, 100)), ('avg_reward', 'axis_reward', (240, 200, 60)))

    def __init__(self):
        self.view, self.follow, self.mode = None, True, 'both'      # the window (first, last) in steps, or None for everything
        self.drag, self.last_click, self.last_plot = None, 0, None

    @staticmethod
    def bounds(points):
        return (points[0]['total'], points[-1]['total']) if len(points) >= 2 and points[-1]['total'] > points[0]['total'] else (0, 1)

    @staticmethod
    def min_width(points):
        first, last = TrainingChart.bounds(points)
        return max(3.0 * (last - first) / max(1, len(points) - 1), 1.0)

    def current(self, points):
        first, last = self.bounds(points)
        if self.view is None:
            return first, last
        width = max(self.min_width(points), self.view[1] - self.view[0])
        if width >= last - first:
            return first, last
        end = last if self.follow else self.view[1]
        start = max(first, min(end - width, last - width))
        return start, start + width

    def _set(self, start, end, points):
        first, last = self.bounds(points)
        width = end - start
        if width >= last - first - 1e-9:
            self.view, self.follow = None, True
            return
        if start < first:
            start, end = first, first + width
        if end > last:
            start, end = last - width, last
        self.view, self.follow = (start, end), (last - end) <= width * 0.02

    def zoom(self, points, factor, anchor=0.5):
        """Zoom by `factor` (below 1: closer) around `anchor`, a fraction (0 to 1) of the window width."""
        if len(points) < 3:
            return
        first, last = self.bounds(points)
        start, end = self.current(points)
        width = max(self.min_width(points), min(last - first, (end - start) * factor))
        centre = start + (end - start) * anchor
        self._set(centre - width * anchor, centre - width * anchor + width, points)

    def pan_from(self, points, start_view, delta_steps):
        self._set(start_view[0] + delta_steps, start_view[1] + delta_steps, points)

    def reset(self):
        self.view, self.follow = None, True

    def nearest(self, points, step):
        """The point nearest to a step count."""
        totals = [p['total'] for p in points]
        index = bisect.bisect_left(totals, step)
        candidates = [i for i in (index - 1, index) if 0 <= i < len(points)]
        return min(candidates, key=lambda i: abs(totals[i] - step)) if candidates else None

    def active(self):
        return [item for item in self.SERIES if self.mode == 'both' or self.mode == item[0].replace('avg_', '')]

    def draw(self, surface, rect, points, font, labels, mouse=None):
        """Draw the chart in `rect`. Returns the point under the pointer (or None)."""
        pygame.draw.rect(surface, (30, 36, 60), rect, border_radius=5)
        self.last_plot = None
        if len(points) < 2 or points[-1]['total'] <= points[0]['total']:
            text = render_fit(font, labels['empty'], COLORS['light_gray'], rect.w - 12, padding=0)
            surface.blit(text, text.get_rect(center=rect.center))
            return None
        series = self.active()
        plot = pygame.Rect(rect.x + self.LEFT, rect.y + self.TOP, rect.w - self.LEFT - (self.RIGHT_DUAL if len(series) == 2 else self.RIGHT),
                           rect.h - self.TOP - self.BOTTOM)
        if plot.w < 20 or plot.h < 12:
            return None
        self.last_plot = plot
        start, end = self.current(points)
        totals = [p['total'] for p in points]
        low_i, high_i = max(0, bisect.bisect_left(totals, start) - 1), min(len(points), bisect.bisect_right(totals, end) + 1)
        shown = points[low_i:high_i]
        grid, text_color = (52, 60, 92), COLORS['light_gray']
        x_of = lambda step: plot.x + plot.w * (step - start) / float(end - start)
        ticks, step_size = nice_ticks(start, end, max(2, plot.w // 45))
        for tick in ticks:
            if start <= tick <= end:
                x = int(x_of(tick))
                pygame.draw.line(surface, grid, (x, plot.y), (x, plot.bottom))
                label = font.render(format_tick(tick, step_size), True, text_color)
                surface.blit(label, (min(max(rect.x, x - label.get_width() // 2), rect.right - label.get_width()), plot.bottom + 2))
        old_clip = surface.get_clip()
        mappers = []
        for index, (key, _label, color) in enumerate(series):
            values = [p[key] for p in shown]
            low, high = min(values), max(values)
            pad = (high - low) * 0.08 or 0.5
            y_ticks, y_step = nice_ticks(low - pad, high + pad, max(2, plot.h // 34))
            axis_low, axis_high = min(low - pad, y_ticks[0]), max(high + pad, y_ticks[-1])
            y_of = (lambda lo, hi: lambda v: plot.bottom - plot.h * (v - lo) / float(hi - lo))(axis_low, axis_high)
            mappers.append(y_of)
            for tick in y_ticks:
                y = int(y_of(tick))
                if plot.y - 1 <= y <= plot.bottom + 1:
                    if index == 0:
                        pygame.draw.line(surface, grid, (plot.x, y), (plot.right, y))
                    label = font.render(format_tick(tick, y_step), True, color)
                    surface.blit(label, (plot.x - label.get_width() - 3, y - label.get_height() // 2) if index == 0
                                 else (plot.right + 3, y - label.get_height() // 2))
        surface.set_clip(old_clip.clip(plot))
        for (key, _label, color), y_of in zip(series, mappers):
            line = [(x_of(p['total']), y_of(p[key])) for p in shown]
            if len(line) >= 2:
                pygame.draw.lines(surface, color, False, line, 2)
        surface.set_clip(old_clip)
        hovered = None
        if mouse is not None and plot.collidepoint(mouse):
            hovered = self.nearest(points, start + (mouse[0] - plot.x) / float(plot.w) * (end - start))
        if hovered is None:
            return None
        point = points[hovered]
        x = int(x_of(point['total']))
        pygame.draw.line(surface, COLORS['white'], (x, plot.y), (x, plot.bottom))
        lines = [f"{labels['steps']}: {int(point['total']):,}"]
        for (key, label_key, color), y_of in zip(series, mappers):
            pygame.draw.circle(surface, color, (x, int(y_of(point[key]))), 3)
            lines.append(f"{labels[key]}: {point[key]:,.2f}" if key == 'avg_fruits' else f"{labels[key]}: {point[key]:,.1f}")
        rendered = [font.render(text, True, COLORS['white']) for text in lines]
        box = pygame.Rect(0, 0, max(r.get_width() for r in rendered) + 10, sum(r.get_height() for r in rendered) + 8)
        box.topleft = (x + 8, plot.y + 4)
        if box.right > rect.right - 2:
            box.right = x - 8
        box.clamp_ip(rect)
        pygame.draw.rect(surface, (18, 22, 38), box, border_radius=4)
        pygame.draw.rect(surface, (110, 120, 160), box, 1, border_radius=4)
        y = box.y + 4
        for r in rendered:
            surface.blit(r, (box.x + 5, y))
            y += r.get_height()
        return point


_RESET_ICONS = {}


def ui_reset_icon(color, size=14):
    """A small circular arrow ('put the default back'), drawn big and scaled down so it is smooth; cached."""
    key = (tuple(color[:3]), size)
    icon = _RESET_ICONS.get(key)
    if icon is None:
        big = 8 * size
        surf = pygame.Surface((big, big), pygame.SRCALPHA)
        c, r, start = big / 2.0, big * 0.30, 0.6
        pygame.draw.arc(surf, color, pygame.Rect(c - r, c - r, 2 * r, 2 * r), start, 5.5, max(2, int(big * 0.11)))
        px, py = c + r * math.cos(start), c - r * math.sin(start)
        tx, ty = math.sin(start), math.cos(start)                 # the way round the circle, into the gap
        nx, ny = -ty, tx
        length, width = big * 0.20, big * 0.16
        pygame.draw.polygon(surf, color, [(px + tx * length * 0.55, py + ty * length * 0.55),
                                          (px - tx * length * 0.45 + nx * width, py - ty * length * 0.45 + ny * width),
                                          (px - tx * length * 0.45 - nx * width, py - ty * length * 0.45 - ny * width)])
        icon = _RESET_ICONS[key] = pygame.transform.smoothscale(surf, (size, size))
    return icon


def format_decimal(value):
    """A number as the shortest text that gives exactly the same number back, never in scientific notation (10.8263,
    53712.4182, 0.0001)."""
    from decimal import Decimal
    text = repr(float(value))
    if 'e' in text or 'E' in text:
        text = format(Decimal(text), 'f')
    if '.' in text:
        text = text.rstrip('0').rstrip('.')
    return '0' if text in ('', '-0') else text


RL_REWARD_LIMIT, RL_REWARD_WARN = 1e9, 1000.0       # a reward weight is refused beyond the first, and flagged beyond the second


def parse_reward_text(text):
    """(value, problem) for a typed reward weight: any integer or decimal, with a comma or a dot, exactly as typed.
    problem is '' or the Studio label to show ('reward_invalid' for something that is not a number, 'reward_range' for
    a magnitude beyond RL_REWARD_LIMIT)."""
    cleaned = str(text).strip().replace(',', '.')
    if not re.fullmatch(r'[+-]?(\d+(\.\d*)?|\.\d+)', cleaned):
        return None, 'reward_invalid'
    try:
        value = float(cleaned)
    except ValueError:
        return None, 'reward_invalid'
    if not math.isfinite(value) or abs(value) > RL_REWARD_LIMIT:
        return None, 'reward_range'
    return value + 0.0, ''


class UIWidget:
    """Common base: rect, state (normal/hover/focused/pressed/disabled), mouse +
    semantic-action input, focus participation, drawing hook."""
    focusable = True
    interactive = True          # receives mouse hit-tests
    captures_text = False

    def __init__(self, rect=None, key=None, enabled=True, visible=True,
                 on_activate=None, tab_index=None):
        self.rect = pygame.Rect(rect) if rect is not None else pygame.Rect(0, 0, 0, 0)
        self.key = key
        self.enabled, self.visible = enabled, visible
        self.on_activate = on_activate
        self.tab_index = tab_index
        self.hover = self.pressed = self.focused = False
        self.ui = None
        self.scroll_parent = None       # owning UIScrollView (if any)
        self.content_rect = None        # rect in the scroll view's content space

    # -- state --------------------------------------------------------------
    @property
    def state(self):
        if not self.enabled:
            return 'disabled'
        if self.pressed:
            return 'pressed'
        if self.focused and (self.ui is None or self.ui.focus_visible):
            return 'focused'
        return 'hover' if self.hover else 'normal'

    @property
    def show_focus(self):
        return self.focused and self.enabled and (self.ui is None or self.ui.focus_visible)

    def lang(self):
        return self.ui.language if self.ui is not None else 'en'

    @staticmethod
    def val(v):
        return v() if callable(v) else v

    def is_focusable(self):
        return self.focusable and self.enabled and self.visible and self.rect.w > 0 and self.rect.h > 0

    def hit(self, pos):
        if not (self.visible and self.interactive and self.rect.collidepoint(pos)):
            return False
        sp = self.scroll_parent
        return sp is None or sp.viewport.collidepoint(pos)

    # -- behaviour hooks ------------------------------------------------------
    def activate(self):
        if self.enabled and self.on_activate:
            self.on_activate()

    def on_focus(self):
        pass

    def on_blur(self):
        pass

    def handle_action(self, action, event=None):
        """Semantic keyboard input while focused. Return True if consumed."""
        if action == 'CONFIRM':
            self.activate()
            return True
        return False

    def handle_text(self, event):
        return False

    def mouse_down(self, pos):
        pass

    def mouse_drag(self, pos):
        pass

    def mouse_up(self, pos, inside):
        if inside:
            self.activate()

    def draw(self, surface):
        pass

    def draw_overlay(self, surface):
        pass


class UILabel(UIWidget):
    focusable = False
    interactive = False

    def __init__(self, text, rect=None, style='regular', size=16, color=None,
                 align='left', wrap=False, line_gap=2, key=None, valign='top'):
        super().__init__(rect, key=key)
        self.text, self.style, self.size = text, style, size
        self.color = color if color is not None else COLORS['white']
        self.align, self.wrap, self.line_gap, self.valign = align, wrap, line_gap, valign

    def _lines(self, width):
        txt = self.val(self.text)
        if not self.wrap:
            return [txt]
        return ui_wrap_text(self.lang(), self.style, self.size, txt, width)

    def line_height(self):
        return get_font(self.lang(), self.style, self.size).get_height()

    def measure(self, width):
        """Height needed when laid out `width` px wide (wrapped labels grow, others don't)."""
        lines = self._lines(width)
        lh = self.line_height()
        return len(lines) * lh + (len(lines) - 1) * self.line_gap

    def text_width(self):
        return ui_text_size(self.lang(), self.style, self.size, self.val(self.text))[0]

    def draw(self, surface):
        if not self.visible or self.rect.w <= 0:
            return
        lang, r = self.lang(), self.rect
        old = surface.get_clip()
        surface.set_clip(old.clip(r))
        lines = self._lines(r.w)
        lh = self.line_height()
        total = len(lines) * lh + (len(lines) - 1) * self.line_gap
        y = r.y + ((r.h - total) // 2 if self.valign == 'center' else 0)
        for line in lines:
            if line:
                s = ui_text_surface(lang, self.style, self.size, line, self.color,
                                    None if self.wrap else r.w)
                x = r.x if self.align == 'left' else r.right - s.get_width() if self.align == 'right' \
                    else r.x + (r.w - s.get_width()) // 2
                surface.blit(s, (x, y))
            y += lh + self.line_gap
        surface.set_clip(old)


class UIPanel(UIWidget):
    focusable = False
    interactive = False

    def __init__(self, rect=None, bg=None, border=None, radius=None, key=None, border_width=1):
        super().__init__(rect, key=key)
        self.bg = bg if bg is not None else UI_STYLE['panel_bg']
        self.border, self.border_width = border, border_width
        self.radius = UI_STYLE['radius'] if radius is None else radius

    def draw(self, surface):
        if not self.visible:
            return
        pygame.draw.rect(surface, self.bg, self.rect, border_radius=self.radius)
        if self.border:
            pygame.draw.rect(surface, self.border, self.rect, width=self.border_width,
                             border_radius=self.radius)


class UIButton(UIWidget):
    """Push button. `text` may be a str or a callable (re-evaluated so language
    changes apply). Label is shrunk with render_fit() when the button is narrow,
    and the font shrinks with the button height so compressed layouts stay legible."""

    def __init__(self, text, rect=None, color=None, on_activate=None, key=None,
                 font_size=20, style='bold', radius=10, glow=True, text_color=None,
                 enabled=True, tab_index=None):
        super().__init__(rect, key=key, enabled=enabled, on_activate=on_activate, tab_index=tab_index)
        self.text = text
        self.color = color if color is not None else COLORS['button']
        self.font_size, self.style, self.radius, self.glow = font_size, style, radius, glow
        self.text_color = text_color if text_color is not None else COLORS['white']

    def _fit_size(self):
        return max(10, min(self.font_size, int(self.rect.h * 0.56)))

    def preferred_width(self, pad=28):
        return ui_text_size(self.lang(), self.style, self.font_size, self.val(self.text))[0] + pad

    def draw(self, surface):
        if not self.visible or self.rect.w <= 0 or self.rect.h <= 0:
            return
        r, st = self.rect, self.state
        high_contrast = bool(globals().get('_ACCESSIBILITY_HIGH_CONTRAST', False))
        if high_contrast:
            if st == 'disabled':
                bg, fg = (0, 0, 0), (160, 160, 160)
                border = (160, 160, 160)
            else:
                bg = ((64, 64, 64) if st == 'pressed' else
                      (32, 32, 32) if st in ('hover', 'focused') else (0, 0, 0))
                fg, border = (255, 255, 255), (255, 255, 0)
        elif st == 'disabled':
            bg, fg = UI_STYLE['disabled_bg'], UI_STYLE['disabled_fg']
        else:
            fg = self.text_color
            if st == 'pressed':
                bg = _ui_shade(self.color, -35)
            elif st in ('hover', 'focused'):
                pulse = int((self.ui.pulse if self.ui is not None else 0.5) * 50)
                bg = _ui_shade(self.color, pulse)
            else:
                bg = self.color
        pygame.draw.rect(surface, bg, r, border_radius=self.radius)
        if high_contrast:
            pygame.draw.rect(surface, border, r, width=2, border_radius=self.radius)
        if (self.glow and not high_contrast
                and not globals().get('_ACCESSIBILITY_REDUCED_MOTION', False)
                and st in ('hover', 'focused')):
            gk = (r.w, r.h, self.radius)
            g, cached = _lru_cache_get(_ui_glow_cache, gk)
            if not cached:
                g = pygame.Surface((r.w + 8, r.h + 8), pygame.SRCALPHA)
                pygame.draw.rect(g, (255, 255, 255, 255), g.get_rect(), border_radius=self.radius + 2)
                _lru_cache_put(_ui_glow_cache, gk, g, 64)
            g.set_alpha(int((self.ui.pulse if self.ui is not None else 0.5) * 150))
            surface.blit(g, (r.x - 4, r.y - 4))
        s = ui_text_surface(self.lang(), self.style, self._fit_size(), self.val(self.text), fg,
                            max(1, r.w - 10))
        surface.blit(s, s.get_rect(center=r.center))
        if self.show_focus:
            ui_draw_focus_ring(surface, r, self.radius)


class UICheckbox(UIWidget):
    def __init__(self, label, rect=None, checked=False, on_change=None, key=None,
                 size=16, enabled=True):
        super().__init__(rect, key=key, enabled=enabled)
        self.label, self.checked, self.on_change, self.size = label, checked, on_change, size

    def toggle(self):
        if not self.enabled:
            return
        self.checked = not self.checked
        if self.on_change:
            self.on_change(self.checked)

    def activate(self):
        self.toggle()

    def draw(self, surface):
        if not self.visible:
            return
        r, st = self.rect, self.state
        box = pygame.Rect(0, 0, min(22, r.h - 2), min(22, r.h - 2))
        box.midleft = (r.x + 2, r.centery)
        dis = st == 'disabled'
        pygame.draw.rect(surface, UI_STYLE['disabled_bg'] if dis else COLORS['button'], box, border_radius=4)
        pygame.draw.rect(surface, COLORS['white'] if not dis else UI_STYLE['disabled_fg'], box, width=2, border_radius=4)
        if self.checked:
            pts = [(box.x + 4, box.centery), (box.centerx - 1, box.bottom - 5), (box.right - 4, box.y + 5)]
            pygame.draw.lines(surface, COLORS.get('green', (60, 200, 90)) if not dis else UI_STYLE['disabled_fg'],
                              False, pts, 3)
        s = ui_text_surface(self.lang(), 'regular', self.size, self.val(self.label),
                            UI_STYLE['disabled_fg'] if dis else COLORS['white'],
                            max(1, r.w - box.w - 14))
        surface.blit(s, (box.right + 10, r.centery - s.get_height() // 2))
        if self.show_focus:
            ui_draw_focus_ring(surface, r.inflate(-2, 0), 6)


class UISlider(UIWidget):
    def __init__(self, rect=None, minimum=0, maximum=100, value=0, step=1,
                 on_change=None, key=None, fmt=None, enabled=True):
        super().__init__(rect, key=key, enabled=enabled)
        self.min, self.max, self.step = minimum, maximum, step
        self.value = value
        self.on_change, self.fmt = on_change, fmt
        self.dragging = False

    def _track(self):
        r = self.rect
        return pygame.Rect(r.x + 10, r.centery - 3, max(1, r.w - 20), 6)

    def set_value(self, v, notify=True):
        v = _ui_clamp(v, self.min, self.max)
        if self.step:
            v = self.min + round((v - self.min) / self.step) * self.step
            v = _ui_clamp(v, self.min, self.max)
        if v != self.value:
            self.value = v
            if notify and self.on_change:
                self.on_change(v)

    def _value_at(self, x):
        t = self._track()
        frac = _ui_clamp((x - t.x) / float(t.w), 0.0, 1.0)
        return self.min + frac * (self.max - self.min)

    def handle_action(self, action, event=None):
        big = (self.max - self.min) / 10.0
        if action == 'MOVE_LEFT':
            self.set_value(self.value - self.step)
        elif action == 'MOVE_RIGHT':
            self.set_value(self.value + self.step)
        elif action == 'PAGE_DOWN':
            self.set_value(self.value - big)
        elif action == 'PAGE_UP':
            self.set_value(self.value + big)
        elif action == 'HOME':
            self.set_value(self.min)
        elif action == 'END':
            self.set_value(self.max)
        else:
            return False
        return True

    def mouse_down(self, pos):
        self.dragging = True
        self.set_value(self._value_at(pos[0]))

    def mouse_drag(self, pos):
        if self.dragging:
            self.set_value(self._value_at(pos[0]))

    def mouse_up(self, pos, inside):
        self.dragging = False

    def draw(self, surface):
        if not self.visible:
            return
        t, dis = self._track(), self.state == 'disabled'
        pygame.draw.rect(surface, UI_STYLE['disabled_bg'] if dis else COLORS['dark_gray'], t, border_radius=3)
        span = float(self.max - self.min) or 1.0
        frac = (self.value - self.min) / span
        fill = pygame.Rect(t.x, t.y, int(t.w * frac), t.h)
        pygame.draw.rect(surface, UI_STYLE['disabled_fg'] if dis else COLORS['light_blue'], fill, border_radius=3)
        knob = pygame.Rect(0, 0, 16, 22)
        knob.center = (t.x + int(t.w * frac), t.centery)
        pygame.draw.rect(surface, COLORS['white'], knob, border_radius=5)
        if self.fmt:
            s = ui_text_surface(self.lang(), 'regular', 14, self.fmt(self.value), COLORS['white'])
            surface.blit(s, (self.rect.right - s.get_width(), self.rect.y - 1))
        if self.show_focus:
            ui_draw_focus_ring(surface, self.rect.inflate(-4, 0), 6)


class UIDropdown(UIWidget):
    """Single-choice dropdown. The open list is drawn as an overlay above other
    widgets and captures the mouse until closed; keyboard: Enter/Space opens,
    Up/Down/Home/End/PgUp/PgDn move, Enter picks, Esc closes."""

    def __init__(self, options, rect=None, index=0, on_change=None, key=None,
                 size=16, max_rows=6, enabled=True):
        super().__init__(rect, key=key, enabled=enabled)
        self.options = options          # list of (value, label-or-callable)
        self.index, self.on_change, self.size = index, on_change, size
        self.max_rows, self.open, self.hi, self.top = max_rows, False, index, 0

    @property
    def value(self):
        return self.options[self.index][0] if self.options else None

    def _row_h(self):
        return max(24, self.size + 10)

    def _list_rect(self):
        n = min(len(self.options), self.max_rows)
        h = n * self._row_h()
        r = self.rect
        bounds = self.ui.bounds if self.ui else pygame.Rect(0, 0, 10 ** 5, 10 ** 5)
        y = r.bottom + 2
        if y + h > bounds.bottom and r.y - 2 - h >= bounds.y:
            y = r.y - 2 - h
        return pygame.Rect(r.x, y, r.w, h)

    def _open(self):
        if not self.options:
            return
        self.open, self.hi = True, self.index
        self._scroll_to_hi()
        if self.ui:
            self.ui.capture = self

    def _close(self):
        self.open = False
        if self.ui and self.ui.capture is self:
            self.ui.capture = None

    def _scroll_to_hi(self):
        if self.hi < self.top:
            self.top = self.hi
        elif self.hi >= self.top + self.max_rows:
            self.top = self.hi - self.max_rows + 1
        self.top = _ui_clamp(self.top, 0, max(0, len(self.options) - self.max_rows))

    def _pick(self, i):
        changed = i != self.index
        self.index = _ui_clamp(i, 0, len(self.options) - 1)
        self._close()
        if changed and self.on_change:
            self.on_change(self.value)

    def activate(self):
        if self.open:
            self._close()
        else:
            self._open()

    def on_blur(self):
        self._close()

    def handle_action(self, action, event=None):
        if not self.open:
            return super().handle_action(action, event)
        n = len(self.options)
        if action == 'MOVE_UP':
            self.hi = max(0, self.hi - 1)
        elif action == 'MOVE_DOWN':
            self.hi = min(n - 1, self.hi + 1)
        elif action == 'PAGE_UP':
            self.hi = max(0, self.hi - self.max_rows)
        elif action == 'PAGE_DOWN':
            self.hi = min(n - 1, self.hi + self.max_rows)
        elif action == 'HOME':
            self.hi = 0
        elif action == 'END':
            self.hi = n - 1
        elif action == 'CONFIRM':
            self._pick(self.hi)
            return True
        elif action == 'BACK':
            self._close()
            return True
        else:
            return True       # swallow everything else while open
        self._scroll_to_hi()
        return True

    def capture_mouse(self, event, pos):
        """Called by the manager while open. Returns True if the event was consumed."""
        lr = self._list_rect()
        if event.type == pygame.MOUSEMOTION:
            if lr.collidepoint(pos):
                self.hi = self.top + (pos[1] - lr.y) // self._row_h()
                self.hi = _ui_clamp(self.hi, 0, len(self.options) - 1)
            return True
        if event.type == pygame.MOUSEWHEEL:
            self.top = _ui_clamp(self.top - event.y, 0, max(0, len(self.options) - self.max_rows))
            return True
        if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
            if lr.collidepoint(pos):
                self._pick(self.top + (pos[1] - lr.y) // self._row_h())
            elif not self.rect.collidepoint(pos):
                self._close()
            else:
                self._close()
            return True
        return event.type in (pygame.MOUSEBUTTONUP,)

    def mouse_up(self, pos, inside):
        pass                     # opening is handled on mouse_down (capture takes over)

    def mouse_down(self, pos):
        self.activate()

    def draw(self, surface):
        if not self.visible:
            return
        r, st = self.rect, self.state
        dis = st == 'disabled'
        bg = UI_STYLE['disabled_bg'] if dis else COLORS['button']
        if st in ('hover', 'focused') and not dis:
            bg = _ui_shade(bg, 18)
        pygame.draw.rect(surface, bg, r, border_radius=6)
        label = self.val(self.options[self.index][1]) if self.options else ''
        s = ui_text_surface(self.lang(), 'regular', self.size, label,
                            UI_STYLE['disabled_fg'] if dis else COLORS['white'], max(1, r.w - 34))
        surface.blit(s, (r.x + 10, r.centery - s.get_height() // 2))
        cx, cy = r.right - 16, r.centery
        pts = [(cx - 5, cy + 3), (cx + 5, cy + 3), (cx, cy - 3)] if self.open else \
              [(cx - 5, cy - 3), (cx + 5, cy - 3), (cx, cy + 3)]
        pygame.draw.polygon(surface, COLORS['white'], pts)
        if self.show_focus:
            ui_draw_focus_ring(surface, r, 6)

    def draw_overlay(self, surface):
        if not (self.open and self.visible):
            return
        lr, rh = self._list_rect(), self._row_h()
        pygame.draw.rect(surface, UI_STYLE['popup_bg'], lr, border_radius=6)
        for k in range(min(len(self.options), self.max_rows)):
            i = self.top + k
            if i >= len(self.options):
                break
            row = pygame.Rect(lr.x, lr.y + k * rh, lr.w, rh)
            if i == self.hi:
                pygame.draw.rect(surface, COLORS['light_blue'], row.inflate(-4, -2), border_radius=4)
            s = ui_text_surface(self.lang(), 'regular', self.size, self.val(self.options[i][1]),
                                COLORS['white'], max(1, lr.w - 20))
            surface.blit(s, (row.x + 10, row.centery - s.get_height() // 2))
        pygame.draw.rect(surface, COLORS['light_blue'], lr, width=1, border_radius=6)


class UITextInput(UIWidget):
    """Single-line text field with caret editing. Focused == editing: while
    focused it receives printable characters and Backspace first (so typing is
    never mistaken for a shortcut); arrows/Home/End/Delete move the caret via
    semantic actions; Enter submits (and advances focus); Esc leaves the field."""
    captures_text = True

    def __init__(self, rect=None, text='', placeholder='', max_len=None, on_change=None,
                 on_submit=None, key=None, size=20, align='left', icon=None,
                 advance_on_submit=True, enabled=True):
        super().__init__(rect, key=key, enabled=enabled)
        self.text, self.placeholder, self.max_len = text, placeholder, max_len
        self.on_change, self.on_submit = on_change, on_submit
        self.size, self.align, self.icon = size, align, icon
        self.advance_on_submit = advance_on_submit
        self.caret = len(text)
        self.flash_until = 0
        self.last_input = 0                # when the player last typed or moved the caret (keeps the caret solid)

    def flash(self, ms=900):
        self.flash_until = pygame.time.get_ticks() + ms

    def set_text(self, text, notify=False):
        self.text = text
        self.caret = min(self.caret, len(text))
        if notify and self.on_change:
            self.on_change(self.text)

    def _changed(self):
        self.last_input = pygame.time.get_ticks()
        if self.on_change:
            self.on_change(self.text)

    def on_focus(self):
        self.caret = len(self.text)
        self.last_input = pygame.time.get_ticks()

    def handle_text(self, event):
        if event.type != pygame.KEYDOWN:
            return False
        if event.key == pygame.K_BACKSPACE:
            if self.caret > 0:
                self.text = self.text[:self.caret - 1] + self.text[self.caret:]
                self.caret -= 1
                self._changed()
            return True
        ch = getattr(event, 'unicode', '')
        if ch and ch.isprintable() and not (event.mod & (pygame.KMOD_CTRL | pygame.KMOD_ALT)):
            if self.max_len is None or len(self.text) < self.max_len:
                self.text = self.text[:self.caret] + ch + self.text[self.caret:]
                self.caret += len(ch)
                self._changed()
            return True
        return False

    def handle_action(self, action, event=None):
        if action in ('MOVE_LEFT', 'MOVE_RIGHT', 'HOME', 'END', 'DELETE'):
            self.last_input = pygame.time.get_ticks()
        if action == 'MOVE_LEFT':
            self.caret = max(0, self.caret - 1)
        elif action == 'MOVE_RIGHT':
            self.caret = min(len(self.text), self.caret + 1)
        elif action == 'HOME':
            self.caret = 0
        elif action == 'END':
            self.caret = len(self.text)
        elif action == 'DELETE':
            if self.caret < len(self.text):
                self.text = self.text[:self.caret] + self.text[self.caret + 1:]
                self._changed()
        elif action == 'CONFIRM':
            if self.on_submit:
                self.on_submit(self.text)
            if self.advance_on_submit and self.ui:
                self.ui.focus_step(1)
        elif action == 'BACK':
            if self.ui:
                self.ui.blur()
        else:
            return False
        return True

    def mouse_down(self, pos):
        # place caret at the click position
        self.last_input = pygame.time.get_ticks()
        inner = self.rect.inflate(-16, 0)
        pad = self._icon_pad()
        x = pos[0] - (inner.x + pad) + getattr(self, '_sx', 0)
        best, acc = len(self.text), 0
        for i in range(len(self.text) + 1):
            w = ui_text_size(self.lang(), 'regular', self.size, self.text[:i])[0]
            if w >= x:
                best = i if i == 0 or (w - x) < (x - acc) else i - 1
                break
            acc = w
        self.caret = best

    def mouse_up(self, pos, inside):
        pass

    def _icon_pad(self):
        return 28 if self.icon == 'search' else 0

    def draw(self, surface):
        if not self.visible:
            return
        r, lang = self.rect, self.lang()
        active = self.focused
        flashing = pygame.time.get_ticks() < self.flash_until
        bg = COLORS['light_gray'] if (active or flashing) else COLORS['gray']
        if UI_STYLE['input_bg'] is not None:
            bg = UI_STYLE['input_bg']
        pygame.draw.rect(surface, bg, r, border_radius=5)
        if active:
            pygame.draw.rect(surface, COLORS['blue'], r, width=2, border_radius=5)       # the field being typed into stands out
        if flashing:
            pygame.draw.rect(surface, COLORS.get('red', (220, 60, 60)), r, width=2, border_radius=5)
        inner = r.inflate(-16, 0)
        pad = self._icon_pad()
        if self.icon == 'search':
            ic = 18
            icon_rect = pygame.Rect(r.x + 7, r.centery - ic // 2 - 1, ic - 4, ic - 4)
            pygame.draw.circle(surface, COLORS['dark_gray'], icon_rect.center, icon_rect.w // 2, 2)
            pygame.draw.line(surface, COLORS['dark_gray'], (icon_rect.right - 2, icon_rect.bottom - 2),
                             (icon_rect.right + 4, icon_rect.bottom + 4), 2)
        area = pygame.Rect(inner.x + pad, r.y, max(1, inner.w - pad), r.h)
        old = surface.get_clip()
        surface.set_clip(old.clip(area))
        size = max(10, min(self.size, r.h - 6))
        if not self.text and not active:
            s = ui_text_surface(lang, 'regular', size, self.val(self.placeholder), COLORS['dark_gray'], area.w)
            x = area.x if self.align == 'left' else area.centerx - s.get_width() // 2
            surface.blit(s, (x, r.centery - s.get_height() // 2))
        else:
            font = get_font(lang, 'regular', size)
            s = ui_text_surface(lang, 'regular', size, self.text, COLORS['black']) if self.text else None
            tw = s.get_width() if s else 0
            caret_x = font.size(self.text[:self.caret])[0]
            if tw <= area.w:
                self._sx = 0
                x0 = area.x if self.align == 'left' else area.centerx - tw // 2
            else:
                sx = getattr(self, '_sx', 0)
                if caret_x - sx > area.w - 4:
                    sx = caret_x - area.w + 4
                elif caret_x - sx < 0:
                    sx = caret_x
                self._sx = sx = _ui_clamp(sx, 0, tw - area.w + 4)
                x0 = area.x - sx
            if s:
                surface.blit(s, (x0, r.centery - s.get_height() // 2))
            if active:
                draw_text_caret(surface, x0 + caret_x, r.centery - size // 2, r.centery + size // 2, COLORS['black'],
                                pygame.time.get_ticks(), self.last_input)
        surface.set_clip(old)
        if self.show_focus:
            ui_draw_focus_ring(surface, r, 5)


class UITabBar(UIWidget):
    """Tab strip: one focus stop, Left/Right (or Home/End) change tab. Tabs are laid
    out with UIHorizontalFlow(wrap=True) so long labels wrap onto extra rows instead
    of being squeezed into unreadable widths; call height_for(width) to size it."""

    def __init__(self, tabs, rect=None, selected=0, on_change=None, key=None, size=14,
                 min_tab_w=70, gap=6, row_h=None):
        super().__init__(rect, key=key)
        self.tabs = tabs                # list of (key, label-or-callable)
        self.selected, self.on_change, self.size = selected, on_change, size
        self.min_tab_w, self.gap = min_tab_w, gap
        self.row_h = row_h
        self._rects = []

    def _row_height(self):
        return self.row_h or max(30, get_font(self.lang(), 'bold', self.size).get_height() + 14)

    def _flow(self, width):
        f = UIHorizontalFlow(pygame.Rect(0, 0, width, 0), spacing=self.gap, row_spacing=self.gap, wrap=True)
        rh = self._row_height()
        for k, label in self.tabs:
            w = ui_text_size(self.lang(), 'bold', self.size, self.val(label))[0] + 24
            f.add(k, w, min_w=min(self.min_tab_w, w), h=rh, flex=1)
        return f.solve()

    def height_for(self, width):
        return self._flow(width).height

    def selected_key(self):
        return self.tabs[self.selected][0] if self.tabs else None

    def select(self, i, notify=True):
        i = _ui_clamp(i, 0, len(self.tabs) - 1)
        if i != self.selected:
            self.selected = i
            if notify and self.on_change:
                self.on_change(self.tabs[i][0])

    def handle_action(self, action, event=None):
        if action == 'MOVE_LEFT' and self.selected > 0:
            self.select(self.selected - 1)
        elif action == 'MOVE_RIGHT' and self.selected < len(self.tabs) - 1:
            self.select(self.selected + 1)
        elif action == 'HOME':
            self.select(0)
        elif action == 'END':
            self.select(len(self.tabs) - 1)
        else:
            return False
        return True

    def _tab_rects(self):
        res = self._flow(self.rect.w)
        return [(k, res.rects[k].move(self.rect.x, self.rect.y)) for k, _ in self.tabs if k in res.rects]

    def mouse_down(self, pos):
        for i, (k, rc) in enumerate(self._tab_rects()):
            if rc.collidepoint(pos):
                self.select(i)
                return

    def mouse_up(self, pos, inside):
        pass

    def draw(self, surface):
        if not self.visible:
            return
        lang = self.lang()
        for i, (k, rc) in enumerate(self._tab_rects()):
            active = i == self.selected
            pygame.draw.rect(surface, (55, 110, 190) if active else (35, 45, 70), rc, border_radius=6)
            pygame.draw.rect(surface, (90, 130, 200), rc, width=1, border_radius=6)
            s = ui_text_surface(lang, 'bold', self.size, self.val(self.tabs[i][1]), COLORS['white'], rc.w - 6)
            surface.blit(s, s.get_rect(center=rc.center))
            if active and self.show_focus:
                ui_draw_focus_ring(surface, rc, 6)

class UIScrollView(UIWidget):
    """Clipped viewport over taller content. Owns a ScrollBar (the existing one)
    and children positioned in *content space* (`content_rect`); sync() maps them
    to screen coordinates. Use relayout(build) to (re)build content: the layout
    runs at full width first and is redone with the scrollbar gutter reserved
    only if the content turns out to be taller than the viewport."""
    focusable = False
    interactive = False

    def __init__(self, rect=None, key=None, bg=None, border=None, radius=None, padding=0):
        super().__init__(rect, key=key)
        self.bg, self.border = bg, border
        self.radius = UI_STYLE['radius'] if radius is None else radius
        self.padding = _ui_insets(padding)
        self.children = []
        self.scrollbar = ScrollBar(0, 0, 10, 10, 0)
        self.viewport = pygame.Rect(0, 0, 0, 0)
        self.set_rect(self.rect)

    @property
    def gutter(self):
        return self.scrollbar.bar_width + 4

    @property
    def needs_scroll(self):
        return self.scrollbar.needs_scroll

    def set_rect(self, rect):
        self.rect = pygame.Rect(rect)
        pl, pt, pr, pb = self.padding
        r = self.rect
        self.viewport = pygame.Rect(r.x + pl, r.y + pt, max(0, r.w - pl - pr), max(0, r.h - pt - pb))
        v = self.viewport
        self.scrollbar.set_geometry(v.x, v.y, v.w, v.h)
        self.scrollbar.wheel_rect = self.rect
        self.sync()

    def clear_children(self):
        self.children = []

    def add(self, widget, content_rect):
        widget.content_rect = pygame.Rect(content_rect)
        widget.scroll_parent = self
        widget.ui = self.ui
        self.children.append(widget)
        return widget

    def set_content_height(self, h):
        self.scrollbar.set_content_height(h)
        self.sync()

    def relayout(self, build):
        """build(width) must add children (content-space rects) and return content height."""
        for attempt in (0, 1):
            self.clear_children()
            w = self.viewport.w - (self.gutter if attempt else 0)
            ch = build(max(1, w))
            self.scrollbar.set_content_height(ch)
            if ch <= self.viewport.h:
                break
        if self.ui is not None:
            self.ui._adopt(self)
        self.sync()

    def sync(self):
        off = self.scrollbar.get_content_offset()
        v = self.viewport
        for c in self.children:
            if c.content_rect is not None:
                c.rect = c.content_rect.move(v.x, v.y - off)

    def update(self, dt=None):
        self.scrollbar.update(dt)
        self.sync()

    def ensure_child_visible(self, widget):
        cr = widget.content_rect
        if cr is not None:
            self.scrollbar.ensure_visible(cr.top, cr.bottom)

    def draw_background(self, surface):
        if self.bg is not None:
            pygame.draw.rect(surface, self.bg, self.rect, border_radius=self.radius)
        if self.border is not None:
            pygame.draw.rect(surface, self.border, self.rect, width=1, border_radius=self.radius)

    def draw(self, surface):
        if not self.visible:
            return
        self.sync()
        self.draw_background(surface)
        old = surface.get_clip()
        surface.set_clip(old.clip(self.viewport))
        for c in self.children:
            if c.visible and c.rect.colliderect(self.viewport):
                c.draw(surface)
        surface.set_clip(old)
        self.scrollbar.draw(surface)


class UIListView(UIScrollView):
    """Virtualised list: only visible rows are drawn, so 10 or 10,000 rows cost the
    same. One focus stop for the whole list; Up/Down/PgUp/PgDn/Home/End move the
    selection, Enter activates, Delete requests deletion. At the first/last row the
    key is not consumed so focus can leave the list."""
    focusable = True
    interactive = True

    def __init__(self, rect=None, row_h=40, draw_row=None, key=None, bg=None, border=None,
                 radius=None, padding=0, on_select=None, on_activate_row=None,
                 on_delete=None, on_row_click=None):
        self.row_h, self.draw_row = row_h, draw_row
        self.on_select, self.on_activate_row = on_select, on_activate_row
        self.on_delete, self.on_row_click = on_delete, on_row_click
        self.count, self.selected = 0, -1
        self._down_row = -1
        super().__init__(rect, key=key, bg=bg, border=border, radius=radius, padding=padding)

    def hit(self, pos):
        return (self.visible and self.viewport.collidepoint(pos) and
                not (self.needs_scroll and self.scrollbar.bar_rect.collidepoint(pos)))

    @property
    def row_width(self):
        return self.viewport.w - (self.gutter if self.needs_scroll else 0)

    def set_count(self, n, keep_scroll=True):
        self.count = max(0, n)
        self.scrollbar.set_content_height(self.count * self.row_h)
        if self.selected >= self.count:
            self.selected = self.count - 1
        if not keep_scroll:
            self.scrollbar.home(immediate=True)

    def set_rect(self, rect):
        super().set_rect(rect)
        self.scrollbar.set_content_height(self.count * self.row_h)

    def row_rect(self, i):
        off = self.scrollbar.get_content_offset()
        return pygame.Rect(self.viewport.x, self.viewport.y + i * self.row_h - off,
                           self.row_width, self.row_h)

    def row_at(self, pos):
        if not self.viewport.collidepoint(pos):
            return -1
        off = self.scrollbar.get_content_offset()
        i = (pos[1] - self.viewport.y + off) // self.row_h
        return i if 0 <= i < self.count else -1

    def select(self, i, notify=True, scroll=True):
        if self.count == 0:
            self.selected = -1
            return
        i = _ui_clamp(i, 0, self.count - 1)
        changed = i != self.selected
        self.selected = i
        if scroll:
            self.scrollbar.ensure_visible(i * self.row_h, (i + 1) * self.row_h, margin=0)
        if changed and notify and self.on_select:
            self.on_select(i)

    def on_focus(self):
        if self.selected < 0 and self.count:
            self.select(0)

    def handle_action(self, action, event=None):
        n = self.count
        page = max(1, self.viewport.h // self.row_h - 1)
        if action == 'MOVE_UP':
            if n and self.selected > 0:
                self.select(self.selected - 1)
                return True
            return False
        if action == 'MOVE_DOWN':
            if n and self.selected < n - 1:
                self.select(self.selected + 1)
                return True
            return False
        if action == 'PAGE_UP':
            self.select(max(0, self.selected - page)) if n else None
            return True
        if action == 'PAGE_DOWN':
            self.select(min(n - 1, max(0, self.selected) + page)) if n else None
            return True
        if action == 'HOME':
            self.select(0) if n else None
            return True
        if action == 'END':
            self.select(n - 1) if n else None
            return True
        if action == 'CONFIRM':
            if 0 <= self.selected < n and self.on_activate_row:
                self.on_activate_row(self.selected)
            return True
        if action == 'DELETE':
            if 0 <= self.selected < n and self.on_delete:
                self.on_delete(self.selected)
                return True
            return False
        return False

    def mouse_down(self, pos):
        self._down_row = self.row_at(pos)
        if self._down_row >= 0:
            self.select(self._down_row, scroll=False)

    def mouse_up(self, pos, inside):
        row = self.row_at(pos)
        if inside and row >= 0 and row == self._down_row and self.on_row_click:
            rr = self.row_rect(row)
            self.on_row_click(row, (pos[0] - rr.x, pos[1] - rr.y))
        self._down_row = -1

    def draw(self, surface):
        if not self.visible:
            return
        self.draw_background(surface)
        old = surface.get_clip()
        surface.set_clip(old.clip(self.viewport))
        off = self.scrollbar.get_content_offset()
        first = max(0, off // self.row_h)
        last = min(self.count, (off + self.viewport.h) // self.row_h + 2)
        if self.draw_row:
            for i in range(first, last):
                self.draw_row(surface, self.row_rect(i), i, i == self.selected,
                              self.focused and i == self.selected and self.show_focus)
        if self.show_focus and 0 <= self.selected < self.count:
            rr = self.row_rect(self.selected).clip(self.viewport)
            ui_draw_focus_ring(surface, rr.inflate(-6, -6), 6)
        surface.set_clip(old)
        self.scrollbar.draw(surface)


# ── Layers: dialogs and popups that trap focus ────────────────────────────
_ui_dim_cache = {}


class UILayer:
    """A modal layer drawn above the base UI. While it is on top of the
    UIManager's layer stack, only ITS widgets can receive focus or mouse input,
    which is what keeps hidden/background widgets from stealing focus."""

    def __init__(self, ui, dim=True, dismiss_on_outside=False, on_dismiss=None):
        self.ui, self.dim = ui, dim
        self.dismiss_on_outside, self.on_dismiss = dismiss_on_outside, on_dismiss
        self.rect = pygame.Rect(0, 0, 0, 0)
        self._prev_focus_key = None

    def roots(self):
        return []

    def layout(self, bounds):
        pass

    def draw(self, surface):
        pass

    def default_widget(self):
        return None

    def on_back(self):
        self.dismiss()

    def dismiss(self):
        self.ui.pop_layer(self)
        if self.on_dismiss:
            self.on_dismiss()

    def draw_dim(self, surface):
        if not self.dim:
            return
        size = surface.get_size()
        d, cached = _lru_cache_get(_ui_dim_cache, size)
        if not cached:
            d = pygame.Surface(size, pygame.SRCALPHA)
            d.fill(UI_STYLE['dim_overlay'])
            _lru_cache_put(_ui_dim_cache, size, d, 4)
        surface.blit(d, (0, 0))


class UIPopupLayer(UILayer):
    """Titled box with a scrollable body and a row of footer buttons. Sizes itself
    from its content and the window (body scrolls when the window is short), can be
    anchored to another widget, and wraps footer buttons onto extra rows if narrow.
    Used for confirmation dialogs (ui_dialog) and the High Scores filter popup."""

    def __init__(self, ui, title=None, build_body=None, footer=(), on_result=None,
                 anchor=None, width=420, cancel_key=None, default_key=None, dim=True,
                 dismiss_on_outside=False, on_dismiss=None, border=None):
        super().__init__(ui, dim=dim, dismiss_on_outside=dismiss_on_outside, on_dismiss=on_dismiss)
        self.title, self.build_body = title, build_body
        self.on_result, self.anchor, self.width_pref = on_result, anchor, width
        self.cancel_key, self.default_key = cancel_key, default_key
        self.border = border if border is not None else COLORS['light_blue']
        self.body = UIScrollView()
        self.body.ui = ui
        self.buttons = []
        for key, text, color in footer:
            b = UIButton(text, color=color, key=key, font_size=16, radius=6,
                         on_activate=(lambda k=key: self.finish(k)))
            b.ui = ui
            self.buttons.append(b)
        self._title_rect = pygame.Rect(0, 0, 0, 0)

    def roots(self):
        return [self.body] + self.buttons

    def default_widget(self):
        for b in self.buttons:
            if b.key == self.default_key:
                return b
        return self.buttons[0] if self.buttons else None

    def finish(self, key):
        self.ui.pop_layer(self)
        if self.on_result:
            self.on_result(key)
        if self.on_dismiss and key == self.cancel_key:
            self.on_dismiss()

    def on_back(self):
        if self.cancel_key is not None:
            self.finish(self.cancel_key)
        else:
            self.dismiss()

    def layout(self, bounds):
        lang = self.ui.language
        margin, pad, gap = 12, 14, 10
        W = max(160, min(self.width_pref, bounds.w - 2 * margin))
        inner_w = W - 2 * pad
        title_h = (get_font(lang, 'bold', 20).get_height() + 4) if self.title else 0
        # footer buttons: wrap onto extra rows when they do not fit
        fl = UIHorizontalFlow(pygame.Rect(0, 0, inner_w, 0), spacing=8, row_spacing=6, wrap=True)
        for b in self.buttons:
            b.ui = self.ui
            fl.add(b.key, max(80, b.preferred_width()), min_w=60, h=34, flex=1)
        fres = fl.solve()
        footer_h = fres.height
        max_body = max(40, bounds.h - 2 * margin - 2 * pad - title_h - footer_h - 2 * gap)
        body = self.body
        body.ui = self.ui
        build = self.build_body or (lambda w: 0)
        body.set_rect(pygame.Rect(0, 0, inner_w, 10 ** 4))
        body.relayout(build)
        content_h = body.scrollbar.content_height
        body_h = min(content_h, max_body)
        H = pad + title_h + (gap if title_h else 0) + body_h + gap + footer_h + pad
        if self.anchor is not None:
            x = _ui_clamp(self.anchor.centerx - W // 2, bounds.x + margin, bounds.right - margin - W)
            y = self.anchor.bottom + 8
            if y + H > bounds.bottom - margin:
                above = self.anchor.top - 8 - H
                y = above if above >= bounds.y + margin else max(bounds.y + margin, bounds.bottom - margin - H)
        else:
            x, y = bounds.centerx - W // 2, bounds.centery - H // 2
        self.rect = pygame.Rect(x, y, W, H)
        cy = y + pad
        self._title_rect = pygame.Rect(x + pad, cy, inner_w, title_h)
        cy += title_h + (gap if title_h else 0)
        body.set_rect(pygame.Rect(x + pad, cy, inner_w, body_h))
        body.relayout(build)
        cy += body_h + gap
        for b in self.buttons:
            rc = fres.rects[b.key]
            b.rect = rc.move(x + pad, cy)
        self.ui._adopt(body)

    def draw(self, surface):
        self.draw_dim(surface)
        pygame.draw.rect(surface, UI_STYLE['popup_bg'], self.rect, border_radius=10)
        pygame.draw.rect(surface, self.border, self.rect, width=2, border_radius=10)
        if self.title:
            s = ui_text_surface(self.ui.language, 'bold', 20, self.title, COLORS['white'],
                                self._title_rect.w)
            surface.blit(s, (self._title_rect.x, self._title_rect.y))
            ly = self._title_rect.bottom + 2
            pygame.draw.line(surface, self.border, (self.rect.x + 10, ly), (self.rect.right - 10, ly), 1)
        self.body.draw(surface)
        for b in self.buttons:
            b.draw(surface)


def ui_dialog(ui, title, message, buttons, on_result, cancel_key=None, default_key=None):
    """Confirmation/message dialog. `buttons`: [(key, text_or_callable, colour)]."""
    def build(width):
        lab = UILabel(message, size=17, wrap=True, align='center', color=COLORS['white'])
        lab.ui = ui
        h = lab.measure(width)
        ui_lab = lab
        body_add(ui_lab, pygame.Rect(0, 0, width, h))
        return h

    dlg = UIPopupLayer(ui, title=title, build_body=None, footer=buttons, on_result=on_result,
                       width=440, cancel_key=cancel_key, default_key=default_key,
                       border=COLORS.get('red', (220, 60, 60)))

    def body_add(widget, rect):
        dlg.body.add(widget, rect)

    dlg.build_body = build
    ui.push_layer(dlg)
    return dlg


# ── Manager: focus, event routing, drawing ────────────────────────────────
class UIManager:
    """Per-screen UI root. A screen creates one, adds widgets in *logical focus
    order*, and forwards pygame events:

        action = ui.handle_event(event)      # None if consumed by the UI
        ui.update(dt);  ui.draw(surface)

    handle_event returns an *unconsumed semantic action name* (e.g. 'BACK',
    'TOGGLE_FULLSCREEN', 'EXIT_GAME') so the screen decides what those mean.
    Focus, Tab/Shift+Tab, arrow (spatial) navigation, scrolling keys, modal
    focus trapping and mouse routing are all implemented here once."""

    def __init__(self, get_bounds, language='en'):
        self.get_bounds = get_bounds
        self.language = language
        self.pulse = 0.5
        self.mouse_pos = None          # tests / managers may pin the pointer
        self.widgets = []
        self.layers = []
        self.capture = None            # widget that temporarily owns the mouse (open dropdown)
        self.focused = None
        self.focus_visible = True
        self.mouse_owner = None
        self._repeater = KeyRepeater()          # held Backspace, Delete, arrows and letters repeat inside a focused text field
        self.now = pygame.time.get_ticks

    # -- basics ----------------------------------------------------------------
    @property
    def bounds(self):
        return pygame.Rect(self.get_bounds())

    def _mouse(self):
        return self.mouse_pos if self.mouse_pos is not None else pygame.mouse.get_pos()

    def _adopt(self, w):
        w.ui = self
        for c in getattr(w, 'children', ()):
            self._adopt(c)

    def add(self, widget):
        self._adopt(widget)
        self.widgets.append(widget)
        return widget

    def clear(self, keep_focus=True):
        """Remove every base widget (call before rebuilding a layout). The focused
        widget's key is remembered so restore_focus() can put focus back."""
        self._focus_key = self.focused.key if (keep_focus and self.focused) else None
        if self.focused:
            self.focused.focused = False
        self.focused = None
        self.widgets = []
        self.capture = None
        self.mouse_owner = None

    def restore_focus(self, default_key=None):
        k = getattr(self, '_focus_key', None)
        if not (k is not None and self.focus_key(k)):
            if default_key is not None:
                self.focus_key(default_key)

    def find(self, key):
        for w in self._all_widgets():
            if w.key == key:
                return w
        return None

    # -- traversal ---------------------------------------------------------------
    def _roots(self):
        return self.layers[-1].roots() if self.layers else self.widgets

    @staticmethod
    def _flatten(roots):
        out = []
        for w in roots:
            out.append(w)
            ch = getattr(w, 'children', None)
            if ch:
                out.extend(UIManager._flatten(ch))
        return out

    def _all_widgets(self):
        out = self._flatten(self.widgets)
        for L in self.layers:
            out.extend(self._flatten(L.roots()))
        return out

    def active_widgets(self):
        return self._flatten(self._roots())

    def scroll_views(self):
        return [w for w in self.active_widgets() if isinstance(w, UIScrollView) and w.visible]

    # -- layers ------------------------------------------------------------------
    def push_layer(self, layer):
        layer._prev_focus_key = self.focused.key if self.focused else None
        self.layers.append(layer)
        layer.layout(self.bounds)
        self._adopt_layer(layer)
        self.blur()
        d = layer.default_widget()
        if d is not None:
            self.set_focus(d)
        return layer

    def _adopt_layer(self, layer):
        for r in layer.roots():
            self._adopt(r)

    def pop_layer(self, layer):
        if layer in self.layers:
            self.layers.remove(layer)
        self.blur()
        if not self.layers and layer._prev_focus_key is not None:
            self.focus_key(layer._prev_focus_key)

    def on_resize(self):
        for L in self.layers:
            L.layout(self.bounds)
            self._adopt_layer(L)

    # -- focus -------------------------------------------------------------------
    def _candidates(self):
        b = self.bounds
        out = []
        for w in self.active_widgets():
            if not w.is_focusable():
                continue
            # A widget inside a scroll view is reachable (focus scrolls it into view);
            # a plain widget lying outside the window is not focusable.
            if w.scroll_parent is None and not w.rect.colliderect(b):
                continue
            if w.scroll_parent is not None and not w.scroll_parent.visible:
                continue
            out.append(w)
        if any(w.tab_index is not None for w in out):
            out.sort(key=lambda w: (w.tab_index is None, w.tab_index if w.tab_index is not None else 0))
        return out

    def set_focus(self, widget, visible=True):
        if widget is self.focused:
            if visible:
                self.focus_visible = True
            return
        old = self.focused
        if old is not None:
            old.focused = False
            old.pressed = False
            old.on_blur()
        self.focused = widget
        if visible:
            self.focus_visible = True
        if widget is not None:
            widget.focused = True
            widget.on_focus()
            sp = widget.scroll_parent
            if sp is not None:
                sp.ensure_child_visible(widget)
                sp.sync()

    def blur(self):
        self.set_focus(None, visible=False)

    def focus_key(self, key):
        for w in self._candidates():
            if w.key == key:
                self.set_focus(w)
                return True
        return False

    def focus_step(self, delta):
        cands = self._candidates()
        if not cands:
            return False
        if self.focused in cands:
            i = (cands.index(self.focused) + delta) % len(cands)
        else:
            i = 0 if delta > 0 else len(cands) - 1
        self.set_focus(cands[i])
        return True

    def validate_focus(self):
        """Drop focus from a widget that became disabled/hidden/removed/off-screen."""
        f = self.focused
        if f is not None and f not in self._candidates():
            self.blur()

    def _spatial(self, direction, wrap=True):
        f = self.focused
        cands = [w for w in self._candidates() if w is not f]
        if not cands:
            return None
        if f is None or f not in self.active_widgets():
            return cands[0] if direction in ('MOVE_DOWN', 'MOVE_RIGHT') else cands[-1]
        fr = f.rect
        best, best_s = None, None
        far, far_s = None, None
        for w in cands:
            r = w.rect
            if direction in ('MOVE_UP', 'MOVE_DOWN'):
                sign = 1 if direction == 'MOVE_DOWN' else -1
                d = (r.centery - fr.centery) * sign
                gap = (r.top - fr.bottom) if sign > 0 else (fr.top - r.bottom)
                perp = max(0, max(r.left - fr.right, fr.left - r.right))
                off = abs(r.centerx - fr.centerx)
            else:
                sign = 1 if direction == 'MOVE_RIGHT' else -1
                d = (r.centerx - fr.centerx) * sign
                gap = (r.left - fr.right) if sign > 0 else (fr.left - r.right)
                perp = max(0, max(r.top - fr.bottom, fr.top - r.bottom))
                off = abs(r.centery - fr.centery)
            if d > 0:
                s = max(0, gap) + perp * 3 + off * 0.01 + d * 0.001
                if best_s is None or s < best_s:
                    best, best_s = w, s
            else:
                s = perp * 3 + off * 0.01 + d          # d <= 0: farther away => smaller score
                if far_s is None or s < far_s:
                    far, far_s = w, s
        if best is not None:
            return best
        return far if wrap else None

    def _spatial_nowrap(self, direction):
        return self._spatial(direction, wrap=False)

    def active_scroll_view(self):
        f = self.focused
        if f is not None:
            if isinstance(f, UIScrollView):
                return f
            if f.scroll_parent is not None:
                return f.scroll_parent
        views = [v for v in self.scroll_views() if v.needs_scroll]
        if not views:
            return None
        mp = self._mouse()
        for v in views:
            if v.rect.collidepoint(mp):
                return v
        return views[0]

    # -- events --------------------------------------------------------------------
    def handle_event(self, event):
        t = event.type
        if t in (pygame.MOUSEMOTION, pygame.MOUSEBUTTONDOWN, pygame.MOUSEBUTTONUP, pygame.MOUSEWHEEL):
            return self._handle_mouse(event)
        if t == pygame.KEYDOWN:
            result = self._handle_key(event)
            f = self.focused
            if result is None and f is not None and f.captures_text and f.enabled:
                self._repeater.press(event, self.now())
            return result
        if t == pygame.KEYUP:
            self._repeater.release(event.key)
        elif t == getattr(pygame, 'WINDOWFOCUSLOST', None):
            self._repeater.release()
        return None

    def _topmost(self, pos):
        for w in reversed(self.active_widgets()):
            if w.hit(pos):
                return w
        return None

    def _handle_mouse(self, event):
        t = event.type
        pos = getattr(event, 'pos', None) or self._mouse()
        if t == pygame.MOUSEBUTTONUP and event.button == 1:
            for v in self.scroll_views():
                v.scrollbar.handle_event(event, pos)
            o = self.mouse_owner
            if o is not None:
                o.pressed = False
                self.mouse_owner = None
                o.mouse_up(pos, o.hit(pos))
            return None
        if self.capture is not None:
            if self.capture.capture_mouse(event, pos):
                return None
        if t == pygame.MOUSEMOTION:
            for v in self.scroll_views():
                v.scrollbar.handle_event(event, pos)
            if self.mouse_owner is not None:
                self.mouse_owner.mouse_drag(pos)
            top = self._topmost(pos)
            for w in self.active_widgets():
                w.hover = (w is top) and w.enabled
            return None
        if t == pygame.MOUSEWHEEL:
            for v in reversed(self.scroll_views()):
                if v.needs_scroll and v.rect.collidepoint(pos):
                    v.scrollbar.handle_event(event, pos)
                    return None
            return None
        if t == pygame.MOUSEBUTTONDOWN and event.button == 1:
            self.focus_visible = False
            for v in self.scroll_views():
                if v.needs_scroll and v.scrollbar.bar_rect.collidepoint(pos):
                    v.scrollbar.handle_event(event, pos)
                    return None
            if self.layers:
                top_layer = self.layers[-1]
                if not top_layer.rect.collidepoint(pos):
                    if top_layer.dismiss_on_outside:
                        top_layer.on_back()
                    return None          # modal: swallow clicks outside
            w = self._topmost(pos)
            if w is not None and w.enabled:
                if w.focusable:
                    self.set_focus(w, visible=False)
                else:
                    self.blur()
                w.pressed = True
                self.mouse_owner = w
                w.mouse_down(pos)
            elif self.focused is not None and self.focused.captures_text:
                self.blur()               # clicking elsewhere leaves a text field
            return None
        return None

    def _handle_key(self, event):
        self.focus_visible = True
        f = self.focused
        if f is not None and f.captures_text and f.handle_text(event):
            return None
        first_unhandled = None
        for action in UI_INPUT.actions_for(event):
            if self._dispatch(action, event):
                return None
            if first_unhandled is None:
                first_unhandled = action
        return first_unhandled

    def _dispatch(self, action, event):
        f = self.focused
        if action == 'FOCUS_NEXT':
            return self.focus_step(1) or True
        if action == 'FOCUS_PREV':
            return self.focus_step(-1) or True
        if f is not None and f.handle_action(action, event):
            return True
        if action == 'BACK' and self.layers:
            self.layers[-1].on_back()
            return True
        if action in ('MOVE_UP', 'MOVE_DOWN', 'MOVE_LEFT', 'MOVE_RIGHT'):
            w = self._spatial_nowrap(action)
            if w is not None:
                self.set_focus(w)
                return True
            if action in ('MOVE_UP', 'MOVE_DOWN'):
                sv = self.active_scroll_view()
                if sv is not None and sv.scrollbar.handle_key(action):
                    return True
            w = self._spatial(action, wrap=True)
            if w is not None and w is not f:
                self.set_focus(w)
                return True
            return f is not None      # arrows never leak to the screen while something has focus
        if action in ('PAGE_UP', 'PAGE_DOWN', 'HOME', 'END'):
            sv = self.active_scroll_view()
            if sv is not None and sv.scrollbar.handle_key(action):
                return True
            return False
        return False

    # -- per-frame ---------------------------------------------------------------
    def update(self, dt=None):
        if globals().get('_ACCESSIBILITY_REDUCED_MOTION', False):
            self.pulse = 0.5
        else:
            ph = (pygame.time.get_ticks() / 1100.0) % 2.0
            self.pulse = ph if ph <= 1.0 else 2.0 - ph
        for v in self.scroll_views():
            v.update(dt)
        if self.mouse_owner is None and self.capture is None:
            pos = self._mouse()
            top = self._topmost(pos)
            for w in self.active_widgets():
                w.hover = (w is top) and w.enabled
        f = self.focused
        if f is None or not f.captures_text:
            self._repeater.release()
        else:
            for ev in self._repeater.poll(self.now()):
                self._handle_key(ev)
        over = self._topmost(self._mouse())
        ui_set_cursor('ibeam' if over is not None and over.captures_text and over.enabled else 'arrow')
        self.validate_focus()

    def draw(self, surface):
        for w in self.widgets:
            if w.visible:
                w.draw(surface)
        for w in self._flatten(self.widgets):
            w.draw_overlay(surface)
        for L in self.layers:
            L.draw(surface)
            for w in self._flatten(L.roots()):
                w.draw_overlay(surface)


# ── Legacy navigation bridge (requirements 2–6) ───────────────────────────
_NAV_LEGACY_CLASSES = {
    'SettingsScreen', 'SinglePlayerConfigScreen', 'HighScoresScreen',
    'TutorialScreen', 'MultiplayerModeScreen', 'NetworkLobbyScreen',
    'PlayMenuScreen', 'SingleplayerModeScreen', 'EncyclopediaScreen',
    'MapPickerScreen', 'VSAIConfigScreen', 'MapEditorScreen',
    'StartupCheckDialog',
}
_NAV_MAINMENU_METHODS = {
    'show_language_selection', 'show_tutorial', 'show_credits', 'show_achievements',
}
_NAV_EXCLUDE_NAMES = {
    'rect', 'content_rect', 'detail_rect', 'list_rect', 'viewport', 'viewport_rect',
    'panel_rect', 'box', 'cell_rect', 'board_rect', 'clip_rect', 'surface_rect',
    'title_rect', 'scrollbar_rect', '_scrollbar_rect',
}
_NAV_NAME_HINTS = (
    'button', 'btn', 'back', 'prev', 'previous', 'next', 'start', 'play', 'continue',
    'save', 'cancel', 'close', 'confirm', 'apply', 'reset', 'clear', 'delete',
    'connect', 'host', 'join', 'filter', 'settings', 'tutorial', 'achiev', 'highscore',
    'score', 'encycl', 'map', 'single', 'multi', 'ai', 'language', 'option', 'tab',
    'input', 'seed', 'search', 'retry', 'yes', 'no', 'exit', 'mode', 'profile', 'stats',
    'studio', 'mod', 'continue', 'random', 'custom', 'procedural',
)
_NAV_CONTAINER_HINTS = ('rects', 'controls', 'buttons', 'rows', 'options', 'tabs', 'menu')


def _nav_owner_enabled(owner):
    if owner is None:
        return False
    cls = owner.__class__.__name__
    if cls in _NAV_LEGACY_CLASSES:
        return True
    if cls == 'MainMenu':
        try:
            import inspect as _inspect
            _frame = _inspect.currentframe()
            _caller = _frame.f_back if _frame else None
            _screen_frame = _caller.f_back if _caller else None
            method_name = _screen_frame.f_code.co_name if _screen_frame else ''
            return method_name in _NAV_MAINMENU_METHODS
        except Exception:
            return False
    return False


def _nav_rects_from_value(name, value, depth=0):
    """Collect likely interactive pygame.Rects from a legacy run() locals dict."""
    out = []
    if depth > 3:
        return out
    lname = str(name).lower()
    if isinstance(value, pygame.Rect):
        if lname in _NAV_EXCLUDE_NAMES:
            return out
        direct_hint = any(h in lname for h in _NAV_NAME_HINTS) or lname.endswith('_rect')
        if direct_hint:
            out.append((name, value.copy()))
        return out
    if isinstance(value, dict):
        for k, v in value.items():
            out.extend(_nav_rects_from_value(f'{name}.{k}', v, depth + 1))
        return out
    if isinstance(value, (list, tuple)):
        container_hint = any(h in lname for h in _NAV_CONTAINER_HINTS)
        if container_hint or lname.endswith('_rects'):
            for i, v in enumerate(value):
                out.extend(_nav_rects_from_value(f'{name}[{i}]', v, depth + 1))
        return out
    return out


class LegacyAutoNavigator:
    """Shared focus/navigation adapter for legacy blocking screens.

    It deliberately reuses each screen's existing mouse handlers by posting a
    synthetic LMB event on Enter/Space. This keeps business logic in one place
    instead of creating parallel keyboard-only actions for every screen.
    """

    def __init__(self, owner):
        self.owner = owner
        self.focus_index = 0
        self.focus_sig = None
        self.controls = []
        self.scrollbars = []
        self.viewport_rects = []
        self.focus_visible = True

    def _collect_scrollbars(self, scope):
        found = []
        seen = set()
        def visit(v, depth=0):
            if depth > 3 or id(v) in seen:
                return
            seen.add(id(v))
            if isinstance(v, ScrollBar):
                found.append(v)
                return
            if isinstance(v, dict):
                for x in v.values(): visit(x, depth + 1)
            elif isinstance(v, (list, tuple)):
                for x in v: visit(x, depth + 1)
        for v in scope.values():
            visit(v)
        return found

    def refresh(self, scope):
        raw = []
        for name, value in scope.items():
            raw.extend(_nav_rects_from_value(name, value))

        # First-class support for repeated rows whose loop only leaves the last
        # `row_rect` in locals (notably language selection).
        if 'sorted_languages' in scope and isinstance(scope.get('content_rect'), pygame.Rect):
            row_h = int(scope.get('row_height', 52))
            row_gap = int(scope.get('row_spacing', 8))
            row_x = int(scope.get('row_x', scope['content_rect'].x))
            row_w = int(scope.get('row_width', scope['content_rect'].width))
            sb = scope.get('scrollbar')
            off = int(sb.get_content_offset()) if isinstance(sb, ScrollBar) else 0
            for i in range(len(scope['sorted_languages'])):
                rr = pygame.Rect(row_x, scope['content_rect'].y + i * (row_h + row_gap) - off, row_w, row_h)
                raw.append((f'language_row[{i}]', rr))

        controls = []
        seen = set()
        screen_rect = self.owner.screen.get_rect() if hasattr(self.owner, 'screen') else pygame.display.get_surface().get_rect()
        for name, rect in raw:
            if rect.w < 45 or rect.h < 22:
                continue
            if rect.w >= screen_rect.w * 0.92 and rect.h >= screen_rect.h * 0.80:
                continue
            key = (rect.x, rect.y, rect.w, rect.h)
            if key in seen:
                continue
            seen.add(key)
            # Prefer visible/currently useful controls; repeated list rows are
            # permitted offscreen so keyboard focus can trigger scrolling.
            allow_offscreen = ('[' in str(name))
            if not allow_offscreen and not rect.colliderect(screen_rect):
                continue
            controls.append({'name': str(name), 'rect': rect, 'allow_offscreen': allow_offscreen})

        controls.sort(key=lambda c: (c['rect'].top, c['rect'].left, c['name']))
        old_sig = self.focus_signature()
        self.controls = controls[:100]
        self.scrollbars = self._collect_scrollbars(scope)
        self.viewport_rects = []
        for n in ('content_rect', 'list_rect', 'detail_rect', 'viewport', 'box'):
            v = scope.get(n)
            if isinstance(v, pygame.Rect):
                self.viewport_rects.append(v)
        if old_sig:
            for i, c in enumerate(self.controls):
                if (c['name'], tuple(c['rect'])) == old_sig:
                    self.focus_index = i
                    break
            else:
                self.focus_index = min(self.focus_index, max(0, len(self.controls) - 1))
        else:
            self.focus_index = min(self.focus_index, max(0, len(self.controls) - 1))
        self._ensure_focus_visible()

    def focus_signature(self):
        if not self.controls:
            return None
        i = max(0, min(self.focus_index, len(self.controls) - 1))
        c = self.controls[i]
        return c['name'], tuple(c['rect'])

    def _candidate_indices(self):
        # Keep offscreen rows reachable; their selection scrolls the matching bar.
        return list(range(len(self.controls)))

    def _set_focus(self, idx):
        if not self.controls:
            return False
        self.focus_index = idx % len(self.controls)
        self.focus_visible = True
        self._ensure_focus_visible()
        return True

    def _ensure_focus_visible(self):
        if not self.controls or not self.scrollbars:
            return
        c = self.controls[self.focus_index]
        r = c['rect']
        vp = next((v for v in self.viewport_rects if v.inflate(4, 4).colliderect(r) or v.contains(r)), None)
        if vp is None and self.viewport_rects:
            vp = self.viewport_rects[0]
        if vp is not None:
            for sb in self.scrollbars:
                if sb.needs_scroll:
                    # Scroll just enough using screen-space deltas; legacy rows already
                    # contain the current offset in their rect coordinates.
                    if r.top < vp.top:
                        sb.scroll_by(r.top - vp.top)
                    elif r.bottom > vp.bottom:
                        sb.scroll_by(r.bottom - vp.bottom)
                    return

    def _spatial(self, direction):
        if not self.controls:
            return None
        fr = self.controls[self.focus_index]['rect']
        best = None
        best_score = None
        for i, c in enumerate(self.controls):
            if i == self.focus_index:
                continue
            r = c['rect']
            if direction in ('MOVE_UP', 'MOVE_DOWN'):
                sign = -1 if direction == 'MOVE_UP' else 1
                d = (r.centery - fr.centery) * sign
                if d <= 0:
                    continue
                perp = abs(r.centerx - fr.centerx)
                gap = max(0, (fr.top - r.bottom) if sign < 0 else (r.top - fr.bottom))
            else:
                sign = -1 if direction == 'MOVE_LEFT' else 1
                d = (r.centerx - fr.centerx) * sign
                if d <= 0:
                    continue
                perp = abs(r.centery - fr.centery)
                gap = max(0, (fr.left - r.right) if sign < 0 else (r.left - fr.right))
            score = gap + perp * 3 + d * 0.01
            if best_score is None or score < best_score:
                best, best_score = i, score
        return best

    def _scroll(self, action):
        for sb in self.scrollbars:
            if sb.handle_key(action):
                return True
        return False

    def _post_activate(self):
        if not self.controls:
            return False
        r = self.controls[self.focus_index]['rect']
        if r.w <= 0 or r.h <= 0:
            return False
        pygame.event.post(pygame.event.Event(pygame.MOUSEBUTTONDOWN, {'button': 1, 'pos': r.center}))
        return True

    def _find_previous(self):
        for i, c in enumerate(self.controls):
            n = c['name'].lower()
            if 'previous' in n or '.prev' in n or n.endswith('prev_rect') or n.endswith('prev_button'):
                return i
        return None

    def handle(self, event, scope):
        if not _nav_owner_enabled(self.owner):
            return False
        self.refresh(scope)

        if event.type in (pygame.MOUSEMOTION, pygame.MOUSEBUTTONUP):
            pos = getattr(event, 'pos', None) or pygame.mouse.get_pos()
            for sb in self.scrollbars:
                sb.handle_event(event, pos)
            if event.type == pygame.MOUSEMOTION:
                for i, c in enumerate(self.controls):
                    if c['rect'].collidepoint(pos):
                        self.focus_index = i
                        self.focus_visible = False
            return False

        if event.type == pygame.MOUSEBUTTONDOWN:
            pos = getattr(event, 'pos', None) or pygame.mouse.get_pos()
            # Route scrollbar track/thumb before regular controls.
            for sb in self.scrollbars:
                if sb.needs_scroll and sb.bar_rect.collidepoint(pos):
                    sb.handle_event(event, pos)
                    return True
            for i, c in enumerate(self.controls):
                if c['rect'].collidepoint(pos):
                    self.focus_index = i
                    self.focus_visible = False
                    return False
            return False

        if event.type == pygame.MOUSEWHEEL:
            pos = pygame.mouse.get_pos()
            for sb in self.scrollbars:
                region = sb.wheel_rect
                if region is None:
                    if self.viewport_rects:
                        region = next((v for v in self.viewport_rects if v.collidepoint(pos)), None)
                    if region is None:
                        surf = pygame.display.get_surface()
                        region = pygame.Rect(0, sb.rect.y, surf.get_width(), sb.rect.height) if surf else sb.rect
                if sb.needs_scroll and region.collidepoint(pos):
                    sb.handle_event(event, pos)
                    return True
            return False

        if event.type != pygame.KEYDOWN:
            return False

        # Legacy text inputs often use an *_active boolean. Let those fields own
        # printable/editing/confirm keys; Tab/Escape remain global navigation.
        active_text = any(bool(v) for n, v in scope.items()
                          if str(n).endswith('_active') and bool(v)
                          and ('input' in str(n).lower() or 'text' in str(n).lower() or 'seed' in str(n).lower()))
        actions = UI_INPUT.actions_for(event)
        if not actions:
            return False
        if active_text and any(a not in ('FOCUS_NEXT', 'FOCUS_PREV', 'BACK') for a in actions):
            return False

        for action in actions:
            if action == 'FOCUS_NEXT':
                self._set_focus(self.focus_index + 1)
                return True
            if action == 'FOCUS_PREV':
                self._set_focus(self.focus_index - 1)
                return True
            if action == 'PREVIOUS':
                idx = self._find_previous()
                if idx is not None:
                    self._set_focus(idx)
                    self._post_activate()
                    return True
                return False
            if action in ('PAGE_UP', 'PAGE_DOWN', 'HOME', 'END'):
                if self._scroll(action):
                    return True
                if self.controls:
                    self._set_focus(0 if action in ('PAGE_UP', 'HOME') else len(self.controls) - 1)
                    return True
            if action in ('MOVE_UP', 'MOVE_DOWN', 'MOVE_LEFT', 'MOVE_RIGHT'):
                target = self._spatial(action)
                if target is not None:
                    self._set_focus(target)
                    return True
                if action in ('MOVE_UP', 'MOVE_DOWN') and self._scroll(action):
                    return True
                return bool(self.controls)
            if action == 'CONFIRM':
                return self._post_activate()
            if action == 'BACK':
                return False
            if action == 'TOGGLE_FULLSCREEN':
                return False
        return False

    def draw(self):
        if not _nav_owner_enabled(self.owner) or not self.controls or not self.focus_visible:
            return
        c = self.controls[max(0, min(self.focus_index, len(self.controls) - 1))]
        r = c['rect']
        surf = self.owner.screen if hasattr(self.owner, 'screen') else pygame.display.get_surface()
        if surf is None:
            return
        clip = r.clip(surf.get_rect())
        if clip.w > 0 and clip.h > 0:
            ui_draw_focus_ring(surf, clip, 7)


def _legacy_nav_event(owner, event, scope):
    if _handle_replay_save_retry_event(owner, event):
        return True
    if owner is None or not _nav_owner_enabled(owner):
        return False
    if 'DEV_TOOLS' in globals() and DEV_TOOLS.unlocked:
        # Single hook point so every legacy screen that already calls
        # _legacy_nav_event (High Scores, Settings, Encyclopedia, Map
        # Editor, Tutorial, lobby/config/gameplay screens, ...) gets these
        # for free, instead of wiring them into each screen by hand — per
        # spec: unlocked DEV Mode should be reachable from almost anywhere
        # in the game, not just gameplay, and the overlay must have a quick
        # way to get out of the way without obstructing gameplay.
        if event.type == pygame.KEYDOWN and event.key == pygame.K_F8:
            DEV_TOOLS.open_panel(getattr(owner, 'screen', None), game=None)
            return True
        if event.type == pygame.KEYDOWN and event.key == pygame.K_F9:
            DEV_TOOLS.toggle_overlay_hidden()
            return True
        if (event.type == pygame.MOUSEBUTTONDOWN and event.button == 1
                and DEV_TOOLS._overlay_toggle_rect is not None
                and DEV_TOOLS._overlay_toggle_rect.collidepoint(event.pos)):
            DEV_TOOLS.toggle_overlay_hidden()
            return True
    nav = getattr(owner, '_sgf_legacy_nav', None)
    if nav is None:
        nav = LegacyAutoNavigator(owner)
        owner._sgf_legacy_nav = nav
    return nav.handle(event, scope)


def _legacy_nav_draw(owner):
    if owner is None or not _nav_owner_enabled(owner):
        return
    nav = getattr(owner, '_sgf_legacy_nav', None)
    if nav is not None:
        nav.draw()


NAV_PREVIOUS = '__SGF_NAV_PREVIOUS__'
NAV_BACK_LEVEL = '__SGF_NAV_BACK_LEVEL__'

