def _replay_ui_text(language, key, **values):
    text = (_REPLAY_UI_TEXT.get(language) or {}).get(key) or _REPLAY_UI_TEXT['en'][key]
    return text.format(**values) if values else text


_REPLAY_FILE_EXTENSION = '.sgfr'


def _replay_export_dir():
    """Folder for shareable replay files (created on demand, next to the other data)."""
    path = os.path.join(_user_data_manager.get_root_dir(), 'exports')
    os.makedirs(path, exist_ok=True)
    return path


def save_replay_file(score_data, directory=None):
    """Write a share-code replay file (magic, version and SHA-256 inside) atomically.

    The .sgfr file holds exactly the validated share code, so a file and a
    copied code are interchangeable and both go through the same bounded,
    integrity-checked importer.
    """
    code = export_replay_share_code(score_data)
    directory = directory or _replay_export_dir()
    stem = _safe_content_id(
        f"replay-{score_data.get('score', 0)}-{score_data.get('seed') or score_data.get('date') or 'run'}",
        'replay')
    path = os.path.join(directory, stem + _REPLAY_FILE_EXTENSION)
    counter = 1
    while os.path.exists(path):
        counter += 1
        path = os.path.join(directory, f"{stem}-{counter}{_REPLAY_FILE_EXTENSION}")
    temp_path = path + '.tmp'
    with open(temp_path, 'w', encoding='ascii', newline='\n') as handle:
        handle.write(code + '\n')
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(temp_path, path)
    return path


def load_replay_file(path):
    """Read an .sgfr file; the contents are validated like any pasted share code."""
    if not str(path).lower().endswith(_REPLAY_FILE_EXTENSION):
        raise ValueError('Replay files use the .sgfr extension.')
    if os.path.getsize(path) > _REPLAY_SHARE_MAX_CODE_BYTES + 16:
        raise ValueError('Replay file is too large.')
    with open(path, 'r', encoding='ascii', errors='strict') as handle:
        return import_replay_share_code(handle.read(_REPLAY_SHARE_MAX_CODE_BYTES + 16).strip())


def _network_transport_status(language, uses_cloudflare, state, detail=''):
    """Return only the status belonging to the selected network transport."""
    if not uses_cloudflare:
        return ''
    return _cloudflare_status_text(language, state, detail)

# ---- Floating widget base (used by the lobby card and the Slinky guide) ----
class FloatingWidget:
    TITLE_H = 28

    def __init__(self, title_fn, rect, closable=True):
        self.title_fn = title_fn
        self.rect = pygame.Rect(rect)
        self.closable = closable
        self.minimized = False
        self.dragging = False
        self.user_moved = False
        self._drag_offset = (0, 0)
        self.closed = False

    # -- geometry ---------------------------------------------------------
    def title_rect(self):
        return pygame.Rect(self.rect.x, self.rect.y, self.rect.w, self.TITLE_H)

    def min_button_rect(self):
        t = self.title_rect()
        right = t.right - (30 if self.closable else 0)
        return pygame.Rect(right - 26, t.y + 4, 22, 20)

    def close_button_rect(self):
        t = self.title_rect()
        return pygame.Rect(t.right - 28, t.y + 4, 22, 20)

    def body_rect(self):
        return pygame.Rect(self.rect.x, self.rect.y + self.TITLE_H, self.rect.w,
                           max(0, self.rect.h - self.TITLE_H))

    def occupied_rect(self):
        return self.title_rect() if self.minimized else self.rect

    def clamp(self, bounds):
        """Never lose the widget: at least 60 px of its title bar stays on screen."""
        keep = 60
        self.rect.x = max(bounds.left - self.rect.w + keep, min(self.rect.x, bounds.right - keep))
        self.rect.y = max(bounds.top, min(self.rect.y, bounds.bottom - self.TITLE_H))

    # -- hooks ------------------------------------------------------------
    def draw_body(self, surface, body):
        pass

    def handle_body_event(self, event):
        return False

    def on_close(self):
        self.closed = True

    # -- events -----------------------------------------------------------
    def handle_event(self, event, bounds):
        """True when the event belonged to the widget (and must not reach the screen)."""
        if event.type == pygame.MOUSEMOTION and self.dragging:
            self.rect.x = event.pos[0] - self._drag_offset[0]
            self.rect.y = event.pos[1] - self._drag_offset[1]
            self.user_moved = True
            self.clamp(bounds)
            return True
        if event.type == pygame.MOUSEBUTTONUP and event.button == 1 and self.dragging:
            self.dragging = False
            return True
        if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
            if not self.occupied_rect().collidepoint(event.pos):
                return False
            if self.closable and self.close_button_rect().collidepoint(event.pos):
                self.on_close()
            elif self.min_button_rect().collidepoint(event.pos):
                self.minimized = not self.minimized
            elif self.title_rect().collidepoint(event.pos):
                self.dragging = True
                self._drag_offset = (event.pos[0] - self.rect.x, event.pos[1] - self.rect.y)
            elif not self.minimized:
                self.handle_body_event(event)
            return True
        if not self.minimized and event.type == pygame.MOUSEBUTTONUP and \
                self.body_rect().collidepoint(getattr(event, 'pos', (-1, -1))):
            return True
        return False

    # -- drawing ----------------------------------------------------------
    def draw(self, surface):
        if self.closed:
            return
        language = _LAST_LANGUAGE[0]
        self.clamp(surface.get_rect())
        area = self.occupied_rect()
        pygame.draw.rect(surface, (20, 26, 44), area, border_radius=8)
        pygame.draw.rect(surface, (110, 135, 175), area, 2, border_radius=8)
        title_font = get_font(language, 'bold', 15)
        title = render_fit(title_font, self.title_fn(), (120, 220, 130), self.rect.w - 80, padding=0)
        surface.blit(title, (self.rect.x + 10, self.rect.y + (self.TITLE_H - title.get_height()) // 2))
        for rect, glyph in ((self.min_button_rect(), 'max' if self.minimized else 'min'),
                            (self.close_button_rect(), 'x')):
            if glyph == 'x' and not self.closable:
                continue
            pygame.draw.rect(surface, (50, 58, 84), rect, border_radius=4)
            cx, cy = rect.center
            if glyph == 'min':
                pygame.draw.line(surface, (235, 240, 250), (cx - 5, cy + 3), (cx + 5, cy + 3), 2)
            elif glyph == 'max':
                pygame.draw.rect(surface, (235, 240, 250), (cx - 5, cy - 4, 10, 8), 2)
            else:
                pygame.draw.line(surface, (255, 150, 150), (cx - 4, cy - 4), (cx + 4, cy + 4), 2)
                pygame.draw.line(surface, (255, 150, 150), (cx - 4, cy + 4), (cx + 4, cy - 4), 2)
        if not self.minimized:
            self.draw_body(surface, self.body_rect())


# ---------------------------------------------------------------------------
# HostLobby: everything a host needs to wait for players (TLS identity, invite,
# listening sockets, the Cloudflare relay, the handshake workers and the room
# roster), owned by this object instead of by the host screen. The screen is a
# view on it, so the lobby keeps listening when the player leaves the menu.
# poll() never draws and never touches pygame events; the overlay layer calls it
# once per frame on every screen, so no extra thread has to share its state.
# ---------------------------------------------------------------------------
