def _lobby_label(language, key, **values):
    table = _LOBBY_LABELS.get(language) or _LOBBY_LABELS['en']
    text = table.get(key) or _LOBBY_LABELS['en'][key]
    return text.format(**values) if values else text


class HostLobbyError(Exception):
    """kind is 'tls' (identity could not be created) or 'listen' (sockets)."""

    def __init__(self, kind, cause):
        super().__init__(str(cause))
        self.kind = kind
        self.cause = cause


def _lobby_broadcast_room(roster, max_players, host_name):
    """Tell every waiting guest who is in the room (host first, then join order)."""
    names = [host_name] + [entry['name'] for entry in roster]
    for index, entry in enumerate(roster, start=1):
        entry['link']._send_safe({'t': 'lobby', 'names': names, 'you': index, 'max': max_players})


def _lobby_service_room(roster, max_players, host_name):
    """Keep waiting guests alive; drop the ones that left or went silent."""
    changed = False
    for entry in list(roster):
        link = entry['link']
        for _ in range(8):
            try:
                msg = link._recv_q.get_nowait()
            except _queue_mod.Empty:
                break
            outcome = link._handle_link_message(msg)
            if outcome == 'stop':
                break
            if outcome is None and msg.get('t') == 'profile':
                new_name = _clean_player_name(msg.get('name'), entry['name'])
                changed = changed or new_name != entry['name']
                entry['name'] = new_name
        link._service_link()
        if not link.connected:
            roster.remove(entry)
            link._stop_event.set()
            link._stop_io()
            changed = True
    if changed:
        _lobby_broadcast_room(roster, max_players, host_name)


class HostLobby:
    def __init__(self, port, mode, max_players=2, seed=None, use_tunnel=True,
                 host_name_fn=lambda: 'Host'):
        self.port = port
        self.mode = mode
        self.max_players = max_players
        self.seed = seed if seed else generate_seed()
        self.use_tunnel = use_tunnel
        self.host_name_fn = host_name_fn
        self.room_mode = max_players > 2
        self.chosen_map = None
        self.tls_context = self.tls_fingerprint = None
        self.join_token = self.resume_token = None
        self.invite_code = ''
        self.connection_info = ''
        self.info_version = 0
        self.local_ips, self.local_ip_done = [], False
        self.public_ip, self.public_ip_done = None, False
        self.lan_selected = 0
        self.funnel = ('lan', '', None, '')
        self.tunnel_session = None
        self.srv_sockets = []
        self.roster = []
        self.match_ready = False
        self.match_conn = None
        self.match_link = None          # 1v1: the waiting guest's link, kept alive by this lobby
        self.match_session = None
        self.consumed = False
        self.closed = False
        self.ui_attached = 0
        self.keep_background = False
        self.open_requested = False
        self.widget = None
        self._runtime = None
        self._pending_resume_token = None
        self._handshake_results = _queue_mod.Queue(maxsize=1)
        self._handshake_cancel = threading.Event()
        self._handshake_lock = threading.Lock()
        self._handshake_pending = False
        self._attempts_by_ip = {}
        self._local_ip_result = _queue_mod.Queue(maxsize=1)
        self._public_ip_result = _queue_mod.Queue(maxsize=1)
        self._last_poll = 0.0
        self._last_players = 1
        self._auto_open_done = False

    # -- life cycle ---------------------------------------------------------
    def prepare(self):
        """TLS identity, invite and tokens. Raises HostLobbyError('tls')."""
        try:
            self.tls_context, self.tls_fingerprint = _create_network_tls_server_context()
        except Exception as exc:
            raise HostLobbyError('tls', exc)
        self.join_token = _secrets_mod.token_bytes(32)
        self.resume_token = _new_resume_token()
        self.invite_code = _make_network_invite(self.tls_fingerprint, self.join_token)
        self.connection_info = self.invite_code

    def start(self):
        """Open the listeners and (for Network play) the relay. Raises HostLobbyError('listen')."""
        def detect_local_ips():
            try:
                result = _get_local_ips()
            except Exception:
                result = []
            try:
                self._local_ip_result.put_nowait(result)
            except _queue_mod.Full:
                pass
        threading.Thread(target=detect_local_ips, name='SGF-local-ip-detection', daemon=True).start()
        try:
            self.srv_sockets = _create_network_listener_sockets(self.port)
        except Exception as exc:
            raise HostLobbyError('listen', exc)
        if self.use_tunnel:
            self.tunnel_session = CloudflareQuickTunnelSession(self.port, self.invite_code).start()
            threading.Thread(target=lambda: self._public_ip_result.put(_lookup_public_ip()),
                             name='SGF-public-ip', daemon=True).start()
        self._pending_resume_token = self.resume_token
        _ACTIVE_HOST_LOBBY[0] = self
        self.widget = LobbyWidget(self)
        register_event_filter(self.widget.handle_global, priority=150)
        register_overlay(self.overlay)
        return self

    def attach_runtime(self, runtime):
        """Kept for compatibility: the widget now gets input from the event filter layer."""
        self._runtime = runtime

    def restart_tunnel(self):
        if self.tunnel_session is not None:
            self.tunnel_session.stop()
            self.tunnel_session = CloudflareQuickTunnelSession(self.port, self.invite_code).start()
            self._set_info(self.invite_code)

    def _release(self):
        unregister_overlay(self.overlay)
        if self.widget is not None:
            unregister_event_filter(self.widget.handle_global)
        if _ACTIVE_HOST_LOBBY[0] is self:
            _ACTIVE_HOST_LOBBY[0] = None

    def stop(self):
        """Close everything (idempotent). A lobby whose connection was handed to
        a match is `consumed`: only the registration is removed."""
        if self.closed:
            return
        self.closed = True
        self._release()
        if self.consumed:
            return
        pending_ok, pending_result = False, None
        with self._handshake_lock:
            self._handshake_cancel.set()
            try:
                pending_ok, pending_result = self._handshake_results.get_nowait()
            except _queue_mod.Empty:
                pass
        if pending_ok:
            try:
                pending_result.close()
            except Exception:
                pass
        if self.match_link is not None:
            self._close_match_link(announce=True)
        if self.match_conn is not None:
            try:
                self.match_conn.close()
            except Exception:
                pass
        for entry in self.roster:
            entry['link']._stop_event.set()
            entry['link'].connected = False
            entry['link']._stop_io()
        if self.tunnel_session is not None:
            self.tunnel_session.stop()
        for srv in self.srv_sockets:
            try:
                srv.close()
            except OSError:
                pass
        self.srv_sockets = []

    # -- state --------------------------------------------------------------
    @property
    def players(self):
        return 1 + len(self.roster) + (1 if self.match_ready else 0)

    def _set_info(self, candidate):
        if candidate != self.connection_info:
            self.connection_info = candidate
            self.info_version += 1

    def poll(self, force=False):
        """One non-blocking step: detect addresses, follow the relay, finish
        handshakes, service the room and accept the next guest."""
        if self.closed or self.consumed:
            return
        now = time.monotonic()
        if not force and now - self._last_poll < 0.015:
            return
        self._last_poll = now
        if not self.local_ip_done:
            try:
                self.local_ips = _order_lan_addresses(self._local_ip_result.get_nowait())
                self.local_ip_done = True
                if self.local_ips:
                    self._set_info(_format_network_connection_info(self.local_ips[0], self.port, self.invite_code))
            except _queue_mod.Empty:
                pass
        if self.tunnel_session is not None and not self.public_ip_done:
            try:
                self.public_ip = self._public_ip_result.get_nowait()
                self.public_ip_done = True
                if self.public_ip and self.tunnel_session.snapshot()[0] != 'ready':
                    self._set_info(_format_network_connection_info(self.public_ip, self.port, self.invite_code))
            except _queue_mod.Empty:
                pass
        if self.tunnel_session is None and self.local_ips:
            # LAN play: the shared link follows the address the host picked.
            self.lan_selected = max(0, min(self.lan_selected, len(self.local_ips) - 1))
            self._set_info(_format_network_connection_info(
                self.local_ips[self.lan_selected], self.port, self.invite_code))
        self.funnel = (self.tunnel_session.snapshot() if self.tunnel_session is not None
                       else ('lan', '', None, ''))
        funnel_state, funnel_host, funnel_port, _detail = self.funnel
        if funnel_state == 'ready' and funnel_host and funnel_port:
            self._set_info(_format_network_connection_info(funnel_host, funnel_port, self.invite_code))
        elif self.public_ip and self.tunnel_session is not None:
            self._set_info(_format_network_connection_info(self.public_ip, self.port, self.invite_code))
        try:
            result_ok, result_value = self._handshake_results.get_nowait()
            self._handshake_pending = False
            if result_ok and self.room_mode:
                self.roster.append({'link': _PeerLink(result_value, True),
                                    'resume': self._pending_resume_token,
                                    'name': f'Player {len(self.roster) + 2}'})
                _lobby_broadcast_room(self.roster, self.max_players, self.host_name_fn())
                sgf_log.info('Guest joined the room (%d/%d)', len(self.roster) + 1, self.max_players)
            elif result_ok:
                self.match_conn = result_value
                self.match_session = {'listeners': self.srv_sockets, 'tls_context': self.tls_context,
                                      'resume_token': self.resume_token, 'attempts': {}}
                self.match_link = _LobbyGuestLink(result_value, True, self.match_session)
                self.match_ready = True
                sgf_log.info('Guest connected; keeping it alive until the match starts')
            else:
                # Keep a useful failure reason in the local log. The UI stays
                # generic; the bounded detail helps diagnose TLS/protocol
                # mismatches without recording invite tokens or peer addresses.
                reason = ' '.join(str(result_value or '').split())[:180]
                sgf_log.warning('Rejected peer during secure multiplayer handshake: %s',
                                reason or 'no detail supplied')
        except _queue_mod.Empty:
            pass
        if self.room_mode:
            _lobby_service_room(self.roster, self.max_players, self.host_name_fn())
        if self.match_link is not None:
            self._service_match_link()
        if self.match_ready:
            return
        if not self._handshake_pending and (not self.room_mode or len(self.roster) < self.max_players - 1):
            raw_conn = peer_addr = None
            for srv in self.srv_sockets:
                try:
                    raw_conn, peer_addr = srv.accept()
                    break
                except (BlockingIOError, _socket_mod.timeout):
                    continue
                except OSError:
                    continue
            if raw_conn is not None:
                peer_ip = peer_addr[0] if peer_addr else ''
                if not _allow_network_handshake_attempt(peer_ip, self._attempts_by_ip):
                    raw_conn.close()
                    return
                try:
                    raw_conn.setsockopt(_socket_mod.IPPROTO_TCP, _socket_mod.TCP_NODELAY, 1)
                    if self.room_mode:
                        self._pending_resume_token = _new_resume_token()
                    threading.Thread(
                        target=_finish_secure_host_handshake,
                        args=(raw_conn, self.tls_context, self.join_token, self.mode,
                              self.chosen_map, self.seed, self._handshake_results,
                              self._handshake_cancel, self._handshake_lock),
                        kwargs={'resume_token': self._pending_resume_token,
                                'max_players': self.max_players},
                        name='SGF-secure-handshake', daemon=True).start()
                    self._handshake_pending = True
                except Exception:
                    try:
                        raw_conn.close()
                    except OSError:
                        pass

    # -- the waiting 1v1 guest ----------------------------------------------
    def guest_ready(self):
        """1v1: a guest is connected and its link is healthy (not mid-reconnect)."""
        if not self.match_ready:
            return False
        link = self.match_link
        return link is None or link.is_healthy()

    def _service_match_link(self):
        """Keep the waiting guest alive; free the seat when it leaves for good."""
        link = self.match_link
        try:
            link.service_waiting()
        except Exception as exc:
            sgf_log.warning('Waiting guest could not be serviced: %s', type(exc).__name__)
        if link.is_gone():
            sgf_log.info('The waiting guest left; the lobby is open for a new one')
            self._close_match_link(announce=False)
            self.match_ready = False
            self._auto_open_done = False
            # A new credential, so the guest that left cannot slip back into the seat.
            self.resume_token = self._pending_resume_token = _new_resume_token()

    def _close_match_link(self, announce):
        link, self.match_link = self.match_link, None
        self.match_conn = None
        if link is None:
            return
        if announce and link.connected and not link.peer_left:
            # Deliberate exit: the guest must not spend 30 s trying to come back.
            if link._send_safe({'t': 'bye'}):
                flush_deadline = time.monotonic() + 0.3
                while time.monotonic() < flush_deadline and link._send_q.unfinished_tasks > 0:
                    time.sleep(0.01)
        link.close()

    # -- hand-over to a match -----------------------------------------------
    def take_match(self):
        """1v1: (result, tunnel_session, pending_session) for the connected guest."""
        link = self.match_link
        conn = link if link is not None else self.match_conn
        tunnel = self.tunnel_session if self.funnel[0] == 'ready' else None
        if tunnel is not None:
            self.tunnel_session = None
        pending = self.match_session or {
            'listeners': self.srv_sockets, 'tls_context': self.tls_context,
            'resume_token': self.resume_token, 'attempts': {}}
        self.srv_sockets = []
        self.match_conn = None
        self.match_link = None
        self.consumed = True
        self._release()
        return (True, conn, self.mode, self.chosen_map, self.seed), tunnel, pending

    def take_room(self):
        """Room: (result, tunnel_session, pending_session) when the host starts the match."""
        tunnel = self.tunnel_session if self.funnel[0] == 'ready' else None
        if tunnel is not None:
            self.tunnel_session = None
        pending = {'listeners': self.srv_sockets, 'tls_context': self.tls_context,
                   'resume_tokens': {index + 1: entry['resume'] for index, entry in enumerate(self.roster)},
                   'attempts': {}}
        self.srv_sockets = []
        names = [self.host_name_fn()] + [entry['name'] for entry in self.roster]
        result = (True, {'kind': 'n', 'roster': self.roster, 'names': names},
                  self.mode, self.chosen_map, self.seed)
        self.consumed = True
        self._release()
        return result, tunnel, pending

    # -- overlay ------------------------------------------------------------
    def overlay(self, surface):
        """Called by the overlay layer on every frame, on every screen."""
        try:
            self.poll()
        except Exception as exc:
            sgf_log.warning('Lobby poll failed: %s', type(exc).__name__)
        if self.widget is not None and not self.ui_attached and not self.closed and not self.consumed:
            if self.players != self._last_players:
                if self.players > self._last_players:
                    self.widget.notify()
                self._last_players = self.players
            elif self.match_ready and not self.widget.notified_ready:
                self.widget.notify()
            if self.guest_ready() and not self.room_mode and not self._auto_open_done:
                # 1v1: the guest is already connected and only the host can start,
                # so go straight back into the match as soon as the menu is idle.
                self._auto_open_done = True
                self.open_requested = True
            self.widget.draw(surface)


class LobbyWidget(FloatingWidget):
    """Small floating status card for a lobby that keeps listening while the
    player is somewhere else in the game."""

    def __init__(self, lobby):
        super().__init__(lambda: _lobby_label(_LAST_LANGUAGE[0], 'title'),
                         pygame.Rect(0, 0, 300, 132), closable=False)
        self.lobby = lobby
        self.flash_until = 0.0
        self.notified_ready = False
        self._buttons = {}
        self._copied_until = 0.0
        self.rect.topleft = (12, 44)

    def notify(self):
        self.flash_until = time.monotonic() + 8.0
        self.minimized = False
        if self.lobby.match_ready:
            self.notified_ready = True

    def _status_text(self, language):
        state = self.lobby.funnel[0]
        if self.lobby.tunnel_session is None:
            return _lobby_label(language, 'lan')
        if state == 'ready':
            return _lobby_label(language, 'relay_ready')
        if state in ('unavailable', 'stopped', 'not_installed'):
            return _lobby_label(language, 'relay_down')
        return _lobby_label(language, 'relay_wait')

    def handle_body_event(self, event):
        for key, rect in self._buttons.items():
            if rect.collidepoint(event.pos):
                if key == 'open':
                    self.lobby.open_requested = True
                elif key == 'copy':
                    if self.lobby.connection_info and _copy_to_clipboard(self.lobby.connection_info):
                        self._copied_until = time.monotonic() + 2.0
                elif key == 'stop':
                    self.lobby.stop()
                return True
        return False

    def handle_global(self, event, _actions=None):
        """Non-modal: only the events that belong to the widget are consumed."""
        if self.lobby.closed or self.lobby.ui_attached:
            return False
        surface = pygame.display.get_surface()
        bounds = surface.get_rect() if surface is not None else pygame.Rect(0, 0, 800, 600)
        if event.type in (pygame.MOUSEBUTTONDOWN, pygame.MOUSEBUTTONUP, pygame.MOUSEMOTION):
            return self.handle_event(event, bounds)
        return False

    def draw_body(self, surface, body):
        language = _LAST_LANGUAGE[0]
        font = get_font(language, 'regular', 14)
        bold = get_font(language, 'bold', 14)
        now = time.monotonic()
        y = body.y + 8
        for text, color in (
                (self._status_text(language), (200, 215, 240)),
                (_lobby_label(language, 'players', n=self.lobby.players, max=self.lobby.max_players),
                 (235, 240, 250))):
            surface.blit(font.render(text, True, color), (body.x + 10, y))
            y += font.get_height() + 3
        if now < self.flash_until:
            key = 'ready' if self.lobby.match_ready else 'joined'
            surface.blit(bold.render(_lobby_label(language, key), True, (255, 215, 0)), (body.x + 10, y))
        y = body.bottom - 34
        self._buttons = {}
        bx = body.x + 10
        for key, label, color in (
                ('open', _lobby_label(language, 'open'), (60, 130, 70)),
                ('copy', _lobby_label(language, 'copied' if now < self._copied_until else 'copy'), (50, 58, 84)),
                ('stop', _lobby_label(language, 'stop'), (130, 50, 50))):
            text = bold.render(label, True, (255, 255, 255))
            rect = pygame.Rect(bx, y, text.get_width() + 18, 26)
            pygame.draw.rect(surface, color, rect, border_radius=6)
            surface.blit(text, (rect.x + 9, rect.y + (rect.h - text.get_height()) // 2))
            self._buttons[key] = rect
            bx = rect.right + 6


def stop_active_host_lobby():
    lobby = _ACTIVE_HOST_LOBBY[0]
    if lobby is not None:
        lobby.stop()


class NetworkLobbyScreen:
    """UI for LAN host/join setup. Returns (is_host, conn, mode) or None."""

    PORT = 12345

    def __init__(self, settings, screen):
        self.settings = settings
        self.screen   = screen
        self.transport = 'network'
        self._pending_map = None
        self._pending_seed = None
        self._pending_tunnel_session = None
        self._pending_session = None
        self._seed = None

    # ── public entry-point ───────────────────────────────────────────────

    def run(self, seed=None, transport=None):
        """Show mode → host/join flow. Returns (is_host, conn, mode, map, seed)."""
        self._pending_tunnel_session = None
        self._pending_session = None
        if transport in ('network', 'lan'):
            self.transport = transport
        self._seed = seed if seed else generate_seed()
        active = _ACTIVE_HOST_LOBBY[0]
        if active is not None and not active.closed:
            return self.run_attached(active)       # a lobby is already listening: go back into it
        net_mode = self._pick_mode()
        if net_mode is None:
            return None
        while True:
            choice = self._pick_host_join()
            if choice is None:
                return None
            elif choice == 'host':
                room_size = self._pick_player_count()
                if room_size is None:
                    continue
                result = self._host_flow(net_mode, self._seed, room_size)
                if result:
                    return result
            elif choice == 'join':
                result = self._join_flow(net_mode, self._seed)
                if result:
                    return result

    def run_attached(self, lobby):
        """Re-open a lobby that kept listening in the background."""
        self._pending_tunnel_session = None
        self._pending_session = None
        self._seed = lobby.seed
        return self._host_flow(lobby.mode, lobby.seed, lobby.max_players, lobby=lobby)

    # ── internal screens ────────────────────────────────────────────────

    def _draw_bg(self):
        sw, sh = self.screen.get_width(), self.screen.get_height()
        self.screen.fill(COLORS['dark_blue'])
        t = pygame.time.get_ticks() / 1000.0
        for i in range(20):
            px = int(sw * ((i * 137) % 100) / 100)
            py = int(sh * ((i * 97 + t * 12) % 100) / 100)
            pygame.draw.circle(self.screen, (35, 55, 115), (px, py), 2)

    def _mk_btn(self, rect, label, base_col, mp, font):
        col = tuple(min(255, c + 30) for c in base_col) if rect.collidepoint(mp) else base_col
        pygame.draw.rect(self.screen, col, rect, border_radius=10)
        pygame.draw.rect(self.screen, (180, 210, 255), rect, width=1, border_radius=10)
        s = font.render(label, True, COLORS['white'])
        # Some languages render noticeably wider than English at the same point
        # size (e.g. Arabic, German compound words). Rather than overflow the
        # button box, shrink the rendered label proportionally to fit, so this
        # works for every language without hand-tuning button widths per string.
        max_w = rect.width - 16
        if s.get_width() > max_w and s.get_width() > 0:
            scale = max_w / s.get_width()
            new_size = (max_w, max(1, int(s.get_height() * scale)))
            s = pygame.transform.smoothscale(s, new_size)
        self.screen.blit(s, (rect.centerx - s.get_width() // 2,
                              rect.centery - s.get_height() // 2))

    def _draw_subtitle(self, lang, key, sw, y):
        font = get_font(lang, 'regular', 14)
        surface = render_fit(font, _net_ui_text(lang, key), (140, 170, 220), sw - 32, padding=0)
        self.screen.blit(surface, (sw // 2 - surface.get_width() // 2, y))

    def _draw_relay_host_panel(self, lang, mf, sf, state, detail, host, public_ip,
                               public_ip_done, ready_to_copy, copied, mouse_pos):
        """Network play (Cloudflare): relay progress and one shareable invite link.

        Returns the clickable rectangles: {'copy': Rect, 'retry': Rect | None}.
        """
        sw, sh = self.screen.get_width(), self.screen.get_height()
        small = get_font(lang, 'regular', 13)
        left = max(16, sw // 2 - 200)
        y = int(sh * 0.17)
        step_names = ('step_prepare', 'step_start', 'step_connect', 'step_ready')
        active = _relay_step_index(state)
        pulse = 0.5 + 0.5 * math.sin(pygame.time.get_ticks() / 260.0)
        for index, key in enumerate(step_names):
            failed = False   # once the relay reports failure, which step stalled is unknown
            if active == -1:
                # A failure before the tunnel existed: mark the first step.
                done = False
            else:
                done = index < active
            current = (not done) and active != -1 and index == active
            centre = (left + 9, y + 11)
            if failed:
                pygame.draw.circle(self.screen, (230, 90, 90), centre, 8)
                label_colour = (255, 150, 150)
            elif done:
                pygame.draw.circle(self.screen, (80, 200, 130), centre, 8)
                pygame.draw.line(self.screen, (15, 45, 30), (centre[0] - 4, centre[1]),
                                 (centre[0] - 1, centre[1] + 3), 2)
                pygame.draw.line(self.screen, (15, 45, 30), (centre[0] - 1, centre[1] + 3),
                                 (centre[0] + 4, centre[1] - 3), 2)
                label_colour = (170, 235, 195)
            elif current:
                level = int(150 + 90 * pulse)
                pygame.draw.circle(self.screen, (level, level, 120), centre, 8)
                label_colour = (255, 245, 200)
            else:
                pygame.draw.circle(self.screen, (80, 90, 120), centre, 8, 2)
                label_colour = (120, 135, 165)
            text = render_fit(sf, _net_ui_text(lang, key), label_colour, sw - left - 40, padding=0)
            self.screen.blit(text, (left + 26, y + 11 - text.get_height() // 2))
            y += 30
        y += 4
        status_text = _network_transport_status(lang, True, state, detail)
        if status_text:
            status_surface = render_fit(small, status_text, (140, 160, 195), sw - 32, padding=0)
            self.screen.blit(status_surface, (sw // 2 - status_surface.get_width() // 2, y))
        y += 26

        retry_rect = None
        if state == 'ready' and host:
            card = pygame.Rect(left, y, min(400, sw - 32), 58)
            pygame.draw.rect(self.screen, (18, 52, 44), card, border_radius=10)
            pygame.draw.rect(self.screen, (80, 200, 130), card, width=1, border_radius=10)
            caption = small.render(_net_ui_text(lang, 'link_label'), True, (150, 215, 180))
            self.screen.blit(caption, (card.x + 14, card.y + 8))
            host_surface = render_fit(sf, streamer_mask(host), (230, 255, 240), card.width - 28, padding=0)
            self.screen.blit(host_surface, (card.x + 14, card.y + 30))
            y = card.bottom + 10
            for line in _wrap_ui_text(small, _net_ui_text(lang, 'network_host_hint'), min(400, sw - 32), 3):
                hint_surface = small.render(line, True, (150, 170, 205))
                self.screen.blit(hint_surface, (left, y))
                y += 18
        elif state in ('unavailable', 'not_installed'):
            failure = render_fit(sf, _net_ui_text(lang, 'relay_failed'), (255, 150, 150), sw - 32, padding=0)
            self.screen.blit(failure, (sw // 2 - failure.get_width() // 2, y))
            y += 28
            retry_rect = pygame.Rect(sw // 2 - 90, y, 180, 34)
            self._mk_btn(retry_rect, _net_ui_text(lang, 'relay_retry'), (120, 70, 30), mouse_pos, sf)
            y += 46
            fallback = _net_ui_text(lang, 'relay_fallback', port=streamer_mask(self.PORT))
            for line in _wrap_ui_text(small, fallback, min(420, sw - 32), 2):
                fallback_surface = small.render(line, True, (230, 190, 120))
                self.screen.blit(fallback_surface, (sw // 2 - fallback_surface.get_width() // 2, y))
                y += 18
            if public_ip:
                public_surface = render_fit(
                    small, f"{get_text(lang, 'public_ip_label')}: {streamer_mask(public_ip)}",
                    (140, 200, 235), sw - 32, padding=0)
                self.screen.blit(public_surface, (sw // 2 - public_surface.get_width() // 2, y))

        copy_rect = pygame.Rect(sw // 2 - 115, int(sh * 0.74), 230, 40)
        label = _net_ui_text(lang, 'link_copied' if copied else 'copy_link')
        self._mk_btn(copy_rect, label, (30, 100, 70) if ready_to_copy else (55, 58, 68),
                     mouse_pos, sf)
        return {'copy': copy_rect, 'retry': retry_rect}

    def _draw_lan_host_panel(self, lang, mf, sf, addresses, selected, addresses_done,
                             invite_code, ready_to_copy, copied, mouse_pos):
        """LAN play: selectable local IPv4/IPv6 addresses, port and invite code.

        Returns {'copy': Rect, 'rows': [Rect, ...]} (rows align with addresses).
        """
        sw, sh = self.screen.get_width(), self.screen.get_height()
        small = get_font(lang, 'regular', 13)
        width = min(420, sw - 32)
        left = sw // 2 - width // 2
        y = int(sh * 0.17)
        pick = small.render(_net_ui_text(lang, 'lan_pick'), True, (170, 195, 235))
        self.screen.blit(pick, (sw // 2 - pick.get_width() // 2, y))
        y += 24
        rows = []
        shown = addresses[:5]
        if not shown:
            key = 'lan_no_address' if addresses_done else None
            message = (_net_ui_text(lang, key) if key
                       else get_text(lang, 'local_ip_checking'))
            surface = render_fit(sf, message, (255, 205, 120) if key else (185, 205, 235),
                                 sw - 32, padding=0)
            self.screen.blit(surface, (sw // 2 - surface.get_width() // 2, y + 8))
            y += 44
        for index, address in enumerate(shown):
            family, scope = _classify_lan_address(address)
            rect = pygame.Rect(left, y, width, 38)
            is_selected = index == selected
            hovered = rect.collidepoint(mouse_pos)
            pygame.draw.rect(self.screen, (24, 66, 56) if is_selected else (24, 36, 72)
                             if not hovered else (32, 48, 92), rect, border_radius=8)
            pygame.draw.rect(self.screen, (90, 220, 150) if is_selected else (60, 80, 135),
                             rect, width=2 if is_selected else 1, border_radius=8)
            pygame.draw.circle(self.screen, (90, 220, 150) if is_selected else (90, 105, 140),
                               (rect.x + 18, rect.centery), 7, 0 if is_selected else 2)
            badge_colour = (120, 200, 255) if family == 'IPv6' else (200, 215, 140)
            badge = small.render(family, True, badge_colour)
            address_surface = render_fit(
                mf, streamer_mask(address), (230, 255, 235) if is_selected else (190, 205, 235),
                rect.width - 44 - badge.get_width() - 12, padding=0)
            self.screen.blit(address_surface,
                             (rect.x + 34, rect.centery - address_surface.get_height() // 2))
            self.screen.blit(badge, (rect.right - badge.get_width() - 12,
                                     rect.centery - badge.get_height() // 2))
            rows.append(rect)
            y += 44
        if shown:
            family, scope = _classify_lan_address(shown[min(selected, len(shown) - 1)])
            note = _net_ui_text(lang, 'lan_note_internet' if scope == 'internet' else 'lan_note_local')
            note_surface = render_fit(small, note, (150, 170, 205), width, padding=0)
            self.screen.blit(note_surface, (sw // 2 - note_surface.get_width() // 2, y))
            y += 22
        port_surface = render_fit(small, _net_ui_text(lang, 'lan_port', port=streamer_mask(self.PORT)),
                                  (190, 190, 190), sw - 28, padding=0)
        self.screen.blit(port_surface, (sw // 2 - port_surface.get_width() // 2, y))
        y += 22
        for line in _wrap_ui_text(small, _net_ui_text(lang, 'lan_hint'), width, 2):
            hint_surface = small.render(line, True, (150, 170, 205))
            self.screen.blit(hint_surface, (sw // 2 - hint_surface.get_width() // 2, y))
            y += 18
        y += 6
        invite_label = small.render(get_text(lang, 'secure_invite_label'), True, (255, 205, 120))
        self.screen.blit(invite_label, (sw // 2 - invite_label.get_width() // 2, y))
        y += 20
        invite_font = get_font(lang, 'regular', 13)
        for idx in range(3):
            line = invite_code[idx * 31:(idx + 1) * 31]
            if line:
                line = streamer_mask(line)
            line_surface = invite_font.render(line, True, (255, 235, 190))
            self.screen.blit(line_surface, (sw // 2 - line_surface.get_width() // 2, y + idx * 17))

        copy_rect = pygame.Rect(sw // 2 - 90, max(y + 60, int(sh * 0.74)), 180, 36)
        label = get_text(lang, 'invite_copied') if copied else get_text(lang, 'copy_invite_btn')
        self._mk_btn(copy_rect, label, (75, 85, 125) if ready_to_copy else (55, 58, 68),
                     mouse_pos, sf)
        return {'copy': copy_rect, 'rows': rows}

    def _pick_mode(self):
        """Choose Co-op or 1v1. Returns '1v1', 'coop', or None."""
        clock = pygame.time.Clock()
        mf = get_font(self.settings.language, 'bold',    26)
        sf = get_font(self.settings.language, 'regular', 16)
        while True:
            sw, sh = self.screen.get_width(), self.screen.get_height()
            self._draw_bg()
            lang = self.settings.language
            ts = mf.render(get_text(lang, 'net_choose_mode_title'), True, COLORS['white'])
            self.screen.blit(ts, (sw // 2 - ts.get_width() // 2, int(sh * 0.12)))

            d1 = sf.render(get_text(lang, 'net_coop_desc'), True, (160, 240, 160))
            d2 = sf.render(get_text(lang, 'net_1v1_desc'),       True, (255, 180, 180))
            self.screen.blit(d1, (sw // 2 - d1.get_width() // 2, int(sh * 0.32)))
            self.screen.blit(d2, (sw // 2 - d2.get_width() // 2, int(sh * 0.40)))

            bw, bh = 200, 50
            coop_r = pygame.Rect(sw // 2 - bw - 12, int(sh * 0.54), bw, bh)
            v1_r   = pygame.Rect(sw // 2 + 12,       int(sh * 0.54), bw, bh)
            back_r = pygame.Rect(sw // 2 - bw // 2,  int(sh * 0.70), bw, bh)
            mp = pygame.mouse.get_pos()
            self._mk_btn(coop_r, get_text(lang, 'coop_label'),  (25, 110, 65),  mp, mf)
            self._mk_btn(v1_r,   "1v1",    (130, 35, 35),  mp, mf)
            self._mk_btn(back_r, get_text(lang, 'back'),   (55,  65, 110), mp, mf)
            pygame.display.flip(); clock.tick(60)

            for event in pygame.event.get():
                if _legacy_nav_event(locals().get('self'), event, locals()):
                    continue
                if event.type == pygame.QUIT:               pygame.quit(); sys.exit()
                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_ESCAPE:        return None
                elif event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
                    if   coop_r.collidepoint(event.pos):    return 'coop'
                    elif v1_r.collidepoint(event.pos):      return '1v1'
                    elif back_r.collidepoint(event.pos):    return None
                elif event.type == pygame.VIDEORESIZE:
                    self.screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)

    def _pick_host_join(self):
        """Choose Host or Join. Returns 'host', 'join', or None."""
        clock = pygame.time.Clock()
        mf = get_font(self.settings.language, 'bold',    26)
        sf = get_font(self.settings.language, 'regular', 15)
        while True:
            sw, sh = self.screen.get_width(), self.screen.get_height()
            self._draw_bg()
            lang = self.settings.language
            ts = mf.render(get_text(lang, 'net_multiplayer_title'), True, COLORS['white'])
            self.screen.blit(ts, (sw // 2 - ts.get_width() // 2, int(sh * 0.10)))
            is_relay = getattr(self, 'transport', 'network') == 'network'
            self._draw_subtitle(lang, 'title_network' if is_relay else 'title_lan',
                                sw, int(sh * 0.18))

            for i, line in enumerate([
                _net_ui_text(lang, 'pick_host_network' if is_relay else 'pick_host_lan'),
                _net_ui_text(lang, 'pick_join_network' if is_relay else 'pick_join_lan'),
            ]):
                s = render_fit(sf, line, (200, 220, 255), sw - 32, padding=0)
                self.screen.blit(s, (sw // 2 - s.get_width() // 2, int(sh * 0.30) + i * 28))

            bw, bh = 200, 52
            host_r = pygame.Rect(sw // 2 - bw - 12, int(sh * 0.50), bw, bh)
            join_r = pygame.Rect(sw // 2 + 12,       int(sh * 0.50), bw, bh)
            back_r = pygame.Rect(sw // 2 - bw // 2,  int(sh * 0.66), bw, bh)
            mp = pygame.mouse.get_pos()
            self._mk_btn(host_r, get_text(lang, 'host_game_btn'),  (20, 100, 160), mp, mf)
            self._mk_btn(join_r, get_text(lang, 'join_game_btn'),  (100, 60, 20),  mp, mf)
            self._mk_btn(back_r, get_text(lang, 'back'),       (55,  65, 110), mp, mf)
            pygame.display.flip(); clock.tick(60)

            for event in pygame.event.get():
                if _legacy_nav_event(locals().get('self'), event, locals()):
                    continue
                if event.type == pygame.QUIT:               pygame.quit(); sys.exit()
                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_ESCAPE:        return None
                elif event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
                    if   host_r.collidepoint(event.pos):    return 'host'
                    elif join_r.collidepoint(event.pos):    return 'join'
                    elif back_r.collidepoint(event.pos):    return None
                elif event.type == pygame.VIDEORESIZE:
                    self.screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)

    def _guest_waiting_room(self, conn, mode, host_map, host_seed):
        """Guest of a 3-4 player room: wait on the roster until the host starts."""
        session = dict(self._pending_session or {})
        lang = self.settings.language
        link = _PeerLink(conn, False, None)      # no resume window while still in the lobby
        link._send_safe({'t': 'profile', 'name': self._host_display_name()})
        max_players = int(session.get('max_players', 4))
        names, you = [], None
        clock = pygame.time.Clock()
        mf = get_font(lang, 'bold', 22)
        sf = get_font(lang, 'regular', 15)
        try:
            while True:
                for _ in range(16):
                    try:
                        msg = link._recv_q.get_nowait()
                    except _queue_mod.Empty:
                        break
                    outcome = link._handle_link_message(msg)
                    if outcome == 'stop':
                        break
                    if outcome is None and msg.get('t') == 'lobby':
                        names, you = list(msg['names']), msg['you']
                    elif outcome is None and msg.get('t') == 'nstart':
                        link._session = session       # from now on a drop gets the resume window
                        link._next_ping = time.monotonic() + 0.5
                        handed = link
                        link = None
                        return (False, {'kind': 'n', 'link': handed, 'you': msg['you'],
                                        'count': msg['count'], 'names': list(msg['names'])},
                                mode, host_map, host_seed)
                link._service_link()
                if not link.connected:
                    return None
                sw, sh = self.screen.get_size()
                self._draw_bg()
                title = render_fit(mf, _net_ui_text(lang, 'room_guest_title'), COLORS['white'],
                                   sw - 32, padding=0)
                self.screen.blit(title, (sw // 2 - title.get_width() // 2, int(sh * 0.30)))
                self._draw_subtitle(lang, 'title_network' if _is_cloudflare_quick_hostname(
                    session.get('host', '')) else 'title_lan', sw, int(sh * 0.20))
                self._draw_roster_strip(lang, sf, names, max_players, int(sh * 0.45), you=you)
                cancel_r = pygame.Rect(sw // 2 - 100, int(sh * 0.75), 200, 40)
                self._mk_btn(cancel_r, get_text(lang, 'cancel'), (90, 30, 30),
                             pygame.mouse.get_pos(), mf)
                pygame.display.flip()
                clock.tick(60)
                for event in pygame.event.get():
                    if event.type == pygame.QUIT:
                        pygame.quit(); sys.exit()
                    elif event.type == pygame.KEYDOWN and event.key == pygame.K_ESCAPE:
                        return None
                    elif event.type == pygame.MOUSEBUTTONDOWN and event.button == 1 \
                            and cancel_r.collidepoint(event.pos):
                        return None
                    elif event.type == pygame.VIDEORESIZE:
                        self.screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)
        finally:
            if link is not None:
                # leaving the room on purpose: say goodbye so the host frees the slot
                if link.connected:
                    link._send_safe({'t': 'bye'})
                    deadline = time.monotonic() + 0.3
                    while time.monotonic() < deadline and link._send_q.unfinished_tasks > 0:
                        time.sleep(0.01)
                link._stop_event.set()
                link.connected = False
                link._stop_io()

    def _host_display_name(self):
        return _clean_player_name(getattr(self, 'player_name', None), 'Host')

    def _broadcast_room(self, roster, max_players):
        """Tell every waiting guest who is in the room (host first, then join order)."""
        _lobby_broadcast_room(roster, max_players, self._host_display_name())

    def _service_room(self, roster, max_players):
        """Keep waiting guests alive; drop the ones that left or went silent."""
        _lobby_service_room(roster, max_players, self._host_display_name())

    def _draw_roster_strip(self, lang, sf, names, max_players, y, you=None):
        """Player cards, host first: joined players and open slots."""
        sw = self.screen.get_width()
        card_w = min(150, (sw - 40) // 4 - 8)
        total = max_players * (card_w + 8) - 8
        x = sw // 2 - total // 2
        names = list(names)
        for index in range(max_players):
            rect = pygame.Rect(x + index * (card_w + 8), y, card_w, 44)
            filled = index < len(names)
            colour = LocalMultiplayerNGame.PLAYER_COLORS[index][0]
            pygame.draw.rect(self.screen, (28, 40, 78) if filled else (22, 28, 52), rect, border_radius=8)
            pygame.draw.rect(self.screen, colour if filled else (70, 80, 115), rect,
                             width=2 if filled else 1, border_radius=8)
            label = names[index] if filled else _net_ui_text(lang, 'slot_waiting')
            status = ''
            if filled:
                status = _net_ui_text(lang, 'slot_host' if index == 0 else 'slot_connected')
                if you is not None and index == you:
                    status = _net_ui_text(lang, 'room_you')
            name_surface = render_fit(sf, label, (235, 240, 255) if filled else (110, 125, 160),
                                      rect.width - 14, padding=0)
            self.screen.blit(name_surface, (rect.x + 8, rect.y + 6))
            if status:
                small = get_font(lang, 'regular', 12)
                status_surface = render_fit(small, status, colour, rect.width - 14, padding=0)
                self.screen.blit(status_surface, (rect.x + 8, rect.y + 25))

    def _pick_player_count(self):
        """Room size for the host: 2 keeps the classic duel, 3-4 opens a room."""
        language = self.settings.language
        chosen = {'value': None}
        menu = None
        def pick(value):
            chosen['value'] = value
            menu._go_back()
        entries = [(f'players_{n}', (lambda n=n: _net_ui_text(language, 'players_option', n=n)),
                    COLORS['light_blue'] if n == 2 else COLORS['purple'], (lambda n=n: pick(n)))
                   for n in (2, 3, 4)]
        menu = _SimpleMenuScreen(self.settings, self.screen,
                                 title_fn=lambda: _net_ui_text(language, 'pick_players_title'),
                                 entries=entries)
        menu.runtime = getattr(self, 'runtime', None)
        menu.run()
        return chosen['value']

    def _host_flow(self, mode, seed=None, max_players=2, lobby=None):
        """Host a secure multiplayer session. The waiting logic lives in
        HostLobby, so it keeps running when this screen is closed with Esc or
        'keep open in background'; Cancel stops it. Passing `lobby` re-opens a
        lobby that is already listening."""
        clock = pygame.time.Clock()
        mf = get_font(self.settings.language, 'bold',    22)
        sf = get_font(self.settings.language, 'regular', 15)
        lang = self.settings.language

        if lobby is None:
            lobby = HostLobby(self.PORT, mode, max_players, seed=seed,
                              use_tunnel=getattr(self, 'transport', 'network') == 'network',
                              host_name_fn=self._host_display_name)
            try:
                lobby.prepare()
            except HostLobbyError as exc:
                self._show_error(str(exc.cause))
                return None
            # Host picks the board layout up front: it is sent to the client in
            # the handshake, so both sides always end up with the exact same map.
            picked_map = MapPickerScreen(self.settings, self.screen).run()
            if picked_map == NAV_BACK_LEVEL:
                lobby.stop()             # Back: nothing is hosted, return to the previous screen
                return None
            lobby.chosen_map = picked_map
            try:
                lobby.start()
            except HostLobbyError as exc:
                self._show_error(get_text(lang, 'cannot_start_server').format(error=exc.cause))
                return None
        lobby.host_name_fn = self._host_display_name
        lobby.attach_runtime(getattr(self, 'runtime', None))
        room_mode = lobby.room_mode
        max_players = lobby.max_players

        dots = 0
        dot_timer = 0
        invite_copied = False
        seen_info_version = lobby.info_version
        retry_r = None
        lan_row_rects = []
        lobby.ui_attached += 1
        try:
            while True:
                if lobby.info_version != seen_info_version:
                    seen_info_version = lobby.info_version
                    invite_copied = False
                if lobby.closed:
                    return None
                if lobby.guest_ready() and not room_mode:
                    result, tunnel, pending = lobby.take_match()
                    self._pending_tunnel_session = tunnel
                    self._pending_session = pending
                    return result
                local_ips, local_ip_done = lobby.local_ips, lobby.local_ip_done
                public_ip, public_ip_done = lobby.public_ip, lobby.public_ip_done
                tunnel_session = lobby.tunnel_session
                funnel_state, funnel_host, funnel_port, _funnel_detail = lobby.funnel
                connection_info = lobby.connection_info
                roster = lobby.roster
                sw, sh = self.screen.get_width(), self.screen.get_height()
                self._draw_bg()

                ts = mf.render(get_text(lang, 'hosting_waiting'), True, COLORS['white'])
                self.screen.blit(ts, (sw // 2 - ts.get_width() // 2, int(sh * 0.08)))

                self._draw_subtitle(lang, 'title_network' if tunnel_session is not None
                                    else 'title_lan', sw, int(sh * 0.125))
                relay_pending = (tunnel_session is not None and funnel_state not in (
                    'ready', 'unavailable', 'stopped', 'not_installed'))
                connection_info_ready = _network_connection_info_ready(
                    local_ip_done=local_ip_done, local_ips=local_ips,
                    public_ip=public_ip,
                    relay_host=funnel_host if funnel_state == 'ready' else None,
                    relay_port=funnel_port if funnel_state == 'ready' else None,
                    relay_pending=relay_pending)
                mouse_position = pygame.mouse.get_pos()
                if tunnel_session is not None:
                    panel = self._draw_relay_host_panel(
                        lang, mf, sf, funnel_state, _funnel_detail, funnel_host,
                        public_ip, public_ip_done, connection_info_ready, invite_copied,
                        mouse_position)
                    retry_r = panel['retry']
                    lan_row_rects = []
                else:
                    panel = self._draw_lan_host_panel(
                        lang, mf, sf, local_ips, lobby.lan_selected, local_ip_done,
                        lobby.invite_code, connection_info_ready, invite_copied, mouse_position)
                    retry_r = None
                    lan_row_rects = panel['rows']
                copy_r = panel['copy']

                dot_timer += 1
                if dot_timer > 18: dots = (dots + 1) % 4; dot_timer = 0
                waiting_y = max(int(sh * 0.81), copy_r.bottom + 12)
                mp = pygame.mouse.get_pos()
                bg_label = _lobby_label(lang, 'background')
                start_r = None
                if room_mode:
                    self._draw_roster_strip(
                        lang, sf, [self._host_display_name()] + [entry['name'] for entry in roster],
                        max_players, waiting_y - 8)
                    button_y = max(int(sh * 0.905), waiting_y + 50)
                    start_r = pygame.Rect(sw // 2 - 300, button_y, 190, 40)
                    bg_r = pygame.Rect(sw // 2 - 95, button_y, 190, 40)
                    cancel_r = pygame.Rect(sw // 2 + 110, button_y, 190, 40)
                    self._mk_btn(start_r, _net_ui_text(lang, 'start_match'),
                                 (30, 110, 70) if roster else (55, 58, 68), mp, sf)
                else:
                    ws = sf.render(get_text(lang, 'waiting_connection') + "." * dots, True, (150, 175, 220))
                    self.screen.blit(ws, (sw // 2 - ws.get_width() // 2, waiting_y))
                    button_y = max(int(sh * 0.90), waiting_y + 30)
                    bg_r = pygame.Rect(sw // 2 - 205, button_y, 200, 40)
                    cancel_r = pygame.Rect(sw // 2 + 5, button_y, 200, 40)
                self._mk_btn(bg_r, bg_label, (45, 70, 120), mp, sf)
                self._mk_btn(cancel_r, get_text(lang, 'cancel'), (90, 30, 30), mp, mf)
                # flip() also runs the overlay layer, which polls the lobby.
                pygame.display.flip(); clock.tick(60)

                for event in pygame.event.get():
                    if _legacy_nav_event(locals().get('self'), event, locals()):
                        continue
                    if event.type == pygame.QUIT:           pygame.quit(); sys.exit()
                    elif event.type == pygame.KEYDOWN:
                        if event.key == pygame.K_ESCAPE:
                            lobby.keep_background = True      # leave, but keep listening
                            return None
                    elif event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
                        if cancel_r.collidepoint(event.pos):
                            return None                      # Cancel: the lobby is stopped below
                        elif bg_r.collidepoint(event.pos):
                            lobby.keep_background = True
                            return None
                        elif room_mode and roster and start_r is not None and start_r.collidepoint(event.pos):
                            result, tunnel, pending = lobby.take_room()
                            self._pending_tunnel_session = tunnel
                            self._pending_session = pending
                            return result
                        elif retry_r is not None and retry_r.collidepoint(event.pos):
                            lobby.restart_tunnel()           # the old relay is stopped first
                            invite_copied = False
                        elif any(row.collidepoint(event.pos) for row in lan_row_rects):
                            lobby.lan_selected = next(i for i, row in enumerate(lan_row_rects)
                                                      if row.collidepoint(event.pos))
                        elif copy_r.collidepoint(event.pos):
                            if connection_info_ready:
                                invite_copied = _copy_to_clipboard(connection_info)
                            if invite_copied:
                                sgf_log.info('Secure multiplayer connection URI copied to clipboard')
                    elif event.type == pygame.VIDEORESIZE:
                        self.screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)
        finally:
            lobby.ui_attached -= 1
            if not lobby.keep_background:
                lobby.stop()           # backing out (or an error) stops the relay and the listeners
            lobby.keep_background = False

    def _join_flow(self, mode, seed=None):
        """IP-entry + connect UI. Host remains authoritative for seed/map."""
        clock = pygame.time.Clock()
        mf  = get_font(self.settings.language, 'bold',    22)
        sf  = get_font(self.settings.language, 'regular', 15)
        ip_str  = ''
        invite_str = ''
        link_str = ''
        join_port = self.PORT
        is_relay = getattr(self, 'transport', 'network') == 'network'
        self._expected_mode = mode
        status  = ''
        status_col = (200, 200, 200)
        active_field = 'ip'
        connect_results = _queue_mod.Queue(maxsize=1)
        connect_pending = False
        connect_cancel = None

        def _begin_connect():
            nonlocal connect_pending, connect_cancel, status, status_col
            nonlocal ip_str, invite_str, join_port
            if connect_pending:
                return
            if is_relay:
                try:
                    parsed_link = _parse_network_connection_info(link_str)
                except ValueError:
                    parsed_link = None
                if not parsed_link:
                    status = _net_ui_text(lang, 'link_invalid')
                    status_col = (255, 185, 80)
                    return
                ip_str, join_port, invite_str = parsed_link
            ip = ip_str.strip()
            if not ip:
                status = get_text(lang, 'please_enter_ip')
                status_col = (255, 185, 80)
                return
            if not invite_str:
                status = get_text(lang, 'invite_required')
                status_col = (255, 185, 80)
                return
            cancel_event = threading.Event()
            connect_cancel = cancel_event
            connect_pending = True
            ip, target_port = _split_join_endpoint(ip, join_port, self.PORT)
            status = get_text(lang, 'connecting_to').format(ip=ip, port=target_port)
            status_col = (200, 225, 255)

            def _connect_worker():
                connection = self._do_connect(ip, invite_str, seed, target_port,
                                              cancel_event=cancel_event)
                if cancel_event.is_set():
                    if connection:
                        try: connection.close()
                        except OSError: pass
                    return
                result = (connection, self._pending_map, self._pending_seed)
                try:
                    connect_results.put_nowait(result)
                except _queue_mod.Full:
                    if connection:
                        try: connection.close()
                        except OSError: pass

            threading.Thread(target=_connect_worker, name='SGF-secure-connect', daemon=True).start()

        lang = self.settings.language
        # The join screen is always typing into a field. Naming this local
        # ``*_input_active`` tells the shared keyboard navigator to leave letters
        # (WASD), Space and Enter to the fields instead of treating them as menu
        # navigation, so typed addresses and Enter-to-connect work.
        text_input_active = True
        while True:
            try:
                connection, host_map, host_seed = connect_results.get_nowait()
                connect_pending = False
                if connection and (self._pending_session or {}).get('max_players', 2) > 2:
                    room_result = self._guest_waiting_room(connection, mode, host_map, host_seed)
                    if room_result:
                        return room_result
                    status = _net_ui_text(lang, 'host_left_room')
                    status_col = (255, 185, 80)
                    raise _queue_mod.Empty
                if connection:
                    return (False, connection, mode, host_map, host_seed)
                _shown_host, _shown_port = _split_join_endpoint(ip_str, join_port, self.PORT)
                status = get_text(lang, 'could_not_connect').format(
                    ip=streamer_mask(_shown_host), port=streamer_mask(_shown_port))
                # Short language-neutral stage code (dns, edge, relay 530, pin,
                # auth, host) so a failed relay join can be diagnosed.
                failure_stage = str(getattr(self, '_last_connect_stage', '') or '')
                if failure_stage and _is_cloudflare_quick_hostname(_shown_host):
                    status = f'{status} [{failure_stage}]'
                status_col = (255, 100, 100)
            except _queue_mod.Empty:
                pass
            sw, sh = self.screen.get_width(), self.screen.get_height()
            self._draw_bg()

            ts = mf.render(get_text(lang, 'join_game_title'), True, COLORS['white'])
            self.screen.blit(ts, (sw // 2 - ts.get_width() // 2, int(sh * 0.09)))

            self._draw_subtitle(lang, 'title_network' if is_relay else 'title_lan',
                                sw, int(sh * 0.15))
            if is_relay:
                field_w = min(520, sw - 32)
                label_surface = sf.render(_net_ui_text(lang, 'link_label'), True, (200, 220, 255))
                self.screen.blit(label_surface, (sw // 2 - field_w // 2, int(sh * 0.24)))
                link_rect = pygame.Rect(sw // 2 - field_w // 2, int(sh * 0.30), field_w, 48)
                pygame.draw.rect(self.screen, (22, 33, 68), link_rect, border_radius=6)
                pygame.draw.rect(self.screen, (100, 160, 255), link_rect, width=2, border_radius=6)
                if link_str:
                    shown_link = (link_str if len(link_str) <= 44 else link_str[:30] + '…' + link_str[-12:])
                    shown_link = streamer_mask(shown_link)
                    link_surface = sf.render(shown_link, True, COLORS['white'])
                else:
                    link_surface = sf.render(_net_ui_text(lang, 'link_placeholder'), True, (75, 100, 145))
                self.screen.blit(link_surface, (link_rect.x + 12, link_rect.centery - link_surface.get_height() // 2))
                ip_rect = invite_rect = link_rect
                try:
                    link_info = _parse_network_connection_info(link_str) if link_str else None
                except ValueError:
                    link_info = None
                if link_info:
                    relay_line = render_fit(
                        sf, _net_ui_text(lang, 'link_relay', host=streamer_mask(link_info[0])),
                        (120, 245, 170), field_w, padding=0)
                    self.screen.blit(relay_line, (sw // 2 - relay_line.get_width() // 2, int(sh * 0.43)))
                elif link_str:
                    invalid_line = render_fit(sf, _net_ui_text(lang, 'link_invalid'),
                                              (255, 185, 80), field_w, padding=0)
                    self.screen.blit(invalid_line, (sw // 2 - invalid_line.get_width() // 2, int(sh * 0.43)))
            else:
                lbl = sf.render(get_text(lang, 'host_ip_label'), True, (200, 220, 255))
                self.screen.blit(lbl, (sw // 2 - 185, int(sh * 0.20)))

                ip_rect = pygame.Rect(sw // 2 - 185, int(sh * 0.26), 370, 44)
                pygame.draw.rect(self.screen, (22, 33, 68), ip_rect, border_radius=6)
                border_c = (100, 160, 255) if active_field == 'ip' else (55, 75, 130)
                pygame.draw.rect(self.screen, border_c, ip_rect, width=2, border_radius=6)
                disp = streamer_mask(ip_str) if ip_str else get_text(lang, 'ip_placeholder')
                dc   = COLORS['white'] if ip_str else (75, 100, 145)
                ds   = sf.render(disp, True, dc)
                self.screen.blit(ds, (ip_rect.x + 12, ip_rect.centery - ds.get_height() // 2))

                invite_label = sf.render(get_text(lang, 'secure_invite_hint'), True, (200, 220, 255))
                self.screen.blit(invite_label, (sw // 2 - 185, int(sh * 0.38)))
                invite_rect = pygame.Rect(sw // 2 - 185, int(sh * 0.44), 370, 44)
                pygame.draw.rect(self.screen, (22, 33, 68), invite_rect, border_radius=6)
                border_c = (100, 160, 255) if active_field == 'invite' else (55, 75, 130)
                pygame.draw.rect(self.screen, border_c, invite_rect, width=2, border_radius=6)
                invite_display = streamer_mask(invite_str) if invite_str else 'SGF1-…'
                if len(invite_display) > 42:
                    invite_display = invite_display[:39] + '...'
                ds = sf.render(invite_display, True, COLORS['white'] if invite_str else (75, 100, 145))
                self.screen.blit(ds, (invite_rect.x + 12, invite_rect.centery - ds.get_height() // 2))

                if _is_cloudflare_quick_hostname(ip_str):
                    cloudflare_port_text = {
                        'pt_PT': f'Porta pública: {join_port} · o túnel encaminha para a porta local {self.PORT}',
                        'pt_BR': f'Porta pública: {join_port} · o túnel encaminha para a porta local {self.PORT}',
                        'es': f'Puerto público: {join_port} · el túnel conecta al puerto local {self.PORT}',
                        'fr': f'Port public : {join_port} · le tunnel rejoint le port local {self.PORT}',
                        'de': f'Öffentlicher Port: {join_port} · Tunnel verbindet lokalen Port {self.PORT}',
                    }.get(lang, f'Public port: {join_port} · tunnel forwards to local port {self.PORT}')
                    port_surface = render_fit(sf, cloudflare_port_text, (150, 170, 200), 370)
                else:
                    port_surface = sf.render(
                        get_text(lang, 'port_label_both').format(port=join_port),
                        True, (150, 170, 200))
                self.screen.blit(port_surface, (sw // 2 - port_surface.get_width() // 2,
                                                int(sh * 0.55)))
                lan_hint_surface = render_fit(
                    get_font(lang, 'regular', 13), _net_ui_text(lang, 'lan_join_hint'),
                    (130, 150, 190), sw - 32, padding=0)
                self.screen.blit(lan_hint_surface, (sw // 2 - lan_hint_surface.get_width() // 2,
                                                    int(sh * 0.585)))

            bw, bh = 200, 50
            conn_r = pygame.Rect(sw // 2 - bw - 10, int(sh * 0.65), bw, bh)
            back_r = pygame.Rect(sw // 2 + 10,       int(sh * 0.65), bw, bh)
            mp = pygame.mouse.get_pos()
            self._mk_btn(conn_r, get_text(lang, 'connect_btn'), (20, 100, 160), mp, mf)
            self._mk_btn(back_r, get_text(lang, 'back'),    (55, 65, 110),  mp, mf)

            if status:
                ss = sf.render(status, True, status_col)
                self.screen.blit(ss, (sw // 2 - ss.get_width() // 2, int(sh * 0.77)))

            hint = render_fit(sf, _net_ui_text(lang, 'join_network_hint') if is_relay
                              else get_text(lang, 'type_ip_hint'),
                              (80, 108, 160), sw - 32, padding=0)
            self.screen.blit(hint, (sw // 2 - hint.get_width() // 2, int(sh * 0.89)))

            pygame.display.flip(); clock.tick(60)

            for event in pygame.event.get():
                if (not is_relay and event.type == pygame.KEYDOWN and event.key == pygame.K_TAB):
                    active_field = 'invite' if active_field == 'ip' else 'ip'
                    continue
                if _legacy_nav_event(locals().get('self'), event, locals()):
                    continue
                if event.type == pygame.QUIT:
                    if connect_cancel:
                        connect_cancel.set()
                    pygame.quit(); sys.exit()
                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_ESCAPE:
                        if connect_cancel:
                            connect_cancel.set()
                        return None
                    elif event.key == pygame.K_TAB:
                        if not is_relay:
                            active_field = 'invite' if active_field == 'ip' else 'ip'
                    elif event.key == pygame.K_v and (event.mod & pygame.KMOD_CTRL) and is_relay:
                        try:
                            link_str = ''.join(str(_read_from_clipboard() or '').split())[:400]
                        except Exception:
                            pass
                        status = ''
                    elif event.key == pygame.K_v and (event.mod & pygame.KMOD_CTRL):
                        try:
                            pasted = _read_from_clipboard()
                            connection_info = _parse_network_connection_info(pasted)
                            if connection_info:
                                ip_str, join_port, invite_str = connection_info
                                active_field = 'invite'
                            else:
                                invite_candidate = ''.join(ch for ch in pasted if ch.isascii() and (ch.isalnum() or ch in '-_'))[:100]
                                if active_field == 'invite' and invite_candidate.startswith('SGF1-'):
                                    invite_str = invite_candidate
                                elif active_field == 'ip':
                                    ip_str = pasted.strip()[:255]
                        except Exception:
                            pass
                        status = ''
                    elif event.key == pygame.K_BACKSPACE:
                        if is_relay:
                            link_str = link_str[:-1]
                        elif active_field == 'ip':
                            ip_str = ip_str[:-1]
                        else:
                            invite_str = invite_str[:-1]
                        status = ''
                    elif event.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
                        _begin_connect()
                    elif is_relay and event.unicode and event.unicode.isascii() and (event.unicode.isalnum() or event.unicode in '-_.:/[]%') and len(link_str) < 400:
                        link_str += event.unicode; status = ''
                    elif active_field == 'ip' and event.unicode and event.unicode.isascii() and (event.unicode.isalnum() or event.unicode in '.:-%_[]') and len(ip_str) < 255:
                        ip_str += event.unicode; status = ''
                    elif active_field == 'invite' and event.unicode and event.unicode.isascii() and (event.unicode.isalnum() or event.unicode in '-_') and len(invite_str) < 100:
                        invite_str += event.unicode; status = ''
                elif event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
                    if ip_rect.collidepoint(event.pos):
                        active_field = 'ip'
                    elif invite_rect.collidepoint(event.pos):
                        active_field = 'invite'
                    if conn_r.collidepoint(event.pos) and is_relay:
                        _begin_connect()
                    elif conn_r.collidepoint(event.pos):
                        ip = ip_str.strip()
                        if not ip:
                            status = get_text(lang, 'please_enter_ip')
                            status_col = (255, 185, 80)
                        elif not invite_str:
                            status = get_text(lang, 'invite_required')
                            status_col = (255, 185, 80)
                        else:
                            _begin_connect()
                    elif back_r.collidepoint(event.pos):
                        if connect_cancel:
                            connect_cancel.set()
                        return None
                elif event.type == pygame.VIDEORESIZE:
                    self.screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)
                    mf = get_font(self.settings.language, 'bold',    22)
                    sf = get_font(self.settings.language, 'regular', 15)

    def _open_relay_stream(self, ip, port, invite_code, cancel_event=None, budget=30.0):
        """Open the pinned TLS stream through a Cloudflare relay (see the shared helper)."""
        def note_stage(stage):
            self._last_connect_stage = stage
        stream, _token = _open_secure_peer_stream(
            ip, port, invite_code, cancel_event, budget, note_stage)
        return stream

    def _do_connect(self, ip, invite_code, requested_seed=None, port=None, cancel_event=None):
        """Connect only when TLS identity pinning and one-time auth succeed."""
        if not ip or not invite_code:
            return None
        self._pending_map = None
        self._pending_seed = None
        self._pending_session = None
        self._last_connect_stage = ''
        s = None
        try:
            target_port = int(port or self.PORT)
            if _is_cloudflare_quick_hostname(ip):
                if not 1 <= target_port <= 65535:
                    raise ValueError('Cloudflare invitation contains an invalid public port')
                s = self._open_relay_stream(ip, target_port, invite_code, cancel_event)
                join_token = s.join_token
            else:
                s = _socket_mod.create_connection((ip, target_port), timeout=6.0)
                s.setsockopt(_socket_mod.IPPROTO_TCP, _socket_mod.TCP_NODELAY, 1)
                s, join_token = _wrap_and_pin_network_client(s, invite_code)
            s.settimeout(6)
            if _is_cloudflare_quick_hostname(ip):
                self._last_connect_stage = 'auth'
            _net_send(s, {'t': 'secure_auth', 'token': join_token.hex()})
            msg = _net_recv(s)
            if msg and msg.get('t') == 'hello':
                if set(msg) != {'t', 'v', 'mode', 'seed', 'map', 'map_hash', 'resume',
                                'max_players'}:
                    raise _NetProtocolError('invalid host handshake fields')
                room_size = msg.get('max_players')
                if type(room_size) is not int or not 2 <= room_size <= 4:
                    raise _NetProtocolError('host announced an invalid room size')
                resume_hex = msg.get('resume')
                if (not isinstance(resume_hex, str) or len(resume_hex) != 64
                        or any(ch not in '0123456789abcdef' for ch in resume_hex)):
                    raise _NetProtocolError('host supplied an invalid resume credential')
                incoming_map = msg.get('map')
                if not _validate_net_map(incoming_map):
                    raise _NetProtocolError('host supplied an invalid map')
                expected_hash = msg.get('map_hash')
                actual_hash = _map_fingerprint(incoming_map)
                if expected_hash != actual_hash:
                    raise _NetProtocolError('map fingerprint mismatch')
                host_mode = msg.get('mode')
                if host_mode not in ('1v1', 'coop') or host_mode != getattr(self, '_expected_mode', host_mode):
                    raise _NetProtocolError('host mode mismatch')
                host_seed = msg.get('seed')
                if not isinstance(host_seed, str) or not host_seed.strip() or len(host_seed) > 128:
                    raise _NetProtocolError('host did not provide a deterministic seed')
                self._pending_map = incoming_map
                self._pending_seed = host_seed
                self._pending_session = {
                    'host': ip, 'port': target_port, 'invite': invite_code,
                    'resume': resume_hex, 'mode': host_mode, 'max_players': room_size}
                if requested_seed and str(requested_seed).strip() and str(requested_seed).strip() != host_seed:
                    print('[network] joiner seed differs; host seed is authoritative')
                _net_send(s, {'t': 'hello_ack', 'map_hash': actual_hash, 'seed': host_seed})
                s.settimeout(15.0)
                self._last_connect_stage = ''
                return s
            s.close()
        except _NetProtocolError as _e:
            detail = re.sub(r'\b(?:\d{1,3}\.){3}\d{1,3}\b', '[address]', str(_e))
            detail = re.sub(r'\b[a-z0-9-]+\.trycloudflare\.com\b', '[relay]', detail, flags=re.IGNORECASE)
            sgf_log.warning('Secure multiplayer handshake rejected: %s', detail[:180])
            try: s.close()
            except Exception: pass
        except OSError as exc:
            # Connection dropped/reset mid-handshake — a normal thing to
            # happen while waiting for a peer to join over a LAN.
            detail = re.sub(r'\b(?:\d{1,3}\.){3}\d{1,3}\b', '[address]', str(exc))
            detail = re.sub(r'\b[a-z0-9-]+\.trycloudflare\.com\b', '[relay]', detail, flags=re.IGNORECASE)
            sgf_log.warning('Secure multiplayer connection failed (%s): %s',
                            type(exc).__name__, detail[:180])
        except Exception as _e:
            print(f"[network] unexpected error during connect handshake: {_e}")
            try: s.close()
            except Exception: pass
        return None

    def _show_error(self, text):
        clock = pygame.time.Clock()
        mf = get_font(self.settings.language, 'bold',    22)
        sf = get_font(self.settings.language, 'regular', 17)
        sw, sh = self.screen.get_width(), self.screen.get_height()
        self._draw_bg()
        es = mf.render(text, True, (255, 100, 100))
        self.screen.blit(es, (sw // 2 - es.get_width() // 2, sh // 2 - 30))
        ks = sf.render(get_text(self.settings.language, 'press_any_key'), True, (180, 180, 210))
        self.screen.blit(ks, (sw // 2 - ks.get_width() // 2, sh // 2 + 25))
        _legacy_nav_draw(locals().get('self'))
        pygame.display.flip()
        waiting = True
        while waiting:
            for e in pygame.event.get():
                if e.type in (pygame.KEYDOWN, pygame.MOUSEBUTTONDOWN):
                    waiting = False
            clock.tick(30)


def _draw_link_overlay(screen, settings, link, waiting_name=None):
    """Connection-state screen for any session type (``link`` supplies the state)."""
    sw, sh = screen.get_width(), screen.get_height()
    background_color, _board_color, _grid_color = _map_theme_colors(settings)
    screen.fill(background_color)
    ov = pygame.Surface((sw, sh), pygame.SRCALPHA)
    ov.fill((0, 0, 0, 200)); screen.blit(ov, (0, 0))
    lang = settings.language
    bf = get_font(lang, 'bold', 38)
    sf = get_font(lang, 'regular', 20)
    state = link.link_state()
    seconds = link.reconnect_seconds_left()
    if state == 'waiting':
        title = _net_ui_text(lang, 'waiting_player_title')
        message = _net_ui_text(lang, 'waiting_player_msg', seconds=seconds)
        title_colour = (255, 205, 110)
    elif state == 'reconnecting':
        title = _net_ui_text(lang, 'reconnecting_title')
        message = _net_ui_text(lang, 'reconnecting_msg', seconds=seconds)
        title_colour = (255, 205, 110)
    elif state == 'left':
        title = _net_ui_text(lang, 'peer_left_title')
        message = _net_ui_text(lang, 'peer_left_msg')
        title_colour = (255, 150, 120)
    else:
        title = get_text(lang, 'connection_lost_title')
        reason = link.disconnect_reason
        if reason == 'protocol_error':
            message = _net_ui_text(lang, 'lost_msg_protocol')
        elif reason == 'stalled':
            message = _net_ui_text(lang, 'lost_msg_stalled')
        elif link._session is not None and reason in link.RECOVERABLE_REASONS:
            message = _net_ui_text(lang, 'lost_msg_timeout')
        else:
            message = get_text(lang, 'connection_lost_msg')
        title_colour = (255, 100, 100)
    if waiting_name:
        title = f"{waiting_name}: {title}" if state == 'waiting' else title
    hint = (_net_ui_text(lang, 'leave_hint') if state in ('waiting', 'reconnecting')
            else get_text(lang, 'connection_lost_esc'))
    for text, font, colour, y in (
            (title, bf, title_colour, sh // 2 - 80),
            (message, sf, (200, 200, 200), sh // 2 - 10),
            (hint, sf, (180, 180, 210), sh // 2 + 45)):
        surface = render_fit(font, text, colour, sw - 32, padding=0)
        screen.blit(surface, (sw // 2 - surface.get_width() // 2, y))


class _NetworkLinkMixin:
    """One secure peer connection: I/O threads, heartbeat, stall detection and resume.

    Shared by the two-player NetworkGame and by the per-guest links of the
    multi-player session, so reconnection logic exists exactly once.
    """

    HEARTBEAT_INTERVAL = 1.5      # guest -> host ping period (seconds)
    STALL_WARN_SECONDS = 3.0      # silence before the badge says "unstable"
    STALL_LOST_SECONDS = 12.0     # silence before the link is declared dead
    RECONNECT_WINDOW = 30.0       # how long both sides try to resume a match
    # Drops that can be a network hiccup. Protocol errors and rate-limit
    # violations mean the peer misbehaved, so those never trigger a resume.
    RECOVERABLE_REASONS = frozenset({
        'peer_disconnect', 'socket_error', 'send_socket_error', 'send_backpressure', 'stalled'})

    def _init_link(self, conn, is_host, session):
        """Set up the connection state shared by every session type and start its I/O.

        ``conn`` may be a _LobbyGuestLink: a guest that was already connected (and
        kept alive) while the host sat in a menu. Its running I/O is then taken
        over instead of starting a second reader on the same socket.
        """
        adopt = conn if isinstance(conn, _LobbyGuestLink) else None
        if adopt is not None:
            conn = adopt.conn
        self.is_host = is_host
        self.conn = conn
        self.connected = True
        self.disconnect_reason = None
        self._stop_event = threading.Event()
        self._recv_q   = _queue_mod.Queue(maxsize=256)
        self._send_q   = _queue_mod.Queue(maxsize=32)

        # Reconnection / liveness state. ``session`` carries what is needed to
        # resume: the host keeps its listeners and TLS context, the guest the
        # endpoint, invite and resume credential.
        self._session = session if isinstance(session, dict) else None
        self._conn_gen = 0
        self._conn_stop = threading.Event()
        self._recv_t = None
        self._send_t = None
        self._last_rx = time.monotonic()
        self._next_ping = time.monotonic() + 1.0
        self._ping_seq = 0
        self._ping_sent = {}
        self.latency_ms = None
        self.peer_left = False
        self._reconnect_state = None      # None | 'host_wait' | 'client_dial'
        self._reconnect_exhausted = False  # window used up: the link is finally lost
        self._reconnect_deadline = 0.0
        self._resume_results = _queue_mod.Queue()
        self._resume_pending = False
        self._dial_cancel = threading.Event()
        self._next_listener_poll = 0.0
        if adopt is not None:
            self._take_over_io(adopt)
        else:
            self._start_io(conn)

    def _take_over_io(self, link):
        """Continue a lobby link's connection without restarting its threads.

        The reader/writer threads keep running (restarting them could split a
        frame), so the queues and events they use are shared, and the link
        forwards what the threads write (connected, reason, last receive time)
        to this object from now on. The resume state moves too, so a guest that
        was mid-reconnect when the match opened still gets back in.
        """
        self.conn = link.conn
        self._stop_event = link._stop_event
        self._conn_stop = link._conn_stop
        self._conn_gen = link._conn_gen
        self._recv_q, self._send_q = link._recv_q, link._send_q
        self._recv_t, self._send_t = link._recv_t, link._send_t
        self._resume_results = link._resume_results
        self._resume_pending = link._resume_pending
        self._dial_cancel = link._dial_cancel
        self._reconnect_state = link._reconnect_state
        self._reconnect_deadline = link._reconnect_deadline
        self._reconnect_exhausted = link._reconnect_exhausted
        self.connected = link.connected
        self.disconnect_reason = link.disconnect_reason
        self.peer_left = link.peer_left
        self.latency_ms = link.latency_ms
        self._last_rx = link._last_rx
        link._owner = self

    def _queue_net_event(self, msg):
        if isinstance(msg, dict) and msg.get('t') == 'state':
            with self._recv_q.mutex:
                for idx in range(len(self._recv_q.queue) - 1, -1, -1):
                    queued = self._recv_q.queue[idx]
                    if isinstance(queued, dict) and queued.get('t') == 'state':
                        self._recv_q.queue[idx] = msg
                        self._recv_q.not_empty.notify()
                        return
        try:
            self._recv_q.put_nowait(msg)
        except _queue_mod.Full:
            # State frames are disposable; preserve control/disconnect messages.
            if isinstance(msg, dict) and msg.get('t') == 'state':
                return
            try:
                self._recv_q.get_nowait()
            except _queue_mod.Empty:
                pass
            try:
                self._recv_q.put_nowait(msg)
            except _queue_mod.Full:
                pass

    def _start_io(self, conn):
        """Attach a (new) connection and start its reader/writer threads."""
        self._conn_gen += 1
        gen = self._conn_gen
        stop = threading.Event()
        self._conn_stop = stop
        self.conn = conn
        self._last_rx = time.monotonic()
        self._recv_t = threading.Thread(target=self._recv_loop, args=(conn, gen, stop), daemon=True)
        self._recv_t.start()
        self._send_t = threading.Thread(target=self._send_loop, args=(conn, gen, stop), daemon=True)
        self._send_t.start()

    def _stop_io(self):
        """Close the current connection; its threads exit without reporting."""
        self._conn_stop.set()
        conn = self.conn
        try:
            conn.shutdown(_socket_mod.SHUT_RDWR)
        except (OSError, AttributeError):
            pass
        try:
            conn.close()
        except (OSError, AttributeError):
            pass
        for thread in (self._recv_t, self._send_t):
            if thread and thread.is_alive() and thread is not threading.current_thread():
                thread.join(timeout=0.35)

    def _report_disconnect(self, gen, reason, detail=None):
        """Record a failure of connection ``gen``; stale connections are ignored."""
        if gen != self._conn_gen or self._stop_event.is_set() or self._conn_stop.is_set():
            return
        self.connected = False
        self.disconnect_reason = reason
        event = {'t': 'disconnect', 'reason': reason, 'gen': gen}
        if detail:
            event['detail'] = detail
        self._queue_net_event(event)

    def _recv_loop(self, conn, gen, stop):
        rate_start = time.monotonic()
        rate_count = 0
        while not (stop.is_set() or self._stop_event.is_set()):
            try:
                frame_limit = NET_MAX_SESSION_INPUT_FRAME if self.is_host else NET_MAX_SESSION_STATE_FRAME
                msg = _net_recv(conn, max_frame=frame_limit)
                if msg is None:
                    self._report_disconnect(gen, 'peer_disconnect')
                    return
                now = time.monotonic()
                if now - rate_start >= 1.0:
                    rate_start, rate_count = now, 0
                rate_count += 1
                message_rate_limit = 130 if self.is_host else 75
                if rate_count > message_rate_limit:
                    raise _NetProtocolError('peer exceeded the message rate limit')
                if not _validate_net_session_message(msg, self.is_host):
                    raise _NetProtocolError('peer sent an unexpected or invalid session message')
                self._last_rx = now
                self._queue_net_event(msg)
            except _NetProtocolError as exc:
                self._report_disconnect(gen, 'protocol_error', str(exc))
                print('[network] protocol error from peer')
                return
            except (ConnectionError, BrokenPipeError, OSError) as exc:
                self._report_disconnect(gen, 'socket_error', str(exc))
                return
            except Exception as exc:
                # Do not disguise programming errors as a normal disconnect.
                self._report_disconnect(gen, 'receiver_error', repr(exc))
                print(f"[network] unexpected receiver failure: {exc}")
                return

    def _send_safe(self, msg):
        if not self.connected or self._stop_event.is_set():
            return False
        if not isinstance(msg, dict):
            return False
        is_state = msg.get('t') == 'state'
        with self._send_q.mutex:
            pending = self._send_q.queue
            if is_state:
                # State is a replaceable snapshot. Coalesce it so a slow link
                # cannot build latency or an unbounded backlog.
                for idx in range(len(pending) - 1, -1, -1):
                    if isinstance(pending[idx], dict) and pending[idx].get('t') == 'state':
                        pending[idx] = msg
                        self._send_q.not_empty.notify()
                        return True
            else:
                # Keep control/input ordering ahead of any stale snapshot.
                for idx in range(len(pending) - 1, -1, -1):
                    if isinstance(pending[idx], dict) and pending[idx].get('t') == 'state':
                        del pending[idx]
                        self._send_q.unfinished_tasks -= 1
                        break
            if len(pending) >= self._send_q.maxsize:
                queue_full = True
            else:
                pending.append(msg)
                self._send_q.unfinished_tasks += 1
                self._send_q.not_empty.notify()
                queue_full = False
        if queue_full:
            self.connected = False
            self.disconnect_reason = 'send_backpressure'
            self._queue_net_event({'t': 'disconnect', 'reason': self.disconnect_reason})
            return False
        return True

    def _send_loop(self, conn, gen, stop):
        while not (stop.is_set() or self._stop_event.is_set()):
            try:
                msg = self._send_q.get(timeout=0.1)
            except _queue_mod.Empty:
                continue
            try:
                _net_send(conn, msg)
            except (ConnectionError, BrokenPipeError, OSError) as exc:
                self._report_disconnect(gen, 'send_socket_error', str(exc))
                return
            except Exception as exc:
                self._report_disconnect(gen, 'send_error', repr(exc))
                print(f"[network] unexpected send failure: {exc}")
                return
            finally:
                self._send_q.task_done()

    def link_state(self):
        """'connected' | 'unstable' | 'reconnecting' | 'waiting' | 'left' | 'lost'."""
        if self.peer_left:
            return 'left'
        if self._reconnect_state == 'host_wait':
            return 'waiting'
        if self._reconnect_state == 'client_dial':
            return 'reconnecting'
        if not self.connected:
            return 'lost'
        if time.monotonic() - self._last_rx > self.STALL_WARN_SECONDS:
            return 'unstable'
        return 'connected'

    def reconnect_seconds_left(self):
        return max(0, int(math.ceil(self._reconnect_deadline - time.monotonic())))

    def _clear_send_queue(self):
        with self._send_q.mutex:
            self._send_q.queue.clear()
            self._send_q.unfinished_tasks = 0

    def _begin_reconnect(self):
        """Pause and try to resume after a recoverable drop (both roles)."""
        self._stop_io()
        self._clear_send_queue()
        self._reconnect_deadline = time.monotonic() + self.RECONNECT_WINDOW
        sgf_log.info('Multiplayer link lost (%s); trying to resume', self.disconnect_reason)
        if self.is_host:
            self._reconnect_state = 'host_wait'
            return
        self._reconnect_state = 'client_dial'
        self._dial_cancel = threading.Event()
        threading.Thread(target=self._dial_loop,
                         args=(self._reconnect_deadline, self._dial_cancel),
                         name='SGF-resume-dial', daemon=True).start()

    def _dial_loop(self, deadline, cancel):
        """Guest side: keep trying to rejoin the same match until the deadline."""
        session = self._session or {}
        while not cancel.is_set() and time.monotonic() < deadline:
            stream = None
            try:
                remaining = max(2.0, min(8.0, deadline - time.monotonic()))
                stream, _token = _open_secure_peer_stream(
                    session['host'], session['port'], session['invite'], cancel, remaining)
                stream.settimeout(6.0)
                _net_send(stream, {'t': 'secure_resume', 'token': session['resume']})
                reply = _net_recv(stream)
                if isinstance(reply, dict) and reply.get('t') == 'resumed' and set(reply) == {'t', 'v'}:
                    stream.settimeout(15.0)
                    self._resume_results.put((True, stream))
                    return
            except Exception as exc:
                sgf_log.info('Resume attempt failed: %s', _describe_relay_failure(exc))
            if stream is not None:
                try:
                    stream.close()
                except OSError:
                    pass
            wake = time.monotonic() + 1.0
            while time.monotonic() < wake and not cancel.is_set():
                time.sleep(0.05)
        self._resume_results.put((False, None))

    def _adopt_connection(self, conn):
        """Switch to a freshly resumed connection and carry on the same match."""
        self._stop_io()   # a half-open old connection is replaced by the guest's new one
        self._clear_send_queue()
        with self._recv_q.mutex:
            self._recv_q.queue.clear()
        self._start_io(conn)
        self.connected = True
        self.disconnect_reason = None
        self.peer_left = False
        self._reconnect_state = None
        self._reconnect_exhausted = False
        self._initial_board_sent = False
        self._next_ping = time.monotonic() + 0.2
        sgf_log.info('Multiplayer link resumed')

    def _poll_resume_listeners(self, now):
        """Host side: admit the original guest back (works while still 'connected')."""
        session = self._session
        if not self.is_host or not session or not session.get('listeners'):
            return
        try:
            ok, value = self._resume_results.get_nowait()
        except _queue_mod.Empty:
            ok = value = None
        else:
            self._resume_pending = False
            if ok:
                self._adopt_connection(value)
                return
        if self._resume_pending or now < self._next_listener_poll:
            return
        self._next_listener_poll = now + 0.2
        for listener in session['listeners']:
            try:
                raw, address = listener.accept()
            except (BlockingIOError, _socket_mod.timeout, OSError):
                continue
            peer_ip = address[0] if address else ''
            if not _allow_network_handshake_attempt(
                    peer_ip, session.setdefault('attempts', {}), max_attempts=30):
                raw.close()
                continue
            try:
                raw.setsockopt(_socket_mod.IPPROTO_TCP, _socket_mod.TCP_NODELAY, 1)
                threading.Thread(
                    target=_finish_secure_host_resume,
                    args=(raw, session['tls_context'], session['resume_token'],
                          self._resume_results, self._dial_cancel),
                    name='SGF-secure-resume', daemon=True).start()
                self._resume_pending = True
            except Exception:
                try:
                    raw.close()
                except OSError:
                    pass
            break

    def _service_link(self):
        """Per-frame link maintenance: heartbeat, stall detection, resume."""
        now = time.monotonic()
        if self.is_host:
            self._poll_resume_listeners(now)
        elif self._reconnect_state == 'client_dial':
            try:
                ok, value = self._resume_results.get_nowait()
            except _queue_mod.Empty:
                pass
            else:
                if ok:
                    self._adopt_connection(value)
                else:
                    self._reconnect_state = None   # gave up: final "connection lost"
                    self._reconnect_exhausted = True
                return
        if self._reconnect_state is not None:
            if self._reconnect_state == 'host_wait' and now >= self._reconnect_deadline:
                self._reconnect_state = None
                self._reconnect_exhausted = True
                sgf_log.warning('The guest did not return within the reconnect window')
            return
        if self.connected:
            if not self.is_host and now >= self._next_ping:
                self._ping_seq = (self._ping_seq + 1) % (2 ** 31)
                self._ping_sent[self._ping_seq] = now
                for stale in sorted(self._ping_sent)[:-8]:
                    self._ping_sent.pop(stale, None)
                self._send_safe({'t': 'ping', 'n': self._ping_seq})
                self._next_ping = now + self.HEARTBEAT_INTERVAL
            if now - self._last_rx > self.STALL_LOST_SECONDS:
                self.connected = False
                self.disconnect_reason = 'stalled'
        if (not self.connected and not self.peer_left and self._session is not None
                and not self._reconnect_exhausted
                and self.disconnect_reason in self.RECOVERABLE_REASONS
                and not self._stop_event.is_set()):
            self._begin_reconnect()

    # ── host helpers ────────────────────────────────────────────────────

    def _handle_link_message(self, msg):
        """Handle link-level messages. Returns 'handled', 'stop', or None for game messages."""
        t = msg.get('t')
        if t == 'disconnect':
            if msg.get('gen', self._conn_gen) != self._conn_gen:
                return 'handled'     # a connection that was already replaced
            self.connected = False
            self.disconnect_reason = msg.get('reason', 'peer_disconnect')
            return 'stop'
        if t == 'ping' and self.is_host:
            self._send_safe({'t': 'pong', 'n': msg.get('n', 0)})
            return 'handled'
        if t == 'pong' and not self.is_host:
            sent_at = self._ping_sent.pop(msg.get('n'), None)
            if sent_at is not None:
                self.latency_ms = int(round((time.monotonic() - sent_at) * 1000))
            return 'handled'
        if t == 'bye':
            # Deliberate exit by the other side: no reconnect window.
            self.peer_left = True
            self.connected = False
            self.disconnect_reason = 'peer_left'
            return 'stop'
        return None



class NetworkGame(_NetworkLinkMixin):
    """
    LAN multiplayer game session.

    is_host=True  → runs the full simulation (authoritative); sends state to client.
    is_host=False → renders state received from host; sends key presses to host.

    Both players use WASD or Arrow keys on their own device.
    """

    def __init__(self, settings, screen, is_host, conn, mode='1v1', custom_map=None,
                 seed=None, tunnel_session=None, session=None):
        self.settings  = settings
        self.screen    = screen
        self.is_host   = is_host
        self.conn      = conn
        self.mode      = mode
        self.custom_map = custom_map  # same map dict on both peers — sent by host during handshake
        self.tunnel_session = tunnel_session if is_host else None
        self.seed      = seed if seed else generate_seed()
        self._init_link(conn, is_host, session)
        self._input_window_start = time.monotonic()
        self._input_window_count = 0
        self._pause_window_start = time.monotonic()
        self._pause_window_count = 0
        self._restart_window_start = time.monotonic()
        self._restart_window_count = 0

        if is_host:
            # Host owns the authoritative MultiplayerGame
            self.mp = MultiplayerGame(settings, screen, mode, seed=self.seed, custom_map=custom_map)
            if 'DEV_TOOLS' in globals(): DEV_TOOLS.register_game(self.mp)
        else:
            # Client holds the last rendered state dict
            self.render_state = None
            self._local_dir   = (0, -1)   # for 180° guard
            # Client: shadow MultiplayerGame purely for replay recording —
            # built with the SAME custom_map the host sent during handshake,
            # so the client's saved replay has the same board/obstacles too.
            self._client_recorder = MultiplayerGame(settings, screen, mode, seed=self.seed, custom_map=custom_map)
            self._client_recorder.mp_history = []
            self._client_recorder._mp_history_position_samples = 0
            self._client_recorder._mp_history_truncated = False
            if 'DEV_TOOLS' in globals(): DEV_TOOLS.register_game(self._client_recorder)

        # Both peers keep a saved flag so we only persist once per match
        self._mp_saved = False
        self._initial_board_sent = False

    # ── background receiver ──────────────────────────────────────────────

    def close(self):
        # Tell the peer this is deliberate so it does not wait for a reconnect.
        if self.connected and not self.peer_left and not self._stop_event.is_set():
            if self._send_safe({'t': 'bye'}):
                flush_deadline = time.monotonic() + 0.4
                while (time.monotonic() < flush_deadline
                       and (self._send_q.unfinished_tasks > 0) and self.connected):
                    time.sleep(0.01)
        self._stop_event.set()
        self._dial_cancel.set()
        self.connected = False
        self._stop_io()
        session = self._session
        if session:
            for listener in session.get('listeners', []) or []:
                try:
                    listener.close()
                except OSError:
                    pass
            session['listeners'] = []
        tunnel_session = getattr(self, 'tunnel_session', None)
        if tunnel_session is not None:
            self.tunnel_session = None
            tunnel_session.stop()

    # ── liveness, heartbeat and resume ───────────────────────────────────

    def _state_dict(self):
        mp = self.mp
        return {
            't':  'state',
            'p1': [list(s) for s in mp.p1_snake],
            'p2': [list(s) for s in mp.p2_snake],
            'f':  list(mp.fruit_pos) if mp.fruit_pos else None,
            'ft': getattr(mp, 'fruit_type', 'regular'),
            's1': mp.p1_score,
            's2': mp.p2_score,
            'a1': mp.p1_alive,
            'a2': mp.p2_alive,
            'go': mp.game_over,
            'pa': mp.paused,
            'w':  mp.winner,
            'obs': [list(o) for o in mp.obstacles],
            'bw': mp.board_width,
            'bh': mp.board_height,
            'cs': mp.cell_size,
            'ox': mp.board_offset_x,
            'oy': mp.board_offset_y,
            'seed': getattr(mp, 'seed', None),
            # Authoritative per-frame replay snapshot (exact same structure
            # SnakeGame/MultiplayerGame use for their own replay history).
            # Sending this verbatim — rather than having the client
            # reconstruct its own snapshot from a subset of the fields above
            # — guarantees both peers end up with the byte-for-byte same
            # replay record for this match (same fruit_type, same
            # directions, same everything), instead of two independently
            # drifting "shadow" recordings.
            'snap': mp._mp_snap(),
        }

    def _apply_client_input(self, d_list):
        """Apply a direction from the client to P2 (avoids 180° reversal)."""
        nd = tuple(d_list)
        cur = self.mp.p2_dir
        if not (nd[0] == -cur[0] and nd[1] == -cur[1]):
            self.mp.p2_next = nd

    def _host_key(self, key):
        """Host controls P1 (WASD or Arrows)."""
        mp = self.mp
        mapping = {
            pygame.K_w: (0,-1), pygame.K_UP:    (0,-1),
            pygame.K_s: (0, 1), pygame.K_DOWN:  (0, 1),
            pygame.K_a: (-1,0), pygame.K_LEFT:  (-1,0),
            pygame.K_d: ( 1,0), pygame.K_RIGHT: ( 1,0),
        }
        if key not in mapping:
            return
        nd = mapping[key]
        cur = mp.p1_dir
        if not (nd[0] == -cur[0] and nd[1] == -cur[1]):
            mp.p1_next = nd

    # ── client helpers ───────────────────────────────────────────────────

    def _client_key(self, key):
        """Client controls P2; sends direction to host."""
        mapping = {
            pygame.K_w: (0,-1), pygame.K_UP:    (0,-1),
            pygame.K_s: (0, 1), pygame.K_DOWN:  (0, 1),
            pygame.K_a: (-1,0), pygame.K_LEFT:  (-1,0),
            pygame.K_d: ( 1,0), pygame.K_RIGHT: ( 1,0),
        }
        if key not in mapping:
            return
        nd = mapping[key]
        cur = self._local_dir
        if nd[0] == -cur[0] and nd[1] == -cur[1]:
            return
        self._local_dir = nd
        self._send_safe({'t': 'input', 'd': list(nd)})

    # ── rendering (client-side) ─────────────────────────────────────────

    def _draw_client(self):
        sw, sh = self.screen.get_width(), self.screen.get_height()
        background_color, board_color, grid_color = _map_theme_colors(self.settings)
        self.screen.fill(background_color)
        st = self.render_state

        if st is None:
            f = get_font(self.settings.language, 'bold', 24)
            s = f.render(get_text(self.settings.language, 'waiting_for_host'), True, COLORS['white'])
            self.screen.blit(s, (sw//2 - s.get_width()//2, sh//2 - s.get_height()//2))
            return

        bw = st.get('bw', 15); bh = st.get('bh', 15)
        cs = st.get('cs', 24); ox = st.get('ox', 0); oy = st.get('oy', 62)

        # Board
        pygame.draw.rect(self.screen, board_color,
                         pygame.Rect(ox, oy, bw*cs, bh*cs))
        for x in range(bw+1):
            pygame.draw.line(self.screen, grid_color,
                             (ox+x*cs, oy), (ox+x*cs, oy+bh*cs), 1)
        for y in range(bh+1):
            pygame.draw.line(self.screen, grid_color,
                             (ox, oy+y*cs), (ox+bw*cs, oy+y*cs), 1)

        # Obstacles
        for obs in st.get('obs', []):
            r = pygame.Rect(ox+obs[0]*cs, oy+obs[1]*cs, cs, cs)
            pygame.draw.rect(self.screen, COLORS.get('obstacle', (100,100,100)), r)

        # Fruit
        fp = st.get('f')
        if fp:
            fr = pygame.Rect(ox+fp[0]*cs, oy+fp[1]*cs, cs, cs)
            if cs >= 10 and self.settings.fruit_types_enabled:
                draw_fruit(self.screen, fr, st.get('ft', 'regular'))
            else:
                pygame.draw.rect(self.screen, COLORS['fruit'], fr)

        # Snakes
        def _ds(seg_list, bc, hc, alive):
            bc2 = bc if alive else (100,100,100)
            hc2 = hc if alive else (70,70,70)
            for i, seg in enumerate(seg_list or []):
                r = pygame.Rect(ox+seg[0]*cs+1, oy+seg[1]*cs+1, cs-2, cs-2)
                pygame.draw.rect(self.screen, hc2 if i==0 else bc2, r,
                                 border_radius=max(1, cs//5))

        _ds(st.get('p2',[]), MultiplayerGame.P2_BODY, MultiplayerGame.P2_HEAD, st.get('a2',True))
        _ds(st.get('p1',[]), MultiplayerGame.P1_BODY, MultiplayerGame.P1_HEAD, st.get('a1',True))

        # HUD
        hf = get_font(self.settings.language, 'bold',    20)
        sf = get_font(self.settings.language, 'regular', 14)
        lang = self.settings.language
        if self.mode == '1v1':
            p1c = (100,255,100) if st.get('a1',True) else (130,130,130)
            p2c = ( 80,215,255) if st.get('a2',True) else (130,130,130)
            self.screen.blit(hf.render(f"{get_text(lang, 'host_p1_score')}: {st.get('s1',0)}", True, p1c), (10, 8))
            s2 = hf.render(f"{get_text(lang, 'you_p2_score')}: {st.get('s2',0)}", True, p2c)
            self.screen.blit(s2, (sw - s2.get_width() - 10, 8))
        else:
            sc = st.get('s1',0) + st.get('s2',0)
            ss = hf.render(f"{get_text(lang, 'coop_score')}: {sc}", True, COLORS['white'])
            self.screen.blit(ss, (sw//2 - ss.get_width()//2, 8))
        tag = "1v1" if self.mode == '1v1' else get_text(lang, 'coop_label')
        ht = sf.render(get_text(lang, 'lan_controls_hint').format(mode=tag), True, (80,110,160))
        self.screen.blit(ht, (sw//2 - ht.get_width()//2, 44))

        # Game-over overlay
        if st.get('go'):
            ov = pygame.Surface((sw, sh), pygame.SRCALPHA)
            ov.fill((0,0,0,180)); self.screen.blit(ov, (0,0))
            bf = get_font(self.settings.language, 'bold',    50)
            mf2= get_font(self.settings.language, 'bold',    28)
            sf2= get_font(self.settings.language, 'regular', 20)
            w = st.get('w')
            if self.mode == '1v1':
                if   w==1:       txt,col = get_text(lang, 'host_wins'),    (100,255,100)
                elif w==2:       txt,col = get_text(lang, 'you_win_exclaim'), ( 80,215,255)
                elif w=='draw':  txt,col = get_text(lang, 'draw_exclaim'), (255,215,  0)
                else:            txt,col = get_text(lang, 'game_over'),    (200,200,200)
                sc_txt = f"{get_text(lang, 'host_p1_score')}: {st.get('s1',0)}     {get_text(lang, 'you_p2_score')}: {st.get('s2',0)}"
            else:
                if w=='coop_win': txt,col = get_text(lang, 'you_win_exclaim'), (100,255,100)
                else:             txt,col = get_text(lang, 'game_over'),  (255,80,80)
                sc_txt = f"{get_text(lang, 'team_score')}: {st.get('s1',0)+st.get('s2',0)}"
            for surf, y in [
                (bf.render(txt, True, col), sh//2-110),
                (mf2.render(sc_txt, True, COLORS['white']), sh//2-30),
                (sf2.render(get_text(lang, 'esc_back_menu'), True, (190,190,210)), sh//2+50),
            ]:
                self.screen.blit(surf, (sw//2 - surf.get_width()//2, y))
            _draw_replay_save_widget(
                self.screen, lang,
                getattr(self._client_recorder, '_replay_save_game_id', None),
                sw // 2, 68)
        elif st.get('pa'):
            ov = pygame.Surface((sw, sh), pygame.SRCALPHA)
            ov.fill((0, 0, 0, 145))
            self.screen.blit(ov, (0, 0))
            paused = hf.render(get_text(lang, 'paused').upper(), True, COLORS['white'])
            self.screen.blit(paused, paused.get_rect(center=(sw // 2, sh // 2)))
            resume_hint = sf.render(get_text(lang, 'press_p_to_resume'), True, (190, 205, 230))
            self.screen.blit(resume_hint, resume_hint.get_rect(center=(sw // 2, sh // 2 + 34)))

    def _link_label(self):
        """'NET' for relay sessions, 'LAN' otherwise."""
        session = self._session or {}
        relay = (self.tunnel_session is not None
                 or _is_cloudflare_quick_hostname(session.get('host', '')))
        return 'NET' if relay else 'LAN'

    def _draw_host_net_badge(self):
        """Top-right link badge for both roles: transport, state and latency."""
        lang = self.settings.language
        sf = get_font(lang, 'regular', 13)
        tag = "1v1" if self.mode == '1v1' else get_text(lang, 'coop_label')
        state = self.link_state()
        if state == 'connected':
            colour = (80, 255, 80)
            status = f"● {get_text(lang, 'connected_label')}"
            if self.latency_ms is not None:
                status += f" · {self.latency_ms} ms"
        elif state == 'unstable':
            colour = (255, 200, 80)
            status = f"● {_net_ui_text(lang, 'link_unstable')}"
        else:
            colour = (255, 80, 80)
            status = f"✕ {get_text(lang, 'disconnected_label')}"
        s = sf.render(f"[{self._link_label()} {tag}] {status}", True, colour)
        self.screen.blit(s, (self.screen.get_width() - s.get_width() - 8, 44))

    def _draw_conn_lost(self):
        """Full-screen state for a link that is gone, being resumed, or ended."""
        _draw_link_overlay(self.screen, self.settings, self)

    def _drain_network_messages(self):
        """Apply up to 16 queued peer messages (shared by run() and tests)."""
        for _message_budget in range(16):
            try:
                msg = self._recv_q.get_nowait()
            except _queue_mod.Empty:
                break
            if not isinstance(msg, dict):
                self.connected = False
                self.disconnect_reason = 'protocol_error'
                break
            outcome = self._handle_link_message(msg)
            if outcome == 'handled':
                continue
            if outcome == 'stop':
                break
            t = msg.get('t')
            if self.is_host:
                if t in ('pause_req', 'resume_req'):
                    self._pause_window_start, self._pause_window_count, _rate_ok = _network_rate_window(
                        self._pause_window_start, self._pause_window_count,
                        time.monotonic(), limit=4)
                    if not _rate_ok:
                        self.connected = False
                        self.disconnect_reason = 'pause_rate_limit'
                        self._queue_net_event({'t': 'disconnect', 'reason': self.disconnect_reason})
                        break
                elif t == 'restart_req':
                    self._restart_window_start, self._restart_window_count, _rate_ok = _network_rate_window(
                        self._restart_window_start, self._restart_window_count,
                        time.monotonic(), limit=2)
                    if not _rate_ok:
                        self.connected = False
                        self.disconnect_reason = 'restart_rate_limit'
                        self._queue_net_event({'t': 'disconnect', 'reason': self.disconnect_reason})
                        break
                if t == 'pause_req':
                    if not self.mp.game_over and not self.mp.paused:
                        self.mp.paused = True
                        if getattr(self, 'runtime', None) is not None:
                            self.runtime.set_game_paused(True, {'game': 'network'})
                elif t == 'resume_req':
                    if not self.mp.game_over and self.mp.paused:
                        self.mp.paused = False
                        if getattr(self, 'runtime', None) is not None:
                            self.runtime.set_game_paused(False, {'game': 'network'})
                elif t == 'input':
                    now = time.monotonic()
                    if now - self._input_window_start >= 1.0:
                        self._input_window_start = now
                        self._input_window_count = 0
                    self._input_window_count += 1
                    if self._input_window_count > 120:
                        self.connected = False
                        self.disconnect_reason = 'input_rate_limit'
                        self._queue_net_event({'t': 'disconnect', 'reason': self.disconnect_reason})
                        break
                    d = msg.get('d')
                    if _validate_net_direction(d):
                        self._apply_client_input(d)
                    else:
                        self.connected = False
                        self.disconnect_reason = 'protocol_error'
                        self._queue_net_event({'t': 'disconnect', 'reason': self.disconnect_reason, 'detail': 'invalid direction payload'})
                        break
                elif t == 'restart_req' and self.mp.game_over:
                    self.mp.reset()
                    self._mp_saved = False
                    if self.connected:
                        try:
                            self._send_safe({'t': 'restart'})
                        except OSError:
                            self.connected = False
                        except Exception as _e:
                            print(f"[network] unexpected error sending restart: {_e}")
                            self.connected = False
                elif t not in ('restart_req', 'pause_req'):
                    self.connected = False
                    self.disconnect_reason = 'protocol_error'
                    self._queue_net_event({'t': 'disconnect', 'reason': self.disconnect_reason, 'detail': 'unexpected message for host'})
                    break
            else:
                if t == 'state':
                    if not _validate_net_state_message(msg):
                        self.connected = False
                        self.disconnect_reason = 'protocol_error'
                        print('[network] rejected invalid state payload from host')
                        break
                    previous_state = self.render_state
                    old_score = None
                    new_score = (msg.get('s1', 0) + msg.get('s2', 0)
                                 if self.mode == 'coop' else msg.get('s2', 0))
                    if previous_state is not None:
                        old_score = (previous_state.get('s1', 0) + previous_state.get('s2', 0)
                                     if self.mode == 'coop' else previous_state.get('s2', 0))
                        if new_score > old_score:
                            _trigger_mobile_haptic(30)
                        if msg.get('go') and not previous_state.get('go'):
                            _trigger_mobile_haptic(90)
                    elif msg.get('go'):
                        _trigger_mobile_haptic(90)
                    self.render_state = msg
                    # Record this frame using the host's exact authoritative
                    # snapshot — not a client-side reconstruction — so both
                    # peers end up with the identical replay record for
                    # this match (same fruit types, directions, everything).
                    rec = self._client_recorder
                    rec.board_width  = msg.get('bw', rec.board_width)
                    rec.board_height = msg.get('bh', rec.board_height)
                    rec.seed = msg.get('seed', rec.seed)
                    snap = msg.get('snap')
                    if snap and (not rec.mp_history or rec.mp_history[-1] != snap):
                        _append_mp_replay_snapshot(rec, snap)
                    # Keep a few fields mirrored on rec itself too, in case
                    # save_match() or anything else reads current state
                    # directly rather than through mp_history.
                    rec.p1_score  = msg.get('s1', 0)
                    rec.p2_score  = msg.get('s2', 0)
                    if old_score is not None and new_score > old_score:
                        _track_game_fruit(rec, previous_state.get('ft', 'regular'))
                    rec._sgf_xp_score_override = (
                        new_score if self.mode == 'coop' else msg.get('s2', 0))
                    rec._sgf_xp_victory_override = (
                        msg.get('w') == 'coop_win' if self.mode == 'coop'
                        else msg.get('w') == 2)
                    rec.game_over = msg.get('go', False)
                    rec.winner    = msg.get('w')
                elif t == 'restart':
                    self.render_state = None
                    self._client_recorder.mp_history = []
                    self._client_recorder._mp_history_position_samples = 0
                    self._client_recorder._mp_history_truncated = False
                    _clear_game_xp_award(self._client_recorder)
                    self._client_recorder.fruits_eaten = 0
                    self._client_recorder.unique_fruits_collected = set()
                    self._client_recorder._sgf_xp_score_override = 0
                    self._client_recorder._sgf_xp_victory_override = False
                    self._mp_saved = False
                elif t == 'lan_leaderboard':
                    if not _validate_lan_leaderboard_message(msg):
                        self.connected = False
                        self.disconnect_reason = 'protocol_error'
                        self._queue_net_event({'t': 'disconnect', 'reason': self.disconnect_reason,
                                               'detail': 'invalid LAN leaderboard payload'})
                        break
                    _merge_lan_leaderboard(msg['entries'])
                else:
                    self.connected = False
                    self.disconnect_reason = 'protocol_error'
                    self._queue_net_event({'t': 'disconnect', 'reason': self.disconnect_reason, 'detail': 'unexpected message for client'})
                    break

    # ── main loop ────────────────────────────────────────────────────────

    def run(self):
        running = True
        clock   = pygame.time.Clock()

        while running:
            _pump_audio()
            frame_start = time.perf_counter()
            input_start = frame_start
            self._drain_network_messages()
            self._service_link()

            # Connection-lost screen
            if not self.connected:
                self._draw_conn_lost()
                _legacy_nav_draw(locals().get('self'))
                pygame.display.flip()
                for event in pygame.event.get():
                    if _legacy_nav_event(locals().get('self'), event, locals()):
                        continue
                    if getattr(self, 'runtime', None) is not None:
                        handled, _actions = self.runtime.input.route(event)
                        if handled:
                            continue
                    if event.type == pygame.QUIT:
                        running = False
                    elif event.type == pygame.KEYDOWN and event.key == pygame.K_ESCAPE:
                        running = False
                clock.tick(30)
                continue

            # Event handling
            for event in pygame.event.get():
                if _legacy_nav_event(locals().get('self'), event, locals()):
                    continue
                if _is_app_background_event(event):
                    if self.is_host:
                        if not self.mp.game_over:
                            self.mp.paused = True
                            if getattr(self, 'runtime', None) is not None:
                                self.runtime.set_game_paused(True, {'game': 'network'})
                    elif not (self.render_state and self.render_state.get('go')):
                        self._send_safe({'t': 'pause_req'})
                    continue
                if getattr(self, 'runtime', None) is not None:
                    handled, _actions = self.runtime.input.route(event)
                    if handled:
                        continue
                if event.type == pygame.QUIT:
                    running = False
                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_F8 and DEV_TOOLS.unlocked:
                        target_game = getattr(self, 'mp', None) or getattr(self, '_client_recorder', None) or self
                        DEV_TOOLS.open_panel(self.screen, target_game)
                        continue
                    k = event.key
                    if k == pygame.K_F11:
                        self.screen = _toggle_fullscreen(self.screen)
                    elif k == pygame.K_ESCAPE:
                        running = False
                    elif k == pygame.K_r:
                        if self.is_host and self.mp.game_over:
                            self.mp.reset()
                            try:
                                self._send_safe({'t': 'restart'})
                            except OSError:
                                self.connected = False
                            except Exception as _e:
                                print(f"[network] unexpected error sending restart: {_e}")
                                self.connected = False
                        elif not self.is_host:
                            try:
                                self._send_safe({'t': 'restart_req'})
                            except OSError:
                                self.connected = False
                            except Exception as _e:
                                print(f"[network] unexpected error sending restart_req: {_e}")
                                self.connected = False
                    elif k == pygame.K_p and self.is_host and not self.mp.game_over:
                        self.mp.paused = not self.mp.paused
                        if getattr(self, 'runtime', None) is not None:
                            self.runtime.set_game_paused(self.mp.paused, {'game': 'network'})
                    elif (k == pygame.K_p and not self.is_host and self.render_state
                          and self.render_state.get('pa') and not self.render_state.get('go')):
                        self._send_safe({'t': 'resume_req'})
                    elif self.is_host and not self.mp.game_over and not self.mp.paused:
                        self._host_key(k)
                    elif not self.is_host:
                        go = self.render_state.get('go') if self.render_state else False
                        if not go:
                            self._client_key(k)
                elif event.type == pygame.VIDEORESIZE:
                    self.screen = pygame.display.set_mode(
                        (event.w, event.h), pygame.RESIZABLE)
                    if self.is_host:
                        self.mp._init_layout()

            # Host: tick + send state
            if self.is_host:
                now = time.time() * 1000
                if not self.mp.paused and not self.mp.game_over:
                    if now - self.mp.last_tick >= DEV_TOOLS.scaled_update_interval(self.settings.update_rate_ms):
                        DEV_TOOLS.apply_frame_cheats(self.mp)
                        self.mp.tick()
                        self.mp.last_tick = now
                # Send state every frame so the client stays fresh
                if self.connected:
                    if not self._initial_board_sent:
                        self._initial_board_sent = self._send_safe({
                            't': 'lan_leaderboard', 'entries': _lan_leaderboard_snapshot()})
                    self._send_safe(self._state_dict())

                self.mp.draw()
                self._draw_host_net_badge()
            else:
                self._draw_client()
                self._draw_host_net_badge()

            # Persist the match locally on whichever peer sees game-over
            if not self._mp_saved:
                if self.is_host and self.mp.game_over:
                    self.mp.save_match(p1_name='Host', p2_name='Client', source='lan_host')
                    self._mp_saved = True
                    self._send_safe({'t': 'lan_leaderboard', 'entries': _lan_leaderboard_snapshot()})
                elif (not self.is_host) and self.render_state and self.render_state.get('go'):
                    self._client_recorder.save_match(
                        p1_name='Host', p2_name='You', source='lan_client')
                    self._mp_saved = True

            _legacy_nav_draw(locals().get('self'))
            render_start = time.perf_counter()
            # The game draw/client draw already happened above.  Render time here
            # intentionally measures only the DEV overlay/flip bookkeeping.
            DEV_TOOLS.draw_dev_indicator(self.screen, replay=False)
            render_ms = (time.perf_counter() - render_start) * 1000.0
            frame_ms = clock.tick(60)
            input_ms = (time.perf_counter() - input_start) * 1000.0
            target = self.mp if self.is_host else self._client_recorder
            _dev_game_frame_hook(target, frame_ms, render_ms=render_ms, input_ms=input_ms)
            pygame.display.flip()

        # Cleanup: stop receiver and close the socket cleanly so daemon threads
        # cannot outlive the game screen or keep a launcher process alive.
        self.close()
        _runtime_emit(self, 'NETWORK_DISCONNECTED', {'reason': self.disconnect_reason or 'local_exit'})


##############
# NETWORK MATCH FOR 3-4 PLAYERS
##############
class _PeerLink(_NetworkLinkMixin):
    """Link to one remote player of a multi-player session."""

    def __init__(self, conn, is_host, session=None):
        self._init_link(conn, is_host, session)

    def _poll_resume_listeners(self, now):
        return   # the match admits returning guests for every slot at once


_LINK_ONLY_MESSAGES = frozenset({'ping', 'pong', 'bye', 'disconnect'})


class _LobbyGuestLink(_PeerLink):
    """The guest of a two-player match while the host is still in a menu.

    HostLobby services its heartbeat (so the guest is not declared lost after
    12 s of silence), keeps its resume window alive, and finally hands the very
    same connection to the NetworkGame. Once the game owns it, the threads that
    are still running report to the game through the forwarding properties.
    """
    _owner = None

    def _forwarded(name):
        slot = '_lobby_' + name

        def getter(self):
            owner = self._owner
            return getattr(owner, name) if owner is not None else getattr(self, slot, None)

        def setter(self, value):
            owner = self._owner
            if owner is not None:
                setattr(owner, name, value)
            else:
                setattr(self, slot, value)
        return property(getter, setter)

    connected = _forwarded('connected')
    disconnect_reason = _forwarded('disconnect_reason')
    _last_rx = _forwarded('_last_rx')
    del _forwarded

    # A single guest is re-admitted by the link itself (a room does it for everyone).
    _poll_resume_listeners = _NetworkLinkMixin._poll_resume_listeners

    def close(self):
        self._stop_event.set()
        self._dial_cancel.set()
        self.connected = False
        self._stop_io()

    def service_waiting(self):
        """Answer heartbeat/leave messages; game messages stay queued for the match."""
        handled = []
        with self._recv_q.mutex:
            queued = self._recv_q.queue
            if any(isinstance(m, dict) and m.get('t') in _LINK_ONLY_MESSAGES for m in queued):
                handled = [m for m in queued if isinstance(m, dict) and m.get('t') in _LINK_ONLY_MESSAGES]
                keep = [m for m in queued if not (isinstance(m, dict) and m.get('t') in _LINK_ONLY_MESSAGES)]
                queued.clear()
                queued.extend(keep)
        for msg in handled:
            if self._handle_link_message(msg) == 'stop':
                break
        self._service_link()

    def is_gone(self):
        """True once the guest left or the reconnect window ran out."""
        return self.peer_left or (not self.connected and self._reconnect_state is None)

    def is_healthy(self):
        return self.link_state() in ('connected', 'unstable')


_DIRECTION_NAMES = {(0, -1): 'up', (0, 1): 'down', (-1, 0): 'left', (1, 0): 'right'}
_KEY_DIRECTIONS = {
    pygame.K_w: (0, -1), pygame.K_UP: (0, -1), pygame.K_s: (0, 1), pygame.K_DOWN: (0, 1),
    pygame.K_a: (-1, 0), pygame.K_LEFT: (-1, 0), pygame.K_d: (1, 0), pygame.K_RIGHT: (1, 0),
}


class NetworkMatchN:
    """Network match for 3-4 players.

    The host runs the authoritative LocalMultiplayerNGame; every guest owns one
    link to the host, sends only its direction and draws the snapshots it
    receives with the very same engine (snapshots are validated by the engine's
    own loader). A guest that drops gets the same 30 s resume window as in a
    two-player match; the match pauses meanwhile, and a guest that does not
    return (or leaves on purpose) is eliminated while the others play on.
    """
    SEND_KEEPALIVE_SECONDS = 0.25
    MAX_RECORDED_FRAMES = 24000

    def __init__(self, settings, screen, is_host, mode, seed, custom_map, names,
                 you=0, links=None, link=None, tunnel_session=None, session=None):
        self.settings = settings
        self.screen = screen
        self.is_host = is_host
        self.mode = 'coop' if mode == 'coop' else '1v1'
        self.seed = seed if seed else generate_seed()
        self.custom_map = custom_map
        self.names = [_clean_player_name(name, f'Player {i + 1}') for i, name in enumerate(names)][:4]
        self.count = len(self.names)
        self.you = int(you)
        self.tunnel_session = tunnel_session if is_host else None
        self._session = session if isinstance(session, dict) else None
        self.links = list(links or [])           # host: slot i + 1 -> links[i]
        self.link = link                         # guest: the link to the host
        self.engine = LocalMultiplayerNGame(
            settings, screen, self.mode, player_count=self.count,
            player_configs=[{'name': name} for name in self.names],
            seed=self.seed, custom_map=custom_map)
        self.engine.save_source = 'lan_host' if is_host else 'lan_client'
        self.runtime = None
        self.slot_state = ['ok'] * self.count     # host's view of every slot
        self.guest_status = ['ok'] * self.count   # what the host last told a guest
        self._last_sent = (-1, None, None)
        self._last_send_time = 0.0
        self._resume_results = _queue_mod.Queue()
        self._resume_pending = False
        self._next_poll = 0.0
        self._cancel = threading.Event()
        self._recorded = 1
        self._saved = False
        self._closed = False
        if is_host:
            for slot, peer in enumerate(self.links, start=1):
                peer._session = {'slot': slot}   # marks the link as resumable
        if 'DEV_TOOLS' in globals():
            DEV_TOOLS.register_game(self.engine)

    # -- state shared by both roles ------------------------------------------

    def connected_players(self):
        if self.is_host:
            return 1 + sum(1 for state in self.slot_state[1:] if state == 'ok')
        return sum(1 for state in self.guest_status if state == 'ok')

    def waiting_names(self):
        states = self.slot_state if self.is_host else self.guest_status
        return [self.names[i] for i, state in enumerate(states) if state == 'wait']

    def _announce_start(self):
        """Host: tell every guest the match began (its slot and the final roster)."""
        for slot, peer in enumerate(self.links, start=1):
            peer._send_safe({'t': 'nstart', 'count': self.count, 'you': slot,
                             'names': list(self.names)})

    # -- host ----------------------------------------------------------------

    def _peer_state(self, peer):
        state = peer.link_state()
        if state in ('connected', 'unstable'):
            return 'ok'
        if state in ('waiting', 'reconnecting'):
            return 'wait'
        return 'left'

    def _eliminate(self, slot):
        if self.engine.alive[slot]:
            self.engine.alive[slot] = False
        self.slot_state[slot] = 'left'

    def _apply_direction(self, slot, vector):
        name = _DIRECTION_NAMES.get(tuple(vector))
        if name and self.engine.alive[slot]:
            self.engine._request_direction(slot, name)

    def _restart(self):
        self.engine.reset()
        self.engine.save_source = 'lan_host'
        self._last_sent = (-1, None, None)
        for slot, state in enumerate(self.slot_state):
            if state == 'left':
                self.engine.alive[slot] = False

    def _drain_peer(self, slot, peer):
        for _ in range(16):
            try:
                msg = peer._recv_q.get_nowait()
            except _queue_mod.Empty:
                break
            outcome = peer._handle_link_message(msg)
            if outcome == 'handled':
                continue
            if outcome == 'stop':
                break
            kind = msg.get('t')
            if kind == 'input':
                self._apply_direction(slot, msg['d'])
            elif kind == 'pause_req' and not self.engine.game_over:
                self.engine.paused = True
            elif kind == 'resume_req' and self.engine.paused and not self.engine.game_over:
                self.engine.paused = False
            elif kind == 'restart_req' and self.engine.game_over:
                self._restart()

    def _poll_resume(self, now):
        session = self._session
        if not session or not session.get('listeners'):
            return
        try:
            result = self._resume_results.get_nowait()
        except _queue_mod.Empty:
            result = None
        if result is not None:
            self._resume_pending = False
            ok, value, slot = result
            if ok and slot is not None and 1 <= slot <= len(self.links) and self.slot_state[slot] != 'left':
                self.links[slot - 1]._adopt_connection(value)
            elif ok:
                try:
                    value.close()
                except OSError:
                    pass
        if self._resume_pending or now < self._next_poll:
            return
        self._next_poll = now + 0.2
        tokens = {slot: session['resume_tokens'][slot] for slot in range(1, self.count)
                  if self.slot_state[slot] != 'left' and slot in session.get('resume_tokens', {})}
        for listener in session['listeners']:
            try:
                raw, address = listener.accept()
            except (BlockingIOError, _socket_mod.timeout, OSError):
                continue
            peer_ip = address[0] if address else ''
            if not tokens or not _allow_network_handshake_attempt(
                    peer_ip, session.setdefault('attempts', {}), max_attempts=60):
                raw.close()
                continue
            try:
                raw.setsockopt(_socket_mod.IPPROTO_TCP, _socket_mod.TCP_NODELAY, 1)
                threading.Thread(
                    target=_finish_secure_host_resume_any,
                    args=(raw, session['tls_context'], tokens, self._resume_results, self._cancel),
                    name='SGF-secure-resume', daemon=True).start()
                self._resume_pending = True
            except Exception:
                try:
                    raw.close()
                except OSError:
                    pass
            break

    def host_step(self, now=None):
        """One host frame of networking + simulation (also driven directly by tests)."""
        now = time.monotonic() if now is None else now
        for slot, peer in enumerate(self.links, start=1):
            self._drain_peer(slot, peer)
            peer._service_link()
            state = self._peer_state(peer)
            if state == 'left' and self.slot_state[slot] != 'left':
                self._eliminate(slot)
            elif self.slot_state[slot] != 'left':
                self.slot_state[slot] = state
        self._poll_resume(now)
        waiting = any(state == 'wait' for state in self.slot_state)
        engine = self.engine
        if not (engine.paused or engine.game_over or waiting):
            wall = time.time() * 1000
            if wall - engine.last_tick >= DEV_TOOLS.scaled_update_interval(self.settings.update_rate_ms):
                DEV_TOOLS.apply_frame_cheats(engine)
                engine.tick()
                engine.last_tick = wall
        self._broadcast_state(now)

    def _broadcast_state(self, now):
        engine = self.engine
        signature = (len(engine.mp_history), engine.paused, tuple(self.slot_state))
        if signature == self._last_sent and now - self._last_send_time < self.SEND_KEEPALIVE_SECONDS:
            return
        self._last_sent = signature
        self._last_send_time = now
        message = {'t': 'nstate', 'snap': engine._mp_snap(), 'pa': engine.paused,
                   'st': list(self.slot_state)}
        for peer in self.links:
            if peer.connected:
                peer._send_safe(message)

    # -- guest ---------------------------------------------------------------

    def guest_step(self):
        link = self.link
        for _ in range(16):
            try:
                msg = link._recv_q.get_nowait()
            except _queue_mod.Empty:
                break
            outcome = link._handle_link_message(msg)
            if outcome == 'handled':
                continue
            if outcome == 'stop':
                break
            if msg.get('t') != 'nstate':
                continue
            snap = msg['snap']
            if (not isinstance(snap.get('snakes'), list) or len(snap['snakes']) != self.count
                    or not self.engine._mp_load_snap(snap)):
                link._report_disconnect(link._conn_gen, 'protocol_error', 'invalid match snapshot')
                break
            self.engine.paused = msg['pa']
            if len(msg['st']) == self.count:
                self.guest_status = list(msg['st'])
            if self._recorded < self.MAX_RECORDED_FRAMES:
                self.engine.mp_history.append(snap)
                self._recorded += 1
            if not snap.get('game_over'):
                self._saved = False
                self.engine._match_saved = False
        link._service_link()
        if self.engine.game_over and not self._saved:
            self._saved = True
            self.engine.save_match(source='lan_client')

    # -- input / drawing -----------------------------------------------------

    def _handle_key(self, key):
        vector = _KEY_DIRECTIONS.get(key)
        if vector is None:
            return
        if self.is_host:
            self._apply_direction(0, vector)
            return
        current = self.engine.directions[self.you] if self.engine.directions else (0, 0)
        if vector == (-current[0], -current[1]):
            return
        self.link._send_safe({'t': 'input', 'd': list(vector)})

    def _draw_status(self):
        lang = self.settings.language
        font = get_font(lang, 'regular', 13)
        if self.is_host:
            label = f"[{self._transport_label()} {self.count}P] ● {self.connected_players()}/{self.count}"
            colour = (80, 255, 80) if self.connected_players() == self.count else (255, 200, 80)
        else:
            state = self.link.link_state()
            if state == 'connected':
                label = f"[{self._transport_label()} {self.count}P] ● {get_text(lang, 'connected_label')}"
                if self.link.latency_ms is not None:
                    label += f" · {self.link.latency_ms} ms"
                colour = (80, 255, 80)
            elif state == 'unstable':
                label = f"[{self._transport_label()} {self.count}P] ● {_net_ui_text(lang, 'link_unstable')}"
                colour = (255, 200, 80)
            else:
                label = f"[{self._transport_label()} {self.count}P] ✕ {get_text(lang, 'disconnected_label')}"
                colour = (255, 80, 80)
        surface = font.render(label, True, colour)
        self.screen.blit(surface, (self.screen.get_width() - surface.get_width() - 8, 44))

    def _transport_label(self):
        session = self._session or {}
        relay = (self.tunnel_session is not None
                 or _is_cloudflare_quick_hostname(session.get('host', '')))
        return 'NET' if relay else 'LAN'

    def _draw_waiting(self):
        names = self.waiting_names()
        if not names:
            return
        lang = self.settings.language
        sw, sh = self.screen.get_size()
        overlay = pygame.Surface((sw, 70), pygame.SRCALPHA)
        overlay.fill((0, 0, 0, 170))
        self.screen.blit(overlay, (0, sh // 2 - 35))
        seconds = None
        if self.is_host:
            seconds = max((peer.reconnect_seconds_left() for peer in self.links
                           if peer._reconnect_state == 'host_wait'), default=None)
        text = f"{', '.join(names)} · {_net_ui_text(lang, 'waiting_player_title')}"
        if seconds is not None:
            text += f" · {seconds} s"
        surface = render_fit(get_font(lang, 'bold', 20), text, (255, 205, 110), sw - 32, padding=0)
        self.screen.blit(surface, (sw // 2 - surface.get_width() // 2, sh // 2 - surface.get_height() // 2))

    def draw(self):
        if not self.is_host and not self.link.connected:
            _draw_link_overlay(self.screen, self.settings, self.link)
            return
        self.engine.draw()
        self._draw_status()
        self._draw_waiting()

    def close(self):
        if self._closed:
            return
        self._closed = True
        self._cancel.set()
        for peer in ([self.link] if self.link is not None else []) + list(self.links):
            try:
                if peer.connected and not peer.peer_left:
                    peer._send_safe({'t': 'bye'})
            except Exception:
                pass
        flush_deadline = time.monotonic() + 0.4
        while time.monotonic() < flush_deadline and any(
                peer._send_q.unfinished_tasks > 0 and peer.connected
                for peer in ([self.link] if self.link is not None else []) + list(self.links)):
            time.sleep(0.01)
        for peer in ([self.link] if self.link is not None else []) + list(self.links):
            peer._stop_event.set()
            peer._dial_cancel.set()
            peer.connected = False
            peer._stop_io()
        session = self._session
        if session:
            for listener in session.get('listeners', []) or []:
                try:
                    listener.close()
                except OSError:
                    pass
            session['listeners'] = []
        tunnel, self.tunnel_session = self.tunnel_session, None
        if tunnel is not None:
            tunnel.stop()

    def run(self):
        clock = pygame.time.Clock()
        running = True
        while running:
            _pump_audio()
            if self.is_host:
                self.host_step()
            else:
                self.guest_step()
            for event in pygame.event.get():
                if _legacy_nav_event(locals().get('self'), event, locals()):
                    continue
                if event.type == pygame.QUIT:
                    running = False
                elif event.type == pygame.VIDEORESIZE:
                    self.screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)
                    self.engine.screen = self.screen
                    self.engine._init_layout()
                elif event.type == pygame.KEYDOWN:
                    key = event.key
                    if key == pygame.K_ESCAPE:
                        running = False
                    elif key == pygame.K_F11:
                        self.screen = _toggle_fullscreen(self.screen)
                        self.engine.screen = self.screen
                        self.engine._init_layout()
                    elif key == pygame.K_p and not self.engine.game_over:
                        if self.is_host:
                            self.engine.paused = not self.engine.paused
                        elif self.link.connected:
                            self.link._send_safe({'t': 'resume_req' if self.engine.paused else 'pause_req'})
                    elif key == pygame.K_r and self.engine.game_over:
                        if self.is_host:
                            self._restart()
                        elif self.link.connected:
                            self.link._send_safe({'t': 'restart_req'})
                    elif self.is_host and not self.engine.paused or (not self.is_host and self.link.connected):
                        self._handle_key(key)
            self.draw()
            _legacy_nav_draw(locals().get('self'))
            DEV_TOOLS.draw_dev_indicator(self.screen, replay=False)
            pygame.display.flip()
            clock.tick(60)
        self.close()
        _runtime_emit(self, 'NETWORK_DISCONNECTED', {'reason': 'local_exit'})


##############
# AI / VS AI
##############

class SnakeAI:
    """
    Pathfinding AI for snake games.  Works for both single-player VS-AI and
    multiplayer AI slots.

    Difficulty levels
    -----------------
    noob       – random moves (the chaos baseline; never reverses into its own neck)
    easy       – safe one-step fruit seeking
    medium     – bounded BFS planning, with a safe one-step fallback
    hard       – full BFS + flood-fill safety, anti-loop logic
    impossible – hard planning plus opponent interception
    """

    DIRS = [(0, -1), (1, 0), (0, 1), (-1, 0)]   # up right down left
    MEDIUM_SEARCH_BUDGET = 2048

    def __init__(self, difficulty='medium', rng=None):
        self.difficulty  = difficulty
        # Loop-detection: store last N head positions
        self._history    = []          # list of (x, y)
        self._history_max = 12
        # Seeded RNG — falls back to the global random module if none supplied
        self._rng = rng or random

    # ── public API ──────────────────────────────────────────────────────

    last_decision_ns = 0

    def choose_direction(self, snake, occupied, fruit, board_w, board_h,
                         portals=None, powerup_pos=None, wall_collision=True,
                         opponent_snake=None):
        """Return (dx, dy) for the next move. Also records how long the decision took (`last_decision_ns`)."""
        started = time.perf_counter_ns()
        try:
            return self._choose_direction(snake, occupied, fruit, board_w, board_h, portals, powerup_pos,
                                          wall_collision, opponent_snake)
        finally:
            self.last_decision_ns = time.perf_counter_ns() - started

    def _choose_direction(self, snake, occupied, fruit, board_w, board_h,
                          portals=None, powerup_pos=None, wall_collision=True,
                          opponent_snake=None):
        head = snake[0]

        if self.difficulty == 'noob':
            return self._noob(snake)

        # Record head for loop detection (hard/impossible use this)
        self._history.append(tuple(head))
        if len(self._history) > self._history_max:
            self._history.pop(0)

        # Build blocked set: obstacles + own body
        blocked = set(map(tuple, occupied))
        if len(snake) > 1:
            blocked.update(map(tuple, snake[1:]))

        # Build portal map  pos → exit_pos
        portal_map = {}
        if portals:
            for a, b, _ in portals:
                portal_map[tuple(a)] = tuple(b)
                portal_map[tuple(b)] = tuple(a)

        ctx = (board_w, board_h, wall_collision)

        if self.difficulty == 'easy':
            return self._easy(head, blocked, fruit, ctx)
        elif self.difficulty == 'medium':
            return self._medium(head, blocked, fruit, ctx, portal_map, powerup_pos)
        elif self.difficulty == 'hard':
            return self._hard(head, snake, blocked, fruit, ctx, portal_map, powerup_pos)
        else:
            return self._impossible(head, snake, blocked, fruit, ctx,
                                    portal_map, powerup_pos, opponent_snake)

    # ── difficulty implementations ───────────────────────────────────────

    def _noob(self, snake):
        """Chaos baseline: any direction except straight back into the neck (an illegal reversal in Snake)."""
        options = list(self.DIRS)
        if len(snake) > 1:
            neck = (snake[1][0] - snake[0][0], snake[1][1] - snake[0][1])
            options = [d for d in options if d != neck] or options
        return self._rng.choice(options)

    def _easy(self, head, blocked, fruit, ctx):
        safe = self._safe_dirs(head, blocked, ctx)
        if not safe:
            return self.DIRS[1]
        return self._greedy_safe_dir(head, safe, fruit, ctx)

    def _medium(self, head, blocked, fruit, ctx, portal_map=None, powerup_pos=None):
        safe = self._safe_dirs(head, blocked, ctx)
        if not safe:
            return self.DIRS[1]
        target = self._best_target(head, fruit, powerup_pos, ctx, margin=1)
        portal_map = portal_map or {}
        path = self._bfs(
            head, target, blocked, ctx, portal_map,
            node_budget=self.MEDIUM_SEARCH_BUDGET)
        if path and len(path) > 1:
            direction = self._dir_from(head, path[1], ctx)
            if direction in safe:
                return direction
        return self._greedy_safe_dir(head, safe, target, ctx)

    def _greedy_safe_dir(self, head, safe, target, ctx):
        """Choose a safe move that minimizes one-step distance to the target."""
        bw, bh, wall = ctx
        scores = []
        best = None
        for direction in safe:
            nxt = self._step(head, direction, ctx)
            distance = self._manhattan(nxt, target, bw, bh,
                                       wall_collision=wall)
            if best is None or distance < best:
                best = distance
                scores = [direction]
            elif distance == best:
                scores.append(direction)
        return self._rng.choice(scores) if scores else self.DIRS[1]

    def _hard(self, head, snake, blocked, fruit, ctx, portal_map, powerup_pos):
        """
        Competent AI. BFS to fruit + flood-fill safety gate.
        Anti-loop: if the snake has been oscillating for the last 8 ticks,
        force exploration by shuffling direction priorities.
        Falls back to max-space direction (with tie-breaking randomness).
        """
        target = self._best_target(head, fruit, powerup_pos, ctx, margin=2)

        # ── loop detection ─────────────────────────────────────────────
        looping = self._is_looping(window=8)

        path = self._bfs(head, target, blocked, ctx, portal_map,
                         shuffle=looping)
        if path and len(path) > 1:
            nxt = path[1]
            d   = self._dir_from(head, nxt, ctx)
            # After moving: old head joins body, old tail leaves body.
            # nxt is the new head and must NOT be in the fill's blocked set.
            after_blocked = (set(blocked) - {tuple(snake[-1])}) | {tuple(snake[0])}
            threshold = max(len(snake) // 2, 3)
            if self._flood_fill(nxt, after_blocked, ctx) >= threshold:
                return d

        return self._escape_dir(head, snake, blocked, ctx, looping)

    def _impossible(self, head, snake, blocked, fruit, ctx,
                    portal_map, powerup_pos, opponent_snake):
        """Expert AI: hard + tracks opponent, intercepts when larger."""
        extra = set(blocked)
        if opponent_snake and len(opponent_snake) > 1:
            extra.update(map(tuple, opponent_snake[1:]))

        target   = tuple(fruit)
        opp_head = tuple(opponent_snake[0]) if opponent_snake else None

        if opp_head and len(snake) > len(opponent_snake):
            path = self._bfs(head, opp_head, extra, ctx, portal_map)
            if path and len(path) <= 6:
                target = opp_head

        if powerup_pos:
            bw, bh, _ = ctx
            wall = ctx[2]
            if self._manhattan(head, powerup_pos, bw, bh, wall) < self._manhattan(head, target, bw, bh, wall) - 1:
                target = powerup_pos

        looping = self._is_looping(window=8)
        path = self._bfs(head, target, extra, ctx, portal_map, shuffle=looping)
        if path and len(path) > 1:
            nxt = path[1]
            d   = self._dir_from(head, nxt, ctx)
            after_blocked = (set(extra) - {tuple(snake[-1])}) | {tuple(snake[0])}
            if self._flood_fill(nxt, after_blocked, ctx) >= max(len(snake) // 2, 3):
                return d

        return self._escape_dir(head, snake, extra, ctx, looping)

    # ── pathfinding helpers ──────────────────────────────────────────────

    def _step(self, pos, d, ctx):
        """Step one cell; returns None if it would hit a wall."""
        bw, bh, wall = ctx
        nx = pos[0] + d[0]
        ny = pos[1] + d[1]
        if wall:
            return (nx, ny) if (0 <= nx < bw and 0 <= ny < bh) else None
        return (nx % bw, ny % bh)

    def _safe_dirs(self, head, blocked, ctx):
        """Directions that lead to in-bounds, unblocked cells."""
        return [d for d in self.DIRS
                if (nxt := self._step(head, d, ctx)) is not None
                and nxt not in blocked]

    def _bfs_reference(self, start, goal, blocked, ctx, portal_map, shuffle=False,
                       node_budget=None):
        """
        Original tuple/set BFS, kept as the reference the fast version is tested against.
        BFS from start to goal.
        shuffle=True randomises neighbour order to escape loops.
        Returns path list or None.
        """
        if goal is None:
            return None
        goal  = tuple(goal)
        start = tuple(start)
        from collections import deque
        dirs = list(self.DIRS)
        if shuffle:
            self._rng.shuffle(dirs)
        q = deque([start])
        parents = {start: None}
        expanded = 0
        budget = (max(1, int(node_budget)) if node_budget is not None else None)
        while q:
            cur = q.popleft()
            expanded += 1
            if cur == goal:
                path = []
                node = cur
                while node is not None:
                    path.append(node)
                    node = parents[node]
                path.reverse()
                return path
            if budget is not None and expanded >= budget:
                break
            for d in dirs:
                nxt = self._step(cur, d, ctx)
                if nxt is None or nxt in blocked or nxt in parents:
                    continue
                parents[nxt] = cur
                q.append(nxt)
                if nxt in portal_map:
                    ex = portal_map[nxt]
                    if ex not in parents and ex not in blocked:
                        parents[ex] = nxt
                        q.append(ex)
        return None

    def _flood_fill_reference(self, start, blocked, ctx):
        """Original set-based flood fill (reference for the fast version)."""
        from collections import deque
        start = tuple(start)
        if start in blocked:
            return 0
        visited = {start}
        q = deque([start])
        while q:
            cur = q.popleft()
            for d in self.DIRS:
                nxt = self._step(cur, d, ctx)
                if nxt is not None and nxt not in blocked and nxt not in visited:
                    visited.add(nxt)
                    q.append(nxt)
        return len(visited)

    # ── fast integer-grid versions (same results as the *_reference methods, several times quicker) ─────

    _NEIGHBOUR_CACHE = {}

    @classmethod
    def _neighbour_table(cls, bw, bh, wall):
        """For every cell index y*bw+x: its up/right/down/left neighbour indices (-1 = a wall), in DIRS order."""
        key = (bw, bh, bool(wall))
        table = cls._NEIGHBOUR_CACHE.get(key)
        if table is None:
            table = []
            for y in range(bh):
                for x in range(bw):
                    row = []
                    for dx, dy in cls.DIRS:
                        nx, ny = x + dx, y + dy
                        if wall:
                            row.append(ny * bw + nx if 0 <= nx < bw and 0 <= ny < bh else -1)
                        else:
                            row.append((ny % bh) * bw + (nx % bw))
                    table.append(tuple(row))
            table = tuple(table)
            if len(cls._NEIGHBOUR_CACHE) > 16:
                cls._NEIGHBOUR_CACHE.clear()
            cls._NEIGHBOUR_CACHE[key] = table
        return table

    @staticmethod
    def _blocked_grid(blocked, bw, bh):
        grid = bytearray(bw * bh)
        for cell in blocked:
            x, y = cell[0], cell[1]
            if 0 <= x < bw and 0 <= y < bh:
                grid[y * bw + x] = 1
        return grid

    def _bfs(self, start, goal, blocked, ctx, portal_map, shuffle=False, node_budget=None):
        """BFS from start to goal over an integer grid. Returns the path as a list of (x, y) or None.
        Identical in result to _bfs_reference (same neighbour order, same portal handling, same budget rule)."""
        if goal is None:
            return None
        bw, bh, wall = ctx
        start = (start[0], start[1])
        goal = (goal[0], goal[1])
        if not (0 <= goal[0] < bw and 0 <= goal[1] < bh and 0 <= start[0] < bw and 0 <= start[1] < bh):
            return None
        order = [0, 1, 2, 3]
        if shuffle:
            self._rng.shuffle(order)
        nb = self._neighbour_table(bw, bh, wall)
        blk = self._blocked_grid(blocked, bw, bh)
        source, target = start[1] * bw + start[0], goal[1] * bw + goal[0]
        parents = [-2] * (bw * bh)
        parents[source] = -1
        pmap = None
        if portal_map:
            pmap = {}
            for a, b in portal_map.items():
                if 0 <= a[0] < bw and 0 <= a[1] < bh and 0 <= b[0] < bw and 0 <= b[1] < bh:
                    pmap[a[1] * bw + a[0]] = b[1] * bw + b[0]
        queue = collections.deque([source])
        pop, push = queue.popleft, queue.append
        expanded = 0
        budget = (max(1, int(node_budget)) if node_budget is not None else None)
        while queue:
            cur = pop()
            expanded += 1
            if cur == target:
                path = []
                node = cur
                while node != -1:
                    path.append((node % bw, node // bw))
                    node = parents[node]
                path.reverse()
                return path
            if budget is not None and expanded >= budget:
                break
            around = nb[cur]
            for k in order:
                n = around[k]
                if n < 0 or blk[n] or parents[n] != -2:
                    continue
                parents[n] = cur
                push(n)
                if pmap is not None and n in pmap:
                    ex = pmap[n]
                    if parents[ex] == -2 and not blk[ex]:
                        parents[ex] = n
                        push(ex)
        return None

    def _flood_fill(self, start, blocked, ctx):
        """Count cells reachable from start (integer grid). Same count as _flood_fill_reference."""
        bw, bh, wall = ctx
        sx, sy = start[0], start[1]
        if not (0 <= sx < bw and 0 <= sy < bh):
            return 0
        blk = self._blocked_grid(blocked, bw, bh)
        origin = sy * bw + sx
        if blk[origin]:
            return 0
        nb = self._neighbour_table(bw, bh, wall)
        blk[origin] = 1                       # the grid doubles as the visited set
        stack = [origin]
        count = 1
        while stack:
            for n in nb[stack.pop()]:
                if n >= 0 and not blk[n]:
                    blk[n] = 1
                    count += 1
                    stack.append(n)
        return count

    def _escape_dir(self, head, snake, blocked, ctx, looping):
        """
        Fallback: pick the safe direction with the most open space.
        Uses correct after-move blocked set (old head added, old tail removed).
        When looping, adds random noise to break ties.
        """
        best_d     = None
        best_score = -1
        dirs = list(self.DIRS)
        if looping:
            self._rng.shuffle(dirs)
        # after any move: old head joins body, old tail leaves
        after_base = (set(blocked) - {tuple(snake[-1])}) | {tuple(snake[0])}
        for d in dirs:
            nxt = self._step(head, d, ctx)
            if nxt is None or nxt in blocked:
                continue
            score = self._flood_fill(nxt, after_base, ctx)
            if looping:
                score += self._rng.uniform(0, 3)
            if score > best_score:
                best_score = score
                best_d     = d
        if best_d:
            return best_d
        safe = self._safe_dirs(head, blocked, ctx)
        return self._rng.choice(safe) if safe else self.DIRS[1]

    def _is_looping(self, window=8):
        """True if the snake's head has revisited the same cell in the last `window` steps."""
        if len(self._history) < window:
            return False
        recent = self._history[-window:]
        return len(recent) != len(set(recent))

    def _best_target(self, head, fruit, powerup_pos, ctx, margin):
        if not powerup_pos:
            return tuple(fruit)
        bw, bh, _ = ctx
        wall = ctx[2]
        if self._manhattan(head, powerup_pos, bw, bh, wall) < self._manhattan(head, fruit, bw, bh, wall) - margin:
            return tuple(powerup_pos)
        return tuple(fruit)

    def _manhattan(self, a, b, bw, bh, wall_collision=False):
        dx = abs(a[0] - b[0])
        dy = abs(a[1] - b[1])
        if wall_collision:
            return dx + dy
        return min(dx, bw - dx) + min(dy, bh - dy)

    def _dir_from(self, frm, to, ctx):
        bw, bh, wall = ctx
        dx = to[0] - frm[0]
        dy = to[1] - frm[1]
        if not wall:
            if abs(dx) > 1: dx = -1 if dx > 0 else 1
            if abs(dy) > 1: dy = -1 if dy > 0 else 1
        return (dx, dy)


def _run_ai_lab_benchmark(seed=20261005, scenario_count=32):
    """Compare current AI planning tiers on the same reproducible board states."""
    count = max(4, min(128, int(scenario_count)))
    rng = random.Random(str(seed))
    board_w, board_h = 16, 12
    scenarios = []
    for _ in range(count):
        hx = rng.randint(3, board_w - 4)
        hy = rng.randint(2, board_h - 3)
        snake = [(hx, hy), (hx - 1, hy), (hx - 2, hy)]
        protected = set(snake)
        protected.update(((hx + 1, hy), (hx, hy - 1), (hx, hy + 1)))
        free = [(x, y) for y in range(board_h) for x in range(board_w)
                if (x, y) not in protected]
        fruit = rng.choice(free)
        free.remove(fruit)
        obstacle_count = min(rng.randint(0, 14), len(free))
        obstacles = set(rng.sample(free, obstacle_count))
        opponents = []
        opponent_cells = {p for p in free if p not in obstacles and p != fruit}
        opponent_pairs = [
            (head, tail)
            for head in sorted(opponent_cells)
            for tail in ((head[0], head[1] - 1), (head[0], head[1] + 1))
            if tail in opponent_cells
        ]
        if opponent_pairs:
            opp_head, opp_tail = rng.choice(opponent_pairs)
            opponents = [opp_head, opp_tail]
        wall_collision = bool(rng.getrandbits(1))
        scenarios.append((snake, obstacles, fruit, opponents, wall_collision))

    original_choose = globals().get('_original_snake_ai_choose_direction')
    if not callable(original_choose):
        original_choose = SnakeAI.choose_direction
    results = {}
    for level in ('easy', 'medium', 'hard', 'impossible'):
        legal = 0
        closer = 0
        elapsed_ns = 0
        for scenario_index, (snake, obstacles, fruit, opponent, wall) in enumerate(scenarios):
            agent = SnakeAI(level, rng=random.Random(
                f'{seed}:{level}:{scenario_index}'))
            ctx = (board_w, board_h, wall)
            distance_before = agent._manhattan(
                snake[0], fruit, board_w, board_h, wall)
            started = time.perf_counter_ns()
            move = original_choose(
                agent, snake, obstacles, fruit, board_w, board_h,
                wall_collision=wall,
                opponent_snake=(opponent if level == 'impossible' else None))
            elapsed_ns += max(0, time.perf_counter_ns() - started)
            nxt = agent._step(snake[0], move, ctx)
            is_legal = (nxt is not None and nxt not in obstacles and
                        nxt not in set(snake[1:]))
            if is_legal:
                legal += 1
                distance_after = agent._manhattan(
                    nxt, fruit, board_w, board_h, wall)
                if distance_after < distance_before:
                    closer += 1
        results[level] = {
            'samples': count,
            'legal_percent': round(100.0 * legal / count, 1),
            'closer_percent': round(100.0 * closer / count, 1),
            'average_us': round(elapsed_ns / count / 1000.0, 2),
        }
    return results


##############
# AI LAB: many robots on one board, a speed that goes past what can be drawn, and a governor that keeps it stable
##############
LAB_LEVELS = ('noob', 'easy', 'medium', 'hard', 'impossible')
LAB_LEVEL_WEIGHT = {'noob': 1, 'easy': 2, 'medium': 4, 'hard': 8, 'impossible': 16}   # rough relative CPU cost
LAB_VISUAL_MAX_TPS = 120          # above this many ticks per second the board is no longer drawn (blind mode)
LAB_MAX_POPULATION = 400


class LabSnake:
    """One robot of the AI Lab. `body` is a deque of (x, y) cells, head first."""
    __slots__ = ('sid', 'level', 'home_level', 'ai', 'body', 'alive', 'score', 'deaths', 'spawned_at',
                 'respawn_at', 'decision_ns', 'decisions', 'last_cause')

    def __init__(self, sid, level, seed):
        self.sid = sid
        self.level = self.home_level = level
        self.ai = _lab_make_brain(level, random.Random(f'{seed}:{sid}'))
        self.body = collections.deque()
        self.alive = False
        self.score = self.deaths = self.decisions = 0
        self.spawned_at = 0
        self.respawn_at = 0
        self.decision_ns = 0          # CPU time of this snake's last decision, in nanoseconds
        self.last_cause = ''

    def set_level(self, level):
        self.level = level
        self.ai = _lab_make_brain(level, self.ai._rng)


class AILabArena:
    """A deterministic (seeded) arena with any number of AI snakes that compete for fruit.

    Snakes that die respawn after `respawn_delay` ticks, so the population stays steady for as long as the
    experiment runs. All levels use the same SnakeAI brain; they differ only in what that brain is allowed
    to see and think about. The arena never draws anything: a front end reads `snakes`, `fruits`, `obstacles`."""

    def __init__(self, levels=None, width=48, height=32, seed=0, wall_collision=True,
                 fruit_ratio=0.25, respawn_delay=12, obstacle_count=0):
        self.width, self.height = int(width), int(height)
        self.seed = seed
        self.rng = random.Random(f'{seed}:arena')
        self.wall_collision = bool(wall_collision)
        self.fruit_ratio = float(fruit_ratio)
        self.respawn_delay = int(respawn_delay)
        self.mix_pool = list(LAB_LEVELS)       # which levels the front end wants in the mix
        self.tick_count = 0
        self.snakes = []
        self.fruits = set()
        self.obstacles = set()
        self._next_sid = 0
        self.level_stats = {level: {'decisions': 0, 'decision_ns': 0, 'deaths': 0, 'fruits': 0, 'alive_ticks': 0}
                            for level in LAB_LEVELS}
        self.total_decisions = 0
        for _ in range(max(0, int(obstacle_count))):
            self.obstacles.add((self.rng.randrange(self.width), self.rng.randrange(self.height)))
        self.set_population(list(levels or ('easy', 'medium', 'hard', 'impossible')))

    # ---- population -----------------------------------------------------------
    def set_population(self, levels):
        """Make the arena hold exactly one snake per entry of `levels` (existing snakes are kept in order)."""
        levels = [lv if (lv in LAB_WEIGHT_LEVELS or lab_is_custom_level(lv)) else 'noob' for lv in levels][:LAB_MAX_POPULATION]
        while len(self.snakes) > len(levels):
            self.snakes.pop()
        for index, level in enumerate(levels):
            if index < len(self.snakes):
                self.snakes[index].home_level = level
                if self.snakes[index].level != level:
                    self.snakes[index].set_level(level)
            else:
                snake = self._make_snake(self._next_sid, level)
                self._next_sid += 1
                self.snakes.append(snake)
                self._spawn(snake)
        self._top_up_fruit()

    def _make_snake(self, sid, level):
        return LabSnake(sid, level, self.seed)

    def alive_snakes(self):
        return [s for s in self.snakes if s.alive]

    def _occupied(self):
        cells = set(self.obstacles) | self.fruits
        for s in self.snakes:
            cells.update(s.body)
        return cells

    def _free_cell(self, taken):
        width, height = self.width, self.height
        for _ in range(80):
            cell = (self.rng.randrange(width), self.rng.randrange(height))
            if cell not in taken:
                return cell
        free = [(x, y) for y in range(height) for x in range(width) if (x, y) not in taken]
        return self.rng.choice(free) if free else None

    def _spawn(self, snake):
        taken = self._occupied()
        for _ in range(60):
            head = self._free_cell(taken)
            if head is None:
                break
            dx, dy = self.rng.choice(SnakeAI.DIRS)
            cells = [(head[0] - dx * i, head[1] - dy * i) for i in range(3)]
            if all(0 <= x < self.width and 0 <= y < self.height and (x, y) not in taken for x, y in cells):
                snake.body = collections.deque(cells)
                snake.alive = True
                snake.spawned_at = self.tick_count
                return True
        snake.alive = False
        snake.respawn_at = self.tick_count + self.respawn_delay
        return False

    def _top_up_fruit(self):
        wanted = max(1, int(round(max(1, len(self.snakes)) * self.fruit_ratio)))
        while len(self.fruits) < wanted:
            cell = self._free_cell(self._occupied())
            if cell is None:
                break
            self.fruits.add(cell)

    # ---- one tick ----------------------------------------------------------------
    def tick(self):
        """Advance every snake one cell. Returns the number of AI decisions made."""
        width, height, wall = self.width, self.height, self.wall_collision
        for s in self.snakes:
            if not s.alive and self.tick_count >= s.respawn_at:
                self._spawn(s)
        alive = [s for s in self.snakes if s.alive]
        everything = set(self.obstacles)
        for s in alive:
            everything.update(s.body)
        fruits = list(self.fruits)
        moves = {}
        decisions = 0
        clock = time.perf_counter_ns
        for s in alive:
            body = list(s.body)
            head = body[0]
            started = clock()
            if hasattr(s.ai, 'decide'):
                near = min(fruits, key=lambda f: abs(f[0] - head[0]) + abs(f[1] - head[1])) if fruits else None
                direction = s.ai.decide({'width': width, 'height': height, 'wall': wall, 'body': body,
                                         'others': [list(o.body) for o in alive if o is not s],
                                         'obstacles': self.obstacles, 'fruit': near, 'fruit_value': 1.0, 'speed': 0.5})
            elif s.level == 'noob':
                direction = s.ai.choose_direction(body, (), None, width, height, wall_collision=wall)
            else:
                occupied = everything.difference(body)
                fruit = min(fruits, key=lambda f: abs(f[0] - head[0]) + abs(f[1] - head[1])) if fruits else head
                opponent = None
                if s.level == 'impossible':
                    others = [o for o in alive if o is not s]
                    if others:
                        near = min(others, key=lambda o: abs(o.body[0][0] - head[0]) + abs(o.body[0][1] - head[1]))
                        opponent = list(near.body)
                direction = s.ai.choose_direction(body, occupied, fruit, width, height,
                                                  wall_collision=wall, opponent_snake=opponent)
            spent = clock() - started
            s.decision_ns = spent
            s.decisions += 1
            decisions += 1
            stat = self.level_stats.setdefault(s.level, {'decisions': 0, 'decision_ns': 0, 'deaths': 0, 'fruits': 0, 'alive_ticks': 0})
            stat['decisions'] += 1
            stat['decision_ns'] += spent
            stat['alive_ticks'] += 1
            moves[s.sid] = direction
        dead = []
        for s in alive:
            dx, dy = moves[s.sid]
            nx, ny = s.body[0][0] + dx, s.body[0][1] + dy
            if wall:
                if not (0 <= nx < width and 0 <= ny < height):
                    dead.append((s, 'wall'))
                    continue
            else:
                nx, ny = nx % width, ny % height
            s.body.appendleft((nx, ny))
            if (nx, ny) in self.fruits:
                self.fruits.discard((nx, ny))
                s.score += 1
                self.level_stats.setdefault(s.level, {'decisions': 0, 'decision_ns': 0, 'deaths': 0, 'fruits': 0, 'alive_ticks': 0})['fruits'] += 1
            else:
                s.body.pop()
        counts = {}
        for s in alive:
            if any(d is s for d, _ in dead):
                continue
            for cell in s.body:
                counts[cell] = counts.get(cell, 0) + 1
        for s in alive:
            if any(d is s for d, _ in dead):
                continue
            head = s.body[0]
            if head in self.obstacles:
                dead.append((s, 'obstacle'))
            elif counts[head] > 1:
                dead.append((s, 'collision'))
        for s, cause in dead:
            s.alive = False
            s.body.clear()
            s.deaths += 1
            s.last_cause = cause
            s.respawn_at = self.tick_count + self.respawn_delay
            self.level_stats.setdefault(s.level, {'decisions': 0, 'decision_ns': 0, 'deaths': 0, 'fruits': 0, 'alive_ticks': 0})['deaths'] += 1
        self.tick_count += 1
        self.total_decisions += decisions
        self._top_up_fruit()
        return decisions


LAB_WEIGHT_LEVELS = frozenset(LAB_LEVELS)


class LabGovernor:
    """The dynamic fuse: when the simulation cannot keep up with the requested speed, first swap the heaviest
    robots for the lightest one (Noob) and only then remove robots; when there is room again, bring them back.

    `ceiling` is the population the player asked for (the density slider). The governor never goes above it
    and never below `min_population`."""

    def __init__(self, ceiling, min_population=2, patience=3, calm_frames=30):
        self.ceiling = max(1, int(ceiling))
        self.min_population = max(1, int(min_population))
        self.patience = max(1, int(patience))
        self.calm_frames = max(1, int(calm_frames))
        self.strikes = 0
        self.calm = 0
        self.sheds = 0
        self.restores = 0

    def observe(self, arena, behind):
        """Call once per frame; `behind` is True when the arena could not run all the ticks that were due."""
        if behind:
            self.calm = 0
            self.strikes += 1
            if self.strikes >= self.patience:
                self.strikes = 0
                return self.shed(arena)
            return None
        self.strikes = 0
        self.calm += 1
        if self.calm >= self.calm_frames:
            self.calm = 0
            return self.restore(arena)
        return None

    def shed(self, arena):
        heavy = sorted((s for s in arena.snakes if LAB_LEVEL_WEIGHT.get(s.level, 8) > LAB_LEVEL_WEIGHT['noob']),
                       key=lambda s: -LAB_LEVEL_WEIGHT.get(s.level, 8))
        if heavy:
            for s in heavy[:max(1, len(heavy) // 4)]:
                s.set_level('noob')
            self.sheds += 1
            return 'downgrade'
        if len(arena.snakes) > self.min_population:
            keep = max(self.min_population, int(len(arena.snakes) * 0.85))
            arena.set_population([s.home_level for s in arena.snakes][:keep])
            self.sheds += 1
            return 'remove'
        return None

    def restore(self, arena):
        wanted = [s.home_level for s in arena.snakes]
        for s in arena.snakes:
            if s.level != s.home_level:
                s.set_level(s.home_level)
                self.restores += 1
                return 'upgrade'
        if len(arena.snakes) < self.ceiling and wanted:
            arena.set_population(wanted + [_lab_mix(len(wanted) + 1, arena.mix_pool)[-1]])
            self.restores += 1
            return 'add'
        return None


class AILabSimulation:
    """Drives an AILabArena from a front end's frame loop.

    `target_tps` is how many ticks per second the player asked for (None = as many as possible).
    Up to LAB_VISUAL_MAX_TPS the board is drawn each frame (`blind` is False); above it nothing is drawn and
    the frame is spent on simulation (`blind` is True). `resource` (0 to 1) is how much of each frame the
    simulation may use."""

    def __init__(self, arena, target_tps=30.0, resource=0.5, ceiling=None, frame_ms=16.0):
        self.arena = arena
        self.target_tps = target_tps
        self.resource = max(0.0, min(1.0, float(resource)))
        self.frame_ms = float(frame_ms)
        self.governor = LabGovernor(ceiling if ceiling is not None else len(arena.snakes))
        self.fuse_enabled = True           # the lab screen turns this off unless the player asks for it
        self.render_mode = 'auto'          # 'auto': draw while the speed is at or below visual_limit; 'always'; 'never'
        self.visual_limit = LAB_VISUAL_MAX_TPS
        self.reduce = False                # True: the simulation only uses half of its usual share of each frame
        self._owed = 0.0
        self.ticks_last_frame = 0
        self.decisions_last_frame = 0
        self.sim_ms_last_frame = 0.0
        self.rate_window = collections.deque(maxlen=60)    # (seconds, ticks, decisions) of recent frames

    @property
    def blind(self):
        if self.render_mode == 'never':
            return True
        if self.render_mode == 'always':
            return False
        return self.target_tps is None or self.target_tps > self.visual_limit

    def slice_ms(self):
        """How long the simulation may run in one frame."""
        share = (0.2 + 0.75 * self.resource) if self.blind else (0.15 + 0.5 * self.resource)
        return self.frame_ms * share * (0.5 if self.reduce else 1.0)

    def advance(self, dt_seconds):
        """Run the ticks that are due (or as many as fit in this frame's slice). Returns the ticks executed."""
        started = time.perf_counter()
        budget = self.slice_ms() / 1000.0
        ticks = decisions = 0
        behind = False
        if self.target_tps is None:
            while time.perf_counter() - started < budget:
                decisions += self.arena.tick()
                ticks += 1
        else:
            self._owed = min(self._owed + max(0.0, dt_seconds) * float(self.target_tps), float(self.target_tps))
            while self._owed >= 1.0:
                if time.perf_counter() - started >= budget:
                    behind = True
                    break
                decisions += self.arena.tick()
                ticks += 1
                self._owed -= 1.0
        spent = time.perf_counter() - started
        self.ticks_last_frame, self.decisions_last_frame = ticks, decisions
        self.sim_ms_last_frame = spent * 1000.0
        self.rate_window.append((max(dt_seconds, 1e-6), ticks, decisions))
        if self.fuse_enabled:
            self.governor.observe(self.arena, behind)
        return ticks

    def rates(self):
        """(ticks per second, AI decisions per second) over the recent frames."""
        seconds = sum(w[0] for w in self.rate_window)
        if seconds <= 0:
            return 0.0, 0.0
        return sum(w[1] for w in self.rate_window) / seconds, sum(w[2] for w in self.rate_window) / seconds


def _lab_mix(population, levels=None):
    """A repeatable list of `population` levels cycling through `levels` (all five by default)."""
    pool = [lv for lv in (levels or LAB_LEVELS) if lv in LAB_WEIGHT_LEVELS] or ['noob']
    return [pool[i % len(pool)] for i in range(max(1, int(population)))]


def _lab_worker_run(config):
    """One CPU core's share of a stress test: its own arena, run flat out for `seconds` of wall time.
    Module-level so a separate process can import and run it."""
    if _lab_is_worker_process():
        lab_set_low_priority(True)
    arena = AILabArena(_lab_mix(config['population'], config.get('levels')), width=config.get('width', 48),
                       height=config.get('height', 32), seed=f"{config.get('seed', 0)}:{config.get('worker', 0)}",
                       wall_collision=config.get('wall_collision', True))
    seconds = max(0.05, float(config['seconds']))
    started = time.perf_counter()
    while time.perf_counter() - started < seconds:
        arena.tick()
    elapsed = time.perf_counter() - started
    return {'ticks': arena.tick_count, 'decisions': arena.total_decisions, 'seconds': elapsed,
            'level_stats': {lv: dict(st) for lv, st in arena.level_stats.items()}}


def run_ai_lab_stress_test(seconds=3.0, population=16, workers=1, levels=None, seed=0):
    """Hardware stress test: AI decisions per second the machine sustains. `workers` > 1 runs that many
    independent arenas in separate processes (Python threads cannot use more than one core). The headline
    number, the "SGF Score", is decisions per second summed over all workers."""
    workers = max(1, min(int(workers), os.cpu_count() or 1))
    base = {'seconds': seconds, 'population': population, 'levels': levels, 'seed': seed}
    configs = [dict(base, worker=i) for i in range(workers)]
    started = time.perf_counter()
    if workers == 1:
        results = [_lab_worker_run(configs[0])]
        used = 1
    else:
        try:
            import multiprocessing
            from concurrent.futures import ProcessPoolExecutor
            # The workers import this program; keep them from opening audio or a window while they do.
            saved_env = {k: os.environ.get(k) for k in ('SDL_AUDIODRIVER', 'SDL_VIDEODRIVER', 'PYGAME_HIDE_SUPPORT_PROMPT')}
            os.environ.update({'SDL_AUDIODRIVER': 'dummy', 'SDL_VIDEODRIVER': 'dummy', 'PYGAME_HIDE_SUPPORT_PROMPT': '1'})
            try:
                with ProcessPoolExecutor(max_workers=workers, mp_context=multiprocessing.get_context('spawn')) as pool:
                    results = list(pool.map(_lab_worker_run, configs))
            finally:
                for key, value in saved_env.items():
                    if value is None:
                        os.environ.pop(key, None)
                    else:
                        os.environ[key] = value
            used = workers
        except Exception as exc:                     # no extra processes available: do it in this one
            _logging_mod.getLogger('sgf').warning('Parallel stress test unavailable (%s); running on one core', exc)
            results = [_lab_worker_run(configs[0])]
            used = 1
    wall = max(1e-6, time.perf_counter() - started)
    decisions = sum(r['decisions'] for r in results)
    ticks = sum(r['ticks'] for r in results)
    busy = max(r['seconds'] for r in results)
    per_level = {}
    for lv in LAB_LEVELS:
        n = sum(r['level_stats'][lv]['decisions'] for r in results)
        ns = sum(r['level_stats'][lv]['decision_ns'] for r in results)
        if n:
            per_level[lv] = round(ns / n / 1000.0, 2)
    return {'score': int(decisions / busy), 'decisions': decisions, 'ticks_per_second': int(ticks / busy),
            'workers': used, 'population': int(population), 'seconds': round(busy, 2),
            'wall_seconds': round(wall, 2), 'microseconds_per_decision': per_level}


def lab_set_low_priority(low=True):
    """Keep the operating system responsive while the lab hammers the CPU. Windows: below-normal priority for
    this process (and back to normal when `low` is False). Elsewhere only worker processes are niced, because
    a normal user cannot raise a process's priority again."""
    try:
        if os.name == 'nt':
            import ctypes
            kernel = ctypes.windll.kernel32
            return bool(kernel.SetPriorityClass(kernel.GetCurrentProcess(), 0x00004000 if low else 0x00000020))
        if low and _lab_is_worker_process():
            os.nice(10)
            return True
    except Exception:
        pass
    return False


def _lab_is_worker_process():
    try:
        import multiprocessing
        return multiprocessing.parent_process() is not None
    except Exception:
        return False


def _lab_shard_main(config, stop_event, ticks_value, decisions_value):
    """A background worker of the AI Lab: its own arena, ticking until told to stop, publishing its counters."""
    lab_set_low_priority(True)
    arena = AILabArena(_lab_mix(config['population'], config.get('levels')), width=config.get('width', 48),
                       height=config.get('height', 32), seed=f"{config.get('seed', 0)}:shard{config.get('worker', 0)}",
                       wall_collision=config.get('wall_collision', True))
    while not stop_event.is_set():
        for _ in range(20):
            arena.tick()
        ticks_value.value = arena.tick_count
        decisions_value.value = arena.total_decisions


class LabShardPool:
    """Extra CPU cores for the live AI Lab: separate processes that each simulate their own arena at full speed
    (Python threads share one core, so only processes add real parallelism). They are started in the
    background (a worker needs a second or two to load the program) and always stopped when the lab closes."""

    def __init__(self):
        self.procs, self.counters = [], []
        self.stop_event = None
        self.error = ''
        self._starting = False

    @property
    def starting(self):
        return self._starting

    def start(self, workers, config):
        if self.procs or self._starting or workers < 1:
            return
        self._starting = True
        threading.Thread(target=self._launch, args=(workers, config), name='lab-shards', daemon=True).start()

    def _launch(self, workers, config):
        saved = {k: os.environ.get(k) for k in ('SDL_AUDIODRIVER', 'SDL_VIDEODRIVER', 'PYGAME_HIDE_SUPPORT_PROMPT')}
        try:
            import multiprocessing
            ctx = multiprocessing.get_context('spawn')
            os.environ.update({'SDL_AUDIODRIVER': 'dummy', 'SDL_VIDEODRIVER': 'dummy', 'PYGAME_HIDE_SUPPORT_PROMPT': '1'})
            stop = ctx.Event()
            procs, counters = [], []
            for index in range(workers):
                ticks, decisions = ctx.Value('Q', 0), ctx.Value('Q', 0)
                proc = ctx.Process(target=_lab_shard_main, args=(dict(config, worker=index + 1), stop, ticks, decisions),
                                   daemon=True)
                proc.start()
                procs.append(proc)
                counters.append((ticks, decisions))
            self.stop_event, self.counters, self.procs = stop, counters, procs
        except Exception as exc:
            self.error = str(exc)
            _logging_mod.getLogger('sgf').warning('AI Lab workers could not start: %s', exc)
        finally:
            for key, value in saved.items():
                if value is None:
                    os.environ.pop(key, None)
                else:
                    os.environ[key] = value
            self._starting = False

    def totals(self):
        """(ticks, decisions) done by all workers so far."""
        try:
            return (sum(t.value for t, _d in self.counters), sum(d.value for _t, d in self.counters))
        except Exception:
            return 0, 0

    def stop(self, wait=3.0):
        deadline = time.monotonic() + wait
        while self._starting and time.monotonic() < deadline:
            time.sleep(0.02)
        if self.stop_event is not None:
            self.stop_event.set()
        for proc in self.procs:
            proc.join(max(0.05, deadline - time.monotonic()))
            if proc.is_alive():
                proc.terminate()
        self.procs, self.counters, self.stop_event = [], [], None


def record_lab_score(result):
    """Keep the latest AI Lab stress-test result so the Data tab's diagnostics export can include it."""
    entry = {'score': int(result.get('score', 0)), 'decisions': int(result.get('decisions', 0)),
             'ticks_per_second': int(result.get('ticks_per_second', 0)), 'workers': int(result.get('workers', 1)),
             'population': int(result.get('population', 0)), 'seconds': float(result.get('seconds', 0.0)),
             'microseconds_per_decision': dict(result.get('microseconds_per_decision', {})),
             'cpu_count': os.cpu_count() or 1, 'platform': sys.platform,
             'when': datetime.now().isoformat(timespec='seconds')}
    global _LAB_LAST_RESULT
    _LAB_LAST_RESULT = entry

    def mutate(data):
        data['ai_lab_score'] = entry
        return data
    try:
        _save_data_async(mutate)
    except Exception as exc:
        _logging_mod.getLogger('sgf').warning('Could not store the AI Lab score: %s', exc)
    return entry


_LAB_LAST_RESULT = None


def lab_last_score():
    """The most recent stress-test result: this session's, else the one saved on disk, else None."""
    if _LAB_LAST_RESULT is not None:
        return dict(_LAB_LAST_RESULT)
    try:
        saved = _load_data().get('ai_lab_score')
        return dict(saved) if isinstance(saved, dict) else None
    except Exception:
        return None


