STUDIO_STEPS = (5000, 20000, 60000, 200000, 1000000)
STUDIO_BOARDS = ((10, 8), (14, 10), (20, 14), (30, 20))
STUDIO_HIDDEN = ((16,), (24,), (32,), (64,), (32, 32), (64, 32))
STUDIO_BOTS = (None, 'noob', 'easy', 'medium', 'hard', 'impossible')


def _studio_label(language, key, **values):
    table = _STUDIO_LABELS.get(language) or _STUDIO_LABELS['en']
    text = table.get(key) or _STUDIO_LABELS['en'].get(key, key)
    try:
        return text.format(**values) if values else text
    except (KeyError, IndexError, ValueError):
        return text


def ai_model_with_inputs(model, inputs, seed=0):
    """A copy of `model` that sees `inputs` instead: weights of inputs it already had are kept, new inputs start small."""
    inputs = [k for k in AI_INPUT_KEYS if k in set(inputs)] or ['wall']
    old_names = model.input_names
    new_names = ai_input_names(inputs)
    rng = random.Random(f'inputs:{model.name}:{seed}')
    first_w, first_b = model.layers[0]
    column = {name: index for index, name in enumerate(old_names)}
    limit = 1.0 / math.sqrt(max(1, len(new_names)))
    rows = [[row[column[n]] if n in column else rng.uniform(-limit, limit) * 0.5 for n in new_names] for row in first_w]
    layers = [(rows, list(first_b))] + [([list(r) for r in w], list(b)) for w, b in model.layers[1:]]
    meta = dict(model.meta)
    clone = AIModel(model.name, inputs, model.hidden, model.activation, layers, meta)
    clone.validate()
    return clone


class _StudioJob:
    """Something the studio does in the background while a progress bar tells the player what is happening."""

    def __init__(self, label_key, **label_values):
        self.label_key, self.label_values = label_key, label_values
        self.progress = 0.0
        self.stop = False
        self.done = False
        self.result = None
        self.error = ''
        self.checkpoints = []
        self.kind = 'steps'               # for training: 'steps', 'time' or 'continuous'
        self.total_seconds = 0.0          # for a timed run
        self.started = time.monotonic()
        self.display_key = None           # the label shown while it runs, when it differs from label_key
        self.base_steps = 0               # what the AI had trained before this run
        self.power = {}                   # which power-saving protections the training managed to switch off (Windows)
        self.samples = collections.deque(maxlen=64)   # (time, steps) pairs, for the steps per second
        self.rate = 0.0                   # steps per second, over the last few seconds
        self.steps_done = 0               # steps of this run so far (updated while it trains)


class AIStudioScreen:
    """Build an AI, choose what it can see and how it is rewarded, train it with reinforcement learning, rate it, and keep
    it in the game (or share it as a .sgfai file)."""

    def __init__(self, settings, screen):
        self.settings, self.screen = settings, screen
        self.language = settings.language
        ai_library_load_all()
        self.hits = {}
        self.scroll = 0
        self.job = None
        self.message = ''
        self.edit_target, self.editor = None, None                        # the text box being typed into: 'name', a number box or 'wr:<reward>'
        self.repeater, self.now = KeyRepeater(), pygame.time.get_ticks
        self.name_draft = ''                                              # what the name box shows; the AI keeps its last non-empty name meanwhile
        self.history, self.session_steps, self.explore_restart = [], 0, False   # chart so far; steps of the last training; start exploring from 100% again
        self.window_active = pygame.display.get_active                   # False while the window is minimised
        self.chart, self.chart_rect, self.mouse_pos = TrainingChart(), None, pygame.mouse.get_pos
        self.chart_rates = (('steps', 500), ('steps', 5000), ('seconds', 1.0), ('seconds', 5.0), ('seconds', 30.0))   # how often the chart takes new points
        self.chart_rate_index, self._chart_at = 0, (0.0, 0)
        self.speed = {'visible': [0, 0.0], 'minimized': [0, 0.0]}        # steps and seconds of the last training, by window state
        self._speed_last = None
        self._name_area = self._name_font = None
        self.confirm = None                                               # a question waiting for Yes or Cancel: {'text', 'yes'}
        self.state_bytes = 0                                              # size of the saved training state of this AI
        self.saved_steps, self._setup_seen = 0, None                      # steps the AI had when it was last saved; the set-up last written
        self.preset_index = 0
        self.mode_index, self.learners, self.bots_index = 0, 1, 0
        self.board_index, self.powerups = 1, True
        self.board_w, self.board_h = STUDIO_BOARDS[self.board_index]     # the board is any size from 3x3 to 100x100
        self.duration_kind = 'steps'                                      # 'steps', 'time' or 'continuous'
        self.duration_hms = [0, 10, 0]                                    # used when the duration is by time
        self.steps_index, self.hidden_index, self.activation_index = 1, 1, 0
        self.checkpoints = []
        self.model = None
        self.reward = rl_reward_spec()
        self.setup_last = self._read_last_setup()
        self.user_presets = rl_user_presets_load()                           # the player's own reward presets
        names = sorted(AI_REGISTRY)
        self._adopt(AI_REGISTRY[names[0]] if names else AIModel.new('My AI', hidden=STUDIO_HIDDEN[self.hidden_index]))

    # ---- model and settings -----------------------------------------------------------------
    def _adopt(self, model):
        self.model = model
        self.name_draft = model.name
        self.edit_target, self.editor = None, None
        self.confirm = None
        rl = model.meta.get('rl') if isinstance(model.meta.get('rl'), dict) else {}
        self.saved_steps = int(rl.get('steps_trained', 0)) if isinstance(rl.get('steps_trained'), (int, float)) else 0
        self.state_bytes = rl_state_size(model.name)
        self._setup_apply(rl_clean_setup(model.meta.get('studio')) or self.setup_last)          # this AI's own set-up, or the one used last
        if tuple(model.hidden) in STUDIO_HIDDEN:                                                # the layer buttons start at what the AI really has
            self.hidden_index = STUDIO_HIDDEN.index(tuple(model.hidden))
        if model.activation in AI_ACTIVATIONS:
            self.activation_index = AI_ACTIVATIONS.index(model.activation)
        self._setup_seen = self._setup_snapshot()
        self.reward = dict(rl_reward_spec(), **{k: float(v) for k, v in (rl.get('reward') or {}).items() if k in RL_REWARD_KEYS})
        self.history, self.checkpoints, self.session_steps = rl_clean_history(rl), [], 0

    # ---- the set-up (mode, learners, bots, board, duration, layers...) is remembered ----------------
    def _setup_snapshot(self):
        return {'mode': self.mode_index, 'learners': self.learners, 'bots': self.bots_index, 'board': [self.board_w, self.board_h],
                'powerups': bool(self.powerups), 'duration': self.duration_kind, 'hms': list(self.duration_hms), 'steps': self.steps_index,
                'hidden': self.hidden_index, 'activation': self.activation_index, 'explore_restart': bool(self.explore_restart),
                'chart_mode': self.chart.mode, 'chart_rate': self.chart_rate_index}

    def _setup_apply(self, data):
        if not data:
            return
        self.mode_index, self.learners, self.bots_index = data.get('mode', self.mode_index), data.get('learners', self.learners), data.get('bots', self.bots_index)
        self.board_w, self.board_h = data.get('board', [self.board_w, self.board_h])
        self.board_index = STUDIO_BOARDS.index((self.board_w, self.board_h)) if (self.board_w, self.board_h) in STUDIO_BOARDS else self.board_index
        self.powerups, self.duration_kind = data.get('powerups', self.powerups), data.get('duration', self.duration_kind)
        self.duration_hms = list(data.get('hms', self.duration_hms))
        self.steps_index, self.hidden_index = data.get('steps', self.steps_index), data.get('hidden', self.hidden_index)
        self.activation_index, self.explore_restart = data.get('activation', self.activation_index), data.get('explore_restart', self.explore_restart)
        self.chart.mode, self.chart_rate_index = data.get('chart_mode', self.chart.mode), data.get('chart_rate', self.chart_rate_index)

    @staticmethod
    def _setup_path():
        return os.path.join(studio_data_dir(), '_studio_setup.json')

    def _read_last_setup(self):
        try:
            with open(self._setup_path(), 'r', encoding='utf-8') as handle:
                return rl_clean_setup(json.load(handle))
        except (OSError, ValueError):
            return {}

    def _setup_tick(self):
        """Called every frame: when the set-up changed, keep it with the AI (so it goes with the saved file) and as the last used one."""
        snapshot = self._setup_snapshot()
        if snapshot == self._setup_seen:
            return
        self._setup_seen = snapshot
        self.setup_last = rl_clean_setup(snapshot)
        if self.model is not None:
            self.model.meta['studio'] = snapshot
        try:
            os.makedirs(studio_data_dir(), exist_ok=True)
            _atomic_write_json(self._setup_path(), snapshot)
        except OSError:
            pass                                                            # not being able to remember the set-up is never fatal

    # ---- a question that needs Yes or Cancel ----------------------------------------------------
    def _ask(self, key, yes, **values):
        self.confirm = {'text': _studio_label(self.language, key, **values), 'yes': yes}

    def unsaved_steps(self):
        rl = self.model.meta.get('rl') if isinstance(self.model.meta.get('rl'), dict) else {}
        steps = int(rl.get('steps_trained', 0)) if isinstance(rl.get('steps_trained'), (int, float)) else 0
        return max(0, steps - self.saved_steps)

    def layout_pending(self):
        """True when the layer buttons ask for something other than what the AI has (it only changes on Rebuild)."""
        return tuple(STUDIO_HIDDEN[self.hidden_index]) != tuple(self.model.hidden) or AI_ACTIVATIONS[self.activation_index] != self.model.activation

    def env_config(self):
        width, height = self.board_w, self.board_h
        mode = ('solo', 'versus', 'coop', 'mixed')[self.mode_index]
        return {'mode': mode, 'learners': self.learners, 'bots': [STUDIO_BOTS[self.bots_index]] if STUDIO_BOTS[self.bots_index] else [],
                'width': width, 'height': height, 'powerups': self.powerups, 'max_steps': rl_default_max_steps(width, height)}

    # ---- number boxes (board size and training time) --------------------------------------------
    FIELDS = {'sz_w': (RL_BOARD_MIN, RL_BOARD_MAX, 1), 'sz_h': (RL_BOARD_MIN, RL_BOARD_MAX, 1),
              't_h': (0, 99, 1), 't_m': (0, 5999, 1), 't_s': (0, 359999, 10)}     # (lowest, highest, step of the - / + buttons)

    def validation(self):
        return rl_validate_config(self.env_config())

    def validation_text(self, item):
        return _studio_label(self.language, item[0], **item[1])

    def total_seconds(self):
        hours, minutes, seconds = self.duration_hms
        return hours * 3600 + minutes * 60 + seconds

    def _get_field(self, name):
        if name == 'sz_w':
            return self.board_w
        if name == 'sz_h':
            return self.board_h
        return self.duration_hms[('t_h', 't_m', 't_s').index(name)]

    def _set_field(self, name, value):
        """Store a typed or stepped value; anything out of range is brought into range and the player is told."""
        low, high, _step = self.FIELDS[name]
        clamped = max(low, min(high, int(value)))
        if clamped != value:
            self.message = _studio_label(self.language, 'clamped', min=low, max=high, value=clamped)
        if name == 'sz_w':
            self.board_w = clamped
        elif name == 'sz_h':
            self.board_h = clamped
        else:
            self.duration_hms[('t_h', 't_m', 't_s').index(name)] = clamped
            total = self.total_seconds()
            fitted = max(RL_MIN_SECONDS, min(RL_MAX_SECONDS, total))
            if fitted != total:
                self.message = _studio_label(self.language, 'time_range', value=_fmt_hms(fitted))
            self.duration_hms = [fitted // 3600, fitted % 3600 // 60, fitted % 60]      # 90 minutes becomes 1 h 30 m

    # ---- typing into a box (the name, a number box, a reward value) -------------------------------
    TEXT_HITS = ('rename', 'sz_w', 'sz_h', 't_h', 't_m', 't_s', 'rw_name')

    def is_text_hit(self, name):
        return name in self.TEXT_HITS or name.startswith('wr_')

    @staticmethod
    def _hit_name(target):
        return 'rename' if target == 'name' else ('rw_name' if target == 'preset_name' else ('wr_' + target[3:] if target.startswith('wr:') else target))

    def _start_edit(self, target, pos=None):
        self._commit_edit()
        if target == 'name':
            editor = TextEditor(self.name_draft, 40, lambda ch: ch.isalnum() or ch in ' -_')
            if pos is not None and self._name_area is not None:
                editor.caret = editor.caret_from_x(pos[0] - self._name_area.x, self._name_font)
        elif target == 'preset_name':
            current = self.matching_preset()
            editor = TextEditor(current if current in self.user_presets else '', RL_PRESET_NAME_MAX, lambda ch: ch.isalnum() or ch in ' -_')
        elif target in self.FIELDS:
            editor = TextEditor('', 6, lambda ch: ch.isascii() and ch.isdigit())
        else:
            editor = TextEditor(format_decimal(self.reward.get(target[3:], 0.0)), 24, lambda ch: ch in '0123456789.,-+')
        self.edit_target, self.editor = target, editor

    def _stop_edit(self):
        self.edit_target, self.editor = None, None
        self.repeater.release()

    def _commit_edit(self):
        target, editor = self.edit_target, self.editor
        self._stop_edit()
        if target is None or target == 'name':
            return                                                          # the name is applied as it is typed
        if target == 'preset_name':
            self._save_preset(editor.text)
            return
        text = editor.text.strip()
        if target in self.FIELDS:
            if text.isascii() and text.isdigit():
                self._set_field(target, int(text))
            return
        value, problem = parse_reward_text(text)
        if problem:
            self.message = _studio_label(self.language, problem, max=f'{RL_REWARD_LIMIT:,.0f}')
            return
        self.reward[target[3:]] = value                                      # exactly what was typed, no rounding
        if abs(value) > RL_REWARD_WARN:
            self.message = _studio_label(self.language, 'reward_big', value=format_decimal(value))

    def _edit_changed(self):
        if self.edit_target == 'name':
            self.name_draft = self.editor.text
            if self.name_draft.strip():
                self.model.name = self.name_draft.strip()

    def _update_speed(self, job, now, steps, active):
        """Steps per second over the last few seconds, and the average speed of this training while the window was visible and
        while it was minimised (so a slowdown when minimising shows up as a number, not a feeling)."""
        if self._speed_last is not None:
            last_time, last_steps = self._speed_last
            if steps >= last_steps and now > last_time:
                bucket = self.speed['visible' if active else 'minimized']
                bucket[0] += steps - last_steps
                bucket[1] += now - last_time
        self._speed_last = (now, steps)
        if not job.samples or job.samples[-1][1] != steps:
            job.samples.append((now, steps))
        window = [(t, n) for t, n in job.samples if now - t <= 5.0]
        if len(window) >= 2 and window[-1][0] > window[0][0]:
            job.rate = (window[-1][1] - window[0][1]) / (window[-1][0] - window[0][0])

    def speed_text(self):
        seen, hidden = self.speed['visible'], self.speed['minimized']
        if seen[1] >= 3.0 and hidden[1] >= 3.0:
            return _studio_label(self.language, 'speed_both', visible=f'{seen[0] / seen[1]:,.0f}', minimized=f'{hidden[0] / hidden[1]:,.0f}')
        total_steps, total_time = seen[0] + hidden[0], seen[1] + hidden[1]
        return _studio_label(self.language, 'speed_avg', sps=f'{total_steps / total_time:,.0f}') if total_time >= 3.0 else ''

    def chart_points(self):
        """Everything trained so far (earlier sessions, then this one), in steps trained."""
        return self.history + [p for p in self.checkpoints if 'total' in p]

    def _chart_wheel(self, direction):
        """The wheel over the chart zooms it (towards the pointer) instead of scrolling the list; False when not over the chart."""
        plot = self.chart.last_plot
        mouse = self.mouse_pos()
        if self.chart_rect is None or plot is None or not self.chart_rect.collidepoint(mouse) or direction == 0:
            return False
        anchor = max(0.0, min(1.0, (mouse[0] - plot.x) / float(plot.w)))
        self.chart.zoom(self.chart_points(), 0.8 if direction > 0 else 1.25, anchor)
        return True

    def _chart_drag(self, pos):
        plot = self.chart.last_plot
        if plot is None or self.chart.drag is None:
            return
        start_x, (start, end) = self.chart.drag
        self.chart.pan_from(self.chart_points(), (start, end), -(pos[0] - start_x) / float(plot.w) * (end - start))

    def _chart_due(self, now, steps):
        """Whether the chart should take the new points now, by the update rate the player chose."""
        kind, amount = self.chart_rates[self.chart_rate_index]
        last_time, last_steps = self._chart_at
        return (steps - last_steps >= amount) if kind == 'steps' else (now - last_time >= amount)

    def update_input(self):
        """Once per frame: replay the held key (Backspace, arrows, letters) while a box is being typed into."""
        if self.editor is None:
            self.repeater.release()
            return
        for event in self.repeater.poll(self.now()):
            if self.editor is not None and self.editor.key(event) == 'changed':
                self._edit_changed()

    # ---- reward presets, copy and paste -----------------------------------------------------------
    def matching_preset(self):
        """The name of the preset whose values are exactly the ones on screen, or None (the player changed something)."""
        for name in rl_preset_names(self.user_presets):
            if rl_preset_values(name, self.user_presets) == self.reward:
                return name
        return None

    def _save_preset(self, raw_name):
        name = ' '.join(str(raw_name).split())
        if not name:
            self.message = _studio_label(self.language, 'preset_name_empty')
        elif name in RL_REWARD_PRESETS:
            self.message = _studio_label(self.language, 'preset_name_builtin', name=name)
        elif name not in self.user_presets and len(self.user_presets) >= RL_PRESET_MAX:
            self.message = _studio_label(self.language, 'preset_limit', n=RL_PRESET_MAX)
        else:
            self.user_presets[name] = {key: float(self.reward[key]) for key in RL_REWARD_KEYS if key in self.reward}
            try:
                rl_user_presets_save(self.user_presets)
            except OSError as exc:
                self.message = _studio_label(self.language, 'preset_failed', reason=f'{type(exc).__name__}: {exc}')
                return
            self.preset_index = rl_preset_names(self.user_presets).index(name)
            self.message = _studio_label(self.language, 'preset_saved', name=name)

    def delete_preset(self, confirmed=False):
        name = self.matching_preset()
        if name not in self.user_presets:
            return
        if not confirmed:
            self._ask('confirm_delete_preset', lambda: self.delete_preset(True), name=name)
            return
        del self.user_presets[name]
        try:
            rl_user_presets_save(self.user_presets)
        except OSError:
            pass
        self.preset_index = 0
        self.message = _studio_label(self.language, 'preset_deleted', name=name)

    def copy_rewards(self):
        text = rl_rewards_to_text(self.reward)
        if _copy_to_clipboard(text):
            self.message = _studio_label(self.language, 'rw_copied', n=len(self.reward))
            return
        path = os.path.join(studio_data_dir(), 'rewards_copy.txt')               # no clipboard on this system: keep it in a file instead
        try:
            os.makedirs(studio_data_dir(), exist_ok=True)
            with open(path, 'w', encoding='utf-8') as handle:
                handle.write(text)
            self.message = _studio_label(self.language, 'rw_copy_failed', path=path)
        except OSError:
            self.message = _studio_label(self.language, 'rw_copy_nowhere')

    def paste_rewards(self):
        values, skipped, problem = rl_rewards_from_text(_read_from_clipboard() or '')
        if problem:
            self.message = _studio_label(self.language, problem)
            return
        self.reward = dict(rl_default_reward(), **values)                       # a pasted set replaces the whole set; what it leaves out is the default
        self.message = _studio_label(self.language, 'rw_pasted', n=len(values), extra=(', ' + _studio_label(self.language, 'rw_skipped', n=skipped)) if skipped else '')

    def _name_ok(self):
        if self.name_draft.strip():
            return True
        self.message = _studio_label(self.language, 'name_required')
        return False

    def _step_field(self, name, direction, big):
        self._set_field(name, self._get_field(name) + direction * self.FIELDS[name][2] * (5 if big else 1))

    def new_model(self, confirmed=False):
        if not confirmed and self.unsaved_steps() > 0:
            self._ask('confirm_discard', lambda: self.new_model(True), steps=f'{self.unsaved_steps():,}')
            return
        name, number = 'My AI', 1
        while name in AI_REGISTRY:
            number += 1
            name = f'My AI {number}'
        enabled = self.model.inputs if self.model is not None else AI_DEFAULT_INPUTS
        self._adopt(AIModel.new(name, inputs=enabled, hidden=STUDIO_HIDDEN[self.hidden_index],
                                activation=AI_ACTIVATIONS[self.activation_index], seed=random.randrange(10 ** 6)))
        self.message = ''

    def rebuild(self, confirmed=False):
        rl = self.model.meta.get('rl') if isinstance(self.model.meta.get('rl'), dict) else {}
        steps = int(rl.get('steps_trained', 0)) if isinstance(rl.get('steps_trained'), (int, float)) else 0
        if not confirmed and (steps > 0 or self.model.meta.get('quality')):
            self._ask('confirm_rebuild', lambda: self.rebuild(True), steps=f'{steps:,}')
            return
        self.model = AIModel.new(self.model.name, inputs=self.model.inputs, hidden=STUDIO_HIDDEN[self.hidden_index],
                                 activation=AI_ACTIVATIONS[self.activation_index], seed=random.randrange(10 ** 6))
        self.history, self.checkpoints, self.session_steps, self.saved_steps = [], [], 0, 0      # a rebuilt AI starts from nothing, and so does its chart
        self.model.meta['studio'] = self._setup_snapshot()
        rl_state_delete(self.model.name)                                         # what the learning had saved belongs to the old weights
        self.state_bytes = 0
        self.message = _studio_label(self.language, 'rebuilt')

    def toggle_input(self, key):
        chosen = set(self.model.inputs)
        chosen.symmetric_difference_update({key})
        if chosen:
            self.model = ai_model_with_inputs(self.model, chosen)
            rl_state_delete(self.model.name)                                    # other inputs: the saved learning state no longer fits
            self.state_bytes = 0
            if (self.model.meta.get('rl') or {}).get('steps_trained'):
                self.message = _studio_label(self.language, 'inputs_changed')

    def add_easy_inputs(self):
        missing = [k for k in AI_EASY_INPUTS if k not in self.model.inputs]
        if not missing:
            self.message = _studio_label(self.language, 'inputs_easy_have')
            return
        self.model = ai_model_with_inputs(self.model, set(self.model.inputs) | set(missing))
        rl_state_delete(self.model.name)
        self.state_bytes = 0
        self.message = _studio_label(self.language, 'inputs_easy_added')

    def adjust_weight(self, key, direction, big=False):
        value = self.reward.get(key, 0.0)
        step = 0.05 if abs(value) < 0.5 else (0.5 if abs(value) < 5 else 1.0)
        from decimal import Decimal                    # decimal arithmetic: 10.8263 + 1 is 11.8263, not 11.826300000000002
        moved = float(Decimal(repr(float(value))) + Decimal(repr(float(direction * step * (10 if big else 1)))))
        self.reward[key] = max(-RL_REWARD_LIMIT, min(RL_REWARD_LIMIT, moved))

    # ---- background work --------------------------------------------------------------------
    def start_job(self, label_key, work, full_speed=False, **label_values):
        if self.job is not None and not self.job.done:
            return None
        job = _StudioJob(label_key, **label_values)
        self.job = job

        def run():
            if full_speed:
                job.power = training_power_enter()          # training is the point: no lowered priority, no power throttling, no sleep
            else:
                lower_current_thread_priority()            # loading and rating yield to the rest of the computer
            try:
                job.result = work(job)
            except Exception as exc:
                job.error = f'{type(exc).__name__}: {exc}'
            finally:
                if full_speed:
                    training_power_leave()
            job.progress = 1.0
            job.done = True
        threading.Thread(target=run, name='ai-studio', daemon=True).start()
        return job

    def train(self):
        self._commit_edit()
        check = self.validation()
        if check['status'] == 'blocked':
            self.message = self.validation_text(check['blocked'][0])           # the reason is shown; nothing starts
            return
        model, reward, config = self.model, dict(self.reward), self.env_config()
        kind, seconds = self.duration_kind, float(self.total_seconds())
        steps = STUDIO_STEPS[self.steps_index] if kind == 'steps' else None
        duration = seconds if kind == 'time' else None
        recovery = os.path.join(ai_library_dir(), 'recovery', _ai_file_name(model.name) + '.sgfai')
        state_path = rl_state_path(model.name)
        explore_restart = self.explore_restart

        def work(job):
            def progress(step, _total, point):
                job.steps_done = step
                if point.get('progress', -1.0) >= 0:
                    job.progress = min(1.0, point['progress'])

            def autosave(current):
                os.makedirs(os.path.dirname(recovery), exist_ok=True)         # a copy of the weights so far, outside the library
                ai_export_file(current, recovery)
            result = rl_train_dqn(model, reward, config, steps=steps, seed=random.randrange(10 ** 6), on_progress=progress,
                                  should_stop=lambda: job.stop, duration=duration, history=job.checkpoints,
                                  on_autosave=autosave if kind != 'steps' else None,
                                  explore='restart' if explore_restart else 'continue', state_path=state_path)
            if not result.get('autosave_error') and os.path.exists(recovery):
                os.remove(recovery)                                           # it finished normally: the backup is not needed
            return result
        self.history = rl_clean_history(model.meta.get('rl'))                  # the chart keeps what was already trained and continues to its right
        self.checkpoints = []
        job = self.start_job('training', work, full_speed=True, pct=0, elapsed='0s', left=_fmt_hms(seconds))
        if job is not None:
            job.kind, job.total_seconds = kind, seconds
            job.base_steps = int((model.meta.get('rl') or {}).get('steps_trained', 0)) if isinstance(model.meta.get('rl'), dict) else 0
            self.session_steps = 0
            self.speed, self._speed_last, self._chart_at = {'visible': [0, 0.0], 'minimized': [0, 0.0]}, None, (0.0, 0)
    def benchmark(self):
        model = self.model

        def work(job):
            job.progress = 0.05
            lab_reference_scores()
            job.progress = 0.7
            return ai_benchmark_quality(model)
        self.start_job('benchmarking', work)

    def load(self, model):
        def work(job):
            job.progress = 0.3
            model.validate()
            job.progress = 0.7
            AI_REGISTRY[model.name] = model
            return model
        self.start_job('loading', work)
        self._pending_adopt = model

    def import_files(self, paths=None):
        folder = os.path.join(ai_library_dir(), 'import')
        os.makedirs(folder, exist_ok=True)
        if paths is None:
            paths = [os.path.join(folder, n) for n in sorted(os.listdir(folder)) if n.endswith('.sgfai')]

        def work(job):
            imported = []
            for index, path in enumerate(paths):
                imported.append(ai_import_file(path))
                job.progress = (index + 1) / float(max(1, len(paths)))
            return imported
        if not paths:
            _open_folder_in_os(folder)
            self.message = _studio_label(self.language, 'import_hint')
            return
        self.start_job('loading', work)
        self._importing = True

    def export_file(self):
        if not self._name_ok():
            return
        self.model.name = self.name_draft = self.name_draft.strip()
        folder = os.path.join(ai_library_dir(), 'export')
        os.makedirs(folder, exist_ok=True)
        path = ai_export_file(self.model, os.path.join(folder, _ai_file_name(self.model.name) + '.sgfai'))
        _open_folder_in_os(folder)
        self.message = _studio_label(self.language, 'exported', path=path)

    def poll(self):
        self._setup_tick()
        job = self.job
        if job is None:
            return
        if job.label_key == 'training':
            elapsed = time.monotonic() - job.started
            job.label_values.update(pct=int(job.progress * 100), elapsed=_fmt_hms(elapsed),
                                    left=_fmt_hms(max(0.0, job.total_seconds - elapsed)))
            job.display_key = {'time': 'training_time', 'continuous': 'training_cont'}.get(job.kind)
            now_chart = time.monotonic()
            if not self.checkpoints or self._chart_due(now_chart, job.steps_done):
                self.checkpoints, self._chart_at = list(job.checkpoints), (now_chart, job.steps_done)
            self.session_steps = job.steps_done
            self._update_speed(job, time.monotonic(), job.steps_done, bool(self.window_active()))
        if not job.done:
            return
        self.job = None
        lang = self.language
        if job.error:
            self.message = _studio_label(lang, 'error', reason=job.error)
            return
        if job.label_key == 'training':
            if job.result:
                self.session_steps = job.result.get('steps_done', job.steps_done)
            self.history, self.checkpoints = rl_clean_history(self.model.meta.get('rl')), []      # the saved history now includes this run
            self.state_bytes = rl_state_size(self.model.name)
            last = job.checkpoints[-1] if job.checkpoints else {'avg_fruits': 0.0, 'avg_reward': 0.0}
            self.message = (_studio_label(lang, 'stopped') if job.stop else
                            _studio_label(lang, 'done_training', fruits=f"{last['avg_fruits']:.2f}", reward=f"{last['avg_reward']:.1f}"))
            state_result = (job.result or {}).get('state') or {}
            if state_result.get('loaded') == 'loaded':
                self.message += '  ' + _studio_label(lang, 'state_restored')
            elif str(state_result.get('loaded', '')).startswith('ignored'):
                self.message += '  ' + _studio_label(lang, 'state_ignored', why=str(state_result['loaded'])[8:])
            if state_result.get('error'):
                self.message += '  ' + _studio_label(lang, 'state_failed', reason=state_result['error'])
            if job.result and job.result.get('autosave_error'):
                self.message += '  ' + _studio_label(lang, 'autosave_failed', reason=job.result['autosave_error'])
            if self.speed_text():
                self.message += '  ' + self.speed_text()
        elif job.label_key == 'benchmarking':
            self.message = _studio_label(lang, 'rated', score=job.result['score'])
        elif job.label_key == 'loading':
            if getattr(self, '_importing', False):
                self._importing = False
                if job.result:
                    self._adopt(job.result[-1])
                self.message = _studio_label(lang, 'imported', count=len(job.result or []))
            elif getattr(self, '_pending_adopt', None) is not None:
                self._adopt(self._pending_adopt)
                self._pending_adopt = None

    # ---- actions ------------------------------------------------------------------------------
    def save(self):
        if not self._name_ok():
            return
        self.model.name = self.name_draft = self.name_draft.strip()
        self.model.meta['studio'] = self._setup_snapshot()
        ai_library_save(self.model)
        self.saved_steps = int((self.model.meta.get('rl') or {}).get('steps_trained', 0)) if isinstance(self.model.meta.get('rl'), dict) else 0
        self.message = _studio_label(self.language, 'saved', name=self.model.name)

    def delete(self):
        if not self._name_ok():
            return
        name = self.model.name
        ai_library_delete(name)
        rl_state_delete(name)
        names = sorted(AI_REGISTRY)
        self.message = _studio_label(self.language, 'deleted', name=name)
        self._adopt(AI_REGISTRY[names[0]] if names else AIModel.new('My AI', hidden=STUDIO_HIDDEN[self.hidden_index]))

    def next_model(self, confirmed=False):
        names = sorted(AI_REGISTRY)
        if self.model.name in AI_REGISTRY and len(names) > 1:
            if not confirmed and self.unsaved_steps() > 0:
                self._ask('confirm_discard', lambda: self.next_model(True), steps=f'{self.unsaved_steps():,}')
                return
            self.load(AI_REGISTRY[names[(names.index(self.model.name) + 1) % len(names)]])

    def _cycle(self, attr, count):
        setattr(self, attr, (getattr(self, attr) + 1) % count)

    def _click(self, name, pos, mods):
        if name == 'back':
            return 'back'
        simple = {'new': self.new_model, 'rebuild': self.rebuild, 'save': self.save, 'delete': self.delete,
                  'benchmark': self.benchmark, 'import': self.import_files, 'export': self.export_file, 'next': self.next_model}
        if name in simple:
            simple[name]()
        elif name == 'train':
            if self.job is not None and not self.job.done:
                self.job.stop = True
            else:
                self.train()
        elif name == 'lab':
            AILabScreen(self.settings, self.screen).run()
        elif name == 'rename':
            self._start_edit('name', pos)
        elif name == 'preset':
            names = rl_preset_names(self.user_presets)
            current = self.matching_preset()
            start = names.index(current) if current in names else self.preset_index % len(names)
            self.preset_index = (start + 1) % len(names)
            self.reward = rl_preset_values(names[self.preset_index], self.user_presets)
        elif name == 'rw_copy':
            self.copy_rewards()
        elif name == 'rw_paste':
            self.paste_rewards()
        elif name == 'rw_save':
            self._start_edit('preset_name')
        elif name == 'rw_del':
            self.delete_preset()
        elif name == 'rw_name':
            self._start_edit('preset_name')
        elif name == 'mode':
            self._cycle('mode_index', 4)
        elif name == 'learners':
            self.learners = self.learners % 4 + 1
        elif name == 'bots':
            self._cycle('bots_index', len(STUDIO_BOTS))
        elif name == 'board':
            self._cycle('board_index', len(STUDIO_BOARDS))
            self.board_w, self.board_h = STUDIO_BOARDS[self.board_index]
        elif name == 'explore':
            self.explore_restart = not self.explore_restart
        elif name == 'chart_series':
            modes = ('both', 'avg_fruits', 'avg_reward')
            current = 'both' if self.chart.mode == 'both' else 'avg_' + self.chart.mode
            nxt = modes[(modes.index(current) + 1) % len(modes)]
            self.chart.mode = 'both' if nxt == 'both' else nxt.replace('avg_', '')
        elif name == 'chart_rate':
            self.chart_rate_index = (self.chart_rate_index + 1) % len(self.chart_rates)
        elif name == 'duration':
            kinds = ('steps', 'time', 'continuous')
            self.duration_kind = kinds[(kinds.index(self.duration_kind) + 1) % len(kinds)]
        elif name in self.FIELDS:
            self._start_edit(name)
        elif name[:-1] in self.FIELDS and name[-1] in '+-':
            self._step_field(name[:-1], 1 if name[-1] == '+' else -1, bool(mods & pygame.KMOD_SHIFT))
        elif name == 'powerups':
            self.powerups = not self.powerups
        elif name == 'steps':
            self._cycle('steps_index', len(STUDIO_STEPS))
        elif name == 'hidden':
            self._cycle('hidden_index', len(STUDIO_HIDDEN))
        elif name == 'activation':
            self._cycle('activation_index', len(AI_ACTIVATIONS))
        elif name == 'inputs_easy':
            self.add_easy_inputs()
        elif name.startswith('in_'):
            self.toggle_input(name[3:])
        elif name.startswith('w-') or name.startswith('w+'):
            self.adjust_weight(name[2:], -1 if name[1] == '-' else 1, bool(mods & pygame.KMOD_SHIFT))
        elif name.startswith('wr_'):
            self._start_edit('wr:' + name[3:])
        elif name.startswith('rs_'):
            self.reward[name[3:]] = rl_default_reward()[name[3:]]
        return None

    def handle_event(self, event):
        if self.confirm is not None:                                          # a question is open: only Yes, Cancel, Enter and Esc count
            pending = self.confirm
            if event.type == pygame.KEYDOWN and event.key in (pygame.K_ESCAPE, pygame.K_BACKSPACE):
                self.confirm = None
            elif event.type == pygame.KEYDOWN and event.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
                self.confirm = None
                pending['yes']()
            elif event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
                clicked = next((name for name, rect in self.hits.items() if rect.collidepoint(event.pos)), None)
                if clicked == 'confirm_yes':
                    self.confirm = None
                    pending['yes']()
                elif clicked == 'confirm_no' or clicked is None:
                    self.confirm = None if clicked == 'confirm_no' else self.confirm
            return None
        if event.type == pygame.KEYDOWN:
            if self.editor is not None:
                result = self.editor.key(event)
                if result == 'enter':
                    self._commit_edit()
                elif result == 'escape':
                    self._stop_edit()                                          # leaves the box; a number or reward is not applied
                elif result is not None:
                    if result == 'changed':
                        self._edit_changed()
                    self.repeater.press(event, self.now())
                return None
            if event.key == pygame.K_ESCAPE:
                return 'back'
        elif event.type == pygame.KEYUP:
            self.repeater.release(event.key)
        elif event.type == getattr(pygame, 'WINDOWFOCUSLOST', None):
            self.repeater.release()
        elif event.type == pygame.MOUSEWHEEL:
            if self._chart_wheel(event.y):
                return None
            self.scroll = max(0, self.scroll - event.y * 40)
        elif event.type == pygame.MOUSEMOTION and self.chart.drag is not None:
            self._chart_drag(event.pos)
        elif event.type == pygame.MOUSEBUTTONUP and event.button == 1:
            self.chart.drag = None
        elif event.type == pygame.MOUSEBUTTONDOWN and event.button == 1 and self.chart_rect is not None and self.chart_rect.collidepoint(event.pos):
            self._commit_edit()
            now = self.now()
            if now - self.chart.last_click < 400:                                  # double click: show everything again
                self.chart.reset()
                self.chart.drag = None
            else:
                points = self.chart_points()
                self.chart.drag = (event.pos[0], self.chart.current(points)) if len(points) >= 3 else None
            self.chart.last_click = now
        elif event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
            clicked = next((name for name, rect in self.hits.items() if rect.collidepoint(event.pos)), None)
            if self.editor is not None and clicked == self._hit_name(self.edit_target):
                if self._name_area is not None and self.edit_target == 'name':
                    self.editor.caret = self.editor.caret_from_x(event.pos[0] - self._name_area.x + self.editor.scroll_x, self._name_font)
                    self.editor.last_input = self.now()
                return None                                                    # a second click in the same box just places the caret
            self._commit_edit()
            if clicked is not None:
                return self._click(clicked, event.pos, pygame.key.get_mods())
        elif event.type == pygame.MOUSEBUTTONDOWN and event.button in (4, 5):
            if not self._chart_wheel(1 if event.button == 4 else -1):
                self.scroll = max(0, self.scroll - (40 if event.button == 4 else -40))
        elif event.type == pygame.DROPFILE:
            self.import_files([event.file])
        return None

    # ---- drawing --------------------------------------------------------------------------------
    def _t(self, text, size, color, x, y, bold=False, width=None):
        font = get_font(self.language, 'bold' if bold else 'regular', size)
        surf = render_fit(font, text, color, width, padding=0) if width else font.render(text, True, color)
        self.screen.blit(surf, (x, y))
        return surf.get_height()

    def _button(self, name, rect, label, color=None, active=False):
        self.hits[name] = rect
        pygame.draw.rect(self.screen, color or COLORS['button'], rect, border_radius=6)
        if active:
            pygame.draw.rect(self.screen, COLORS['white'], rect, 2, border_radius=6)
        font = get_font(self.language, 'bold', max(11, min(16, rect.h - 10)))
        surf = render_fit(font, label, COLORS['white'], rect.w - 8, padding=0)
        self.screen.blit(surf, surf.get_rect(center=rect.center))

    def _field(self, name, rect, prefix='', suffix=''):
        """A number box with - and + buttons; clicking the number lets the player type it (Enter confirms, Esc cancels)."""
        side = max(16, rect.h)
        self._button(name + '-', pygame.Rect(rect.x, rect.y, side, rect.h), '-', COLORS['button'])
        self._button(name + '+', pygame.Rect(rect.right - side, rect.y, side, rect.h), '+', COLORS['button'])
        box = pygame.Rect(rect.x + side + 2, rect.y, max(10, rect.w - 2 * side - 4), rect.h)
        editing = self.edit_target == name
        self.hits[name] = box
        pygame.draw.rect(self.screen, (60, 70, 110) if editing else (40, 50, 80), box, border_radius=5)
        font = get_font(self.language, 'bold', max(11, min(16, rect.h - 10)))
        if editing:
            pygame.draw.rect(self.screen, COLORS['white'], box, 2, border_radius=5)
            self.editor.draw(self.screen, box.inflate(-8, 0), font, COLORS['white'])
            return
        surf = render_fit(font, f"{prefix}{self._get_field(name)}{suffix}", COLORS['white'], box.w - 4, padding=0)
        self.screen.blit(surf, surf.get_rect(center=box.center))

    def _reward_box(self, key, rect, value):
        """A reward weight: click it to type any number (Enter confirms, Esc leaves it as it was); the small circular arrow
        on the right puts the default back, and only shows when the weight is not the default."""
        editing = self.edit_target == 'wr:' + key
        changed = value != rl_default_reward()[key]
        icon = pygame.Rect(rect.right - 18, rect.y, 18, rect.h)
        if changed and not editing:
            self.hits['rs_' + key] = icon                                       # registered first, so it wins where the boxes overlap
        self.hits['wr_' + key] = rect
        pygame.draw.rect(self.screen, (60, 70, 110) if editing else (40, 50, 80), rect, border_radius=5)
        font = get_font(self.language, 'bold', max(11, min(16, rect.h - 10)))
        if editing:
            pygame.draw.rect(self.screen, COLORS['white'], rect, 2, border_radius=5)
            self.editor.draw(self.screen, rect.inflate(-8, 0), font, COLORS['white'])
            return
        room = rect.w - 6 - (16 if changed else 0)
        surf = render_fit(font, format_decimal(value), COLORS['white'], room, padding=0)
        self.screen.blit(surf, surf.get_rect(center=(rect.x + (rect.w - (16 if changed else 0)) // 2, rect.centery)))
        if changed:
            glyph = ui_reset_icon(COLORS['light_gray'], 14)
            self.screen.blit(glyph, glyph.get_rect(center=icon.center))

    def draw(self):
        screen, lang = self.screen, self.language
        sw, sh = screen.get_size()
        screen.fill(COLORS['dark_blue'])
        self.hits = {}
        m = max(8, int(sw * 0.012))
        ref = min(sw, sh)
        small = max(11, int(ref * 0.021))
        row_h = max(20, int(ref * 0.04))
        # top bar
        self._t(_studio_label(lang, 'title'), max(20, int(ref * 0.045)), COLORS['white'], m, m // 2, True)
        top = m + max(26, int(ref * 0.05))
        name_rect = pygame.Rect(m, top, int(sw * 0.3), row_h)
        self.hits['rename'] = name_rect
        editing_name = self.edit_target == 'name'
        pygame.draw.rect(screen, (60, 70, 110) if editing_name else (40, 50, 80), name_rect, border_radius=5)
        if editing_name:
            pygame.draw.rect(screen, COLORS['white'], name_rect, 2, border_radius=5)
        name_font = get_font(lang, 'regular', small)
        prefix = f"{_studio_label(lang, 'name')}: "
        text_x = name_rect.x + 8 + name_font.size(prefix)[0]
        self._t(prefix, small, COLORS['light_gray'], name_rect.x + 8, name_rect.y + 3)
        area = pygame.Rect(text_x, name_rect.y, max(10, name_rect.right - text_x - 6), name_rect.h)
        self._name_area, self._name_font = area, name_font
        if editing_name:
            self.editor.draw(screen, area, name_font, COLORS['white'])
        elif self.name_draft.strip():
            self._t(self.name_draft, small, COLORS['white'], area.x, name_rect.y + 3, False, area.w)
        else:
            self._t(_studio_label(lang, 'name_hint'), small, (255, 130, 130), area.x, name_rect.y + 3, False, area.w)
        quality = self.model.meta.get('quality')
        chip = pygame.Rect(name_rect.right + 8, top, int(sw * 0.2), row_h)
        pygame.draw.rect(screen, tuple(self.model.meta.get('color') or (70, 80, 110)), chip, border_radius=5)
        rl_meta = self.model.meta.get('rl') if isinstance(self.model.meta.get('rl'), dict) else {}
        trained_total = int(rl_meta.get('steps_trained', 0)) if isinstance(rl_meta.get('steps_trained'), (int, float)) else 0
        if self.job is not None and not self.job.done and self.job.label_key == 'training':
            trained_total = self.job.base_steps + self.job.steps_done                     # live, while it trains
        stale = bool(quality) and isinstance(quality.get('at_steps'), int) and quality['at_steps'] != trained_total and not (self.job is not None and not self.job.done)
        score_text = _studio_label(lang, 'unrated') if not quality else (_studio_label(lang, 'quality_old', score=quality['score']) if stale else quality['score'])
        self._t(f"{_studio_label(lang, 'quality')}: {score_text}", small, (0, 0, 0) if quality else COLORS['white'], chip.x + 8, chip.y + 3, True, chip.w - 12)
        info = (_studio_label(lang, 'trained_session', steps=f'{trained_total:,}', session=f'{self.session_steps:,}') if self.session_steps
                else _studio_label(lang, 'trained', steps=f'{trained_total:,}')) + '   ' + _studio_label(lang, 'backend', name=_rl_backend())
        if self.job is not None and not self.job.done and self.job.label_key == 'training' and self.job.rate > 0:
            info += '   ' + _studio_label(lang, 'rate', sps=f'{self.job.rate:,.0f}')
        if self.state_bytes > 0:
            info += '   ' + _studio_label(lang, 'state_size', mb=f'{self.state_bytes / 1048576.0:.1f}')
        self._t(info, small, COLORS['light_gray'], chip.right + 10, top + 3, False, sw - chip.right - m - 120)
        self._button('back', pygame.Rect(sw - m - 100, m // 2, 100, row_h), _studio_label(lang, 'back'), COLORS['red'])
        # three columns
        body_top = top + row_h + m
        bottom = sh - m - row_h - 6
        lw, mw = int(sw * 0.40), int(sw * 0.26)
        # -- rewards
        left = pygame.Rect(m, body_top, lw - m, bottom - body_top)
        self._t(_studio_label(lang, 'rewards'), small, COLORS['light_gray'], left.x, left.y, False, left.w)
        preset_rect = pygame.Rect(left.x, left.y + small + 4, left.w, row_h)
        matching = self.matching_preset()
        if self.edit_target == 'preset_name':                                    # typing the name to save the weights under
            self.hits['rw_name'] = preset_rect
            pygame.draw.rect(screen, (60, 70, 110), preset_rect, border_radius=6)
            pygame.draw.rect(screen, COLORS['white'], preset_rect, 2, border_radius=6)
            prompt = _studio_label(lang, 'preset_name_prompt') + ': '
            prompt_font = get_font(lang, 'bold', max(11, min(16, row_h - 10)))
            self._t(prompt, small, COLORS['light_gray'], preset_rect.x + 8, preset_rect.y + 3)
            self.editor.draw(screen, pygame.Rect(preset_rect.x + 12 + prompt_font.size(prompt)[0], preset_rect.y, max(10, preset_rect.w - 20 - prompt_font.size(prompt)[0]), preset_rect.h),
                             prompt_font, COLORS['white'])
        else:
            self._button('preset', preset_rect, f"{_studio_label(lang, 'preset')}: {matching or _studio_label(lang, 'preset_custom')}", COLORS['purple'])
        tools_y, tools_h = preset_rect.bottom + 3, max(18, row_h - 4)
        tool_w = (left.w - 3 * 4) // 4
        for index, (tool, enabled) in enumerate((('rw_copy', True), ('rw_paste', True), ('rw_save', True), ('rw_del', matching in self.user_presets))):
            self._button(tool, pygame.Rect(left.x + index * (tool_w + 4), tools_y, tool_w, tools_h), _studio_label(lang, tool),
                         COLORS['button'] if enabled else COLORS['dark_gray'])
        list_top = tools_y + tools_h + 8
        pt = lang.startswith('pt')
        previous_clip = screen.get_clip()
        screen.set_clip(pygame.Rect(left.x, list_top, left.w, left.bottom - list_top))
        y = list_top - self.scroll
        max_scroll = max(0, len(RL_REWARD_TERMS) * (row_h + 2) - (left.bottom - list_top))
        self.scroll = min(self.scroll, max_scroll)
        for key, en, pt_label, default, modes in RL_REWARD_TERMS:
            if left.y < y + row_h and y < left.bottom:
                value = self.reward.get(key, 0.0)
                applies = ''.join(t[0].upper() for t in modes)
                minus = pygame.Rect(left.right - 150, y, 28, row_h)
                val = pygame.Rect(minus.right + 2, y, 66, row_h)
                plus = pygame.Rect(val.right + 2, y, 28, row_h)
                color = COLORS['green'] if value > 0 else (COLORS['red'] if value < 0 else COLORS['light_gray'])
                self._t(pt_label if pt else en, small, color if value else COLORS['light_gray'], left.x + 2, y + 3, False, left.w - 220)
                self._t(applies, small - 1, COLORS['gold'], left.right - 190, y + 3)
                if y >= list_top - row_h:
                    self._button('w-' + key, minus, '-', COLORS['button'])
                    self._reward_box(key, val, value)
                    self._button('w+' + key, plus, '+', COLORS['button'])
            y += row_h + 2
        screen.set_clip(previous_clip)
        # -- training settings
        mx = left.right + m
        mid = pygame.Rect(mx, body_top, mw - m, bottom - body_top)
        kind = self.duration_kind
        check = self.validation()
        training = self.job is not None and not self.job.done and self.job.label_key == 'training'
        busy = self.job is not None and not self.job.done
        rows = [('button', 'mode', f"{_studio_label(lang, 'mode')}: {_studio_label(lang, ('solo', 'versus', 'coop', 'mixed')[self.mode_index])}"),
                ('button', 'learners', f"{_studio_label(lang, 'learners')}: {self.learners}"),
                ('button', 'bots', f"{_studio_label(lang, 'bots')}: {STUDIO_BOTS[self.bots_index] or _studio_label(lang, 'none')}"),
                ('button', 'board', f"{_studio_label(lang, 'board')}: {self.board_w}x{self.board_h}"),
                ('size',),
                ('button', 'powerups', f"{_studio_label(lang, 'powerups')}: {_studio_label(lang, 'on' if self.powerups else 'off')}"),
                ('button', 'duration', f"{_studio_label(lang, 'duration')}: {_studio_label(lang, {'steps': 'by_steps', 'time': 'by_time', 'continuous': 'continuous'}[kind])}")]
        if kind == 'steps':
            rows.append(('button', 'steps', f"{_studio_label(lang, 'steps')}: {STUDIO_STEPS[self.steps_index]:,}"))
        elif kind == 'time':
            rows += [('time1',), ('time2',)]
        rl_now = self.model.meta.get('rl') if isinstance(self.model.meta.get('rl'), dict) else {}
        if isinstance(rl_now.get('steps_trained'), (int, float)) and rl_now.get('steps_trained', 0) > 0:
            resume_eps = rl_resume_epsilon(rl_now, RL_DEFAULT_CONFIG, 'continue')
            rows.append(('button', 'explore', f"{_studio_label(lang, 'explore')}: " + (_studio_label(lang, 'explore_restart') if self.explore_restart
                         else _studio_label(lang, 'explore_continue', pct=int(round(resume_eps * 100))))))
        pending_layers = tuple(STUDIO_HIDDEN[self.hidden_index]) != tuple(self.model.hidden)
        pending_activation = AI_ACTIVATIONS[self.activation_index] != self.model.activation
        layers_text = 'x'.join(str(h) for h in STUDIO_HIDDEN[self.hidden_index])
        rows += [('button', 'hidden', f"{_studio_label(lang, 'layers')}: " + (f"{'x'.join(str(h) for h in self.model.hidden)} > {layers_text}" if pending_layers else layers_text), pending_layers),
                 ('button', 'activation', f"{_studio_label(lang, 'activation')}: " + (f"{self.model.activation} > {AI_ACTIVATIONS[self.activation_index]}" if pending_activation else AI_ACTIVATIONS[self.activation_index]), pending_activation)]
        # the rows share the column: with a short window they get thinner instead of running off the bottom
        unit = max(18, min(row_h + 4, int(mid.h // (len(rows) + 8.9))))
        rh = max(16, unit - 4)
        y = mid.y
        for row in rows:
            rect = pygame.Rect(mid.x, y, mid.w, rh)
            if row[0] == 'button':
                self._button(row[1], rect, row[2], (200, 110, 40) if len(row) > 3 and row[3] else None)
            elif row[0] == 'size':
                half = (rect.w - 6) // 2
                self._field('sz_w', pygame.Rect(rect.x, y, half, rh), 'W ')
                self._field('sz_h', pygame.Rect(rect.x + half + 6, y, half, rh), 'H ')
            elif row[0] == 'time1':
                half = (rect.w - 6) // 2
                self._field('t_h', pygame.Rect(rect.x, y, half, rh), '', ' h')
                self._field('t_m', pygame.Rect(rect.x + half + 6, y, half, rh), '', ' min')
            else:
                half = (rect.w - 6) // 2
                self._field('t_s', pygame.Rect(rect.x, y, half, rh), '', ' s')
                self._t(f'= {_fmt_hms(self.total_seconds())}', max(11, small), COLORS['light_gray'], rect.x + half + 12, y + max(0, (rh - small) // 2), False, half - 8)
            y += unit
        self._button('train', pygame.Rect(mid.x, y, mid.w, rh + 6), _studio_label(lang, 'stop' if training else 'train'),
                     COLORS['red'] if training else (COLORS['dark_gray'] if check['status'] == 'blocked' else COLORS['green']))
        y += rh + 10
        rl_note = self.model.meta.get('rl') if isinstance(self.model.meta.get('rl'), dict) else {}
        trained_now = int(rl_note.get('steps_trained', 0)) if isinstance(rl_note.get('steps_trained'), (int, float)) else 0
        if check['status'] == 'blocked':
            note, note_color = self.validation_text(check['blocked'][0]), COLORS['red']
        elif self.layout_pending():                                                # the layout will change on Rebuild: say what is lost
            note, note_color = _studio_label(lang, 'layout_pending_trained' if trained_now else 'layout_pending', steps=f'{trained_now:,}'), (255, 170, 90)
        elif check['status'] == 'warn':
            note, note_color = self.validation_text(check['warnings'][0]), COLORS['orange']
            if len(check['warnings']) > 1:
                note += ' ' + _studio_label(lang, 'val_more', count=len(check['warnings']) - 1)
        else:
            note, note_color = _studio_label(lang, 'val_ok'), COLORS['light_gray']
        note_size = max(10, small - 2)
        note_font = get_font(lang, 'regular', note_size)
        lines, line = [], ''
        for word in note.split(' '):                                            # up to two lines, so the reason stays readable
            if line and note_font.size(line + ' ' + word)[0] > mid.w:
                lines.append(line)
                line = word
            else:
                line = (line + ' ' + word).strip()
        lines.append(line)
        if len(lines) > 2:
            lines = [lines[0], ' '.join(lines[1:])]
        for index, text_line in enumerate(lines):
            self._t(text_line, note_size, note_color, mid.x, y + index * (note_size + 2), False, mid.w)
        y += unit + note_size - 2
        half = (mid.w - 6) // 2
        for index, (name, color) in enumerate((('benchmark', COLORS['orange']), ('rebuild', COLORS['button']), ('new', COLORS['button']),
                                               ('save', COLORS['green']), ('next', COLORS['button']), ('delete', COLORS['red']),
                                               ('import', COLORS['blue']), ('export', COLORS['blue']))):
            rect = pygame.Rect(mid.x + (index % 2) * (half + 6), y + (index // 2) * unit, half, rh)
            self._button(name, rect, _studio_label(lang, name) if name != 'next' else '>>', COLORS['dark_gray'] if (busy and name in ('benchmark', 'rebuild')) or (not self.name_draft.strip() and name in ('save', 'export', 'delete')) else color)
        y += 4 * unit
        self._button('lab', pygame.Rect(mid.x, y, mid.w, rh), _studio_label(lang, 'lab'), (200, 110, 40))
        # -- inputs and chart
        rx = mid.right + m
        right = pygame.Rect(rx, body_top, sw - rx - m, bottom - body_top)
        easy_w = min(104, right.w // 2)
        self._t(_studio_label(lang, 'inputs'), small, COLORS['light_gray'], right.x, right.y, False, right.w - easy_w - 6)
        self._button('inputs_easy', pygame.Rect(right.right - easy_w, right.y - 2, easy_w, small + 6), _studio_label(lang, 'inputs_easy'),
                     COLORS['dark_gray'] if all(k in self.model.inputs for k in AI_EASY_INPUTS) else (60, 130, 90))
        y = right.y + small + 6 + 4
        half = (right.w - 6) // 2
        chosen = set(self.model.inputs)
        for index, (key, label, size, _default) in enumerate(AI_INPUT_GROUPS):
            rect = pygame.Rect(right.x + (index % 2) * (half + 6), y + (index // 2) * (row_h - 4), half, row_h - 6)
            self.hits['in_' + key] = rect
            pygame.draw.rect(screen, COLORS['green'] if key in chosen else (50, 55, 80), rect, border_radius=4)
            self._t(f'{label} ({size})', small - 1, COLORS['white'], rect.x + 5, rect.y + 2, False, rect.w - 8)
        y += ((len(AI_INPUT_GROUPS) + 1) // 2) * (row_h - 4) + 8
        buttons_h = small + 8
        chart = pygame.Rect(right.x, y, right.w, max(40, right.bottom - y - buttons_h - 4))
        self.chart_rect = chart
        chart_font = get_font(lang, 'regular', max(9, small - 2))
        self.chart.draw(screen, chart, self.chart_points(), chart_font,
                        {'empty': _studio_label(lang, 'chart_empty'), 'steps': _studio_label(lang, 'axis_steps'),
                         'avg_fruits': _studio_label(lang, 'axis_fruits'), 'avg_reward': _studio_label(lang, 'axis_reward')}, self.mouse_pos())
        kind, amount = self.chart_rates[self.chart_rate_index]
        rate_text = _studio_label(lang, 'rate_steps' if kind == 'steps' else 'rate_seconds', n=f'{amount:,.0f}' if kind == 'steps' else f'{amount:g}')
        half_w = (chart.w - 6) // 2
        self._button('chart_series', pygame.Rect(chart.x, chart.bottom + 4, half_w, buttons_h), _studio_label(lang, 'chart_' + self.chart.mode), COLORS['button'])
        self._button('chart_rate', pygame.Rect(chart.x + half_w + 6, chart.bottom + 4, half_w, buttons_h), _studio_label(lang, 'chart_rate', value=rate_text), COLORS['button'])
        # status and the loading / progress bar
        bar = pygame.Rect(m, sh - m - row_h, sw - 2 * m, row_h)
        pygame.draw.rect(screen, (30, 36, 60), bar, border_radius=5)
        if self.job is not None and not self.job.done:
            if self.job.label_key == 'training' and self.job.kind == 'continuous':
                block = max(24, bar.w // 5)                                     # no end to measure: a block slides along the bar
                pygame.draw.rect(screen, COLORS['light_blue'], pygame.Rect(bar.x + int((bar.w - block) * ((time.time() * 0.5) % 1.0)), bar.y, block, bar.h), border_radius=5)
            else:
                pygame.draw.rect(screen, COLORS['light_blue'], pygame.Rect(bar.x, bar.y, int(bar.w * max(0.02, self.job.progress)), bar.h), border_radius=5)
            text = _studio_label(lang, self.job.display_key or self.job.label_key, **self.job.label_values)
        else:
            text = self.message or _studio_label(lang, 'idle')
        self._t(text, small, COLORS['white'], bar.x + 8, bar.y + 3, False, bar.w - 16)
        if self.confirm is not None:
            self._draw_confirm(screen, sw, sh, small)

    def finish_job_before_exit(self, timeout=15.0):
        """Closing the game while it trains: ask the training to stop and give it a moment to save its state, so closing the
        window never costs the work of the last minutes."""
        job = self.job
        if job is None or job.done:
            return True
        job.stop = True
        deadline = time.monotonic() + timeout
        while not job.done and time.monotonic() < deadline:
            time.sleep(0.05)
        return job.done

    def _draw_confirm(self, screen, sw, sh, small):
        """A question with Yes and Cancel: everything else is dimmed and cannot be clicked until it is answered."""
        dim = pygame.Surface((sw, sh), pygame.SRCALPHA)
        dim.fill((0, 0, 0, 170))
        screen.blit(dim, (0, 0))
        self.hits = {}                                                            # nothing behind the question can be clicked
        lang = self.language
        width = min(sw - 40, 480)
        font = get_font(lang, 'regular', max(13, small + 2))
        lines, line = [], ''
        for word in self.confirm['text'].split(' '):
            if line and font.size(line + ' ' + word)[0] > width - 36:
                lines.append(line)
                line = word
            else:
                line = (line + ' ' + word).strip()
        lines.append(line)
        height = 36 + len(lines) * (font.get_height() + 4) + 14 + 40
        panel = pygame.Rect(0, 0, width, height)
        panel.center = (sw // 2, sh // 2)
        pygame.draw.rect(screen, (26, 32, 54), panel, border_radius=10)
        pygame.draw.rect(screen, (230, 170, 80), panel, 2, border_radius=10)
        y = panel.y + 18
        for text_line in lines:
            surf = font.render(text_line, True, COLORS['white'])
            screen.blit(surf, (panel.x + 18, y))
            y += font.get_height() + 4
        button_w = (width - 36 - 10) // 2
        self._button('confirm_yes', pygame.Rect(panel.x + 18, panel.bottom - 50, button_w, 34), _studio_label(lang, 'confirm_yes'), (200, 110, 40))
        self._button('confirm_no', pygame.Rect(panel.x + 18 + button_w + 10, panel.bottom - 50, button_w, 34), _studio_label(lang, 'confirm_no'), COLORS['button'])

    def run(self):
        clock = pygame.time.Clock()
        while True:
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    self.finish_job_before_exit()
                    pygame.quit()
                    sys.exit()
                elif event.type == pygame.VIDEORESIZE:
                    self.screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)
                elif event.type == pygame.KEYDOWN and event.key == pygame.K_F11 and self.editor is None:
                    self.screen = _toggle_fullscreen(self.screen)
                elif self.handle_event(event) == 'back':
                    if self.job is not None:
                        self.job.stop = True
                    ui_set_cursor('arrow')
                    return None
            self.update_input()
            self.poll()
            if not self.window_active():                       # minimised: nothing to draw, so the training gets all the time
                clock.tick(10)
                continue
            self.draw()
            mouse = pygame.mouse.get_pos()
            under = next((name for name, rect in self.hits.items() if rect.collidepoint(mouse)), None)
            ui_set_cursor('ibeam' if under is not None and self.is_text_hit(under) else 'arrow')
            pygame.display.flip()
            clock.tick(30 if (self.job is not None and not self.job.done and self.job.label_key == 'training') else 60)   # drawing less often while it trains gives the training more time


##############
# VS-AI GAME
##############
class VSAIGame:
    """
    Single-player vs one or more AI-controlled snakes.
    Reuses the same board layout conventions as MultiplayerGame.
    Supports 1–3 AI opponents.
    """

    # Colour palette for AI snakes (up to 3)
    AI_COLOURS = [
        {'body': (230,  80,  80), 'head': (180,  30,  30)},   # red
        {'body': (230, 160,  30), 'head': (170, 110,   0)},   # orange
        {'body': (160,  80, 230), 'head': (100,  30, 170)},   # purple
    ]
    P1_BODY = ( 50, 205,  50)
    P1_HEAD = ( 20, 165,  20)

    def __init__(self, settings, screen, ai_count=1, ai_difficulty='medium',
                 seed=None, custom_map=None, ai_configs=None):
        self.settings      = settings
        self.screen        = screen
        self.custom_map    = custom_map  # optional Map Editor layout (obstacles + portals)
        # Seed system — generate one if not provided
        self.seed = seed if seed else generate_seed()
        self.rng  = SeedRNG(self.seed)
        self.cosmetic_rng = random.Random(seed_to_int(f'{self.seed}:cosmetic'))
        if ai_configs is None:
            count = max(0, min(4, int(ai_count or 0)))
            self.ai_configs = _normalize_ai_configs(
                [{'difficulty': ai_difficulty} for _ in range(count)], count)
        else:
            self.ai_configs = _normalize_ai_configs(ai_configs)
        self.ai_count = len(self.ai_configs)
        self.ai_difficulty = (
            self.ai_configs[0]['difficulty']
            if self.ai_configs else str(ai_difficulty or 'medium')
        )
        self.ai_names = [cfg['name'] for cfg in self.ai_configs]
        self.ai_skins = [cfg['skin'] for cfg in self.ai_configs]
        self.ai_engines = [
            SnakeAI(cfg['difficulty'], rng=SeedRNG(self.seed + f'_ai{i}'))
            for i, cfg in enumerate(self.ai_configs)
        ]
        self._enc_updates = {}
        for cfg in self.ai_configs:
            self._enc_touch(f"ai_{cfg['difficulty']}", encountered=1)
        self._init_layout()
        self.reset()
        if 'DEV_TOOLS' in globals():
            DEV_TOOLS.register_game(self)

    # ── layout ──────────────────────────────────────────────────────────

    def _board_size(self):
        if isinstance(self.settings.board_size, str):
            m = {"small": 10, "medium": 15, "large": 20, "extra_large": 25}
            return m.get(self.settings.board_size, 15)
        return max(10, int(self.settings.board_size))

    def _init_layout(self):
        if self.custom_map:
            self.board_width  = self.custom_map.get('board_width', 20)
            self.board_height = self.custom_map.get('board_height', 20)
        else:
            size = self._board_size()
            self.board_width  = size
            self.board_height = size
        sw, sh = self.screen.get_width(), self.screen.get_height()
        hud_h = 70
        cs = min(sw, sh - hud_h) // max(self.board_width, self.board_height, 1)
        self.cell_size      = max(4, cs)
        self.board_offset_x = (sw - self.board_width  * self.cell_size) // 2
        self.board_offset_y = hud_h + (sh - hud_h - self.board_height * self.cell_size) // 2

    # ── reset ────────────────────────────────────────────────────────────

    def _enc_touch(self, entry_id, encountered=0, used=0):
        """Accumulate an encyclopedia encounter/use count for this match;
        flushed to disk at game-over via _flush_encyclopedia_updates()."""
        if not entry_id:
            return
        d = self._enc_updates.setdefault(entry_id, {'encountered': 0, 'used': 0})
        d['encountered'] += encountered
        d['used'] += used

    def reset(self):
        # Re-seed so restarting reproduces the exact same sequence for
        # this seed instead of continuing the RNG stream from before.
        _clear_game_xp_award(self)
        self.rng = SeedRNG(self.seed)
        self.cosmetic_rng = random.Random(seed_to_int(f'{self.seed}:cosmetic'))

        # Recreate the AI engines from scratch too — SnakeAI keeps its own
        # RNG stream *and* internal state (loop-detection history, move
        # counters); reusing the old objects here would carry that state
        # over from the previous match, so replaying "the same seed" via
        # Play Again wouldn't actually reproduce the same AI movements.
        self.ai_engines = [
            SnakeAI(cfg['difficulty'], rng=SeedRNG(self.seed + f'_ai{i}'))
            for i, cfg in enumerate(self.ai_configs)
        ]
        self.ai_names = [cfg['name'] for cfg in self.ai_configs]
        self.ai_skins = [cfg['skin'] for cfg in self.ai_configs]
        self.ai_count = len(self.ai_configs)
        self.ai_difficulty = (
            self.ai_configs[0]['difficulty'] if self.ai_configs else self.ai_difficulty
        )
        self._init_layout()
        bw, bh = self.board_width, self.board_height

        # Player 1 starts on the left
        self.p1_snake = [(bw // 6, bh // 2)]
        self.p1_dir   = (1, 0)
        self.p1_next  = (1, 0)
        self.p1_score = 0
        self.p1_alive = True

        # AI snakes start spread across the right side
        self.ai_snakes = []
        self.ai_dirs   = []
        self.ai_nexts  = []
        self.ai_scores = []
        self.ai_alive  = []
        positions = [
            (5 * bw // 6, bh // 2),
            (2 * bw // 3, bh // 4),
            (2 * bw // 3, 3 * bh // 4),
            (bw // 2, bh // 6),
        ]
        for i in range(self.ai_count):
            sx, sy = positions[i % len(positions)]
            self.ai_snakes.append([(sx, sy)])
            self.ai_dirs.append((-1, 0))
            self.ai_nexts.append((-1, 0))
            self.ai_scores.append(0)
            self.ai_alive.append(True)

        # Obstacles
        self.obstacles = []
        if self.custom_map:
            self.obstacles = [tuple(o) for o in self.custom_map.get('obstacles', [])]
        elif self.settings.enable_obstacles:
            self._gen_obstacles()

        # Portals
        self.portals = []
        if self.custom_map:
            for p in self.custom_map.get('portals', []):
                x1, y1, x2, y2, pal_idx = p
                self.portals.append(((x1, y1), (x2, y2), pal_idx))
        elif getattr(self.settings, 'enable_portals', False):
            self._gen_portals()

        if self.obstacles:
            self._enc_touch('obstacle_static', encountered=1)
        if self.portals:
            self._enc_touch('portal_pair', encountered=len(self.portals))
        self._enc_touch('mechanic_seeds', encountered=1)

        # Power-up state
        self.powerup_pos  = None
        self.powerup_type = None
        self.powerup_spawn_interval = 15000
        self.powerup_timer = -self.powerup_spawn_interval
        self._spawn_powerup_check(0)

        self.fruit_pos  = self._new_fruit()
        self.fruit_type = _pick_cosmetic_fruit_type(getattr(self.settings, 'fruit_types_enabled', True), self.cosmetic_rng)
        self.fruits_eaten = 0
        self.unique_fruits_collected = set()
        self.game_over  = False
        self.winner     = None   # 'player', 'ai', 'draw'
        self.paused     = False
        self._sim_time_ms = 0.0
        self._update_accumulator_ms = max(1.0, float(self.settings.update_rate_ms))
        self.last_tick  = 0.0
        self.start_time = time.time()
        self.game_history   = []    # per-tick snapshots for replay
        self._score_saved   = False # guard: save only once per game
        self._replay_mode   = False
        self._replay_idx    = 0
        self.performance_stats = GameplayPerformanceStats()

    def _gen_obstacles(self):
        all_snakes = list(self.p1_snake)
        for s in self.ai_snakes:
            all_snakes.extend(s)
        safe = set()
        for sx, sy in all_snakes:
            for dx in range(-3, 4):
                for dy in range(-3, 4):
                    safe.add((sx + dx, sy + dy))
        available = [(x, y) for x in range(self.board_width)
                     for y in range(self.board_height) if (x, y) not in safe]
        count = min(getattr(self.settings, 'obstacle_count', 5),
                    len(available) // 5, 25)
        if count > 0 and available:
            self.obstacles = self.rng.sample(available, count)

    def _gen_portals(self):
        occupied = (set(self.p1_snake) |
                    {c for s in self.ai_snakes for c in s} |
                    set(self.obstacles))
        candidates = [(x, y) for x in range(self.board_width)
                      for y in range(self.board_height)
                      if (x, y) not in occupied]
        if len(candidates) >= 4:
            pts = self.rng.sample(candidates, 4)
            self.portals = [(pts[0], pts[1], 0), (pts[2], pts[3], 1)]

    def _new_fruit(self):
        ai_cells = {c for s in self.ai_snakes for c in s}
        occupied = (set(self.p1_snake) | ai_cells |
                    set(self.obstacles) |
                    ({self.powerup_pos} if self.powerup_pos else set()))
        avail = [(x, y) for x in range(self.board_width)
                 for y in range(self.board_height)
                 if (x, y) not in occupied]
        return self.rng.choice(avail) if avail else None

    def _spawn_powerup_check(self, now_ms):
        if not getattr(self.settings, 'powerups_enabled', True):
            return
        if self.powerup_pos is None and now_ms - self.powerup_timer >= self.powerup_spawn_interval:
            all_cells = (set(self.p1_snake) |
                         {c for s in self.ai_snakes for c in s} |
                         set(self.obstacles) |
                         ({self.fruit_pos} if hasattr(self, 'fruit_pos') and self.fruit_pos else set()))
            avail = [(x, y) for x in range(self.board_width)
                     for y in range(self.board_height)
                     if (x, y) not in all_cells]
            if avail:
                self.powerup_pos   = self.rng.choice(avail)
                self.powerup_type  = self.rng.choice(['speed', 'double_points',
                                                      'invincible', 'shield'])
                self.powerup_timer = now_ms

    # ── input ────────────────────────────────────────────────────────────

    def handle_key(self, key):
        action = _movement_action_for_key(self.settings, key)
        candidates = {
            'up': ((0, -1), (0, 1)), 'down': ((0, 1), (0, -1)),
            'left': ((-1, 0), (1, 0)), 'right': ((1, 0), (-1, 0)),
        }
        if action in candidates:
            new_direction, opposite = candidates[action]
            if self.p1_dir != opposite:
                self.p1_next = new_direction

    # ── update ───────────────────────────────────────────────────────────

    def _new_head(self, snake, direction):
        hx, hy = snake[0]
        dx, dy = direction
        if self.settings.wall_collision and not getattr(self, '_dev_no_wall_collision', False):
            nx, ny = hx + dx, hy + dy
            if not (0 <= nx < self.board_width and 0 <= ny < self.board_height):
                return None
            return (nx, ny)
        return ((hx + dx) % self.board_width, (hy + dy) % self.board_height)

    def _build_ai_occupied(self, ai_idx):
        """Blocked cells for AI snake ai_idx: obstacles + all other snakes."""
        occupied = list(self.obstacles)
        # Own body (excluding tail which will move away)
        occupied.extend(self.ai_snakes[ai_idx][:-1])
        # Player body
        occupied.extend(self.p1_snake[:-1])
        # Other AI bodies
        for j, s in enumerate(self.ai_snakes):
            if j != ai_idx:
                occupied.extend(s[:-1])
        return occupied

    def deterministic_state_signature(self):
        """Return gameplay state suitable for deterministic regression tests."""
        return {
            'seed': self.seed,
            'board': (self.board_width, self.board_height),
            'p1': tuple(self.p1_snake),
            'p1_score': self.p1_score,
            'p1_alive': self.p1_alive,
            'ais': tuple(tuple(s) for s in self.ai_snakes),
            'ai_scores': tuple(self.ai_scores),
            'ai_alive': tuple(self.ai_alive),
            'fruit': self.fruit_pos,
            'powerup': (self.powerup_pos, self.powerup_type),
            'obstacles': tuple(self.obstacles),
            'portals': tuple(self.portals),
        }

    def get_performance_stats(self):
        """Return a copy of the current rolling performance telemetry."""
        return self.performance_stats.snapshot()

    def tick(self):
        if self.game_over or self.paused:
            return

        now_ms = self._sim_time_ms
        self._spawn_powerup_check(now_ms)

        # ── AI decisions ─────────────────────────────────────────────────
        ai_start = time.perf_counter()
        for i, engine in enumerate(self.ai_engines):
            if not self.ai_alive[i]:
                continue
            occ = self._build_ai_occupied(i)
            direction = engine.choose_direction(
                snake         = self.ai_snakes[i],
                occupied      = occ,
                fruit         = self.fruit_pos,
                board_w       = self.board_width,
                board_h       = self.board_height,
                portals       = self.portals,
                powerup_pos   = self.powerup_pos,
                wall_collision= self.settings.wall_collision,
                opponent_snake= self.p1_snake,
            )
            self.ai_nexts[i] = direction
        self._last_ai_time_ms = (time.perf_counter() - ai_start) * 1000.0

        # ── Move all snakes ───────────────────────────────────────────────
        self.p1_dir = self.p1_next
        for i in range(self.ai_count):
            self.ai_dirs[i] = self.ai_nexts[i]

        h1 = self._new_head(self.p1_snake, self.p1_dir) if self.p1_alive else None

        ai_heads = []
        for i in range(self.ai_count):
            if self.ai_alive[i]:
                ai_heads.append(self._new_head(self.ai_snakes[i], self.ai_dirs[i]))
            else:
                ai_heads.append(None)

        obs_set = set(map(tuple, self.obstacles))
        pts     = max(1, int(10 * 1000 / max(1, self.settings.update_rate_ms)))

        # Portal teleport helper
        def _portal_teleport(pos):
            if not self.portals:
                return pos
            for a, b, _ in self.portals:
                if pos == tuple(a): return tuple(b)
                if pos == tuple(b): return tuple(a)
            return pos

        # ── Collision detection for player ────────────────────────────────
        p1_die = h1 is None
        if getattr(self, '_dev_no_death', False):
            p1_die = False
        if h1:
            h1 = _portal_teleport(h1)
            if h1 in obs_set:                         p1_die = True
            if h1 in set(self.p1_snake[:-1]):         p1_die = True
            for s in self.ai_snakes:
                if h1 in set(s):                      p1_die = True

        # ── Collision detection for AI ─────────────────────────────────────
        ai_die = [False] * self.ai_count
        for i in range(self.ai_count):
            if ai_heads[i] is None:
                ai_die[i] = True
                continue
            ai_heads[i] = _portal_teleport(ai_heads[i])
            h = ai_heads[i]
            if h in obs_set:                                    ai_die[i] = True
            if h in set(self.ai_snakes[i][:-1]):                ai_die[i] = True
            if self.p1_alive and h in set(self.p1_snake):      ai_die[i] = True
            for j, s in enumerate(self.ai_snakes):
                if j != i and h in set(s):                      ai_die[i] = True
            # Head-on with player
            if h1 and h == h1:
                p1_die = True
                ai_die[i] = True

        # ── Move + eat ────────────────────────────────────────────────────
        p1_ate = False
        if not p1_die and h1:
            self.p1_snake.insert(0, h1)
            if h1 == self.fruit_pos:
                self.p1_score += pts; p1_ate = True
                _track_game_fruit(self, self.fruit_type)
                _trigger_mobile_haptic(30)
            else:
                self.p1_snake.pop()
            if h1 == self.powerup_pos:
                self.powerup_pos  = None
                self.powerup_timer = self._sim_time_ms
                self.p1_score += pts * 2

        for i in range(self.ai_count):
            if ai_die[i] or ai_heads[i] is None:
                continue
            h = ai_heads[i]
            self.ai_snakes[i].insert(0, h)
            if h == self.fruit_pos and not p1_ate:
                self.ai_scores[i] += pts
                p1_ate = True    # fruit consumed
            else:
                self.ai_snakes[i].pop()
            if h == self.powerup_pos:
                self.powerup_pos  = None
                self.powerup_timer = self._sim_time_ms

        if p1_ate:
            self.fruit_pos = self._new_fruit()
            self.fruit_type = _pick_cosmetic_fruit_type(getattr(self.settings, 'fruit_types_enabled', True), self.cosmetic_rng)

        # ── Record snapshot (alive flags still at pre-death state) ───────────
        if not self.game_over:
            _append_solo_replay_snapshot(self)

        # ── Apply deaths ──────────────────────────────────────────────────
        if p1_die:  self.p1_alive = False
        for i in range(self.ai_count):
            if ai_die[i]: self.ai_alive[i] = False

        # ── End-of-game check ─────────────────────────────────────────────
        ai_all_dead = self.ai_count > 0 and not any(self.ai_alive)
        if not self.p1_alive or ai_all_dead:
            self.game_over = True
            if not self.p1_alive and ai_all_dead:
                if self.p1_score >= max(self.ai_scores):
                    self.winner = 'player'
                elif self.p1_score < max(self.ai_scores):
                    self.winner = 'ai'
                else:
                    self.winner = 'draw'
            elif not self.p1_alive:
                self.winner = 'ai'
            else:
                self.winner = 'player'
            if not self._score_saved:
                self._score_saved = True
                self.save_score()
            _trigger_mobile_haptic(90)

    # ── replay & save ─────────────────────────────────────────────────────

    def _snap(self):
        """Compact JSON-serialisable snapshot of current VS-AI game state."""
        snap = {
            'p1':  [list(c) for c in self.p1_snake],
            'p1s': self.p1_score,
            'p1a': self.p1_alive,
            'ais': [[list(c) for c in s] for s in self.ai_snakes],
            'ass': list(self.ai_scores),
            'aia': list(self.ai_alive),
            'fr':  list(self.fruit_pos) if self.fruit_pos else None,
            'ft':  getattr(self, 'fruit_type', 'regular'),
            'pp':  list(self.powerup_pos) if self.powerup_pos else None,
            'aic': _copy_json_safe(self.ai_configs),
            'dev_modified': DEV_TOOLS.modified,
        }
        return snap

    def _load_snap(self, snap):
        """Restore game state from a snapshot dict."""
        self.p1_snake  = [tuple(c) for c in snap['p1']]
        self.p1_score  = snap['p1s']
        self.p1_alive  = snap['p1a']
        self.ai_snakes = [[tuple(c) for c in s] for s in snap['ais']]
        self.ai_scores = list(snap['ass'])
        self.ai_alive  = list(snap['aia'])
        self.fruit_pos = tuple(snap['fr']) if snap['fr'] else None
        self.fruit_type = snap.get('ft', 'regular')
        self.powerup_pos = tuple(snap['pp']) if snap['pp'] else None
        if isinstance(snap.get('aic'), list):
            self.ai_configs = _normalize_ai_configs(
                snap.get('aic'), len(snap.get('aic')))
            self.ai_count = len(self.ai_configs)
            self.ai_names = [cfg['name'] for cfg in self.ai_configs]
            self.ai_skins = [cfg['skin'] for cfg in self.ai_configs]
            self.ai_difficulty = (
                self.ai_configs[0]['difficulty'] if self.ai_configs else self.ai_difficulty
            )

    def save_score(self):
        """Save player score to the shared high-scores file."""
        _flush_encyclopedia_updates(getattr(self, '_enc_updates', {}))
        self._enc_updates = {}

        _award_game_xp_async(self, 'vs_ai')

        if self.p1_score <= 0:
            return

        game_id = f"{int(time.time())}-{self.rng.randint(1000,9999)}"
        player_name = getattr(self, 'player_name', '') or 'Player'
        settings_dict = {k: v for k, v in vars(self.settings).items()
                         if isinstance(v, (int, float, str, bool, list, dict))}

        score_entry = {
            'name':            player_name,
            'score':           self.p1_score,
            'date':            datetime.now().strftime('%Y-%m-%d %H:%M'),
            'timestamp':       datetime.now().isoformat(),
            'board_size':      self.board_width,
            'update_rate_ms':  self.settings.update_rate_ms,
            'victory':         self.winner == 'player',
            'wall_collision':  self.settings.wall_collision,
            'powerups_enabled':self.settings.powerups_enabled,
            'fruit_types_enabled': getattr(self.settings, 'fruit_types_enabled', True),
            'obstacles_enabled': self.settings.enable_obstacles,
            'portals_enabled': getattr(self.settings, 'enable_portals', False),
            'portal_pairs':    getattr(self.settings, 'portal_pairs', 0),
            'game_mode':       'vs_ai',
            'ai_difficulty':   self.ai_difficulty,
            'ai_count':        self.ai_count,
            'ai_configs':      _copy_json_safe(self.ai_configs),
            'seed':            self.seed,
            'replay_format_version': _REPLAY_FORMAT_VERSION,
            'game_id':         game_id,
            'has_replay':      False,
            'settings':        settings_dict,
            'custom_map':      self.custom_map,
            'actual_board_width':  self.board_width,
            'actual_board_height': self.board_height,
        }
        self._replay_save_game_id = _queue_completed_score(
            score_entry, self.game_history, max_records=10)

    def start_replay(self, game_history):
        """Enter replay mode from a saved history list."""
        if not game_history:
            return False
        self.game_history  = game_history
        self._replay_mode  = True
        self._replay_idx   = 0
        self.game_over     = False
        self.paused        = False
        self._load_snap(game_history[0])
        return True

    def run_replay(self):
        """Replay viewer: plays back a saved VS-AI game."""
        clock = pygame.time.Clock()
        paused = False
        spd = 1.0
        frame_ms = self.settings.update_rate_ms
        replay_timer = 0.0

        while True:
            frame_dt = min(float(clock.tick(60)), 250.0)
            replay_start = time.perf_counter()
            for event in pygame.event.get():
                if _legacy_nav_event(locals().get('self'), event, locals()):
                    continue
                if event.type == pygame.QUIT:
                    return
                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_ESCAPE:
                        return
                    elif event.key == pygame.K_SPACE:
                        paused = not paused
                    elif event.key == pygame.K_RIGHT:
                        if self._replay_idx < len(self.game_history) - 1:
                            self._replay_idx += 1
                            self._load_snap(self.game_history[self._replay_idx])
                    elif event.key == pygame.K_LEFT:
                        if self._replay_idx > 0:
                            self._replay_idx -= 1
                            self._load_snap(self.game_history[self._replay_idx])
                    elif event.key in (pygame.K_EQUALS, pygame.K_PLUS, pygame.K_KP_PLUS):
                        spd = min(8.0, spd * 2)
                    elif event.key in (pygame.K_MINUS, pygame.K_KP_MINUS):
                        spd = max(0.25, spd / 2)
                elif event.type == pygame.VIDEORESIZE:
                    self.screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)
                    self._init_layout()

            if not paused:
                replay_timer += frame_dt * spd
                while replay_timer >= frame_ms and self._replay_idx < len(self.game_history) - 1:
                    self._replay_idx += 1
                    self._load_snap(self.game_history[self._replay_idx])
                    replay_timer -= frame_ms

            replay_ms = (time.perf_counter() - replay_start) * 1000.0
            render_start = time.perf_counter()
            sw, sh = self.screen.get_width(), self.screen.get_height()
            self.screen.fill(COLORS['dark_blue'])
            self._draw_hud()
            self._draw_board()
            for i in range(self.ai_count - 1, -1, -1):
                fallback = self.AI_COLOURS[i % len(self.AI_COLOURS)]
                col = AI_SKINS.get(self.ai_skins[i], fallback) if i < len(self.ai_skins) else fallback
                self._draw_snake(self.ai_snakes[i], col['body'], col['head'], self.ai_alive[i],
                                 LAB_LEVEL_COLORS.get(getattr(self.ai_engines[i], 'difficulty', ''), (255, 255, 255)))
            self._draw_snake(self.p1_snake, self.P1_BODY, self.P1_HEAD, self.p1_alive, _autopilot_eye_color())
            if self.fruit_pos:
                bx, by, cs = self.board_offset_x, self.board_offset_y, self.cell_size
                fr = pygame.Rect(bx + self.fruit_pos[0] * cs, by + self.fruit_pos[1] * cs, cs, cs)
                if cs >= 10 and getattr(self.settings, 'fruit_types_enabled', True):
                    draw_fruit(self.screen, fr, getattr(self, 'fruit_type', 'regular'))
                else:
                    pygame.draw.rect(self.screen, COLORS['fruit'], fr)

            progress = self._replay_idx / max(1, len(self.game_history) - 1)
            bar_w = int(sw * 0.6)
            bar_x = (sw - bar_w) // 2
            bar_y = sh - 36
            pygame.draw.rect(self.screen, (50, 55, 80), (bar_x, bar_y, bar_w, 12), border_radius=6)
            pygame.draw.rect(self.screen, COLORS['light_blue'], (bar_x, bar_y, int(bar_w * progress), 12), border_radius=6)
            hf = get_font(self.settings.language, 'regular', 16)
            hints = f"SPACE pause  ←→ step  +/- speed ({spd:.2g}×)  ESC exit"
            hs = hf.render(hints, True, (180, 200, 230))
            self.screen.blit(hs, (sw // 2 - hs.get_width() // 2, sh - 20))
            lbl = hf.render("◀ REPLAY ▶", True, (255, 220, 80))
            self.screen.blit(lbl, (sw // 2 - lbl.get_width() // 2, bar_y - 22))

            _legacy_nav_draw(locals().get('self'))
            DEV_TOOLS.draw_dev_indicator(self.screen, replay=True, snapshot=self.game_history[self._replay_idx] if self.game_history else None)
            pygame.display.flip()
            render_ms = (time.perf_counter() - render_start) * 1000.0
            _dev_game_frame_hook(self, frame_dt, render_ms=render_ms, replay_ms=replay_ms)
            self.performance_stats.record_frame(
                frame_dt, render_ms=render_ms, replay_ms=replay_ms,
                object_counts={
                    'player_segments': len(getattr(self, 'p1_snake', [])),
                    'ai_segments': sum(len(s) for s in getattr(self, 'ai_snakes', [])),
                    'obstacles': len(getattr(self, 'obstacles', [])),
                    'replay_frames': len(getattr(self, 'game_history', [])),
                })

    # ── draw ─────────────────────────────────────────────────────────────

    def draw(self):
        sw, sh = self.screen.get_width(), self.screen.get_height()
        background_color, _board_color, _grid_color = _map_theme_colors(self.settings)
        self.screen.fill(background_color)
        self._draw_hud()
        self._draw_board()
        # Draw AI snakes first (player appears on top)
        for i in range(self.ai_count - 1, -1, -1):
            col = self.AI_COLOURS[i % len(self.AI_COLOURS)]
            self._draw_snake(self.ai_snakes[i], col['body'], col['head'],
                             self.ai_alive[i],
                             LAB_LEVEL_COLORS.get(getattr(self.ai_engines[i], 'difficulty', ''), (255, 255, 255)))
        self._draw_snake(self.p1_snake, self.P1_BODY, self.P1_HEAD,
                         self.p1_alive, _autopilot_eye_color())
        # Draw fruit
        if self.fruit_pos:
            bx, by, cs = self.board_offset_x, self.board_offset_y, self.cell_size
            fr = pygame.Rect(bx + self.fruit_pos[0] * cs,
                             by + self.fruit_pos[1] * cs, cs, cs)
            if cs >= 10 and getattr(self.settings, 'fruit_types_enabled', True):
                draw_fruit(self.screen, fr, getattr(self, 'fruit_type', 'regular'))
            else:
                pygame.draw.rect(self.screen, COLORS['fruit'], fr)
        # Draw powerup
        if self.powerup_pos:
            bx, by, cs = self.board_offset_x, self.board_offset_y, self.cell_size
            px = bx + self.powerup_pos[0] * cs + cs // 2
            py = by + self.powerup_pos[1] * cs + cs // 2
            r  = max(4, cs // 3)
            pulse = (math.sin(pygame.time.get_ticks() / 300) + 1) / 2
            pc    = (int(100 + 155 * pulse), int(50 + 100 * pulse), 255)
            pygame.draw.circle(self.screen, pc, (px, py), r)
            pygame.draw.circle(self.screen, (255, 255, 255), (px, py), max(2, r // 3))
        if self.game_over:
            self._draw_game_over()
        elif self.paused:
            self._draw_paused()
        _legacy_nav_draw(locals().get('self'))
        pygame.display.flip()

    def _draw_board(self):
        bx, by = self.board_offset_x, self.board_offset_y
        bw_px  = self.board_width  * self.cell_size
        bh_px  = self.board_height * self.cell_size
        cs     = self.cell_size
        _background_color, board_color, grid_color = _map_theme_colors(self.settings)

        pygame.draw.rect(self.screen, board_color,
                         pygame.Rect(bx, by, bw_px, bh_px))
        for x in range(self.board_width + 1):
            pygame.draw.line(self.screen, grid_color,
                             (bx + x * cs, by), (bx + x * cs, by + bh_px), 1)
        for y in range(self.board_height + 1):
            pygame.draw.line(self.screen, grid_color,
                             (bx, by + y * cs), (bx + bw_px, by + y * cs), 1)
        for obs in self.obstacles:
            r = pygame.Rect(bx + obs[0] * cs, by + obs[1] * cs, cs, cs)
            pygame.draw.rect(self.screen, COLORS.get('obstacle', (100, 100, 100)), r)
        for a, b, _ in self.portals:
            for pos, col in [(a, (80, 180, 255)), (b, (255, 130, 60))]:
                cx = bx + pos[0] * cs + cs // 2
                cy = by + pos[1] * cs + cs // 2
                pygame.draw.circle(self.screen, col, (cx, cy), max(4, cs // 2 - 2))

    def _draw_snake(self, snake, body_col, head_col, alive, eye_color=(255, 255, 255)):
        if not snake:
            return
        bc = body_col if alive else (100, 100, 100)
        hc = head_col if alive else ( 70,  70,  70)
        cs = self.cell_size
        bx, by = self.board_offset_x, self.board_offset_y
        for i, (sx, sy) in enumerate(snake):
            r   = pygame.Rect(bx + sx * cs + 1, by + sy * cs + 1, cs - 2, cs - 2)
            col = hc if i == 0 else bc
            pygame.draw.rect(self.screen, col, r,
                             border_radius=max(1, cs // 5))
            if i == 0 and cs > 10:
                _draw_snake_eyes(self.screen, r, _snake_head_direction(snake, self.board_width, self.board_height),
                                 eye_color if alive else (150, 150, 150))

    def _draw_hud(self):
        sw      = self.screen.get_width()
        hf      = get_font(self.settings.language, 'bold',    20)
        sf      = get_font(self.settings.language, 'regular', 13)
        diff_lbl = self.ai_difficulty.capitalize()

        you_lbl = get_text(self.settings.language, 'you_label').upper()
        ai_lbl  = get_text(self.settings.language, 'ai_label')
        p1c  = (100, 255, 100) if self.p1_alive else (130, 130, 130)
        p1s  = hf.render(f"{you_lbl}: {self.p1_score}", True, p1c)
        self.screen.blit(p1s, (10, 8))

        for i in range(self.ai_count):
            fallback = self.AI_COLOURS[i % len(self.AI_COLOURS)]
            col  = AI_SKINS.get(self.ai_skins[i], fallback) if i < len(self.ai_skins) else fallback
            ac   = col['body'] if self.ai_alive[i] else (130, 130, 130)
            label_name = self.ai_names[i] if i < len(self.ai_names) else f"{ai_lbl} {i+1}"
            ais  = hf.render(f"{label_name}: {self.ai_scores[i]}", True, ac)
            self.screen.blit(ais, (sw - ais.get_width() - 10 - i * 130, 8))

        hint = sf.render(
            get_text(self.settings.language, 'vsai_controls_hint').format(diff=diff_lbl),
            True, (80, 110, 160))
        self.screen.blit(hint, (sw // 2 - hint.get_width() // 2, 40))

    def _draw_game_over(self):
        music = globals().get('_SOUND_MGR')
        if music is not None and music._bgm_volume > 0:
            music.set_music_context('game_over')
        sw, sh = self.screen.get_width(), self.screen.get_height()
        ov = pygame.Surface((sw, sh), pygame.SRCALPHA)
        ov.fill((0, 0, 0, 180))
        self.screen.blit(ov, (0, 0))

        bf = get_font(self.settings.language, 'bold',    52)
        mf = get_font(self.settings.language, 'bold',    28)
        sf = get_font(self.settings.language, 'regular', 22)

        if   self.winner == 'player': txt, col = get_text(self.settings.language, 'you_win_exclaim'), (100, 255, 100)
        elif self.winner == 'ai':     txt, col = get_text(self.settings.language, 'ai_wins'),          (255,  80,  80)
        else:                         txt, col = get_text(self.settings.language, 'vsai_draw'),        (255, 215,   0)

        ai_lbl = get_text(self.settings.language, 'ai_label')
        ai_score_str = "  ".join(f"{ai_lbl} {i+1}: {self.ai_scores[i]}"
                                  for i in range(self.ai_count))
        sc_txt = f"{get_text(self.settings.language, 'you_label')}: {self.p1_score}     {ai_score_str}"

        ts  = bf.render(txt,    True, col)
        scs = mf.render(sc_txt, True, COLORS['white'])

        seed_hint = sf.render(f"{get_text(self.settings.language, 'seed_label')}: {self.seed}", True, (120, 150, 200))

        self.screen.blit(ts,  (sw // 2 - ts.get_width()  // 2, sh // 2 - 130))
        self.screen.blit(scs, (sw // 2 - scs.get_width() // 2, sh // 2 -  70))
        if self.p1_score > 0:
            _draw_replay_save_widget(self.screen, self.settings.language,
                                        getattr(self, '_replay_save_game_id', None), sw // 2, 8)
        self.screen.blit(seed_hint, (sw // 2 - seed_hint.get_width() // 2, sh // 2 - 8))

        # --- Touch/mouse buttons — Play Again, Menu, Copy Seed, (View Replay) ---
        has_replay = bool(self.game_history)
        n_buttons = 4 if has_replay else 3
        gap = int(sw * 0.02)
        margin = int(sw * 0.04)
        available = sw - margin * 2 - gap * (n_buttons - 1)
        btn_w = max(90, min(220, available // n_buttons))
        btn_h = max(40, int(sh * 0.07))
        total_w = n_buttons * btn_w + (n_buttons - 1) * gap
        start_x = sw // 2 - total_w // 2
        by = sh // 2 + 25

        buttons = {}
        labels = [
            ('play_again', get_text(self.settings.language, 'play_again'), COLORS['green']),
            ('menu', get_text(self.settings.language, 'menu'), COLORS['button']),
            ('copy_seed', get_text(self.settings.language, 'copy_seed'), (100, 130, 200)),
        ]
        if has_replay:
            labels.append(('view_replay', get_text(self.settings.language, 'view_replay'), (170, 45, 170)))

        btn_font = get_font(self.settings.language, 'bold', max(14, int(sh * 0.025)))
        for i, (key, label, color) in enumerate(labels):
            rect = pygame.Rect(start_x + i * (btn_w + gap), by, btn_w, btn_h)
            pygame.draw.rect(self.screen, color, rect, border_radius=8)
            pygame.draw.rect(self.screen, COLORS['white'], rect, width=1, border_radius=8)
            text_surf = btn_font.render(label, True, COLORS['white'])
            max_w = rect.width - 14
            if text_surf.get_width() > max_w and text_surf.get_width() > 0:
                scale = max_w / text_surf.get_width()
                new_size = (max_w, max(1, int(text_surf.get_height() * scale)))
                text_surf = pygame.transform.smoothscale(text_surf, new_size)
            self.screen.blit(text_surf, text_surf.get_rect(center=rect.center))
            buttons[key] = rect
        self._go_buttons = buttons

        if getattr(self, '_seed_copied_until', 0) > time.time():
            note = sf.render(get_text(self.settings.language, 'seed_copied'), True, (140, 220, 140))
            self.screen.blit(note, note.get_rect(center=(sw // 2, by + btn_h + 22)))

        hint_font = get_font(self.settings.language, 'regular', 15)
        its = hint_font.render(get_text(self.settings.language, 'restart_hint_vsai'),
                                True, (150, 150, 170))
        self.screen.blit(its, (sw // 2 - its.get_width() // 2, by + btn_h + 44))

    def _draw_paused(self):
        sw, sh = self.screen.get_width(), self.screen.get_height()
        ov = pygame.Surface((sw, sh), pygame.SRCALPHA)
        ov.fill((0, 0, 0, 110))
        self.screen.blit(ov, (0, 0))
        f  = get_font(self.settings.language, 'bold',    50)
        f2 = get_font(self.settings.language, 'regular', 22)
        s  = f.render(get_text(self.settings.language, 'paused').upper(), True, COLORS['white'])
        s2 = f2.render(get_text(self.settings.language, 'press_p_to_resume'), True, (180, 180, 210))
        self.screen.blit(s,  (sw // 2 - s.get_width()  // 2, sh // 2 - s.get_height() // 2))
        self.screen.blit(s2, (sw // 2 - s2.get_width() // 2, sh // 2 + 40))

    # ── main loop ────────────────────────────────────────────────────────

    def run(self):
        """Run VS-AI with a fixed-step simulation independent of render FPS."""
        running = True
        clock = pygame.time.Clock()

        while running:
            _pump_audio()
            frame_dt = min(float(clock.tick(60)), 250.0)
            raw_frame_dt = frame_dt
            frame_dt = DEV_TOOLS.scale_dt(frame_dt)
            input_start = time.perf_counter()
            update_ms = 0.0
            ai_ms = 0.0
            render_ms = 0.0

            for event in pygame.event.get():
                if _legacy_nav_event(locals().get('self'), event, locals()):
                    continue
                if _is_app_background_event(event):
                    if not self.game_over:
                        self.paused = True
                        if getattr(self, 'runtime', None) is not None:
                            self.runtime.set_game_paused(True, {'game': 'vs_ai'})
                    continue
                if getattr(self, 'runtime', None) is not None:
                    handled, _actions = self.runtime.input.route(event)
                    if handled:
                        continue
                if event.type == pygame.QUIT:
                    running = False
                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_F11:
                        self.screen = _toggle_fullscreen(self.screen)
                    elif event.key == pygame.K_F8 and DEV_TOOLS.unlocked:
                        DEV_TOOLS.open_panel(self.screen, self)
                    elif event.key == pygame.K_ESCAPE:
                        running = False
                    elif event.key == pygame.K_r and self.game_over:
                        self.reset()
                    elif event.key == pygame.K_w and self.game_over and self.game_history:
                        self.run_replay()
                    elif event.key == pygame.K_p and not self.game_over:
                        self.paused = not self.paused
                        if getattr(self, 'runtime', None) is not None:
                            self.runtime.set_game_paused(self.paused, {'game': 'vs_ai'})
                    elif not self.game_over and not self.paused:
                        self.handle_key(event.key)
                elif event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
                    mp = event.pos
                    if self.game_over and hasattr(self, '_go_buttons'):
                        gb = self._go_buttons
                        if gb.get('play_again') and gb['play_again'].collidepoint(mp):
                            self.reset()
                        elif gb.get('menu') and gb['menu'].collidepoint(mp):
                            running = False
                        elif gb.get('copy_seed') and gb['copy_seed'].collidepoint(mp):
                            if _copy_to_clipboard(str(self.seed)):
                                self._seed_copied_until = time.time() + 2.0
                        elif gb.get('view_replay') and gb['view_replay'].collidepoint(mp):
                            self.run_replay()
                elif event.type == pygame.VIDEORESIZE:
                    self.screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)
                    self._init_layout()

            input_ms = (time.perf_counter() - input_start) * 1000.0
            if not self.paused and not self.game_over:
                self._sim_time_ms += frame_dt
                self._update_accumulator_ms += frame_dt
                update_start = time.perf_counter()
                step_ms = max(1.0, self.settings.update_rate_ms)
                while self._update_accumulator_ms >= step_ms:
                    DEV_TOOLS.apply_frame_cheats(self)
                    self.tick()
                    ai_ms += getattr(self, '_last_ai_time_ms', 0.0)
                    self._update_accumulator_ms -= step_ms
                    self.last_tick = self._sim_time_ms - self._update_accumulator_ms
                    if self.game_over:
                        self._update_accumulator_ms = 0.0
                        break
                    if self._update_accumulator_ms < step_ms:
                        break
                update_ms = (time.perf_counter() - update_start) * 1000.0

            render_start = time.perf_counter()
            self.draw()
            DEV_TOOLS.draw_ai_overlay(self.screen, self)
            DEV_TOOLS.draw_dev_indicator(self.screen, replay=False)
            render_ms = (time.perf_counter() - render_start) * 1000.0
            _dev_game_frame_hook(self, raw_frame_dt, update_ms=update_ms, render_ms=render_ms, input_ms=input_ms, ai_ms=ai_ms)
            self.performance_stats.record_frame(
                frame_dt,
                update_ms=update_ms, render_ms=render_ms, ai_ms=ai_ms,
                object_counts={
                    'player_segments': len(getattr(self, 'p1_snake', [])),
                    'ai_segments': sum(len(s) for s in getattr(self, 'ai_snakes', [])),
                    'obstacles': len(getattr(self, 'obstacles', [])),
                    'replay_frames': len(getattr(self, 'game_history', [])),
                })

        return

