class PlayMenuScreen:
    """
    Top-level Play menu: Singleplayer or Multiplayer.
    Returns 'singleplayer', 'multiplayer', or None (back/cancel).
    """

    def __init__(self, settings, screen):
        self.settings = settings
        self.screen = screen

    def run(self):
        clock = pygame.time.Clock()
        while True:
            sw, sh = self.screen.get_width(), self.screen.get_height()
            self.screen.fill(COLORS['dark_blue'])

            t = pygame.time.get_ticks() / 1000.0
            for i in range(20):
                px = int(sw * ((i * 137) % 100) / 100)
                py = int(sh * ((i * 97 + t * 12) % 100) / 100)
                pygame.draw.circle(self.screen, (30, 50, 110), (px, py), 2)

            _ref = min(sw, sh)
            tf = get_font(self.settings.language, 'bold', max(28, int(_ref * 0.07)))
            bf = get_font(self.settings.language, 'bold', max(18, int(_ref * 0.04)))

            title = tf.render(get_text(self.settings.language, 'play'), True, COLORS['white'])
            self.screen.blit(title, (sw // 2 - title.get_width() // 2, int(sh * 0.15)))

            btn_w = max(220, int(sw * 0.32))
            btn_h = max(38, min(60, int(sh * 0.075)))
            gap = max(8, int(sh * 0.02))
            cy = int(sh * 0.30)

            sp_rect = pygame.Rect(sw // 2 - btn_w // 2, cy, btn_w, btn_h)
            mp_rect = pygame.Rect(sw // 2 - btn_w // 2, cy + btn_h + gap, btn_w, btn_h)
            daily_rect = pygame.Rect(sw // 2 - btn_w // 2, cy + (btn_h + gap) * 2, btn_w, btn_h)
            back_rect = pygame.Rect(sw // 2 - btn_w // 2, cy + (btn_h + gap) * 3, btn_w, btn_h)

            pygame.draw.rect(self.screen, COLORS['green'], sp_rect, border_radius=10)
            pygame.draw.rect(self.screen, (0, 130, 180), mp_rect, border_radius=10)
            pygame.draw.rect(self.screen, (125, 90, 185), daily_rect, border_radius=10)
            pygame.draw.rect(self.screen, COLORS['button'], back_rect, border_radius=10)

            for rect, label in ((sp_rect, get_text(self.settings.language, 'singleplayer_title')), (mp_rect, get_text(self.settings.language, 'multiplayer_local_title')),
                                 (daily_rect, get_text(self.settings.language, 'daily_challenge')),
                                 (back_rect, get_text(self.settings.language, 'back'))):
                surf = render_fit(bf, label, COLORS['white'], rect.width)
                self.screen.blit(surf, surf.get_rect(center=rect.center))

            _legacy_nav_draw(locals().get('self'))
            pygame.display.flip()

            for event in pygame.event.get():
                if _legacy_nav_event(locals().get('self'), event, locals()):
                    continue
                if event.type == pygame.QUIT:
                    pygame.quit(); sys.exit()
                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_F11:
                        self.screen = _toggle_fullscreen(self.screen)
                    elif event.key == pygame.K_ESCAPE:
                        return None
                elif event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
                    mp = event.pos
                    if sp_rect.collidepoint(mp):
                        return 'singleplayer'
                    if mp_rect.collidepoint(mp):
                        return 'multiplayer'
                    if daily_rect.collidepoint(mp):
                        return 'daily_challenge'
                    if back_rect.collidepoint(mp):
                        return NAV_BACK_LEVEL
                elif event.type == pygame.VIDEORESIZE:
                    self.screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)
            clock.tick(60)


