_ui_title_glow_cache = {}


class UIAnimatedTitle(UIWidget):
    """The floating, glowing game title. Text and glow surfaces are cached; the
    animation only changes an alpha value and a y offset per frame."""
    focusable = False
    interactive = False

    def __init__(self, text, base_size, key='title'):
        super().__init__(key=key)
        self.text, self.base_size = text, base_size

    def draw(self, surface):
        r = self.rect
        if r.w <= 0 or r.h <= 0:
            return
        lang = self.lang()
        avail = max(10, r.h - 10)
        fh = get_font(lang, 'bold', self.base_size).get_height()
        size = self.base_size if fh <= avail else max(14, int(self.base_size * avail / fh))
        s = ui_text_surface(lang, 'bold', size, self.val(self.text), COLORS['white'], max(1, r.w - 20))
        if _ACCESSIBILITY_REDUCED_MOTION:
            surface.blit(s, s.get_rect(center=r.center))
            return
        t = pygame.time.get_ticks()
        gw, gh = s.get_width() + 20, s.get_height() + 20
        glow_key = (gw, gh)
        g, cached = _lru_cache_get(_ui_title_glow_cache, glow_key)
        if not cached:
            g = pygame.Surface((gw, gh), pygame.SRCALPHA)
            pygame.draw.ellipse(g, (100, 150, 255, 255), g.get_rect())
            _lru_cache_put(_ui_title_glow_cache, glow_key, g, 8)
        g.set_alpha(int(100 + 50 * math.sin(t / 1000.0)))
        y = r.y + 5 + int(math.sin(t / 800.0) * 5) + max(0, (avail - s.get_height()) // 2)
        surface.blit(g, (r.centerx - gw // 2, y - 10))
        surface.blit(s, (r.centerx - s.get_width() // 2, y))


class _SimpleMenuScreen:
    """Reusable 'title (+ optional body text) + list of buttons + Back' screen.

    Player Hub, Studio, Mods and any future top-level category page
    (MAIN MENU\\Player Hub, MAIN MENU\\Studio, MAIN MENU\\Mods, ...) build on
    this instead of each hand-rolling another one-off menu loop — the same
    fit->compress->scroll layout and full keyboard focus/navigation the Main
    Menu uses (the UI foundation: UIManager/UIVerticalFlow/UIScrollView) is
    written once here. Also doubles as a plain "coming soon" placeholder
    screen when `entries` is empty and `body_fn` explains what's missing —
    so unfinished areas of the new navigation tree are still real, navigable
    screens rather than silently absent buttons.
    """

    def __init__(self, settings, screen, title_fn, entries, body_fn=None):
        """entries: list of (key, text_fn, color, handler) — same shape as
        MainMenu._menu_entries(); handler() is called on activation. A
        'Back' entry is added automatically."""
        self.settings = settings
        self.screen = screen
        self.title_fn = title_fn
        self.entries = entries
        self.body_fn = body_fn
        self.runtime = None  # set by whoever opens this, like every other sub-screen
        self.current_language = settings.language
        # Optional live preview: a subclass sets preview_draw(surface, rect)
        # and the menu then takes the left part of the window while the
        # preview fills the right part (see _preview_split()).
        if not hasattr(self, 'preview_draw'):
            self.preview_draw = None
        self._init_ui()

    def _preview_split(self):
        """(menu_width, preview_rect or None) for the current window size."""
        sw, sh = self.screen.get_size()
        if self.preview_draw is None or sw < 520:
            return sw, None
        menu_w = int(sw * 0.52)
        margin = max(12, int(sw * 0.03))
        rect = pygame.Rect(menu_w, margin, sw - menu_w - margin, sh - 2 * margin)
        return menu_w, rect

    def _init_ui(self):
        self.ui = UIManager(lambda: self.screen.get_rect(), self.settings.language)
        self.view = UIScrollView(self.screen.get_rect())
        self.ui.add(self.view)
        self._widgets = {}
        self._order = []
        self._populate_widgets()
        self._sig = None
        self._clock = pygame.time.Clock()
        self._dt = 1 / 60.0
        self._running = True
        self._build()
        w = self._widgets
        first = next((k for k in self._order if isinstance(w[k], UIButton)), 'back')
        self.ui.focus_key(first)

    def _populate_widgets(self):
        """Fill self._widgets / self._order. Subclasses that need extra
        widgets (a text field, a list of checkboxes, ...) override this —
        never _init_ui() itself, since _init_ui() calls _build() right
        after this returns and _build() is often overridden too; building
        before every widget it needs exists would crash."""
        w = self._widgets
        w['title'] = UILabel(self.title_fn, size=40, align='center', style='bold')
        self._order.append('title')
        if self.body_fn is not None:
            w['body'] = UILabel(self.body_fn, align='center', wrap=True, size=20)
            self._order.append('body')
        for key, text_fn, color, handler in self.entries:
            w[key] = UIButton(text_fn, color=color, key=key, on_activate=handler)
            self._order.append(key)
        w['back'] = UIButton(lambda: get_text(self.settings.language, 'back'),
                             color=COLORS['red'], key='back', on_activate=self._go_back)
        self._order.append('back')

    def _go_back(self):
        self._running = False

    def _build(self):
        ui, view, W = self.ui, self.view, self._widgets
        sw, sh = self.screen.get_size()
        sw, _preview_rect = self._preview_split()  # menu column width
        lang = self.settings.language
        ui.language = lang
        view.set_rect(pygame.Rect(0, 0, sw, sh))
        ref = min(sw, sh)
        font_size = max(15, min(24, int(ref * 0.04)))
        btn_h = max(36, min(60, int(sh * 0.075)))
        min_btn_h = max(26, int(btn_h * 0.66))
        gap = max(6, min(20, int(btn_h * 0.3)))
        title_size = max(28, min(52, int(ref * 0.07)))
        title_h = get_font(lang, 'bold', title_size).get_height() + 20
        W['title'].size = title_size
        widest = 0
        for k in self._order:
            b = W[k]
            if isinstance(b, UIButton):
                b.font_size = font_size
                widest = max(widest, ui_text_size(lang, 'bold', font_size, b.val(b.text))[0])
        bw = min(int(sw * 0.92), max(max(160, min(320, int(sw * 0.28))), widest + 44))
        pad_v = max(8, int(sh * 0.03))

        def build(width):
            flow = UIVerticalFlow(pygame.Rect(0, 0, width, sh), padding=(0, pad_v), spacing=gap,
                                  min_spacing=2, valign='center')
            for k in self._order:
                if k == 'title':
                    flow.add(k, title_h, min_h=int(title_h * 0.55))
                elif k == 'body':
                    body_h = W['body'].measure(bw) + 16
                    has_bar = any(isinstance(W[other], UIProgressBar) for other in self._order)
                    flow.add(k, body_h, min_h=int(body_h * 0.5), w=bw,
                             gap=gap if has_bar else gap * 2, min_gap=4)
                elif k == 'back':
                    flow.add(k, btn_h, min_h=min_btn_h, w=bw, gap=gap * 2, min_gap=4)
                elif isinstance(W[k], UIProgressBar):
                    bar_h = max(12, min(22, int(sh * 0.03)))
                    flow.add(k, bar_h, min_h=8, w=bw, gap=gap * 2, min_gap=4)
                else:
                    flow.add(k, btn_h, min_h=min_btn_h, w=bw)
            res = flow.solve()
            for k in self._order:
                view.add(W[k], res.rects[k])
            last_child_bottom = max(
                (rect.bottom for rect in res.rects.values()), default=0)
            return max(view.viewport.h, res.content_height,
                       last_child_bottom + pad_v)

        fk = ui.focused.key if ui.focused is not None else None
        view.relayout(build)
        if fk is not None:
            ui.focus_key(fk)

    def draw(self):
        _pump_audio()
        frame_start = time.perf_counter()
        scr = self.screen
        scr.fill(COLORS['dark_blue'])
        sig = (scr.get_width(), scr.get_height(), self.settings.language)
        if sig != self._sig:
            self._sig = sig
            self._build()
        self.ui.language = self.settings.language
        self.ui.update(self._dt)
        self.ui.draw(scr)
        _menu_w, preview_rect = self._preview_split()
        if preview_rect is not None and self.preview_draw is not None:
            try:
                self.preview_draw(scr, preview_rect)
            except Exception as exc:
                sgf_log.warning('Preview draw failed: %s', type(exc).__name__)
        pygame.display.flip()
        render_ms = (time.perf_counter() - frame_start) * 1000.0
        DEV_TOOLS.telemetry.record_frame(
            max(self._dt * 1000.0, render_ms), render_ms=render_ms, ui_ms=render_ms)

    def run(self):
        self._running = True
        while self._running:
            self._dt = self._clock.tick(60) / 1000.0
            self.draw()
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    pygame.quit()
                    sys.exit()
                elif event.type == pygame.VIDEORESIZE:
                    self.screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)
                elif (event.type == pygame.KEYDOWN and event.key == pygame.K_F8
                      and 'DEV_TOOLS' in globals() and DEV_TOOLS.unlocked):
                    DEV_TOOLS.open_panel(self.screen, game=None)
                elif (event.type == pygame.KEYDOWN and event.key == pygame.K_F9
                      and 'DEV_TOOLS' in globals() and DEV_TOOLS.unlocked):
                    DEV_TOOLS.toggle_overlay_hidden()
                else:
                    action = self.ui.handle_event(event)
                    if action == 'BACK':
                        self._running = False
                    elif action == 'TOGGLE_FULLSCREEN':
                        self.screen = _toggle_fullscreen(self.screen)
        self.current_language = self.settings.language


class UIProgressBar(UIWidget):
    """A read-only progress bar (XP, loading...). ``fraction`` is a number or a function returning
    0..1 (clamped); the fill never relies on colour alone, because the track is always visible and
    the amount is the length of the fill."""
    focusable = False
    interactive = False

    def __init__(self, fraction, rect=None, color=None, key=None):
        super().__init__(rect, key=key)
        self.fraction = fraction
        self.color = color if color is not None else COLORS['green']

    def value(self):
        try:
            return max(0.0, min(1.0, float(self.val(self.fraction))))
        except (TypeError, ValueError, ZeroDivisionError):
            return 0.0

    def draw(self, surface):
        r = self.rect
        if not self.visible or r.w <= 0 or r.h <= 0:
            return
        radius = max(2, r.h // 2)
        pygame.draw.rect(surface, (34, 44, 74), r, border_radius=radius)
        fill = self.value()
        if fill > 0.0:
            width = max(r.h, int(round(r.w * fill)))       # never thinner than a dot, so it stays visible
            pygame.draw.rect(surface, self.color, pygame.Rect(r.x, r.y, min(width, r.w), r.h),
                             border_radius=radius)
        pygame.draw.rect(surface, (120, 135, 175), r, 1, border_radius=radius)


class UIScrollText(UILabel):
    """Wrapped text for a UIScrollView. It wraps once per (language, size, width,
    text) and draws only the lines that are on screen, so a huge document (the
    licence) costs the same per frame as a short one."""

    def __init__(self, text, size=20, line_gap=3, key=None):
        super().__init__(text, style='regular', size=size, align='left', wrap=True,
                         line_gap=line_gap, key=key)
        self._wrap_key = None
        self._wrap_lines = ['']

    def _lines(self, width):
        text = self.val(self.text)
        key = (self.lang(), self.size, width, text)
        if key != self._wrap_key:
            self._wrap_lines = ui_wrap_text(self.lang(), self.style, self.size, text, width)
            self._wrap_key = key
        return self._wrap_lines

    def content_height(self, width):
        return len(self._lines(width)) * (self.line_height() + self.line_gap)

    def draw(self, surface):
        if not self.visible or self.rect.w <= 0:
            return
        lang, r = self.lang(), self.rect
        lines = self._lines(r.w)
        step = self.line_height() + self.line_gap
        clip = surface.get_clip()
        first = max(0, (clip.top - r.y) // step)
        last = min(len(lines), (clip.bottom - r.y) // step + 1)
        right_to_left = lang in ('ar', 'he')
        y = r.y + first * step
        for index in range(first, last):
            line = lines[index]
            if line:
                rendered = ui_text_surface(lang, self.style, self.size, line, self.color)
                surface.blit(rendered, (r.right - rendered.get_width() if right_to_left else r.x, y))
            y += step


class _TextViewScreen(_SimpleMenuScreen):
    """Title on top, a scrollable text panel in the middle and the buttons pinned
    at the bottom. Used for every long text (Stats, LAN Leaderboard, Licence,
    Third-party notices, Modding Guide, Privacy Center): the text scrolls with the
    wheel, PgUp/PgDn/Home/End, the arrow keys and the scrollbar, and is never
    squashed or cut off by the buttons like the plain menu layout did."""

    def _populate_widgets(self):
        super()._populate_widgets()
        if 'body' in self._order:
            self._order.remove('body')
            self._widgets.pop('body', None)
        self.text_view = UIScrollView(self.screen.get_rect(), key='text_view', bg=(22, 30, 54),
                                      border=(60, 75, 120), radius=10, padding=12)
        self.text = UIScrollText(self.body_fn if self.body_fn is not None else '', size=20, key='text')
        self.ui.add(self.text_view)

    def _build(self):
        ui, view, W = self.ui, self.view, self._widgets
        sw, sh = self.screen.get_size()
        lang = self.settings.language
        ui.language = lang
        view.set_rect(pygame.Rect(0, 0, sw, sh))
        ref = min(sw, sh)
        margin = max(10, int(ref * 0.035))
        btn_h = max(34, min(54, int(sh * 0.07)))
        gap = max(6, int(btn_h * 0.25))
        title_size = max(26, min(46, int(ref * 0.065)))
        title_h = get_font(lang, 'bold', title_size).get_height() + 12
        W['title'].size = title_size
        font_size = max(15, min(22, int(ref * 0.036)))
        buttons = [key for key in self._order if key != 'title']
        widest = 0
        for key in buttons:
            W[key].font_size = font_size
            widest = max(widest, ui_text_size(lang, 'bold', font_size, W[key].val(W[key].text))[0])
        bw = min(sw - 2 * margin, max(200, min(340, int(sw * 0.4)), widest + 44))
        bottom_h = len(buttons) * btn_h + (len(buttons) - 1) * gap
        col_w = min(sw - 2 * margin, 780)
        title_rect = pygame.Rect(margin, margin // 2, sw - 2 * margin, title_h)
        text_top = title_rect.bottom + gap
        text_rect = pygame.Rect((sw - col_w) // 2, text_top, col_w,
                                max(60, sh - margin - bottom_h - gap - text_top))
        rects = {'title': title_rect}
        y = sh - margin - bottom_h
        for key in buttons:
            rects[key] = pygame.Rect((sw - bw) // 2, y, bw, btn_h)
            y += btn_h + gap

        def build(_width):
            for key in self._order:
                view.add(W[key], rects[key])
            return sh

        def build_text(width):
            self.text.size = font_size
            height = self.text.content_height(width)
            self.text_view.add(self.text, pygame.Rect(0, 0, width, height))
            return height

        focused = ui.focused.key if ui.focused is not None else None
        view.relayout(build)
        for key in self._order:
            # The buttons are laid out in the (never scrolling) main view; without this a focused
            # button would make that view the "active" one and PgUp/PgDn/arrows would never reach the text.
            W[key].scroll_parent = None
        self.text_view.set_rect(text_rect)
        self.text_view.relayout(build_text)
        if focused is not None:
            ui.focus_key(focused)


# ---------------------------------------------------------------------------
# Studio creators: Theme Creator and Challenge Creator. Studio is where the
# player CREATES things, so both really create and save something.
# ---------------------------------------------------------------------------
class _CreatorFormScreen(_SimpleMenuScreen):
    """_SimpleMenuScreen whose rows can also be plain labels, text inputs and
    sliders. Subclasses add the widgets in _populate_widgets() (inserting the
    keys into self._order) and record each extra key's kind in _row_kinds
    ('label', 'input' or 'slider'); every other key is a button."""

    _row_kinds = {}

    def _build(self):
        ui, view, W = self.ui, self.view, self._widgets
        sw, sh = self.screen.get_size()
        sw, _preview_rect = self._preview_split()      # menu column width
        lang = self.settings.language
        ui.language = lang
        view.set_rect(pygame.Rect(0, 0, sw, sh))
        ref = min(sw, sh)
        btn_h = max(36, min(60, int(sh * 0.075)))
        min_btn_h = max(26, int(btn_h * 0.66))
        gap = max(6, min(20, int(btn_h * 0.3)))
        title_size = max(28, min(52, int(ref * 0.07)))
        title_h = get_font(lang, 'bold', title_size).get_height() + 20
        W['title'].size = title_size
        label_h = get_font(lang, 'regular', 22).get_height()
        input_h = max(32, min(50, int(sh * 0.06)))
        slider_h = max(28, min(40, int(sh * 0.055)))
        font_size = max(15, min(24, int(ref * 0.04)))
        bw = min(int(sw * 0.92), max(160, min(360, int(sw * 0.84))))
        for key in self._order:
            if isinstance(W[key], UIButton):
                W[key].font_size = font_size
            elif isinstance(W[key], UITextInput):
                W[key].size = max(16, min(24, int(ref * 0.04)))
        pad_v = max(8, int(sh * 0.03))

        def build(width):
            flow = UIVerticalFlow(pygame.Rect(0, 0, width, sh), padding=(0, pad_v),
                                  spacing=gap, min_spacing=2, valign='center')
            for key in self._order:
                kind = self._row_kinds.get(key)
                if key == 'title':
                    flow.add(key, title_h, min_h=int(title_h * 0.55))
                elif key == 'body':
                    body_h = W['body'].measure(bw) + 12
                    flow.add(key, body_h, min_h=max(24, int(body_h * 0.55)), w=bw, gap=gap, min_gap=2)
                elif kind == 'label':
                    flow.add(key, label_h, min_h=int(label_h * 0.8), w=bw, gap=gap, min_gap=2)
                elif kind == 'input':
                    flow.add(key, input_h, min_h=int(input_h * 0.75), w=bw, gap=4, min_gap=2)
                elif kind == 'slider':
                    flow.add(key, slider_h, min_h=int(slider_h * 0.8), w=bw, gap=4, min_gap=2)
                elif key == 'back':
                    flow.add(key, btn_h, min_h=min_btn_h, w=bw, gap=gap * 2, min_gap=4)
                else:
                    flow.add(key, btn_h, min_h=min_btn_h, w=bw)
            res = flow.solve()
            for key in self._order:
                view.add(W[key], res.rects[key])
            last_child_bottom = max((rect.bottom for rect in res.rects.values()), default=0)
            return max(view.viewport.h, res.content_height, last_child_bottom + pad_v)

        focused = ui.focused.key if ui.focused is not None else None
        view.relayout(build)
        if focused is not None:
            ui.focus_key(focused)


# The four parts of a theme the player can colour, and the colour keys each one sets.
_THEME_CREATOR_SLOTS = (
    ('tc_background', ('dark_blue', 'background')),
    ('tc_buttons', ('button', 'key_bg')),
    ('tc_board', ('board_background',)),
    ('tc_accent', ('blue',)),
)


def _theme_creator_colors(values):
    """Expand the four chosen colours into the colour keys a theme overrides."""
    colors = {}
    for (_label, keys), rgb in zip(_THEME_CREATOR_SLOTS, values):
        for key in keys:
            colors[key] = [max(0, min(255, int(channel))) for channel in rgb[:3]]
    colors['grid_line'] = [min(255, int(channel) + 28) for channel in values[2][:3]]
    return colors


def _save_user_theme(name, values):
    """Write a new user theme (themes/<id>/theme.json) and register it.

    Validates before touching the disk, writes atomically and returns the new id."""
    name = name.strip() if isinstance(name, str) else ''
    if not name or len(name) > 40 or any(ord(char) < 32 for char in name):
        raise ValueError('Theme name is invalid')
    theme_id = 'user-' + _hashlib.sha256(
        f'{name}|{time.time_ns()}'.encode('utf-8')).hexdigest()[:12]
    manifest = {
        'id': theme_id, 'name': name, 'version': '1.0.0', 'game_version': '*',
        'theme_api_version': THEME_API_VERSION, 'extends': 'default',
        'colors': _theme_creator_colors(values),
    }
    ThemeDefinition(manifest).validate()
    folder = os.path.join(_user_data_manager.get_theme_dir(), theme_id)
    os.makedirs(folder, exist_ok=True)
    _atomic_write_json(os.path.join(folder, 'theme.json'), manifest)
    THEME_MANAGER.register_theme(ThemeDefinition(
        manifest, root_dir=folder, source_owner=f'theme:{theme_id}'))
    return theme_id


class ThemeCreatorScreen(_CreatorFormScreen):
    """Create a theme: name it, pick a part (background, buttons, board, accent)
    and mix its colour with three sliders. Every change shows live on the real
    screen and in the preview; Save writes the theme and applies it, Back puts
    the old look back."""

    _row_kinds = {'name_label': 'label', 'name_input': 'input',
                  'c_r': 'slider', 'c_g': 'slider', 'c_b': 'slider'}

    def __init__(self, settings, screen):
        self.theme_manager = THEME_MANAGER
        self.original_active_theme_id = THEME_MANAGER.active_theme_id
        self.original_setting_theme_id = getattr(settings, 'theme_id', 'default')
        self.values = [list(COLORS[keys[0]])[:3] for _label, keys in _THEME_CREATOR_SLOTS]
        self.part = 0
        self.saved_theme_id = None
        self.error = False
        self.preview_draw = self._draw_preview
        super().__init__(
            settings, screen,
            title_fn=lambda: get_text(settings.language, 'theme_creator'),
            entries=[('save_theme', lambda: get_text(settings.language, 'save'),
                      COLORS['green'], self._save)],
            body_fn=self._body_text)

    def _populate_widgets(self):
        super()._populate_widgets()
        w = self._widgets
        w['name_label'] = UILabel(lambda: get_text(self.settings.language, 'name'),
                                  size=22, align='center')
        w['name_input'] = UITextInput(
            text='', max_len=40, key='name_input', size=24, align='center',
            placeholder=lambda: get_text(self.settings.language, 'name'),
            advance_on_submit=True)
        w['part'] = UIButton(
            lambda: get_text(self.settings.language, _THEME_CREATOR_SLOTS[self.part][0]),
            color=COLORS['blue'], key='part', on_activate=self._next_part)
        extra = ['name_label', 'name_input', 'part']
        for index, channel in enumerate('rgb'):
            w['c_' + channel] = UISlider(
                minimum=0, maximum=255, value=self.values[self.part][index], step=1,
                key='c_' + channel, fmt=lambda v, ch=channel: f'{ch.upper()} {int(v)}',
                on_change=lambda v, i=index: self._set_channel(i, v))
            extra.append('c_' + channel)
        at = self._order.index('save_theme')
        self._order[at:at] = extra

    def _body_text(self):
        if self.error:
            return get_text(self.settings.language, 'theme_save_failed')
        return get_text(self.settings.language, 'tc_help')

    def _apply_live(self):
        try:
            self.theme_manager._apply_colors({'colors': _theme_creator_colors(self.values)})
        except Exception as exc:
            sgf_log.warning('Theme live preview failed: %s', type(exc).__name__)

    def _set_channel(self, index, value):
        self.values[self.part][index] = int(value)
        self._apply_live()

    def _next_part(self):
        self.part = (self.part + 1) % len(_THEME_CREATOR_SLOTS)
        for index, channel in enumerate('rgb'):
            self._widgets['c_' + channel].set_value(self.values[self.part][index], notify=False)

    def _draw_preview(self, surface, rect):
        pygame.draw.rect(surface, COLORS['board_background'], rect, border_radius=12)
        pygame.draw.rect(surface, COLORS['grid_line'], rect, 2, border_radius=12)
        cell = max(10, min(rect.w - 24, rect.h // 2) // 10)
        cols, rows = (rect.w - 24) // cell, (rect.h // 2 - 12) // cell
        left, top = rect.x + 12, rect.y + 12
        for col in range(cols + 1):
            pygame.draw.line(surface, COLORS['grid_line'], (left + col * cell, top),
                             (left + col * cell, top + rows * cell))
        for row in range(rows + 1):
            pygame.draw.line(surface, COLORS['grid_line'], (left, top + row * cell),
                             (left + cols * cell, top + row * cell))
        for index in range(min(4, cols - 2)):
            part = pygame.Rect(left + (1 + index) * cell + 2, top + (rows // 2) * cell + 2,
                               cell - 4, cell - 4)
            pygame.draw.rect(surface, COLORS['snake_head'] if index == 3 else COLORS['snake'],
                             part, border_radius=3)
        pygame.draw.circle(surface, COLORS['fruit'],
                           (left + min(cols - 1, 7) * cell + cell // 2,
                            top + (rows // 2) * cell + cell // 2), max(3, cell // 2 - 3))
        button = pygame.Rect(rect.x + 16, rect.centery + 16, rect.w - 32,
                             max(30, min(56, rect.h // 8)))
        pygame.draw.rect(surface, COLORS['button'], button, border_radius=10)
        label = render_fit(get_font(self.settings.language, 'bold', 20),
                           get_text(self.settings.language, 'tc_buttons'),
                           COLORS['white'], button.w - 16)
        surface.blit(label, label.get_rect(center=button.center))
        accent = pygame.Rect(button.x, button.bottom + 12, button.w, 8)
        pygame.draw.rect(surface, COLORS['blue'], accent, border_radius=4)

    def _save(self):
        field = self._widgets['name_input']
        if not field.text.strip():
            field.flash()
            return
        try:
            theme_id = _save_user_theme(field.text, self.values)
            self.theme_manager.apply(theme_id)
            self.settings.theme_id = theme_id
            if self.settings.save() is False:
                raise IOError('Theme settings could not be saved')
        except Exception as exc:
            sgf_log.warning('Could not save the new theme: %s', type(exc).__name__)
            self.settings.theme_id = self.original_setting_theme_id
            self.theme_manager.apply(self.original_active_theme_id)
            self.error = True
            self._sig = None
            return
        self.saved_theme_id = theme_id
        self._running = False

    def _go_back(self):
        if self.saved_theme_id is None:
            self.theme_manager.apply(self.original_active_theme_id)
        super()._go_back()


_CHALLENGE_MODIFIER_KEYS = {'classic': 'daily_modifier_classic', 'wrap_walls': 'daily_modifier_wrap'}


class ChallengeBuilderScreen(_CreatorFormScreen):
    """Create a challenge: optional name, one of the player's maps, the rule
    (classic or wrap walls) and the speed. Create saves it (content-derived id
    and seed, like every other challenge) and hands it back to the Studio."""

    _row_kinds = {'name_label': 'label', 'name_input': 'input'}

    def __init__(self, settings, screen):
        self.maps = _load_custom_maps()
        self.map_names = sorted(self.maps, key=lambda item: item.casefold())
        self.map_index = 0
        self.modifier_index = 0
        self.speed_index = min(1, len(_CUSTOM_CHALLENGE_SPEEDS) - 1)
        self.created_challenge = None
        self.open_map_editor = False
        self.error = False
        if self.map_names:
            entries = [('create_challenge',
                        lambda: get_text(settings.language, 'challenge_create'),
                        COLORS['green'], self._create)]
        else:
            entries = [('open_map_editor',
                        lambda: get_text(settings.language, 'map_creator'),
                        COLORS['blue'], self._request_map_editor)]
        super().__init__(
            settings, screen,
            title_fn=lambda: get_text(settings.language, 'challenge_new'),
            entries=entries, body_fn=self._body_text)

    def _populate_widgets(self):
        super()._populate_widgets()
        if not self.map_names:
            return
        w = self._widgets
        lang = lambda: self.settings.language
        w['name_label'] = UILabel(lambda: get_text(lang(), 'name'), size=22, align='center')
        w['name_input'] = UITextInput(
            text='', max_len=80, key='name_input', size=24, align='center',
            placeholder=lambda: get_text(lang(), 'name'),
            on_change=lambda _value: setattr(self, 'error', False),
            advance_on_submit=True)
        w['map_pick'] = UIButton(
            lambda: f"{get_text(lang(), 'challenge_map')}: {self.map_names[self.map_index]}",
            color=COLORS['blue'], key='map_pick', on_activate=self._next_map)
        w['rule_pick'] = UIButton(
            lambda: get_text(lang(), _CHALLENGE_MODIFIER_KEYS[
                _CUSTOM_CHALLENGE_MODIFIERS[self.modifier_index]]),
            color=COLORS['purple'], key='rule_pick', on_activate=self._next_rule)
        w['speed_pick'] = UIButton(
            lambda: f"{get_text(lang(), 'speed')}: {_CUSTOM_CHALLENGE_SPEEDS[self.speed_index]} ms",
            color=COLORS['blue'], key='speed_pick', on_activate=self._next_speed)
        at = self._order.index('create_challenge')
        self._order[at:at] = ['name_label', 'name_input', 'map_pick', 'rule_pick', 'speed_pick']

    def _body_text(self):
        lang = self.settings.language
        if not self.map_names:
            return _no_maps_text(lang)
        if self.error:
            return get_text(lang, 'challenge_create_failed')
        data = self.maps[self.map_names[self.map_index]]
        return f"{self.map_names[self.map_index]} · {data.get('board_width')}x{data.get('board_height')}"

    def _next_map(self):
        self.map_index = (self.map_index + 1) % len(self.map_names)
        self.error = False

    def _next_rule(self):
        self.modifier_index = (self.modifier_index + 1) % len(_CUSTOM_CHALLENGE_MODIFIERS)

    def _next_speed(self):
        self.speed_index = (self.speed_index + 1) % len(_CUSTOM_CHALLENGE_SPEEDS)

    def _request_map_editor(self):
        self.open_map_editor = True
        self._running = False

    def _create(self):
        map_name = self.map_names[self.map_index]
        try:
            challenge = _create_or_load_custom_challenge(
                map_name, self.maps[map_name],
                _CUSTOM_CHALLENGE_MODIFIERS[self.modifier_index],
                _CUSTOM_CHALLENGE_SPEEDS[self.speed_index])
            label = self._widgets['name_input'].text.strip()
            if label and label != challenge['display_name']:
                challenge = _rename_custom_challenge(challenge['challenge_id'], label)
        except Exception as exc:
            sgf_log.warning('Could not create the challenge: %s', type(exc).__name__)
            self.error = True
            self._sig = None
            return
        self.created_challenge = challenge
        self._running = False


class ThemeEditorScreen(_SimpleMenuScreen):
    """Preview themes in place and either persist the choice or roll it back."""

    def __init__(self, settings, screen, allow_create=False):
        self.theme_manager = THEME_MANAGER
        self.original_active_theme_id = self.theme_manager.active_theme_id
        self.original_setting_theme_id = getattr(settings, 'theme_id', 'default')
        self.preview_theme_id = self.original_active_theme_id
        self.preview_valid = True
        self.preview_error_key = None
        self.committed = False
        self.create_requested = False

        entries = []
        if allow_create:
            entries.append((
                'new_theme', lambda: get_text(self.settings.language, 'theme_new'),
                COLORS['green'], self._request_create))
        for theme_id in self.theme_manager.ids():
            theme = self.theme_manager.get_theme(theme_id)
            theme_name = theme.name if theme else theme_id
            entries.append((
                f'theme_{theme_id}',
                lambda name=theme_name, tid=theme_id:
                    f"{name} · {_t_or(self.settings.language, 'map_theme_selected', 'Selected')}"
                    if self.preview_theme_id == tid else name,
                COLORS['blue'],
                lambda tid=theme_id: self._preview_theme(tid),
            ))
        entries.append((
            'apply_theme',
            lambda: get_text(self.settings.language, 'theme_apply'),
            COLORS['green'], self._commit_preview))
        super().__init__(
            settings, screen,
            title_fn=lambda: get_text(self.settings.language, 'theme_creator'),
            entries=entries, body_fn=self._status_text)

    def _request_create(self):
        self.create_requested = True
        self._go_back()          # puts the previewed theme back, then leaves

    def _status_text(self):
        if self.preview_error_key:
            return get_text(self.settings.language, self.preview_error_key)
        theme = self.theme_manager.get_theme(self.preview_theme_id)
        return get_text(self.settings.language, 'theme_preview_status').format(
            theme=theme.name if theme else self.preview_theme_id)

    def _preview_theme(self, theme_id):
        try:
            applied = self.theme_manager.apply(theme_id)
            self.preview_theme_id = applied
            self.preview_valid = applied == theme_id
            self.preview_error_key = (
                None if self.preview_valid else 'theme_preview_failed')
        except Exception:
            self.preview_valid = False
            self.preview_error_key = 'theme_preview_failed'

    def _commit_preview(self):
        if not self.preview_valid:
            return
        try:
            self.settings.theme_id = self.preview_theme_id
            if self.settings.save() is False:
                raise IOError('Theme settings could not be saved')
        except Exception:
            self.settings.theme_id = self.original_setting_theme_id
            self.theme_manager.apply(self.original_active_theme_id)
            self.preview_theme_id = self.theme_manager.active_theme_id
            self.preview_valid = self.preview_theme_id == self.original_active_theme_id
            self.preview_error_key = 'theme_save_failed'
            return
        self.committed = True
        self._running = False

    def _go_back(self):
        if not self.committed:
            self.settings.theme_id = self.original_setting_theme_id
            if self.theme_manager.active_theme_id != self.original_active_theme_id:
                self.theme_manager.apply(self.original_active_theme_id)
        super()._go_back()


class CosmeticSelectionScreen(_SimpleMenuScreen):
    """Stage an appearance choice, preview it, then save or roll it back."""

    def __init__(self, settings, screen, *, title_fn, options, initial_value,
                 preview_fn, commit_fn, selected_key, extra_status_fn=None,
                 can_select_fn=None, preview_draw=None, progress_fn=None):
        self.preview_draw = preview_draw
        self.progress_fn = progress_fn            # 0..1 -> a bar under the status text (e.g. XP)
        self.original_value = initial_value
        self.preview_value = initial_value
        self.preview_fn = preview_fn
        self.commit_fn = commit_fn
        self.selected_key = selected_key
        self.extra_status_fn = extra_status_fn
        self.can_select_fn = can_select_fn
        self.apply_error = False
        self.committed = False
        self._option_names = {value: label_fn for value, label_fn, _color in options}

        entries = []
        for value, label_fn, color in options:
            def label(value=value, label_fn=label_fn):
                name = label_fn()
                if self.preview_value == value:
                    return f"{name} · {get_text(self.settings.language, self.selected_key)}"
                return name
            entries.append((
                f'appearance_{value}', label, color,
                lambda value=value: self._preview_selection(value)))
        entries.append((
            'apply_selection',
            lambda: get_text(self.settings.language, 'apply_selection'),
            COLORS['green'], self._commit_selection))
        super().__init__(settings, screen, title_fn=title_fn, entries=entries,
                         body_fn=self._status_text)

    def _populate_widgets(self):
        super()._populate_widgets()
        if self.progress_fn is not None and 'body' in self._order:
            self._widgets['progress'] = UIProgressBar(self.progress_fn, key='progress')
            self._order.insert(self._order.index('body') + 1, 'progress')

    def _status_text(self):
        if self.apply_error:
            return get_text(self.settings.language, 'cosmetic_save_failed')
        label_fn = self._option_names.get(self.preview_value)
        name = label_fn() if label_fn else str(self.preview_value)
        status = get_text(self.settings.language, 'cosmetic_preview_status').format(
            name=name)
        if self.extra_status_fn:
            status += '\n' + self.extra_status_fn()
        return status

    def _preview_selection(self, value):
        if self.can_select_fn and not self.can_select_fn(value):
            return
        self.preview_fn(value)
        self.preview_value = value
        self.apply_error = False

    def _commit_selection(self):
        try:
            result = self.commit_fn(self.preview_value)
            if result is False:
                raise IOError('Appearance selection could not be saved')
        except Exception:
            self.preview_fn(self.original_value)
            self.preview_value = self.original_value
            self.apply_error = True
            return
        self.committed = True
        self._running = False

    def _go_back(self):
        if not self.committed:
            self.preview_fn(self.original_value)
            self.preview_value = self.original_value
        super()._go_back()


