def _date_state_path():
    return os.path.join(_user_data_manager.get_config_dir(), 'date_format.json')


def date_format_name():
    if not _DATE_STATE['loaded']:
        _DATE_STATE['loaded'] = True
        try:
            with open(_date_state_path(), 'r', encoding='utf-8') as handle:
                stored = json.load(handle)
            if isinstance(stored, dict) and stored.get('format') in DATE_FORMATS:
                _DATE_STATE['format'] = stored['format']
        except (OSError, ValueError):
            pass
    return _DATE_STATE['format']


def set_date_format(name):
    if name not in DATE_FORMATS:
        return
    _DATE_STATE['loaded'] = True
    _DATE_STATE['format'] = name
    try:
        _atomic_write_json(_date_state_path(), {'version': 1, 'format': name})
    except Exception as exc:
        _logging_mod.getLogger('sgf').warning('Could not save the date format: %s', exc)


def format_date(value):
    """Draw-ready date for a datetime/date or a POSIX timestamp ('—' if none)."""
    try:
        if value is None:
            return '—'
        if isinstance(value, (int, float)):
            value = datetime.fromtimestamp(value)
        return value.strftime(_DATE_STRFTIME[date_format_name()])
    except (ValueError, OSError, OverflowError, AttributeError):
        return '—'


def format_date_text(text):
    """Re-format a stored ISO-style text ('2026-10-08', '2026-10-08 15:18' or
    a full ISO timestamp). Anything else is returned untouched."""
    match = _DATE_TEXT_RE.match(str(text or ''))
    if not match:
        return str(text or '')
    year, month, day, hour, minute, _second = match.groups()
    try:
        day_text = datetime(int(year), int(month), int(day)).strftime(_DATE_STRFTIME[date_format_name()])
    except ValueError:
        return str(text)
    return f'{day_text} {hour}:{minute}' if hour is not None else day_text


def _date_pattern_label(language, name=None):
    year = (_DATE_LABELS.get(language) or _DATE_LABELS['en'])['year']
    return {'dmy': f'dd/mm/{year}', 'mdy': f'mm/dd/{year}',
            'ymd': f'{year}-mm-dd'}[name or date_format_name()]


def _date_format_button_text(language):
    label = (_DATE_LABELS.get(language) or _DATE_LABELS['en'])['label']
    return f'{label}: {_date_pattern_label(language)}'


