def _graphics_label(language, key):
    table = _GRAPHICS_LABELS.get(language) or _GRAPHICS_LABELS['en']
    return table.get(key) or _GRAPHICS_LABELS['en'][key]


def _graphics_state_path():
    return os.path.join(_user_data_manager.get_config_dir(), 'graphics.json')


def graphics_state():
    if not _GRAPHICS_STATE['loaded']:
        _GRAPHICS_STATE['loaded'] = True
        try:
            with open(_graphics_state_path(), 'r', encoding='utf-8') as handle:
                stored = json.load(handle)
            if isinstance(stored, dict):
                if stored.get('frame_cap') in GRAPHICS_FRAME_CAPS:
                    _GRAPHICS_STATE['frame_cap'] = stored['frame_cap']
                if stored.get('ssaa') in GRAPHICS_SSAA_LEVELS:
                    _GRAPHICS_STATE['ssaa'] = stored['ssaa']
                if isinstance(stored.get('background_saver'), bool):
                    _GRAPHICS_STATE['background_saver'] = stored['background_saver']
        except (OSError, ValueError):
            pass
    return _GRAPHICS_STATE


def graphics_set(**changes):
    state = graphics_state()
    for key, value in changes.items():
        if key == 'frame_cap' and value in GRAPHICS_FRAME_CAPS:
            state['frame_cap'] = value
        elif key == 'ssaa' and value in GRAPHICS_SSAA_LEVELS:
            state['ssaa'] = value
        elif key == 'background_saver':
            state['background_saver'] = bool(value)
    try:
        _atomic_write_json(_graphics_state_path(), {
            'version': 1, 'frame_cap': state['frame_cap'], 'ssaa': state['ssaa'],
            'background_saver': state['background_saver']})
    except Exception as exc:
        _logging_mod.getLogger('sgf').warning('Could not save graphics settings: %s', exc)


def _graphics_network_busy():
    """True while something must keep running at full speed: a network match or
    lobby (counted by the wrapped screens) or a live tunnel/connection thread."""
    if _GRAPHICS_NETWORK_DEPTH[0] > 0 or _ACTIVE_HOST_LOBBY[0] is not None:
        return True
    try:
        return any(t.name.lower().startswith(_GRAPHICS_NETWORK_THREAD_PREFIXES)
                   for t in threading.enumerate() if t.is_alive())
    except Exception:
        return True      # when unsure, never slow the game down


def _graphics_window_minimized():
    try:
        return bool(pygame.display.get_init() and pygame.display.get_surface() is not None
                    and not pygame.display.get_active())
    except pygame.error:
        return False


