def _autotune_label(language, key, **values):
    table = _AUTOTUNE_LABELS.get(language) or _AUTOTUNE_LABELS['en']
    text = table.get(key) or _AUTOTUNE_LABELS['en'].get(key, key)
    try:
        return text.format(**values) if values else text
    except (KeyError, IndexError, ValueError):
        return text


def _total_ram_bytes():
    """Physical memory in bytes, or None. psutil when present, otherwise the operating system."""
    try:
        import psutil
        return int(psutil.virtual_memory().total)
    except Exception:
        pass
    try:
        if sys.platform == 'win32':
            import ctypes

            class _MemoryStatus(ctypes.Structure):
                _fields_ = [('length', ctypes.c_ulong), ('load', ctypes.c_ulong),
                            ('total', ctypes.c_ulonglong), ('avail', ctypes.c_ulonglong),
                            ('page_total', ctypes.c_ulonglong), ('page_avail', ctypes.c_ulonglong),
                            ('virtual_total', ctypes.c_ulonglong), ('virtual_avail', ctypes.c_ulonglong),
                            ('extended', ctypes.c_ulonglong)]
            status = _MemoryStatus()
            status.length = ctypes.sizeof(_MemoryStatus)
            if ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(status)):
                return int(status.total)
        elif os.path.exists('/proc/meminfo'):
            with open('/proc/meminfo', 'r', encoding='utf-8') as stream:
                for line in stream:
                    if line.startswith('MemTotal:'):
                        return int(line.split()[1]) * 1024
    except Exception:
        pass
    return None


def detect_hardware():
    """What can be learned about this computer from the standard library and pygame. The graphics
    card is not exposed by pygame, so it is reported as undetected rather than guessed."""
    info = {'cpu_count': os.cpu_count() or 0, 'ram_bytes': _total_ram_bytes(), 'refresh_hz': 0,
            'display_size': None, 'gpu': None, 'platform': sys.platform}
    try:
        if pygame.display.get_init():
            rate = getattr(pygame.display, 'get_current_refresh_rate', None)
            hz = int(rate()) if rate else 0
            info['refresh_hz'] = hz if 20 <= hz <= 500 else 0
            sizes = pygame.display.get_desktop_sizes()
            if sizes:
                info['display_size'] = tuple(sizes[0])
    except Exception:
        pass
    return info


def _autotune_draw_world(surface, factor):
    """A board-like frame for the measurement: grid, a snake and some fruit at `factor` times the size."""
    width, height = surface.get_size()
    cells = 40
    cell = max(2, min(width, height) // (cells + 2))
    left, top = (width - cells * cell) // 2, (height - cells * cell) // 2
    surface.fill((20, 24, 38))
    pygame.draw.rect(surface, (32, 40, 60), (left, top, cells * cell, cells * cell))
    for index in range(cells + 1):
        pygame.draw.line(surface, (55, 65, 90), (left + index * cell, top), (left + index * cell, top + cells * cell), factor)
        pygame.draw.line(surface, (55, 65, 90), (left, top + index * cell), (left + cells * cell, top + index * cell), factor)
    for index in range(60):
        pygame.draw.rect(surface, (60, 200, 90), (left + (index % cells) * cell + 1, top + (index // cells + 5) * cell + 1,
                                                  cell - 2, cell - 2), border_radius=max(1, cell // 4))
    for index in range(8):
        pygame.draw.circle(surface, (230, 70, 70), (left + (index * 5 + 2) * cell, top + (30 - index) * cell), max(2, cell // 2 - 1))


def graphics_benchmark(size, frames=10):
    """Milliseconds per frame (median) of drawing a board-like frame without SSAA and with 2x
    SSAA at `size`, the same way the game does (draw large, then smoothscale)."""
    width = max(64, min(int(size[0]), 1920))
    height = max(64, min(int(size[1]), 1080))
    result = {}
    for factor in GRAPHICS_SSAA_LEVELS:
        big = pygame.Surface((width * factor, height * factor))
        target = pygame.Surface((width, height))
        times = []
        for _ in range(frames + 2):
            started = time.perf_counter()
            _autotune_draw_world(big, factor)
            target.blit(pygame.transform.smoothscale(big, (width, height)) if factor > 1 else big, (0, 0))
            times.append((time.perf_counter() - started) * 1000.0)
        times = sorted(times[2:])
        result[factor] = times[len(times) // 2]
    return result


def graphics_recommendation(hardware, bench, current):
    """Frame cap and SSAA that suit a computer, from what was detected and measured. Pure: no
    side effects. The cap follows the display's refresh rate (60 when unknown) and is lowered
    while the board drawing alone would take more than a quarter of the frame; SSAA is
    suggested only when its measured cost fits the same budget and the machine is not tiny."""
    caps = [cap for cap in GRAPHICS_FRAME_CAPS if cap]
    refresh = int(hardware.get('refresh_hz') or 0)
    cap = max([c for c in caps if c <= refresh] or [60]) if refresh >= 30 else 60
    plain, supersampled = float(bench.get(1, 0.0)), float(bench.get(2, 0.0))
    while cap > min(caps) and plain * 4 > 1000.0 / cap:
        cap = max(c for c in caps if c < cap)
    ram = hardware.get('ram_bytes')
    small = (hardware.get('cpu_count') or 0) < 2 or (ram is not None and ram < 2 * 1024 ** 3)
    ssaa = 2 if (not small and supersampled * 4 <= 1000.0 / cap) else 1
    return {'frame_cap': cap, 'ssaa': ssaa}


# ---------------------------------------------------------------------------
# Hardware profile: what this computer is and how fast it is, measured once on the first start and again at
# most once a day, kept in game_data.json so everything else (first-run graphics, the AI Lab) just reads it.
# ---------------------------------------------------------------------------
HARDWARE_PROFILE_VERSION = 1
_HARDWARE_PROFILE_LOCK = threading.Lock()
_HARDWARE_PROFILE_CACHE = [None]
_HARDWARE_REFRESH_THREAD = [None]


def _hardware_today():
    return datetime.now().strftime('%Y-%m-%d')


def hardware_recommendation(specs, bench):
    """Settings that suit a computer, from its specs and measured speed. Pure: no side effects.
    `lab_reduce` ('on'/'off') says whether load reduction is advisable; `lab_visual_limit` is the speed (ticks per
    second) above which drawing the AI Lab board is no longer worth it. One core is always left to the
    operating system."""
    cores = max(1, int(specs.get('cpu_count') or 1))
    ram = specs.get('ram_bytes')
    per_core = float(bench.get('ai_decisions_per_s') or 0)
    graphics = {int(k): float(v) for k, v in (bench.get('graphics_ms') or {}).items()}
    base = graphics_recommendation(
        {'cpu_count': cores, 'ram_bytes': ram, 'refresh_hz': specs.get('refresh_hz') or 0},
        {1: graphics.get(1, 0.0), 2: graphics.get(2, 0.0)}, {})
    weak = cores <= 2 or (ram is not None and ram < 4 * 1024 ** 3) or (per_core and per_core < 2500)
    workers = 1 if weak else max(1, min(cores - 1, 16))
    refresh = int(specs.get('refresh_hz') or 60)
    if per_core and per_core < 2500:
        visual_limit = 30
    elif per_core and per_core < 8000:
        visual_limit = 60
    else:
        visual_limit = max(60, min(240, refresh * 2))
    population = 8 if not per_core else int(max(4, min(64, per_core * 0.010)))      # about 10 ms of thinking per tick
    reasons = []
    if weak:
        reasons.append('weak')
    if cores > 2:
        reasons.append('leaves_one_core')
    return {'frame_cap': base['frame_cap'], 'ssaa': base['ssaa'], 'lab_workers': workers,
            'lab_resource': int(round(100.0 * (workers - 1) / max(1, cores - 1))) if cores > 1 else 0,
            'lab_population': population, 'lab_visual_limit': visual_limit,
            'lab_reduce': 'on' if weak else 'off', 'reasons': reasons}


def measure_hardware_profile(screen_size=(1280, 720), ai_seconds=0.6, graphics_frames=6):
    """Run the short benchmark (about two seconds) and build a complete profile."""
    specs = detect_hardware()
    specs['display_size'] = list(specs['display_size']) if specs.get('display_size') else None
    ai = run_ai_lab_stress_test(seconds=ai_seconds, population=8, workers=1)
    try:
        graphics = graphics_benchmark(screen_size, frames=graphics_frames)
    except Exception:
        graphics = {}
    bench = {'ai_decisions_per_s': int(ai['score']), 'ai_us_per_decision': ai['microseconds_per_decision'],
             'graphics_ms': {str(k): round(float(v), 2) for k, v in graphics.items()}}
    return {'version': HARDWARE_PROFILE_VERSION, 'specs': specs, 'bench': bench,
            'measured_at': datetime.now().isoformat(timespec='seconds'), 'tested_day': _hardware_today(),
            'recommendation': hardware_recommendation(specs, bench), 'first_run_applied': False}


def hardware_profile_stale(profile):
    """True when there is no profile, it is from an older format, or it was last measured on another day."""
    return (not isinstance(profile, dict) or profile.get('version') != HARDWARE_PROFILE_VERSION
            or profile.get('tested_day') != _hardware_today())


def hardware_profile_cached():
    """The stored profile (or None); reads game_data.json only once per run."""
    with _HARDWARE_PROFILE_LOCK:
        if _HARDWARE_PROFILE_CACHE[0] is None:
            try:
                stored = _load_data().get('hardware_profile')
                _HARDWARE_PROFILE_CACHE[0] = stored if isinstance(stored, dict) else {}
            except Exception:
                _HARDWARE_PROFILE_CACHE[0] = {}
        return dict(_HARDWARE_PROFILE_CACHE[0]) if _HARDWARE_PROFILE_CACHE[0] else None


def hardware_profile_store(profile):
    """Keep the profile in memory and in game_data.json. The specs are written when they are first measured
    and only replaced if they really changed; the daily test refreshes the numbers."""
    old = hardware_profile_cached()
    if old and old.get('specs'):
        same = all(old['specs'].get(k) == profile['specs'].get(k) for k in ('cpu_count', 'ram_bytes', 'platform'))
        if same:
            profile['specs'] = old['specs']
        else:
            profile['specs_changed_at'] = profile['measured_at']
        profile['first_run_applied'] = bool(old.get('first_run_applied')) or bool(profile.get('first_run_applied'))
    with _HARDWARE_PROFILE_LOCK:
        _HARDWARE_PROFILE_CACHE[0] = dict(profile)

    def mutate(data):
        data['hardware_profile'] = profile
        return data
    try:
        _save_data_async(mutate)
    except Exception as exc:
        _logging_mod.getLogger('sgf').warning('Could not store the hardware profile: %s', exc)
    return profile


def hardware_profile_ensure(screen_size=(1280, 720), force=False):
    """The up-to-date profile, measuring it now if there is none yet, it is from another day or `force` is set."""
    profile = hardware_profile_cached()
    if force or hardware_profile_stale(profile):
        profile = hardware_profile_store(measure_hardware_profile(screen_size))
    return profile


def hardware_profile_refresh_async(screen_size=(1280, 720)):
    """Daily check in the background, so the menu never waits for it."""
    thread = _HARDWARE_REFRESH_THREAD[0]
    if thread is not None and thread.is_alive():
        return False

    def work():
        try:
            hardware_profile_store(measure_hardware_profile(screen_size))
        except Exception as exc:
            _logging_mod.getLogger('sgf').warning('Daily hardware check failed: %s', exc)
    _HARDWARE_REFRESH_THREAD[0] = threading.Thread(target=work, name='hardware-check', daemon=True)
    _HARDWARE_REFRESH_THREAD[0].start()
    return True


def hardware_profile_startup(screen_size=(1280, 720)):
    """Called once while the game starts. First start: measure now (about two seconds, behind the loading bar) and
    apply the recommended graphics once. Later starts: use what is stored, and re-measure in the background if the
    stored test is from another day. Returns the profile."""
    profile = hardware_profile_cached()
    if not profile or profile.get('version') != HARDWARE_PROFILE_VERSION:
        profile = hardware_profile_store(measure_hardware_profile(screen_size))
        recommended = profile['recommendation']
        graphics_set(frame_cap=recommended['frame_cap'], ssaa=recommended['ssaa'])
        profile['first_run_applied'] = True
        hardware_profile_store(profile)
    elif hardware_profile_stale(profile):
        hardware_profile_refresh_async(screen_size)
    return profile


def hardware_profile_note_stress(result):
    """A stress test the player ran is a better measurement than the daily one: fold it into the profile."""
    profile = hardware_profile_cached()
    if not profile or not result:
        return None
    profile = dict(profile)
    bench = dict(profile.get('bench') or {})
    per_core = int(result['score'] / max(1, int(result.get('workers', 1))))
    bench['ai_decisions_per_s'] = per_core
    bench['ai_us_per_decision'] = result.get('microseconds_per_decision', bench.get('ai_us_per_decision'))
    profile['bench'] = bench
    profile['measured_at'] = datetime.now().isoformat(timespec='seconds')
    profile['tested_day'] = _hardware_today()
    profile['recommendation'] = hardware_recommendation(profile['specs'], bench)
    return hardware_profile_store(profile)


def graphics_effective_fps(requested, minimized=None, network_busy=None):
    """FPS a loop that asked for `requested` should really run at."""
    if requested <= 0:
        return requested
    state = graphics_state()
    if state['background_saver']:
        minimized = _graphics_window_minimized() if minimized is None else minimized
        if minimized:
            busy = _graphics_network_busy() if network_busy is None else network_busy
            if not busy:
                return 1
    if requested <= 30:
        return requested         # slow loops (waiting screens) keep their own pace
    return state['frame_cap']


class _PolicyClock:
    """Drop-in for pygame.time.Clock that applies graphics_effective_fps()."""

    def __init__(self):
        self._clock = _REAL_PYGAME_CLOCK()

    def tick(self, framerate=0):
        return self._clock.tick(graphics_effective_fps(framerate))

    def tick_busy_loop(self, framerate=0):
        return self._clock.tick_busy_loop(graphics_effective_fps(framerate))

    def __getattr__(self, name):
        return getattr(self._clock, name)


if not hasattr(pygame.time, '_sgf_real_clock'):
    pygame.time._sgf_real_clock = pygame.time.Clock
_REAL_PYGAME_CLOCK = pygame.time._sgf_real_clock
pygame.time.Clock = _PolicyClock


def _graphics_count_network_activity(function):
    @functools.wraps(function)
    def wrapper(*args, **kwargs):
        _GRAPHICS_NETWORK_DEPTH[0] += 1
        try:
            return function(*args, **kwargs)
        finally:
            _GRAPHICS_NETWORK_DEPTH[0] -= 1
    return wrapper


