def _streamer_label(language, key):
    table = _STREAMER_LABELS.get(language) or _STREAMER_LABELS['en']
    return table.get(key) or _STREAMER_LABELS['en'][key]


def _streamer_state_path():
    return os.path.join(_user_data_manager.get_config_dir(), 'streamer_mode.json')


def streamer_mode_enabled():
    """Machine-level setting (not per profile): the streamer is the machine."""
    if not _STREAMER_STATE['loaded']:
        _STREAMER_STATE['loaded'] = True
        try:
            with open(_streamer_state_path(), 'r', encoding='utf-8') as handle:
                stored = json.load(handle)
            _STREAMER_STATE['enabled'] = bool(isinstance(stored, dict) and stored.get('enabled'))
        except (OSError, ValueError):
            _STREAMER_STATE['enabled'] = False
    return _STREAMER_STATE['enabled']


def set_streamer_mode(enabled):
    _STREAMER_STATE['loaded'] = True
    _STREAMER_STATE['enabled'] = bool(enabled)
    try:
        _atomic_write_json(_streamer_state_path(), {'version': 1, 'enabled': bool(enabled)})
    except Exception as exc:
        _logging_mod.getLogger('sgf').warning('Could not save streamer mode: %s', exc)


def streamer_mask(value, kind='generic'):
    """Text to DRAW for a sensitive value. kind='path' keeps only the last
    folder name (never the parent folders, which contain the user name)."""
    if not streamer_mode_enabled():
        return str(value)
    if kind == 'path':
        name = re.split(r'[\\/]', str(value).rstrip('/\\'))[-1]   # either separator, on any OS
        return f'{_STREAMER_MASK}/{name}' if name else _STREAMER_MASK
    return _STREAMER_MASK


def streamer_draw_badge(surface, language):
    """Small always-visible reminder that the mode is on."""
    if not streamer_mode_enabled():
        return
    font = get_font(language, 'bold', 13)
    text = font.render(_streamer_label(language, 'badge'), True, (255, 255, 255))
    box = pygame.Rect(8, 8, text.get_width() + 16, text.get_height() + 8)
    pygame.draw.rect(surface, (150, 40, 60), box, border_radius=8)
    surface.blit(text, (box.x + 8, box.y + 4))


_SCRUB_PATTERNS = (
    (re.compile(r'SGF1-[A-Za-z0-9_\-]+'), 'SGF1-<invite>'),
    (re.compile(r'(?i)\b[a-z0-9-]+\.trycloudflare\.com\b'), '<tunnel-host>'),
    (re.compile(r'(?i)\b([a-z]:\\{1,2}users\\{1,2})[^\\/"\s]+'), r'\1<user>'),
    (re.compile(r'(/(?:home|Users)/)[^/\s"\']+'), r'\1<user>'),
    (re.compile(r'\b(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\b'),
     lambda match: match.group(0) if match.group(0) in ('127.0.0.1', '0.0.0.0') else '<ip>'),
    (re.compile(r'(?<![0-9A-Fa-f:])(?:[0-9A-Fa-f]{1,4}:){7}[0-9A-Fa-f]{1,4}(?![0-9A-Fa-f:])'), '<ip>'),
    (re.compile(r'(?<![0-9A-Fa-f:])(?:[0-9A-Fa-f]{1,4}(?::[0-9A-Fa-f]{1,4}){0,6})?::[0-9A-Fa-f]{1,4}(?::[0-9A-Fa-f]{1,4}){0,6}(?![0-9A-Fa-f:])'), '<ip>'),
)


def scrub_sensitive_text(text):
    """Remove what must not leave this machine in a bug report: IP addresses
    (127.0.0.1 and 0.0.0.0 are kept), tunnel hosts, invite codes, the user name
    inside home folders, and the OS user/host names themselves."""
    text = str(text)
    for pattern, replacement in _SCRUB_PATTERNS:
        text = pattern.sub(replacement, text)
    try:
        import getpass as _getpass_mod
        import socket as _socket_mod
        for name, tag in ((_getpass_mod.getuser(), '<user>'), (_socket_mod.gethostname(), '<host>')):
            if name and len(name) >= 3:
                text = re.sub(r'(?i)(?<![A-Za-z0-9_])' + re.escape(name) + r'(?![A-Za-z0-9_])', tag, text)
    except Exception:
        pass
    return text


_OVERLAY_DRAWERS = []      # callables(surface), drawn over every screen, in order


def register_overlay(drawer):
    if drawer not in _OVERLAY_DRAWERS:
        _OVERLAY_DRAWERS.append(drawer)


def unregister_overlay(drawer):
    if drawer in _OVERLAY_DRAWERS:
        _OVERLAY_DRAWERS.remove(drawer)


_EVENT_FILTERS = []        # (priority, callable(event) -> True when the event was consumed)


def register_event_filter(handler, priority=0):
    """Widgets see input before any screen does, on every screen: pygame.event.get()
    runs each event through the filters, highest priority first. A filter that
    returns True consumes the event; the screen never sees it."""
    unregister_event_filter(handler)
    _EVENT_FILTERS.append((int(priority), handler))
    _EVENT_FILTERS.sort(key=lambda item: item[0], reverse=True)


def unregister_event_filter(handler):
    # `!=`, not `is not`: every access to obj.method builds a new bound-method object.
    _EVENT_FILTERS[:] = [(p, h) for p, h in _EVENT_FILTERS if h != handler]


def _event_consumed(event):
    for _priority, handler in list(_EVENT_FILTERS):
        try:
            if handler(event):
                return True
        except Exception as exc:
            _logging_mod.getLogger('sgf').warning('Event filter removed after an error: %s', type(exc).__name__)
            unregister_event_filter(handler)
    return False


if not hasattr(pygame.event, '_sgf_real_get'):
    pygame.event._sgf_real_get = pygame.event.get
    pygame.event._sgf_real_poll = pygame.event.poll
_REAL_EVENT_GET = pygame.event._sgf_real_get
_REAL_EVENT_POLL = pygame.event._sgf_real_poll


def _filtered_event_get(*args, **kwargs):
    events = _REAL_EVENT_GET(*args, **kwargs)
    if not _EVENT_FILTERS:
        return events
    return [event for event in events if not _event_consumed(event)]


def _filtered_event_poll():
    while True:
        event = _REAL_EVENT_POLL()
        if event.type == pygame.NOEVENT or not _EVENT_FILTERS or not _event_consumed(event):
            return event


pygame.event.get = _filtered_event_get
pygame.event.poll = _filtered_event_poll


def _flip_with_overlays():
    """pygame.display.flip plus the always-on overlays (floating widgets such
    as the tutorial guide, and the streamer badge), so every screen shows them
    without drawing them itself. A failing overlay is removed, never fatal."""
    surface = pygame.display.get_surface()
    if surface is not None:
        for drawer in list(_OVERLAY_DRAWERS):
            try:
                drawer(surface)
            except Exception as exc:
                _logging_mod.getLogger('sgf').warning('Overlay removed after an error: %s', type(exc).__name__)
                unregister_overlay(drawer)
        if streamer_mode_enabled():
            streamer_draw_badge(surface, _LAST_LANGUAGE[0])
    _REAL_DISPLAY_FLIP()


if not hasattr(pygame.display, '_sgf_real_flip'):
    pygame.display._sgf_real_flip = pygame.display.flip
_REAL_DISPLAY_FLIP = pygame.display._sgf_real_flip
pygame.display.flip = _flip_with_overlays


def _bundled_resource_path(name):
    """Path of a file shipped next to the game: beside the script when run from
    source, inside PyInstaller's extraction folder (sys._MEIPASS) in a build."""
    base = getattr(sys, '_MEIPASS', None) if getattr(sys, 'frozen', False) else None
    if not base:
        base = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(base, name)


