def _update_label(language, key, **values):
    table = _UPDATE_LABELS.get(language) or _UPDATE_LABELS['en']
    text = table.get(key) or _UPDATE_LABELS['en'].get(key, key)
    try:
        return text.format(**values) if values else text
    except (KeyError, IndexError, ValueError):
        return text


def _update_version_tuple(text):
    """'v1.2.3' / '1.2' -> (1, 2, 3) / (1, 2, 0); None when not a version."""
    match = re.fullmatch(r'[vV]?(\d+)(?:\.(\d+))?(?:\.(\d+))?(?:\.(\d+))?', str(text or '').strip())
    if not match:
        return None
    parts = [int(part) if part is not None else 0 for part in match.groups()]
    return tuple(parts)


def _update_is_newer(remote, local):
    remote_t, local_t = _update_version_tuple(remote), _update_version_tuple(local)
    return bool(remote_t and local_t and remote_t > local_t)


def _update_state_path():
    return os.path.join(_user_data_manager.get_config_dir(), 'update_state.json')


def _load_update_state():
    state = {'enabled': True, 'mode': 'auto', 'last_check': 0.0, 'skipped_version': '',
             'remind_until': 0.0, 'remind_version': '', 'remind_days': _UPDATE_REMIND_DEFAULT,
             'update_ready': False, 'pending_version': '', 'new_exe_cache_path': '', 'new_exe_sha256': '',
             'core_version': ''}
    try:
        with open(_update_state_path(), 'r', encoding='utf-8') as handle:
            stored = json.load(handle)
        if isinstance(stored, dict):
            mode = stored.get('mode')
            if mode not in _UPDATE_MODES:
                mode = 'auto' if stored.get('enabled', True) else 'off'
            state['mode'] = mode
            state['enabled'] = mode != 'off'
            state['last_check'] = float(stored.get('last_check') or 0.0)
            skipped = stored.get('skipped_version')
            state['skipped_version'] = skipped if isinstance(skipped, str) else ''
            remind_version = stored.get('remind_version')
            state['remind_version'] = remind_version if isinstance(remind_version, str) else ''
            state['remind_until'] = max(0.0, float(stored.get('remind_until') or 0.0))
            days = stored.get('remind_days')
            state['remind_days'] = days if days in _UPDATE_REMIND_CHOICES else _UPDATE_REMIND_DEFAULT
            for text_key in ('pending_version', 'new_exe_cache_path', 'new_exe_sha256', 'core_version'):
                value = stored.get(text_key)
                state[text_key] = value if isinstance(value, str) else ''
            state['update_ready'] = bool(stored.get('update_ready') is True and state['pending_version']
                                         and state['new_exe_cache_path'])
    except (OSError, ValueError, TypeError, OverflowError):
        pass
    return state


def _save_update_state(state):
    try:
        mode = state.get('mode') if state.get('mode') in _UPDATE_MODES else (
            'auto' if state.get('enabled', True) else 'off')
        _atomic_write_json(_update_state_path(), {
            'version': 3, 'mode': mode, 'enabled': mode != 'off',
            'last_check': float(state.get('last_check') or 0.0),
            'skipped_version': str(state.get('skipped_version') or ''),
            'remind_until': float(state.get('remind_until') or 0.0),
            'remind_version': str(state.get('remind_version') or ''),
            'remind_days': (state.get('remind_days') if state.get('remind_days') in _UPDATE_REMIND_CHOICES
                            else _UPDATE_REMIND_DEFAULT),
            # Hand-over to launcher.exe: a verified exe waits in the cache and the launcher swaps it in
            # the next time the game is started. Written by the game, cleared by the launcher.
            'update_ready': bool(state.get('update_ready')),
            'pending_version': str(state.get('pending_version') or ''),
            'new_exe_cache_path': str(state.get('new_exe_cache_path') or ''),
            'new_exe_sha256': str(state.get('new_exe_sha256') or ''),
            'core_version': str(state.get('core_version') or '')})   # written by the game; read by the launcher
        return True
    except Exception as exc:
        _logging_mod.getLogger('sgf').warning('Could not save update state: %s', exc)
        return False


# Shown when an update could not be installed: the player is told plainly to download it by hand.
_UPDATE_MANUAL_LABELS = {
    'en': {'manual': 'The update could not be installed. Download it manually from the download page.',
           'reason_manual': 'this copy of the game cannot update itself; start it with the launcher to get automatic updates'},
    'pt_PT': {'manual': 'Não foi possível instalar a atualização. Tens de a transferir manualmente a partir da página de transferências.',
              'reason_manual': 'esta cópia do jogo não se consegue atualizar sozinha; abre-a com o launcher para ter atualizações automáticas'},
    'pt_BR': {'manual': 'Não foi possível instalar a atualização. Você precisa baixá-la manualmente na página de downloads.',
              'reason_manual': 'esta cópia do jogo não consegue se atualizar sozinha; abra-a com o launcher para ter atualizações automáticas'},
}


def _update_manual_label(language, key):
    table = _UPDATE_MANUAL_LABELS.get(language) or _UPDATE_MANUAL_LABELS['en']
    return table.get(key) or _UPDATE_MANUAL_LABELS['en'].get(key, key)


_UPDATE_REMIND_LABELS = {
    'en': {'remind': 'Remind me later', 'remind_in': 'Remind me in: {span}',
           'day': '1 day', 'days': '{n} days', 'week': '1 week', 'weeks': '{n} weeks', 'month': '1 month', 'months': '{n} months'},
    'pt_PT': {'remind': 'Lembrar mais tarde', 'remind_in': 'Lembrar daqui a: {span}',
              'day': '1 dia', 'days': '{n} dias', 'week': '1 semana', 'weeks': '{n} semanas', 'month': '1 mês', 'months': '{n} meses'},
    'pt_BR': {'remind': 'Lembrar mais tarde', 'remind_in': 'Lembrar em: {span}',
              'day': '1 dia', 'days': '{n} dias', 'week': '1 semana', 'weeks': '{n} semanas', 'month': '1 mês', 'months': '{n} meses'},
}


def _update_remind_label(language, key, **values):
    table = _UPDATE_REMIND_LABELS.get(language) or _UPDATE_REMIND_LABELS['en']
    text = table.get(key) or _UPDATE_REMIND_LABELS['en'].get(key, key)
    try:
        return text.format(**values) if values else text
    except (KeyError, IndexError, ValueError):
        return text


def _update_remind_span_text(language, days):
    """'1 day', '3 days', '1 week', '2 weeks', '1 month', '3 months' for a number of days."""
    if days % 30 == 0:
        months = days // 30
        return _update_remind_label(language, 'month' if months == 1 else 'months', n=months)
    if days % 7 == 0:
        weeks = days // 7
        return _update_remind_label(language, 'week' if weeks == 1 else 'weeks', n=weeks)
    return _update_remind_label(language, 'day' if days == 1 else 'days', n=days)


def _update_prompt_wanted(info, state, now=None):
    """Whether the main menu should put the update screen in front of the player: only for an
    available update that was not skipped and is not being postponed. A postponement is for one
    version; a newer release is offered again at once."""
    if not info or info.get('status') != 'available':
        return False
    now = time.time() if now is None else now
    version = info.get('version')
    if state.get('remind_version') == version and now < float(state.get('remind_until') or 0.0):
        return False
    return bool(info.get('installed') or info.get('staged') or version != state.get('skipped_version'))


def _update_remind_later(version, days=None, now=None):
    """Leave `version` alone for `days` days (the player's chosen span, 1 week by default)."""
    state = _load_update_state()
    days = days if days in _UPDATE_REMIND_CHOICES else state.get('remind_days', _UPDATE_REMIND_DEFAULT)
    now = time.time() if now is None else now
    state.update(remind_version=str(version or ''), remind_until=now + days * 86400.0, remind_days=days)
    _save_update_state(state)
    return state['remind_until']


def _update_cycle_remind_days():
    state = _load_update_state()
    choices = _UPDATE_REMIND_CHOICES
    state['remind_days'] = choices[(choices.index(state['remind_days']) + 1) % len(choices)]
    _save_update_state(state)
    return state['remind_days']


def _update_check_due(state, now=None):
    now = time.time() if now is None else now
    return bool(state.get('enabled', True)) and (
        now - float(state.get('last_check') or 0.0) >= _UPDATE_CHECK_INTERVAL_SECONDS)


def _update_http_get(url, headers, limit):
    """(status, body) for an https GET, reading at most `limit` bytes."""
    import urllib.request as _urlrequest
    import urllib.error as _urlerror
    if not url.startswith('https://'):
        raise ValueError('Only https URLs are allowed')
    request = _urlrequest.Request(url, headers=dict(headers, **{'User-Agent': 'SGF update check'}))
    try:
        with _urlrequest.urlopen(request, timeout=6.0) as response:
            return response.status, response.read(limit + 1)
    except _urlerror.HTTPError as exc:
        return exc.code, b''


def _update_release_candidate(body, frozen):
    release = json.loads(body.decode('utf-8'))
    if not isinstance(release, dict) or release.get('draft') or release.get('prerelease'):
        return None
    tag = str(release.get('tag_name') or '')
    if _update_version_tuple(tag) is None:
        return None
    page = str(release.get('html_url') or '')
    if not page.startswith(f'https://github.com/{GAME_UPDATE_REPO}/'):
        page = f'https://github.com/{GAME_UPDATE_REPO}/releases'
    asset, asset_url, sums_url, asset_digest = '', '', '', ''
    prefix = f'https://github.com/{GAME_UPDATE_REPO}/releases/download/'
    if frozen:
        for item in release.get('assets') or []:
            if not isinstance(item, dict):
                continue
            name = str(item.get('name') or '')
            link = str(item.get('browser_download_url') or '')
            if not link.startswith(prefix):
                continue
            if name.lower() == 'sgf.exe':
                asset, asset_url = name, link          # the game itself, taken over any other exe
                asset_digest = str(item.get('digest') or '')   # GitHub's own "sha256:<hex>" of the upload
            elif name.lower().endswith('.exe') and 'launcher' not in name.lower() and not asset:
                asset, asset_url = name, link
                asset_digest = str(item.get('digest') or '')
            elif name.lower() in ('sha256sums', 'sha256sums.txt', 'sha256sum.txt'):
                sums_url = link
    return {'version': tag.lstrip('vV'), 'source': 'release', 'url': page,
            'notes': str(release.get('body') or '').strip()[:600], 'asset': asset,
            'asset_url': asset_url, 'sums_url': sums_url, 'asset_digest': asset_digest}


def fetch_update_info(local_version=None, fetch=None, frozen=None):
    """Compare this game with the newest release (and, when running from
    source, with GAME_VERSION in the repository). Returns a dict with
    status 'available' | 'up_to_date' | 'error'. `fetch` is injectable."""
    local = local_version or GAME_VERSION
    fetch = fetch or _update_http_get
    frozen = bool(getattr(sys, 'frozen', False)) if frozen is None else frozen
    candidates, attempts, errors = [], 0, 0
    attempts += 1
    try:
        status, body = fetch(
            f'https://api.github.com/repos/{GAME_UPDATE_REPO}/releases/latest',
            {'Accept': 'application/vnd.github+json'}, 400000)
        if status == 200:
            candidate = _update_release_candidate(body, frozen)
            if candidate:
                candidates.append(candidate)
        elif status != 404:      # 404 simply means "no release published yet"
            errors += 1
    except Exception:
        errors += 1
    if not frozen:
        attempts += 1
        found = False
        for name in _UPDATE_SOURCE_FILES:
            try:
                status, body = fetch(
                    f'https://raw.githubusercontent.com/{GAME_UPDATE_REPO}/main/{name}',
                    {'Range': f'bytes=0-{_UPDATE_RANGE_BYTES - 1}'}, _UPDATE_RANGE_BYTES)
            except Exception:
                continue
            if status in (200, 206):
                match = _UPDATE_VERSION_RE.search(body.decode('utf-8', 'replace'))
                if match:
                    candidates.append({
                        'version': match.group(1), 'source': 'source',
                        'url': f'https://github.com/{GAME_UPDATE_REPO}', 'notes': '', 'asset': '',
                        'file': name})
                    found = True
                    break
        if not found:
            errors += 1
    if not candidates:
        return {'status': 'error' if errors >= attempts else 'up_to_date', 'local': local}
    best = max(candidates, key=lambda c: (_update_version_tuple(c['version']), c['source'] == 'release'))
    result = dict(best, local=local)
    result['status'] = 'available' if _update_is_newer(best['version'], local) else 'up_to_date'
    return result


def _update_target_script():
    """Path of the running script when it can be replaced, else None."""
    if getattr(sys, 'frozen', False):
        return None
    try:
        return os.path.abspath(__file__)
    except NameError:
        return None


def _update_launcher_present():
    """True when the game was started by launcher.exe (it sets SGF_LAUNCHER=1). Only the launcher
    can put a downloaded exe in place, because a running exe cannot replace itself on Windows."""
    return os.environ.get('SGF_LAUNCHER') == '1'


def _update_install_blocker(frozen=None, script_path=None, platform=None, launched=None):
    """Why the game must not (or cannot) install an update here (a reason key) or None."""
    frozen = bool(getattr(sys, 'frozen', False)) if frozen is None else frozen
    if frozen:
        if (platform or sys.platform) != 'win32':
            return 'unsupported'
        if not (_update_launcher_present() if launched is None else launched):
            return 'manual'        # started without launcher.exe: nothing would install the download
        return None if os.access(_user_data_manager.get_cache_dir(), os.W_OK) else 'readonly'
    path = script_path or _update_target_script()
    if not path:
        return 'unsupported'
    folder = os.path.dirname(path)
    if '_snake_game_runtime' in path.replace('\\', '/').split('/'):
        return 'launcher'          # a launcher re-extracts its own copy
    if os.path.isdir(os.path.join(folder, '.git')):
        return 'dev'               # never overwrite a development checkout
    if not os.access(folder, os.W_OK):
        return 'readonly'
    return None


def update_install_source(info, script_path, fetch=None):
    """Download the new script, verify it and replace `script_path`.
    Verified: https from the project's repository only, size limit, valid UTF-8
    and Python syntax, and the downloaded file must itself declare a version
    newer than the running one. The old script is kept as <name>.<old version>.bak.
    Returns (ok, reason_key)."""
    fetch = fetch or _update_http_get
    name = info.get('file') or os.path.basename(script_path)
    if name not in _UPDATE_SOURCE_FILES:
        return False, 'download'
    new_path = script_path + '.new'
    try:
        status, body = fetch(
            f'https://raw.githubusercontent.com/{GAME_UPDATE_REPO}/main/{name}', {}, _UPDATE_MAX_SOURCE_BYTES)
        if status != 200 or not body or len(body) > _UPDATE_MAX_SOURCE_BYTES:
            return False, 'download'
        text = body.decode('utf-8')
        match = _UPDATE_VERSION_RE.search(text)
        if not match or not _update_is_newer(match.group(1), info.get('local') or GAME_VERSION):
            return False, 'checksum'
        compile(text, 'SGF_update', 'exec')
        if 'GAME_VERSION' not in text or '__main__' not in text:
            return False, 'checksum'
        with open(new_path, 'wb') as handle:
            handle.write(body)
            handle.flush()
            os.fsync(handle.fileno())
        # The backup goes to SGF Data/backups, not next to the game: the game folder must hold
        # only the game (and anything an older update left there is moved by adopt_loose_update_backups).
        backup = os.path.join(_user_data_manager.get_backup_dir(),
                              f"{os.path.basename(script_path)}.{info.get('local') or GAME_VERSION}.bak")
        _shutil_mod.copy2(script_path, backup)
        os.replace(new_path, script_path)
        return True, ''
    except (SyntaxError, UnicodeDecodeError, ValueError):
        return False, 'checksum'
    except OSError as exc:
        _logging_mod.getLogger('sgf').warning('Update install failed: %s', exc)
        return False, 'readonly'
    except Exception as exc:
        _logging_mod.getLogger('sgf').warning('Update install failed: %s', type(exc).__name__)
        return False, 'download'
    finally:
        try:
            if os.path.exists(new_path):
                os.remove(new_path)
        except OSError:
            pass


# ---------------------------------------------------------------------------
# Backups and restore. Everything lives in SGF Data/backups (never loose files next to the
# game): update backups, data exports, pre-migration copies and replays that no score
# refers to any more. These functions work on files only, so they can be tested without
# the UI. Nothing here deletes data: a restore first keeps a copy of what it replaces.
# ---------------------------------------------------------------------------
_ORPHAN_REPLAY_DIRNAME = 'orphan_replays'
_BACKUP_UPDATE_RE = re.compile(r'^(?P<stem>.+?)\.(?P<version>\d+(?:\.\d+){1,3})\.bak$')   # non-greedy: the version is the LAST dotted number group
_BACKUP_DATA_RE = re.compile(r'^(?P<kind>pre_schema_upgrade|pre_content_split|pre_restore)_.+\.json$')
_RESTORABLE_CATEGORIES = ('replays', 'maps', 'mods', 'themes', 'saves')
_RESTORE_MAX_BYTES = 4 * 1024 ** 3          # refuse an export that would unpack to more than 4 GB


def orphan_replay_dir():
    path = os.path.join(_user_data_manager.get_backup_dir(), _ORPHAN_REPLAY_DIRNAME)
    os.makedirs(path, exist_ok=True)
    return path


def _unique_path(directory, filename):
    """directory/filename, or directory/name_2.ext, name_3.ext... if it is taken."""
    stem, ext = os.path.splitext(filename)
    for double in ('.json.gz', '.json.xz'):
        if filename.endswith(double):
            stem, ext = filename[:-len(double)], double
    candidate, number = os.path.join(directory, filename), 2
    while os.path.exists(candidate):
        candidate = os.path.join(directory, f'{stem}_{number}{ext}')
        number += 1
    return candidate


def quarantine_replay_file(path):
    """Move a replay nobody refers to into backups/orphan_replays instead of deleting it.
    Returns True when it was moved; on any error the file stays where it is."""
    try:
        destination = _unique_path(orphan_replay_dir(), os.path.basename(path))
        _shutil_mod.move(path, destination)
        return True
    except OSError as exc:
        _logging_mod.getLogger('sgf').warning('Could not quarantine replay %s: %s', os.path.basename(path), exc)
        return False


def recover_orphan_replays():
    """Put every replay from backups/orphan_replays back into the replay folder. Returns the count."""
    moved = 0
    source = orphan_replay_dir()
    target = _user_data_manager.get_replay_dir()
    for name in sorted(os.listdir(source)):
        full = os.path.join(source, name)
        if not os.path.isfile(full):
            continue
        try:
            _shutil_mod.move(full, _unique_path(target, name))
            moved += 1
        except OSError as exc:
            _logging_mod.getLogger('sgf').warning('Could not recover replay %s: %s', name, exc)
    return moved


def adopt_loose_update_backups(script_path=None):
    """Move 'SGF.py.<version>.bak' files that an older update left next to the game into
    SGF Data/backups, so the game folder holds nothing but the game. Returns how many moved."""
    script_path = script_path or _update_target_script()
    if not script_path:
        return 0
    folder, base = os.path.split(script_path)
    pattern = re.compile('^' + re.escape(base) + r'\.\d+(?:\.\d+){1,3}\.bak$')
    moved = 0
    try:
        names = os.listdir(folder)
    except OSError:
        return 0
    for name in names:
        if not pattern.match(name):
            continue
        source = os.path.join(folder, name)
        destination = os.path.join(_user_data_manager.get_backup_dir(), name)
        try:
            if not os.path.exists(destination):
                _shutil_mod.copy2(source, destination)
            if os.path.getsize(destination) != os.path.getsize(source):
                continue                       # the copy is not identical: leave the original alone
            os.remove(source)
            moved += 1
        except OSError as exc:
            _logging_mod.getLogger('sgf').warning('Could not move %s into the backups folder: %s', name, exc)
    return moved


# The Backups list is also read once and kept; Recalculate (or an action that changes backups) reads it again.
_BACKUP_LIST_CACHE = {'found': None, 'built_at': None}
_BACKUP_LIST_LOCK = threading.Lock()


def list_backups_cached(force=False):
    """list_backups() from memory. The disk is read the first time and when `force` is set; nothing else refreshes it."""
    with _BACKUP_LIST_LOCK:
        if force or _BACKUP_LIST_CACHE['found'] is None:
            _BACKUP_LIST_CACHE['found'] = list_backups()
            _BACKUP_LIST_CACHE['built_at'] = time.time()
        return _BACKUP_LIST_CACHE['found']


def backups_list_invalidate():
    with _BACKUP_LIST_LOCK:
        _BACKUP_LIST_CACHE['found'] = None


def list_backups():
    """Everything restorable in SGF Data/backups, newest first:
    {'update': [...], 'exports': [...], 'data': [...], 'orphan_replays': {'count', 'bytes'}}."""
    found = {'update': [], 'exports': [], 'data': [], 'orphan_replays': {'count': 0, 'bytes': 0}}
    directory = _user_data_manager.get_backup_dir()
    try:
        names = os.listdir(directory)
    except OSError:
        return found
    for name in names:
        full = os.path.join(directory, name)
        if os.path.isdir(full):
            continue
        try:
            info = {'path': full, 'name': name, 'size': os.path.getsize(full),
                    'mtime': os.path.getmtime(full)}
        except OSError:
            continue
        match = _BACKUP_UPDATE_RE.match(name)
        if match:
            found['update'].append(dict(info, version=match.group('version')))
        elif name.startswith('sgf_export_') and name.endswith('.zip'):
            found['exports'].append(info)
        elif _BACKUP_DATA_RE.match(name):
            found['data'].append(dict(info, kind=_BACKUP_DATA_RE.match(name).group('kind')))
    orphans = os.path.join(directory, _ORPHAN_REPLAY_DIRNAME)
    if os.path.isdir(orphans):
        for name in os.listdir(orphans):
            full = os.path.join(orphans, name)
            if os.path.isfile(full):
                found['orphan_replays']['count'] += 1
                found['orphan_replays']['bytes'] += os.path.getsize(full)
    for key in ('update', 'exports', 'data'):
        found[key].sort(key=lambda item: item['mtime'], reverse=True)
    return found


def update_rollback(backup_path, script_path=None):
    """Remove an update: put an older copy of the game script back. The script being replaced is
    kept as a backup too, so the rollback itself can be undone. Returns (ok, reason) with reason
    one of 'frozen', 'invalid', 'same', 'readonly'. Takes effect the next time the game starts."""
    script_path = script_path or _update_target_script()
    if not script_path:
        return False, 'frozen'
    temp_path = script_path + '.rollback.tmp'
    try:
        with open(backup_path, 'rb') as handle:
            body = handle.read(_UPDATE_MAX_SOURCE_BYTES + 1)
        if not body or len(body) > _UPDATE_MAX_SOURCE_BYTES:
            return False, 'invalid'
        text = body.decode('utf-8')
        match = _UPDATE_VERSION_RE.search(text)
        compile(text, 'SGF_rollback', 'exec')
        if not match or 'GAME_VERSION' not in text or '__main__' not in text:
            return False, 'invalid'
        if match.group(1) == GAME_VERSION:
            return False, 'same'
        keep = os.path.join(_user_data_manager.get_backup_dir(),
                            f'{os.path.basename(script_path)}.{GAME_VERSION}.bak')
        _shutil_mod.copy2(script_path, keep)
        with open(temp_path, 'wb') as handle:
            handle.write(body)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp_path, script_path)
        return True, ''
    except (SyntaxError, UnicodeDecodeError, ValueError):
        return False, 'invalid'
    except OSError as exc:
        _logging_mod.getLogger('sgf').warning('Update rollback failed: %s', exc)
        return False, 'readonly'
    finally:
        try:
            if os.path.exists(temp_path):
                os.remove(temp_path)
        except OSError:
            pass


def export_categories(zip_path):
    """Restorable categories that a data export actually contains, with their file counts."""
    import zipfile
    counts = {}
    try:
        with zipfile.ZipFile(zip_path) as archive:
            for member in archive.namelist():
                top = member.replace('\\', '/').split('/')[0]
                for category in _RESTORABLE_CATEGORIES:
                    if top == _user_data_manager._CATEGORY_DIRNAMES.get(category) and not member.endswith('/'):
                        counts[category] = counts.get(category, 0) + 1
    except (OSError, zipfile.BadZipFile):
        return {}
    return counts


def restore_from_export(zip_path, categories, overwrite=False):
    """Copy the files of the chosen categories back out of a data export. Safe by design: the zip
    is verified first, a safety export of the current data is made before anything changes, only
    the chosen categories are touched, nothing can land outside the data folder, and by default
    only files that are missing are added (existing files stay). Returns a dict with 'restored',
    'skipped', 'safety_backup' and 'error' (None, 'invalid', 'safety_failed' or 'too_big')."""
    import zipfile
    result = {'restored': 0, 'skipped': 0, 'safety_backup': None, 'error': None}
    wanted = {_user_data_manager._CATEGORY_DIRNAMES[c] for c in categories if c in _RESTORABLE_CATEGORIES}
    if not wanted:
        result['error'] = 'invalid'
        return result
    root = os.path.realpath(_user_data_manager.get_root_dir())
    try:
        with zipfile.ZipFile(zip_path) as archive:
            if archive.testzip() is not None:
                result['error'] = 'invalid'
                return result
            members = [item for item in archive.infolist()
                       if not item.is_dir() and item.filename.replace('\\', '/').split('/')[0] in wanted]
            if sum(item.file_size for item in members) > _RESTORE_MAX_BYTES:
                result['error'] = 'too_big'
                return result
            result['safety_backup'] = _user_data_manager.export_data()
            if not result['safety_backup']:
                result['error'] = 'safety_failed'
                return result
            for item in members:
                destination = os.path.realpath(os.path.join(root, *item.filename.replace('\\', '/').split('/')))
                if not destination.startswith(root + os.sep):
                    result['skipped'] += 1               # a path that leaves the data folder is never written
                    continue
                if os.path.exists(destination) and not overwrite:
                    result['skipped'] += 1
                    continue
                os.makedirs(os.path.dirname(destination), exist_ok=True)
                temp_path = destination + f'.restore-{_secrets_mod.token_hex(4)}'
                try:
                    with archive.open(item) as source, open(temp_path, 'wb') as target:
                        _shutil_mod.copyfileobj(source, target)
                    os.replace(temp_path, destination)
                    result['restored'] += 1
                finally:
                    if os.path.exists(temp_path):
                        os.remove(temp_path)
    except (OSError, zipfile.BadZipFile):
        result['error'] = result['error'] or 'invalid'
    return result


def restore_data_file(json_path):
    """Replace the saved game data (scores, achievements, profiles, settings) with a JSON backup.
    The current data is kept first as pre_restore_<time>.json. Returns (ok, reason)."""
    try:
        if os.path.getsize(json_path) > 64 * 1024 * 1024:
            return False, 'invalid'
        with open(json_path, 'r', encoding='utf-8') as handle:
            data = json.load(handle)
        if not isinstance(data, dict):
            return False, 'invalid'
    except (OSError, ValueError):
        return False, 'invalid'
    if not _flush_async_data_writes():
        return False, 'busy'
    stamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    keep = os.path.join(_user_data_manager.get_backup_dir(), f'pre_restore_{stamp}.json')
    try:
        with _data_save_lock:
            if os.path.exists(_DATA_FILE):
                _shutil_mod.copy2(_DATA_FILE, keep)
                if os.path.getsize(keep) != os.path.getsize(_DATA_FILE):
                    raise OSError('the safety copy of the current data is incomplete')   # never overwrite without a full copy
                # (the copy is checked by size, not parsed: the current file may be the damaged one being replaced)
            _atomic_write_json(_DATA_FILE, data)
        _DATA_LOAD_STATE['recovery_pending'] = False
        return True, ''
    except (OSError, ValueError) as exc:
        _logging_mod.getLogger('sgf').warning('Data restore failed: %s', type(exc).__name__)
        return False, 'readonly'


def _update_staged_exe_path():
    """Where a verified release .exe waits for the swap: SGF Data/cache/SGF.exe.new."""
    return os.path.join(_user_data_manager.get_cache_dir(), 'SGF.exe.new')


def _update_exe_backup_path():
    """Where the replaced .exe is kept: SGF Data/backups/SGF.exe.old (one copy, refreshed by each update)."""
    return os.path.join(_user_data_manager.get_backup_dir(), 'SGF.exe.old')


def _update_sha256_of_file(path):
    digest = hashlib.sha256()
    with open(path, 'rb') as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b''):
            digest.update(chunk)
    return digest.hexdigest()


def update_stage_release(info, exe_path, fetch=None):
    """Download the release .exe, verify it against the release's SHA256SUMS file
    and store it as SGF Data/cache/SGF.exe.new, then tell launcher.exe (through update_state.json)
    that it is ready. The game never replaces its own exe; the launcher does it at the next start.
    Without SHA256SUMS, with a wrong hash, without the 'MZ' header or with an
    implausible size nothing is staged. The file is written under a temporary name
    in the cache, read back and hashed again, and only then renamed to its final
    name, so a half-written download can never be mistaken for an update.
    `exe_path` is kept for callers; the staged file no longer lives next to the game.
    Returns (ok, reason_key)."""
    fetch = fetch or _update_http_get
    digest = str(info.get('asset_digest') or '').lower()
    digest = digest[len('sha256:'):] if digest.startswith('sha256:') else ''
    digest = digest if re.fullmatch(r'[0-9a-f]{64}', digest) else ''
    if not info.get('asset_url') or not (info.get('sums_url') or digest):
        return False, 'checksum'
    try:
        # The hash to check against comes from the release's SHA256SUMS file when it has one, and
        # otherwise from the SHA-256 that GitHub itself computed for the uploaded asset. When both
        # exist they must agree.
        expected = ''
        if info.get('sums_url'):
            status, sums = fetch(info['sums_url'], {}, 1024 * 1024)
            if status == 200:
                for line in sums.decode('utf-8', 'replace').splitlines():
                    parts = line.replace('*', ' ').split()
                    if len(parts) >= 2 and parts[-1] == info['asset']:
                        expected = parts[0].lower()
            if not re.fullmatch(r'[0-9a-f]{64}', expected):
                expected = ''
            if expected and digest and expected != digest:
                return False, 'checksum'
        expected = expected or digest
        if not expected:
            return False, 'checksum'
        status, body = fetch(info['asset_url'], {}, _UPDATE_MAX_EXE_BYTES)
    except Exception as exc:
        _logging_mod.getLogger('sgf').warning('Update download failed: %s', type(exc).__name__)
        return False, 'download'
    if status != 200 or not body or len(body) > _UPDATE_MAX_EXE_BYTES:
        return False, 'download'
    if hashlib.sha256(body).hexdigest() != expected:
        return False, 'checksum'
    if not body.startswith(b'MZ') or len(body) < 100_000:     # not a Windows executable
        return False, 'checksum'
    new_path = _update_staged_exe_path()
    temp_path = new_path + f'.part-{_secrets_mod.token_hex(4)}'
    try:
        with open(temp_path, 'wb') as handle:
            handle.write(body)
            handle.flush()
            os.fsync(handle.fileno())
        if os.path.getsize(temp_path) != len(body) or _update_sha256_of_file(temp_path) != expected:
            return False, 'checksum'     # what reached the disk is not what was verified
        os.replace(temp_path, new_path)
        if not _update_mark_ready(info.get('version'), expected):
            return False, 'readonly'
        return True, ''
    except OSError as exc:
        _logging_mod.getLogger('sgf').warning('Could not store the update: %s', type(exc).__name__)
        return False, 'readonly'
    finally:
        try:
            if os.path.exists(temp_path):
                os.remove(temp_path)     # only this call's incomplete temporary file
        except OSError:
            pass


def _update_mark_ready(version, sha256):
    """Tell launcher.exe that SGF Data/cache/SGF.exe.new is verified and waiting."""
    state = _load_update_state()
    relative = os.path.relpath(_update_staged_exe_path(), _user_data_manager.get_root_dir()).replace(os.sep, '/')
    state.update(update_ready=True, pending_version=str(version or ''), new_exe_cache_path=relative,
                 new_exe_sha256=str(sha256 or ''))
    return _save_update_state(state)


def _update_clear_ready():
    state = _load_update_state()
    state.update(update_ready=False, pending_version='', new_exe_cache_path='', new_exe_sha256='')
    return _save_update_state(state)


def _update_record_core_version():
    """Let the launcher know which version this exe is (it compares it with GitHub's latest)."""
    state = _load_update_state()
    if state.get('core_version') != GAME_VERSION:
        state['core_version'] = GAME_VERSION
        _save_update_state(state)


def _update_state_reconcile():
    """If the pending update was already installed (the game now runs that version or a newer one),
    drop the signal and any file left in the cache. A newer pending version stays untouched."""
    state = _load_update_state()
    if not state['update_ready'] or _update_is_newer(state['pending_version'], GAME_VERSION):
        return
    _update_clear_ready()
    try:
        if os.path.isfile(_update_staged_exe_path()):
            os.remove(_update_staged_exe_path())
    except OSError:
        pass


def update_restart():
    """Called after the UI has closed pygame when the player chose to restart for an update.
    Source install: start the script again. Frozen build: only leave with exit code 0; the
    update was downloaded and verified into SGF Data/cache and signalled in update_state.json,
    and launcher.exe swaps it in the next time the game is started (no helper script, no waiting
    for file locks)."""
    if getattr(sys, 'frozen', False):
        sys.exit(0)
    subprocess.Popen([sys.executable] + sys.argv)
    return True


def _update_cleanup_after_swap():
    """At startup of a frozen build: tidy what the update mechanism may have left.
    The backup SGF Data/backups/SGF.exe.old is deliberately kept (it is the way back).
    Removed or moved here: a previous exe an older version left next to the game
    (<exe>.old, moved into the backups folder), a staged file and a preparation file
    next to the game (<exe>.new, <exe>.update-tmp), and incomplete downloads in the cache."""
    if not getattr(sys, 'frozen', False):
        return
    _update_state_reconcile()
    _update_record_core_version()
    exe = sys.executable
    try:
        loose = exe + '.old'
        if os.path.isfile(loose):
            central = _update_exe_backup_path()
            target = central if not os.path.exists(central) else central + '.legacy'
            if not os.path.exists(target):
                _shutil_mod.copy2(loose, target)
                if os.path.getsize(target) == os.path.getsize(loose):
                    os.remove(loose)
    except OSError:
        pass       # still in use or read-only: try again at the next start
    for leftover in (exe + '.new', exe + '.update-tmp'):
        try:
            if os.path.isfile(leftover):
                os.remove(leftover)
        except OSError:
            pass
    try:
        cache = _user_data_manager.get_cache_dir()
        for name in os.listdir(cache):
            if name.startswith('SGF.exe.new.part-'):
                os.remove(os.path.join(cache, name))
    except OSError:
        pass


class UpdateChecker:
    """Runs fetch_update_info (and, in 'auto' mode, the install) on a worker
    thread; the UI only reads `result`."""

    def __init__(self, fetch=None):
        self.fetch = fetch
        self.result = None
        self.checking = False
        self.prompted = False
        self.installing = False
        self.restart_requested = False

    def install(self, info=None):
        """Install the update described by `info`; fills result['installed'],
        result['staged'] or result['install_error'] (a reason key)."""
        info = info or self.result
        if not info or info.get('status') != 'available':
            return False
        if getattr(sys, 'frozen', False) and info.get('version') == _load_update_state().get('skipped_version'):
            return False          # skipped by the player, or rolled back by the launcher after a failed start
        blocker = _update_install_blocker()
        if blocker:
            info['install_error'] = blocker
            return False
        self.installing = True
        try:
            if getattr(sys, 'frozen', False):
                ok, reason = update_stage_release(info, sys.executable, self.fetch)
                key = 'staged'
            else:
                ok, reason = update_install_source(info, _update_target_script(), self.fetch)
                key = 'installed'
            if ok:
                info[key] = True
                info.pop('install_error', None)
            else:
                info['install_error'] = reason
            return ok
        finally:
            self.installing = False

    def start(self, force=False):
        if os.environ.get('SGF_NO_UPDATE_CHECK') == '1' or self.checking:
            return False
        state = _load_update_state()
        if not force and not _update_check_due(state):
            return False
        self.checking, self.result = True, None

        def work():
            info = {'status': 'error', 'local': GAME_VERSION}
            try:
                info = fetch_update_info(fetch=self.fetch)
            except Exception as exc:
                _logging_mod.getLogger('sgf').warning('Update check failed: %s', type(exc).__name__)
            if info.get('status') != 'error':
                latest = _load_update_state()
                latest['last_check'] = time.time()
                _save_update_state(latest)
            if info.get('status') == 'available' and _load_update_state().get('mode') == 'auto':
                try:
                    self.install(info)
                except Exception as exc:
                    info['install_error'] = 'download'
                    _logging_mod.getLogger('sgf').warning('Auto update failed: %s', type(exc).__name__)
            self.result = info
            self.checking = False

        threading.Thread(target=work, name='update-check', daemon=True).start()
        return True


class UpdateAvailableScreen(_SimpleMenuScreen):
    """Shows the update state (checking / up to date / installed / available /
    offline) and the actions that make sense for it."""

    def __init__(self, settings, screen, checker):
        self.checker = checker
        self.postponed = False       # the player chose "remind me later" or "skip this version"
        lang = lambda: settings.language
        entries = [
            ('update_primary', self._primary_label, COLORS['green'], self._primary),
            ('update_open', lambda: _update_label(lang(), 'open'), COLORS['blue'], self._open_page),
            ('update_remind', lambda: _update_remind_label(lang(), 'remind'), COLORS['blue'], self._remind),
            ('update_remind_in', lambda: _update_remind_label(
                lang(), 'remind_in', span=_update_remind_span_text(lang(), _load_update_state()['remind_days'])),
             COLORS['button'], self._cycle_remind_days),
            ('update_skip', lambda: _update_label(lang(), 'skip'), COLORS['button'], self._skip),
            ('update_mode', self._mode_label, COLORS['button'], self._cycle_mode),
        ]
        super().__init__(settings, screen,
                         title_fn=lambda: _update_label(lang(), 'title'),
                         entries=entries, body_fn=self._body)

    def _info(self):
        return self.checker.result

    def _done(self, info):
        return bool(info and (info.get('installed') or info.get('staged')))

    def _body(self):
        lang = self.settings.language
        mode = _load_update_state().get('mode', 'auto')
        info = self._info()
        if mode == 'off' and info is None:
            return _update_label(lang, 'disabled')
        if self.checker.checking or self.checker.installing or info is None:
            return _update_label(lang, 'checking')
        if info['status'] == 'error':
            return _update_label(lang, 'error')
        if info['status'] == 'up_to_date':
            return _update_label(lang, 'up_to_date', local=info['local'])
        if info.get('installed'):
            return _update_label(lang, 'installed', version=info['version'])
        if info.get('staged'):
            return _update_label(lang, 'staged', version=info['version'])
        text = _update_label(lang, 'available', version=info['version'], local=info['local'])
        if info.get('install_error'):
            # Say it plainly: the update was not installed and has to be downloaded by hand.
            error = str(info['install_error'])
            reason = (_update_manual_label(lang, 'reason_manual') if error == 'manual'
                      else _update_label(lang, 'reason_' + error))
            text += '\n\n' + _update_manual_label(lang, 'manual') + '\n(' + reason + ')'
        if info.get('notes'):
            text += '\n\n' + _update_label(lang, 'notes') + '\n' + info['notes'][:300]
        return text

    def _primary_label(self):
        lang = self.settings.language
        info = self._info()
        if self._done(info):
            return _update_label(lang, 'restart')
        if info and info.get('status') == 'available' and not info.get('install_error'):
            return _update_label(lang, 'install')
        return _update_label(lang, 'open')

    def _primary(self):
        info = self._info()
        if self._done(info):
            self.checker.restart_requested = True
            self._running = False
        elif (info and info.get('status') == 'available' and not info.get('install_error')
                and not self.checker.installing):
            # Download and verify off the UI thread; the body shows progress.
            threading.Thread(target=self.checker.install, args=(info,),
                             name='update-install', daemon=True).start()
        else:
            self._open_page()

    def _mode_label(self):
        return _update_label(self.settings.language, 'mode_' + _load_update_state().get('mode', 'auto'))

    def _open_page(self):
        info = self._info()
        if info and info.get('status') == 'available' and str(info.get('url', '')).startswith('https://github.com/'):
            try:
                webbrowser.open(info['url'])
            except Exception as exc:
                _logging_mod.getLogger('sgf').warning('Could not open the download page: %s', exc)

    def _remind(self):
        info = self._info()
        if info and info.get('status') == 'available':
            _update_remind_later(info['version'])
            self.postponed = True
            self._running = False

    def _cycle_remind_days(self):
        _update_cycle_remind_days()

    def _skip(self):
        info = self._info()
        if info and info.get('status') == 'available':
            state = _load_update_state()
            state['skipped_version'] = info['version']
            _save_update_state(state)
            self.postponed = True
            self._running = False

    def _cycle_mode(self):
        state = _load_update_state()
        current = state.get('mode', 'auto')
        state['mode'] = _UPDATE_MODES[(_UPDATE_MODES.index(current) + 1) % len(_UPDATE_MODES)]
        _save_update_state(state)


