def _tour_label(language, key, **values):
    table = _TOUR_LABELS.get(language) or _TOUR_LABELS['en']
    text = table.get(key) or _TOUR_LABELS['en'][key]
    return text.format(**values) if values else text


def _tour_text(language, step, detailed):
    table = _TOUR_TEXT.get(language) or _TOUR_TEXT['en']
    quick, extra = table[step]
    return f'{quick} {extra}' if detailed else quick


class SlinkyTour:
    """Pure state of the tour (no drawing): which step, forward/back, finish."""

    def __init__(self, detailed=False, steps=_TOUR_STEPS, modes=None):
        self.steps = tuple(steps)
        self.detailed = bool(detailed)
        self.modes = dict(_TOUR_INTERACTION if modes is None else modes)
        self.index = 0
        self.finished = False

    @property
    def interaction(self):
        """block_all / allow_target / allow_all for the current step (default: block_all)."""
        mode = self.modes.get(self.step, 'block_all')
        return mode if mode in _TOUR_MODES else 'block_all'

    @property
    def step(self):
        return self.steps[self.index]

    @property
    def is_last(self):
        return self.index >= len(self.steps) - 1

    def next(self):
        if self.is_last:
            self.finished = True
        else:
            self.index += 1

    def back(self):
        self.index = max(0, self.index - 1)


