def _dev_draw_loading_hook(name, duration_ms):
    try:
        if DEV_TOOLS.active:
            DEV_TOOLS.telemetry.record_loading(name, duration_ms)
    except Exception:
        pass


def _dev_game_frame_hook(game, frame_dt, *, update_ms=0.0, render_ms=0.0,
                         input_ms=0.0, gc_ms=0.0, ai_ms=0.0,
                         replay_ms=0.0, ui_ms=0.0):
    loaded_assets = active_entities = particles = None
    if DEV_TOOLS.active:
        try:
            loaded_assets = len(getattr(ASSET_MANAGER, '_cache', {}))
        except Exception:
            pass
        active_entities = 0
        for attr in ('snake', 'p1_snake', 'ai_snakes', 'obstacles', 'moving_obstacles', 'active_powerups'):
            val = getattr(game, attr, None)
            if isinstance(val, int):
                active_entities += val
            elif isinstance(val, (list, tuple, dict, set)):
                active_entities += len(val)
        particles = len(getattr(game, 'particles', [])) if hasattr(game, 'particles') else 0
    DEV_TOOLS.telemetry.record_frame(
        frame_dt * 1000.0 if frame_dt < 10.0 else frame_dt,
        update_ms=update_ms, render_ms=render_ms, input_ms=input_ms,
        gc_ms=gc_ms, ai_ms=ai_ms, replay_ms=replay_ms, ui_ms=ui_ms,
        loaded_assets=loaded_assets, active_entities=active_entities, particles=particles,
    )


def _dev_annotate_snapshot(snapshot):
    if isinstance(snapshot, dict):
        snapshot = copy.deepcopy(snapshot)
        snapshot['dev_modified'] = DEV_TOOLS.modified
    return snapshot


def _dev_patch_replay_history(history):
    if not isinstance(history, list):
        return history
    return [_dev_annotate_snapshot(x) for x in history]


# ---- AI decision capture ---------------------------------------------------
# Wrapped after the class definition so no AI algorithm is duplicated or
# changed when Dev Mode is locked.
if not getattr(SnakeAI, '_dev_wrapped', False):
    _original_snake_ai_choose_direction = SnakeAI.choose_direction
    def _dev_choose_direction(self, *args, **kwargs):
        dev = globals().get('DEV_TOOLS')
        if dev is None or not dev.active:
            return _original_snake_ai_choose_direction(self, *args, **kwargs)
        started = time.perf_counter()
        result = _original_snake_ai_choose_direction(self, *args, **kwargs)
        try:
            snake = args[0] if args else kwargs.get('snake', [])
            occupied = args[1] if len(args) > 1 else kwargs.get('occupied', [])
            fruit = args[2] if len(args) > 2 else kwargs.get('fruit')
            bw = args[3] if len(args) > 3 else kwargs.get('board_w', 0)
            bh = args[4] if len(args) > 4 else kwargs.get('board_h', 0)
            wall = kwargs.get('wall_collision', True)
            blocked = set(map(tuple, occupied))
            if len(snake) > 1: blocked.update(map(tuple, snake[1:]))
            candidates = []
            for d in SnakeAI.DIRS:
                nxt = self._step(tuple(snake[0]), d, (bw, bh, wall)) if snake else None
                safe = nxt is not None and nxt not in blocked
                score = -1.0
                if safe:
                    score = -float(abs(nxt[0]-fruit[0]) + abs(nxt[1]-fruit[1])) if fruit else 0.0
                candidates.append((d, nxt, score))
            target = None
            try:
                target = self._best_target(tuple(snake[0]), fruit, kwargs.get('powerup_pos'), (bw, bh, wall), margin=2)
            except Exception:
                target = fruit
            path = []
            if target is not None and snake:
                try:
                    path = self._bfs(tuple(snake[0]), tuple(target), blocked, (bw, bh, wall), {}, shuffle=False) or []
                except Exception:
                    path = []
            self.debug_info = {
                'chosen': result, 'target': target, 'path': path,
                'candidates': candidates, 'head': tuple(snake[0]) if snake else None,
                'duration_ms': (time.perf_counter() - started) * 1000.0,
                'difficulty': getattr(self, 'difficulty', 'N/A'),
            }
            dev.ai_debug_history.append(copy.deepcopy(self.debug_info))
        except Exception:
            pass
        return result
    SnakeAI.choose_direction = _dev_choose_direction
    SnakeAI._dev_wrapped = True


class DevPanelScreen:
    """Tabbed developer panel.  Uses the existing SGF font/theme helpers and
    simple hit regions; it intentionally does not introduce another widget
    framework just for developer tooling."""
    def __init__(self, tools, screen, game=None):
        self.tools = tools
        self.screen = screen
        self.game = game
        self._display_surface = screen
        try:
            self._workspace_enabled = screen is pygame.display.get_surface()
        except Exception:
            self._workspace_enabled = False
        self._workspace_canvas = pygame.Surface(screen.get_size())
        self._workspace_layout = _normalize_dev_workspace_layout(
            getattr(getattr(tools, 'state', None), 'workspace_layout', None))
        self._workspace_rect = _dev_workspace_rect(
            self._workspace_layout, screen.get_size())
        self._workspace_restore_rect = self._workspace_rect.copy()
        self._workspace_minimized = False
        self._workspace_hidden = False
        self._workspace_maximized = False
        self._workspace_drag_offset = None
        self._workspace_resize_origin = None
        self._workspace_content_rect = pygame.Rect(0, 0, 0, 0)
        self._workspace_scale = 1.0
        self._mapped_mouse_pos = (-1, -1)
        self._workspace_shade = None
        self._workspace_background = None   # frame behind the widget (the game/menu stays visible)
        self._overlay_mode = False          # True: drawn over the live screen, no backdrop, no dimming
        self._workspace_restore_chip = pygame.Rect(0, 0, 0, 0)
        self.tab = 0
        self.scroll = 0
        self.graph_metric = None
        self.running = True
        self.confirm = None
        self.toast_until = 0.0
        self.toast_text = ''
        self._last_size = screen.get_size()
        self._performance_snapshot_cache = None

    @property
    def lang(self):
        return getattr(getattr(self.game, 'settings', None), 'language', 'en')

    def _t(self, text):
        # Developer-only copy intentionally falls back to English because the
        # panel is not part of the normal player-facing translation surface.
        return str(text)

    def _font(self, size=16, bold=False):
        return get_font(self.lang, 'bold' if bold else 'regular', size)

    def _button(self, rect, label, *, active=False, danger=False):
        bg = (95, 105, 145) if active else ((150, 55, 55) if danger else COLORS['button'])
        hover = rect.collidepoint(self._mapped_mouse_pos)
        if hover:
            bg = (120, 135, 190) if not danger else (190, 70, 70)
        pygame.draw.rect(self.screen, bg, rect, border_radius=6)
        pygame.draw.rect(self.screen, (120, 130, 165), rect, 1, border_radius=6)
        s = render_fit(self._font(max(11, min(17, rect.height // 2)), True), str(label), COLORS['white'], rect.w - 6, padding=4)
        self.screen.blit(s, s.get_rect(center=rect.center))
        return hover

    def _toggle_row(self, y, label, key, *, description=None):
        h = 34
        rect = pygame.Rect(30, y, self.screen.get_width() - 60, h)
        active = bool(self.tools.cheats.get(key, self.tools.toggles.get(key, False)))
        self._button(rect, f"{'ON ' if active else 'OFF'}  {label}", active=active)
        if description:
            small = self._font(11)
            ss = small.render(description, True, (165, 175, 195))
            self.screen.blit(ss, (42, rect.bottom + 1))
        return rect

    def _action_row(self, y, label, key):
        rect = pygame.Rect(30, y, self.screen.get_width() - 60, 34)
        self._button(rect, label)
        return rect

    def _tabs(self):
        sw = self.screen.get_width(); n = len(DEV_CATEGORIES)
        visible = max(4, min(7, sw // 150))
        self._visible_tab_start = max(0, min(self.tab, max(0, n - visible)))
        self._visible_tab_end = min(n, self._visible_tab_start + visible)
        count = max(1, self._visible_tab_end - self._visible_tab_start)
        w = max(90, (sw - 40) // count)
        y = 54
        for i in range(self._visible_tab_start, self._visible_tab_end):
            x = 20 + (i - self._visible_tab_start) * w
            self._button(pygame.Rect(x, y, w - 5, 32), DEV_CATEGORIES[i], active=(i == self.tab))
        return y + 40

    def _draw_header(self):
        self.screen.fill((10, 13, 24))
        title = self._font(26, True).render('DEV MODE', True, (255, 95, 95))
        self.screen.blit(title, (20, 16))
        status = 'MODIFIED' if self.tools.modified else 'SAFE'
        col = (255, 100, 100) if self.tools.modified else (130, 220, 150)
        st = self._font(13, True).render(status, True, col)
        self.screen.blit(st, (self.screen.get_width() - st.get_width() - 20, 20))

    def _draw_metric(self, y, label, metric, unit='', allow_graph=True, summary=None):
        # Callers that render a metrics page should share one snapshot; building
        # it repeatedly sorts the rolling 60-second sample history each time.
        snap = summary if summary is not None else self.tools.telemetry.snapshot().get(metric, {})
        cur = snap.get('current')
        avg = snap.get('average')
        if cur is None:
            value = 'N/A'
        elif unit == 'ms':
            value = f'{cur:.2f} ms'
        elif unit == 'fps':
            value = f'{cur:.1f}'
        elif unit == 'mb':
            value = f'{cur:.1f} MB'
        elif unit == '%':
            value = f'{cur:.2f}%'
        elif unit == 'mbps':
            value = f'{cur:.2f} MB/s'
        else:
            value = f'{cur:.2f}' if isinstance(cur, float) else str(cur)
        rect = pygame.Rect(30, y, self.screen.get_width() - 60, 30)
        pygame.draw.rect(self.screen, (20, 26, 40), rect, border_radius=5)
        pygame.draw.rect(self.screen, (55, 65, 85), rect, 1, border_radius=5)
        self.screen.blit(self._font(14, True).render(label, True, COLORS['white']), (42, y + 6))
        vs = self._font(14).render(value, True, COLORS['light_gray'])
        self.screen.blit(vs, (rect.right - vs.get_width() - 50, y + 6))
        if allow_graph:
            gr = pygame.Rect(rect.right - 36, y + 5, 26, 20)
            self._button(gr, 'G')
        if avg is not None and cur is not None:
            avg_txt = self._font(10).render(f'avg {avg:.2f}', True, (130, 140, 165))
            self.screen.blit(avg_txt, (rect.x + 120, y + 8))
        return rect

    def _performance_snapshot(self):
        now = time.monotonic()
        cached = self._performance_snapshot_cache
        if cached is None or now - cached[0] >= 0.5:
            cached = (now, self.tools.telemetry.snapshot())
            self._performance_snapshot_cache = cached
        return cached[1]

    def _performance_tracing_rect(self, top):
        return pygame.Rect(30, top + self.scroll, self.screen.get_width() - 60, 34)

    def _draw_performance(self, top):
        telemetry = self.tools.telemetry
        rect = self._performance_tracing_rect(top)
        self._button(rect, f"{'ON ' if telemetry.deep_tracing else 'OFF'}  Allocation tracing (slows the game)",
                     active=telemetry.deep_tracing)
        note = 'Needed only for the allocation rate and traced memory; off by default and paused while minimized.'
        self.screen.blit(self._font(11).render(note, True, (165, 175, 195)), (42, rect.bottom + 1))
        y = top + self.scroll + 52
        snap = self._performance_snapshot()
        metrics = [
            ('FPS', 'fps', 'fps'), ('Frame time', 'frame_ms', 'ms'),
            ('1% low FPS', 'fps', 'fps'), ('0.1% low FPS', 'fps', 'fps'),
            ('CPU', 'cpu_percent', '%'), ('Memory', 'memory_mb', 'mb'),
            ('Allocation rate', 'allocation_mb_s', 'mbps'),
            ('Update time', 'update_ms', 'ms'), ('Render time', 'render_ms', 'ms'),
            ('Input time', 'input_ms', 'ms'), ('Other time', 'other_ms', 'ms'),
            ('GC time', 'gc_ms', 'ms'), ('AI time', 'ai_ms', 'ms'),
            ('Replay time', 'replay_ms', 'ms'), ('UI time', 'ui_ms', 'ms'),
        ]
        for label, metric, unit in metrics:
            if label == '1% low FPS':
                summary = snap.get('fps', {}); val = summary.get('low_1')
                self._draw_metric_value(y, label, val, unit); y += 34; continue
            if label == '0.1% low FPS':
                summary = snap.get('fps', {}); val = summary.get('low_0_1')
                self._draw_metric_value(y, label, val, unit); y += 34; continue
            self._draw_metric(y, label, metric, unit, summary=snap.get(metric, {})); y += 34
        extras = [
            f"Frame spikes {snap.get('frame_spikes', 0)}",
            f"Performance incidents {snap.get('incident_count', 0)}",
            f"Max frame time {snap.get('max_frame_ms', 0.0):.2f} ms",
            f"Loaded assets {snap.get('loaded_assets', 0)}",
            f"Active entities {snap.get('active_entities', 0)}",
            f"Particles {snap.get('particles', 0)}",
        ]
        for txt in extras:
            self.screen.blit(self._font(14).render(txt, True, (185, 195, 210)), (36, y)); y += 22
        spikes = list(self.tools.telemetry.spikes)[-6:]
        if spikes:
            self.screen.blit(self._font(13, True).render('FRAME SPIKES', True, (245, 190, 110)), (36, y + 4)); y += 24
            for spike in reversed(spikes):
                line = f"{spike['frame_ms']:.2f} ms   Tick {spike['tick']}   game {spike['update_ms']:.2f} ms   render {spike['render_ms']:.2f} ms"
                self.screen.blit(self._font(11).render(line, True, (195, 200, 215)), (40, y)); y += 18

    def _draw_metric_value(self, y, label, val, unit):
        rect = pygame.Rect(30, y, self.screen.get_width() - 60, 30)
        pygame.draw.rect(self.screen, (20, 26, 40), rect, border_radius=5)
        self.screen.blit(self._font(14, True).render(label, True, COLORS['white']), (42, y + 6))
        txt = 'N/A' if val is None else (f'{val:.1f}' if unit == 'fps' else f'{val:.2f} ms')
        s = self._font(14).render(txt, True, COLORS['light_gray'])
        self.screen.blit(s, (rect.right - s.get_width() - 50, y + 6))
        gr = pygame.Rect(rect.right - 36, y + 5, 26, 20)
        self._button(gr, 'G')

    def _draw_graphs(self, top):
        y = top + 10
        metrics = [('FPS', 'fps'), ('Frame time', 'frame_ms'), ('CPU', 'cpu_percent'), ('Memory', 'memory_mb'), ('Update time', 'update_ms'), ('Render time', 'render_ms')]
        for label, metric in metrics:
            rect = pygame.Rect(30, y, self.screen.get_width() - 60, 48)
            self._button(rect, f'VIEW 60s GRAPH  —  {label}')
            if rect.collidepoint(self._mapped_mouse_pos) and pygame.mouse.get_pressed()[0]:
                self.graph_metric = metric
            y += 56
        self.screen.blit(self._font(12).render('Click a metric to open its 60-second graph.', True, (150, 160, 180)), (34, y + 5))

    def _draw_game(self, top):
        y = top + self.scroll
        data = self.tools.debug_game_state()
        lines = [
            f"Seed {data.get('seed', 'N/A')}", f"State {data.get('state', 'N/A')}",
            f"Board {data.get('board', 'N/A')}", f"Snake length {data.get('snake_length', 'N/A')}",
            f"Score {data.get('score', 'N/A')}", f"Difficulty {data.get('difficulty', 'N/A')}",
            f"Replay frames {data.get('replay_frames', 0)}",
            f"Replay recording {data.get('replay_recording', False)}",
            f"Deterministic {'YES' if self._determinism_ok() else 'N/A'}",
            f"DEV modified {'YES' if self.tools.modified else 'NO'}",
        ]
        for line in lines:
            self.screen.blit(self._font(16).render(line, True, (210, 220, 235)), (36, y)); y += 28
        for key, label, rect in self._game_toggle_layout(top):
            active = bool(self.tools.toggles.get(key, False))
            self._button(rect, f"{'ON ' if active else 'OFF'}  {label}", active=active)

    def _game_toggle_layout(self, top):
        labels = (
            ('show_hitboxes', 'Show hitboxes'),
            ('show_collision_grid', 'Show collision grid'),
            ('show_entity_ids', 'Show entity IDs'),
            ('show_coordinates', 'Show coordinates'),
            ('show_mouse_position', 'Show mouse position'),
        )
        y = top + self.scroll + 10 * 28 + 10
        return [(key, label, pygame.Rect(30, y + index * 42,
                                          self.screen.get_width() - 60, 34))
                for index, (key, label) in enumerate(labels)]

    def _determinism_ok(self):
        return bool(self.game and hasattr(self.game, 'deterministic_state_signature'))

    def _draw_replay(self, top):
        y = top + 10 + self.scroll
        g = self.tools.current_game
        frames = len(getattr(g, 'game_history', [])) if g else 0
        duration = (frames * float(getattr(getattr(g, 'settings', None), 'update_rate_ms', 100)) / 1000.0) if g else 0.0
        lines = [
            f'Recording: {"ON" if g and not getattr(g, "replay_mode", False) else "OFF"}',
            f'Size: {frames} snapshots   Duration: {duration:.1f}s', f'Events: {frames}   Max: unlimited',
            f'Determinism: {self.tools.determinism_status if self.tools.determinism_status != "NOT VERIFIED" else ("SIGNATURE AVAILABLE" if self._determinism_ok() else "N/A")}',
            f'DEV modified: {"YES" if self.tools.replay_dev_modified or self.tools.modified else "NO"}',
        ]
        for line in lines:
            self.screen.blit(self._font(16).render(line, True, (210,220,235)), (36,y)); y += 26
        for label, key, rect in self._replay_action_layout(top):
            self._button(rect, label)

    def _replay_action_layout(self, top):
        y = top + 10 + self.scroll + 5 * 26
        actions = [('START', 'start_replay'), ('STOP', 'stop_replay'),
                   ('SAVE', 'save_replay'), ('LOAD', 'load_replay'),
                   ('VERIFY', 'verify_replay')]
        result = []
        for label, key in actions:
            result.append((label, key, pygame.Rect(
                30, y, self.screen.get_width() - 60, 34)))
            y += 42
        return result

    def _draw_memory(self, top):
        y = top + 10
        stats = self.tools.memory_stats()
        for label, key in (
            ('Process memory','process_memory_mb'), ('Allocation rate','allocation_mb_s'),
            ('Peak memory','peak_memory_mb'), ('Python objects','python_objects'),
            ('Textures','textures'), ('Surfaces','surfaces'), ('Sounds','sounds'),
            ('Fonts','fonts'), ('Loaded assets','loaded_assets'), ('Unused assets','unused_assets'),
        ):
            v = stats.get(key)
            if key.endswith('_mb'):
                val = 'N/A' if v is None else f'{v:.2f} MB'
            elif key == 'allocation_mb_s':
                val = 'N/A' if v is None else f'{v:.2f} MB/s'
            else:
                val = 'N/A' if v is None else str(v)
            self.screen.blit(self._font(14).render(f'{label}: {val}', True, (205,215,230)), (36,y)); y += 24

    def _draw_storage(self, top):
        y = top + 10 + self.scroll
        total = 0
        stats, actions = self._storage_action_layout(top)
        for cat, size in stats:
            mb = (size / 1024.0 / 1024.0) if size is not None else None
            total += size or 0
            self.screen.blit(self._font(14).render(f'{cat:10} {"N/A" if mb is None else f"{mb:.2f} MB"}', True, (205,215,230)), (36,y))
            y += 24
        self.screen.blit(self._font(17, True).render(f'TOTAL {total/1024.0/1024.0:.2f} MB', True, COLORS['white']), (36,y+6)); y += 38
        for label, _key, rect in actions:
            self._button(rect, label)

    def _storage_action_layout(self, top):
        stats = self.tools.storage_stats()
        y = top + 10 + self.scroll + len(stats) * 24 + 38
        actions = [('OPEN DATA FOLDER', 'open_folder', pygame.Rect(
            30, y, self.screen.get_width() - 60, 34))]
        y += 44
        for cat in ('replays', 'logs', 'cache', 'saves'):
            actions.append((f'CLEAR {cat.upper()}', f'clear_{cat}', pygame.Rect(
                30, y, self.screen.get_width() - 60, 34)))
            y += 42
        return stats, actions

    def _draw_rendering(self, top):
        y = top + 10
        stats, toggles = self._rendering_toggle_layout(top)
        for label, val in stats.items():
            self.screen.blit(self._font(14).render(f'{label}: {val}', True, (205,215,230)), (36,y)); y += 24
        for key, label, rect in toggles:
            active = bool(self.tools.toggles.get(key, False))
            self._button(rect, f"{'ON ' if active else 'OFF'}  {label}", active=active)

    def _rendering_toggle_layout(self, top):
        stats = self.tools.rendering_stats(self.screen)
