    def _draw_ai_debug(self, top):
        y = top + 8 + self.scroll
        self._action_row(y, 'AI LAB — RUN COMPARISON', 'ai_benchmark')
        y += 42
        benchmark = getattr(self.tools, 'ai_benchmark_results', None)
