    class _GhostGameProbe:
        def __init__(self, settings, screen, seed=None, custom_map=None):
            self.settings, self.screen = settings, screen
            self.seed, self.custom_map = seed, custom_map
        def run(self):
            return None
    class _GhostBriefingProbe:
        choose_ghost = True
        def __init__(self, settings, screen, title_fn, entries, body_fn=None):
            self.entries, self.body_fn = entries, body_fn
        def _go_back(self):
            return None
        def run(self):
            selected = None
            if self.choose_ghost:
                selected = next((entry for entry in self.entries
                                 if entry[0] == 'race_custom_challenge_ghost'), None)
            if selected is None:
                selected = next(entry for entry in self.entries
                                if entry[0] == 'start_custom_challenge')
            selected[3]()
