    class _GraphTelemetryProbe:
        MAX_SECONDS = 60.0
        started_at = time.perf_counter() - 20.0
        metric_value_calls = 0
        def metric_values(self, metric):
            self.metric_value_calls += 1
            now = time.perf_counter() - self.started_at
            return [{'t': now - 1.0, metric: 55.0}, {'t': now, metric: 60.0}]
        def metric_summary(self, metric):
            return {'current': 60.0, 'average': 57.5, 'minimum': 55.0,
                    'maximum': 60.0, 'low_1': 55.0, 'low_0_1': 55.0}
