        _dv_top = _dv_panel._tabs()
        _dv_panel._draw_automation(_dv_top)
        assert DEV_CATEGORIES[16] == 'Automation' and 'autopilot' in DEV_CHEATS
        _dv_panel._handle_action('autopilot')
        assert DEV_TOOLS.cheats['autopilot']
        _dv_panel._handle_action('autopilot')
        _dv_level = DEV_TOOLS.autopilot_level
        _dv_panel._handle_action('ap_level')
        assert DEV_TOOLS.autopilot_level != _dv_level
        _dv_panel._handle_action('run_stress')
        _dv_started = time.monotonic()
