        assert len(_sd_controls['_data_arrows']) == len(_sd_all_categories)
        assert not {'tools', 'backups', 'bin'} & {row[1] for row in _sd_controls['_data_rows']}
        assert {'data_recalculate_button', 'data_cleanup_button'} <= set(_sd_controls)
        assert sum(seg[3] for seg in _sd_controls['_storage_segments']) == _sd_controls['_data_storage_summary']['size_bytes']
        assert 'tools' in [seg[1] for seg in _sd_controls['_storage_segments']]
        _sd_screen.data_expanded.add('tools')
        _sd_screen.draw_data_settings(800, 1500, 32, 520, 96, 48, _sd_controls)
        assert [hit[2]['name'] for hit in _sd_controls['_data_tree_hits']] == ['cloudflared']
        assert [path for _rect, path in _sd_controls['_data_tree_arrows']] == [_sd_cf]
        assert _sd_screen._handle_data_tree_arrow_click(_sd_controls, _sd_controls['_data_tree_arrows'][0][0].center)
        _sd_screen.draw_data_settings(800, 1500, 32, 520, 96, 48, _sd_controls)
        _sd_names = [hit[2]['name'] for hit in _sd_controls['_data_tree_hits']]
        assert _sd_names == ['cloudflared', 'cloudflared-2026.10.3.exe', 'cloudflared-2026.9.0.exe', 'release.json']
        # A line is highlighted and the cylinder shows its share of the group.
