        assert _sd_screen._handle_data_selection_click(_sd_controls, _sd_exe_hit[0].center)
        assert _sd_screen.storage_selected_path == _sd_exe_cur and _sd_screen.storage_selected_category == 'tools'
        assert _sd_screen.storage_selected_info == ('cloudflared-2026.10.3.exe', len(_sd_cur))
        _sd_screen.draw_data_settings(800, 1500, 32, 520, 96, 48, _sd_controls)
        assert any(seg[1] == 'tools' for seg in _sd_controls['_storage_segments'])
        _sd_row_hit = next(hit for hit in _sd_controls['_data_row_hits'] if hit[1] == 'saves')
        assert _sd_screen._handle_data_selection_click(_sd_controls, _sd_row_hit[0].center)
        assert (_sd_screen.storage_selected_row, _sd_screen.storage_selected_path,
                _sd_screen.storage_selected_category) == ('saves', None, 'saves')
        assert _sd_screen.storage_selected_info == (_sd_row_hit[2], _sd_row_hit[3])
        _sd_screen.draw_data_settings(800, 1500, 32, 520, 96, 48, _sd_controls)
        # Recalculate forgets the cached sizes and the selection that showed one.
