        assert all(os.path.exists(path) for path in (_sd_exe_old, _sd_part, _sd_q_old, *_sd_baks))
        _sd_expected = sum(group['size'] for group in _sd_plan.values())
        assert _sd_screen._execute_data_action(_sd_action) is False
