        _retry_click = pygame.event.Event(pygame.MOUSEBUTTONDOWN,
                                           button=1, pos=_retry_rect.center)
        assert _handle_replay_save_retry_event(_retry_owner, _retry_click)
        assert _flush_async_data_writes(timeout=5.0)
        _retry_status = _get_replay_save_status(_retry_job_id)
        assert _retry_status['phase'] == 'complete'
        with _replay_save_jobs_lock:
            assert _replay_save_jobs[_retry_job_id]['history'] == ()
