    _map_probe.redo()
    assert (2, 3) in _map_probe.obstacles
    _map_probe.erase((2, 3))
    assert (2, 3) not in _map_probe.obstacles
    _map_probe.undo()
    assert (2, 3) in _map_probe.obstacles
    _map_probe.place_portal((4, 5))
    _map_probe.undo()
    assert _map_probe.pending_portal is None
    _map_probe.redo()
    assert _map_probe.pending_portal == (4, 5)
    _map_probe.place_portal((7, 8))
    _map_probe.undo()
    assert _map_probe.pending_portal == (4, 5) and not _map_probe.portals
    _map_probe.redo()
    assert _map_probe.pending_portal is None and len(_map_probe.portals) == 1
    _map_probe.erase((4, 5))
    assert not _map_probe.portals
    _map_probe.undo()
    assert len(_map_probe.portals) == 1
